(window.GIM_TUR_P=window.GIM_TUR_P||{})["SOC.11"]={"from":671,"s":[["\u0010y0\u0011 צָרִיךְ לִזָּהֵר מְאֹד בְּהַדְלָקַת נֵרוֹת \u0010y1\u0011 חֲנֻכָּה, וַאֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה \u0010y2\u0011 שׁוֹאֵל אוֹ מוֹכֵר כְּסוּתוֹ וְלוֹקֵחַ שֶׁמֶן לְהַדְלִיק. \u0010c0\u0011\nכַּמָּה נֵרוֹת מַדְלִיק; בַּלַּיְלָה הָרִאשׁוֹן מַדְלִיק אֶחָד, \u0010y3\u0011 \u0010c1\u0011 מִכָּאן וָאֵילָךְ מוֹסִיף וְהוֹלֵךְ \u0010y4\u0011 אֶחָד בְּכָל \u0010y5\u0011 לַיְלָה עַד שֶׁבְּלֵיל \u0010y6\u0011 הָאַחֲרוֹן יִהְיוּ שְׁמוֹנָה, וַאֲפִלּוּ אִם רַבִּים בְּנֵי הַבַּיִת \u0010y7\u0011 לֹא יַדְלִיקוּ יוֹתֵר. \u0010c2\u0011 \u0005 הַגָּה: \u0010y8\u0011 וְיֵשׁ אוֹמְרִים דְּכָל אֶחָד מִבְּנֵי הַבַּיִת \u0010y9\u0011 יַדְלִיק \u0006 \u0005(רַמְבַּ\"ם)\u0006, \u0005 וְכֵן \u0006 \u0005 הַמִּנְהָג פָּשׁוּט; וְיִזָּהֲרוּ לִתֵּן כָּל אֶחָד וְאֶחָד נֵרוֹתָיו בְּמָקוֹם מְיֻחָד, כְּדֵי שֶׁיְּהֵא הֶכֵּר כַּמָּה נֵרוֹת מַדְלִיקִין \u0006 \u0005(מהר\"א מִפְּרַאג)\u0006. \u0010c3\u0011 \u0010c4\u0011 \u0010c5\u0011\nנֵר שֶׁיֵּשׁ לוֹ \u0010y10\u0011 שְׁתֵּי פִּיּוֹת \u0010y11\u0011 עוֹלֶה לוֹ בִּשְׁבִיל שְׁנַיִם.\nמִלֵּא קְעָרָה שֶׁמֶן וְהִקִּיפָהּ פְּתִילוֹת, \u0010y12\u0011 אִם כָּפָה עָלֶיהָ כְּלִי כָּל פְּתִילָה עוֹלָה בִּשְׁבִיל נֵר אֶחָד; לֹא כָּפָה עָלֶיהָ כְּלִי, אֲפִלּוּ לְנֵר אֶחָד אֵינוֹ עוֹלֶה \u0010y13\u0011 לְפִי שֶׁהוּא כִּמְדוּרָה. \u0005 הַגָּה: וְלָכֵן יֵשׁ לִזָּהֵר לְהַעֲמִיד הַנֵּרוֹת \u0010y14\u0011 בְּשׁוּרָה \u0006 \u0005 בְּשָׁוֶה, וְלֹא בְּעִגּוּל \u0010y15\u0011 דְּהָוֵי כִּמְדוּרָה \u0006 \u0005(הג\"מ בְּשֵׁם סְמַ\"ק)\u0006; \u0005 וּמֻתָּר לְהַדְלִיק \u0010y16\u0011 בְּפָּמוֹטוֹת שֶׁקּוֹרִין \u0006 \u0005 לַאמְפָּ\"א, \u0010y17\u0011 מֵאַחַר שֶׁכָּל נֵר מֻבְדָּל הַרְבֵּה מֵחֲבֵרוֹ \u0006 \u0005(ת\"ה סִימָן ק\"ה)\u0006. \u0005 וְיִזָּהֲרוּ כְּשֶׁעוֹשִׂים נֵרוֹת, אֲפִלּוּ בְּשַׁעֲוָה, \u0010y18\u0011 שֶׁאֵין לְדַבְּקָן בְּיַחַד וּלְהַדְלִיקָן, דְּהָוֵי כִּמְדוּרָה \u0006 \u0005(פִּסְקֵי מַהֲרִי\"וּ ס\"ה)\u0006; \u0010y19\u0011 \u0005 אֲפִלּוּ בְּנֵרוֹת שֶׁל שַׁבָּת וְיוֹם טוֹב יִזָּהֲרוּ שֶׁלֹּא לַעֲשׂוֹת כֵּן \u0006 \u0005(אוֹר זָרוּעַ)\u0006. \u0010c6\u0011 \u0010c7\u0011 \u0010c8\u0011\nנֵר חֲנֻכָּה מַנִּיחוֹ עַל פֶּתַח הַסָמוּךְ \u0010y20\u0011 לִרְשׁוּת הָרַבִּים מִבַּחוּץ. אִם הַבַּיִת פָּתוּחַ לִרְשׁוּת הָרַבִּים, מַנִּיחוֹ עַל פִּתְחוֹ; \u0010y21\u0011 וְאִם יֵשׁ חָצֵר לִפְנֵי הַבַּיִת, מַנִּיחוֹ עַל פֶּתַח הֶחָצֵר; \u0010c9\u0011 וְאִם הָיָה דָּר בַּעֲלִיָּה \u0010y22\u0011 שֶׁאֵין לוֹ פֶּתַח פָּתוּחַ לִרְשׁוּת הָרַבִּים, מַנִּיחוֹ בַּחַלּוֹן הַסָמוּךְ לִרְשׁוּת הָרַבִּים; וּבִשְׁעַת הַסַכָּנָה שֶׁאֵינוֹ רַשַּׁאי לְקַיֵּם הַמִּצְוָה, מַנִּיחוֹ עַל שֻׁלְחָנוֹ וְדַיּוֹ, \u0010y23\u0011 וְצָרִיךְ נֵר אַחֵר לְהִשְׁתַּמֵּשׁ \u0010c10\u0011 לְאוֹרוֹ; \u0010y24\u0011 וְאִם יֵשׁ מְדוּרָה אֵין צָרִיךְ נֵר אַחֵר; וְאִם הוּא אָדָם חָשׁוּב שֶׁאֵין דַּרְכּוֹ לְהִשְׁתַּמֵּשׁ לְאוֹר הַמְּדוּרָה, צָרִיךְ נֵר אַחֵר.\nמַנִּיחוֹ \u0010y25\u0011 לְמַעְלָה מִג' טְפָחִים, וּמִצְוָה לְהַנִּיחוֹ \u0010y26\u0011 לְמַטָּה מִי' טְפָחִים, וְאִם הִנִּיחוֹ לְמַעְלָה מִי' טְפָחִים, יָצָא, אֲבָל אִם מַנִּיחוֹ \u0010y27\u0011 לְמַעְלָה מִכ' אַמָּה \u0010y28\u0011 לֹא יָצָא. \u0005 הַגָּה: וַאֲפִלּוּ לְקָחָהּ כָּךְ דָּלוּק \u0010y29\u0011 וְהִנִּיחָהּ לְמַטָּה מִכ', לֹא יָצָא, דְּהַדְלָקָה עוֹשָׂה מִצְוָה \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם תּוֹסָפוֹת)\u0006.\nמִצְוָה לְהַנִּיחוֹ \u0010y30\u0011 בַּטֶּפַח הַסָמוּךְ \u0010y31\u0011 לַפֶּתַח מִשְּׂמֹאל, \u0010y32\u0011 כְּדֵי שֶׁתְּהֵא מְזוּזָה מִיָּמִין וְנֵר חֲנֻכָּה מִשְּׂמֹאל; \u0010y33\u0011 וְאִם אֵין מְזוּזָה בַּפֶּתַח, מַנִּיחוֹ מִיָּמִין; \u0010y34\u0011 וְאִם הִנִּיחוּ בַּדֶּלֶת עַצְמוֹ, יַנִּיחֶנּוּ \u0010y35\u0011 מֵחֶצְיוֹ שֶׁל כְּנִיסָה לְצַד שְׂמֹאל. \u0005 הַגָּה: וּמִיהוּ בַּזְּמַן הַזֶּה, שֶׁכֻּלָּנוּ מַדְלִיקִין בִּפְנִים וְאֵין הֶכֵּר לִבְנֵי רְשׁוּת הָרַבִּים כְּלָל, אֵין לָחוּשׁ כָּל כָּךְ אִם אֵין מַדְלִיקִין בַּטֶּפַח הַסָּמוּךְ לַפֶּתַח; \u0010y36\u0011 וּמִכָּל מָקוֹם הַמִּנְהָג לְהַדְלִיק בַּטֶּפַח הַסָּמוּךְ לַפֶּתַח כְּמוֹ בִּימֵיהֶם, \u0010y37\u0011 וְאֵין לְשַׁנּוֹת אֶלָּא אִם כֵּן רַבִּים בְּנֵי הַבַּיִת שֶׁעָדִיף יוֹתֵר לְהַדְלִיק כָּל אֶחָד בְּמָקוֹם מְיֻחָד מִלְּעָרֵב הַנֵּרוֹת בְּיַחַד וְאֵין הֶכֵּר כַּמָּה נֵרוֹת מַדְלִיקִין; וּמִכָּל מָקוֹם יִזָּהֵר שֶׁלֹּא לְהַדְלִיק בַּמָּקוֹם שֶׁמַּדְלִיקִין הַנֵּרוֹת כָּל הַשָּׁנָה, כִּי אָז לֹא יִהְיֶה הֶכֵּר כְּלָל; וְאַף כִּי אֵין הֶכֵּר רַק לִבְנֵי הַבַּיִת, מִכָּל מָקוֹם הֶכֵּר קְצָת מִיהָא בַּעְיָא. \u0010y38\u0011 \u0006 וּבְבֵית הַכְּנֶסֶת מַנִּיחוֹ \u0010y39\u0011 בְּכֹתֶל דָּרוֹם \u0005 אוֹ \u0010y40\u0011 בִּדְרוֹם הַמְּנוֹרָה, \u0010y41\u0011 וּמְסַדְּרָן מִמִּזְרָח \u0010y42\u0011 לְמַעֲרָב \u0006 \u0005(ת\"ה סי' ק\"ד \u0010y43\u0011 בֵּית יוֹסֵף)\u0006, וּמַדְלִיקִין וּמְבָרְכִין \u0005 בְּבֵית הַכְּנֶסֶת \u0006 מִשּׁוּם פִּרְסוּמֵי נִסָא. \u0005 הַגָּה: וְאֵין אָדָם יוֹצֵא בַּנֵּרוֹת שֶׁל בֵּית הַכְּנֶסֶת, \u0010y44\u0011 וְצָרִיךְ לַחֲזֹר וּלְהַדְלִיק בְּבֵיתוֹ \u0006 \u0005(ריב\"ש סִימָן קי\"א)\u0006; \u0010y45\u0011 \u0005 וְנוֹהֲגִין לְהַדְלִיק בְּבֵית הַכְּנֶסֶת בֵּין מִנְחָה לְמַעֲרִיב; וְיֵשׁ נוֹהֲגִין לְהַדְלִיק \u0010y46\u0011 בְּעֶרֶב שַׁבָּת \u0006 \u0005 קֹדֶם מִנְחָה \u0006 \u0005(כָּל בּוֹ וְאַבּוּדַרְהַם)\u0006; \u0010y47\u0011 \u0005 אִם רוֹצִים לְמַהֵר לְהִתְפַּלֵּל לְאַחַר שֶׁבֵּרַךְ הַשְּׁלִיחַ צִבּוּר וְהִדְלִיק אֶחָד מֵהֶן, \u0010y48\u0011 יוּכַל \u0006 \u0005 הַשַּׁמָּשׁ לְהַדְלִיק הַנִּשְׁאָרִים, וְהַשְּׁלִיחַ צִבּוּר יִתְפַּלֵּל \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0010y49\u0011 \u0010c11\u0011 \u0010c12\u0011 \u0010c13\u0011\nחָצֵר שֶׁיֵּשׁ לוֹ שְׁנֵי פְּתָחִים \u0010c14\u0011 מִשְּׁנֵי רוּחוֹת, צָרִיךְ לְהַדְלִיק בִּשְׁתֵּיהֶן \u0010y50\u0011 מִפְּנֵי הַחֲשָׁד; וְאִם שְׁנֵי הַפְּתָחִים \u0010y51\u0011 בְּרוּחַ אֶחָד \u0010y52\u0011 \u0005 וְהֵם בְּבַיִת אֶחָד \u0006 \u0005(כָּל בּוֹ)\u0006 דַּי לוֹ בְּאֶחָד מֵהֶם. \u0005 הַגָּה: וְאִם מַדְלִיק בִּשְׁנֵי פְּתָחִים אֵינוֹ מְבָרֵךְ רַק בְּאֶחָד מֵהֶם וּבַשֵּׁנִי מַדְלִיק בְּלֹא בְּרָכָה, \u0006 \u0005(ר\"ן)\u0006 \u0005 מִיהוּ בַּזְּמַן הַזֶּה שֶׁכֻּלָּם מַדְלִיקִין \u0010y53\u0011 בִּפְנִים מַמָּשׁ, וְאֵין הֶכֵּר לִבְנֵי רְשׁוּת הָרַבִּים כְּלָל, אֲפִלּוּ יֵשׁ לֶחָצֵר אוֹ לַבַּיִת הַרְבֵּה פְּתָחִים לְאַרְבַּע רוּחוֹת אֵין מַדְלִיקִים אֶלָּא פַּעַם אַחַת בִּפְנִים, כֵּן נ\"ל וְכֵן הַמִּנְהָג פָּשׁוּט. \u0006",["\u0003צריך ליזהר וכו'\u0004 ואמרינן בגמרא הרגיל בנר הויין לו בנים ת\"ח שנאמר כי נר מצוה ותורה אור ופירש\"י ע\"ז נר מצוה דשבת וחנוכה:","\u0003ואפילו עני וכו'\u0004 משום פרסומי ניסא:","\u0003שואל\u0004 על הפתחים או מוכר כסותו או משכיר עצמו אבל אינו מחוייב בכל זה רק בשביל נר אחד בכל לילה:","\u0003מכאן ואילך וכו'\u0004 ואם אין ידו משגת רק לנר אחד בכל לילה לו ולביתו יצא בזה מדינא ושיעורא דשו\"ע הוא רק למי שידו משגת להיות מהדר מן המהדרין כדאיתא בגמרא:","\u0003אחד בכל לילה\u0004 ואם יש לו ט' נרות ידליק בליל שני שתי נרות ואם יש לו י' נרות אעפ\"כ לא ידליק רק בליל ב' ב' ובליל ג' לא ידליק שתים רק אחת [ח\"א]:","\u0003עד שבליל אחרון וכו'\u0004 ומי שאין לו שמן הרבה יתן באחד שמן כשיעור והמותר יחלק לכולם שאם יעשה לכולם בשוה לא ידליק אפילו אחד כשיעור. ואם יש לו שמן בצמצום על כל השמנה ימים ולחבירו אין לו כלום מוטב שידליק בכל לילה אחד ויתן גם לחבירו דהא מדינא א\"צ אלא אחד כנ\"ל ודוקא כשחבירו אינו מב\"ב או שאינו סמוך על שולחנו אבל אם הוא מב\"ב מוטב שיהיה הוא מהמהדרין:","\u0003יהיו שמנה\u0004 ואם השמן הוא ביוקר מוטב להדליק בנרות שעוה ולהיות מוסיף והולך כמו שכתוב בפנים ממה שידליק בשמן זית נר א' בכל לילה לבד:","\u0003לא ידליקו יותר\u0004 בין בלילה ראשונה ובין בשארי לילות דהכל נגררים אצל בעה\"ב אפילו בניו הגדולים ומשרתיו כיון שהם סמוכים על שולחנו בקביעות הם בכלל בני ביתו:","\u0003וי\"א דכל אחד וכו'\u0004 לבד מאשתו דהיא כגופו:","\u0003ידליק\u0004 היינו כמו שכתוב לעיל בס\"ב דיוסיף והולך נר א' בכל לילה ואם אין ידם משגת כ\"כ ידליקו נר אחד בכל לילה:","\u0003שתי פיות\u0004 היינו שהפתילות מבפנים מונחים בנר זה אצל זה רק ראשי הפתילות כשבולטין לחוץ נחלקין לשתי מקומות וקמ\"ל דאע\"פ שמבפנים אינן מובדלין הפתילות כלל זה מזה מ\"מ כיון שבמקום הנחתן בפה מינכר שהם שתים נחשבות כשתים:","\u0003עולה לו בשביל שנים\u0004 משמע מלשון זה דאפילו למהדרין העושין נר לכל אחד ג\"כ יועיל זה לשני בני אדם ועיין במ\"א שדעתו דלפי מאי דאיתא לעיל בהג\"ה דלדידן דמוסיפין בכל לילה נר אחד לכל אחד מן הבית צריך כ\"א להדליק נרותיו במקום מיוחד לא ידליקו שני אנשים בנר אחד ואפילו בלילה הראשונה יש ליזהר בזה. ואפשר דוקא נר אחד שיש לו רק שני פיות אבל במנורת שלנו שיש להן ח' פיות מותר להדליק שני בני אדם זה בקצה זה וזה בקצה זה שהרי רואין שהדליקו שנים דאל\"כ היה מדליק כסדר אחד אצל חבירו [ח\"א] וכן נוהגין העולם:","\u0003אם כפה וכו'\u0004 שעי\"ז אין מתחברים כל הפתילות יחד ודוקא כשכפה ואח\"כ הדליק אבל אם הדליק ואח\"כ כפה צריך לכבות ולכסות בכלי ולחזור ולהדליק:","\u0003לפי שהוא כמדורה\u0004 שמתחברות כל הלהב יחד:","\u0003בשורה בשוה\u0004 היינו שלעשות אחד נכנס ואחד יוצא ג\"כ אינו כדאי שלא יבוא לעשות בעיגול:","\u0003דהוי כמדורה\u0004 ואם יש הפסק מחיצה בין נר לנר וכרחב אצבע ביניהן מותר ואפילו לא כפה עליה כלי וכן נוהגין דדוקא בקערה שאין שום הפסק בין נר לנר [ח\"א]:","\u0003בפמוטות\u0004 של נחושת העשויין קנים קנים יוצאין סביבות בעיגול שהקנים חלולין ומחיצת כל קנה מפסיק בינו לבין חבירו:","\u0003מאחר שכל נר מובדל הרבה וכו'\u0004 משמע מלשון זה דתרתי בעינן דהיינו שיהיו ג\"כ מובדלים הקנים אחד מחבירו לבד מה שיש לכל קנה מחיצה בפני עצמה ועיין בא\"ר שכתב דדי ברחב אצבע. וה\"ה כשמדבקין נרות שעוה בכותל יראה שיהיו מרווח אחד מחבירו עכ\"פ כשיעור אצבע:","\u0003שאין לדבקן ביחד ולהדליקן\u0004 אפילו להדביק שנים ביחד אסור וכ\"ש ד' או ה' דודאי נראה כמדורה:","\u0003אפילו בנרות של שבת ויו\"ט וכו'\u0004 עיין בבה\"ל:","\u0003מבחוץ\u0004 משום פרסומי ניסא וקמפרש ואזיל כיצד אם הבית וכו':","\u0003ואם יש חצר לפני הבית וכו'\u0004 וחצרותיהן היו פתוחות לר\"ה:","\u0003שאין לו פתח פתוח לר\"ה\u0004 וגם אין לו פתח פתוח לחצר אלא פתוחה היא לבית:","\u0003וצריך נר אחר\u0004 לעשות היכר לדבר:","\u0003ואם יש מדורה\u0004 ויכול להשתמש לפניה ויש הכירה שהנר של מצוה היא:","\u0003למעלה מג\"ט\u0004 דכל למטה מג' כאלו הניח בקרקע ואין ניכר שבעה\"ב הניחו שם ומ\"מ בדיעבד יצא [פר\"ח]:","\u0003למטה מי\"ט\u0004 דאיכא פרסום הנס טפי כשהוא למטה דדבר העשוי לאור אין דרך להניחה כ\"כ למטה ועיין בא\"ר שכתב דהא דאין העולם נזהרין בזה משום דסומכין על המרדכי שכתב דעכשיו שהורגלו להניח בפנים אין קפידא בזה אכן הטור סתם בזה ומשמע דס\"ל דאין לחלק בזה וכן נוהגין כל המדקדקים כמ\"ש בב\"י. ואם דר בעליה מניחה בחלון שהוא לצד ר\"ה אפילו אם החלון גבוה יותר מי\"ט מקרקעית העליה. ואם יש לו שתי חלונות אחד למעלה מי\"ט ואחד למטה מי\"ט ודאי יניחנה בחלון שהיא למטה מי\"ט. ובנרות בהכ\"נ המנהג שהמנורה במקום גבוה:","\u0003למעלה מכ' אמה וכו'\u0004 דלא שלטא ביה עינא ואין נ\"מ בין אם מדליק מבחוץ ובין אם מדליק בבית:","\u0003לא יצא\u0004 וצריך לחזור ולברך כ\"כ הפר\"ח ועיין בפמ\"ג מש\"כ בזה:","\u0003והניחה למטה מכ\"ף וכו'\u0004 אבל אם הדליקה למטה מכ' ונטלה משם והניחה במקום אחר תוך כ' יוצא דהא הוי הדלקה במקומה דשני המקומות כשרים:","\u0003בטפח הסמוך וכו'\u0004 שאם ירחיקנה להלן מן הפתח אינו ניכר שבעה\"ב הניחו שם:","\u0003לפתח\u0004 בין אם ההנחה הוא על פתח הבית או על פתח החצר:","\u0003כדי שתהא וכו'\u0004 ויהיה מסובב במצות מיהו בדיעבד אם הניח נר חנוכה מימין יצא:","\u0003ואם אין וכו' מימין\u0004 דכל מידי דמצוה ימין עדיף ועוד דאיכא פרסומי ניסא טפי שהכל פונין לצד ימין:","\u0003ואם הניחו בדלת עצמו וכו'\u0004 קאי אריש הסעיף:","\u0003מחציו של כניסה וכו'\u0004 היינו מקום הדלת שנכנס משם לתוך הבית יחלקנו לשנים ובחצי הנוטה לצד שמאל [שהוא נגד המזוזה שהמזוזה בימין] שם יניחנו [מ\"א] ומשמע מזה דיכול להניח בכל שטח אותו החצי ועיין בט\"ז שדעתו דלמעשה ראוי להחמיר להניח הנרות בצד השמאל בקצה האחרון סמוך לכותל:","\u0003ומ\"מ המנהג וכו'\u0004 כדי שיכנס בין שתי מצות:","\u0003ואין לשנות\u0004 ומ\"מ אם יש לו חלון הסמוך לר\"ה נכון יותר שיניחנו שם כדי שיהיה היכר לבני ר\"ה ויתפרסם הנס אם לא במקום דשכיחא הזיקא עי\"ז:","\u0003ובבית הכנסת\u0004 או בבית המדרש:","\u0003בכותל דרום\u0004 או על השולחן שעומד אצל כותל דרום והטעם בכ\"ז זכר למנורה שמקומה במקדש בדרום:","\u0003כנרות המנורה\u0004 או בדרום המנורה: ט\"ס וצ\"ל כנרות המנורה:","\u0003ומסדרן ממזרח וכו'\u0004 זהו ג\"כ כעין מנורה דהנרות היו מסודרין במקדש בין מזרח למערב כן יסדר ג\"כ נרות חנוכה. ודע דיש מהראשונים דס\"ל דאף דהמנורה היתה עומדת בדרום מ\"מ נרותיה היו מסודרין מצפון לדרום וממילא לדידהו גם נרות חנוכה יש לסדר באופן הזה ויש מקומות שנהגו כן ואין למחות בם דיש להם על מה לסמוך:","\u0003למערב\u0004 והמדליק עומד אחוריו לדרום ופניו לצפון ומתחיל מימינו שהוא הנר הסמוך לארון הקודש ושוב מוסיף והולך ומתחיל מהשמאלי ופונה לימינו [תשו' ח\"ס סי' קפ\"ו] ועיין לקמן בס\"ס תרע\"ו מה שנכתוב בזה:","\u0003ומדליקין ומברכין\u0004 אף דבבהכ\"נ הוא רק מנהגא מ\"מ מברכין עליו כמו שמברכין על הלל דר\"ח שאינו אלא מנהג. אם אבל מתפלל בערב חנוכה מדליק אדם אחר הנרות משום שהחיינו דמברכין אז ומינכר דעת שמחה היא לצבור ואין כדאי שאבל ידליקם [אבל בביתו יכול לברך שהחיינו] אבל שאר ערבית דחנוכה דאין מברכין שהחיינו יכול האבל להדליק נר חנוכה. ומתפלל האבל בחנוכה מנחה ומעריב. ובט\"ו באב ושבט ול\"ג בעומר דלית הלל האבל מתפלל שחרית ג\"כ. ובחוה\"מ דהוי כיו\"ט מנעתי לפעמים להניח האבל להתפלל מנחה ומעריב [פמ\"ג]:","\u0003וצריך לחזור ולהדליק\u0004 ואפילו הש\"ץ שבירך בביהכ\"נ צריך לחזור ולהדליק בביתו דיש חיוב על כל אחד להדליק בביתו ומ\"מ לא יחזיר לומר בביתו ברכת שהחיינו אם לא שמדליק להוציא אשתו וב\"ב:","\u0003להדליק בבית הכנסת בין מנחה למעריב\u0004 ר\"ל אפילו הנוהגים להדליק בכל יום בצה\"כ בבהכ\"נ נוהגים אחר מנחה בשעה שהעולם מקובצים וגם דלאחר מעריב אין נכון לעכב העולם לזה דצריך כ\"א למהר לילך לביתו ולהדליק נ\"ח:","\u0003קודם מנחה\u0004 וכ\"כ רש\"ל אבל בד\"מ כתב שאין אנו נוהגין כן אלא אף בערב שבת מדליקין בבהכ\"נ בין מנחה למעריב בשעה שהעולם מתחילין להתקבץ ואיכא פרסומי ניסא אכן אם העולם מתאחרין לבוא וטרם שיבוא מנין לביהכ\"נ יתקדש היום לא ימתין כלל אלא יברך וידליק מיד אפילו קודם מנחה דמ\"מ איכא פרסומי ניסא כשבאים אח\"כ לביהכ\"נ ורואים הנרות ולענין יחיד עיין לקמן בסוף סימן תרע\"ט במ\"ב:","\u0003אם רוצה למהר וכו'\u0004 ודוקא באופן זה אבל בלא\"ה טוב יותר שיגמור בעצמו המצוה שהתחיל בה:","\u0003יוכל השמש וכו'\u0004 דהברכה חל על האחד שהדליק דהיא העיקר והשאר אינן אלא הידור מצוה בעלמא וה\"ה בביתו כשמזדמן לו איזה דבר נחוץ לאחר שהדליק אחד מהן יוכל אחר להשלים בשבילו את שארי הנרות:","\u0003חצר שיש לו שני פתחים\u0004 וה\"ה בית:","\u0003מפני החשד\u0004 שיאמרו בני עירו מדלא אדליק בהא באחרת נמי לא אדליק וע\"כ אפילו כל הבתים שבחצר שייך לאדם אחד או שאין לו שם בחצר רק בית אחד צריך להדליק בשתי הפתחים:","\u0003ברוח אחד וכו'\u0004 הטעם דהא חזי ליה שהדליק באחד ומה שלא הדליק בשני ידעו אנשי עירו שמבפנים הוא בית אחד ושני הפתחים שייכים לאדם אחד ודי להדליק במקום אחד:","\u0003והם בבית אחד\u0004 אבל אם הם בשני בתים או שבית אחד חלוק מתוכו אע\"פ שהם של אדם אחד צריך להדליק בשתיהן משום חשד שיחשדו ששני בני אדם דרין שם ויש מקילין בששתיהן שייכין לאדם אחד:","\u0003בפנים ממש\u0004 היינו שבזמן הטור היו מדליקין אצל פתח הבית מבפנים והיו עושין עכ\"פ היכר לעוברים ע\"כ יש חשד כל שאין היכר כראוי לעוברים משא\"כ עכשיו שמדליקין ממש בפנים ולא איכפת לן כלל לעשות היכר לבני ר\"ה ע\"כ לא איכפת לן בחשדא דידהו:"],["\u0003 ואפילו עני וכו'\u0004 - הרה\"מ כתב דהרמב\"ם למד כן מדין ד' כוסות דזה וזה הוי משום פרסומי ניסא ולפ\"ז נראה דהגבאים מחוייבים ליתן לו נרות להדליק כמו בד' כוסות מיהו אם לא נתנו לו צריך לעשות כמו שכתוב בשו\"ע וכן הדין בד' כוסות מיהו נראה דאין צריכין ליתן לו כ\"א נר אחד בכל לילה דהיינו נר איש וביתו דיותר הוי מן המהדרין ואין חיוב ליתן לו [חמד משה].","\u0003 בלילה הראשון מדליק אחד וכו'\u0004 - אמרינן בגמרא דמצות חנוכה נר איש וביתו [ר\"ל דדי נר אחד לכל ב\"ב בכל לילה ולילה] והמהדרין מדליקין נר לכל אחד ואחד והמהדרין מן המהדרין יום ראשון מדליק אחד מכאן ואילך מוסיף והולך אחד בכל לילה עד שבליל אחרון יהיו שמנה והטעם כנגד ימים היוצאים וזה היום שעומד בו נמנה עם הימים שיצאו כבר [והיינו שבזה ידעו ויזכרו הכל כמה ימים יצא בהתמדת הנס וכשיזכירו זה שהיה הנס משך זמן רב יש בו פרסומי ניסא ושבח יותר להש\"י] ועוד שמעלין בקודש [גמרא].","\u0003 לא ידליקו יותר\u0004 - עיין מ\"ב והטעם דלפ\"ז כשרואין בבית בליל שני שדולקין שתי נרות ירגישו בתוספות הנר אבל לדעה השניה שמדליקין בלילה הראשונה נר לכל אחד מבני הבית אז אם ידליקו בלילה השניה שנים לכל אחד אין כאן הכרה לתוספות הנס כי יאמרו שיש הרבה בני בית ולכל אחד אין שם רק נר אחת והיינו כשכל הנרות דולקים במקום אחד זה אצל זה.","\u0003 וי\"א דכ\"א מבני הבית וכו'\u0004 - עיין בביאור הגר\"א שכתב דגם דעת הרי\"ף כן הוא מדהביא המימרא דרבה בב\"ח אמר ר\"י וכו'. ולולי דברי קדשו היה אפשר לומר עוד דדעת הרי\"ף דזה לא נכנס בכלל מה דקי\"ל בעלמא דהלכה כב\"ה בדינא אחרי דאינם מחולקים בענין הלכה אלא בענין הידור בעלמא ולזה הביא מה שאמר ר' יוחנן על שני זקנים ומשמע לכאורה דהיו בימיו שכבר נפסק בעלמא דהלכה כב\"ה ואפ\"ה זקן אחד עשה כב\"ש. אכן מדלא הוזכר ד\"ז בשום פוסק אין לצרף ד\"ז להלכה כלל ולא כתבתי רק לעורר לב המעיינים.","\u0003 ויזהרו ליתן וכו'\u0004 - דבאופן זה גם התוספות מודו שיכולין להדליק יותר [הגר\"א בשם ד\"מ].","\u0003 כדי שיהא היכר וכו'\u0004 - היינו בעת שניתוסף הנרות כן מוכח מא\"ר בס\"ג ודעת המגן אברהם בסק\"ב דאפילו בלילה הראשונה יש ליזהר בזה משום לא פלוג כמו שכתב שם הפמ\"ג.","\u0003 מילא קערה שמן והקיפה פתילות\u0004 - וה\"ה כשהקיף נרות בעיגול עד שעי\"ז יוכל להתחבר הלהב ג\"כ דינא הכי.","\u0003 ומותר להדליק בפמוטות\u0004 - עיין מ\"ב וכתבו האחרונים בשם רש\"ל דאף דמן הדין מותר מ\"מ אין זה הידור לנר חנוכה.","\u0003 אפילו בנרות של שבת וכו'\u0004 - מלשון זה משמע דאף בשבת ויו\"ט יש ליזהר שלא לעשות כן ואינו כן דבשבת ויו\"ט מצוה לעשות כרוכים כדלעיל בסימן רס\"ג וכבר הקשה כן במגן אברהם ועיין בסוף דבריו דלפי מאי דמסיק בשם רש\"ל דאסור בענינינו אפילו בשתי נרות כרוכין ממילא אין שום ביאור לדברי רמ\"א במה שמסיק דאפילו בנרות של שבת ויו\"ט יש ליזהר ועיין בפמ\"ג שגם הוא נדחק מאוד בדברי רמ\"א ולענ\"ד נראה דחסר כאן פרט אחד הנזכר באור זרוע דהיינו כשמדבקין אותן אחר הדלקתן עד שעי\"ז מתחממות ונופלות וזה באמת אסור בין בחנוכה ובין בשוי\"ט וז\"ל ד\"מ כשמדליקין נר שבת או חנוכה או יו\"ט ודובקין הנרות סמוכין זה לזה עד שהן מתחממות זו מזו ונוטף השעוה גם נכפלות ונופלות לא קיימו המצוה אור זרוע עכ\"ל ולאות שהאמת כדברי שציין ברמ\"א אור זרוע והלא דין הראשון לא נזכר כלל באור זרוע אלא דין זה.","\u0003 פתח החצר\u0004 - ר\"ל ושלא כדעת רש\"י דסובר דמניחו על פתח הבית הפתוח לחצר. ובר\"ן ובאור זרוע העתיקו כרש\"י.","\u0003 וצריך נר אחר להשתמש לאורה\u0004 - פי' רש\"י משום הכירא ור\"ל שאפילו אם לא ירצה כלל להשתמש לאורה מ\"מ צריך נר אחר שיהיה היכולת בידו להשתמש לאורה ועי\"ז מינכר שהנר הראשון הוא לשם מצוה דאל\"ה כיון שעומד על השולחן יאמרו שלצרכו הדליקה. ונראה דוקא במניחה על שולחנו אבל כל שמניחה סמוך לפתח א\"צ לנר אחרת אע\"פ שעומד לו לשם הואיל ואינו בא להשתמש לאורה לאיזה תשמיש. אכן מנהג העולם וכן מנהג רבותינו דבכל נר חנוכה המודלקת בתוך הבית צריך נר אחרת אפילו לא היה צריך לתשמיש שלא יאמרו לצרכו הדליקה וכן אני נוהג למעשה כ\"כ המאירי עי\"ש ועיין בפמ\"ג שכן משמע ג\"כ מתשובת רמ\"א. ועיין בסוף סימן תרע\"ח סק\"ג במגן אברהם דאפילו מי שאין לו אלא נר אחד [ונר אחרת להדליק לשמש לאורה אין לו] מ\"מ ידליק את הנר ויברך עליה. ומ\"מ לכתחלה בודאי יזהר שלא להשתמש לפניה.","\u0003 ומ\"מ המנהג להדליק בטפח וכו'\u0004 - ר\"ל המנהג הנכון להתנהג כך דאל\"ה סותר ד\"ע.","\u0003 ובבית הכנסת מניחו בכותל דרום\u0004 - זהו אפילו לזמן הגמרא שהיו מדליקין בחוץ על פתח הבית הכא מדליקין בפנים דהוא לפרסם הנס ברבים. והנה המחבר היה צריך לבאר בתחלה שצריך להדליק בביהכ\"נ ואח\"כ מקום הנחתו אלא לפי שקאמר לעיל בתחלת הסעיף דמצוה להניחו בטפח הסמוך להפתח קאמר דבבהכ\"נ עושין זכר למקדש שהמנורה עמדה בדרום.","\u0003 ויש נוהגין להדליק בע\"ש קודם מנחה\u0004 - עיין מ\"ב במה שכתבנו בשם הד\"מ דהמנהג וכו' אכן אם העולם וכו' דמ\"מ איכא פרסומי ניסא כשבאין אח\"כ לביהכ\"נ כ\"ז כתב המגן אברהם והנה במור וקציעה והובא בשע\"ת חולק ע\"ז ודעתו דכיון שמה שמדליקין בבהכ\"נ הוא כדי לפרסם הנס במקהלות בעינן דוקא שיהיו עשרה בשעת הדלקה דכוותה אשכחן נמי בכל פרסומי מילתא בעלמא דלא סגי בלאו עשרה כדאשכחן בפ\"ק דכתובות וכדאשכחן דא\"ל שמואל לר\"י זיל אייתי לי בי עשרה ואימא באנפייהו המזכה לעובר וכו' וע\"כ דעתו דצריך קהל ממש ואין עדה פחותה מעשרה והנה היחידים יוצאין לעצמן כ\"א בביתו ולא נתקנו הנרות לשנותן בבהכ\"נ אלא בצבור בלבד אמנם אם השעה דחוקה אין לבטל ההדלקה אלא ידליק בלא ברכה ונראה שגם מה שהביא המגן אברהם בשם מהרי\"ל הכי הוה עובדא ולא נזכר שם שבירך ג\"כ עכ\"ל ולענ\"ד פרסומי ניסא דחנוכה אינו תלוי כ\"כ בזה דעצם הדלקה הוא בכלל פרסום הנס ודומיא דמאי דאמרינן בגמרא נר חנוכה וקידוש היום נר חנוכה עדיף משום פרסומי ניסא ולא אשכחן חד דאמר דוקא כשיש בי עשרה בשעת הדלקה א\"ו דעצם הדלקה שציוו חכמים על כלל ישראל הוא נקרא פרסום הנס ונהי דהדלקה זו של ביהכ\"נ הוא אינו מצד תק\"ח רק ההנהגה שהנהיגו כל ישראל כדי לפרסם הנס ברבים כמו שכתבו הפוסקים הרי עי\"ז ג\"כ יתפרסם הנס כשיבואו אח\"כ כל הקהל בביהכ\"נ ויראו נרות המנורה דלוקין כמו שכתב המגן אברהם וכעין ראיה לסברא זו ממאי דאיתא באבודרהם טעם על מה שאמרו בגמרא הרואה נר חנוכה צריך לברך ולא תקנו בשאר מצות ברכה על הראיה ותירץ שם בראשונה משום פרסומי ניסא וכעין זה כתבו ג\"כ התוספות בסוכה דף מ\"ו ד\"ה הרואה משום שיש כמה בני אדם שאין להם בית ואין בידם לקיים המצות הרי דאף שלא היה האיש הזה בשעת הדלקה רק ראה אותה אח\"כ מקרי פרסום הנס וה\"נ בענינינו כשבאין אח\"כ כל הקהל ורואין הנרות דלוקין במנורה אין לך פרסום הנס גדול מזה. וגם במהרי\"ל איתא בהדיא שהדליק שמש העיר בע\"ש טרם בוא הקהל לביהכ\"נ וכן מאבודרהם ומכל בו ומהרש\"ל שכולם דעתם שידליקו קודם מנחה ולא אישתמיט אחד מהם לומר דוקא כשנתקבץ שם עדה ומה שכתב המו\"ק דאפשר שהדליק השמש בלא ברכה זהו דוחק דא\"כ הי\"ל לפרש דבאופן זה דוקא בלי ברכה וע\"כ נלענ\"ד דהמדליק בברכה יש לו על מי לסמוך וכן העתיק הח\"א דצריך להדליק בברכה. ואם בנקל לו להשיג מנין בשעת ברכה מה טוב.","\u0003 שיש לו שני פתחים משני רוחות\u0004 - היינו אחת בצפון ואחת במזרח כ\"כ רש\"י וטעות נזדקר לפני פתחי עולם שכתב בשם רש\"י א' בצפון ואחד בדרום עי\"ש."],"\u0010y0\u0011 \u0010g0\u0011 צָרִיךְ לִזָּהֵר מְאֹד בְּהַדְלָקַת נֵרוֹת \u0010y1\u0011 \u0010t0\u0011 חֲנֻכָּה, וַאֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה \u0010y2\u0011 שׁוֹאֵל אוֹ מוֹכֵר כְּסוּתוֹ וְלוֹקֵחַ שֶׁמֶן לְהַדְלִיק. \u0010c0\u0011 \u0010g1\u0011 \u0010r0\u0011 \u0010r1\u0011\nכַּמָּה נֵרוֹת מַדְלִיק; בַּלַּיְלָה הָרִאשׁוֹן מַדְלִיק אֶחָד, \u0010y3\u0011 \u0010c1\u0011 מִכָּאן וָאֵילָךְ \u0010t1\u0011 \u0010s0\u0011 \u0010m0\u0011 מוֹסִיף וְהוֹלֵךְ \u0010y4\u0011 אֶחָד בְּכָל \u0010y5\u0011 לַיְלָה עַד שֶׁבְּלֵיל \u0010y6\u0011 הָאַחֲרוֹן יִהְיוּ \u0010g2\u0011 שְׁמוֹנָה, וַאֲפִלּוּ אִם רַבִּים בְּנֵי הַבַּיִת \u0010y7\u0011 לֹא יַדְלִיקוּ יוֹתֵר. \u0010c2\u0011 \u0005 הַגָּה: \u0010y8\u0011 וְיֵשׁ אוֹמְרִים דְּכָל אֶחָד מִבְּנֵי הַבַּיִת \u0010y9\u0011 יַדְלִיק \u0010g3\u0011 \u0006 \u0005(רַמְבַּ\"ם)\u0006, \u0005 וְכֵן \u0010t2\u0011 \u0010s1\u0011 \u0006 \u0005 הַמִּנְהָג פָּשׁוּט; וְיִזָּהֲרוּ לִתֵּן כָּל אֶחָד וְאֶחָד נֵרוֹתָיו בְּמָקוֹם מְיֻחָד, כְּדֵי שֶׁיְּהֵא הֶכֵּר כַּמָּה נֵרוֹת מַדְלִיקִין \u0006 \u0005(מהר\"א מִפְּרַאג)\u0006. \u0010c3\u0011 \u0010c4\u0011 \u0010c5\u0011 \u0010g4\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011\nנֵר שֶׁיֵּשׁ לוֹ \u0010y10\u0011 שְׁתֵּי פִּיּוֹת \u0010y11\u0011 עוֹלֶה לוֹ \u0010m1\u0011 בִּשְׁבִיל \u0010t3\u0011 שְׁנַיִם. \u0010g5\u0011 \u0010r5\u0011\nמִלֵּא קְעָרָה שֶׁמֶן וְהִקִּיפָהּ פְּתִילוֹת, \u0010y12\u0011 אִם \u0010t4\u0011 כָּפָה עָלֶיהָ כְּלִי כָּל פְּתִילָה עוֹלָה בִּשְׁבִיל נֵר אֶחָד; לֹא כָּפָה עָלֶיהָ כְּלִי, אֲפִלּוּ לְנֵר אֶחָד אֵינוֹ עוֹלֶה \u0010y13\u0011 לְפִי שֶׁהוּא כִּמְדוּרָה. \u0005 הַגָּה: וְלָכֵן יֵשׁ לִזָּהֵר לְהַעֲמִיד הַנֵּרוֹת \u0010y14\u0011 \u0010m2\u0011 בְּשׁוּרָה \u0010t5\u0011 \u0006 \u0005 בְּשָׁוֶה, וְלֹא בְּעִגּוּל \u0010y15\u0011 דְּהָוֵי כִּמְדוּרָה \u0006 \u0005(הג\"מ בְּשֵׁם סְמַ\"ק)\u0006; \u0005 וּמֻתָּר לְהַדְלִיק \u0010y16\u0011 בְּפָּמוֹטוֹת שֶׁקּוֹרִין \u0010t6\u0011 \u0006 \u0005 לַאמְפָּ\"א, \u0010y17\u0011 מֵאַחַר שֶׁכָּל נֵר מֻבְדָּל הַרְבֵּה מֵחֲבֵרוֹ \u0006 \u0005(ת\"ה סִימָן ק\"ה)\u0006. \u0005 וְיִזָּהֲרוּ כְּשֶׁעוֹשִׂים נֵרוֹת, אֲפִלּוּ בְּשַׁעֲוָה, \u0010y18\u0011 \u0010m3\u0011 שֶׁאֵין לְדַבְּקָן בְּיַחַד וּלְהַדְלִיקָן, דְּהָוֵי כִּמְדוּרָה \u0006 \u0005(פִּסְקֵי מַהֲרִי\"וּ ס\"ה)\u0006; \u0010y19\u0011 \u0005 אֲפִלּוּ בְּנֵרוֹת שֶׁל שַׁבָּת וְיוֹם טוֹב יִזָּהֲרוּ שֶׁלֹּא לַעֲשׂוֹת כֵּן \u0006 \u0005(אוֹר זָרוּעַ)\u0006. \u0010c6\u0011 \u0010c7\u0011 \u0010c8\u0011 \u0010g6\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011\nנֵר חֲנֻכָּה מַנִּיחוֹ עַל פֶּתַח הַסָמוּךְ \u0010y20\u0011 לִרְשׁוּת הָרַבִּים מִבַּחוּץ. אִם הַבַּיִת פָּתוּחַ לִרְשׁוּת הָרַבִּים, מַנִּיחוֹ עַל פִּתְחוֹ; \u0010y21\u0011 וְאִם יֵשׁ חָצֵר לִפְנֵי הַבַּיִת, מַנִּיחוֹ עַל פֶּתַח הֶחָצֵר; \u0010c9\u0011 \u0010g7\u0011 וְאִם הָיָה דָּר בַּעֲלִיָּה \u0010y22\u0011 שֶׁאֵין לוֹ פֶּתַח פָּתוּחַ לִרְשׁוּת הָרַבִּים, מַנִּיחוֹ בַּחַלּוֹן הַסָמוּךְ לִרְשׁוּת הָרַבִּים; וּבִשְׁעַת הַסַכָּנָה שֶׁאֵינוֹ רַשַּׁאי לְקַיֵּם הַמִּצְוָה, מַנִּיחוֹ עַל שֻׁלְחָנוֹ וְדַיּוֹ, \u0010y23\u0011 \u0010g8\u0011 \u0010m4\u0011 וְצָרִיךְ נֵר אַחֵר לְהִשְׁתַּמֵּשׁ \u0010c10\u0011 לְאוֹרוֹ; \u0010y24\u0011 וְאִם יֵשׁ מְדוּרָה אֵין צָרִיךְ נֵר אַחֵר; וְאִם הוּא אָדָם חָשׁוּב שֶׁאֵין דַּרְכּוֹ לְהִשְׁתַּמֵּשׁ לְאוֹר הַמְּדוּרָה, צָרִיךְ נֵר אַחֵר. \u0010g9\u0011 \u0010r9\u0011\nמַנִּיחוֹ \u0010y25\u0011 לְמַעְלָה מִג' טְפָחִים, וּמִצְוָה לְהַנִּיחוֹ \u0010y26\u0011 \u0010g10\u0011 \u0010m5\u0011 לְמַטָּה \u0010t7\u0011 \u0010s2\u0011 מִי' טְפָחִים, וְאִם הִנִּיחוֹ לְמַעְלָה מִי' טְפָחִים, יָצָא, \u0010g11\u0011 אֲבָל אִם מַנִּיחוֹ \u0010y27\u0011 לְמַעְלָה מִכ' אַמָּה \u0010y28\u0011 לֹא יָצָא. \u0005 הַגָּה: וַאֲפִלּוּ לְקָחָהּ כָּךְ דָּלוּק \u0010y29\u0011 וְהִנִּיחָהּ לְמַטָּה מִכ', לֹא יָצָא, \u0010m6\u0011 דְּהַדְלָקָה עוֹשָׂה מִצְוָה \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם \u0010g12\u0011 תּוֹסָפוֹת)\u0006. \u0010r10\u0011 \u0010r11\u0011 \u0010r12\u0011 \u0010r13\u0011\nמִצְוָה לְהַנִּיחוֹ \u0010y30\u0011 בַּטֶּפַח הַסָמוּךְ \u0010y31\u0011 לַפֶּתַח \u0010g13\u0011 מִשְּׂמֹאל, \u0010y32\u0011 כְּדֵי שֶׁתְּהֵא מְזוּזָה מִיָּמִין וְנֵר חֲנֻכָּה מִשְּׂמֹאל; \u0010y33\u0011 \u0010g14\u0011 וְאִם אֵין מְזוּזָה בַּפֶּתַח, מַנִּיחוֹ מִיָּמִין; \u0010y34\u0011 \u0010g15\u0011 וְאִם הִנִּיחוּ בַּדֶּלֶת עַצְמוֹ, יַנִּיחֶנּוּ \u0010y35\u0011 \u0010t8\u0011 \u0010s3\u0011 \u0010m7\u0011 מֵחֶצְיוֹ שֶׁל כְּנִיסָה לְצַד שְׂמֹאל. \u0005 הַגָּה: וּמִיהוּ בַּזְּמַן הַזֶּה, שֶׁכֻּלָּנוּ מַדְלִיקִין בִּפְנִים וְאֵין הֶכֵּר לִבְנֵי רְשׁוּת הָרַבִּים כְּלָל, אֵין לָחוּשׁ כָּל כָּךְ אִם אֵין מַדְלִיקִין בַּטֶּפַח הַסָּמוּךְ לַפֶּתַח; \u0010y36\u0011 וּמִכָּל מָקוֹם הַמִּנְהָג לְהַדְלִיק בַּטֶּפַח הַסָּמוּךְ לַפֶּתַח כְּמוֹ בִּימֵיהֶם, \u0010y37\u0011 וְאֵין לְשַׁנּוֹת אֶלָּא אִם כֵּן רַבִּים בְּנֵי הַבַּיִת שֶׁעָדִיף יוֹתֵר לְהַדְלִיק כָּל אֶחָד בְּמָקוֹם מְיֻחָד מִלְּעָרֵב הַנֵּרוֹת בְּיַחַד וְאֵין הֶכֵּר כַּמָּה נֵרוֹת מַדְלִיקִין; וּמִכָּל מָקוֹם יִזָּהֵר שֶׁלֹּא לְהַדְלִיק בַּמָּקוֹם שֶׁמַּדְלִיקִין הַנֵּרוֹת כָּל הַשָּׁנָה, כִּי אָז לֹא יִהְיֶה הֶכֵּר כְּלָל; וְאַף כִּי אֵין הֶכֵּר רַק לִבְנֵי הַבַּיִת, מִכָּל מָקוֹם הֶכֵּר קְצָת מִיהָא בַּעְיָא. \u0010y38\u0011 \u0010g16\u0011 \u0006 וּבְבֵית הַכְּנֶסֶת מַנִּיחוֹ \u0010y39\u0011 בְּכֹתֶל דָּרוֹם \u0005 אוֹ \u0010y40\u0011 \u0010g17\u0011 בִּדְרוֹם הַמְּנוֹרָה, \u0010y41\u0011 וּמְסַדְּרָן \u0010m8\u0011 מִמִּזְרָח \u0010y42\u0011 לְמַעֲרָב \u0006 \u0005(ת\"ה סי' ק\"ד \u0010y43\u0011 בֵּית יוֹסֵף)\u0006, וּמַדְלִיקִין \u0010g18\u0011 \u0010t9\u0011 \u0010s4\u0011 וּמְבָרְכִין \u0005 בְּבֵית הַכְּנֶסֶת \u0006 מִשּׁוּם פִּרְסוּמֵי נִסָא. \u0005 הַגָּה: וְאֵין אָדָם יוֹצֵא בַּנֵּרוֹת שֶׁל בֵּית הַכְּנֶסֶת, \u0010y44\u0011 וְצָרִיךְ לַחֲזֹר וּלְהַדְלִיק \u0010t10\u0011 \u0010s5\u0011 בְּבֵיתוֹ \u0006 \u0005(ריב\"ש סִימָן קי\"א)\u0006; \u0010y45\u0011 \u0005 וְנוֹהֲגִין לְהַדְלִיק בְּבֵית הַכְּנֶסֶת בֵּין מִנְחָה לְמַעֲרִיב; וְיֵשׁ נוֹהֲגִין לְהַדְלִיק \u0010y46\u0011 \u0010t11\u0011 \u0010s6\u0011 \u0010m9\u0011 בְּעֶרֶב שַׁבָּת \u0006 \u0005 קֹדֶם מִנְחָה \u0006 \u0005(כָּל בּוֹ וְאַבּוּדַרְהַם)\u0006; \u0010y47\u0011 \u0005 אִם רוֹצִים לְמַהֵר לְהִתְפַּלֵּל לְאַחַר שֶׁבֵּרַךְ הַשְּׁלִיחַ צִבּוּר וְהִדְלִיק אֶחָד מֵהֶן, \u0010y48\u0011 \u0010m10\u0011 יוּכַל \u0010t12\u0011 \u0010s7\u0011 \u0006 \u0005 הַשַּׁמָּשׁ לְהַדְלִיק הַנִּשְׁאָרִים, וְהַשְּׁלִיחַ צִבּוּר יִתְפַּלֵּל \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0010y49\u0011 \u0010c11\u0011 \u0010c12\u0011 \u0010c13\u0011 \u0010g19\u0011 \u0010r14\u0011 \u0010r15\u0011 \u0010r16\u0011 \u0010r17\u0011 \u0010r18\u0011 \u0010r19\u0011 \u0010r20\u0011 \u0010r21\u0011\nחָצֵר שֶׁיֵּשׁ לוֹ שְׁנֵי פְּתָחִים \u0010c14\u0011 מִשְּׁנֵי רוּחוֹת, צָרִיךְ לְהַדְלִיק בִּשְׁתֵּיהֶן \u0010y50\u0011 \u0010m11\u0011 מִפְּנֵי \u0010g20\u0011 \u0010t13\u0011 \u0010s8\u0011 הַחֲשָׁד; וְאִם שְׁנֵי הַפְּתָחִים \u0010y51\u0011 בְּרוּחַ אֶחָד \u0010y52\u0011 \u0010m12\u0011 \u0005 וְהֵם בְּבַיִת אֶחָד \u0006 \u0005(כָּל בּוֹ)\u0006 דַּי לוֹ בְּאֶחָד מֵהֶם. \u0005 הַגָּה: וְאִם מַדְלִיק בִּשְׁנֵי פְּתָחִים אֵינוֹ מְבָרֵךְ רַק בְּאֶחָד מֵהֶם וּבַשֵּׁנִי מַדְלִיק בְּלֹא בְּרָכָה, \u0006 \u0005(ר\"ן)\u0006 \u0005 מִיהוּ בַּזְּמַן הַזֶּה שֶׁכֻּלָּם מַדְלִיקִין \u0010y53\u0011 \u0010m13\u0011 בִּפְנִים מַמָּשׁ, וְאֵין הֶכֵּר לִבְנֵי רְשׁוּת הָרַבִּים כְּלָל, אֲפִלּוּ יֵשׁ לֶחָצֵר אוֹ לַבַּיִת הַרְבֵּה פְּתָחִים לְאַרְבַּע רוּחוֹת אֵין מַדְלִיקִים אֶלָּא פַּעַם אַחַת בִּפְנִים, כֵּן נ\"ל וְכֵן הַמִּנְהָג פָּשׁוּט. \u0006 \u0010r22\u0011 \u0010r23\u0011",{"g":["\u0003רמב\"ם בפ\"ב במשנה דאפי' עני שבישראל וכו'\u0004 פסחים צ\"א וה\"נ משום פרסומי ניסא","בריי' שבת כ\"ג וכב\"ה","תוס' שם וכ\"כ הטור","ר\"ל כמו שמפרש רמב\"ם סוגיא דגמ' שם דהרי כ' שהמנהג הפשוט בספרד שיהיו כל אנשי הבית מדליקין נר א' בלילה ומוסיפין נר בכל לילה ואפי' אם רבים בני הבית","מימרא דרב הונא שם כ\"ג","מימרא דרבא שם","ברייתא שם כ\"א וכפי' התוס' שם","שם בברייתא","מימרא דרבא שם","טור בשם מהר\"ם מרוטנבורג","מימרא דרבא שם","מימרא דרב שם כ\"ב","מימרא דרבה שם","כרב שמואל מדפתי שם","טור בשם אבי העזרי והגהות מרדכי בשם רבי יקיר","שם בשם סמ\"ק והמרדכי שם","שם","נ\"ל שצריך להיות או כנרות המנורה וכן הוא בת\"ה ודוק","כמו שמברכין על הלל דר\"ח אע\"פ שאינו אלא מנהג","מימרא דרב הונא וכדמפרש רבא שם כ\"ג","הא דאיתא לעיל בסימן צ' ס\"ח דהיכא דיש לב\"ה שני פתחים דליכא חשד התם שאני דכיון דאי לא מצלי הוה ליה פורק מלכות שמים לא אתו למחשדיה א\"נ שאני הכא דאית ביה הפסד ממון אתי למחשדיה טפי ב\"י:"],"t":["\u0003עני. \u0004 אבל אינו חייב להשכיר עצמו כמו בד' כוסות:","\u0003מוסיף. \u0004 נ\"ל דאם יש לו כדי להדליק בכל לילה נר אחד דאין צריך לחזור על הפתחים או למכור כסותו מאחר דיוצא י\"ח מן הדין. וכתב המ\"א ונ\"ל דמי שאין לו שמן הרב' יתן באחד שמן כשיעור והמותר יחלק לכולם שאם יעשה לכולם בשוה לא ידליק אפי' אחד כשיעור ואם יש לו שמן בצמצום ולחבירו אין לו כלום מוטב שידליק בכל ליל' א' ויתן גם לחבירו דהא מדינא א\"צ אלא אחד עכ\"ל:","\u0003המנהג. \u0004 וזה חידוש שהספרדים נוהגים כתוס' והאשכנזים כרמב\"ם וזה לא מצינו בשאר מקומות:","\u0003שנים. \u0004 פרש\"י בשביל ב' בני אדם למהדרין העושים נר לכל א'. ונ\"ל דלדידן דמוסיפין בכל ליל' לא ידליקו ב' אנשים בנר אחד דאז לא יהי' היכר כמה נרות מדליקין כמ\"ש בהג\"ה. מ\"א:","\u0003כפה. \u0004 וצריך שיכפה עליה כלי קודם שידליק שאם ידליקנה ואח\"כ יכפ' עליה כלי הרי הנרות היו דולקות מקמי הכי במדורות ולית בהו שום מצוה וע\"י כפיית הכלי נתקנה להיות כנרות וצריך שתהי' בשעת הדלקתם לשם מצו' מהר\"א הלוי בספר גן המלך סי' קנ\"א:","\u0003בשוה. \u0004 ולא אחד נכנס וא' יוצא. ד\"מ מהרי\"ל:","\u0003לאמפ\"א. \u0004 וכ' רש\"ל צריך לתלותה בטפח הסמוך לפתח ויתחיל מנר האמצעי שהוא הסמוך לפתח ויסבב לצד ימין. והמדקדקים אינם מדליקין בלאמפ\"א שאין בה הידור לנר חנוכה עכ\"ל:","\u0003מי\"ט. \u0004 נ\"ל דאם דר בעליה מניח' בחלון אפי' הוא למעל' מיו\"ד מ\"א. וע' בתשו' פנים מאירות סי' מ\"ז. ובתשובת שבות יעקב ח\"ב סי' ל\"ב. וע' ביד אהרן:","\u0003מחציו. \u0004 עט\"ז ובב\"ח וחות יאיר סי' רכ\"ז:","\u0003ומברכין. \u0004 עיין בתשובת חכם צבי סי' פ\"ח מה שתמה ע\"ז. כתב רמ\"א בתשו' סי' מ\"ו דאם אבל מתפלל בערב חנוכה ידליק אדם אחר הנרות משום שהחיינו אבל שאר ערבית דחנוכה יתפלל ע\"ש:","\u0003בביתו. \u0004 משמע אפי' הש\"ץ צריך לחזור ולהדליק בביתו:","\u0003קודם מנחה. \u0004 וכ\"כ רש\"ל. ובד\"מ כתב ואין אנו נוהגין כן אלא מדליקין בין מנחה למעריב ונ\"ל דאם הוא סמוך לחשיכה וטרם שיבואו מנין לבה\"כ יתקדש היום יברך וידליק מיד דמ\"מ איכא פרסומי ניסא כשבאים אח\"כ לבה\"כ. מ\"א ע\"ש ועיין בתשובת שבות יעקב ח\"ב סימן מ\"א:","\u0003השמש וכו'. \u0004 אבל בביתו צריך הוא להדליק כולם לבוש. אבל רש\"ל בתשו' כתב שגם בביתו רשאי לעשות כן וכן נ\"ל שכן מצינו ביומא פרק ג' קרצו ומרק אחר ע\"י וכו' ע\"ש ועיין בחולין פרק ב':","\u0003החשד. \u0004 עט\"ז ומ\"א. ובתשובת חכם צבי סימן צ\"א. ובתשובת יד אליהו סי' ז' וע' בי\"א במה ששמע להקשות ודו\"ק:"],"s":["\u0003מוסיף והולך כו'. \u0004 עבה\"ט ועיין בר\"י מי שלא היה לו שמן רק לנר אחד ובירך עליו ותיכף נזדמן לו שמן לנרות השייכים להידור בלילה ההיא כתב מהר\"מ מזרחי ומהר\"א נחום דלא יברך פעם אחרת על נרות הנוספים ועיין לקמן סוף סי' תרע\"ב. וע\"ש אם ב' וג' ב\"ב דרים בבית א' וכ\"א אוכל עם ב\"ב בפ\"ע כ' בש\"ה שא\"צ להדליק כ\"א בפ\"ע רק להשתתף יחד בפריטי ודלא כמ\"ש בשערי ישועה כו':","\u0003המנהג. \u0004 וע' בכנסת יחזקאל סי' י\"ז ששם המנהג הספרדים שרק בעה\"ב הוסיף והולך וכתב שאם אשכנזי דר בבית אצל ספרדי אינו יכול למחות בידו האשכנזי הדר שם מלהדליק בביתו ואין בזה משום לא תתגודדו כו' ע' שם מלתא בטעמא:","\u0003מיוד טפחים. \u0004 עבה\"ט ועיין בפמ\"א שתמה לפי מ\"ש הטור בח\"מ סימן תי\"ח לפסוק כת\"ק דר\"י א\"כ האיך פסק הכא כרבינא דאליבא דר\"י אתמר עיין שם באורך ובשבו\"י ח\"ג כתב דפלוגתת רבנן הוא לומר שאף על פי שהוא ברשות חייב דהכי משמע מדקאמר ר\"י אומר בנ\"ח פטור מפני שהוא ברשות וגם דאיך קאמר זאת אומרת כו' דלא כהלכתא עיין שם וע' בתוספתא פ\"ו דב\"ק דתני ר\"י אומר בנ\"ח פטור מפני שהניח ברשות ח\"א בין זה ובין זה חייב כגון אלו מסככין על פתחי חנותיהן ברה\"ר אע\"פ שיש להם רשות ובא אחר והוזק בהם חייב עיין שם לשון זה משמע קצת כמ\"ש השבו\"י דלאו מטעם הנ\"ל לאנוחי למעלה מגמל ורוכבו אתי עלה אלא אפי' אם מצוה להניח תוך יו\"ד טפחים וברשות קעביד אפ\"ה אם הוזק חייב ועיין מ\"ש במח\"ב בזה. ובא\"ר הביא בשם סדר היום שמצותה למעלה מעשרה טפחים עד י\"ח טפחים שכן גובה של מנורה י\"ח טפחים והא\"ר תמה עליו דמנ\"ל לומר דלמטה מעשרה לא ובמח\"ב כ' כיון שהרי\"ף והרמב\"ם השמיטו הא דאמר\"י צריך להניח למטה כו' מסתמא דין חנוכה כסוכה ומבוי וכ\"כ הרמ\"ע בס' אלפסי זוטא וע\"ש שבטור ברקת כתב דמצוה להניחה מעט למעלה משבעה טפחים ובסוף שומר אמונים סימן ה' כ' שיש לו מקום בכתבי האר\"י ז\"ל על מה לסמוך עיין שם:","\u0003מחציו. \u0004 עבה\"ט ועיין בחוות יאיר סימן רכ\"ו על מ\"ש הב\"י בפי' דברי הסמ\"ק ובדברי הב\"ח שם עיין שם ועיין מ\"ש ביד אפרים דברי הט\"ז בזה:","\u0003ומברכים. \u0004 עבה\"ט ומ\"ש בשם הח\"צ סי' פ\"ח שתמה על זה שאין תמיהתו רק על המחבר שכ' דין זה דהא עיקר טעם הריב\"ש הוא דמברכים כמו שמברכים על הלל בר\"ח שהוא ממנהגא (ועיין באר הגולה) א\"כ המחבר שפסק בה' ר\"ח כהרמב\"ם וכתב שכן נוהגים בא\"י וסביבותיהם וא\"כ לדידהו אין לברר בנר בה\"כ ע\"ש אבל לדידן דמברכים בהלל בר\"ח גם הח\"צ מודה דשפיר מברכים אנרות בה\"כ ומ\"ש בה\"ט כ' רמ\"א בתשובה כו' זה העתיק מט\"ז והוא ט\"ס בט\"ז וצ\"ל רמ\"מ סימן מ\"ג והוא ר\"ת מוהר\"ם מינץ וכמ\"ש ביד אפרים ומצאתי במח\"ב ובנ\"ב שהרגישו בזה ועיין שם במח\"ב ובנ\"ב שכתבו שזהו לענין להדליק בציבור משא\"כ בביתו בודאי מברך שהחיינו ועיין במג\"א סימן תקנ\"א כו' עיין שם ועיין מ\"ש ביד אפרים בזה:\n(•) \u0003 (ס\"ז בש\"ע) ובבה\"כ מניחו \u0004 ועיין בכנסת יחזקאל שכ' בקהלות אה\"ו בבה\"כ הגדולה באלטונה שהיא ראשון במנין ובנין מסדרין בין צפון לדרום ובשאר בה\"כ קטבים זה בכה כו' אף שהמסדרים בין מזרח למערב הוא בש\"ע וכ\"כ רש\"ל וט\"ז מכל מקום נראה לי עיקר כהרמב\"ם וריב\"ש סימן ת\"י ולכן גזר אומר שיהיו כולם נמשכין אחר בה\"כ מלסדר בין צפון לדרום כמו הבה\"כ הגדולה אף דל\"ש במנהג לא תתגודדו ומכ\"ש בג' קהילות אה\"ו שהם ככל ב\"ד בעיר א' כמ\"ש המג\"א סימן ת\"צ מ\"מ בדברי המג\"א קצת צ\"ע ומוטב שיהיו כל הבה\"כ שוים לטובה עיין שם ועיין במו\"ק שאם אין בבה\"כ עשרה אין להדליק בברכה ועיין לקמן ס\"ק י\"ב:","\u0003בביתו. \u0004 עבה\"ט עיין במח\"ב בשם זרע אמת אם הדליק בלילה הראשונה בביתו ואח\"כ מדליק בבה\"כ יברך שהחיינו ג\"כ ואם הדליק קודם בבה\"כ לא יחזור לו' בביתו ברכת שהחיינו אם לא שמדליק להוציא ג\"כ אשתו וב\"ב עיין שם:","\u0003קודם מנחה. \u0004 ועיין לעיל ס\"ק ז' מ\"ש בשם מו\"ק דחולק ע\"ז אלא כיון שהוא משום פרסומי ניסא צריך שיהיה עדה בשעת מעשה ומכל מקום כשהשעה דחוקה אין לבטל ההדלקה רק ידליק בלא ברכה עיין שם ומ\"ש בשם השבו\"י ח\"ב עיין שם דמבואר במקום שיש מנהג להדליק בכל השנה באותה מנורה דליכא היכר אם הנרות של שעוה גדולים שדולקים עכ\"פ עד חצות לילה כמנהג בבה\"כ פשיטא דהוי היכרא טובא אלא אפי' כשמדליקין בשמן זית וכן בכל השנה באותה מנורה אז יפסיק בשבת קודם ולא ידליק באותן נרות דאו הוי היכר פרסומי ניסא כמ\"ש לענין שמפסיקין לתקוע בער\"ה כדי להפסיק בין תקיעות דאורייתא לדרבנן וה\"ה לענין פרסומי ניסא דרבנן עיין שם ולענ\"ד צ\"ע אם יש לבטל בשביל זה ההדלקה שנוהגין תדיר להדליק לכבוד שבת במנורה זו בבה\"כ בשביל שיהיה בשבת חנוכה שאח\"ז פרסומי ניסא ואין זה דומה לתקיעות כלל כמובן ויותר נראה שידליק איזה שבתות קודם נרות פשוטים כשאר נרות של בה\"כ וכשידליק עתה שמן זית איכא פרסומי ניסא ואע\"ג דגם לגבי שבת אמרינן דשמן זית מן המובחר מכל מקום אין קפידא כ\"כ כמו אם לא ידליק כלל מכ\"ש אם ידליקו בשבתות קודם נרות שעוה שלדעת הב\"ח נרות שעוה דידן הוי' כשמן זית שהרי אורה צלול וכמבואר בסימן רס\"ד עיין שם וע\"ש בשבו\"י מ\"ש ליישב קושיית גיסו בעל א\"ז על התו' בשבת דף ך\"א דמדייקו מנר שיש לו שתי פיות כו' עיין שם:","\u0003השמש. \u0004 עבה\"ט ועיין במו\"ק שהסכים ללבוש וכ' דבעל נפש יחוש כיון שהוא רוצה להיות מן המהדרין אינו בדין שעול מצות יהיה עליו כמשוי ע\"ש והביאו מח\"ב:","\u0003החשד. \u0004 עבה\"ט ועיין בספר רב משולם בסוף סימן ב' והגאון ח\"צ ז\"ל לפרש דברי רש\"י שכתב אחד בצפון ואחד במזרח משום שבימיהם החצר לפני הבית והרחב' מאחוריו ולכן א\"א לומר שהשני למערב שא\"כ הוא פתוח לרחבה והאיך אפשר לומר שהבית חלוק לשני בני אדם שהרי כל בית של אדם א' יש לו שני פתחים אלו לכך הוצרך לומר אחד בצפון ואחד במזרח עיין שם ועיין בבה\"י בשם מכתם לדוד מי שייש לו חצר של שני פתחים שמברך באחת ויום א' שהיה טרוד צוה שידליקו וכן עשו והדליקו בפתח א' ועד שלא הדליקו בשני בא יכול לברך כשידליק בפתח שני עיין שם:"],"m":["\u0003מוסיף והולך\u0004. נ\"ל דמי שאין לו שמן הרבה יתן באחד שמן כשיעור והמותר יחלק לכולם שאם יעשה לכלם בשוה לא ידלק אפי' א' כשיעור ואם יש לו שמן בצמצום ולחבירו אין לו כלל מוטב שידליק בכל לילה א' ויתן גם לחבירו דהא מדינא א\"צ אלא א':","\u0003בשביל ב'\u0004. פירש\"י שני בני אדם למהדרין העושים נר לכל א' ונ\"ל דלדידן דמוסיפין בכל לילה לא ידליקו ב' אנשים בנר א' דאז לא יהי' היכר כמה נרות מדליקין כמ\"ש בהג\"ה:","\u0003בשורה בשוה\u0004. ולא א' נכנס וא' יוצא [ד\"מ מהרי\"ל]:","\u0003שאין לדבקן יחד\u0004. ז\"ל ד\"מ כשמדליקין נר שבת או חנוכה או י\"ט ודובקין הנרות סמוכין זה לזה עד שהן מתחממות זו מזו ונוטף השעו' משום החמימות גם נכפלו' ונופלו' לא קיימו מצוה [א\"ז] עכ\"ל משמע דנרות כרוכים יחד מותר לעשות דהא בשבת ויו\"ט מצוה לעשות כרוכים כמ\"ש סי' רס\"ג ובמהרי\"ו כ' וז\"ל בערפורט לוקחין ד' או ה' נרות חנוכה ומדביקין אותן ביחד [פי' שקלועין כמו שרשרת] ומדליקין אותן לנר א' ואסרתי אותן דהוי כמדו' עכ\"ל אפשר דשני נרות שרי אבל בתשובת רש\"ל משמע דאסור וכ\"מ סי' רצ\"ח סק\"ב וסי' תל\"ג ס\"ב, כ' רש\"ל בתשו' המדליק בפמוטות יתלה אות' בטפח הסמוך לפתח ויתחיל בנר האמצעי הסמוך לפתח ויסב בדרך ימין המדקדקי' אין מדליקין בפמוטו' שאין בהן הידור לנר חנוכה עכ\"ל:","\u0003וצריך נר אחר\u0004. פי' הר\"ן אף על פי שמדליקו על השלחן וע\"כ הוא משתמש לאור' אפ\"ה צריך להדליק נר אחד משו' הכירא עכ\"ל ומזה יצא המנהג שמדליקין שמש כמ\"ש רמ\"א סי' פ\"א:","\u0003למט' מי'\u0004. נ\"ל דאם דר בעליה מניח' בחלון אפי' הוא למעלה מי':","\u0003דהדלקה עושה מצוה\u0004. וביש\"ש ספ\"ו דב\"ק מפרש הטעם דהרואה אומר לצרכו הוא דנקט לה:","\u0003מחציו של כניס'\u0004. בסה\"ת הגי' מחצי' לצד שמאל של כניסה פי' שניחנו בחצי השנית שלא בצד המזוזה, ומ\"מ המנהג משום שיכנס בין ב' מצות (ד\"מ) ונ\"ל דאם יש לו חלון הסמוך לר\"ה יניחנו בחלון דבזה ליכא חשש סכנה אם לא במקום דשכיחא הזיקא:","\u0003ממזרח למערב\u0004. ויש מסדרין מצפון לדרום כמ\"ש סמ\"ג והרמב\"ם ונהרא נהרא ופשטיה (ת\"ה) וז\"ל רש\"ל ויהיו מונחים ממזרח למערב ואל תשגיח במנהג עכ\"ל ול\"ל דאין לזוז ממנהג דיש לו על מה לסמוך:","\u0003קודם מנחה\u0004. וכ\"פ רש\"ל ובד\"מ כתוב ואין אנו נוהגין כן אלא מדליקין בין מנחה למעריב ונ\"ל דאם הוא סמוך לחשיכ' וטרם שיבואו מנין לבה\"כ יתקדש היום יברך וידליק מיד דמ\"מ איכא פרסומא ניסא כשבאים אח\"כ לבה\"כ ודמי למדליק ברחוב בשע' שאין שם איש ואח\"כ באו אנשים וכ\"ה במהרי\"ל שהדליקו טרם בואם לבה\"כ:","\u0003יוכל השמש וכו'\u0004. אבל בביתו צריך הוא להדליק כולם (לבוש) אבל רש\"ל בתשו' כ' שגם בביתו רשאי לעשו' כן ע\"כ וכן נ\"ל שכן מצינו ביומא פ\"ג קרצו ומרק אחר על ידו וכו' ע\"ש בחולין פ\"ב:","\u0003מפני החשד\u0004. שיאמרו מדלא אדליק בהא באחרת נמי לא אדליק אבל כשהם מרוח א' חזי ליה ולא חיישי' לחשד דעלמא שיסברו שהבית חלוק מתוכו ויאמרו שהם שני בתים דאנשים נכרים אין מצוים ברחובות בלילה, הקשה הרב\"י בסי' צ' ס\"ח אמרי' אם יש לבה\"כ פתח אחר מותר וכו' ולא אמרי' מדבהא לא עייל בהא נמי לא עייל ותי' כיון שיש כאן חסרון כיס יחשדוהו טפי משא\"כ בבה\"כ עכ\"ל ול\"נ דלק\"מ דמהם אין הטעם שיחשדוהו שלא יכנס לבה\"כ דהא באמת כמה פעמים שהוא טרוד בעסקיו א\"צ לילך לבה\"כ ועוד דכשמהלך בשוק בשעת תפלה אנו רואים שאין נכנס לבה\"כ ואפ\"ה שרי אלא הטעם כמ\"ש רש\"י דכשהולך סמוך לבה\"כ נראה כפורק עול ומבז' בה\"כ שאע\"פ שאינו נכנס לה הולך סמוך לה דה\"ל להתרחק ממנה ולהתבייש במה שאינו יכול ליכנס לה אבל אי איכא פתחא אחרינא ליכא ביזוי לבה\"כ דוק ברש\"י בברכות דף ס\"א ותמצא כדברי ועל תי' הרב\"י קשה דאטו בבה\"כ מי לית בה חסרון כיס דאדהכי והכי בטל משווקים כדאמרינן בב\"מ פ\"ב:","\u0003והם בבית א'\u0004. אבל אם הם בב' בתים אף על פי שהם של אדם א' צריך להדליק בשתיהן (ד\"מ כל בו) אבל מלשון רש\"י דדוקא כשהן של ב' בני אדם צריך להדליק בשתיהן ע\"ש אבל של אדם א' א\"צ וכ\"מ סי' תרע\"ז דדוקא אורח שיש לו פתח פתוח חייב משמע דבע\"ה פטור:","\u0003בפנים ממש\u0004. פי' שבזמן הטור היו מדליקין אצל פתח הבית מבפנים אבל אנו מדליקין בפנים ממש:"],"r":["\u0003ס\"א צריך כו'. \u0004דאמרינן שם הזהיר בנר כו' ופירש רש\"י שם ד\"ה בנים הנר שבת וחנוכה וכ\"כ הטור:","\u0003ואפי' עני כו'. \u0004דאמרינן בפ' ע\"פ ולא יפחתו כו' ואפי' מן התמחוי ופי' רשב\"ם שואל או כו' ואמרינן בגמ' מן התמחוי פשיטא לא נצרכה אלא לר\"ע כו' תנא דבי אליהו אע\"פ שאמרו עשה כו' אלמא דבר מועט לכבוד שבת צריך לשאול על הפתחים שואל או מוכר כנ\"ל ואמרינן שם דקידוש קודם לכבוד היום וכבוד לילה ואמרינן בשבת שם דנ\"ח קודם לקידוש היום ש\"מ דמוכר כו'.","\u0003ס\"ב ואפילו רבים. \u0004תוס' דלא קאי אמהדרין דא\"כ לא הוי היכר וכ\"כ הרמב\"ם דכן נהגו:","\u0003וי\"א \u0004כ\"כ הרמב\"ם להלכה נראה שכן הוא דעת הרי\"ף מדהביא מימרא דרבב\"ח אר\"י שני זקנים כו' כנגד פרי החג כו' דמעלין בקודש ואין כו' דלהאי טעמא לא חיישינן להיכרא דימים הנכנסין או היוצאים שכתב התוספות שם. וכ\"מ בגמרא שם חד אמר כו' וחד אמר טעמא כו' דנ\"מ בכה\"ג כנ\"ל ומסקנא דב' זקנים כמ\"ד דמעלין בקודש כו':","\u0003וכן המנהג. \u0004כתב בד\"מ בשם מהראמ\"פ דלדידן שמדליקין בפנים ויודעין כמה בני הבית אף תוס' מודי ועוד כיון שמדליקין בפנים אין לחוש לטפח הסמוך לפתח כ\"כ כמ\"ש בס\"ז בהג\"ה ויכולין להדליק כ\"א במקום מיוחד ואיכא היכרא וז\"ש ויזהרו כו' וע\"ש בהג\"ה:","\u0003ס\"ג בשביל שנים. \u0004הטור כתב לב' נרות מליל ב' ואילך לפ\"ד שכתב כדעת התוספות בס\"ב ואפי' רבים כו' ולכן לא פירש כפירש רש\"י למהדרין אחר שאנו עושין כמהדרין מן המהדרין וגם לא פירש כפירוש תוספות לפי שאנו מדליקין בבית אבל ש\"ע שהעתיק בס\"ה לשון גמרא ותוספות כתב בשביל שנים כלשון גמרא:","\u0003ס\"ד בשורה בשוה. \u0004עמ\"א:","\u0003מאחר שכל. \u0004שכן פירש בעל העיטור מלא קערה כז' במקורבות דוקא ואף להטור שחולק עליו כאן מודה כיון שמובדלות במחיצה וע' תה\"ד:","\u0003אפי' בנרות של. \u0004עמ\"א סי'","\u0003ס\"ה הסמוך לר\"ה. \u0004כפירוש תוספות שם שהכריחו מהא דס\"ג וכבר נזהר רש\"י מזה כנ\"ל ועוד הכריחו מהא דס\"ח:","\u0003ס\"ו מניחו למעלה. \u0004מרדכי:","\u0003ומצוה כו'. \u0004דלא שבקינן פשיטותא דרבא משום דחייה בעלמא הרשב\"א ורא\"ש וש\"פ דלא כרי\"ף ורמב\"ם שהשמיטו:","\u0003ואם הניחו. \u0004כן מוכח ממ\"ש בסמוך אבל כו':","\u0003ואפי' לקחה. \u0004דלהכי ל\"ק ימעט כמ\"ש בעירובין ב' א' מבוי' דרבנן כו' משום דימעט משמע בעודה דלוקה כו' וע\"ש: דהדלקה כו'. כן העתיק בב\"י בשם תוספות וליתא בתוספות שלנו אלא דלכאורה משמע כן ממ\"ש בתוספות כ\"ב א' סד\"ה נ\"ח. כדמוכח לקמן ור\"ל כמ\"ש כ\"ג א' עששית כו' וע' תוס' שם ד\"ה מכבה כו' אבל בריש סוכה סד\"ה דאורייתא כתב ואפילי למ\"ד כו' ולזה כיוונו ג\"כ בתוספות דשבת ול\"ד לעששית כו' שהקשו וא\"ת כו'. דשם מונחת במקומה:","\u0003ס\"ז ואם אין. \u0004דלא אמרו שמאל אלא משום מזוזה כנ\"ל:","\u0003ומיהו כו'. \u0004כ\"מ בדברי מהראמ\"פ הנ\"ל בס\"ב:","\u0003ומ\"מ המנהג כו'. \u0004וכ\"כ מהרי\"ל ותה\"ד וכ\"ב המרדכי והטור אלא שאין ראיה מהמרדכי והטור לפי שבימיה' היו מדליקין בפתח הבית כמ\"ש בטור בס\"ס תרע\"ב. ר\"מ. וז\"ש אא\"כ כו' וכנ\"ל בס\"ב:","\u0003ומ\"מ יזהרו. \u0004בגמרא שם ובשעת הסכנה כו' וצריך כו' וערש\"י ד\"ה צריך כו':","\u0003בכותל דרום. \u0004זכר למנורה וג\"כ משום סידור כמ\"ש בהג\"ה ומסדרן כו'. וכתב בתה\"ד משום דקי\"ל הלכה כרבי מחבירו וכן ס\"ל לרש\"י כמ\"ש ברפ\"ב דשבת ובפי' התורה אבל הרמב\"ם פסק כרבו בשלחן וכר\"א ב\"ש במנורה וכ\"ד הסמ\"ג וטעמו דקי\"ל כרבי מחבירו וכן סתם דמתניתין דמנחות שם כרבי כמ\"ש תוס' שם צ\"ו א' ד\"ה כל צ\"ח ב' ד\"ה מזרח כו' וכ\"פ הרמב\"ם שם כהמתניתין והעתיקה הרמב\"ם שם הלכה ח' אבל במנורה פסק כראב\"ש משום דסוגיא דמגילה כ\"א ב' כוותיה. אבל הראב\"ד שם השיג עליו וכתב דהא מתני' דתמיד כרבי וכ\"כ תוספות במנחות צ\"ח ב' ד\"ה מדכתיב כו' והרמב\"ם בפי' שם כתב דלא קי\"ל כהך מתניתין:","\u0003מדליקין. \u0004ראיה מהלל בלילי פסחים שנתקן על הכוס ואומרין בב\"ה משום פרסומי ניסא כמ\"ש בירושלמי בענין ברכה הסמוכה לחברתה והרי אשר גאלנו שניא שאם שמעה בב\"ה יצא:","\u0003ואין אדם. \u0004שאף חצר שיש לה שני פתחים כו' ועוד שהרי אמרו נר איש וביתו:","\u0003ואם רוצים. \u0004ע' מ\"א מיומא פ\"ג קרצו מרק כו' ושם דוקא משום שהיה צריך למהר לקבל הדם וז\"ש ואם רוצים למהר דוקא ואף שהשאר אינן אלא מצוה בעלמא שם ג\"כ המירוק אמרו בחולין פ\"ב יכול לא מירק כו' ועמ\"א:","\u0003ס\"ח והם בבית אחד. \u0004כן משמע ברש\"י ד\"ה אפי' מרוח כו' דלא כמ\"א שכתב משמו להיפך:","\u0003ומיהו כו'. \u0004כ\"כ בטור בשם סה\"ת וחלק עליו דכיון שמדליקין בפתח יש היכרא לעוברין ושבין וכתב בד\"מ דבימיו היו מדליקין בפתח הבית וכ\"כ ברי\"ו משא\"כ לדידן שמדליקין בפנים ממש וז\"ש ממש כו':"]}],["אֵין מַדְלִיקִין נֵר חֲנֻכָּה קֹדֶם שֶׁתִּשְׁקַע הַחַמָּה, אֶלָּא \u0010y0\u0011 עִם סוֹף שְׁקִיעָתָהּ, \u0010c0\u0011 לֹא מְאַחֲרִים \u0010c1\u0011 וְלֹא מַקְדִּימִים. \u0010c2\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר \u0010y1\u0011 שֶׁאִם הוּא טָרוּד יָכוֹל לְהַדְלִיק \u0010y2\u0011 מִפְּלַג הַמִּנְחָה וּלְמַעְלָה, וּבִלְבַד \u0010y3\u0011 שֶׁיִּתֵּן בָּהּ שֶׁמֶן \u0010c3\u0011 עַד שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק.\nשָׁכַח אוֹ הֵזִיד וְלֹא הִדְלִיק עִם שְׁקִיעַת הַחַמָּה, מַדְלִיק וְהוֹלֵךְ עַד שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק, שֶׁהוּא כְּמוֹ חֲצִי שָׁעָה שֶׁאָז הָעָם עוֹבְרִים וְשָׁבִים וְאִכָּא פִּרְסוּמֵי \u0010y4\u0011 נִסָא; הִלְכָּךְ צָרִיךְ לִתֵּן בָּהּ שֶׁמֶן כְּזֶה \u0010y5\u0011 \u0010c4\u0011 הַשִּׁעוּר, וְאִם נָתַן בָּהּ יוֹתֵר \u0010y6\u0011 יָכוֹל לְכַבּוֹתָהּ לְאַחַר שֶׁעָבַר זֶה הַזְּמַן, וְכֵן יָכוֹל \u0010y7\u0011 לְהִשְׁתַּמֵּשׁ לְאוֹרָהּ לְאַחַר זֶה הַזְּמַן. \u0005 הַגָּה: יֵשׁ אוֹמְרִים \u0010y8\u0011 שֶׁבַּזְּמַן הַזֶּה שֶׁמַּדְלִיקִין בִּפְנִים \u0010y9\u0011 אֵינוֹ צָרִיךְ לִזָּהֵר לְהַדְלִיק קֹדֶם שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק \u0006 \u0005(דִּבְרֵי עַצְמוֹ וְטוּר בְּשֵׁם תּוֹסָפוֹת)\u0006, \u0005 וּמִכָּל מָקוֹם טוֹב \u0010c5\u0011 לִזָּהֵר גַּם בַּזְּמַן הַזֶּה; \u0006 וּמִיהוּ הָנֵי מִלֵּי לְכַתְּחִלָּה, אֲבָל אִם עָבַר זֶה הַזְּמַן וְלֹא הִדְלִיק, מַדְלִיק וְהוֹלֵךְ \u0010y10\u0011 כָּל הַלַּיְלָה; וְאִם עָבַר כָּל הַלַּיְלָה וְלֹא הִדְלִיק, אֵין לוֹ תַּשְׁלוּמִין. \u0005 הַגָּה: וּבַלֵּילוֹת הָאֲחֵרוֹת יַדְלִיק \u0010y11\u0011 כְּמוֹ שְׁאָר בְּנֵי אָדָם, אַף עַל פִּי שֶׁלֹּא הִדְלִיק בָּרִאשׁוֹנָה \u0006 \u0005(מָצָא כָּתוּב בְּשֵׁם מַהֲרִי\"ל וַאֲגֻדָּה וְדִבְרֵי עַצְמוֹ)\u0006.",["\u0003עם סוף שקיעתה\u0004 היינו צאת הכוכבים שאז העם עוברין ושבין ורואין בביתו ואיכא פרסומי ניסא. אכן בע\"ש מקדימין וכדלקמן בסי' תרע\"ט והנה המחבר סתם כדעת הטור וסייעתו דס\"ל דמה שאמר הגמרא דזמן הדלקת נר חנוכה הוא משתשקע החמה היינו סוף שקיעה אבל באמת יש הרבה ראשונים דס\"ל דכונת הגמרא הוא על תחלת שקיעה שניה והוא בערך רבע שעה מקודם ועיין בביאור הלכה שביארנו דלאותן האנשים הנוהגין להתפלל מעריב בזמנו דהיינו אחר צאת הכוכבים נכון לנהוג כן לכתחלה להדליק קודם מעריב וכ\"כ במור וקציעה וכן נהג הגר\"א [אכן יטיל בה כ\"כ שמן שידלוק חצי שעה אחר צאת הכוכבים] ואם לא הדליק מקודם והגיע זמן צה\"כ יקדים להתפלל מעריב דהוא תדיר וגם יש בה מצות ק\"ש שהיא דאורייתא [שע\"ת] ודע דאפילו הנוהגין תמיד להדליק אחר תפלת ערבית מן הנכון שיכינו עכ\"פ השמן בתוך הנרות קודם תפילת ערבית כדי שיהיה מוכן תיכף אחר תפלת ערבית להדליק דאם יעשה הכל אחר תפלת ערבית בודאי יש לחוש שיעבור עיקר זמן הדלקתו והוא חצי שעה מדינא דגמרא:","\u0003שאם הוא טרוד וכו'\u0004 ר\"ל שלא יהיה לו פנאי אח\"כ:","\u0003מפלג המנחה\u0004 הוא שעה ורביע קודם צה\"כ וחשבינן השעה לפי קוצר היום דהיינו שעות זמניות. ויכול לברך ג\"כ:","\u0003שיתן בה שמן עד וכו'\u0004 דאם לא ידלוק בלילה ליכא פרסומי ניסא. ואם לא נתן בה שמן רק כשיעור חצי שעה כנהוג בכל יום יחזור ויתן בה שמן וידליק ומ\"מ לא יחזור ויברך:","\u0003הלכך צריך ליתן וכו' כזה וכו'\u0004 משמע דאם הדליק זמן מה אחר שקיעת החמה א\"צ ליתן שמן כ\"כ רק עד שתכלה רגל מן השוק אכן כ\"ז הוא לדין התלמוד שהיה ההיכר לעוברים ושבים אבל האידנא דההיכר הוא רק לב\"ב לעולם בעי שיעור הידוע [פר\"ח] ואף מדליק אחר שכלה הרגל משוק בעי זה השיעור [פמ\"ג]:","\u0003השיעור\u0004 ואף בזמנינו צריך לשיעור הזה אבל אם נותן בה שמן הרבה שידליק יותר אין בו שום מצוה אבל בנרות של שעוה יש הידור מצוה כשהן ארוכות ומ\"מ אין לעשותם גדולות יותר מדאי. כתב הב\"י בשם א\"ח מי שבירך והדליק נר אחת בלילה שניה ידליק אח\"כ עוד נר אחת ולא יברך ועיין בפמ\"ג שמצדד דאפילו לא היה דעתו מתחלה רק על נר אחת ואח\"כ נזדמן לו עוד נר ג\"כ לא יברך עוד כי מדינא אין חיוב רק נר א' והשאר משום הידור כנ\"ל:","\u0003יכול לכבותה וכו'\u0004 שאינו מקצה השמן רק מה שצריך לשיעור חצי שעה למצותו וע\"כ מותר לכבותו ולהנות ממנו ומ\"מ הסכימו כמה אחרונים דלכתחלה טוב להתנות שאינו מקצה השמן אלא לשיעור הדלקה משום דיש מן הפוסקים שסוברים דאם נתן בסתם הקצה למצותה הכל:","\u0003להשתמש לאורה וכו'\u0004 ויש מחמירין שבעוד שהנרות דולקין אין להשתמש לאורן משום הרואה שלא ידע לחלק בין תוך זמן שיעורו לאחר זה הזמן:","\u0003שבזמן הזה שמדליקין בפנים\u0004 ר\"ל וא\"כ ההיכר הוא רק לב\"ב:","\u0003אינו צריך\u0004 וידליק כשבני הבית מקובצים יחד. ואפילו ללמוד אסור משהגיע זמנה וכ\"ש אכילה וש\"ד ואפילו התחיל פוסק:","\u0003כל הלילה\u0004 עד עמוד השחר ובברכה והיינו דוקא אם בני הבית נעורים אבל אם ישנים אין לברך עליהם אלא ידליק בלא ברכה דכמו דלדידהו לא היה מברך אלא בזמן פרסום הנס ה\"נ לדידן. ואם בא לביתו קודם עה\"ש ומצא ב\"ב ישנים מן הנכון שיקיצם כדי שיוכל להדליק בברכה:","\u0003כמו שאר בני אדם\u0004 ר\"ל בלילה שניה שתי נרות ובלילה שלישית שלש ולא נימא דלדידיה הלילה שניה היא ראשונה וידליק רק אחת [ד\"מ]:"],["\u0003 עם סוף שקיעתה\u0004 - כ\"כ הטור וכ\"כ הרא\"ש בפ\"א דתענית אבל ברשב\"א ור\"ן משמע בהדיא שהוא תחלת השקיעה אלא דמשמע שם בשקיעה שניה [הגר\"א] וכ\"כ במאירי כרשב\"א ור\"ן וכתב עוד ועיין במרדכי ספ\"ב דשבת שכתב דלשון משתשקע מוכח שהוא תחלת השקיעה וכו' וכן עיקר עכ\"ל וכ\"כ הפר\"ח.","\u0003 לא מאחרים\u0004 - ולפ\"ז צריך להדליק תיכף אחר צה\"כ וא\"כ צ\"ע מי שנוהג תמיד להתפלל מעריב בזמנו דהיינו אחר צה\"כ איך יעשה [פמ\"ג] והנה לדחות תפילת ערבית משום זה ג\"כ אינו כדאי דיש בה מצות ק\"ש שהיא דאורייתא וגם דתדיר קודם כמו שכתבו האחרונים וע\"כ נ\"ל דאיש כזה בודאי מן הנכון שידליק קודם מעריב אחד דהרבה ראשונים ס\"ל דלכתחלה יש לנהוג כן כמו שהביא הגר\"א ועוד דאף הטור שכתב סוף שקיעה נוכח בסמוך דגם הוא ס\"ל דיכול להקדים עד קרוב לחצי שעה מקודם ובפרט אם נסבור בדעת הרמב\"ם במה שכתב דמדליקין עם שקיעתה היינו ממש עם הזמן שנתכסה השמש מעינינו וידוע שדעתו דמצות הדלקה הוא רק כחצי שעה או מעט יותר אח\"כ ואם עבר הזמן שוב לא ידליק עוד א\"כ אם ידליק בשעת צה\"כ אינו יוצא כלל מצות הדלקה לדעת הרמב\"ם והעומדים בשיטתו בזמן השקיעה. ואפילו המקילים שיכול להדליק אח\"כ הוא ג\"כ רק מטעם ספק לכמה פוסקים וע\"כ נראה דטוב ונכון לכתחלה להדליק קודם מעריב ועיין בשע\"ת שכתב בשם מח\"ב ג\"כ שמי שעושה כן לא הפסיד ולפי מה שהוכחנו יש לנהוג כן לכתחלה.","\u0003 ולא מקדימים\u0004 - הוא מלשון הרמב\"ם עיין בר\"ן ורשב\"א דפליגי ע\"ז [הגר\"א] והנה מקור הרמב\"ם כתב הרה\"מ שהוא ממה דאיתא בשבת כ\"ג ע\"ב ובלבד שלא יקדים ולא יאחר ויפרש לה דאיירי בחנוכה ולפ\"ז לרוב הפוסקים דמפרשי לה דאנר של שבת קאי [הר\"ח ורש\"י ותוספות והרא\"ש ורבינו יונה והמרדכי בריש פ' תפלת השחר] תו אין לנו מקור לדינו של הרמב\"ם וגם הטור בסימן רס\"ג נסיב לה לענין שבת וקצת פלא על השו\"ע דסתם בסימן רס\"ג ס\"ד לענין שבת וגם בענינינו לענין חנוכה ואולי דבענינינו סובר הטור ואפשר גם להרמב\"ם שהוא מצד הסברא שאינו ניכר לפרסומי ניסא כשמקדים דשרגא בטיהרא מאי מהני אבל קשה דהתינח אם מפרש משתשקע החמה כפשטיה נוכל לומר שקודם שקיעה שאור היום גדול לא מינכר אור הנר וליכא פרסומי ניסא אבל כיון שהעתיק השו\"ע כפירושו של הטור והמרדכי דהיינו מסוף שקיעה והוא צאת הכוכבים בודאי כשמקדים קצת כערך רבע שעה והוא זמן בין השמשות [אפילו לדעת ר\"ת וסייעתו] או מעט יותר איכא היכר שהוא ללילה ותדע בשבת ג\"כ פסק השו\"ע שם שלא יקדים מטעם שאינו היכר שמדליקו לכבוד שבת ואפ\"ה ידוע שמוכרח לכו\"ע להדליקו קודם ביה\"ש הנ\"ל וע\"כ אנו צריכין לומר דמה שאמרו ובלבד שלא יקדים היינו דוקא שמדליקו בעוד היום גדול שאז אינו מינכר שהוא לכבוד שבת וכן בענינינו שהוא לשם חנוכה וכן מוכח לשון השו\"ע שם עי\"ש אבל לא כשמדליקו רבע שעה או אפילו חצי שעה לערך קודם צה\"כ. והנה הטור כשהעתיק מסוף שקיעה לא העתיק ובלבד שלא יקדים והרמב\"ם שהעתיק ובלבד שלא יקדים לא העתיק מסוף שקיעה אלא כתב שמדליקין עם השקיעה [וז\"ל בפ\"ד מה' חנוכה הלכה ה' אין מדליקין נרות חנוכה קודם שתשקע החמה אלא עם שקיעתה לא מאחרין ולא מקדימין] וכונתו ממש קודם השקיעה [וכענין שאמרו בשבת ל\"ג ג' דברים צריך אדם לומר ע\"ש עם חשיכה וכו' הדליקו את הנר הרי דלשון עם היינו זמן מה קודם] ואפילו אם נפרש דהרמב\"ם סובר כר\"ת וסייעתו דהיינו השקיעה השנייה ג\"כ אנו מוכרחין לומר דזמן של בין השמשות ומעט יותר כעשרה מינוט מקודם דהוא בס\"ה לערך כ\"ה מינוט קודם צה\"כ אינו בכלל ובלבד שלא יקדים והראיה משבת וכ\"ש לפי מה שביררנו לעיל בסימן רס\"א מכמה פוסקים דהרמב\"ם סובר דצריך להדליק נרות בע\"ש קודם שנתכסה השמש מעינינו [ואינו סובר כר\"ת דשני שקיעות הן] והוא הנקרא שקיעה א\"כ בודאי כשמדליק אפי' קודם שקיעה ג\"כ אינו בכלל שלא יקדים אך שלא יקדים הרבה קודם שקיעה דזהו מה שאמרו ובלבד שלא יקדים. היוצא מדברינו דהמחבר שהעתיק כטור מסוף שקיעה וצירף לזה דברי הרמב\"ם שלא יקדים הוא צע\"ג.\nואגב דאיירינן בהאי ענינא אכתוב מה דקשה לי בדברי הב\"י שכתב ודברי הרמב\"ם כדברי בה\"ג שכתב אין מדליקין נרות קודם שתשקע החמה אלא עם שקיעתה לא מאחרין ולא מקדימין עכ\"ל וקשה הלא הר\"ן מקשה על דברי בה\"ג ממה דקי\"ל לענין שבת דאחר שקיעה אסור להדליק ושם נמי תניא משתשקע וע\"כ דבענינינו ג\"כ אם רצה להדליק מקודם מדליק ותירץ דבה\"ג יסבור כרב יוסף ושם נמי מותר אחר שקיעה ע\"ש ולפ\"ז מה יענה להרמב\"ם דפוסק כרבה כמו שכתב הרה\"מ בפ\"ה מהלכות שבת וע\"כ אנו צריכין לומר כמו שכתבנו מקודם דעם שקיעתה היינו זמן מה קודם ג\"כ נכלל בעם שקיעתה ודומיא מה דאיתא בשבת ג' דברים צריך לומר ע\"ש עם חשיכה וכו' הדליקו נר ומה שכתב אין מדליקין נרות קודם שתשקע החמה היינו זמן הרבה קודם.","\u0003 ובלבד שיתן בה שמן עד שתכלה וכו'\u0004 - לכמה פוסקים הוא כחצי שעה אחר צאת הכוכבים שהוא בס\"ה שעה וג' רבע שעה מזמן הדלקה ואסור להשתמש לאורה כל אותו הזמן (אף שהדליקה בעוד היום גדול) ואם כבתה בחול קודם צאת הכוכבים צריך לחזור ולהדליק אבל לא יברך דע\"פ הדחק אמרינן דמפלג המנחה ולמעלה כבר הותחל המצוה [פמ\"ג].","\u0003 כזה השיעור\u0004 - ומי שאין לו שמן כשיעור הזה ידליק בלא ברכה [פמ\"ג] ושעוה מעובדי עבודת גלולים אין ליקח וכדלעיל בסימן קנ\"ד במ\"ב סקמ\"ה.","\u0003 ומכל מקום טוב ליזהר גם בזה\"ז\u0004 - שאע\"פ שמדליקין בפנים כיון שמדליקין בפתח הבית והוא פתוח יש הכירא לעוברים ושבים [טור]."],"\u0010g0\u0011 אֵין מַדְלִיקִין נֵר חֲנֻכָּה קֹדֶם שֶׁתִּשְׁקַע הַחַמָּה, אֶלָּא \u0010y0\u0011 עִם \u0010t0\u0011 \u0010m0\u0011 סוֹף שְׁקִיעָתָהּ, \u0010c0\u0011 לֹא מְאַחֲרִים \u0010c1\u0011 וְלֹא מַקְדִּימִים. \u0010c2\u0011 \u0010g1\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר \u0010y1\u0011 שֶׁאִם הוּא טָרוּד יָכוֹל לְהַדְלִיק \u0010y2\u0011 מִפְּלַג הַמִּנְחָה וּלְמַעְלָה, \u0010g2\u0011 וּבִלְבַד \u0010y3\u0011 שֶׁיִּתֵּן בָּהּ שֶׁמֶן \u0010c3\u0011 עַד \u0010t1\u0011 \u0010s0\u0011 שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק. \u0010g3\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011\nשָׁכַח אוֹ הֵזִיד וְלֹא הִדְלִיק עִם שְׁקִיעַת הַחַמָּה, מַדְלִיק וְהוֹלֵךְ עַד שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק, שֶׁהוּא כְּמוֹ חֲצִי שָׁעָה שֶׁאָז הָעָם עוֹבְרִים וְשָׁבִים וְאִכָּא פִּרְסוּמֵי \u0010y4\u0011 \u0010m1\u0011 נִסָא; הִלְכָּךְ צָרִיךְ לִתֵּן בָּהּ שֶׁמֶן \u0010m2\u0011 כְּזֶה \u0010y5\u0011 \u0010c4\u0011 \u0010g4\u0011 הַשִּׁעוּר, וְאִם נָתַן בָּהּ יוֹתֵר \u0010y6\u0011 \u0010m3\u0011 יָכוֹל \u0010t2\u0011 לְכַבּוֹתָהּ לְאַחַר שֶׁעָבַר זֶה הַזְּמַן, וְכֵן יָכוֹל \u0010y7\u0011 לְהִשְׁתַּמֵּשׁ לְאוֹרָהּ לְאַחַר זֶה הַזְּמַן. \u0005 הַגָּה: יֵשׁ אוֹמְרִים \u0010y8\u0011 שֶׁבַּזְּמַן הַזֶּה שֶׁמַּדְלִיקִין בִּפְנִים \u0010y9\u0011 \u0010m4\u0011 אֵינוֹ צָרִיךְ לִזָּהֵר לְהַדְלִיק קֹדֶם שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק \u0006 \u0005(דִּבְרֵי עַצְמוֹ וְטוּר בְּשֵׁם תּוֹסָפוֹת)\u0006, \u0005 וּמִכָּל מָקוֹם טוֹב \u0010c5\u0011 לִזָּהֵר גַּם בַּזְּמַן הַזֶּה; \u0010g5\u0011 \u0006 וּמִיהוּ הָנֵי מִלֵּי לְכַתְּחִלָּה, אֲבָל אִם עָבַר זֶה הַזְּמַן וְלֹא הִדְלִיק, מַדְלִיק וְהוֹלֵךְ \u0010y10\u0011 \u0010t3\u0011 \u0010m5\u0011 כָּל הַלַּיְלָה; \u0010g6\u0011 וְאִם \u0010t4\u0011 עָבַר כָּל הַלַּיְלָה וְלֹא הִדְלִיק, אֵין לוֹ תַּשְׁלוּמִין. \u0005 הַגָּה: וּבַלֵּילוֹת הָאֲחֵרוֹת יַדְלִיק \u0010y11\u0011 כְּמוֹ שְׁאָר בְּנֵי אָדָם, אַף עַל פִּי שֶׁלֹּא הִדְלִיק בָּרִאשׁוֹנָה \u0006 \u0005(מָצָא כָּתוּב בְּשֵׁם מַהֲרִי\"ל וַאֲגֻדָּה וְדִבְרֵי עַצְמוֹ)\u0006. \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011",{"g":["לשון הרמב\"ם בפ\"ד מברייתא שבת כ\"א","בשם מהר\"י אבוהב","שם בגמרא לתירוצא בתרא","שם בגמרא לתירוצא קמא","כן פי' הרי\"ף ורא\"ש שם לתירוצא בתרא א\"נ לשיעורא","תוספות שם בשם הר\"י פורת וכן משמע מדברי רא\"ש","טור ושכ\"כ ר' יצחק בר יהודה וכן כת' המרדכי שם"],"t":["\u0003סוף. \u0004 היינו צ\"ה. ב\"ח מ\"א:","\u0003שתכלה. \u0004 כתב שכנה\"ג שכל יחיד ידליק אחר תפילת ערבית ומיד כשמתחיל זמנו לא יאכל ולא ילמוד עד שידליק ואם התחיל פוסק וכ\"כ בתשובת שבות יעקב חלק ב' סי' מ' ע\"ש: \u0003וכתב\u0004 המ\"א מי שלא התפלל מעריב מדליק קודם דא\"צ זמן כ\"כ למיחש שמא ישכח מעריב וכ\"כ הכנה\"ג שנהג כן:","\u0003לכבותה. \u0004 והב\"ח כתב שלא לכבותה ואף אם נכבה מעצמה אסור להנות מהם אף שדלק חצי שעה כיון שהוקצה למצוה. כתב בליקוטי מהרי\"ו אין לטלטל הנרות ממקומן עד שדלקו חצי שעה:","\u0003כל\u0004 \u0003הלילה. \u0004 בב\"י כתב דהוי ספיקא דדינא וא\"כ משמע שאין לברך אבל מדסתם בש\"ע משמע דעתו שיברך ורש\"ל כ' דוקא עד חצות וא\"כ אחר חצות אין לברך ובהגמ\"נ כתב כל זמן שבני הבית נעורים אפי' עד עמוד השחר. וכן נ\"ל להורות אבל אם ישנים אין לברך עליהם. מ\"א:","\u0003עבר. \u0004 ומי שלא הדליק מנין הנרות של אותה הלילה ישלים וא\"צ לברך פעם אחרת. ד\"מ:"],"s":["\u0003שתכלה. \u0004 עבה\"ט שכ' בשם שכנה\"ג כו' להדליק אחר מעריב וכ\"כ בשבו\"י אח\"כ הביא דברי המג\"א ובשם כנה\"ג והמעיין בשבו\"י יראה שדברי הבה\"ט הם מהופכים ששם הביא דברי המג\"א וכ' ע\"ז אכן בשכנה\"ג כ' ובבחרותי כו' חזרתי כמנהגי להדליק אחר תפלת ערבית וכן עיקר לדינא דודאי תדיר קודם היכי דמצי למעבד תרווייהו כמ\"ש התו' בשבת דף ך\"ג ע\"ש ועיין לקמן סימן תרפ\"ד במג\"א ובפר\"ח שם ומ\"ש ביד אפרים שם עיין באשל אברהם כאן בשם השב יעקב בזה וע' מח\"ב שהרא' מקום לד' שיטות למהרי\"ש בסופו סי' ב' וסיים מח\"ב שנראה שהמדליק קודם שילך להתפלל ערבית לא הפסיד שיש לחוש שעד שיתפלל ערבית יעבור זמן הדלקתו שהוא חצי שעה מדינא דגמרא עיין שם:"],"m":["\u0003סוף שקיעתה\u0004. היינו צ\"ה כמ\"ש סי' תקס\"ב (ב\"ח): במ\"ס פ\"כ, מצות הדלקתו משתשקע החמה ואם הדליקו ביום אין נאותין ממנו ואין מברכין עליו שכך אמרו אין מברכין על הנר עד שיאותו לאורו עכ\"ל:","\u0003הלכך צריך ליתן וכו'\u0004. משמע דאם הדליק זמן מה אחר שקיעת החמה א\"צ ליתן שמן כ\"כ רק עד שתכלה רגל מן השוק ובאגוד' כ' במיימוני משמע שיהי' דולק יותר ממיל עכ\"ל:","\u0003כזה השיעור\u0004. ואף עכשיו צריך ליתן בה כשיעור הזה ודלא כיש מקילין בזה [ד\"מ רש\"ל בתשוב'] אבל אין מצוה בנרות ארוכות דהא לאחר שדלקו כשיעור הזה מותר להשתמש בהן ואין שייך הידור מצוה אלא בשעת מצוה ואין ראיה מנרות חנוכה של ב\"ה דהתם איכא מצוה להדליק נרות בכל יום כנ\"ל עכ\"ל ד\"מ ונ\"ל דודאי בנר של שמן אין הידור מצו' בין רב למעט אבל בנרות שעוה כשהם ארוכי' הם נאים יותר כמו בנרות י\"ה ולולב ואתרוג וכיוצא בו וכמדומה לי שכ\"כ בכל בו: בש\"ג למד השיעור לשמן על חצי שעה ממה דאמרינן חצי לוג שמן למנור' ללילי טבת הארוכים ע\"ש ובאמת הכל לפי עובי הפתילה:","\u0003יכול לכבותה\u0004. ורש\"ל כת' דאין להשתמש לאור' אבל לכבות' שרי וב\"ח כ' מאחר דנהגו איסור לכבות ולהשתמש אין להקל וכ\"כ צדה לדרך עכ\"ל:","\u0003א\"צ ליזהר\u0004. וידליק כשהוא לילה, ובני ביתו מקובצים יחד (מ\"צ) וטוב להדליק קודם אכילה (מנהגים) ורש\"ל כתב דאפי' ללמוד אסור משהגיע זמנ' ואפי' התחיל פוסק כמ\"ש סימן תל\"א ס\"ב וכ\"פ ב\"ח ונ\"ל דמי שלא התפלל מעריב מדליק קודם דא\"צ זמן כ\"כ וליכא למיחש שמא ישכח מעריב וכ\"כ בכ\"ה שהוא נוהג כן:","\u0003כל הלילה\u0004. בב\"י כתוב דהוי ספיקא דדינא ואם כן משמע שאין לברך אבל מדסתם בש\"ע משמע דעתו שיברך ורש\"ל כתב דוקא עד חצות וא\"כ אחר חצות אין לברך ובהג\"מ כתב כל זמן שבני הבית נעורים אפי' עד עמוד השחר עכ\"ל וכן נ\"ל להורות אבל אם ישנים אין לברך עליהם:"],"r":["\u0003ס\"א אין מדליקין כו' לא כו' ולא כו'. \u0004לשון הרמב\"ם לבד תיבת סוף שהוסיף המחבר מדברי הטור כמ\"ש למטה. וכ\"נ דעת בה\"ג ורשב\"א ור\"ן כתבו שמותר להקדים וע\"ש יוכיח וע\"ש ושם בארוכה:","\u0003סוף שקיעה. \u0004כ\"כ הטור וכ\"כ הרא\"ש בפ\"א דתענית על מש\"ש כל תענית שלא שקעה כו' וכמ\"ש בברכות ואגב אורחא קמ\"ל כהנים אימת כו' כדתניא ובא השמש וטהר ביאת שמשו כו'. אבל ברשב\"א ור\"ן משמע בהדיא שהוא תחילת השקיעה אלא דמשמע שם בשקיעה שניה עש\"ו. וע' במרדכי ספ\"ב דשבת שכ' דלשון משתשקע מוכח שהוא תחלת השקיעה כמ\"ש בפ' הפועלים משיפקסו עד שיפקסו כו' וכן עיקר ועמש\"ל בסי' רס\"א ס\"ב בארוכה:","\u0003ויש מי. \u0004א\"ח. וראיה מהבדלה:","\u0003ס\"ב חצי שעה. \u0004רי\"ף:","\u0003הלכך. \u0004שם לשיעורה:","\u0003וכן יכול. \u0004שם בפירוש הרי\"ף:","\u0003ומיהו ה\"מ כו'. \u0004כיון דאיכא תירוץ אחר בגמרא. תוס' שם:","\u0003ואם עבר כו'. \u0004כמ\"ש בפ\"ב דסוכה ועוד אר\"א מי שלא כו' וחכ\"א אין כו':","\u0003ובלילות האחרות. \u0004כמ\"ש עושין סוכה בחש\"מ כו' וכן כאן דכל לילה נס בפני עצמה כמ\"ש שם ניסא בכל יומא איתא ול\"ד לספירה דכתי' תמימות:"]}],["\u0010y0\u0011 כָּל הַשְּׁמָנִים וְהַפְּתִילוֹת \u0010y1\u0011 כְּשֵׁרִים \u0010y2\u0011 לְנֵר חֲנֻכָּה, וְאַף עַל פִּי שֶׁאֵין הַשְּׁמָנִים נִמְשָׁכִים אַחַר הַפְּתִילָה וְאֵין הָאוּר נִתְלֶה יָפֶה בְּאוֹתָם הַפְּתִילוֹת. \u0005 הַגָּה: וּמִיהוּ שֶׁמֶן זַיִת מִצְוָה מִן הַמֻּבְחָר \u0006 \u0005(מָרְדְּכַי וְכָל בּוֹ וּמַהֲרִי\"ל)\u0006, \u0005 וְאִם אֵין שֶׁמֶן זַיִת מָצוּי מִצְוָה בִּשְׁמָנִים שֶׁאוֹרָן זַךְ וְנָקִי; וְנוֹהֲגִים בִּמְדִינוֹת אֵלּוּ לְהַדְלִיק בְּנֵרוֹת שֶׁל \u0010y3\u0011 שַׁעֲוָה, כִּי אוֹרוֹ צָלוּל כְּמוֹ שֶׁמֶן. \u0010y4\u0011 \u0006 וַאֲפִלּוּ בְּלֵיל שַׁבָּת שֶׁבְּתוֹךְ יְמֵי חֲנֻכָּה מֻתָּר לְהַדְלִיק בְּנֵר חֲנֻכָּה הַשְּׁמָנִים וְהַפְּתִילוֹת שֶּׁאָסוּר לְהַדְלִיק בָּהֶם נֵר שַׁבָּת, \u0005 הַגָּה: \u0010y5\u0011 אִם אֵינוֹ נוֹתֵן בַּנֵּר רַק כְּדֵי שִׁעוּר מִצְוָתוֹ, \u0006 \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סי' ק\"ע)\u0006, \u0010y6\u0011 לְפִי שֶׁאָסוּר לְהִשְׁתַּמֵּשׁ \u0010y7\u0011 בְּנֵר \u0010y8\u0011 חֲנֻכָּה בֵּין בְּשַׁבָּת בֵּין \u0010y9\u0011 בַּחֹל, וַאֲפִלּוּ לִבְדֹּק מָעוֹת אוֹ לִמְנוֹתָן לְאוֹרָהּ \u0010y10\u0011 אָסוּר, \u0010y11\u0011 וַאֲפִלּוּ תַּשְׁמִישׁ שֶׁל קְדֻשָּׁה, כְּגוֹן לִלְמֹד לְאוֹרָהּ, \u0010y12\u0011 אָסוּר; וְיֵשׁ מִי שֶׁמַּתִּיר בְּתַשְׁמִישׁ \u0010c0\u0011 שֶׁל \u0010y13\u0011 קְדֻשָּׁה; וְנוֹהֲגִים לְהַדְלִיק נֵר נוֹסָף, כְּדֵי \u0010y14\u0011 שֶׁאִם יִשְׁתַּמֵּשׁ \u0010c1\u0011 לְאוֹרָהּ יִהְיֶה לְאוֹר הַנּוֹסָף \u0010c2\u0011 שֶׁהוּא אוֹתוֹ שֶׁהֻדְלַק אַחֲרוֹן, \u0010y15\u0011 וְיַנִּיחֶנּוּ מֵרָחוֹק קְצָת מִשְּׁאָר נֵרוֹת מִצְוָה. \u0005 הַגָּה: וּבִמְדִינוֹת אֵלּוּ אֵין נוֹהֲגִים לְהוֹסִיף, רַק \u0010y16\u0011 מַנִּיחַ אֶצְלָן \u0010y17\u0011 \u0006 \u0005 הַשַּׁמָּשׁ שֶׁבָּהֶן מַדְלִיק הַנֵּרוֹת, וְהוּא \u0010y18\u0011 עָדִיף טְפֵי, וְיֵשׁ לַעֲשׂוֹתוֹ \u0010y19\u0011 יוֹתֵר \u0006 \u0005 אָרֹךְ מִשְּׁאָר נֵרוֹת, שֶׁאִם בָּא לְהִשְׁתַּמֵּשׁ \u0006 \u0005 יִשְׁתַּמֵּשׁ לְאוֹתוֹ נֵר \u0006 \u0005(מָרְדְּכַי)\u0006. \u0010y20\u0011 \u0005 אִם נִתְעָרֵב נֵר חֲנֻכָּה הָאָסוּר \u0006 \u0005 בַּהֲנָאָה בִּשְׁאָר נֵרוֹת, אֲפִלּוּ אֶחָד בְּאֶלֶף, לֹא בָּטִיל \u0010y21\u0011 דְּהָוֵי דָּבָר \u0006 \u0005 שֶׁל מִנְיָן \u0006 \u0005(ת\"ה סי' ק\"ג)\u0006, \u0005 אֶלָּא יַדְלִיק מִן הַתַּעֲרוֹבוֹת \u0010y22\u0011 \u0006 \u0005 כָּל כָּךְ שֶׁבְּוַדַּאי נֵר שֶׁל הֶתֵּר דּוֹלֵק עִם נֵר שֶׁל אִסּוּר, וְאָז \u0010y23\u0011 \u0010c3\u0011 מֻתָּר לְהִשְׁתַּמֵּשׁ אֶצְלָן \u0010y24\u0011 \u0006 \u0005(דִּבְרֵי עַצְמוֹ)\u0006.\nהַדְלָקָה עוֹשָׂה מִצְוָה. \u0010c4\u0011 לְפִיכָךְ אִם כָּבְתָה \u0010c5\u0011 קֹדֶם שֶׁעָבַר זְמַנָּהּ אֵינוֹ זָקוּק לָהּ, וַאֲפִלּוּ כָּבְתָה בְּעֶרֶב שַׁבָּת קֹדֶם קַבָּלַת שַׁבָּת \u0010y25\u0011 שֶׁעֲדַיִן הוּא מִבְּעוֹד יוֹם, אֵינוֹ זָקוּק לָהּ. וְכֵן אִם לְאַחַר שֶׁהִדְלִיקָהּ בָּא לְתַקְּנָהּ וְכִבָּה אוֹתָהּ בְּשׁוֹגֵג, אֵינוֹ זָקוּק לָהּ. \u0005 הַגָּה: \u0010y26\u0011 וְאִם רוֹצֶה \u0006 \u0005 לְהַחְמִיר עַל עַצְמוֹ וְלַחֲזֹר וּלְהַדְלִיקָהּ, אֵין לְבָרֵךְ עָלֶיהָ \u0006 \u0005(רַשְׁבָּ\"א סִימָן תקל\"ט וְרַ\"ן)\u0006.\nנֵר שֶׁל \u0010y27\u0011 חֶרֶס שֶׁהִדְלִיק בּוֹ לַיְלָה אַחַת נַעֲשָׂה יָשָׁן וְאֵין מַדְלִיקִין בּוֹ לַיְלָה \u0010y28\u0011 אַחֶרֶת, אֶלָּא לוֹקֵחַ חֲדָשִׁים בְּכָל לַיְלָה; וְאִם אֵין לוֹ אֶלָּא יָשָׁן, מַסִיקוֹ בְּכָל לַיְלָה בָּאוּר; וְנֵר שֶׁל מַתֶּכֶת אֵינוֹ צָרִיךְ חָדָשׁ. וְשֶׁל זְכוּכִית אוֹ שֶׁל חֶרֶס \u0010y29\u0011 מְכֻסֶה, דִּינוֹ כְּמַתֶּכֶת.\nאֵין חוֹשְׁשִׁין לַפְּתִילוֹת לְהַחְלִיפָם, \u0010y30\u0011 עַד שֶׁתִּכְלֶה.",["\u0003כל השמנים והפתילות וכו'\u0004 היינו כי יש שמנים גרועים שאין נמשכין אחר הפתילה וכן יש פתילות גרועים שאין האור נתלה יפה בהן וכדלעיל בסימן רס\"ד ובשבת אסור להדליקן וס\"ד דבחנוכה אסור ג\"כ להדליקן שמא יבואו לידי כיבוי קמ\"ל דאין לחוש לזה דקי\"ל כבתה אין זקוק לה דכיון שהדליק נעשה זכר לנס ונגמרה המצוה:","\u0003כשרים לנר חנוכה\u0004 ומ\"מ מצוה מן המובחר ליקח לפתילה צמר גפן או חוטי פשתן [ח\"א]. שומן או חלב הנאסר מבב\"ח אסור להדליק ממנו נר חנוכה וג\"כ אסור לבטולי בששים להדליק ממנו [פמ\"ג]. הנוהגין להדליק ביום ראשון א' ומכאן ואילך מוסיף והולך צריך שיהיה הנוסף דומה לנר העיקר אבל אותם שעושים נר לכל אחד מבני הבית יכול האחד להדליק נר של שמן והשני של שעוה. שמן הגזול צ\"ע אי כשר לנר חנוכה [תשו' שואל ומשיב ח\"א מהדורא תליתאה סי' שמ\"ט]:","\u0003לנר חנוכה\u0004 אבל לא להשמש [מ\"א] ור\"ל דבשבת חנוכה אסור לעשות השמש מהשמנים ופתילות שאין מדליקין בהם בשבת דכיון דמותר לעשות איזה תשמיש נגד השמש א\"כ חיישינן שמא יטה. אם נמצא עכבר בשמן מאוס הוא ואסור לנר חנוכה:","\u0003שעוה\u0004 ומ\"מ מצוה בשל שמן טפי מנרות של שעוה דע\"י השמן נעשה הנס:","\u0003ואפילו בליל שבת שבתוך וכו'\u0004 ר\"ל דס\"ד דניחוש בזה כמו בעלמא בנר של שבת שמא לא תדלק יפה ויטה הנר להביא השמן לפי הפתילה קמ\"ל דכאן אין לחוש לזה דהא אסור להשתמש לאורה א\"כ לא איכפת ליה במה שלא תדלק יפה:","\u0003אם אינו נותן וכו' מצותו\u0004 דאם יתן יותר יש חשש שמא יטה אותו נר חנוכה להשתמש בו אחר השיעור של הדלקה שאז מותר ליהנות ממנו כדלעיל בסימן תרע\"ב ס\"ב:","\u0003לפי שאסור להשתמש וכו'\u0004 היינו אפילו אותן שמוסיפין המהדרין בכל לילה ג\"כ אסור להשתמש לאורן:","\u0003בנר חנוכה\u0004 כדי שיהא ניכר שהוא נר מצוה לפרסם הנס ועוד כיון שע\"י נס שנעשה במנורה. תקנוה עשאוה כמנורה שאין משתמשין בה כלל:","\u0003בין בשבת\u0004 היינו דאפילו לאכול אצלן דהוא סעודת מצוה ג\"כ אסור:","\u0003ואפילו לבדוק וכו'\u0004 שהוא תשמיש עראי ג\"כ אסור ועיין במ\"א וט\"ז שהסכימו דאפילו למנותן מרחוק שאין ידיו סמוכות לנר ג\"כ אסור:","\u0003אסור\u0004 כדי שלא יהא מצות בזויות עליו ודוקא בזה שהוא עכ\"פ תשמיש עראי אבל כל שאינו משמש כלום רשאי לישב בביתו בשעה שנר חנוכה דולקת:","\u0003אפילו תשמיש של קדושה וכו'\u0004 מדברי הט\"ז מוכח דלדעה ראשונה אסור אפילו בלימוד דרך עראי דאלו בדרך קבע אפילו לדעה שניה אסור ועיין בבה\"ל מה שכתבנו בזה:","\u0003אסור\u0004 וכן בנרות בהכ\"נ אין משתמשין לאורן אף תשמישי קדושה כמו בבית דהיינו אם ירצה להתפלל מעריב אצלם כ\"ז שלא דלקו חצי שעה אסור:","\u0003ונוהגין להדליק נר נוסף\u0004 פי' מלבד הנר שמניחין על השולחן דחוששין כיון שמדליקין בפנים אולי ישתמשו בנרות של חנוכה ולאו אדעתייהו אבל מעיקר הדין כיון שיש לו נר על שולחנו א\"צ להדליק נר נוסף:","\u0003שאם ישתמש וכו'\u0004 ועיין מ\"א שלכתחלה אין להשתמש אצל כולן יחד כ\"א לאור הנוסף [או להשמש] בלבד כשהוא אחד בפני עצמו דהרואה יאמר לצרכו הדליק כולן דלפעמים אדם מדליק כמה נרות ועיין בה\"ל:","\u0003ויניחנו מרחוק וכו'\u0004 כדי שיהיה היכר כמה נרות מדליקין באותו יום ולא יחשבוהו עמהם:","\u0003מניח אצלן וכו'\u0004 וטוב שלבד זה יניח נר על השלחן:","\u0003השמש שבו וכו'\u0004 ואפילו רבים המדליקין כיון שכל אחד מניח נרותיו במקום מיוחד כנ\"ל בסימן תרע\"א ס\"ב בהג\"ה צריך להניח שמש אצל כל אחד ואחד אפילו יש נר על השולחן דשמא ישתמש אצל הנרות:","\u0003עדיף טפי\u0004 דבזה מוכח בהדיא לבני הבית שאינו ממנין הנרות:","\u0003יותר ארוך וכו' שאם בא להשתמש וכו'\u0004 ר\"ל דכיון שהוא גדול עיקר תשמישו ממנו וה\"ה אם מעמידו גבוה קצת משאר הנרות שפיר דמי:","\u0003אם נתערב וכו'\u0004 ר\"ל לאחר שהודלק שנעשה בו מעשה נתערב [דמקודם לכן לא נאסר דהזמנה לנר חנוכה לאו מילתא היא] ואח\"כ כבה בתוך זמן שיעורו ופסק בתה\"ד דלא בטל אפילו באלף דהיינו ליטול אחת מתוכן להדליקו ולהשתמש בו וה\"ה בעודן דולקין לא יטול אחד מתוכן להשתמש בו לאורו והכל מטעם דהוא דבר של מנין ור\"ל דאפילו במקום שרגילין למכור הנרות במשקל מ\"מ נרות של מצוה הכל מונין אותן בכל לילה ודבר שבמנין חשוב הוא ולא בטיל:","\u0003דהוי דבר של מנין\u0004 ורש\"ל חולק ופוסק דחד בתרי בטל. ועיין בט\"ז שכתב דאפילו להרמ\"א דוקא כשנתערב בתוך ימי חנוכה דחשובין הן דהן ראויין למצוה ביום המחרת אבל אם נתערב ביום השמיני וכ\"ש לאחר מכן כבר בטל חשיבותו ודינו לכו\"ע כיבש ביבש ובטל ברוב:","\u0003כל כך שבודאי וכו'\u0004 פי' אם נתערב נר חנוכה א' מדליק ב' ואם נתערב ב' או ג' ידליק אחד יותר כדי שימצא בו נר של היתר ג\"כ:","\u0003מותר להשתמש אצלן\u0004 דהא הדלקת השמש הוא כדי שישתמש לאורן ש\"מ דאם הם ביחד מותר לשמש אצלן ויש מן הפוסקים דס\"ל דדוקא שמש שעומד למעלה מכל הנרות שרי דאז עיקר תשמישו לאור השמש משא\"כ בזה שמשתמש לאור כולן הרי מתהנה ג\"כ מנר חנוכה והנה במ\"א ופר\"ח הסכימו דהדין עם הרמ\"א אמנם הגר\"א לעיל בסימן רס\"ד האריך בזה ומשמע דלדבריו אין הדין הזה מוכרע וכן במור וקציעה משמע דלמעשה יש להחמיר בדין זה:","\u0003הדלקה עושה מצוה וכו'\u0004 ר\"ל כיון שהדליק תיכף קיים המצוה לפיכך אם כבתה אין זקוק לה ואם הדליקה במקום הרוח וכבתה זקוק לה לחזור ולהדליקה במקום שאין הרוח מצוי דזה הוי כאלו לא נתן בה שמן כשיעור ומ\"מ לא יברך עליה [אחרונים] ופשוט דאם הוא רואה שהאור אין נאחז בהפתילה ובודאי יכבה במהרה שאינו יוצא בהדלקה זו וצריך מדינא לחזור ולהדליקה לאחר הכביה:","\u0003שעדיין הוא מבעוד יום\u0004 הטעם כיון שבע\"ש מחוייב להדליק קודם שקיעה וגם כבר בירך עליה להדליק נר של חנוכה כבר הותחלה המצוה בהכשר ועיין בט\"ז שחולק ע\"ז ודעתו דקודם קבלת שבת שיש עדיין היתר להדליק מחוייב לחזור ולהדליק ובלי ברכה:","\u0003ואם רוצה להחמיר וכו'\u0004 והאחרונים כתבו דראוי להחמיר לחזור ולהדליקה בכל ענין ובפרט אם נכבה בע\"ש קודם קבלת שבת. ואם הוא קיבל בעצמו שבת ואח\"כ כבה ויש עדיין זמן היתר מותר לומר לחבירו שידליקם [פמ\"ג]. ומצוה מן המובחר לקנות שעוה לנר חנוכה מן מה שנוטף מן הנרות בביהכ\"נ מאחר דאיתעביד בהו חדא מצוה ליתעביד בהו מצוה אחריתא:","\u0003חרס\u0004 כתבו הספרים שטוב כל אחד שיטריח לעשות לו מנורה יפה לפי כחו וכן הנרות יעשה יפה:","\u0003אחרת\u0004 שהוא מאוס וביזוי מצוה:","\u0003מכוסה\u0004 היינו מצופה באבר:","\u0003עד שתכלה\u0004 שאין בהם בזיון מצוה דאדרבה הם נוחין להדליק יותר כשהם מודלקין כבר:"],["\u0003 ויש מי שמתיר בתשמיש של קדושה\u0004 - עיין בט\"ז שהאריך והעלה דאף לדעה זו היינו דרך ארעי דוקא אבל לימוד דרך קבע לכו\"ע אסור ועיין בא\"ר ובחמד משה שחולקים עליו ודעתם דלדעה זו אף דרך קבע מותר [וקושיותיו תירצו האחרונים עיין ביד אפרים ובמאמר מרדכי ובח\"מ] וא\"כ אפשר לומר דדעה הראשונה האוסרת הוא דוקא אם הלימוד היה בדרך קבע אבל לא בדרך ארעי ומה שהביא המגן אברהם בסק\"ב ראיה ממה שכתבו הפוסקים דאפילו לאכול אצלן אסור כבר כתב הח\"מ דאין ראיה זו מכרחת דאולי אכילת קבע אמרו ומה שכתב עוד וכן מוכח סימן תרע\"ח גם מהתם אין ראיה דאכילת שבת ודאי קבע הוא ולא ארעי. והנה באמת הלא ידוע דעת הרא\"ש דתשמישי ארעי שרי (ורק בענין הרצאת מעות כשמקרב ידיו אצל נר חנוכה אז אסור משום דהוי גנאי להן אבל בעלמא שרי ומה שהקשה הט\"ז עיין בח\"מ) ורש\"ל פסק ג\"כ הכי וע\"כ לענ\"ד בענינינו דמספקינן לענין לימוד דרך ארעי אין להביא ראיה להחמיר ממה שהביא המגן אברהם בסק\"ג ד\"ה ואפילו תשמיש וכו' וכ\"פ רש\"ל דהלא רש\"ל כתב בהדיא דדוקא הרצאת מעות מאחר שמקרב ידיו אל הנר אבל שאר תשמישי ארעי שרי עכ\"ל וע\"כ לענ\"ד אפילו אם נפסוק להלכה כמסקנת המגן אברהם בסק\"ב דבתשמישי ארעי אפילו כשאין ידיו סמוכות לנר אסור ושלא כדעת ב\"י וד\"מ ורש\"ל שהעתיקו דבריו להלכה כשנצרף לזה ג\"כ כשהוא תשמישי קדושה ובדרך ארעי כגון ללמוד לפניהן דרך ארעי אפשר דלכו\"ע אין להחמיר וצ\"ע. ודע עוד דאפילו ללמוד בדרך קבע אפשר דאין להחמיר רק בכדי שיעור המבואר לעיל סימן תרע\"ב סעיף ב' אבל לא בתר זה והיינו אפילו אם נרצה להחמיר שם שלא כדעת המחבר הוא רק לדבר הרשות אבל לא לדבר מצוה וצ\"ע ויותר טוב אם הוא חול ואין לו נר אחר ללמוד לפניו שיכבנה לאחר כלות השיעור ויחזור וידליקנה:","\u0003 שאם ישתמש וכו'\u0004 - עיין במגן אברהם שכתב אבל מ\"מ אסור להשתמש אצלן וכו' עיין בפמ\"ג שפירש דאף נגד אור הנוסף או השמש ג\"כ אסור לכתחלה והמעיין ברבינו ירוחם שהובא בב\"י לא משמע כן אלא דנגד השמש כשמניחו בפ\"ע רחוק קצת מהנר מותר לשמש נגדו וכ\"כ במחה\"ש בביאור דברי המגן אברהם ע\"ש אח\"כ מצאתי בא\"ר שהסכים ג\"כ לדינא דנגד השמש מותר להשתמש. ועיין בשע\"ת סוף ד\"ה השמש דעתו נמי כמו שכתבנו:","\u0003 יהיה לאור הנוסף\u0004 - הנה לדעת הב\"ח הוא כפשטיה דאך נגדו מותר לשמש אבל נגד כולן יחד אסור כיון שיש נר חנוכה בתוכם וכן מוכח דעת הר\"ן כמו שכתב הפר\"ח כאן והגר\"א בסימן רס\"ד ולדעת רמ\"א בסוף הסעיף כיון שיש נר חול בתוכם שוב אין ביזוי מצוה בהשתמשו נגד כולם כיון שיש שם נר הנוסף או השמש והיה די לו לשמש נגד אורו בלבד ולא מהני ליה נר חנוכה [ולפי דבריו מש\"כ יהיה לאור הנוסף היינו שאור הנוסף הלא יועיל לו ג\"כ לשימושו ולהכי שרי] וכן הסכים המגן אברהם והפר\"ח להקל [אלא שהפר\"ח סיים דאם אין די לו לתשמישו בהנר של חול דהיינו דבר שהוא צריך עיון גדול וצריך לזה הענין ג\"כ האור של נר חנוכה באופן זה בודאי אין להקל] אלא דהמ\"א סיים דלדברי המלחמות אין להשתמש נגד כולן בענינינו מטעם אחר שלא יאמרו לצרכו הדליקן [אבל נגד השמש לבד אין להחמיר וכמו שכתבנו לעיל] משא\"כ שם לענין תערובות לא שייך זה וכמו שכתבנו שם בשם המחה\"ש ע\"ש:","\u0003 ואז מותר וכו'\u0004 - עיין במ\"ב ד\"ה מותר ואע\"ג דמ\"א גופיה כתב בסק\"ד בשם המלחמות אע\"ג דאיכא שמש לא ישתמש אלא לאור השמש ולא לאור נ\"ח היינו משום דנ\"ח דולק למצותן לכן צריכין הכירא שהודלק לשם מצוה ואם ישתמש אצלן יאמרו לצורכו אדלקיה דלפעמים מדליק כמה נרות משא\"כ הכא בתערובות כשידליקן לא ידליקן לשם מצוה כ\"א לצורכו ואין צריך נר התירא כ\"א דלהשתמש לנר האסור בלבד לא שרינן וכיון דאיכא חד נר היתר תו לא מקרי נהנה מדבר איסור [מחה\"ש ועיין בח\"מ דבנתערבה אחר שכבתה מסכים גם הוא לדינא דרמ\"א להקל משא\"כ בדינא דמלחמות הנ\"ל עי\"ש]:","\u0003 הדלקה עושה מצוה\u0004 - בתשובת מהר\"י ברונא סי' ל\"ט כתב דלא יסלק ידו אחר הברכה עד אשר ידליק רוב הפתילה היוצא מן השמן [פ\"ת]:","\u0003 אם כבתה וכו' אינו זקוק לה\u0004 - אכן בעת הדלקה בעינן שיהיה בה שמן שיוכל להדליק כשיעור וכנ\"ל בסימן תרע\"ב ס\"ב ונ\"ל דכמו כן בעינן שבעת הדלקה יהיה כל הנרות לפי חשבון הימים ואז נחשב למהדר מן המהדרין וע\"כ אם כבתה אחת קודם שהשלים ההדלקה צריך לחזור ולהדליקה. ודע עוד דמה שאמרו אינו זקוק לה היינו אפילו כבו כולם דלא בעינן פרסומי ניסא רק בעת ההדלקה:"],"\u0010y0\u0011 \u0010g0\u0011 כָּל הַשְּׁמָנִים וְהַפְּתִילוֹת \u0010y1\u0011 \u0010t0\u0011 \u0010s0\u0011 \u0010m0\u0011 כְּשֵׁרִים \u0010y2\u0011 לְנֵר חֲנֻכָּה, וְאַף עַל פִּי שֶׁאֵין הַשְּׁמָנִים נִמְשָׁכִים אַחַר הַפְּתִילָה וְאֵין הָאוּר נִתְלֶה יָפֶה בְּאוֹתָם הַפְּתִילוֹת. \u0005 הַגָּה: וּמִיהוּ שֶׁמֶן זַיִת מִצְוָה מִן הַמֻּבְחָר \u0006 \u0005(מָרְדְּכַי וְכָל בּוֹ וּמַהֲרִי\"ל)\u0006, \u0005 וְאִם אֵין שֶׁמֶן זַיִת מָצוּי מִצְוָה בִּשְׁמָנִים שֶׁאוֹרָן זַךְ וְנָקִי; וְנוֹהֲגִים בִּמְדִינוֹת אֵלּוּ לְהַדְלִיק בְּנֵרוֹת שֶׁל \u0010y3\u0011 שַׁעֲוָה, כִּי אוֹרוֹ צָלוּל כְּמוֹ שֶׁמֶן. \u0010y4\u0011 \u0010g1\u0011 \u0006 וַאֲפִלּוּ בְּלֵיל שַׁבָּת שֶׁבְּתוֹךְ יְמֵי חֲנֻכָּה מֻתָּר לְהַדְלִיק בְּנֵר חֲנֻכָּה הַשְּׁמָנִים וְהַפְּתִילוֹת שֶּׁאָסוּר לְהַדְלִיק בָּהֶם נֵר שַׁבָּת, \u0005 הַגָּה: \u0010y5\u0011 אִם אֵינוֹ נוֹתֵן בַּנֵּר רַק כְּדֵי שִׁעוּר מִצְוָתוֹ, \u0006 \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סי' ק\"ע)\u0006, \u0010y6\u0011 לְפִי שֶׁאָסוּר לְהִשְׁתַּמֵּשׁ \u0010y7\u0011 בְּנֵר \u0010y8\u0011 \u0010t1\u0011 חֲנֻכָּה בֵּין בְּשַׁבָּת בֵּין \u0010y9\u0011 \u0010g2\u0011 \u0010t2\u0011 \u0010s1\u0011 \u0010m1\u0011 בַּחֹל, וַאֲפִלּוּ לִבְדֹּק מָעוֹת אוֹ לִמְנוֹתָן לְאוֹרָהּ \u0010y10\u0011 אָסוּר, \u0010y11\u0011 \u0010g3\u0011 \u0010m2\u0011 וַאֲפִלּוּ תַּשְׁמִישׁ שֶׁל קְדֻשָּׁה, כְּגוֹן לִלְמֹד לְאוֹרָהּ, \u0010y12\u0011 אָסוּר; \u0010g4\u0011 וְיֵשׁ מִי שֶׁמַּתִּיר בְּתַשְׁמִישׁ \u0010c0\u0011 שֶׁל \u0010y13\u0011 \u0010t3\u0011 \u0010s2\u0011 קְדֻשָּׁה; וְנוֹהֲגִים \u0010g5\u0011 לְהַדְלִיק נֵר נוֹסָף, כְּדֵי \u0010y14\u0011 \u0010m3\u0011 שֶׁאִם יִשְׁתַּמֵּשׁ \u0010c1\u0011 לְאוֹרָהּ יִהְיֶה לְאוֹר הַנּוֹסָף \u0010c2\u0011 שֶׁהוּא אוֹתוֹ שֶׁהֻדְלַק אַחֲרוֹן, \u0010y15\u0011 \u0010g6\u0011 וְיַנִּיחֶנּוּ מֵרָחוֹק קְצָת מִשְּׁאָר נֵרוֹת מִצְוָה. \u0005 הַגָּה: וּבִמְדִינוֹת אֵלּוּ אֵין נוֹהֲגִים לְהוֹסִיף, רַק \u0010y16\u0011 \u0010m4\u0011 מַנִּיחַ אֶצְלָן \u0010y17\u0011 \u0010t4\u0011 \u0010s3\u0011 \u0006 \u0005 הַשַּׁמָּשׁ שֶׁבָּהֶן מַדְלִיק הַנֵּרוֹת, וְהוּא \u0010y18\u0011 \u0010m5\u0011 עָדִיף טְפֵי, וְיֵשׁ לַעֲשׂוֹתוֹ \u0010y19\u0011 \u0010m6\u0011 יוֹתֵר \u0010t5\u0011 \u0006 \u0005 אָרֹךְ מִשְּׁאָר נֵרוֹת, שֶׁאִם בָּא לְהִשְׁתַּמֵּשׁ \u0010t6\u0011 \u0006 \u0005 יִשְׁתַּמֵּשׁ לְאוֹתוֹ נֵר \u0006 \u0005(מָרְדְּכַי)\u0006. \u0010y20\u0011 \u0005 אִם נִתְעָרֵב נֵר \u0010m7\u0011 חֲנֻכָּה הָאָסוּר \u0010t7\u0011 \u0006 \u0005 בַּהֲנָאָה בִּשְׁאָר נֵרוֹת, אֲפִלּוּ אֶחָד בְּאֶלֶף, \u0010g7\u0011 לֹא בָּטִיל \u0010y21\u0011 דְּהָוֵי דָּבָר \u0010t8\u0011 \u0010s4\u0011 \u0010m8\u0011 \u0006 \u0005 שֶׁל מִנְיָן \u0006 \u0005(ת\"ה סי' ק\"ג)\u0006, \u0005 אֶלָּא יַדְלִיק מִן הַתַּעֲרוֹבוֹת \u0010y22\u0011 \u0010t9\u0011 \u0010m9\u0011 \u0006 \u0005 כָּל כָּךְ שֶׁבְּוַדַּאי נֵר שֶׁל הֶתֵּר דּוֹלֵק עִם נֵר שֶׁל אִסּוּר, וְאָז \u0010y23\u0011 \u0010c3\u0011 \u0010m10\u0011 מֻתָּר לְהִשְׁתַּמֵּשׁ אֶצְלָן \u0010y24\u0011 \u0010g8\u0011 \u0006 \u0005(דִּבְרֵי עַצְמוֹ)\u0006. \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011 \u0010r9\u0011\nהַדְלָקָה עוֹשָׂה מִצְוָה. \u0010c4\u0011 \u0010g9\u0011 לְפִיכָךְ \u0010m11\u0011 אִם כָּבְתָה \u0010c5\u0011 קֹדֶם שֶׁעָבַר זְמַנָּהּ \u0010t10\u0011 אֵינוֹ זָקוּק לָהּ, \u0010g10\u0011 וַאֲפִלּוּ כָּבְתָה בְּעֶרֶב שַׁבָּת קֹדֶם קַבָּלַת שַׁבָּת \u0010y25\u0011 שֶׁעֲדַיִן הוּא מִבְּעוֹד יוֹם, אֵינוֹ זָקוּק לָהּ. \u0010g11\u0011 וְכֵן אִם לְאַחַר שֶׁהִדְלִיקָהּ בָּא לְתַקְּנָהּ וְכִבָּה אוֹתָהּ בְּשׁוֹגֵג, אֵינוֹ זָקוּק לָהּ. \u0005 הַגָּה: \u0010y26\u0011 וְאִם רוֹצֶה \u0010t11\u0011 \u0010s5\u0011 \u0006 \u0005 לְהַחְמִיר עַל עַצְמוֹ וְלַחֲזֹר וּלְהַדְלִיקָהּ, אֵין לְבָרֵךְ עָלֶיהָ \u0006 \u0005(רַשְׁבָּ\"א סִימָן תקל\"ט וְרַ\"ן)\u0006. \u0010g12\u0011 \u0010r10\u0011 \u0010r11\u0011 \u0010r12\u0011\nנֵר שֶׁל \u0010y27\u0011 \u0010t12\u0011 \u0010s6\u0011 \u0010s7\u0011 חֶרֶס שֶׁהִדְלִיק בּוֹ לַיְלָה אַחַת נַעֲשָׂה יָשָׁן וְאֵין מַדְלִיקִין בּוֹ לַיְלָה \u0010y28\u0011 אַחֶרֶת, אֶלָּא לוֹקֵחַ חֲדָשִׁים בְּכָל לַיְלָה; וְאִם אֵין לוֹ אֶלָּא יָשָׁן, מַסִיקוֹ בְּכָל לַיְלָה בָּאוּר; וְנֵר שֶׁל מַתֶּכֶת אֵינוֹ צָרִיךְ חָדָשׁ. וְשֶׁל זְכוּכִית אוֹ שֶׁל חֶרֶס \u0010y29\u0011 מְכֻסֶה, דִּינוֹ כְּמַתֶּכֶת. \u0010g13\u0011 \u0010r13\u0011 \u0010r14\u0011\nאֵין חוֹשְׁשִׁין לַפְּתִילוֹת לְהַחְלִיפָם, \u0010y30\u0011 עַד שֶׁתִּכְלֶה. \u0010r15\u0011",{"g":["מימרא דרב שבת כ\"א","שם","מימרא דרב שם כ\"ב","טור בשם אביו רא\"ש וכתב הר\"ן שם דכיון שע\"י נס שנעשו במנורה תקנוהו עשאוהו כמנורה שאין משתמשין בה כלל","טור בשם בעל העיטור וכ\"כ בשבולי הלקט","טור ור' ירוחם","שם בר' ירוחם","פי' להדליק כ\"א בפ\"ע אבל להדליק ב' או ג' ביחד בטל ברוב","מסקנת הגמרא כג","כרב חסדא ור' ירמיה לטעמיה דרב","ת\"ה","הר\"ן בשם תשובת הרשב\"א","טור בשם הר\"מ מרוטנבורג על פי מסכתא סופרים וכ\"כ שאר פוסקים","שבלי הלקט"],"t":["\u0003כשרים. \u0004 עיין בתשובת שער אפרים סי' ל\"ח אי שרי להדליק נר חנוכה בחמאה שנתבשלה בקדירה של בשר בן יומו שנאסרה מחמת שלא היה ס' ופסק דמותר. עוד נשאל שם אי שרי להדליק בה להאיר הבית והטעם שהיא אסורה בהנאה ואסור ע\"ש. ומי שהיה \u0005(מדביק)\u0006 נרות של שעוה בכותל כדי להדליקן למצות נר חנוכה ובעוד שהוא עסוק בכך הביאו לו שמן זית ידליק בנרות של שעוה אף שמצוה מן המובחר הוא שמן זית שבות יעקב חלק א' סי' ל\"ו ע\"ש. ובתשובת חכם צבי סי' מ\"ה דחה דבריו וראיותיו והרבה להביא ראיות דימשוך ידו מנרות של שעוה וידליק בשמן זית ע\"ש. וע' בתשובת יד אליהו סי' מ\"ב. ושוב שלח ידו פעם ב' הרב בעל שבות יעקב בח\"ב סי' למ\"ד והחזיק דבריו ע\"ש. אין להדליק נר חנוכה קצתם משמן זית וקצתם משעוה או משאר שמנים דכיון דמשום פרסומי ניסא הוא יאמרו שקצתם אינם מן המהדרין דדי בנר א' ואינו מן המהדרין דמהדרין כי יאמרו ב' אנשים הדליקום תשובת שער אפרים סי' ל\"ט ע\"ש. וע' בשבות יעקב ח\"ב סי' ל\"א שכתב שבמקום שהשמן זית ביוקר ושאר השמנים בזול שידליק בליל א' ובכל הלילות הנוספות בשמן זית ושאר הנרות בשאר השמנים ע\"ש:","\u0003חנוכה. \u0004 ולאו דוקא שמדליקים בה בראשונה שבאה למצות נ\"ח אלא אפי' אותה שמוסיפין המהדרים בכל לילה אסור להשתמש לאורה מהר\"א הלוי בספר גן המלך סי' מ\"ב:","\u0003מעות. \u0004 שצריך עיון יפה וידיו סמוכות לנר אבל תשמיש עראי שא\"צ להיות ידיו סמוכות לנר שרי ב\"י ד\"מ. ורש\"ל וב\"ח פסקו להחמיר וכ\"כ הסמ\"ק וסה\"ת דאפי' לאכול אצלו אסור וכ\"מ סי' תרע\"ח דאל\"כ יקנה נ\"ח וידליקנה בביתו ויהיה גם שלום ביתו אלא ע\"כ כל תשמיש אסור והכי נהוג מ\"א בסי' תרע\"ח ס\"ק ב' מש\"ש. ועיין ט\"ז ובתשו' שבות יעקב ח\"ב סי' ל\"א:","\u0003קדושה. \u0004 עיין ט\"ז שהאריך והעלה דיש מי שמתיר בתשמיש של קדושה היינו דרך עראי דוקא ולא ללמוד דרך קבע וכאן לא מהני אחר עמו דאפי' בחול אסור משום דלא יהיה היכר שנעשה לשם חנוכה ע\"כ:","\u0003השמש. \u0004 ואפי' רבים המדליקים צריך להניח אצל כל א' וא' שמש אפי' יש נר על השלחן רמ\"א בתשו' סי' פ\"א וכ\"מ בב\"ח ורש\"ל מיקל. ומשמע במאור דאע\"פ שיש השמש אצל הנרות צריך נר על השלחן עמ\"א סק\"ד:","\u0003ארוך. \u0004 וה\"ה אם מעמידו גבוה משאר נרות ש\"ד. ב\"ח מהרי\"ל מ\"צ:","\u0003ישתמש. \u0004 ואסור להשתמש בו תשמיש מגונה וכ\"ש לשחוק בקארטי\"ן ח\"ו אצלו. מ\"כ:","\u0003בהנאה. \u0004 פי' לאחר שהודלק וכבה דקודם לכן לא נאסר דהזמנה לאו מילתא היא כמ\"ש סי' תרל\"ח סס\"א. מ\"א:","\u0003של מנין. \u0004 אפי' במקום שמוכרין הנרות במשקל מ\"מ נרות של מצוה הכל מונין אותן בכל לילה. ת\"ה מ\"א ע\"ש. ועט\"ז ובתשובת פנים מאירות סי' צ\"ח ובתשובת שבות יעקב ח\"ב סי' ל\"ב ועיין יד אהרן:","\u0003כל כך. \u0004 פי' אם נתערב א' ידליק ב' ואם נתערבו ב' ידליק ג' ורש\"ל פסק דחד בתרי בטל וכן דעת הט\"ז ע\"ש:","\u0003זקוק. \u0004 ואם הניחה במקום שהרוח מצוי' וכבתה זקוק לה וחייב להדליק פעם אחרת בברכה וכן אם כבתה במזיד גן המלך סימן מ\"ג. ובכנה\"ג כתב משם שה\"ג לחייב לחזור ולהדליקו אבל אין צריך לחזור ולברך וכ\"כ הט\"ז דא\"צ לחזור ולברך ע\"ש:","\u0003להחמיר. \u0004 הסכמת האחרונים דראוי להחמיר לחזור ולהדליקו בכל ענין ובפרט בערב שבת קודם שבת ע\"ש. כתב רש\"ל מצוה מן המובחר לקנות שעוה לנר חנוכה ממה שנוטף מן הנרות בבה\"כ מאחר דאיתעביד בהו חדא מצוה ויזהר שלא יקנה שעוה מנרות של בתי תפלות שלהם וע' סימן קנ\"ד סי\"א:","\u0003חרס. \u0004 רש\"ל קנה של כסף ובליל ב' התחיל להדליק בה ובירך להדליק ושעשה נסים ושהחיינו אף שבשעת קנין יש לברך מכל מקום ניחא לסדר ברכות שהחיינו עם אלו שני ברכות מט\"מ. ובסדה\"י האריך שכל א' יטריח לעשות לו מנורה יפה ומי שידו משגת יעשה של כסף וכן הנרות יעשה יפה:"],"s":["\u0003כשרים. \u0004 עבה\"ט מ\"ש בשם שער אפרים והעתיק זה מלקט הקמח שכ\"כ ובמ\"כ מ\"ש בשמו מותר אפי' הוא להפך דבאמת אוסר במסקנתו שם להדליק בהנר חנוכה שאסור להשתמש לאורה ואין כאן רק הנאת המצות ומצות לאו ליהנות ניתנו מכל מקום אסור להדליק בה אע\"ג דלא קי\"ל כהרז\"ה דסבר דמצוה דרבנן להנות נתנו מ\"מ י\"ל כיון דנ\"ח בעי שיעור דהיינו שיתן שמן בנר שידליק כשיעור וכיון דבב\"ח אסור בהנאה כתותי מיכתת שיעורא ולכן אסור להדליק בשמן של ערלה גם כן וא\"ל דדוקא בשל ערלה שהוא מהנשרפים (וע') [אבל] בב\"ח שהוא מנקברים לא אמרי' כתותי וא\"ל בזה כל הנקברים לא ישרופו דהתם טעמא משום אפר משא\"כ בהדלקת נ\"ח שאין כאן אפר רק אפר הפתילה והפתילה לא נאסרה בהנאה. מכל מקום יש לאסור שאף אם הטעם דאפר לא שייך כאן מ\"מ לא בטל הדין דכל הנקברים לא ישרופו כדמוכח בכמה דוכתי דבשביל ביטול הטעם לא יתבטל הדין וכמ\"ש בריב\"ש סי' ל\"ד וגם י\"ל דנקברים כששורפו אותם גם כן שייך בהו כתותי ע' שם וע' באליה זוטא תמה ע\"ז דבלא\"ה אסור מחמת בישול בב\"ח דהא בסי' שי\"ח ק\"ל דיש בישול אחר בישול עיין שם ובשו\"ת שבו\"י ח\"א סי' ל\"ח נשאל ע\"ז מחכם א' שהשיב על דברי הא\"ז דכאן כשראש הפתילה הוא מבעיר הוא שורף וקלי איסורי' ואין ע\"ז שם בישול דבב\"ח דהיינו בישול שיכול לאכול ע\"י כדאיתא בחולין דף כ\"ח והשבו\"י השיב דקודם דמקלי קלי האיסור ראוי לאכילה מחמת החימום דהא אפי' חימום דכ\"ש מיקרי בישול לענין בב\"ח (והדברים תמוהים לענ\"ד ע' שם עוד שכ' דבחולין דף כ\"ד משמע כן לאסור מדאורייתא וגדולה מזו מצינו בתוחב כף וכו' ועיין ביש\"ש פרק ג\"ה סימן מ\"ה ובפ\"מ בפתיחה לבב\"ח דחם בחם בלא רוטב אין איסור מה\"ת ומותר בהנאה עיין שם ואין כאן מקומו) ועוד אף אם יש לפקפק ולומר דלא הוי בישל גמור מכל מקום יפה תמה בא\"ז שלא העירו בחשש זה כלל עכ\"ל ועיין בפ\"מ י\"ד סימן פ\"ז וכאן סימן זה שהעיר על דברי שער אפרים דהא זה טיגון וטיגון כת' מהר\"מ שי\"ף בחדושים לחולין דהו' דרבנן וכן בסולת למנחה כלל פ\"ה כ' בחמאה מעורב עם חלב מותר להדליק דטיגון אין איסור מה\"ת ע\"ש ובפתיחה וא\"ל דהבלוע שבקדירה נאסר בהנאה וחוזר ונפלט לתוך החמאה ואסרה דז\"א דבלוע של בב\"ח אין אוסר את החמאה בהנאה כיון שאין נהנה בהדלקה מבליע זו וכדאמרי' גבי כריא דחיטי כו' עיין בפתיחה לבב\"ח בפ\"מ שם ועיין בא\"ח הלכות פסח לענין חיטה שנמצא בתרנגולת ובמ\"א הארכתי בזה ומ\"ש בה\"ט בשם השבו\"י בקצרה ע\"ש שמבואר שאפי' דרכו תמיד להדליק בשמן זית ובא לביתו ולא מצא שמן זית והתחיל להכין עצמו עם נרות שעוה יגמור המצוה בנרות של שעוה כיון שכבר התחיל בה משום מצוה מן המובחר אין לבזות הראשונה כדמשמע ביומא ד\"ז היה עומד ומקריב מנחת העומר כו' וכיוצא בזה כת' בית יעקב סי' ך\"ו לענין חליצה כשבא הגדול וכבר התחילו בסדר חליצה לקטן עיין שם ובח\"צ דחה ראייתו דהכא לא מקרי התחיל במצוה אלא הכנה והזמנה בעלמא עשה שידבק הנרות בכותל ועוד כו' ולכן נראה שצריך למשוך ידיו מן הנרות שעוה אף שכבר הדביקם במקומם ולהדליק בשמן זית וראיה מיומא פרק הוציאו לו ר\"פ אמר ראשון משלח כו' והאריך הרבה וכת' דל\"ד למנחות דף פ\"ט הואיל והתחיל במתנות גומר דהתם הואיל והתחיל במצוה ממש אין לו לדחות זו בשביל האחרת אבל לקיים המצוה עצמו מן המובחר כו' ומפרש למהרי\"ל דס\"ל שלא יצא בנ\"ח בשעוה ואף כשנוהגין כרמ\"א הטעם שאין שמן זית מצוי להם כ\"כ משא\"כ כשישנו תו אין להסתפק כו' ואין חילוק בין הורגל עתה בשמן זית או לא ומ\"ש בשבו\"י בהידור מצוה עד שליש היינו שלא התחיל עדיין במצוה ליתא דאם כן מי שבידו אתרוג והביאו לו אחר אפילו בחנם והוא מהודר מן הראשון אלף פעמים אסור לו להניח הראשון דהא בפרק התדיר אמרינין דמטי זימני הו\"ל כשחוט וה\"נ כשהאיר המזרח יום א' כו'. ועוד אם כבר לקח אתרוג שאינו מהודר בידו לברך ועד שלא בירך הביאו לו במתנת חנם יפה שאין כמוהו יברך על הראשון שאינו מהודר ישתקע הדבר והדבר ברור בין באתרוג ובין בחנוכה ובכל המצות שבעולם מברך על היפה והמהודר אף שבא באחרונה ובשבו\"י ח\"ב סימן ל\"ה נעשה קצת סנגורי' לדבריו כת' דהך הכנה ודאי התחלה גדולה היא כדאמרינן לענין תספורת משיניח סודר וכו' ומכל מקום מבורר שם דמודה שמי שרוצה לעשות המצוה מן המובחר הרשות בידו וכת' שראיותיו בח\"א אינם רק לומר שא\"צ לבזות מצוה ראשונה כו' ע' שם ובבה\"ט הביא בקצרה וראיתי להעתיק שרשי הדברים וטעמם ונימוקם ונראה דאם כבר התחיל הברכה אף על פי שכבר מוכן לפניו השמן זית עם הפתילה וא\"צ לעסוק בה מכל מקום כיון שהתחיל לברך ע\"ז גומר וגם יש בזה ספק אם צריך לברך מחדש כמבואר סי' ר\"ו עיין שם וה\"ה לענין אתרוג כה\"ג וגם נראה דבאתרוג ביום ראשון וזה שאינו מהודר הוא שלו ולקחו בידו לברך ובתוך כך בא חבירו ורוצה ליתן לו מהודר יותר במתנה על מנת להחזיר שפיר יש לסמוך על השבו\"י דאף דמהני המתנ' על מנת להחזיר מכל מקום טפי עדיף שיקיים המצוה בשלו ממש ונראה שגם הח\"צ מודה בזה ומ\"ש בה\"ט בשם תשובת שער אפרים עיין בבר\"י שמפקפק בזה וכת' כיון דלא שייך ביה לצרכו אדלקי' רק שיאמרו שאינו מן המהדרין כו' אין לגזור וגם כיון שכ\"א הניח נרותיו במקום מיוחד וגם כיון דההיכר לבני בית מידע ידעו וכן נ\"ל להקל ועיין סימן תרע\"ה בב\"י בשם מהר\"י אבוהב עד כאן לשונו ועיין באליה זוטא דמכל מקום ראוי להדליק לילה אחד בשעוה ולילה א' בשמן עיין שם. ומ\"ש משם השבו\"י במקום ששמן זית ביוקר כו' נראה מזה שחולק על מ\"ש תחלה בשם השער אפרים שאין להדליק מקצת משמן זית ומקצת משאר שמנים ובתשו' שבו\"י שם דבריו מגומגמים וכצ\"ל ומה\"ט מי שתפוס בין העכו\"ם ולא יוכל להדליק נרות ידליק בכל ליל' אחת (ר\"ל שאף שיש לו שמן לח' ימים לא ידליק ביום השני כמהדרים וכן בשאר הלילות רק ידליק בכל לילה אחת) ומ\"ש בשער אפרים סימן ל\"ט שאין לדמות לגידוד חמשה כו' מכל מקום כיון דכאן עיקר מצוה רק בנר אחד וגם אין הדבר ניכר כל כך בשעת הדלקה כו' עיין שם כצ\"ל:","\u0003מעות. \u0004 עבה\"ט ועיין בפר\"ח בשם מהריק\"ש דלילך לאור נ\"ח לראות שלא יכשל שרי דלא מחויב להעצים עיניו דלא מיקרי תשמיש ועיין בשו\"ת פני אריה סימן מ\"ז שלא אסרו אלא להשתמש אבל כל שאינו משמש כלום רשאי לישב בביתו בשעה שנ\"ח דולקות עיין שם שהביא מדברי הפר\"ח אלו ובאמת שכן מבואר במג\"א לקמן סימן תרע\"ח במ\"ש דעכשיו שמדליקין יקנה לנ\"ח ועכ\"פ לא ישב בחושך כו' ומשם מוכח ג\"כ כמ\"ש מהריק\"ש דהא עיקר שלום ביתו הוא בהליכה שלא יכשל ועיין לעיל סימן רס\"ג במג\"א ס\"ק י\"ג וי\"ד עיין שם:","\u0003קדושה עבה\"ט \u0004 ובט\"ז מ\"ש בזה וע' שו\"ת שבוי\"י ח\"א סי' ל\"ט מ\"ש בזה ושם בסימן מ\"ם תשו' הגאון מוהר\"ד אופנהי' ז\"ל מ\"ש בקונטרס מועד דיד הנדפס בספר בית יהודה עיין שם ועיין בשו\"ת שמש צדקה סי' למד שני תשו' בדבר ושם מבואר בדיני ספק ברכות ועיין בר\"י בשם מהר\"י מולכו שאם צריך לעיין איזה דין בספק שנפל לו בנרות שהדליק ואין לו נר אחר שרי לעיין הדין ההוא לנר אור חנוכה דכמה רבוותא התירו בתשמיש מצוה ואף מאן דאוסר מכל מקום לצורכה יש להתיר דומיא דישינים בבה\"כ בליל יה\"כ לצורך בה\"כ וכן בפרה אדומה כל לצורכה לאו עבודה היא עיין שם וראייתו יש לדחות אך כיון שהוא דרך עראי נראה פשוט דמותר:","\u0003השמש. \u0004 עבה\"ט ע' בהלק\"ט דלכאורה לא סגי בחד שמש מאחר דהנרות מאירים ומזהירים בכל הבית והשמש בטל לגבייהו והיה צריך כ\"כ שמשים כמו הנרות שיאירו כמו נ\"ח וזוז\"ג הוא והתירו בדרבנן ושוב כת' דאפשר שלענין זה אין להחשיב התו' כעיקר דאין הכל יכולים לעשות שמשים כנגדם ור\"ל דנר הנוסף אינו חומרא כ\"כ לענין השימוש לאורו ע\"ש ואע\"ג דלעיל ס\"ק ב' הביא הבה\"ט בשם גן המלך דגם בנר הנוסף אסור להשתמש לאורו מכל מקום כיון דאיכא שמש א' שמאיר גם כן סגי בהכי לתלות שאין השימוש מחמת הראשון ולא מחמת הנוספים לבד שהרי גם אור נר השמש שמה ומקילים בהו שלא נאמר שאור השמש בטל לגבייהו כצ\"ל לדעת הלק\"ט אבל באמת נראה דעיקר איסור השימוש היינו לפי שצריך להתקרב לאור הנר ועיין בט\"ז וכשיש כאן שמש והוא צריך לתשמיש שצריך לקרב לאור הנר אז כשיש שמש הוא מקרב עצמו לעיין לאור נר השמש ושוב לא איכפת לן מה ששאר הנרות מאירים ומזהירים ג\"כ כיון שלא לאורה הוא צריך שפיר נשארים בהיכר שלהם לשם מצות חנוכה משא\"כ כשישתמשו שם כשאין שם ממש אין היכר למצות חנוכה וכן מבואר בלשון הש\"ע כדי שאם ישתמש לאורה יהיה לאור הנוסף כו'. ויותר מבואר בלשון הרמ\"א ויש לעשותו יותר ארוך שאם בא כו' עיין שם ולכן נראה דהרוצה להשתמש נגד נ\"ח אף על פי שהשמש שם יש לו להטות ענין הדבר שמשמש שם אל נר השמש שיהיה ניכר שאין לו חפץ להשתמש בנרות של מצוה ואז אף על פי שהם גורמים יתרון ראות עיניו לית לן בה:","\u0003של מנין. \u0004 עבה\"ט עיין בפמ\"א שם שמחזיק בדעת התה\"ד דאזלי' בתר קודם הביטול דהוי נר חנוכה חשיב דבר שבמנין וגם השיג על הט\"ז דכת' דלא בטל מטעם קבוע דלא שייך בזה כיון שלדעתו אינו דבר שבמנין שהוא קבוע דרבנן וקבוע דאורייתא אין כאן כל שאין האיסור ניכר וידוע במקומו דומיא דט\"ח עיין שם ובשבו\"י סימן ל\"ב השיג על הראיות הפמ\"א ומכל מקום כת' שדברי התה\"ד נכונים שלא בא להביא ראיה ע\"ז דאזלינן בתר קודם הביטול דע\"ז א\"צ ראיה דאפילו בשעת הביטול לא היה ראוי להתכבד ואחר הביטול יהיה ראוי להתכבד לא בטל מכ\"ש להיפך אם בשעת הביטול ראוי לא נטל אף אם אחר הביטול לא יהיה ראוי (ולענ\"ד אין זה מוכרח דבכה\"ג דראוי בשעת הביטול שפיר י\"ל דבטל דמכל מקום בטל כבודו מאליו מחמת התערובות שהרי לא ניכר מי הוא וגלה כבוד ממנו וכיון שאם תאמר כשבטל לא יהיה להתכבד מועיל התערובות לבטלו משא\"כ היכי שאחר הביטול יהיה ראוי להתכבד י\"ל דלא מהני ליה הביטול לעשות מאינו ראוי ראוי וצ\"ע) רק ראיית התה\"ד לומר דנ\"ח קרוי דבר שבמנין אף על גב דכנגדו בנרות חול אין נמכרין במנין כמו בחתיכה דבטלה כו' ע\"ש ומ\"ש הפמ\"א דלא הוי קבוע ע\"ז השיב השבו\"י דדמי לט' חניות אלא שהמקילין נתערבו שהוא א\"י איזה טריפה דמקרי ג\"כ קבוע. ועיין שם במ\"י כלל מ\"ג דזה דלא כדעת בעל ספר כריתות ועיין מ\"ש בספרי בית אפרים על טריפות בקונטרס התשובה סי' ב' ובשו\"ת בית אפרים חלק אה\"ע בענין זה קבוע:","\u0003 (בש\"ע סעיף ב') ואפילו כבתה בע\"ש כו' \u0004 עבט\"ז מ\"ש על התה\"ד בזה ועיין בספרי שו\"ת בית אפרים סימן ע\"ג ליישב דברי הט\"ז והתה\"ד ממה שיש לתמוה עליהם ובישוב דברי הרא\"ש והרי\"ף ליישב דברי התוספות ובקושיא המהרש\"א עיין שם ותמצא מרגוע:","\u0003להחמיר. \u0004 עבה\"ט ועיין שבו\"י ח\"ג סימן מ\"ח דאע\"ג דאין זקוק לה מכל מקום צריך להניח את הנותר מנ\"ח של שעוה או של שמן כל זמן עת ההדלקה אם לא יעשה כן חיישינן לחשדא שלא הדליק כלל וראיה מדאמרינן חצר שיש לה ב' פתחים כו' משום חשדא וקשה מאי חשדא איכא לידינוהו לכף זכות ולומר דהדליק אלא שכבתה ואין זקוק לה כהסכמת הפוסקים אלא ודאי כשלא הניח הנותר באותו מקום איכא חשדא לו' שלא הדליק כלל עיין שם ועיין שם שכת' ליישב קושית הב\"י אהך דחצר מברכות וגם קושית הח\"צ סימן צ\"א אהא דפריך ומנא תימרא דחיישי' לחשדא דאמאי פריך הכא טפי מכל דוכתי וע\"ז כת' דלחשדא שלא יעשה כלל לא חיישינן רק החשד כיון דאמרינן הרואה מברך כו' חשדוהו שרוצה לצאת חובתו בראיותו ולא הדליק בפתחו ולזה פריך ומנא תימרא דאיכא חשדא בכה\"ג ומייתי מפאה דגם כן איכא חשדא שלא נתן מן הקמה שהיא עיקר המצוה כו' וע\"ש ונ\"מ לדינא דגם בכה\"ג שיחשדוהו שאינו עושה מן המובחר גם כן יש להשמר מזה משום והייתם נקיים כו':","\u0003חרס. \u0004 עבה\"ט ועיין בר\"י בענין קליפי בצים לנ\"ח בשם אדמת קודש שהביא בשם בעל חסד לאברהם דקליפי בצים ובצלים אין מדליקין בהם ועיין בשאילת יעב\"ץ ח\"א סי' קמ\"ט שכ' שמה\"ט עדיף טפי להדליק נ\"ח בפנס שיש לו דפנות של זכוכית שאין הרוח שולט שתכבה מהר והביא מהא דעששית שהיה דולקת כו' וסתם עששית הוא לנטירנא כמ\"ש רש\"י וכן מוכח מערוה בעששית כו' והביאו בר\"י ולא ראינו מי שנוהג כן:"],"m":["\u0003כשרים לנר חנוכה\u0004. אבל לא להשתמש [ב\"ח]: יש ליקח משעוה הנוטף בבית הכנסת הואיל ואיתעביד וכו' [מט\"מ ב\"ח]:","\u0003לבדוק מעות\u0004. שצריך עיון יפה וידיו סמוכות לנר אבל תשמיש עראי שא\"צ להיות ידיו סמוכות לנר שרי [ב\"י ד\"מ ורש\"ל בתשו'] וב\"ח פסק להחמיר וכ\"כ הסמ\"ק וסה\"ת דאפי' לאכול אצלו אסור וכ\"מ סי' תרס\"ח /תרע\"ח/ דאם לא כן יקנה נ\"ח וידליקנה בביתו ויהיה גם שלום בית אלא ע\"כ כל תשמיש אסור והכי נהוג:","\u0003ואפי' תשמיש כו'\u0004. וכ\"פ רש\"ל:","\u0003שאם ישתמש\u0004. אבל מ\"מ אסור להשתמש אצלן דהרואה או' לצרכו הדליק כולן דלפעמים אדם מדליק כמה נרות [מלחמות] ובמאור משמע דאפי' שיש שמש אצל הנרו' צריך נר על השלחן שלא יאמרו לצרכו הדליקן וכ' הרי\"ו שאם הדליקן במקום שאין רגילין להדליק שם נר א\"צ נר אחר להשתמש לאורה עכ\"ל ומ\"מ צריך להניח שמש אצלן שמא ישתמש אצלן:","\u0003מניח אצלן\u0004. ואפי' רבים המדליקין צריך להניח אצל כל א' וא' שמש אפי' יש נר על השלחן (רמ\"א בתשו' סי' פ\"א) וכ\"מ בב\"ח ורש\"ל מיקל ע\"ש:","\u0003עדיף טפי\u0004. דאז מוכח בהדי' שאינו ממנין הנרות:","\u0003יותר ארוך\u0004. וה\"ה אם מעמידו גבוה משאר הנרות ש\"ד (ב\"ח מהרי\"ל מ\"צ):","\u0003האסור בהנא'\u0004. פי' לאחר שהודלק וכבה דקודם לכן לא נאסר דהזמנ' לאו מילתא היא כמ\"ש סי' תרל\"ח סס\"א וכ\"כ הע\"ש בשם מהרי\"ב:","\u0003של מנין\u0004. אפי' במקום שמוכרין הנרות במשקל מ\"מ נרות של מצוה הכל מונין אותן בכל לילה (ת\"ה) ורש\"ל פסק דבטל חד בתרי עבי\"ד סי' ק\"י:","\u0003כל כך שבודאי\u0004. פי' אם נתערב נ\"ח א' ידליק ב' ואם נתערבו ב' ידליק ג' ויש גורסין ב' ב' ואין צריך להגיה:","\u0003מותר להשתמש אצלן\u0004. דהא הדלקת השמש הוא כדי שישתמש לאורן ש\"מ דאם הם ביחד מותר להשתמש אצלן [ד\"מ] והב\"ח חולק וס\"ל דדוקא שמש שעומד למעלה מכל הנרות שרי דמשתמש לאור השמש משא\"כ כאן עד כאן לשונו ול\"נ דהדין עם רמ\"א וכ\"מ סי' רע\"ו ס\"ד עמ\"ש שם:","\u0003אם כבת'\u0004. ואם העמיד' במקום הרוח וכבת' זקוק לה דהוה כאלו לא נתן בה שמן כשיעור [ש\"ג ב\"ח] ולא יברך (כ\"ה) וראוי להחמיר לחזור ולהדליק' בכל ענין ובפרט בע\"ש קודם קבלת שבת (רש\"ל וב\"ח):"],"r":["\u0003ס\"א ואע\"פ שאין כו' ואין. \u0004שם שמנים שאמרו חכמים אין כו' מסכסכת בהן:","\u0003ומיהו. \u0004שם ושמן זית כו' ופי' תוס' בנ\"ח מדאמר אביי מריש כו' ועתוס' ד\"ה מריש כו':","\u0003ואם אין כו'. \u0004כמש\"ש דיליל נהורא טפי:","\u0003אם אינו. \u0004כנ\"ל בסי' תער\"ב ס\"ב וכן יכול כו' ואזדא טעמא דר' ירמיה כמש\"ו לפי כו':","\u0003ואפי' תשמיש של. \u0004דאל\"כ אזדא טעם הכ\"ל וכ\"מ ממ\"שש נר ביתו ונ\"ח נר ביתו כו' ואם איתא יעשה נר א' ועולה לכאן ולכאן ויניח על שולחנו כמ\"ש בשעת הסכנה כו':","\u0003ויש מי. \u0004עט\"ז דוקא בתשמיש עראי ולכאורה משמע כן בטור אך שכת' ול\"נ לא\"א הרא\"ש ז\"ל והרא\"ש מתיר בתשמיש עראי וט\"ז אזיל לשיטתו שבס\"ק ג' הגיה ברא\"ש אבל נראה טעמו דמתיר ממ\"ש מעות שהוא תשמיש דחול:","\u0003ונוהגין להדליק. \u0004שם וצריך נר אחרת כו'.","\u0003ויניחנו מרחוק. \u0004כנ\"ל בסי' תרע\"א ס\"ב:","\u0003יותר ארוך. \u0004מטעם הנ\"ל:","\u0003אם נתערב. \u0004כתנא דליטרא קציעות. בפ\"ק די\"ט וכ\"פ בי\"ד סי' פ\"ו ס\"ג וכאן מדליקין אותו במנין אע\"ג דאינו במנין רק משום שהיא קדושה ולא בעצמו דהכי אשכחן אפי' לקולא בפ' הערל פ\"א ב' בחתיכות חטאות טמאה בשל טהורות דתעלה וכ' תוס' שם ד\"ה דברי הכל כו' דלא שייך כו' ועט\"ז שחולק ע\"ז וכמ\"ש בתוס' שם דאזלינן אחר מה שיהי' אחר הביטול וכ\"כ בש\"ע י\"ד סי' ק\"א ס\"א ואפי' אם כו':","\u0003ס\"ב הדלקה. \u0004הוא לשון ש\"ע בעצמו וצ\"ע ועט\"ז שכ' דר\"ל כיון שהדליק קיים כבר המצוה וא\"צ יותר:","\u0003ואפי' כבתה כו'. \u0004דאל\"כ היה אסור בשבת בשמנים ופתילות שאסרו חכמים מטעם דכבתה זקוק ושמא יכבה בכה\"ג ויפשע כמ\"ש רש\"י שם:","\u0003וכן אם כו'. \u0004כן מוכח מגמרא שם מדמתירין להדליק בשמנים שאמרו כו' ולא חיישינן בכה\"ג:","\u0003ס\"ג ונר של מתכת. \u0004דאינו מאוס כמ\"ש פ\"ג דשבת מ\"ד א':","\u0003ושל זכוכית. \u0004ע' בתוס' דסוף פ\"ג דברכות כ\"ה ב' ד\"ה גרף ורא\"ש שם ולעיל סי' פ\"ז ס\"א וכן משמע בגמ' דע\"א ל\"ג במאני דקוניא לפי' ר\"ת שם ד\"ה קוניא:","\u0003ס\"ד אין. \u0004מ\"ס:"]}],["מַדְלִיקִין \u0010y0\u0011 נֵר חֲנֻכָּה מִנֵּר חֲנֻכָּה, וְדַוְקָא לְהַדְלִיק זֶה מִזֶּה \u0010y1\u0011 בְּלֹא אֶמְצָעִי, אֲבָל לְהַדְלִיק זֶה מִזֶּה \u0010y2\u0011 עַל יְדֵי נֵר שֶׁל חֹל, אָסוּר; וְיֵשׁ מַתִּירִים \u0010y3\u0011 גַּם בָּזֶה, אֶלָּא אִם כֵּן הוּא בְּעִנְיָן שֶׁיֵּשׁ לָחוּשׁ שֶׁיִּכְבֶּה הַנֵּר שֶׁל חֹל קֹדֶם שֶׁיַּדְלִיק נֵר אַחֵר שֶׁל חֲנֻכָּה. \u0005 הַגָּה: וְנָהֲגוּ לְהַחְמִיר \u0010y4\u0011 בְּנֵרוֹת חֲנֻכָּה שֶׁלֹּא לְהַדְלִיק אֲפִלּוּ מִנֵּר לְנֵר, \u0010y5\u0011 דְּעִקַּר מִצְוָתוֹ אֵינוֹ אֶלָּא נֵר אֶחָד וְהַשְּׁאָר \u0010y6\u0011 אֵינוֹ לְמִצְוָה כָּל כָּךְ לָכֵן אֵין לְהַדְלִיק זֶה מִזֶּה \u0006 \u0005(הג\"מ וּמָרְדְּכַי)\u0006; \u0005 וְכָל זֶה אֵינוֹ רַק בְּעוֹד שֶׁדּוֹלְקִים לְמִצְוָתָן, אֲבָל אַחַר שֶׁעָבַר זְמַן הַמִּצְוָה מֻתָּרִים בַּהֲנָאָה, \u0010y7\u0011 כָּל שֶׁכֵּן שֶׁמֻּתָּר לְהַדְלִיק מֵהֶן \u0006 \u0005(נ\"י הֲלָכוֹת קְטַנּוֹת)\u0006.\nיֵשׁ מִי שֶׁאוֹמֵר שֶׁנֵּר שֶׁל בֵּית הַכְּנֶסֶת וְשֶׁל שַׁבָּת וְשֶׁל חֲנֻכָּה כֻּלָּם שֶׁל מִצְוָה הֵם \u0010y8\u0011 וּמֻתָּר לְהַדְלִיק זֶה מִזֶּה. \u0005 הַגָּה: וְהוּא הַדִּין נֵר שֶׁל ת\"ת אוֹ נֵר לְחוֹלֶה הַצָּרִיךְ נֵר \u0006 \u0005(נ\"י ה\"ק)\u0006 \u0005 וּבְעִנְיַן נֵר שֶׁל בֵּית הַכְּנֶסֶת עַיֵּן לְעֵיל סי' קנ\"ד סָעִיף י\"ד. \u0006",["\u0003נר חנוכה מנר חנוכה\u0004 מיירי מליל ראשון ואילך שיש יותר מנר אחד ומדליק זה מזה א\"נ בליל ראשון ויש שני אנשים בבית אחד שכל אחד מדליק בפני עצמו מותרין להדליק זה מזה דשתיהן נרות של מצוה הן ואף דמבואר לקמן בסימן תרע\"ה שצריך להניחה תחלה על מקומה ואח\"כ להדליקה כבר כתב הט\"ז לקמן דעל זמן מועט אין להקפיד ע\"ז ולדעת שארי אחרונים דסוברין דעל זמן מועט ג\"כ יש להקפיד הכא מיירי שהיו שניהן קבועין במקומן אכן היה להן פתילות ארוכות והפתילה מגיע לנר שלפניה וא\"צ להסירה ממקומה:","\u0003בלא אמצעי\u0004 דאין בזה ביזוי מצוה כיון דשתיהן של מצוה הן ואם כבה אחד מהנרות אין להדליקה מן האחרים אפילו בלא אמצעי ואפילו כבתה בתוך שיעור הזמן דאין בהדלקה זו מצוה מעיקר הדין דקי\"ל כבתה אין זקוק לה:","\u0003ע\"י נר של חול אסור\u0004 מפני שנראה כמבזה נר של מצוה שמדליק ממנו נר של חול אע\"פ שהוא עושה לצורך מצוה ונר של שמש הוא בכלל נר של חול לזה ועיין לקמיה בסק\"ז:","\u0003גם בזה\u0004 ס\"ל דכיון דעושה כדי להדליק תיכף ממנו נר של מצוה לאו בכלל ביזוי הוא:","\u0003בנרות חנוכה וכו'\u0004 ודוקא בנרות חנוכה ומטעם שמבאר לקמיה אבל בנרות אחרים של מצוה כגון של שבת ושל בית הכנסת וכדומה מדליקין מנר לנר [ד\"מ] וכן הסכים בספר חמד משה דכן הוא עמא דבר וכ\"כ בחיי אדם וכן משמע לעיל בסימן קנ\"ד סי\"ד דדוקא נר של הדיוט אין מדליקין מנר של ביהכ\"נ אבל נר מנר שרי ולא הגיה הרמ\"א שם כלום להחמיר משמע דפשיטא ליה דבזה לית כאן מנהג להחמיר ועיין בפמ\"ג דע\"י נר של חול אין כדאי אפילו בשאר נרות של מצוה ועיין לקמיה מה שנכתוב בזה:","\u0003דעיקר מצותו וכו'\u0004 היינו דמדינא הלא סגי בנר אחד לכל בני הבית היכי דסמוכין כולן על שולחן אחד [מ\"א] ולפ\"ז היכא דשני בע\"ב דרין בבית אחד דמדינא צריך הדלקת נר חנוכה לכל אחד מדליקין זה מזה [פמ\"ג] ועיין מה שכתבנו לעיל בסוף סק\"א:","\u0003אינו למצוה כ\"כ\u0004 כבר כתבנו שאם נכבה אחד מן הנרות אין להדליק מדינא מן נרות אחרות וכ\"ש שאם נכבה השמש שאין להדליקו מן נר חנוכה. וכתב רש\"ל שבבהכ\"נ אין חילוק בין השמש לשאר נרות שכל הנרות שבתוכה קרויים נר מצוה ומשו\"ה יש לגעור באותן שמדליקין נרותיהן ע\"י השפחות מנר ביהכ\"נ אפילו מן השמש חוץ ממוצאי שבת כדי לילך לביתו להאיר במבואות האפילות:","\u0003כ\"ש שמותר להדליק מהן\u0004 ולפי מה שכתבנו לעיל בסימן תרע\"ב דיש פוסקים שסוברין דכל זמן שדולקין אסור להשתמש לאורן ה\"ה דאין להדליק מהן. ומ\"מ נראה דאין להחמיר בזה רק לענין להדליק ממנו נרות של חול אבל נר של מצוה דמדינא מותר אפילו בתוך השיעור עכ\"פ אין לנו להחמיר אחר שעבר השיעור:","\u0003ומותר להדליק זה מזה\u0004 עיין בביאור הגר\"א שכתב דלדיעה ראשונה לעיל בסימן תרע\"ג ס\"א דאפילו תשמיש קדושה אסור להשתמש לנר חנוכה וכתבו הטעם שאינו דומה להא דקי\"ל דמדליקין מנר לנר דהתם כולהו נרות חדא מצוה היא משא\"כ ללמוד הוא מצוה אחרת ונראות כמבטלות זו את זו גם בענינינו אסור ועיין בספר חמד משה דדעתו ג\"כ דאין להדליק שאר נרות מנר חנוכה ע\"ש:"],[],"מַדְלִיקִין \u0010y0\u0011 נֵר חֲנֻכָּה מִנֵּר \u0010g0\u0011 חֲנֻכָּה, וְדַוְקָא לְהַדְלִיק זֶה מִזֶּה \u0010y1\u0011 בְּלֹא אֶמְצָעִי, אֲבָל לְהַדְלִיק זֶה מִזֶּה \u0010y2\u0011 עַל יְדֵי נֵר שֶׁל חֹל, אָסוּר; \u0010g1\u0011 וְיֵשׁ מַתִּירִים \u0010y3\u0011 גַּם בָּזֶה, \u0010g2\u0011 אֶלָּא אִם כֵּן הוּא בְּעִנְיָן שֶׁיֵּשׁ לָחוּשׁ שֶׁיִּכְבֶּה הַנֵּר שֶׁל חֹל קֹדֶם שֶׁיַּדְלִיק נֵר אַחֵר שֶׁל חֲנֻכָּה. \u0005 הַגָּה: וְנָהֲגוּ לְהַחְמִיר \u0010y4\u0011 בְּנֵרוֹת חֲנֻכָּה שֶׁלֹּא לְהַדְלִיק אֲפִלּוּ מִנֵּר לְנֵר, \u0010y5\u0011 \u0010m0\u0011 דְּעִקַּר מִצְוָתוֹ אֵינוֹ אֶלָּא נֵר אֶחָד וְהַשְּׁאָר \u0010y6\u0011 אֵינוֹ לְמִצְוָה כָּל כָּךְ לָכֵן אֵין לְהַדְלִיק \u0010t0\u0011 \u0010s0\u0011 זֶה מִזֶּה \u0006 \u0005(הג\"מ וּמָרְדְּכַי)\u0006; \u0005 וְכָל זֶה אֵינוֹ רַק בְּעוֹד שֶׁדּוֹלְקִים לְמִצְוָתָן, אֲבָל אַחַר שֶׁעָבַר זְמַן הַמִּצְוָה מֻתָּרִים בַּהֲנָאָה, \u0010y7\u0011 כָּל שֶׁכֵּן שֶׁמֻּתָּר לְהַדְלִיק מֵהֶן \u0006 \u0005(נ\"י הֲלָכוֹת קְטַנּוֹת)\u0006. \u0010g3\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011\nיֵשׁ מִי שֶׁאוֹמֵר שֶׁנֵּר שֶׁל בֵּית הַכְּנֶסֶת וְשֶׁל שַׁבָּת וְשֶׁל חֲנֻכָּה כֻּלָּם שֶׁל מִצְוָה הֵם \u0010y8\u0011 וּמֻתָּר לְהַדְלִיק זֶה מִזֶּה. \u0005 הַגָּה: וְהוּא הַדִּין נֵר שֶׁל ת\"ת אוֹ נֵר לְחוֹלֶה הַצָּרִיךְ נֵר \u0006 \u0005(נ\"י ה\"ק)\u0006 \u0005 וּבְעִנְיַן נֵר שֶׁל בֵּית הַכְּנֶסֶת עַיֵּן לְעֵיל סי' קנ\"ד סָעִיף י\"ד. \u0006 \u0010r4\u0011",{"g":["מימרא שבת כב וכרב וכמאן דאמר משום ביזוי מצוה רא\"ש בשם הרי\"ף כ\"כ הרמב\"ן","שם בשם בעל תרומות וכ\"כ הר\"ן וכשמואל","ת\"ה","\u0003טור בשם ספר התרומה:\u0004 "],"t":["\u0003זה מזה. \u0004 וכ\"ש שאם נכבה השמש שאין להדליקו מן נר חנוכה. וכתב רש\"ל שבבה\"כ אין חילוק בין השמש לשאר הנרות שכל הנרות שבתוכה קרויה נר מצוה ומש\"ה יש לגעור באותן שמדליקין נרותיה' ע\"י שפחות מנר בה\"כ חוץ ממוצאי שבת משום מבואות האפילות שעי\"כ זכה שאול למלכות. ונר של הבדלה קרוי נר של מצוה. אבל אחר שהבדיל עליה כבר נעשה המצוה ויכול להדליק ממנה דאפי' נר חנוכה אחר שיעורו שוב אינה קרויה נר מצוה עכ\"ל וע' סי' קנ\"ד:"],"s":["\u0003זה מזה. \u0004 עבה\"ט ועיין בשו\"ת בית יהודה סימן י\"ח שתמה ע\"ז דהא בש\"ס מוכח דמדליקין מנר לנר אפילו נר דמהדרים מנר מצוה הסמוך לו וא\"ל דמפרש נר של בית זה כו' וגם א\"ל דקאי לפי המנהג דסימן תרע\"א להדליק כ\"א מבני הבית דסוף סוף הוא בכלל המהדרים ע\"ש ובאמת דברי הרמ\"א הם מדברי הגמיי' והמרדכי:"],"m":["כתב המרדכי דנהגו להחמיר בנרות חנוכה וכ\"פ הג\"מ וז\"ל כתב ר\"ש אם כבה א' מהנרות אין להדליק' מהאחרים דאין בהדלק' זו מצוה דקי\"ל כבתה אין זקוק לה ע\"כ משמע דוקא בנרות חנוכה נהגו להחמיר ולא בנרות אחרים של מצוה וכ\"מ במרדכי עכ\"ל ד\"מ אבל במרדכי שלפנינו משמע דבכל נרות של מצוה נהגו להחמיר וכ\"מ בהגהות הר\"מ טיקטין ע\"ש וכ\"מ בתוספות ובהג\"מ הגדולים ע\"ש: \u0003דעיקר מצותו כו'\u0004. כלומר דבנר א' סגי לכל בני הבית:"],"r":["\u0003ס\"א ודוקא להדליק. \u0004כתי' ראשון בתוס' שם ד\"ה מאי הוה עלה דקי\"ל כרב:","\u0003ויש מתירין. \u0004כשמואל וכתי' שני בתוס' שם:","\u0003אא\"כ. \u0004גמרא שם גזירה שמא לא יכוין כו':","\u0003ונהגו. \u0004תוס' שם:","\u0003ס\"ב יש מי כו'. \u0004סה\"ת. ואזיל לשיטתו בס\"א אבל לסברא ראשונה בס\"א דביזוי מצוה אסור גם זה אסור שהמצות מבטלות זא\"ז כמ\"ש הר\"ן שלכך אפילו תשמיש של קדושה אשור להשתמש בפני נ\"ח ואע\"ג שהטעם שם משום ביזוי מצוה כמש\"ש בגמ' וכי נר קדושה כו' וכי דם כו' וער\"ן ולעיל סי' תרע\"ג ס\"א:"]}],["\u0010y0\u0011 הַדְלָקָה עוֹשָׂה מִצְוָה, וְלֹא הַנָּחָה, שֶׁאִם הָיְתָה מֻנַּחַת בִּמְקוֹמָהּ שֶׁלֹּא לְשֵׁם מִצְוַת חֲנֻכָּה, מַדְלִיקָהּ שָׁם וְאֵינוֹ צָרִיךְ לַהֲסִירָהּ וּלְהַנִּיחָהּ לְשֵׁם מִצְוַת \u0010y1\u0011 חֲנֻכָּה. לְפִיכָךְ עֲשָׁשִׁית שֶׁהָיְתָה דּוֹלֶקֶת כָּל הַיּוֹם, שֶׁהִדְלִיקָהּ מֵעֶרֶב שַׁבָּת לְמִצְוַת חֲנֻכָּה, לְמוֹצָאֵי שַׁבָּת \u0010y2\u0011 מְכַבָּהּ וּמַדְלִיקָהּ לְשֵׁם מִצְוָה; \u0010y3\u0011 וּמִכָּל מָקוֹם צָרִיךְ \u0010y4\u0011 שֶׁיַּדְלִיקֶנָּה בִּמְקוֹם הַנָּחָתָהּ, שֶׁאִם הִדְלִיקָהּ בִּפְנִים \u0010y5\u0011 וְהוֹצִיאָהּ לַחוּץ, לֹא יָצָא, שֶׁהָרוֹאֶה אוֹמֵר: לְצָרְכּוֹ הוּא מַדְלִיקָהּ; וְכֵן אִם מַדְלִיקָהּ \u0010y6\u0011 וְאוֹחֲזָהּ בְּיָדוֹ, בִּמְקוֹמָהּ, לֹא יָצָא, שֶׁהָרוֹאֶה אוֹמֵר: לְצָרְכּוֹ הוּא אוֹחֲזָהּ.\nיֵשׁ מִי שֶׁאוֹמֵר דְּכֵיוָן דְּהַדְלָקָה עוֹשָׂה מִצְוָה צָרִיךְ שֶׁיִּתֵּן שֶׁמֶן בַּנֵּר, כְּדֵי שִׁעוּר, קֹדֶם הַדְלָקָה, אֲבָל אִם בֵּרַךְ וְהִדְלִיק וְאַחַר כָּךְ הוֹסִיף שֶׁמֶן עַד כְּדֵי \u0010y7\u0011 שִׁעוּר, לֹא יָצָא יְדֵי חוֹבָתוֹ. \u0010y8\u0011\nאִשָּׁה מַדְלֶקֶת \u0010c0\u0011 נֵר \u0010y9\u0011 חֲנֻכָּה, שֶׁאַף הִיא חַיֶּבֶת בָּהּ; אֲבָל אִם הִדְלִיקָהּ חֵרֵשׁ שׁוֹטֶה וְקָטָן, לֹא עָשָׂה \u0010y10\u0011 כְּלוּם, \u0010y11\u0011 וְאַף עַל פִּי שֶׁהִנִּיחָהּ גָּדוֹל; \u0010y12\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר בְּקָטָן שֶׁהִגִּיעַ לְחִנּוּךְ, מֻתָּר. \u0005 הַגָּה: \u0010y13\u0011 וּלְדִידָן דְּכָל אֶחָד \u0010c1\u0011 מִבְּנֵי הַבַּיִת מַדְלִיק בִּפְנֵי עַצְמוֹ, קָטָן שֶׁהִגִּיעַ לְחִנּוּךְ צָרִיךְ לְהַדְלִיק \u0006 \u0005 גַּם כֵּן. \u0006",["\u0003הדלקה עושה מצוה\u0004 מדמברכינן אקב\"ו להדליק נר וכו'. ולפ\"ז גם בשבת ויו\"ט נמי דינא הכי וכמו שכתבנו לעיל בסי' רס\"ג סי\"א בהג\"ה:","\u0003לפיכך וכו'\u0004 ר\"ל שאם היינו סוברין שהנחה עושה מצוה היה צריך לכבותה ולהגביה ולהניחה לשם מצוה ולהדליקה אבל כיון שהדלקה עושה מצוה מדליקה כמות שהיא מונחת:","\u0003מכבה ומדליקה לשם מצוה\u0004 ואינו מועיל מה שהדליקה אתמול לשם מצוה דכל יומא ויומא מילתא באנפי נפשה היא:","\u0003ומ\"מ צריך וכו'\u0004 ר\"ל דלא תימא דלא איכפת לן בהנחה כלל ובאיזה ענין שידליק יצא קמ\"ל:","\u0003שידליקנה במקום הנחתה שאם וכו'\u0004 הנה בזמן הגמרא שהיה צריך להניח הנ\"ח על פתח ביתו מבחוץ הוא כפשטיה דצריך להדליק ג\"כ במקום ההנחה דהיינו מבחוץ ששם הוא מקום החיוב של פרסומי ניסא ואפילו כהיום שאנו מקילין ומדליקין בפנים בבית מ\"מ אינו יוצא באופן זה דצריך שיהיה הדלקת הנרות במקום שיניחם לבסוף משום דהרואה יאמר לצורכו הוא מדליקה ולפ\"ז פשוט דה\"ה אם הדליקה בחוץ והניחה בפנים ג\"כ אינו יוצא מטעם זה:","\u0003והוציאה לחוץ וכו'\u0004 וכתבו הפוסקים שאפילו היה ההדלקה והנחה במקום אחד בפנים או בחוץ ג\"כ יש ליזהר שלא לטלטל הנ\"ח ממקומן עד שיושלם השיעור של הדלקה דהיינו חצי שעה ויש מאחרונים שמקילין בזה וכתב הפמ\"ג דלכתחלה בודאי יש ליזהר בזה. ואפילו בנרות חנוכה שמדליקין בביהכ\"נ ג\"כ נכון ליזהר לכתחלה שלא לטלטלן ממקומן עד שיעור חצי שעה:","\u0003ואוחזה בידו וכו'\u0004 דעת הט\"ז דדוקא שאוחזה כל זמן מצותו אבל אם אוחזה בידו קצת זמן ואח\"כ מניחה כשהיא דולקת יצא אבל כמה אחרונים מפקפקין בזה ודעתם דאין לדלוק עד שיהיו מונחין תחלה במקומן:","\u0003לא יצא ידי חובתו\u0004 וצריך לכבותה וליתן בה שמן כשיעור ולחזור ולהדליק בלא ברכה:","\u0003אשה מדלקת\u0004 פי' בעד כל בני ביתה. ואפילו איש יכול לעשות אותה שליח להוציאו אם עומדין בשעה שמדלקת ושומעין הברכה ובדיעבד אם לא ענו אמן על הברכה ג\"כ יצאו וכן איש מברך לאשה ויוצאת ידי חובתה אם עומדת שם ושומעת הברכה לא בע\"א ועיין בתשובת עולת שמואל סימן ק\"ה דלדידן שמדליקין כ\"א בפ\"ע מ\"מ אשה אינה צריכה להדליק דהויין רק טפילות לאנשים ואם רוצים להדליק מברכות דהוי כשאר מ\"ע שהזמן גרמא דיכולות לברך וכשאין האיש בבית תדליק האשה דהוי בת חיובא ובברכה ולא ידליק קטן וכדלקמיה. כתב רש\"ל בתשובה סימן ע\"ז סומא אם הוא בבית שאחרים דולקין ויכול להשתתף בפריטי עמהם ויברכו עליו זה עדיף וכן אם יש לו אשה אשתו מדלקת עליו ואם הוא בבית מיוחד ואין לו אשה ידליק בעצמו ע\"י סיוע של אחר ועיין בשע\"ת דלא יברך וכ\"ש שאינו יכול להוציא אחרים:","\u0003שאף היא חייבת בה\u0004 שהנס היה גם להן שהגזירה היתה על כל בתולה הנישאת שתבעל להגמון תחלה וגם התשועה נעשה ע\"י אשה שבת יוחנן כ\"ג חתכה ראשו של ראש הצוררים:","\u0003כלום\u0004 אפילו אחרים עומדין ע\"ג דאין עליהן חיוב מצוה:","\u0003ואע\"פ שהניחה גדול\u0004 דהדלקה עושה מצוה ולא הנחה:","\u0003ויש מי שאומר וכו'\u0004 הנה לפי מה שסתם המחבר בסימן תרפ\"ט ס\"ב משמע דלמעשה אין לסמוך שיהיה הקטן יכול להוציא בהדלקתו לגדולים [אחרונים]:","\u0003ולדידן וכו'\u0004 ר\"ל דאף אם נימא להלכה דלא כהי\"א הנ\"ל ואינו יכול להוציא אחרים בהדלקתו מ\"מ הוא בעצמו כיון שהגיע לחינוך צריך להדליק ועיין בבה\"ל ונ\"ל דלקטן א\"צ להחמיר כולי האי ודי שידליק בכל לילה רק נר אחד לכו\"ע. כתבו האחרונים דגר ג\"כ יכול לומר שעשה נסים לאבותינו:"],["\u0003 אשה מדלקת וכו'\u0004 - עיין מ\"ב דיכולה להוציא אפילו בעלה אבל ידוע מה שארז\"ל בברכות דף כ' בן מברך לאביו ואשה מברכת לבעלה אבל אמרו חכמים תבא מארה לאדם שאשתו ובניו מברכין לו. ומה שאמר דקא מדליקי עלי בגו ביתאי מפני שלא היה אז בביתו ועיקר החיוב מונח על הבית:","\u0003 ולדידן דכל אחד וכו'\u0004 - עיין במ\"ב ועיין לקמן בסימן תרע\"ז במגן אברהם סק\"ח דהביא מש\"ג דס\"ל דאפילו לדידן שמדליקין נר לכאו\"א קטנים פטורין [דנהי דמחוייב לחנכו היינו בדבר שיש בו חיוב על הגדול מצד הדין אבל בזה דגם בגדול ליכא כ\"א משום הידור מצוה אינו מחוייב לחנך בו הקטן] ואח\"כ מצאתי במאירי שגם הוא כתב כן וז\"ל המהדרין במצות נר לכל אחד ואחד לפי מנין בני ביתו הגדולים עכ\"ל ומה שכתב שם המחה\"ש להשוות דעת הש\"ג עם דעת הרמ\"א הוא דוחק גדול. ובאמת מה שהמ\"א הביא שם ד\"ז משום דכתב מתחלה דלדעת המחבר מיירי ע\"כ שיש לו בית בפ\"ע להכי מסיים ואפשר דאפילו לדידן וכו' ואינו חייב אלא בשיש לו בית בפ\"ע:"],"\u0010y0\u0011 \u0010g0\u0011 הַדְלָקָה עוֹשָׂה מִצְוָה, וְלֹא הַנָּחָה, שֶׁאִם הָיְתָה מֻנַּחַת בִּמְקוֹמָהּ שֶׁלֹּא לְשֵׁם מִצְוַת חֲנֻכָּה, מַדְלִיקָהּ שָׁם וְאֵינוֹ צָרִיךְ לַהֲסִירָהּ וּלְהַנִּיחָהּ לְשֵׁם מִצְוַת \u0010y1\u0011 \u0010g1\u0011 חֲנֻכָּה. לְפִיכָךְ עֲשָׁשִׁית שֶׁהָיְתָה דּוֹלֶקֶת כָּל הַיּוֹם, שֶׁהִדְלִיקָהּ מֵעֶרֶב שַׁבָּת \u0010m0\u0011 לְמִצְוַת חֲנֻכָּה, לְמוֹצָאֵי שַׁבָּת \u0010y2\u0011 מְכַבָּהּ וּמַדְלִיקָהּ לְשֵׁם מִצְוָה; \u0010y3\u0011 וּמִכָּל מָקוֹם צָרִיךְ \u0010y4\u0011 \u0010m1\u0011 שֶׁיַּדְלִיקֶנָּה בִּמְקוֹם \u0010t0\u0011 \u0010s0\u0011 הַנָּחָתָהּ, שֶׁאִם \u0010g2\u0011 הִדְלִיקָהּ בִּפְנִים \u0010y5\u0011 וְהוֹצִיאָהּ לַחוּץ, לֹא יָצָא, \u0010m2\u0011 שֶׁהָרוֹאֶה אוֹמֵר: לְצָרְכּוֹ הוּא מַדְלִיקָהּ; \u0010g3\u0011 וְכֵן אִם מַדְלִיקָהּ \u0010y6\u0011 \u0010t1\u0011 וְאוֹחֲזָהּ בְּיָדוֹ, בִּמְקוֹמָהּ, לֹא יָצָא, שֶׁהָרוֹאֶה אוֹמֵר: לְצָרְכּוֹ הוּא \u0010g4\u0011 אוֹחֲזָהּ. \u0010r0\u0011\nיֵשׁ מִי שֶׁאוֹמֵר דְּכֵיוָן דְּהַדְלָקָה עוֹשָׂה מִצְוָה צָרִיךְ שֶׁיִּתֵּן שֶׁמֶן בַּנֵּר, כְּדֵי שִׁעוּר, קֹדֶם הַדְלָקָה, אֲבָל אִם בֵּרַךְ וְהִדְלִיק וְאַחַר כָּךְ הוֹסִיף שֶׁמֶן עַד כְּדֵי \u0010y7\u0011 שִׁעוּר, לֹא יָצָא יְדֵי חוֹבָתוֹ. \u0010y8\u0011 \u0010g5\u0011 \u0010t2\u0011 \u0010s1\u0011 \u0010m3\u0011\nאִשָּׁה מַדְלֶקֶת \u0010c0\u0011 נֵר \u0010y9\u0011 חֲנֻכָּה, שֶׁאַף הִיא חַיֶּבֶת בָּהּ; \u0010g6\u0011 אֲבָל אִם הִדְלִיקָהּ חֵרֵשׁ שׁוֹטֶה וְקָטָן, לֹא עָשָׂה \u0010y10\u0011 כְּלוּם, \u0010y11\u0011 וְאַף עַל פִּי שֶׁהִנִּיחָהּ גָּדוֹל; \u0010y12\u0011 \u0010g7\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר בְּקָטָן שֶׁהִגִּיעַ לְחִנּוּךְ, מֻתָּר. \u0005 הַגָּה: \u0010y13\u0011 וּלְדִידָן דְּכָל אֶחָד \u0010c1\u0011 מִבְּנֵי הַבַּיִת מַדְלִיק בִּפְנֵי עַצְמוֹ, קָטָן שֶׁהִגִּיעַ לְחִנּוּךְ צָרִיךְ לְהַדְלִיק \u0010t3\u0011 \u0006 \u0005 גַּם כֵּן. \u0006 \u0010r1\u0011",{"g":["מסקנת הגמרא שבת כ\"ג","מימרא דרבי יהושע בן לוי שם","מימרא דרבא שם","ג\"ז מימרא דרבא שם","הרא\"ש ומימרא דר' יהושע בן לוי שם","שאף הם היו באותו נס ופי' רש\"י שגזרו היונים על כל הבתולות הנישאות שיבעלו להגמון תחלה וע\"י האשה נעשה הנס","מסקנת הגמרא שם","הר\"ן בשם בעל העיטור"],"t":["\u0003הנחתה. \u0004 ויניחנה שם חצי שעה ד\"מ. ועבב\"י די\"א שבנרות בה\"כ מותר להדליקן במקום זה ולהניחן במקום אחר. ומ\"מ יש ליזהר לכתחלה מ\"א. ועט\"ז סעיף קטן א' ועיין בשבות יעקב חלק ב' סימן מ' מה שתמה עליו:","\u0003ואוחזה. \u0004 היינו כל זמן מצותן אבל אם אוחזו בידו קצת זמן ואח\"כ מניחה כשהיא דולקת יצא. ט\"ז ע\"ש:","\u0003אשה. \u0004 ומוציא' אפי' איש משא\"כ במגילה דהוי כמו קריא' התורה סמ\"ג וע' יד אהרן. ואדם שהדליק יכול להדליק לאשה ולברך כגון שעומדת אצלו בשעת הברכה או שמדלקת בעצמה. ב\"ח ע\"ש: סומא אם יכול להשתתף בפריטי מוטב ואם יש לו אשה אשתו מדלקת עליו ואם אין לו אשה ויש לו בית מיוחד מדליק על ידי סיוע של אחר דסומא חייב בכל המצות. תשובת רש\"ל סי' ע\"ו:","\u0003ג\"כ. \u0004 עיין בת' ש\"א סי' מ\"ב:"],"s":["\u0003הנחתה. \u0004 עבט\"ז שכת' מפרש\"י דומיא דמנורה כו' והשבו\"י תמה עליו דרש\"י קאמר לענין מדליקין מנר לנר אבל גם בשבת הדלקה עושה מצוה כדאמרינן בש\"ס מדמברכי' להדליק כו' ועיין במשבצות שהקשה כן וכת' שכבר העיר בזה בא\"ר ג\"כ ועיין בבר\"י ועבה\"ט ועיין בהלק\"ט סי' י\"ב שכת' העוקר נ\"ח ממקומה בתוך זמן הדלקה אפשר שלא יצא י\"ח שהרואה יאמר לצורכו הוא דאדלקה מתחלה עיין שם סימן ר\"פ נר חנוכה שהניחה בדלת רפוי' ומתנועעת אפשר דהרואה יאמר לצורכו הוא דאדלקה מאחר שאין הדלת קבוע עיין שם צ\"ע בזה ונראה דאם חוזר ומדליק במקום קבוע לא יברך:","\u0003אשה. \u0004 עבה\"ט ומה שכת' בשם רש\"ל דמדליק בעצמו על ידי סיוע אחר עיין במו\"ק שלא יברך ואצ\"ל שאינו מוציא אחרים עיין שם והביאו מח\"ב:"],"m":["\u0003למצות חנוכה\u0004. רבותא נקט:","\u0003שידליקנה במקום הנחתה\u0004. דיניחנ' שם חצי שעה ד\"מ וע' בב\"י די\"א שבנרות ב\"ה מותר להדליקן במקום זה ולהניחן במקום אחר ומ\"מ יש ליזהר לכתחלה:","\u0003שהרואה אומר וכו'\u0004. הקשה הב\"ח הא בגמרא אמרינן הטעם דהדלק' במקומ' בעינן כיון שהדלקה עושה מצוה וא\"כ מה צריך לטעם זה ותי' דבא לומר דאפי' לדידן שמדליקין בפנים אם הוציא' לחוץ לא יצא שהרואה אומר לצרכו הדליקה:","\u0003אשה מדלקת\u0004. פי' בעד כל בני הבית: סומא אם יכול להשתתף בפריטי מוטב ואם יש לו אשה מדלקת עליו ואם אין לו אשה ויש לו בית מיוחד מדליק ע\"י סיוע של אחר דסומא חייב בכל המצות ול\"ד לנר הבדלה דפטור דהתם בעינן שיאותו לאורו משא\"כ הכא דאיכא פרסומי' ניסא לאחרי' (תשו' רש\"ל סי' ע\"ז):"],"r":["\u0003ס\"א שהרואה כו'. \u0004כ' כן לדידן דמדליקין בפנים. ב\"ח ומ\"א. ואינו מדוקדק לשון במקום הנחתה כו' דהל\"ל להיפך הדליקה בחוץ והכניסה כו'. ונראה בזמן הטור שהיו מדליקין בפתח הבית ומ\"מ אם הדליק בפנים יצא שהרי לא עשו כדין הגמ' בלא\"ה:","\u0003ס\"ג ויש מי כו'. \u0004כ\"כ בע\"ה וכמ\"ש בירושלמי הנהיגו שיהא קטן קורא את המגילה כו'. והוא כדעת ר\"י במגילה י\"ט ב' וכמ\"ש שם בגמ' דבקטן כה\"ג מיירי וע' תוס' שם ד\"ה ור\"י כו'. ונראה טעמו שפסק כר\"י מכח קושיית תוס' שם וס\"ל דסוגיא דברכות פ\"ג דבן מברך לאביו וסוגיא דפסחים דר\"ש ור\"י דאמרי אגדתא כו' כולהו כר\"י והא דאינו מוציא בהלל ס\"ל כדעת ה\"ג דהלל דאורייתא אבל תוס' שם תי' דמיירי שהקטן אכל כדי שביעה דהוי נמי חד דרבנן וכ\"כ במרדכי שם וכן תי' בתי' שני בברכות ט\"ו א' בד\"ה ור\"י ועוד תי' שם דבהמ\"ז שאני כו' ע\"ש ומהא דפסחים תי' דסומא שאני שנתחייב כבר ועדיף מקטן וכמ\"ש הר\"ן בקדושין ספ\"ק בשם אגדה דלא היו סומים מתולדותם אבל בתוס' דר\"ה ל\"ד א' ד\"ה הא כו' לא כ\"כ ומשמע דס\"ל כדעת בע\"ה הנ\"ל שכ' שם ומיהו יש לדחות דרשות יכול להוציא בר חיובא דרבנן כמו קטן דמברך לאביו ועולה למנין שבעה ומוציא אחרים י\"ח במגילה לר\"י כו' ע\"ש שכ' לכן אמרו אגדתא וכן לכן קאמר ר\"י בפ\"ג דמגילה כל שלא ראה מאורות כו' משמע הא ראה פורס אע\"ג דפוטרו מכל מצות כו' אלא לפי דפריסת שמע מדרבנן יכול להוציא ולפי מ\"ש בתוס' דמגילה הנ\"ל דשאני סומא שהיה כבר מחיייב לכאורה לא היה קשה מהא דמגילה אבל ליתא דמשמע מדברי ר' יהודה דקא' דא\"' לפרוס משום דלא נהנה מעולם וכן פריך בגמ' שם לרבנן מ\"ט ומשני משום דר\"י ומשמע אבל בשאר מילי דרבנן מודה שיכול להוציא אף שלא ראה מעולם וע\"כ צ\"ל כמו שכ' תוס' בר\"ה שם. ומיהו בסומא אין נ\"מ לדינא דקי\"ל דלא כר\"י דסתם מתני' דפ' החובל דלא כוותיה כמש\"ש וכן הסוגיא דפסחים הנ\"ל דלא כוותיה ממש\"ש דסומא פטור מלומר הגדה דוקא ודקדקו שם מאן אמר אגדתא בי ר\"י ולא דקדקו על קידוש וש\"ד בכל השנה ועוד אסקינן שם דאפילו בהגדה חייבים וכ\"פ המרדכי בפ\"ב דמגילה ע\"ש ואין נ\"מ אלא בקטן:"]}],["הַמַּדְלִיק בְּלֵיל רִאשׁוֹן מְבָרֵךְ שָׁלֹשׁ בְּרָכוֹת: \u0010y0\u0011 לְהַדְלִיק נֵר חֲנֻכָּה, וְשֶׁעָשָׂה נִסִים, וְשֶׁהֶחֱיָנוּ; וְאִם לֹא בֵּרַךְ זְמַן בְּלֵיל רִאשׁוֹן, מְבָרֵךְ בְּלֵיל שֵׁנִי \u0010y1\u0011 אוֹ כְּשֶׁיִּזְכֹּר.\nמִלֵּיל רִאשׁוֹן וָאֵילָךְ מְבָרֵךְ \u0010y2\u0011 שְׁתַּיִם: לְהַדְלִיק, וְשֶׁעָשָׂה נִסִים. \u0005 הַגָּה: וִיבָרֵךְ כָּל הַבְּרָכוֹת \u0010y3\u0011 \u0010c0\u0011 קֹדֶם שֶׁיַּתְחִיל לְהַדְלִיק \u0006 \u0005(מַהֲרִי\"ל)\u0006.\nמִי שֶׁלֹּא הִדְלִיק \u0010y4\u0011 וְאֵינוֹ עָתִיד לְהַדְלִיק בְּאוֹתוֹ הַלַּיְלָה, \u0010y5\u0011 וְגַם אֵין מַדְלִיקִין עָלָיו בְּתוֹךְ בֵּיתוֹ, כְּשֶׁרוֹאֶה נֵר חֲנֻכָּה מְבָרֵךְ: שֶׁעָשָׂה נִסִים, וּבְלֵיל רִאשׁוֹן מְבָרֵךְ גַּם: שֶׁהֶחֱיָנוּ, וְאִם אַחַר כָּךְ בְּלֵיל ב' אוֹ ג' בָּא לְהַדְלִיק \u0010y6\u0011 אֵינוֹ חוֹזֵר וּמְבָרֵךְ: \u0010y7\u0011 שֶׁהֶחֱיָנוּ.\nאַחַר שֶׁהִדְלִיק, אוֹמֵר: הַנֵּרוֹת הַלָּלוּ אָנוּ מַדְלִיקִין עַל הַתְּשׁוּעוֹת וְעַל הַנִּסִים וְעַל הַנִּפְלָאוֹת וְכו'.\nיַתְחִיל לְהַדְלִיק בְּלֵיל רִאשׁוֹן \u0010y8\u0011 בַּנֵּר הַיּוֹתֵר יְמִינִי, וּבְלֵיל ב' כְּשֶׁיּוֹסִיף \u0010c1\u0011 נֵר אֶחָד סָמוּךְ לוֹ יַתְחִיל וִיבָרֵךְ עַל הַנּוֹסָף, שֶׁהוּא יוֹתֵר שְׂמָאלִי, \u0010y9\u0011 כְּדֵי לְהַפְנוֹת לַיָּמִין; \u0010c2\u0011 וְכֵן בְּלֵיל ג' כְּשֶׁיּוֹסִיף עוֹד אַחֵר סָמוּךְ לִשְׁנֵי נֵרוֹת הָרִאשׁוֹנוֹת, יַתְחִיל בַּנּוֹסָף וּבוֹ יַתְחִיל הַבְּרָכָה, וְאַחַר כָּךְ יִפְנֶה לְצַד יָמִין, \u0010y10\u0011 וְכֵן בְּכָל לַיְלָה; נִמְצָא שֶׁתָּמִיד מְבָרֵךְ עַל הַנּוֹסָף שֶׁהוּא מוֹרֶה עַל הַנֵּס, שֶׁהֲרֵי בְּתוֹסֶפֶת הַיָּמִים נִתּוֹסֵף הַנֵּס.",["\u0003להדליק נר חנוכה\u0004 בגמרא וכל הפוסקים איתא נר של חנוכה וכ\"כ המהרש\"ל אך שכתב שיאמר שלחנוכה במילה אחת ולא של חנוכה שתי מילות. והעולם אין נוהגין להקפיד בזה [פמ\"ג]. בזמן הזה ולא ובזמן. והגיענו לזמן הזה הלמ\"ד בחיר\"ק ולא בפת\"ח:","\u0003או כשיזכור\u0004 ר\"ל כשיזכור בשאר הלילות בשעת ההדלקה [לבוש] ואם נזכר אחר ההדלקה אינו מברך בלילה זו עוד:","\u0003שתים להדליק ושעשה נסים\u0004 דנס כל יומא איתא שהרי כל שמנה ימים הדליקו מן הפך אבל זמן משהגיענו להתחלת הזמן הגיענו:","\u0003קודם שיתחיל להדליק\u0004 דבעינן שיהיו הברכות עובר לעשייתן. הדליק נר חנוכה ושכח לברך על הדלקתה ורק קודם שהדליק כולן נזכר דעדיין לא בירך יש לו לברך כל הברכות [ת' רע\"א מ\"ת סי\"ג] עוד כתב שאם נזכר לאחר שהדליק כולם אין לו לברך ברכת להדליק רק ברכת שעשה נסים וכן ברכת שהחיינו יש לו לברך:","\u0003ואינו עתיד להדליק באותו הלילה\u0004 אבל אם ידליק אח\"כ לא יברך אראיה כיון דיוכל לברך אח\"כ על ההדלקה:","\u0003וגם אין מדליקין וכו'\u0004 ויש פוסקים דסברי דאפילו יודע שמדליקין עליו בביתו כיון דהוא בעצמו אינו מדליק וגם אינו משתתף עם אחרים בפריטי צריך לברך על הראיה להודות על הנס וגם לברך אז שהחיינו ומ\"מ אינו כדאי לעשות כן למעשה דספק ברכות להקל:","\u0003אינו חוזר וכו'\u0004 משום דהלא בירך מאתמול כשראה הנרות. ואם באתמול לא בירך כלל משום דסמך על אשתו שמדלקת בביתו וכפי מה דמוכח מדברי המחבר דאם אשתו מדלקת עליו בתוך ביתו חשוב כמו שהדליק בעצמו ע\"כ אם בא בליל שני לביתו ומדליק אינו צריך לברך ברכת שהחיינו:","\u0003אחר שהדליק וכו'\u0004 אחר שהדליק נר הראשון שהוא העיקר אומר הנרות הללו ויגמור ההדלקות בעוד שאומר הנרות וכו' ובנוסח הנרות יש ל\"ו תיבות נגד הנרות של חנוכה מלבד אלו שני תיבות הנרות הללו כלומר הנרות הללו הם ל\"ו עכ\"ל רש\"ל [ובשני תיבות הנרת הללו יש ח' אותיות רמז לח' ימי חנוכה] ומ\"מ מי שנוהג לומר הנרות הללו לאחר שהדליק הכל נמי שפיר דמי [פמ\"ג]:","\u0003בנר היותר ימיני וכו'\u0004 יתחיל ויברך על הנוסף וכו'. ואין חילוק בין שמניח מימין הפתח ובין שמניח משמאל הפתח תמיד יתחיל הברכה בנר הנוסף [ב\"י] וי\"א דאם מונח בימין הפתח אזי צריך להתחיל תמיד בנר הימיני שהוא סמוך לפתח והולך מימין לשמאל ואם מניח הנרות בשמאל הפתח צריך להדליק ג\"כ תמיד תחילה הנר הסמוך להפתח והולך ומדליק משמאל לימין ודעביד כמר עביד ודעביד כמר עביד ומה טוב ונכון אם יכול לסדר כולם בתוך חלל הפתח שיהיו כולם שוין בטפח הסמוך לפתח אכן יזהר שלא יפתח הפתח במשך חצי שעה שהנרות דולקין שלא יכבם הרוח ועיין במה שכתבנו בבה\"ל דעת הט\"ז בענין זה:","\u0003כדי להפנות לימין\u0004 כמו שאחז\"ל כל פינות שאתה פונה לא יהא אלא דרך ימין:","\u0003וכן בכל לילה וכו' מברך על הנוסף וכו'\u0004 וה\"ה כשמדליק בחלון או בחלל הפתח או בבהכ\"נ בליל ראשון ידליק בתחלה בנר היותר ימיני ובליל שני ביותר שמאלי וכן בליל ג' וד' עד יום שמיני הכל ידליק בנר הנוסף ואח\"כ פונה והולך לצד ימין ובכל זה ירחיק א\"ע לצד שמאל בעת ההדלקה כדי שיפגע בו תחלה ולא יצטרך להעביר על המצות. ולדעת הי\"א הנ\"ל גם בזה יברך תמיד על הנר הראשון שהוא עיקר המצוה. ונראה דבזה יעמיד הנר הראשון לצד שמאל ואח\"כ בכל יום מוסיף והולך לצד ימין וההדלקה יהיה תמיד בנר שעומד בצד שמאל כמו שכתבנו ופונה והולך לצד ימין:"],["\u0003 ויברך כל הברכות\u0004 - ואין נ\"מ בין לילה ראשונה לשאר הלילות [ב\"י וד\"מ]:","\u0003 ובליל ב' כשיוסיף וכו'\u0004 - ביאור הענין דלדעת המחבר יש מעלה יותר אם נתחיל להדליק בנר הנוסף שעי\"ז נוכל לקיים מה שאחז\"ל כל פינות שאתה פונה לא יהא אלא דרך ימין וגם שהוא מורה על תוספות הנס ואף שעי\"ז נדחה מה שאמרו דלכתחלה מצוה להתחיל בטפח הסמוך לפתח אין לחוש לזה וטעם הי\"א שכתבתי בפנים עיין בשעה\"צ:","\u0003 כדי להפנות לימין\u0004 - עיין מ\"ב ודעת הלבוש והט\"ז דכונת הגמרא היפך מזה דהיינו שנלך מימין לשמאל [וראית המגן אברהם לנגד שיטה זו כבר דחוה האחרונים עיין בשע\"ת] ולפ\"ז פסק הט\"ז באופן זה דהיינו היכא שיש מזוזה שצריך לסדרם משמאל הכניסה אצל הכותל יסדרם בטפח הסמוך לפתח ויתן בלילה הראשון הנר אצל הפתח ובלילה שניה יתן הנר הנוסף לצד חלל הבית דהיינו שהנר הנוסף יהי' לימינו ונר הראשון יהי' לשמאלו ויתחיל להדליק מן נר הנוסף וידליק מן ימין לשמאל וכן בלילה שלישית כשמוסיף עוד נר יהיה הוא לימינו ונרות הראשונים לשמאלו ויתחיל להדליק מן נר הנוסף וילך מן ימין לשמאל. והיכא שמסדרם בחלל הפתח או בחלון או בבהכ\"נ יסדר בלילה הראשונה בקצה השורה הנר לשמאלו ובלילה שניה יתן אצלו הנר הנוסף לימינו ונר הראשון יהיה לשמאלו ויתחיל להדליק מן נר הנוסף שהוא לימינו וילך מן ימין לשמאל וכן בכל לילה כשיתן נר הנוסף ידליק ממנו וילך מן ימין לשמאל עד שבליל שמיני הנר הנוסף הוא בקצה השורה לימינו וידליק ג\"כ אותו בתחלה וילך מן ימין לשמאל וא\"כ צריך לעמוד אחוריו לצפון ופניו לדרום ועיין בפמ\"ג שכתב שהוא נהג כהט\"ז נמצא שיש לנו ג' שיטות דעת המחבר ודעת רש\"ל והגר\"א ודעת הט\"ז וכל אחד יעשה כמנהגו ואף שבח\"א לא נזכר כ\"א שיטת השו\"ע ושיטת המהרש\"ל מ\"מ אין לדחות ג\"כ שיטת הט\"ז אחרי שהפמ\"ג והדה\"ח העתיקוהו להלכה ואי נ\"מ בכל זה בעצם המצוה דבכל גווני יוצא לכו\"ע רק לענין לכתחלה באיזה מקום נכון יותר להתחיל להדליק ממנו:"],"\u0010g0\u0011 הַמַּדְלִיק בְּלֵיל רִאשׁוֹן מְבָרֵךְ שָׁלֹשׁ בְּרָכוֹת: \u0010y0\u0011 \u0010t0\u0011 \u0010s0\u0011 לְהַדְלִיק נֵר חֲנֻכָּה, וְשֶׁעָשָׂה נִסִים, \u0010g1\u0011 וְשֶׁהֶחֱיָנוּ; וְאִם לֹא בֵּרַךְ זְמַן בְּלֵיל רִאשׁוֹן, מְבָרֵךְ בְּלֵיל שֵׁנִי \u0010y1\u0011 אוֹ \u0010g2\u0011 כְּשֶׁיִּזְכֹּר. \u0010r0\u0011\nמִלֵּיל רִאשׁוֹן וָאֵילָךְ מְבָרֵךְ \u0010y2\u0011 שְׁתַּיִם: לְהַדְלִיק, וְשֶׁעָשָׂה נִסִים. \u0005 הַגָּה: וִיבָרֵךְ כָּל הַבְּרָכוֹת \u0010y3\u0011 \u0010c0\u0011 קֹדֶם שֶׁיַּתְחִיל לְהַדְלִיק \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0010g3\u0011 \u0010r1\u0011\nמִי שֶׁלֹּא הִדְלִיק \u0010y4\u0011 וְאֵינוֹ עָתִיד לְהַדְלִיק בְּאוֹתוֹ הַלַּיְלָה, \u0010y5\u0011 וְגַם \u0010m0\u0011 אֵין מַדְלִיקִין עָלָיו בְּתוֹךְ בֵּיתוֹ, כְּשֶׁרוֹאֶה נֵר חֲנֻכָּה מְבָרֵךְ: שֶׁעָשָׂה נִסִים, וּבְלֵיל רִאשׁוֹן מְבָרֵךְ גַּם: \u0010g4\u0011 שֶׁהֶחֱיָנוּ, וְאִם אַחַר כָּךְ בְּלֵיל ב' אוֹ ג' בָּא לְהַדְלִיק \u0010y6\u0011 \u0010t1\u0011 \u0010m1\u0011 אֵינוֹ חוֹזֵר וּמְבָרֵךְ: \u0010y7\u0011 \u0010g5\u0011 שֶׁהֶחֱיָנוּ. \u0010r2\u0011 \u0010r3\u0011\nאַחַר שֶׁהִדְלִיק, \u0010m2\u0011 אוֹמֵר: הַנֵּרוֹת \u0010t2\u0011 הַלָּלוּ אָנוּ מַדְלִיקִין עַל הַתְּשׁוּעוֹת וְעַל הַנִּסִים וְעַל הַנִּפְלָאוֹת וְכו'. \u0010g6\u0011\nיַתְחִיל לְהַדְלִיק בְּלֵיל רִאשׁוֹן \u0010y8\u0011 \u0010m3\u0011 בַּנֵּר הַיּוֹתֵר \u0010t3\u0011 \u0010s1\u0011 יְמִינִי, וּבְלֵיל ב' כְּשֶׁיּוֹסִיף \u0010c1\u0011 נֵר אֶחָד סָמוּךְ לוֹ יַתְחִיל וִיבָרֵךְ עַל הַנּוֹסָף, שֶׁהוּא יוֹתֵר שְׂמָאלִי, \u0010y9\u0011 כְּדֵי \u0010m4\u0011 לְהַפְנוֹת לַיָּמִין; \u0010c2\u0011 וְכֵן בְּלֵיל ג' כְּשֶׁיּוֹסִיף עוֹד אַחֵר סָמוּךְ לִשְׁנֵי נֵרוֹת הָרִאשׁוֹנוֹת, יַתְחִיל בַּנּוֹסָף וּבוֹ יַתְחִיל \u0010t4\u0011 \u0010s2\u0011 הַבְּרָכָה, וְאַחַר כָּךְ יִפְנֶה לְצַד יָמִין, \u0010y10\u0011 וְכֵן בְּכָל לַיְלָה; נִמְצָא שֶׁתָּמִיד מְבָרֵךְ עַל הַנּוֹסָף שֶׁהוּא מוֹרֶה עַל הַנֵּס, שֶׁהֲרֵי בְּתוֹסֶפֶת הַיָּמִים נִתּוֹסֵף הַנֵּס. \u0010r4\u0011 \u0010r5\u0011",{"g":["מימרא דרב יהודה שבת כג","טור בשם תשו' אביו הרא\"ש","שם במימרא הנזכרת","שם וכפי' רש\"י בשם רבינו יעקב","תשובת אשכנזים","טור בשם מ\"ס","מהרי\"ק בשורש קכ\"ד ע\"ש המרדכי בפ\"ב דשבת בשם ר' מאיר"],"t":["\u0003להדליק. \u0004 וכ\"כ האר\"י ז\"ל. וע' של\"ה שי\"ל שלחנוכה תיבה א' וע' בהלק\"ט ח\"א סי' ג' אם שכח והדליק נר א' פחות מן הראוי ידליק עוד ולא יברך כי הברכ' שעש' בתחל' על חיוב כל הנרות עשה ב\"י סי' תרע\"ב. מ\"א ע\"ש:","\u0003אינו. \u0004 וה\"ה אם אשתו הדליק' עליו בראשון עמ\"א:","\u0003הנרות. \u0004 אחר שהדליק נר הראשון אומר הנרות ויהיו ל\"ו תיבות מלבד ב' תיבות הראשונות רמז למנין הנרות רש\"ל ובשני תיבות הנרות הללו יש ח' אותיות רמז לח' ימי חנוכ':","\u0003ימיני. \u0004 בת\"ה סי' ק\"ו כתב דבני ריינוס מתחילין להדליק בנר יותר שמאל ופונה לצד ימין מטעם כל פינות וכו' וכן עשה מהר\"ם. ובני אוסטרייך מתחילין לצד ימין ומדליקין כדרך שאנו בני ברית כותבין וכתב שם להשוות הדיעות האלו דבמקום שאין מזוזה בחדר ממילא צריך להדליק בימין הכניס' בצד הטפח הסמוך לפתח וא\"כ הנר שהוא כנגד ימינו הוא הסמוך לפתח לעולם ובו צריך להתחיל שהוא עקר המצו' דבדידיה לחוד הוי סגי אי לא הוי בעי למהוי מן המהדרין אבל בני ריינו\"ס מיירי שיש לו מזוז' בחדרו וא\"כ הוא צריך להדליק בשמאל הכניס' וא\"כ נר הסמוך לפתח לעולם נגד שמאלו. וא\"ת א\"כ מה צריך מהר\"ם לטעם דכל פינות וכו' תיפוק לי' משום ה\"ט דצריך להדליק תחל' בטפח הסמוך לפתח וי\"ל דנ\"מ אם היו הנרות מסודרים מצד הפתח לצד דופן שכנגד הפתח כגון אם הפתח במזרח והנרות מסודרים ממזרח למערב שאז צריך להפוך פניו לדרום ולהתחיל בנר שסמוך לפתח ולא יהפוך פניו לצפון ויתחיל באותו הנר משום דכל פינות וכו' עכ\"ל. וכתב ב\"י על זה ונרא' שמנהג בני ריינו\"ס הוא הנכון שצריך להדליק כל לילה על הנר הנוסף וכמו שכתב כאן בש\"ע ואין לחלק בין היכא שהנרות בימין הכניס' להיכא שהם בשמאל הכניסה וכן אנו נוהגים עכ\"ל. \u0005(והנה במ\"א כתב דמהרי\"ל ומהרי\"ו מיירי כשאוכל בחדר בפני עצמו ואינו נכון עיין אליה רבה ומבואר בב\"ח ובשכנה\"ג דהמשתתף צריך לשמוע הברכות מהמברך דאם לא כן צריך לברך על הראי')\u0006 וכתב רש\"ל המדקדק יניח באורך כשפוד שיהא כולן שווין בטפח הסמוך לפתח ויתחיל בשמאל ויפנה לימין וכ\"פ הב\"ח. וכ\"כ הט\"ז נהגתי בעצמי הדרך היותר נכון לסדר הנרות באורך סמוך להפתח כמ\"ש רש\"ל כדי שיהיו כל הנרות בטפח הסמוך לפתח ולהדליק בליל' ראשונ' בנר שאצל הכותל ובליל שני יוסיף לו נר שני סמוך לו לצד חלל החדר ויתחיל בנר הנוסף ויסיים בנר שאצל הכותל וכן בכל לילה שאח\"כ יוסיף נר אחד לצד חלל החדר ויתחיל בו ויסיים באותו שאצל הכותל. ואם אי אפשר לסדר כן יסדר אותם על הכותל כשור' מצד ימין הפתח ואע\"פ שהאחרים שיוסיף לא יהיו כולם בטפח הסמוך לפתח אין חשש בזה כיון שהנר הראשון הוא באותו טפח סגי ויתחיל בכל ליל' בנוסף שהוא ימין המזומן בפני האדם וידליק אח\"כ עד נר שאצל הכותל כנ\"ל נכון עכ\"ל ע\"ש. ומט\"מ כתב בשם רש\"ל שיניחם בתוך חלל הפתח כמו המזוז' ע\"ש:","\u0003הברכ'. \u0004 ואם הדליק ולא בירך יש לו לברך על השאר וכל זמן שעוסק יש לו לברך הלק\"ט חלק א' סימן ג' ע\"ש:"],"s":["\u0003להדליק עבה\"ט \u0004 דבשבת אומרים נר של שבת לפי שנ\"ח אסור להשתמש לאורה ולזה אמר נ\"ח להורות כי הנר אינו כ\"א למצות חנוכה משא\"כ בנר של שבת הכונה שאנו משתמשין בו ונרו יאיר לתועלתינו וזה הנר המאור הוא של שבת ע\"ש ועיין בא\"ר ובמח\"ב כת' עוד טעם דבחנוכה אין מצות המעשה רק בנר לבד משא\"כ שבת שיש בה מצות מעשיות קידוש סעודה כו' ונר גם כן אחד מהם שייך לומר נר של שבת הנודע בכמה ענינים מבלעדי הנר עיין שם ועיין בכנה\"ג בשם איגרת הרמב\"ם שהגר יכול לומר שעשה ניסים לאבותינו ואם רצה לומר שעשה ניסים לישראל יאמר עיין שם ועיין לעיל סימן תע\"ג בשם אה\"ח פרשת בהעלותך שגר יכול לומר כל סדר ההגדה עבדים היינו כו' עיין שם:","\u0003ימיני. \u0004 עבה\"ט ועיין בפמ\"א ח\"א ס\"ס צ\"ח שכת' על ראיית מג\"א מיומא דף נ\"ט שאין ראיה דיש לומר דשפיר כהלבוש להדליק מימין לשמאל כדרך הכתיבה דהתם נמי גבי מתנות מזבח הפנימי י\"ל דמה שמושך ידיו אליו כדרך הכתיבה הוי דרך ימין ומה שמושך ידו מנגד גופו והלאה הוי דרך שמאל עיין שם:","\u0003הברכה. \u0004 עבה\"ט ומ\"ש וכל זמן שעוסק כו' משמע קצת דאף לאחר שהדליק כולם אלא שעדיין עוסק שם בתיקון הפתילות וכיוצא בו יכול לברך וז\"א כמבואר ביו\"ד סי' י\"ט דלהש\"ך לא יברך אחר השחיטה כלל כשלא בירך קודם. ולהפר\"ח מצי לברך תוך כ\"ד של השחיטה וכן מבואר לעיל סי' תל\"ב דלאחר סיום הבדיקה אין לברך ועיין סימן קס\"ז סעיף ח' ובסימן תרמ\"ם ס\"ק י\"ב ובסימן תרנ\"א ס\"ק י\"ח (ע' שם שכת' שאם שכח לברך קודם הלקיחה מברך עדיין ועיין בפ\"מ שם שכת' שיש לה משך זמן שצריך לנענע ובא\"ר כ' דלהרבה פוסקים מיקרי זה עובר לעשייתן דכל זמן שהוא בידו עדיין הוא עוסק במצותו עיין שם ואין זה ענין לכאן דהתם טכסיס הברכה על הלקיחה וכל זמן שהוא בידו חד לקיחה היא משא\"כ כאן שטכסיס הברכה להדליק וכל שהדליק מיד גמר מצותו ואפשר דגם כאן אם העסק בענין שאם לא היה מתקן היה עומד לכבות מיד שפי' יכול לברך דהו\"ל כלא הדליק עדיין כלל כיון שהיתה עתידה לכבות מהדלקה זו ובכה\"ג ודאי כבתה זקוק לה ואפשר דגם הכנה\"ג ועט\"ז שהביאו בסימן תרע\"ג ס\"ק י\"א מודים בזה דחוזר ומדליק בברכה דהתם כת' הט\"ז מדליק במקום שהרוח מצויה דשמא דמי לשמנים שאין נמשכים אחר הפתילה עיין שם והתם ג\"כ אינו בירור רק חשש שלא ימשך היטב ויכבה או שלא יעמוד ברוח אבל עכ\"פ ההדלקה עצמה היתה כראוי משא\"כ בזה דבשעת הדלקה גופה ידוע שלא תהיה דולקת בלא התיקון וברכה לבטלה היא אם אינו מתקן ובכה\"ג מסתברא שיוכל לברך אחר ההדלקה קודם התיקון דתיקון זה בודאי שייך להדלקה וכאילו לא הדליק דמי) אך בהלק\"ט שם כת' וז\"ל שאלה אם הדליק הראשון ולא בירך אם יברך על השאר:\nתשו' אפשר כ\"ז שעוסק בהידור מצוה יש לו לברך עכ\"ל ור\"ל דהיינו כ\"ז שהוא עוסק בהדלקת שאר הנרות שהם הידור המצוה כדקי\"ל המהדרים מוסיף והולך שפיר מברך אבל לא מיירי אחר שהשלים הדלקת כל הנרות דאז לא יברך אף שעדיין עסק בהם אם לא שעוסק בתיקון הפתילות שידוע שאי אפשר להיות דולקת בלא תיקון זה וכמש\"ל:"],"m":["שלחנוכה תיבה א' (רש\"ל) וע' הטעם בשל\"ה וכ\"כ מט\"מ, בזמן הזה ולא ובזמן, לזמן הזה למ\"ד בחיר\"ק [רש\"ל מט\"מ], אם שכח והדליק נר א' פחו' מן הראוי ידליק עוד ולא יברך כי הברכ' שעשה בתחלה על חיוב כל הנרות עשה [ב\"י סי' תרע\"ב א\"ח ד\"מ] ועמ\"ש ססי' תרנ\"א: \u0003אין מדליקין עליו\u0004. ורש\"ל פסק דאע\"פ שהדליקו עליו צריך לברך אבל המשתתף בפריטי ושומע ברכה מבע\"ה א\"צ לברך (ב\"ח וכ\"מ ברא\"ש) ומ\"מ נ\"ל דספק ברכות להקל וכ\"מ בתוס' (סוכה דף מ\"ו) שהקשו למה תקנו בחנוכה ברכה לרואה (ולמה לא תירצו דשאני נ\"ח דאיכא מצוה בראיה) משא\"כ בלולב וסוכ' דאין מצוה בראייתן אלא בישיבתן בה:","\u0003אינו חוזר וכו'\u0004. אבל אם אשתו הדליק' עליו בראשון צריך לברך בליל שני שהחיינו דאשתו אינה פוטרת גופו אלא ביתו [ב\"ח] ול\"נ פשוט דלהפוסקים כשאשתו מדלק' עליו א\"צ לברך על הראי' א\"כ ה\"ה דא\"צ לברך שהחיינו כשמדליק וכ\"מ בר' זירא דסמך על אשתו ואי ס\"ד לא לפטר גופו אם כן ה\"ל להשתתף ליפטור גופו אלא ע\"כ נפטר לגמרי וכ\"מ מהרי\"ל סי' קנ\"ז [עמ\"ש סי' תרע\"ז] וכ\"כ הע\"ש בשם כ\"ג מה\"ב:","\u0003אומר הנרות וכו'\u0004. אחר שהדליק נר ראשון אומר הנרות ויהיו ל\"ו תיבו' מלבד ב' תיבות הראשונו' רמז למנין הנרו' [רש\"ל] ובהני תיבות הנרת הללו יש ח' אותיות רמז לח' ימי חנוכ':","\u0003בנר היותר ימיני\u0004. ואין חילוק בין אם מדליק בימין הפתח או בשמאל הפתח [ב\"י] אבל רש\"ל כ' דכשהם מונחים לימין הפתח צריך להתחיל בנר הימיני שהוא סמוך לפתח והמדקדק יניח' באורך כשפוד שיהא כולן שוין בטפח הסמוך לפתח ויתחיל בשמאל ויפנה לימין וכ\"כ הב\"ח ומט\"מ כ' בשם רש\"ל שיניחם בתוך חלל הפתח כמו המזוזה: כתב הב\"ח מ\"כ אדם שהדליק יכול להדליק לאשה ולברך וכגון שעומדת אצלו בשעת הברכה אבל בע\"א אין לברך כיון שהמצוה מוטלת על גוף האדם עכ\"ל ועסי' ח' מ\"ש בשם הג\"מ דמשמע דאחר יכול לברך והיא תדליק ועמ\"ש סי' תל\"ב ס\"ב, כ' הב\"ח כשאחר מברך יברך על הדלקת נר חנוכ' עכ\"ל ובר\"ן פ\"ק דפסחים גבי הפרשת תרומות לא משמע הכי:","\u0003להפנות לימין\u0004. וכ\"ה ביומא דף נ\"ח דזה מקרי דרך ימין וכ\"ה בתשו' מהרי\"ל סי' מ':"],"r":["\u0003ס\"א ואם לא בירך. \u0004עירובין מ' ב':","\u0003ס\"ב ויברך כל. \u0004ר\"ל אף שעשה ושהחיינו צריך עובר לעשייתן כמ\"ש בפ\"ב דמגילה ל\"ש אלא לאחריה כו' כל המצות כולן כו' לפניה מאי כו':","\u0003ס\"ג וגם אין. \u0004ר\"ן וטור וע\"ש בר\"ן אבל במרדכי לא משמע כן וע\"ש וכ\"נ דעת רש\"י:","\u0003ואם אח\"כ. \u0004עירובין שם:","\u0003ס\"ה יתחיל. \u0004במרדכי כת' שידליק משמאל לימין כמ\"ש בזבחים כל פינות כו':","\u0003ויברך על הנוסף. \u0004מהרי\"ק. ואין לו טעם וריח שזה אינו רק למהדרים מן המהדרים ויניח עיקר המצוה ויברך על הרשות וע' סי' תרע\"ד ס\"א בהג\"ה וגם משום פינות לימין יבטל עיקר המצוה טפח הסמוך לפתח אלא העיקר שיתחיל בנר הסמוך לפתח בין מדליק בימין הפתח או בשמאל ויברך כל הלילות עליו ובזה מדליק ומברך תמיד על סמוך לפתח ועל עיקר המצוה ועמ\"א בשם רש\"ל אבל מ\"ש שיניח כשפוד לא נראה:"]}],["\u0010y0\u0011 אַכְסְנַאי \u0010y1\u0011 שֶׁאֵין מַדְלִיקִין עָלָיו בְּבֵיתוֹ, צָרִיךְ \u0010y2\u0011 לָתֵת פְּרוּטָה \u0010c0\u0011 לְבַעַל הַבַּיִת \u0010y3\u0011 לְהִשְׁתַּתֵּף \u0010c1\u0011 עִמּוֹ \u0010c2\u0011 בַּשֶּׁמֶן שֶׁל נֵר \u0010y4\u0011 חֲנֻכָּה; וְאִם יֵשׁ לוֹ \u0010y5\u0011 פֶּתַח \u0010c3\u0011 פָּתוּחַ \u0010y6\u0011 \u0010c4\u0011 לְעַצְמוֹ, \u0010y7\u0011 \u0010c5\u0011 צָרִיךְ לְהַדְלִיק בְּפִתְחוֹ, \u0010y8\u0011 אַף עַל פִּי שֶׁאוֹתוֹ בַּיִת אֵינוֹ מְיֻחָד אֶלָּא לְשֵׁנָה וְהוּא אוֹכֵל עַל שֻׁלְחַן בַּעַל הַבַּיִת, וְהוּא הַדִּין לְבֵן \u0010y9\u0011 הָאוֹכֵל אֵצֶל אָבִיו. \u0005 הַגָּה: \u0010y10\u0011 וְיֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה שֶׁמַּדְלִיקִים בִּפְנִים מַמָּשׁ, יַדְלִיק \u0010y11\u0011 בַּמָּקוֹם שֶׁאוֹכֵל, \u0010c6\u0011 וְכֵן נָהֲגוּ \u0006 \u0005(תְּשׁוּבַת רַשְׁבָּ\"א סי' תקמ\"ב)\u0006. \u0010y12\u0011\nקָטָן שֶׁהִגִּיעַ לְחִנּוּךְ צָרִיךְ לְהַדְלִיק.\nיֵשׁ אוֹמְרִים שֶׁאַף עַל פִּי שֶׁמַּדְלִיקִין עָלָיו בְּתוֹךְ בֵּיתוֹ, אִם הוּא בְּמָקוֹם שֶׁאֵין בּוֹ יִשְׂרָאֵל מַדְלִיק בִּבְרָכוֹת. \u0005 הַגָּה: \u0010y13\u0011 כִּי חַיָּב לִרְאוֹת הַנֵּרוֹת \u0006 \u0005(מָרְדְּכַי)\u0006, \u0005 וְכֵן נוֹהֲגִין; וַאֲפִלּוּ אִם הוּא אֵצֶל יְהוּדִים וְרוֹאֶה הַנֵּרוֹת, \u0010y14\u0011 אִם רוֹצֶה לְהַחְמִיר עַל עַצְמוֹ וּלְהַדְלִיק \u0010c7\u0011 בִּפְנֵי עַצְמוֹ, מַדְלִיק \u0006 \u0005 וּמְבָרֵךְ עֲלֵיהֶם, \u0010y15\u0011 וְכֵן נוֹהֲגִין \u0006 \u0005(ת\"ה וּמַהֲרִי\"ל וּתְשׁוּבַת מַהֲרִי\"ל סי' קמ\"ה)\u0006. \u0010y16\u0011\nהַנּוֹתָר בַּיּוֹם הַשְּׁמִינִי \u0010y17\u0011 מִן הַשֶּׁמֶן \u0010c8\u0011 הַצָּרִיךְ \u0010c9\u0011 לְשִׁעוּר הַדְלָקָה, עוֹשָׂה לוֹ מְדוּרָה \u0010y18\u0011 וְשׂוֹרְפוֹ בִּפְנֵי עַצְמוֹ שֶׁהֲרֵי הֻקְצָה לְמִצְוָתוֹ; וְאִם נִתְעָרֵב בְּשֶׁמֶן אַחֵר וְאֵין שִׁשִּׁים לְבַטְּלוֹ, יֵשׁ מִי שֶׁאוֹמֵר \u0010y19\u0011 שֶׁאֵין לְהוֹסִיף עָלָיו כְּדֵי לְבַטְּלוֹ. \u0010c10\u0011",["\u0003אכסנאי וכו'\u0004 וה\"ה הבחורים שלומדים שלא בביתם צריכין להשתתף עכ\"פ ודוקא בבחור שאוכל בפ\"ע אבל אם סמוך על שולחן בעה\"ב הוא בכלל ב\"ב וה\"ה משרתיו כיון שהם סמוכין על שולחנו בקביעות מדינא א\"צ להדליק אא\"כ רוצה להיות מן המהדרין:","\u0003שאין מדליקין עליו בביתו\u0004 כי מדינא כשאשתו מדלקת נר חנוכה בביתו הוא יוצא י\"ח בהדלקתה אף שהוא במקום רחוק מביתו וא\"צ שוב להשתתף אפילו בפריטי ועיין בט\"ז בשם רש\"ל דדוקא כשהוא יודע בבירור שאשתו מדלקת עליו אבל אם אינו יודע יש לו להדליק וגם לברך. ומטעם זה מי שלא ידע שהדליקו עליו ובא באותו לילה לביתו ומצא שהדליקו עליו צריך להדליק דכיון שלא ידע מתחלה מסתמא היה דעתו להדליק בעצמו ולא לצאת בשל אשתו וממילא חל עליו תקנת חכמים ועיין במ\"א שדעתו בזה דידליק בלא ברכה:","\u0003לתת פרוטה\u0004 היינו שא\"צ האכסנאי ליתן כל חצי הוצאות הנרות רק בפרוטה סגי דעי\"ז מקנה לו חלק בשמן [ויש מאחרונים שכתבו דצריך הבעה\"ב להוסיף מעט שמן בשבילו חוץ השיעור שצריך ליתן לצורך חצי שעה בשביל עצמו] וה\"ה אם בעה\"ב מקנה לו חלק בשמן במתנה שרי דהוי כמשתתף בפרוטה ומ\"מ אם יש לאכסנאי נר נכון יותר להדליק בעצמו:","\u0003להשתתף עמו\u0004 היינו אפילו אם אוכל על שולחן בעה\"ב לא אמרינן דכבני ביתו דמי ומדינא די בנר אחד לכולם כיון דאורח הוא ואינו סמוך על שולחנו בקביעות צריך להשתתף עמו. וצריך האכסנאי לשמוע הברכות מבעה\"ב [אחרונים]:","\u0003ואם יש לו וכו'\u0004 הטעם משום חשדא שיחשדו אותו שלא הדליק נר חנוכה ואפילו אם הוא יודע שמדליקין עליו בביתו לא מהני:","\u0003פתח פתוח וכו'\u0004 אפילו הוא פתוח לרוח שפתח בעל הבית פתוחה והבעה\"ב הלא הדליק נר חנוכה מ\"מ חיישינן שכשידעו שפה התאכסן אורח אחד יאמרו שלא הדליק נר חנוכה:","\u0003לעצמו\u0004 משמע מזה דכשאין פתח פתוח אפילו הוא מתאכסן בחדר בפני עצמו יכול להשתתף בפריטי עם בעה\"ב או אם הוא נשוי יכול לסמוך על ביתו ויש פוסקים שסוברין דכ\"ז בזמן הגמרא שהיו מדליקין בפתחי הבתים ובחצרות אבל האידנא שמדליקין בפנים בבית כל אורחים היינו אפילו נשוי שבביתו מדליקין עליו בודאי ג\"כ צריך להדליק בעצמו בכל גווני דמי יודע באכסניא אם יש לו אשה בבית שמדלקת עליו ואתו למיחשדיה וגם להשתתף בפריטי אינו מועיל משום דכיון שהמנהג כהיום שכל אחד מדליק בבית בפ\"ע אתו בני הבית לחשדו ומסיק המ\"א שאין להחמיר כדבריהם כ\"א כשיש לו עכ\"פ חדר בפ\"ע אבל אם אין לו חדר בפ\"ע יכול לסמוך אאנשי ביתו שהדליקו עליו בביתו או אפריטי ועיין לעיל בסוף סק\"ג שכתבנו דכשיש לו נר נכון יותר להדליק בעצמו ועיין לעיל בסימן תרע\"ו שהבאנו כמה פוסקים שסוברין דכשהוא סומך על אנשי ביתו אף שיוצא בזה ידי נר חנוכה מ\"מ כשרואה אח\"כ נר חנוכה יש אומרים שצריך לברך שעשה נסים וע\"כ נכון יותר להדליק בעצמו אפילו נר אחד ולא לסמוך על קולא זו ועיין לקמיה בס\"ג מה שנכתוב בזה:","\u0003צריך להדליק וכו'\u0004 וכיון דבזה ההדלקה אינו אלא משום חשדא י\"א דלא יברך אם יודע שמדליקין עליו בביתו אבל אם אין מדליקין עליו בביתו צריך לברך דכיון שהוא מדליק בעצמו בודאי אינו משתתף עמהם בפריטי וחל עליו מדינא חובת הדלקה:","\u0003אף על פי שאותו בית וכו'\u0004 טעמו שכיון שיש לו בית מיוחד לשינה והעולם רואין אותו נכנס ויוצא בו איכא חשדא אם אינו מדליק שאין העולם יודעין שאוכל במקום אחר [טור]:","\u0003האוכל אצל אביו\u0004 ואפילו אוכל אצלו בקביעות כיון דהטעם משום חשד:","\u0003וי\"א דבזה\"ז וכו'\u0004 ועיין באחרונים שכתבו דגם הדעה ראשונה מודה בזה\"ז דכיון שמדליקין בפנים ליכא חשדא מעוברים ושבים אלא מבני הבית והם יודעים שמדליק במקום שאוכל או משתתף עם בעה\"ב שם:","\u0003במקום שאוכל\u0004 דמקום אכילתו עיקר. ודוקא לענין אכסנאי הנ\"ל שאין ביתו אצלו או לענין בן הסמוך על שולחן אביו אבל מי שסועד אצל חבירו באקראי ויש לו שם בית באותו העיר צריך לילך לביתו להדליק שם נר חנוכה ואם אינו רוצה לזוז ממקום שסועד יצוה לאשתו שתדליק עליו בביתו ומ\"מ מצוה בו יותר מבשלוחו ועיין בבה\"ל:","\u0003קטן שהגיע לחינוך וכו'\u0004 לפי מה שפסק המחבר בסי' תרע\"א ס\"ב דאפילו המהדרין מן המהדרין אין מדליקין רק נר אחד לכל אנשי הבית ורק שמוסיפין והולכין בכל יום נר אחד יותר ע\"כ מיירי כאן שהקטן הזה יש לו בית בפ\"ע וע\"כ צריך להדליק ולברך אבל לדידן דנהגינן שכל אחד צריך להדר ולהדליק בפ\"ע א\"כ גם הקטן הזה צריך בכל גווני להדליק בפ\"ע והכי פסק הרמ\"א לעיל בסוף סימן תרע\"ה אבל דעת הש\"ג והמאירי דאפילו לדידן א\"צ לחנך הקטן להדליק בפ\"ע אם לא שיש לו בית בפ\"ע:","\u0003כי חייב לראות\u0004 זה סותר לסימן תרע\"ו ס\"ג דסובר שם דכשמדליקין בביתו א\"צ לברך על הראיה ודין דכאן הוא מן המרדכי ושם סתם המחבר כשארי פוסקים שחולקין עליו ולכן לדינא אין לנהוג כן להדליק בברכה אא\"כ שיאמר שאינו רוצה לצאת בהדלקת אשתו וכמ\"ש רמ\"א אח\"ז ועיין לקמיה:","\u0003אם רוצה להחמיר וכו'\u0004 ר\"ל אף דמדינא פטור להדליק אם מדליקין עליו בביתו מ\"מ אם רוצה להחמיר על עצמו ולהדליק בעצמו רשאי ובלבד שיכוין במחשבתו קודם שעת ההדלקה שאינו רוצה לצאת בשל אשתו וממילא לית כאן משום ברכה לבטלה דכיון שאינו רוצה לצאת בהדלקתה חל חיוב הדלקה עליה:","\u0003וכן נוהגין\u0004 וכן סתמו הרבה אחרונים. ויש מן הפוסקים שסוברין אחרי דחז\"ל פטרוהו ע\"י הדלקת אשתו לא כל כמיניה לומר איני רוצה לצאת בשל אשתי וידליק בלא ברכה. והנה אף דודאי אין למחות ביד הנוהגין לברך אחרי דהרבה אחרונים הסכימו לברך מ\"מ טוב יותר להדר לשמוע הברכות מפי אחר ויענה אמן [ויכוין לצאת בהן] וידליק נרותיו או יראה לשער להדליק נרותיו ולברך עליהן זמן מה קודם שמדלקת אשתו בביתו דהיינו שהיא מדלקת אחר מערב כמנהג העולם והוא ידליק קודם מערב:","\u0003הנותר ביום השמיני וכו'\u0004 דבלילות הקודמין אם נותר יכול להשתמש בהן למצות הדלקה בלילות שאחריהן ואם נתערב בשמן אחר דינו כדלקמיה:","\u0003מן השמן הצריך וכו'\u0004 היינו שלא נתן תחלה רק כשיעור הדלקה ונכבה באמצע ונותר ולכן אסור דהוקצה למצותו ואסור להנות הימנו אבל אם נתן הרבה בנר ונותר מותר להשתמש בו לכתחלה וכמו שכתב לעיל בסימן תרע\"ב ס\"ב. ודע דיש פוסקים שסוברין דאם נתן השמן בסתם הוקצה כל השמן אם לא דהתנה לכתחלה שלא יאסור אלא כשיעור ועיין לעיל בסימן תרע\"ב במ\"ב סק\"ז:","\u0003ושורפו בפ\"ע\u0004 דלהניחו לשנה הבאה לנ\"ח אסור דחיישינן לתקלה ואפילו להניחו בכלי מאוס דודאי לא יבוא לאכלו ג\"כ אסור דחיישינן שמא יבוא לדלוק ולהנות הימנו:","\u0003שאין להוסיף עליו וכו'\u0004 ועיין ביו\"ד סימן צ\"ט ס\"ו דיש מתירין בכל איסור דרבנן להוסיף עליו אם נתערב ולכן כתב כאן יש מי שאומר:"],["\u0003 לתת פרוטה לבעה\"ב\u0004 - עיין מ\"ב מש\"כ בבחור הסמוך על שולחן בעה\"ב דא\"צ להשתתף הוא מדברי המגן אברהם [ואינו מדברי מהרש\"ל] ועיין בפר\"ח דלדידיה בכל גווני צריך להשתתף ומה שהביא המגן אברהם ראיה מדברי מהרי\"א בשם או\"ח לענין בן הסמוך ע\"ש אביו המאירי הביא בשם חכמי התוספות דגם בזה צריך להשתתף ואף להמאירי שחולק שם עליהם עכ\"פ בדינא דהמ\"א בודאי מודה להם דצריך להשתתף עי\"ש בדבריו:","\u0003 להשתתף וכו'\u0004 - ומ\"מ צריך ליזהר בשיתוף זה שלא ידליק זה לילה אחת וזה לילה אחרת אלא יהא השמן משותף בכל לילה ולילה או יתן לו פרוטה לזכות לו חלק בכל הלילות [מאירי בשם חכמי התוספות]:","\u0003 עמו וכו'\u0004 - עיין בפמ\"ג בא\"א אות ג' שכתב אם שני בע\"ב דרים בחדר אחד ואין סומכין וכ\"א אוכל משלו צ\"ע אם די בשיתוף דאפשר דצריך כ\"א מדינא להדליק בשלו ואורח אפשר הקילו עכ\"ל ובאות ח' הביא דחולקין בזה הלבוש והפר\"ח ועיין שם בפר\"ח הביא ראיה לדבריו מדברי המ\"מ בפ\"ד מהלכות חנוכה דצריך להדליק אמנם מדברי השיבולי לקט בהלכות חנוכה סימן קפ\"ה בשם רבותינו מסתימת דבריו משמע דכיון שהם בבית אחד די בשיתוף:","\u0003 פתח וכו'\u0004 - לכאורה כיון דהטעם משום חשדא דעוברים ושבים א\"כ בזמנינו דמדליקין בפנים תו ליכא חשדא זו וכמו שכתב בהג\"ה בסוף סימן תרע\"א ואמאי מחמירינן ביש לו פתח פתוח אמנם אח\"כ מצאתי במהרי\"ל בסימן קמ\"ה בהיפך מדברי דמשמע שם בפשטיות לשונו דהאידנא שמדליקין הכל בפנים בבית ע\"כ כל אורח אפילו ידע בודאי שמדליק אשתו בביתו בעבורו מ\"מ צריך להדליק באכסניא לעצמו דמי יודע באכסניא שהוא נשוי ואשתו מדלקת עליו בביתו ואתו למיחשדיה שאינו מדליק נר חנוכה וגם מוכח שם בתשובה שמהרי\"ל דעתו כמהרי\"ו דהשתא רובא דעלמא אין משתתפין מפני שהמנהג הוא שכל אחד מדליק לעצמו ואתו למיחשדיה (ואף דאפשר דאנשי הבית ידעו שנשתתף עם בע\"ה בשמן לא ניתן דברינו לשיעורין) ומ\"מ קשה על הרמ\"א ממ\"נ אי ס\"ל כמהרי\"ל דהשתא מפני שמדליקין בפנים גרע טפי היה לו להגיה דבימינו אפילו אין פתח פתוח צריך להדליק לעצמו ואי לא ס\"ל כסברת מהרי\"ל היה לו להקל אפילו פתח פתוח וצ\"ע:","\u0003 פתוח\u0004 - מסתפקנא אם מיירי אפילו אין הבית חלוק מתוכו אלא שהאורח יש לו בבית זוית אחת שהוא משתמש שם ובאותו זוית יש לו פתח לרחוב שהוא נכנס ויוצא דרך שם וחיישינן לחשדא כשלא ידליק לעצמו או דמיירי דוקא שהבית חלוק מתוכו ויש לו חדר מיוחד שם אז חיישינן לחשדא וכן משמע לכאורה לשון השו\"ע מסוף דבריו. וכן מלשון הרמב\"ם בפ\"ד הלכה י\"א וצ\"ע אח\"כ מצאתי כעין זה בשבה\"ל סימן קפ\"ה שיש שני דיעות בזה וי\"ל קצת:","\u0003 לעצמו\u0004 - עיין מ\"ב. וכדי שתבין מקור דברי מוכרח אני להעתיק לשון המגן אברהם וז\"ל והאידנא שמדליקין בפנים אפילו אורחים מדליקין (דיני מהרי\"ו סי' ל\"א ומהרי\"ל סימן קמ\"ה) ודוקא כשאוכל בחדר בפ\"ע עכ\"ל והנה הא\"ר השיג עליו דשם מוכח בהדיא דמחמירין בכל גווני ומה שהפמ\"ג רוצה לדחוק עצמו וליישב המעיין שם בפנים יראה שם שהאמת עם א\"ר והנה הרבה עמלתי על דברי המגן אברהם אור ישראל איך יטעה בזה ח\"ו. ומצאתי אח\"כ בהגהת תוספות שבת על או\"ח בסופו עי\"ש ומוכח מדבריו שדעת המגן אברהם להורות שאפילו אין פתח פתוח לעצמו ואך כשהוא אוכל בחדר בפ\"ע. והנה באמת דעת מהרי\"ו ומהרי\"ל להחמיר בכל גווני אך דעת המגן אברהם להורות כשיטתם כשאוכל בחדר בפ\"ע עכ\"פ ולפ\"ז מה דמסיים ודוקא הוא הכרעת עצמו ומיושב בזה השגת הא\"ר:","\u0003 במקום שאוכל\u0004 - עיין מ\"ב מש\"כ דמי שסועד אצל חבירו באקראי ויש לו שם בית באותו העיר וכו'. ודוקא באופן זה אבל אם הולך הוא וכל אנשי ביתו לבית אביו או חמיו בקביעות על ח' ימי חנוכה דבר ברור הוא שכיון שסועד וישן שם כל ימי חנוכה אף שביום אוכל אכילת עראי בביתו שאינו מדליק אלא בבית שאוכל וישן שם בלילה דכיון שאין שום אדם בבית למי ידליק וכ\"ש האידנא שההיכר לבני הבית וכיון שישנים בני הבית שם ידליקו [פר\"ח עי\"ש]:","\u0003 ולהדליק בפ\"ע וכו'\u0004 - כתב הח\"א לפי מה שמבואר לעיל דעיקר זמן הדלקתה הוא רק עד שתכלה רגל וידוע שהנוסעים לירידים נוסעים כמה שעות בלילה ולכן ראוי לכל יר\"ש להזהיר לאשתו קודם נסיעתו שתהיה זהירה בזה להדליק תיכף בצאת הכוכבים והוא יסמוך עליהם ומ\"מ כשיבא לאושפיזא ידליק בלא ברכה ויהדר לשמוע הברכות ממי שחייב להדליק ויענה אמן (דעתו כדעת מהרש\"ל והפר\"ח). עכ\"ל:","\u0003 מן השמן וכו'\u0004 - עיין מ\"ב דהיינו כשנכבה באמצע השיעור ואם נכבה כזה בליל זיי\"ן והוסיפו בליל ח' הרבה שמן יותר מן השיעור ודלק כשיעור חצי שעה וניתותר נראה דלכו\"ע אסור להנות מהן דבודאי יש בזה מן השמן של תוך זיי\"ן האסור אם לא שיודע שבשמן שהוסיף על האתמול היה ס' כנגד מעט הראשון:","\u0003 הצריך וכו'\u0004 - עיין מ\"ב מש\"כ דיש פוסקים שסוברין וכו' אבל אם לקח צלוחית של שמן לנר חנוכה ונשתמש ממנו כדי צרכו לכו\"ע אין הנותר בכלל מותר השמן שבנר חנוכה [ע\"ד בשם בארות המים]:","\u0003 לשיעור הדלקה\u0004 - כתב הש\"ג צ\"ע אם נתן השמן לשיעור הדלקת חצי שעה ודלק יותר מחצי שעה (כגון שהפתילה דקה והוא חשב שהפתילה בינונית) אם מותר להסתפק ממנו דאפשר כיון דהוא אקציה מדעתו אף דבטעות הוי נאסר. והובא דבריו במ\"א:"],"\u0010y0\u0011 \u0010g0\u0011 אַכְסְנַאי \u0010y1\u0011 שֶׁאֵין מַדְלִיקִין עָלָיו בְּבֵיתוֹ, צָרִיךְ \u0010y2\u0011 לָתֵת \u0010t0\u0011 פְּרוּטָה \u0010c0\u0011 לְבַעַל הַבַּיִת \u0010y3\u0011 לְהִשְׁתַּתֵּף \u0010c1\u0011 עִמּוֹ \u0010c2\u0011 \u0010t1\u0011 \u0010m0\u0011 בַּשֶּׁמֶן שֶׁל נֵר \u0010y4\u0011 \u0010g1\u0011 חֲנֻכָּה; וְאִם יֵשׁ לוֹ \u0010y5\u0011 \u0010m1\u0011 פֶּתַח \u0010c3\u0011 פָּתוּחַ \u0010y6\u0011 \u0010c4\u0011 \u0010m2\u0011 לְעַצְמוֹ, \u0010y7\u0011 \u0010c5\u0011 צָרִיךְ \u0010m3\u0011 לְהַדְלִיק בְּפִתְחוֹ, \u0010y8\u0011 \u0010g2\u0011 אַף עַל פִּי שֶׁאוֹתוֹ בַּיִת אֵינוֹ מְיֻחָד אֶלָּא לְשֵׁנָה וְהוּא אוֹכֵל עַל שֻׁלְחַן בַּעַל הַבַּיִת, וְהוּא הַדִּין \u0010m4\u0011 לְבֵן \u0010y9\u0011 הָאוֹכֵל אֵצֶל אָבִיו. \u0005 הַגָּה: \u0010y10\u0011 \u0010m5\u0011 וְיֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה שֶׁמַּדְלִיקִים בִּפְנִים מַמָּשׁ, יַדְלִיק \u0010y11\u0011 \u0010m6\u0011 בַּמָּקוֹם שֶׁאוֹכֵל, \u0010c6\u0011 וְכֵן נָהֲגוּ \u0006 \u0005(תְּשׁוּבַת רַשְׁבָּ\"א סי' תקמ\"ב)\u0006. \u0010y12\u0011 \u0010g3\u0011 \u0010m7\u0011 \u0010r0\u0011 \u0010r1\u0011\nקָטָן שֶׁהִגִּיעַ לְחִנּוּךְ צָרִיךְ לְהַדְלִיק. \u0010g4\u0011\nיֵשׁ אוֹמְרִים שֶׁאַף עַל פִּי שֶׁמַּדְלִיקִין עָלָיו בְּתוֹךְ בֵּיתוֹ, אִם הוּא בְּמָקוֹם שֶׁאֵין בּוֹ יִשְׂרָאֵל מַדְלִיק בִּבְרָכוֹת. \u0005 הַגָּה: \u0010y13\u0011 כִּי חַיָּב לִרְאוֹת הַנֵּרוֹת \u0006 \u0005(מָרְדְּכַי)\u0006, \u0005 וְכֵן נוֹהֲגִין; וַאֲפִלּוּ אִם הוּא אֵצֶל יְהוּדִים וְרוֹאֶה הַנֵּרוֹת, \u0010y14\u0011 \u0010m8\u0011 אִם רוֹצֶה לְהַחְמִיר עַל עַצְמוֹ וּלְהַדְלִיק \u0010c7\u0011 בִּפְנֵי עַצְמוֹ, מַדְלִיק \u0010t2\u0011 \u0010s0\u0011 \u0006 \u0005 וּמְבָרֵךְ עֲלֵיהֶם, \u0010y15\u0011 וְכֵן נוֹהֲגִין \u0006 \u0005(ת\"ה וּמַהֲרִי\"ל וּתְשׁוּבַת מַהֲרִי\"ל סי' קמ\"ה)\u0006. \u0010y16\u0011 \u0010g5\u0011 \u0010r2\u0011 \u0010r3\u0011\nהַנּוֹתָר בַּיּוֹם הַשְּׁמִינִי \u0010y17\u0011 מִן הַשֶּׁמֶן \u0010c8\u0011 \u0010m9\u0011 הַצָּרִיךְ \u0010c9\u0011 לְשִׁעוּר הַדְלָקָה, עוֹשָׂה לוֹ מְדוּרָה \u0010y18\u0011 \u0010t3\u0011 \u0010s1\u0011 \u0010m10\u0011 וְשׂוֹרְפוֹ בִּפְנֵי עַצְמוֹ שֶׁהֲרֵי הֻקְצָה לְמִצְוָתוֹ; וְאִם נִתְעָרֵב בְּשֶׁמֶן אַחֵר וְאֵין שִׁשִּׁים לְבַטְּלוֹ, \u0010g6\u0011 יֵשׁ מִי שֶׁאוֹמֵר \u0010y19\u0011 \u0010m11\u0011 שֶׁאֵין לְהוֹסִיף עָלָיו כְּדֵי \u0010t4\u0011 לְבַטְּלוֹ. \u0010c10\u0011 \u0010r4\u0011 \u0010r5\u0011",{"g":["מימרא דרבי זירא שבת כג","מהא דרב הונא","טור בשם תשובת אביו הרא\"ש","אורחת חיים","מהר\"י אבוהב בשם א\"ח וכ\"כ המרדכי","הרא\"ש בפ\"ב דשבת בשם שאלתות דרב אחאי והמרדכי בשם ילמדנו פסיקתא רבתי","\u0003טור בשם הר\"ם מרוטנבורג:\u0004 "],"t":["\u0003פרוטה. \u0004 דייק למימר פרוטה לומר שא\"צ האכסנאי ליתן כל חצי הוצאת הנרות רק בפרוט' דיהיב ליה סגי עיין בס' גן המלך סי' מ'. וגם בזמן הזה מותר להשתתף ד\"מ. כתב בתשובת רש\"ל שגם הבחורי' צריכים להשתתף ואפשר דדוקא כשאוכל בפני עצמו אבל אם סמוך על שלחן בע\"ה בכלל בני ביתו הוא ומדינא אין צריך להדליק אלא אם רוצה להיות מן המהדרין. מי שסועד אצל חבירו באקראי מצו' מן המובחר שילך לביתו וידליק ואם אינו רוצ' לזוז משם יצוה לבני ביתו שידליקו עליו בביתו ט\"ז ע\"ש. ולענין סומא ע' סי' תרע\"ה ס\"ק ג' מש\"ש:","\u0003בשמן. \u0004 וצריך הבע\"ה להוסיף מעט שמן בשבילו ב\"ח אגוד' וכ' הרשב\"א שהוא הדין אם הבע\"ה מקנה לו חלק שמן במתנ' שרי. מ\"א:","\u0003ומברך. \u0004 דברכה לבטלה ליכא כיון שאינו רוצה לצאת בשל אשתו חל חיובא עליו תשובת מהרי\"ל. ויש חולקין וספק ברכות להקל ט\"ז. ורש\"ל כתב מי שבא לביתו ומצא שהדליקו עליו צריך להדליק. וכתב המ\"א ודבריו אינם מוכרחים לכן אין לברך ע\"ש ועיין ט\"ז:","\u0003ושורפו. \u0004 דאסור להניחו לשנה הבאה דחיישינן לתקלה. טור:","\u0003לבטלו. \u0004 עיין ביורה דעה סי' צ\"ט ס\"ק י\"ד מש\"ש. \u0005(עיין בספר אליה רבה בזה שהעלה להלכה דאף שכבר נפל לפחות מס' שאין לבטלו והשיג על כמה אחרונים בזה)\u0006:"],"s":["\u0003ומברך. \u0004 עבה\"ט וכת' בר\"י בשם זרע אמת דלצאת מידי כל הספיקות טוב להשתתף בפריטי כדין אכסנאי וישמע הברכה מבעה\"ב עיין שם:","\u0003בש\"ע הנותר מן השמן כו' \u0004 ועיין בספרי שו\"ת בית אפרים מ\"ש בזה להגאון בעמה\"ת שאילת שלום ז\"ל על השאלתות ועיין שם מ\"ש בדברי הר\"ן וה\"ה ובדברי המ\"א שכת' דהוי דשיל\"מ ע\"ש:"],"m":["כתו' בתשוב' רש\"ל שגם הבחורים צריכים להשתתף ואפשר דדוקא כשאוכל בפ\"ע אבל אם סמוך על שלחן בע\"ה הוא בכלל בני ביתו ומדינא א\"צ להדליק אלא אם רוצ' להיו' ממהדרין וכ\"מ בב\"י בשם מהרי\"א ע\"ש, כת' רש\"ל מי שלא ידע שהדליקו עליו בביתו ובא באותו ליל' לביתו ומצ' שהדליקו עליו צריך להדליק דכבר חל עליו תקנת חכמים עכ\"ל עיין סוף סי' תרע\"ב ודבריו אינן מוכרחי' לכן אין לברך: \u0003בשמן\u0004. צריך הבע\"ה להוסיף מעט שמן בשבילו (ב\"ח אגודה) וכתב הרשב\"א סי' תקמ\"ב שה\"ה אם הבע\"ה מקנ' לו חלק בשמן במתנ' שרי:","\u0003פתח פתוח\u0004. אפי' הוא פתוח לרוח שפתח ב\"ה פתוחה [כ\"ה]:","\u0003לעצמו\u0004. והאידנא שמדליקין בפנים אפי' אורחים מדליקין (דיני מהרי\"ו סי' ל\"א ומהרי\"ל סי' קנ\"ו) ודוקא כשאוכל בחדר בפ\"ע:","\u0003להדליק בפתחו\u0004. וכיון שהטעם מפני החשד א\"צ לברך כמ\"ש ססי' תרע\"ה (כ\"ה) ויש לחלק עס\"ג בהג\"ה:","\u0003לבן האוכל\u0004. פשוט דאפילו אוכל בקביעות אצל אביו כיון דהטעם משום חשד כמ\"ש הטור ובכ\"ה האריך בחנם:","\u0003וי\"א דבזמן כו'\u0004. אף הרא\"ש מודה בזה (ב\"ח ד\"מ):","\u0003במקו' שאוכל\u0004. היינו בקביעות אבל מי שאוכל בבית חבירו באקראי צריך להדליק בביתו (ש\"י סי' ע\"ג) או אשתו מדלקת עליו (סי' תרע\"ה ס\"ג) מ\"מ מצו' בו יותר מבשלוחו עכ\"ל ב\"ח ועיין סי' ת\"ט ס\"ח:","\u0003קטן\u0004. אפשר דמיירי שיש לו בית כמ\"ש ריש סי' תרע\"א ואפשר דאפי' לדידן שכל אחד מדליק קטנים פטורים וכ\"מ בש\"ג ע\"ש:","\u0003אם רוצה\u0004. ואף על גב דלא חיישי' שמא תשכח דהא סמכי' על נשים אפי' באיסור כרת מ\"מ אם רוצה להדליק בעצמו בכלל מהדרין הוא (ת\"ה) ובתשו' מהרי\"ל דמנהג פשוט הוא שאורחי' ובחורי' מדליקין כיון דהשתא מדליק כל אחד וא' מי יודע אם מדליקין עליו בביתו ואתי למחשדיה ומשום ברכה לבטלה ליכא כיון שאינו רוצה לצאת בשל אשתו ממילא חל חיובא עליה עכ\"ל:","\u0003הצריך לשיעור הדלקה\u0004. דביותר משיעור הדלקה מותר להשתמש בו לכתחלה כמ\"ש סי' תרע\"ב ס\"ב (ב\"י מרדכי ורש\"ל וש\"ג) וב\"ח פסק כשנתן השמן בסתם הוקצ' כל השמן וכ\"מ בהג\"מ ובר\"ן ובתוס' שבת דף מ\"ד ומיהו אין מוכרח כל כך ולכן טוב להתנות לכתחלה שלא יאסר אלא כשיעור וכתב הש\"ג צ\"ע אם נתן השמן שיעור חצי שעה ודלק יותר מחצי שעה אם מותר להסתפק ממנו:","\u0003ושורפו\u0004. ואסור להניחו בכלי מאוס לשהותו לשנה הבאה דחיישינן לתקלה (טור יש\"ש) ועבי\"ד סי' נ\"ז:","\u0003שאין להוסיף וכו'\u0004. ול\"ד לסי' תק\"ז ס\"ב דהתם אין נהנה ממנו עד אחר ביעורו משא\"כ הכא דנהנה ממנו בשעת ביעורו אסור לבטלו (טור) ועבי\"ד סי' צ\"ט ס\"ו דיש מתירין ולכן כ' כאן יש מי שאומר וכו' ועיין בש\"ך שם ואפשר דהכא חמיר טפי כיון דהוי דשיל\"מ דמדינא מותר לשהותו לשנה הבאה והוי דומיא דחמץ עבי\"ד סי' ק\"ב:"],"r":["\u0003ס\"א אע\"פ. \u0004כמש\"ל סי' תרע\"א ס\"ח:","\u0003וי\"א. \u0004כמש\"ש מיהו בזה\"ז כו':","\u0003ס\"ג י\"א שאע\"פ. \u0004מרדכי והוא חולק על מש\"ל בסי' תרע\"ו ס\"ג ועט\"ז שם:","\u0003אם רוצה. \u0004כמו מהדרין ואינו רוצה לצאת בשל אשתו:","\u0003ס\"ד הצריך. \u0004כנ\"ל סי' תער\"ב ס\"ב:","\u0003יש. \u0004עי\"ד סימן צ\"ט ס\"ו וצ\"ע:"]}],["מִי שֶׁאֵין יָדוֹ מַשֶּׂגֶת \u0010y0\u0011 לִקְנוֹת נֵר חֲנֻכָּה וְנֵר שַׁבָּת, יִקְנֶה נֵר שַׁבָּת \u0010y1\u0011 מִפְּנֵי שְׁלוֹם בֵּיתוֹ \u0010y2\u0011 \u0005 (וְעַיֵּן לְעֵיל סי' רס\"ג סָעִיף ג')\u0006; וְאִם יֵשׁ לוֹ לְשֶׁל שַׁבָּת \u0010y3\u0011 וְאֵין לוֹ לְנֵר חֲנֻכָּה וּלְיַיִן לְקִדּוּשׁ הַיּוֹם, \u0010y4\u0011 יִקְנֶה לְנֵר \u0010y5\u0011 חֲנֻכָּה, מִשּׁוּם פִּרְסוּמֵי נִסָא. \u0005 הַגָּה: וְהוּא הַדִּין נֵר \u0010y6\u0011 חֲנֻכָּה קוֹדֵם לְיֵין הַבְדָּלָה, \u0010y7\u0011 וְעַיֵּן לְעֵיל סי' רצ\"ו סָעִיף ה'. \u0006",["\u0003לקנות נר חנוכה וכו'\u0004 ואם יש לו נר אחד לביתו סגי אע\"ג דטוב וראוי שיהיה ב' נרות לשבת כדלעיל בסימן רס\"ג מ\"מ במקום הדחק די שיהיה נר אחד על השולחן שאוכל והשאר לנר חנוכה ולהוי מן המהדרין [אחרונים]:","\u0003מפני שלום ביתו\u0004 י\"א דבזה\"ז שמדליקין בפנים יקנה לנר חנוכה שהרי לא ישב בחושך ואע\"פ שאסור להשתמש לאורה הוי כשעת הסכנה דאיתא לעיל בסימן תרע\"א ס\"ה דמניחה על שולחנו אבל רוב האחרונים הסכימו דאין לחלק בזה בין זמן הגמרא לזמנינו:","\u0003וע\"ל סימן רס\"ג ס\"ג\u0004 דמבואר שם דאם אין ידו משגת לנר שבת וקידוש היום ג\"כ נר שבת קודם:","\u0003ואין לו לנר חנוכה וליין וכו'\u0004 ומיירי דיש לו פת דאי אין לו פת קניית הפת דוחה אפילו לנר של שבת וכ\"ש נר חנוכה וקידוש היום ועיין לעיל בסימן רס\"ג סק\"ט במ\"ב ובה\"ל שם:","\u0003יקנה לנר חנוכה\u0004 היינו נר אחד והמותר ליין קידוש:","\u0003משום פרסומי ניסא\u0004 וקידוש היום הלא יכול לקדש בפת ובלא\"ה קידוש על היין הוא רק מדרבנן דמן התורה יוצא בזכירת דברים בעלמא:","\u0003קודם ליין הבדלה\u0004 משום האי טעמא:","\u0003ועיין לעיל וכו'\u0004 אין נזכר שם יותר מכאן ונראה דצ\"ל כדלעיל בסימן וכו':"],[],"\u0010g0\u0011 מִי שֶׁאֵין יָדוֹ מַשֶּׂגֶת \u0010y0\u0011 לִקְנוֹת \u0010t0\u0011 \u0010m0\u0011 נֵר חֲנֻכָּה וְנֵר שַׁבָּת, יִקְנֶה נֵר שַׁבָּת \u0010y1\u0011 מִפְּנֵי \u0010t1\u0011 \u0010s0\u0011 \u0010m1\u0011 שְׁלוֹם בֵּיתוֹ \u0010y2\u0011 \u0005 (וְעַיֵּן לְעֵיל סי' רס\"ג סָעִיף ג')\u0006; \u0010g1\u0011 וְאִם יֵשׁ לוֹ לְשֶׁל שַׁבָּת \u0010y3\u0011 וְאֵין לוֹ לְנֵר חֲנֻכָּה וּלְיַיִן לְקִדּוּשׁ הַיּוֹם, \u0010y4\u0011 \u0010t2\u0011 \u0010m2\u0011 יִקְנֶה לְנֵר \u0010y5\u0011 חֲנֻכָּה, מִשּׁוּם פִּרְסוּמֵי נִסָא. \u0005 הַגָּה: וְהוּא הַדִּין נֵר \u0010y6\u0011 חֲנֻכָּה קוֹדֵם לְיֵין הַבְדָּלָה, \u0010y7\u0011 וְעַיֵּן לְעֵיל סי' רצ\"ו סָעִיף ה'. \u0006",{"g":["מימרא דרבא שבת כג","בעי' והדר פשט'"],"t":["\u0003חנוכה. \u0004 ואם יש לו נר א' לביתו סגי ויקח המותר לנר חנוכה. מ\"א:","\u0003שלום. \u0004 שמצטערים לישב בחשך. וכתב הב\"ח דאם אין לו פת נ\"ח קודם וכ\"כ העט\"ז אבל הט\"ז כתב דפת קודם ע\"ש. וכתב המ\"א ואפשר דבזמן הזה שמדליקין בפנים יקנה נ\"ח ואעפ\"כ לא ישב בחשך ואע\"פ שאסור לאכול לאורה מ\"מ כיון דא\"א בענין אחר הוי כשעת הסכנה דמניחו על שלחנו אע\"פ שע\"כ משמש בו ה\"נ כן הוא וה\"ה בחול מי שאין לו אלא נר אחד ע\"ש:","\u0003יקנה\u0004 \u0003לנ\"ח. \u0004 היינו נר אחד והמותר ליין קידוש. מ\"א:"],"s":["\u0003שלום. \u0004 עבה\"ט ועיין שם סימן מ\"ט ליישב דברי המ\"מ סוף הל' חנוכה דמה שכ' הרמב\"ם דלנ\"ח מוכר כסותו הוא כ\"ש מד' כוסות דמה כ\"ש הוא דהא ד' כוסות נמי פרסומי ניסא איכא וכן הקשה הלח\"מ והא\"ז וכת' ליישב דהא דאמרינן דעדיף מקידוש היום אף על פי שהוא עדות על בריאת העולם מכל מקום הוא רק בביתו משא\"כ נ\"ח שמדליק מבחוץ ואיכא פרסום הנס לציבור ומה\"ט הוי כ\"ש מד' כוסות ולכן שפיר פסק המג\"א דלדידן שמדליקין מבפנים לא אמרי' האי דינא דחנוכה ולא נאמרו אלא בזמן שמדליקין מבחוץ עיין שם ובמחכ\"ת אגב שיטפא רהיט ליה וכ\"כ בשם המג\"א דהמג\"א לא כ\"כ אלא אהא דאמרינן דנר שבת קודם משום שלום ביתו דפירוש מדליקין בפנים יקנה נ\"ח כו' כמ\"ש אבל לא בא לגרוע עדיפות נ\"ח כלל בשביל הדלקה בפנים ואדרבה משמע מדבריו דלענין דעדיף מקידוש היום ויין להבדלה אף עתה הדין כן:"],"m":["\u0003נר חנוכה\u0004. ואם יש לו נר א' לביתו סגי ויקח המותר לנ\"ח:","\u0003שלום ביתו\u0004. שמצטערים לישב בחשך (רש\"י), ואפשר דבזמן הזה שמדליקים בפנים יקנה נ\"ח ואעפ\"כ לא ישב בחושך ואף על פי שאסור לאכול לאורה מ\"מ כיון דא\"א בע\"א הוי כשעת הסכנ' דמניחו על שלחנו אף על פי שע\"כ משתמש בו כמ\"ש הר\"ן ה\"נ כן וה\"ה בחול מי שאין לו אלא נר אחד:","\u0003יקנה לנ\"ח\u0004. היינו נר אחד והמותר ליין קידוש:"]}],["בְּעֶרֶב שַׁבָּת מַדְלִיקִין \u0010y0\u0011 נֵר חֲנֻכָּה תְּחִלָּה וְאַחַר כָּךְ נֵר שַׁבָּת. \u0005 הַגָּה: וּמְבָרֵךְ עֲלֵיהֶם כְּמוֹ בַּחֹל, אַף עַל פִּי שֶׁמַּדְלִיקִין \u0010y1\u0011 בְּעוֹד הַיּוֹם \u0006 \u0005 גָּדוֹל \u0006 \u0005(ת\"ה סי' ק\"ב)\u0006.",["\u0003נר חנוכה תחלה\u0004 כדי לצאת דעת הי\"א דס\"ל דאי ידליק של שבת תחלה קבליה לשבת ואיתסר עליה מלאכה אבל רוב פוסקים חולקים ע\"ז וס\"ל דלא תליא קבלת שבת בהדלקת הנר וע\"כ אם הדליק של שבת ולא קיבל שבת במחשבתו יכול להדליק אח\"כ וכ\"ז באיש המדליק אבל אשה המדלקת כיון שהמנהג שמסתמא מקבלת שבת בהדלקתה א\"כ לא תדליק שוב של חנוכה אלא תאמר לאחר להדליק והוא יברך אקב\"ו להדליק בשבילה אבל ברכת שעשה נסים וכן שהחיינו ביום א' יכולה בעצמה לברך:","\u0003בעוד היום גדול\u0004 ודוקא אחר פלג המנחה שהוא שעה ורביע קודם הלילה כמ\"ש בריש סי' תרע\"ב. וכבר כתבנו בשם האחרונים דצריך ליתן בה שמן עד שידלק חצי שעה אחר צאת הכוכבים וכן במדליק נרות ואם אין לו כ\"כ שמן ונרות גדולות יראה עכ\"פ אחת מהן שיהיה דולקת השיעור הזה וכתבו האחרונים דנכון לכתחלה שיתפלל מנחה תחלה ואח\"כ ידליק:"],[],"\u0010g0\u0011 \u0010m0\u0011 בְּעֶרֶב שַׁבָּת מַדְלִיקִין \u0010y0\u0011 נֵר חֲנֻכָּה תְּחִלָּה \u0010t0\u0011 \u0010s0\u0011 וְאַחַר כָּךְ נֵר שַׁבָּת. \u0005 הַגָּה: וּמְבָרֵךְ עֲלֵיהֶם כְּמוֹ בַּחֹל, אַף עַל פִּי שֶׁמַּדְלִיקִין \u0010y1\u0011 \u0010m1\u0011 בְּעוֹד הַיּוֹם \u0010t1\u0011 \u0006 \u0005 גָּדוֹל \u0006 \u0005(ת\"ה סי' ק\"ב)\u0006. \u0010g1\u0011 \u0010r0\u0011 \u0010r1\u0011",{"g":["טור בשם בעל הלכות גדולות","\u0003וסיים שם כיון דא\"א בענין אחר חשיבה הכשר מצוה וכו'\u0004 "],"t":["\u0003ואח\"כ. \u0004 וכתב הלבוש דמי שהדליק של שבת תחלה ולא קבל שבת במחשבתו שיכול להדליק אח\"כ ע\"ש. וט\"ז חולק עליו וכתב דאינו יכול להדליק הואיל לדידן שיש מנהג פשוט שהאשה המדלקת נר שבת מקבלת שבת עליה ואסור' במלאכה רק אחרים בני בית עדיין מותרים ע\"כ איש שמדליק נר שבת ושכח להדליק של חנוכה אסור לו להדליק של חנוכה אחר כך אלא יתן לאחד מבני ביתו להדליק ע\"ש. ונ\"ל דבאשה המדלקת כיון שהמנהג שמקבלת שבת בהדלקתה כמ\"ש סי' רס\"ג ס\"י א\"כ לכ\"ע לא תדליק שוב של חנוכה אלא תאמר לאחר להדליק. מ\"א ע\"ש:","\u0003גדול. \u0004 דוקא אחר פלג המנחה. ב\"ח:"],"s":["\u0003בש\"ע מדליקין כו' \u0004 עיין בשבות יעקב סי' ט\"ו בסופו שאסור להניח לעכו\"ם בשבת שיכבה הנרות חנוכה בלילה ולחזור ולהדליקן שאין נכון לעשות כן כיון שהוא מלאכה גמורה דאורייתא ואי משום פרסומי ניסא הוי מצוה הבאה בעבירה וגם לא מצינו בשום מקום מצוה זו שיהיה צריכים להיות דולקים בערב ובבוקר משום פרסום ניסא ע\"ש וע' בבר\"י שכ' בשם מהר\"ש אבוהב תשו' כת\"י יש ליזהר להתפלל מנחה בע\"ש של חנוכה ואח\"כ להדליק נ\"ח כי תפילת מנחה נגד תמיד של בין הערבים ונ\"ח זכר לנס הנעשה בנרות המנורה הנדלקת אחר תמיד של בין הערבים עכ\"ל:"],"m":["\u0003בערב שבת וכו'\u0004. ובדיעבד אם הדליק של שבת ולא קיבל שבת במחשבתו יכול להדליק אח\"כ (לבוש) ונ\"ל דבאשה המדלקת כיון שהמנהג שמקבל' שבת בהדלקתה כמ\"ש סי' רס\"ג ס\"י א\"כ לא תדליק שוב של חנוכה אלא תאמר לאחר להדליק [עמ\"ש ס\"ס תרע\"ו]:","\u0003בעוד היום גדול\u0004. משום דא\"א בע\"א חשוב הכשר מצוה [ת\"ה] ונ\"ל דוקא אחר פלג המנחה כמ\"ש סי' תרע\"ב וכ\"מ בב\"ח:"],"r":["\u0003ס\"א בע\"ש. \u0004הוא דעת בה\"ג בסי' רס\"ג ס\"י:","\u0003ומברך. \u0004עמ\"א בשם ת\"ה ועתוס' דפ\"ק דיבמות ו' א' ד\"ה שכן. ונראה לר\"י כו' ואפ\"ה ה\"א דדחי. אבל ברשב\"א ור\"ן משמע דוקא משתשקע חמה או קודם. ע\"ש:"]}],["\u0010y0\u0011 בְּלֵיל שַׁבָּת צָרִיךְ \u0010y1\u0011 לִתֵּן שׁוּם דָּבָר, לַחוּץ \u0010y2\u0011 בֵּין הַנֵּרוֹת לַפֶּתַח, בִּשְׁבִיל הָרוּחַ שֶׁלֹּא יְכַבֶּה הַנֵּרוֹת כְּשֶׁפּוֹתֵחַ אֶת הַדֶּלֶת.\nבְּעֶרֶב שַׁבָּת אָסוּר לִקְבֹּעַ הַנֵּרוֹת \u0010y3\u0011 בַּדֶּלֶת עַצְמָהּ אֲחוֹרֵי הַדֶּלֶת, וְיֵשׁ מִי שֶׁמַּתִּיר \u0010y4\u0011 \u0005 וְעַיֵּן לְעֵיל סי' רע\"ז סָעִיף א'. \u0006",["\u0003בליל שבת וכו'\u0004 וה\"ה בחול צריך ליזהר בזה שלא להעמיד הנרות נגד המקום ששולט שם הרוח אלא דבשבת צריך שמירה יתירה בזה:","\u0003שום דבר לחוץ וכו'\u0004 היינו במקום שמדליקין הנרות נגד פתח הבית מבפנים [וגם במקום שמדליקין בכותל אחורי הדלת יש ליזהר בזה וכדלעיל בסימן רע\"ז ס\"א] אבל במקום שמדליקין בבית החורף ויש בית לפני בית החורף אין לחוש לכבוי דאפילו יכבה בפתיחתו אין זה פסיק רישא אם לא שיפתח בית החורף מכוון כנגד פתח הבית הפתוח לחצר או לר\"ה דאז יזהר לנעול פתח הבית קודם שיפתח פתח בית החורף [ב\"ח]:","\u0003בין הנרות לפתח וכו'\u0004 ואם לא נתן אסור לפתוח הדלת ועיין לעיל בסימן רע\"א בבה\"ל ד\"ה כדרכו:","\u0003בדלת עצמה וכו'\u0004 שפתיחתו ונעילתו מקרב השמן לנר או מרחיקו ממנה ויש בזה משום מכבה או מבעיר ואע\"ג דאינו מכוין לזה הוא פסיק רישא:","\u0003ועיין לעיל וכו'\u0004 ר\"ל דשם סתם לאיסור וכן הלכה:"],[],"\u0010y0\u0011 \u0010g0\u0011 בְּלֵיל שַׁבָּת \u0010m0\u0011 צָרִיךְ \u0010y1\u0011 לִתֵּן שׁוּם דָּבָר, לַחוּץ \u0010y2\u0011 בֵּין הַנֵּרוֹת לַפֶּתַח, בִּשְׁבִיל הָרוּחַ שֶׁלֹּא יְכַבֶּה הַנֵּרוֹת כְּשֶׁפּוֹתֵחַ אֶת הַדֶּלֶת. \u0010r0\u0011\nבְּעֶרֶב שַׁבָּת \u0010g1\u0011 אָסוּר לִקְבֹּעַ הַנֵּרוֹת \u0010y3\u0011 בַּדֶּלֶת עַצְמָהּ \u0010g2\u0011 אֲחוֹרֵי הַדֶּלֶת, \u0010g3\u0011 וְיֵשׁ מִי שֶׁמַּתִּיר \u0010y4\u0011 \u0005 וְעַיֵּן לְעֵיל סי' רע\"ז סָעִיף א'. \u0006 \u0010r1\u0011 \u0010r2\u0011",{"g":["טור ונתבאר בסי' רע\"ז","טור לפי פירש\"י","וה\"ה הדלת עצמו מצד חוץ והאי דנקט אחורי הדלת משום שמעשה רבי שמואל שהביא הר\"ם כך היה","שם בשם ר\"מ מרוטנבורג בשם רבו ה\"ר שמואל"],"m":["\u0003צריך ליתן\u0004. היינו במקום שמדליקין אצל פתח הבית:"],"r":["\u0003ס\"א בליל. \u0004כפרש\"י שם ק\"כ ב':","\u0003ס\"ב בערב שבת. \u0004כפי' תוס' שם:","\u0003ויש. \u0004דאמרי' שם נר שע\"ג טבלא כו' וכמש\"ש הרא\"ש לפי' הערוך וע\"ש תוס' ד\"ה פתח:"]}],["בְּמוֹצָאֵי שַׁבָּת אֵין מַבְדִּילִין בְּנֵר \u0010y0\u0011 חֲנֻכָּה, שֶׁאֵין נֶהֱנִים לְאוֹרוֹ וְאֵין מְבָרְכִין עַל הַנֵּר עַד שֶׁיֵּאוֹתוּ לְאוֹרוֹ.\nמַדְלִיקִין \u0010c0\u0011 נֵר חֲנֻכָּה בְּבֵית הַכְּנֶסֶת \u0010y1\u0011 קֹדֶם הַהַבְדָּלָה. \u0005 הַגָּה: \u0010y2\u0011 וְכָל שֶׁכֵּן בְּבֵיתוֹ שֶׁמַּדְלִיק וְאַחַר כָּךְ מַבְדִּיל, שֶׁהֲרֵי כְּבָר הִבְדִּיל בְּבֵית הַכְּנֶסֶת. \u0006",["\u0003אין מבדילין\u0004 ר\"ל שאם בירך תחלה על הדלקת נר חנוכה אין להבדיל עליהם אח\"כ מטעם הכתוב בשו\"ע אבל יכול לברך תחלה על הנר חנוכה להבדלה ולכבותה ולחזור ולהדליקה למצות נר חנוכה ועדיף טפי למיעבד הכי דכיון דעביד ביה מצוה חדא ליעבד ביה מצוה אחריתא אלא דכיון דקי\"ל דלאחר האפוקי יומא עדיף טפי כדלקמיה בס\"ב נוהגין להדליק נר חנוכה תחלה ושוב א\"א להבדיל עליו:","\u0003קודם ההבדלה\u0004 דאף דמצות הבדלה תדירה מ\"מ כל מה דנוכל לאחר לצאת מן השבת עדיף טפי וגם בהדלקה יש פרסומי ניסא ואם שכח אתה חוננתנו יאמר המבדיל בין קודש לחול ואח\"כ ידליק ואח\"כ אומרים ויתן לך ואח\"כ מבדילין:","\u0003וכ\"ש בביתו וכו' שהרי כבר הבדיל\u0004 ר\"ל וכבר שמע הבדלה ודבריו מגומגם דהא לא נתכוין לצאת בהבדלה של ש\"ץ ששמע בבהכ\"נ. ודע דט\"ז ועוד כמה אחרונים שעומדים בשיטתו פליגי על עיקר דינו של המחבר ורמ\"א וס\"ל דמצות הבדלה קודמת לנר חנוכה משום דהיא תדירה. ועיין בבה\"ל שהבאנו דיש בזה דיעות בין הראשונים וע\"כ בבהכ\"נ אין לשנות המנהג שנהגו בישראל להדליק מקודם ואח\"כ להבדיל ובבית דעביד כמר עביד ודעביד כמר עביד:"],["\u0003 מדליקין וכו' קודם ההבדלה\u0004 - עיין במ\"ב במה שכתבנו בשם הט\"ז ובאמת רבים אחרונים קיימי בשיטתיה דהבדלה קודמת המהר\"ל מפראג והתוי\"ט [הובא בא\"ר] ופר\"ח ודה\"ח וכן הרבה אחרונים קיימי בשיטת השו\"ע והרמ\"א הלא המה המגן אברהם והא\"ר והגר\"א ובית מאיר וכן בחמד משה השיב על כל ראיותיו של הט\"ז וכן בשאילת יעב\"ץ מסכים ג\"כ עם השולחן ערוך אכן באמת כבר נשמע ד\"ז בין החיים וכבר איפלגו בה קמאי לבד מה שהובא בב\"י שדעת תה\"ד דנר חנוכה קודם ומהרי\"ל ואגור וכל בו סוברים ג\"כ כמותו ור\"ד אבודרהם כתב שיש שמבדילין קודם כי הנה במאירי כתב שמנהגינו להדליק נ\"ח קודם הבדלה ובאשכול הלכות חנוכה כתוב וז\"ל ראיתי רבים מברכין קודם הבדלה ולי הכותב נראה שטעות בידם וכו' עי\"ש [עיין במחה\"ש וברכי יוסף וזכור לאברהם] וע\"כ הנכון להתנהג בזה כמו שהסכימו כמה אחרונים דבבהכ\"נ אין לשנות המנהג שנהגו מעולם להדליק נר חנוכה קודם ובביתו דעביד כמר עביד ודעביד כמר עביד וגם בפמ\"ג כתב דאין לגעור על שום אדם כי יש לו על מי לסמוך:"],"בְּמוֹצָאֵי שַׁבָּת אֵין מַבְדִּילִין בְּנֵר \u0010y0\u0011 \u0010g0\u0011 חֲנֻכָּה, שֶׁאֵין נֶהֱנִים לְאוֹרוֹ וְאֵין מְבָרְכִין עַל הַנֵּר עַד שֶׁיֵּאוֹתוּ לְאוֹרוֹ. \u0010g1\u0011\nמַדְלִיקִין \u0010c0\u0011 נֵר חֲנֻכָּה בְּבֵית הַכְּנֶסֶת \u0010y1\u0011 \u0010t0\u0011 \u0010s0\u0011 \u0010m0\u0011 קֹדֶם הַהַבְדָּלָה. \u0005 הַגָּה: \u0010y2\u0011 וְכָל שֶׁכֵּן בְּבֵיתוֹ שֶׁמַּדְלִיק וְאַחַר כָּךְ מַבְדִּיל, שֶׁהֲרֵי כְּבָר הִבְדִּיל בְּבֵית הַכְּנֶסֶת. \u0006 \u0010r0\u0011",{"g":["טור בשם הירו'","ת\"ה סי' ס'"],"t":["\u0003קודם. \u0004 ובמ\"צ כתב שמדליקין קודם ויתן לך. וכתב המ\"א דמי ששכח אתה חוננתנו יבדיל ואח\"כ ידליק דהא נהגו עכשיו האנשים שלא להדליק קודם הבדלה שבתפלה אם כן אסור להדליק כיון שלא הבדיל ומ\"מ בצבור לא יעשה כן רק יאמר המבדיל וידליק ואח\"כ יבדיל עכ\"ל. ומי\"ט כתב שהגאון מהר\"ל מפראג הנהיג להבדיל קודם וטעמא שמא ישכח להבדיל בתפלה ועביד איסור בהדלקה ומסיק שכן יש לנהוג וכ\"פ הט\"ז למעשה להבדיל בביתו עכ\"פ קודם ואח\"כ להדליק נר חנוכה ע\"ש: \u0005(ובספר אליה רבה העלה להלכה דלעולם מדליקין תחלה ואח\"כ מבדילין ודחה דברי ט\"ז בשתי ידים ע\"ש)\u0006:"],"s":["קודם. עבה\"ט ועיין בספרי שו\"ת בית אפרים מ\"ש בזה בדברי התה\"ד ובביאור דברי הט\"ז ובתשובת מהראנ\"ח סימן ע\"ט לענין מילה שלא בזמנה ופדיון הבן הי מינייהו קדים (ועיין מש\"ל סימן רמ\"ט וסימן תרס\"א על דברי המג\"א וכמ\"ש שם מהתוספות דמו\"ק דמילה כל יומא זמנה שאסור להניחו ערל) בביאור דברי הרא\"ש והטור סי' רפ\"ו עיין שם:"],"m":["\u0003קודם הבדלה\u0004. שמאחרין לצאת מן השבת ובמ\"צ כתב שמדליקין קודם ויתן לך ונ\"ל דמי ששכח אתה חוננתנו יבדיל ואח\"כ ידליק דלא נהיגי עכשיו האנשי' שלא להדליק קודם הבדלה שבתפל' כמ\"ש סי' רצ\"ט א\"כ אסור להדליק כיון שלא הבדיל ואף על גב שיכול לו' המבדיל כו' מ\"מ כיון שי\"א שלעולם מבדילין תחלה וא\"כ בכה\"ג יש לעשות כוותייהו ומכל מקום בצבור לא יעשה כן רק יאמר המבדיל וידליק ואחר כך יבדיל:"],"r":["\u0003ס\"ב מדליקין. \u0004ברכות נ\"ב א' אפוקי יומא כו' אע\"ג דברכת היום עדיפא לב\"ש מתדיר וכ\"ש לגבי תדיר וכ\"ש לשני תי' אחרונים שבתו' דשבת כ\"ג ב' ד\"ה הדר. ועוד כו'. והט\"ז הקשה דהא עדיף לב\"ה תדיר מעיולי יומא וכ\"ש מאפוקי יומא. ואשתמיטתי' דברי תה\"ד וש\"ע סי' תפ\"ט ס\"ט וכשחל י\"ט האחרון כו' וע' מש\"ש וכל דברי ט\"ז כאן דחויים עיין עליו:"]}],["כָּל שְׁמוֹנַת יְמֵי \u0010y0\u0011 חֲנֻכָּה אוֹמֵר עַל הַנִּסִים \u0010y1\u0011 בְּבִרְכַּת הַמָּזוֹן בְּבִרְכַּת הָאָרֶץ, וּבַתְּפִלָּה בְּבִרְכַּת מוֹדִים; וְאִם לֹא אָמַר, \u0010y2\u0011 אֵין מַחֲזִירִין אוֹתוֹ \u0005 וְעַיֵּן לְעֵיל סי' רצ\"ד סָעִיף ד' וְה'; \u0006 וּמִיהוּ אִם נִזְכַּר בְּאוֹתָהּ בְּרָכָה כָּל זְמַן שֶׁלֹּא הִזְכִּיר אֶת הַשֵּׁם, אֲפִלּוּ נִזְכַּר בֵּין אַתָּה לְהַשֵּׁם, חוֹזֵר. \u0005 הַגָּה: יֵשׁ אוֹמְרִים כְּשֶׁשָּׁכַח עַל הַנִּסִּים בְּבִרְכַּת הַמָּזוֹן \u0010y3\u0011 \u0006 \u0005 כְּשֶׁמַּגִּיעַ לְהָרַחֲמָן \u0010y4\u0011 יֹאמַר: הָרַחֲמָן יַעֲשֶׂה לָנוּ נִסִּים וְנִפְלָאוֹת כְּשֵׁם שֶׁעָשִׂיתָ לַאֲבוֹתֵינוּ בַּיָּמִים הַהֵם בַּזְּמַן הַזֶּה בִּימֵי מַתִּתְיָהוּ כו' \u0006 \u0005(כָּל בּוֹ)\u0006, \u0005 וּכְבָר נִתְבָּאֵר סִימָן קפ\"ז סָעִיף ד'. \u0006\nגַּם בְּמוּסָף שֶׁל שַׁבָּת וְשֶׁל \u0010y5\u0011 רֹאשׁ חֹדֶשׁ צָרִיךְ לְהַזְכִּיר שֶׁל חֲנֻכָּה, אַף עַל פִּי שֶׁאֵין מוּסָף \u0010y6\u0011 בַּחֲנֻכָּה.\nאֵין אוֹמְרִים: כְּשֵׁם שֶׁעָשִׂיתָ וְכֻלֵּי, אֶלָּא מְסַיֵּם: וְעָשִׂיתָ עִמָּהֶם נִסִים וּגְבוּרוֹת בַּיָּמִים הַהֵם בָּעֵת הַזֹּאת; \u0010y7\u0011 וְיֵשׁ אוֹמְרִים שֶׁאוֹמְרִים אוֹתוֹ.",["\u0003אומר על הנסים\u0004 כתוב בספרים שבנוסח על הניסים יאמר ועל הנסים בוי\"ו הן בתפלה הן בבהמ\"ז. כשעמדה עליהם יש לדלג תיבת עליהם דהא אח\"כ אומר על עמך ישראל אא\"כ אומר ועל עמך ישראל [פר\"ח]:","\u0003בברכת המזון בברכת הארץ ובתפלה בברכת מודים\u0004 הטעם דכולה מילתא דחנוכה עיקרה הודאה היא. ובברכה מעין שלש בחנוכה ופורים אין מזכירין של חנוכה ופורים:","\u0003אין מחזירין אותו\u0004 דלאו דאורייתא נינהו וקאי אתפלה ואברכת המזון ואין חילוק בבהמ\"ז בין בחול ובין בשבת חנוכה אף דמוכרח לאכול מצד שהוא שבת מ\"מ אינו חוזר בשביל על הניסים דחנוכה [פמ\"ג] ועיין בסימן קפ\"ח במ\"ב סוף סקל\"ג:","\u0003כשמגיע להרחמן וכו'\u0004 וה\"ה שיאמר כן בתפלה אחר גמר התפלה דרך בקשה קודם יהיו לרצון [א\"ר]:","\u0003יאמר הרחמן\u0004 וכן בפורים [לבוש] ובר\"ח שבחנוכה יאמר זה אחר הרחמן הוא יחדש וכו' משום דתדיר קודם:","\u0003צריך להזכיר\u0004 דיום הוא שנתחייב בארבעה תפלות. ואם לא אמרו אין מחזירין אותו:","\u0003אין אומרים כשם שעשית\u0004 י\"א משום דלא ישאל אדם צרכיו בג' ראשונות ואחרונות וטעות הוא דבשביל הצבור שרי אלא עיקר הטעם דכל דבר דהוי להבא תקנו בלהבא ובדבר דהודאה הוי לשעבר ועיקר על הניסים הוי כלשעבר [ב\"י]:","\u0003וי\"א שאומרים אותו\u0004 כתב ב\"י ודעביד כמר עביד ודעביד כמר עביד. בעל הניסים י\"ל להשכיחם תורתיך ולא יאמר מתורתיך במ\"ם. צ\"ל שמונת ימי חנוכה אלו להודות [מ\"א]:"],[],"\u0010g0\u0011 כָּל שְׁמוֹנַת יְמֵי \u0010y0\u0011 \u0010s0\u0011 חֲנֻכָּה אוֹמֵר עַל הַנִּסִים \u0010y1\u0011 בְּבִרְכַּת הַמָּזוֹן בְּבִרְכַּת הָאָרֶץ, וּבַתְּפִלָּה בְּבִרְכַּת מוֹדִים; \u0010g1\u0011 וְאִם לֹא אָמַר, \u0010y2\u0011 אֵין מַחֲזִירִין אוֹתוֹ \u0005 וְעַיֵּן לְעֵיל סי' רצ\"ד סָעִיף ד' וְה'; \u0010g2\u0011 \u0006 וּמִיהוּ אִם נִזְכַּר בְּאוֹתָהּ בְּרָכָה כָּל זְמַן שֶׁלֹּא הִזְכִּיר אֶת הַשֵּׁם, אֲפִלּוּ נִזְכַּר בֵּין אַתָּה לְהַשֵּׁם, חוֹזֵר. \u0005 הַגָּה: יֵשׁ אוֹמְרִים כְּשֶׁשָּׁכַח עַל הַנִּסִּים בְּבִרְכַּת הַמָּזוֹן \u0010y3\u0011 \u0010t0\u0011 \u0006 \u0005 כְּשֶׁמַּגִּיעַ לְהָרַחֲמָן \u0010y4\u0011 יֹאמַר: הָרַחֲמָן יַעֲשֶׂה לָנוּ נִסִּים וְנִפְלָאוֹת כְּשֵׁם שֶׁעָשִׂיתָ לַאֲבוֹתֵינוּ בַּיָּמִים הַהֵם בַּזְּמַן הַזֶּה בִּימֵי מַתִּתְיָהוּ כו' \u0006 \u0005(כָּל בּוֹ)\u0006, \u0005 וּכְבָר נִתְבָּאֵר סִימָן קפ\"ז סָעִיף ד'. \u0010g3\u0011 \u0006\nגַּם בְּמוּסָף שֶׁל שַׁבָּת וְשֶׁל \u0010y5\u0011 רֹאשׁ חֹדֶשׁ צָרִיךְ לְהַזְכִּיר שֶׁל \u0010m0\u0011 חֲנֻכָּה, אַף עַל פִּי שֶׁאֵין מוּסָף \u0010y6\u0011 \u0010g4\u0011 \u0010m1\u0011 בַּחֲנֻכָּה.\nאֵין אוֹמְרִים: כְּשֵׁם שֶׁעָשִׂיתָ וְכֻלֵּי, אֶלָּא מְסַיֵּם: וְעָשִׂיתָ עִמָּהֶם נִסִים וּגְבוּרוֹת בַּיָּמִים הַהֵם בָּעֵת הַזֹּאת; \u0010y7\u0011 \u0010g5\u0011 וְיֵשׁ אוֹמְרִים שֶׁאוֹמְרִים אוֹתוֹ. \u0010r0\u0011",{"g":["כרב הונא ורב ששת שבת כ\"ד","הרי\"ף והרא\"ש מהא דתני ר' אושעיא שם וכ\"כ התו' שם ובשם תוספתא דברכות וכ\"פ הטור בשמם","טור","מסקנת הגמ' שם","טור בשם י\"א ואביו הרא\"ש דלא ישאל אדם צרכיו לא בג' ראשונות ולא בג' אחרונות","שם בשם י\"א דכיון דצורך רבים הוא שרי וכ\"כ בא\"ח שכך היא הנוסחא ברוב התפלות וכ\"כ בנוסח הרמב\"ם ובמס' סופרים"],"t":["\u0003כשמגיע. \u0004 וה\"ה שיאמר כן בתפלה אחר גמר התפלה דרך בקשה. יש לומר הרשעה בחטף ב\"י. להשכיחם תורתך ולהעבירם חקי וכו' בלא ממי\"ן ש\"ג מרדכי וכ\"כ בכנה\"ג. בזמן בלא וא\"ו ט\"ז דלא כלבוש שכתב לומר ובזמן הזה בוא\"ו ע\"ש. וי\"ל שמונת ימי חנוכה אלו להודות וכו'. מ\"א:"],"s":["\u0003בש\"ע אומר על הנסים כו' \u0004 ועיין לעיל סימן תרע\"ו שגם גר יכול לומר שעשית לאבותינו כו' ומה שכתב אם נזכר באותה ברכה כו' ואם הזכיר השם וסיים הברכה אין רשאי לחזור כל שהוא באמצע תפלתו ואם יחזור הוי ברכה לבטלה כ\"כ בש\"ח בשם מטה יהודה ועיין שם בשם הרדב\"ז סי' תקס\"א שיכול לומר על הנסים או יעלה ויבא בין ברכה לברכ' שאין כאן ברכה לבטלה והפסק נמי לא הוי שהרי מעין הברכה היא וכת' שכן ראוי לנהוג והכנה\"ג הביא דברי הרדב\"ז בסתם וכן דעת מעדני המלך אך בבר\"י סי' קפ\"ח גמגם בזה עיין שם ועיין שם בשם מכתם לדוד מי ששכח עה\"נ והיה סבור שצריך לחזור ולהתחיל להתפלל ונזכר שטעה בדין שבאמת א\"צ לחזור יפסיק אפילו באמצע ברכה עיין שם ועיין שם במי ששכח על הניסים וכיוצא שאין צריך לחזור ורוצה להחמיר לחזור ולהתפלל צריך לכוין לשם נדבה וגם צריך שיהיה מכיר בעצמו שיוכל לכוין היטב בתפילתו מראש ועד סוף ואם יודע לחדש בה דבר ולא יוטרד טוב לעשות כן עיין שם ועבה\"ט בנוסח עה\"נ שיאמ' הרשעה בחטף ובפר\"ת כת' לקרות בחירק תחת הרי\"ש ומ\"ש להעבירם חוקי רצונך כת' הפר\"ח שיותר נכון לומר מחוקי רצונך וכ\"כ אבודרהם שכן הוא בסדר רב סעדיה וכ\"כ מהר\"ם מרוטנבורג ע' שם:"],"m":["\u0003הרשעה בחט\"ף [ב\"י], להשכיח' תורתך ולהעבירם חוקי וכו'\u0004 בלא ממי\"ן [ש\"ג במרדכי] וכ\"ה בכ\"ה בשם רד\"א, י\"א אלו להודות וכו' ול\"נ שי\"ל ימי חנוכה אלו כמו שאנו אומרים ותתן לנו את יום חג פלוני הזה: \u0003אף על פי שאין מוסף\u0004. דיום הוא שנתחייב בד' תפלות:","\u0003א\"א כשם\u0004. דלא ישאל צרכיו בג' אחרונות וי\"א ס\"ל דצרכי רבים שאני כמו בזכרנו ומי כמוך:"],"r":["\u0003ס\"ג אין אומרין. \u0004עתוס' במגילה ד' א' ד\"ה פסק. משום דאמרו חכמים כו':"]}],["כָּל שְׁמוֹנַת יְמֵי \u0010y0\u0011 חֲנֻכָּה גּוֹמְרִין אֶת הַהַלֵּל. \u0005 הַגָּה: וְכָל שְׁמוֹנַת יְמֵי חֲנֻכָּה \u0006 \u0005 אֵין אוֹמְרִים תַּחֲנוּן וצו\"ץ וְלַמְנַצֵּחַ וְצִדּוּק הַדִּין גַּם בְּעֶרֶב חֲנֻכָּה בְּמִנְחָה, וְעַיֵּן לְעֵיל סי' קל\"א \u0006 \u0005(מַהֲרִי\"ל וּמִנְהָגִים)\u0006.",["\u0003גומרין את ההלל\u0004 לפי שבכל יום נוסף נס חדש ועוד יש טעמים עיין בב\"י. ואחר ההלל אומרים חצי קדיש. מי שהוא אבל בשחרית אין מתפלל לפני העמוד דיש הלל הא ערבית מתפלל דמתפלל בר\"ח ג\"כ ערבית. אין אומרים אל ארך אפים בב' וה' בחנוכה ויה\"ר אחר ס\"ת. ולענין הלל אם מותר לומר בבית האבל עיין בשע\"ת אבל האבל בעצמו בודאי לא יאמר:"],[],"\u0010g0\u0011 \u0010s0\u0011 כָּל שְׁמוֹנַת יְמֵי \u0010y0\u0011 חֲנֻכָּה גּוֹמְרִין אֶת הַהַלֵּל. \u0005 הַגָּה: וְכָל שְׁמוֹנַת יְמֵי \u0010t0\u0011 חֲנֻכָּה \u0006 \u0005 אֵין אוֹמְרִים תַּחֲנוּן וצו\"ץ וְלַמְנַצֵּחַ וְצִדּוּק הַדִּין גַּם בְּעֶרֶב חֲנֻכָּה בְּמִנְחָה, וְעַיֵּן לְעֵיל סי' קל\"א \u0006 \u0005(מַהֲרִי\"ל וּמִנְהָגִים)\u0006.",{"g":["מימרא דר\"י משום דר' יהוצדק ערכין ו' והטעם מפני שהנס נתחדש בכל יום ועוד שכל נשיא שלו חלוק משל חבירו וכ\"א צריך לגמור הלל על קרבנותיו שבולי הלקט."],"t":["\u0003אין. \u0004 כתב הכלבו אין אומרים שיר מזמור לאסף לפי שהם כעין יום טוב מאחר שאומרים בו הלל:"],"s":["\u0003גומרים ההלל וכו' \u0004 והפר\"ח כת' שאין לומר הלל בבית האבל ובא\"ר סימן קל\"א כת' שאומרים וכ\"כ במח\"ב כא דפשוט שיאמרו בחנוכה הלל בבית האבל והמגן אברהם סימן קל\"ה כת' שבחנוכה טוב שיקרא כ\"א בביתו הביאו בה\"ט שם ע\"ש:"]}],["קוֹרִין בְּקָרְבְּנוֹת \u0010y0\u0011 הַנְּשִׂיאִים שֶׁבְּפָרָשַׁת נָשׂא, שְׁלֹשָׁה בְּכָל יוֹם; וּמַתְחִילִין בְּבִרְכַּת \u0010y1\u0011 כֹּהֲנִים \u0005 וְיֵשׁ אוֹמְרִים שֶׁמַּתְחִילִין בְּיוֹם כַּלּוֹת מֹשֶׁה \u0006 \u0005(טוּר)\u0006, \u0005 וְכֵן אָנוּ נוֹהֲגִין, \u0006 וְקוֹרֵא אוֹתוֹ \u0010y2\u0011 עִם כֹּהֵן וְלֵוִי, וְיִשְׂרָאֵל קוֹרֵא בַּיּוֹם הָרִאשׁוֹן. \u0005 וְיֵשׁ אוֹמְרִים שֶׁהַכֹּהֵן קוֹרֵא כָּל אוֹתָהּ הַפָּרָשָׁה עַד בַּיּוֹם הָרִאשׁוֹן, וְהַלֵּוִי וְהַיִּשְׂרָאֵל קוֹרִין בַּיּוֹם הָרִאשׁוֹן \u0006 \u0005(מִנְהָגִים)\u0006 \u0005 וְכֵן נוֹהֲגִין; \u0006 בְּיוֹם שֵׁנִי קוֹרֵא כֹּהֵן בַּיּוֹם הַשֵּׁנִי עַד פַּר אֶחָד בֶּן בָּקָר, וְלֵוִי עַד בַּיּוֹם הַשְּׁלִישִׁי, וְיִשְׂרָאֵל חוֹזֵר וְקוֹרֵא: בַּיּוֹם הַשֵּׁנִי, וְעַל דֶּרֶךְ זֶה בְּכָל יוֹם. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁיִּשְׂרָאֵל קוֹרֵא בַּיּוֹם שֶׁלְּאַחֲרָיו, דְּהַיְנוּ בַּיּוֹם הַג', וְכֵן בְּכָל יוֹם; וְכֵן נוֹהֲגִין \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פי\"ג)\u0006; בְּיוֹם שְׁמִינִי מַתְחִילִין: בַּיּוֹם \u0010y3\u0011 הַשְּׁמִינִי, וְגוֹמְרִין כָּל הַסֵדֶר, וְקוֹרִין פָּרָשָׁה רִאשׁוֹנָה שֶׁל בְּהַעֲלוֹתְךָ \u0005 וְנוֹהֲגִים לְסַיֵּם כֵּן עָשָׂה אֶת הַמְּנוֹרָה \u0006 \u0005(מִנְהָגִים)\u0006.\nבְּשַׁבָּת שֶׁבַּחֲנֻכָּה מוֹצִיאִין ב' סְפָרִים; בְּאֶחָד קוֹרֵא \u0010y4\u0011 בְּפָרָשַׁת הַשָּׁבוּעַ, וּבַשֵּׁנִי קוֹרֵא \u0010y5\u0011 בְּשֶׁל \u0010y6\u0011 חֲנֻכָּה, וּמַפְטִיר: רָנִּי וְשִׂמְחִי; וְאִם חָלוּ בּוֹ שְׁתֵּי שַׁבָּתוֹת, מַפְטִיר בַּשֵּׁנִי בִּמְלָכִים, בְּנֵרוֹת דִּשְׁלֹמֹה. \u0005 הַגָּה: וְאִם חָל חֲתֻנָּה בְּשַׁבָּת זוֹ, \u0010y7\u0011 מַפְטִירִין בְּשֶׁל חֲנֻכָּה \u0006 \u0005(מִנְהָגִים)\u0006.\nאִם חָל רֹאשׁ חֹדֶשׁ טֵבֵת בְּשַׁבָּת, מוֹצִיאִין ג' סְפָרִים וְקוֹרִין ו' \u0010y8\u0011 בְּפָרָשַׁת הַשָּׁבוּעַ, וּבַשֵּׁנִי קוֹרֵא \u0010y9\u0011 אֶחָד בְּשֶׁל רֹאשׁ חֹדֶשׁ וּמַתְחִיל: וּבְיוֹם הַשַּׁבָּת, וּבַג' קוֹרֵא מַפְטִיר בְּשֶׁל \u0010y10\u0011 חֲנֻכָּה וּמַפְטִיר: רָנִּי וְשִׂמְחִי; \u0010y11\u0011 וְאִם חָל רֹאשׁ חֹדֶשׁ בַּחֹל, מוֹצִיאִין ב' סְפָרִים וְקוֹרִין בְּאֶחָד ג' בְּשֶׁל רֹאשׁ חֹדֶשׁ, וּבַשֵּׁנִי קוֹרֵא אֶחָד בְּשֶׁל חֲנֻכָּה. וְאִם טָעָה הַחַזָּן \u0010y12\u0011 וְקָרָא ד' בְּשֶׁל רֹאשׁ חֹדֶשׁ, אִם לֹא הוֹצִיאוּ סֵפֶר ב' \u0010y13\u0011 אֵינוֹ צָרִיךְ לִקְרוֹת יוֹתֵר; אֲבָל אִם הוֹצִיאוּ סֵפֶר \u0010y14\u0011 ב', מִשּׁוּם פְּגָמוֹ צָרִיךְ \u0010y15\u0011 לִקְרוֹת חֲמִישִׁי בְּשֶׁל חֲנֻכָּה. \u0005 הַגָּה: וְאִם טָעָה וְהִתְחִיל \u0010c0\u0011 לִקְרוֹת בְּשֶׁל \u0010y16\u0011 חֲנֻכָּה צָרִיךְ \u0006 \u0005 לְהַפְסִיק לִקְרוֹת בְּשֶׁל רֹאשׁ חֹדֶשׁ \u0006 \u0005(אַבּוּדַרְהַם הִלְכוֹת בְּרָכוֹת)\u0006; \u0010y17\u0011 \u0005 וְאִם צָרִיךְ לְבָרֵךְ \u0010c1\u0011 עַל קְרִיאַת רֹאשׁ חֹדֶשׁ, עַיִּןִ לְעֵיל סִימָן ק\"מ. \u0006",["\u0003הנשיאים\u0004 משום שנגמר מלאכת המשכן בכ\"ה בכסליו:","\u0003כהנים\u0004 לפי שנעשה הנס ע\"י כהנים:","\u0003עם כהן ולוי\u0004 כהן יקרא עד לפני המשכן או עד לחנוכת המזבח והשאר יקראו לוי וישראל אבל אותם שנהגו לקרות לכהן עד ואני אברכם הוא מנהג בטעות וצריך לבטלו שהשלשה צריכין שיקראו בסדר היום וסדר היום הוא פרשת נשיאים. ואחר הקריאה אומרים ח\"ק. אם טעו וקראו ביום שני של חנוכה פרשת נשיא ג' וכיוצא עלתה להם דאין קפידא בימים:","\u0003השמיני\u0004 כהן ולוי קורא בקרבנו של גמליאל וישראל גומר וכו':","\u0003השבוע\u0004 שבעה קרואים לפחות ואומר ח\"ק:","\u0003בשל חנוכה\u0004 ואם הוא יום א' של חנוכה מתחיל מויהי ביום כלות [לבוש] המפטיר יקרא רק נשיא אחד דיום ההוא לבד וכן בר\"ח שבחנוכה קורים להרביעי רק נשיא אחד לבד של אותו היום דהיינו יום הששי ואם ר\"ח טבת שני ימים קורא ביום ב' דר\"ח שהוא ז' דחנוכה נשיא הז' לבד:","\u0003ומפטיר רני ושמחי\u0004 על שם ראיתי והנה מנורת זהב כולה:","\u0003מפטירין בשל חנוכה\u0004 ר\"ל אף דבעלמא המנהג בשבת שיש חתן לדחות הפטרת השבוע ולקרות הפטרת שוש אשיש שהוא מענינא דחתן כמבואר לעיל בסוף סי' תכ\"ח מ\"מ בשבת חנוכה בין בשבת ראשון בין בשבת שני אין לדחות של חנוכה דפרסומי ניסא עדיף והנה המ\"א הביא די\"א דה\"מ בשבת ראשונה אבל אם איקלע חתן בשבת שניה מפטירין שוש אשיש ואין מפטירין בשל חנוכה הואיל וכבר הפטירו בשל חנוכה בשבת ראשון אבל בא\"ר כתב דמרמ\"א משמע דבין בשבת ראשון ובין בשני קורין רק של חנוכה לחוד וכן נוהגין:","\u0003בפרשת השבוע\u0004 וה\"ה אם רוצים לקרות בה ז' או יותר מן ז' ג\"כ שרי והעיקר דבין כולם לא יפחות משבעה. כשגומר פרשת השביעי מניחין הס\"ת הב' ואין אומרין קדיש רק מגביהין הראשונה וגוללין אותה ופושטין השניה וקורא בה וכשאומרין קדיש על השניה מניחין השלישית אצלה:","\u0003בשל ר\"ח\u0004 דתדיר קודם:","\u0003ומפטיר רני ושמחי\u0004 דהא דתדיר קודם היינו להקדים אבל לענין לדחות פרסומי ניסא עדיף ועוד דכיון דקורא בשל חנוכה באחרונה יש להפטיר במאי דסליק מניה:","\u0003ואם חל ר\"ח בחול\u0004 סדר קריאת התורה בר\"ח בחול. מתחיל פ' התמיד כהן עד רביעית ההין. לוי עד ונסכה. ישראל עד ונסכו. והרביעי קורא בחנוכה [פמ\"ג]:","\u0003וקרא רביעי בשל ר\"ח\u0004 וה\"ה טעה ונזדמן בשבת חנוכה:","\u0003א\"צ לקרות יותר\u0004 דאין משגיחין בחנוכה דר\"ח עיקר ואפילו אם נזכרו בתחילת קריאת הרביעי אין לומר שרביעי עצמו יקרא בס\"ת זו בשל חנוכה קודם שיחתום בפרשת ר\"ח דה\"ל מדלג ואין מדלגין בתורה בשני ענינין כדלעיל בסימן קמ\"ד אלא מאחר שהרביעי התחיל לקרות בשל ר\"ח יחתום ויברך ויבוא חמישי אחריו ויקרא בס\"ת השניה אם הוציאוה בשל חנוכה:","\u0003משום פגמו\u0004 דמוטב לבטל הא דאמרינן דבר\"ח אין מוסיפין על ארבעה מלפגום הס\"ת [ב\"י]:","\u0003לקרות חמישי וכו'\u0004 ויאמר קדיש אחריו ואם אמר קדיש אחר הרביעי לא יאמרנו אחר החמישי:","\u0003צריך להפסיק\u0004 עיין בט\"ז שכתב דהאי פסקא לאו דסמכא הוא ואין צריך להפסיק אלא קורא כהן בשל חנוכה ואח\"כ יקרא לאחרים בשל ר\"ח ועיין בבה\"ל שביררנו כל הפרטים שיש בזה:","\u0003ואם צריך לברך וכו'\u0004 עיין בבה\"ל:"],["\u0003 ואם טעה והתחיל וכו' צריך להפסיק וכו'\u0004 - עיין במ\"ב במה שכתבנו בשם הט\"ז דחולק ע\"ז ופוסק דמכיון שהתחיל לקרות בשל חנוכה צריך לגמור הכהן בשל חנוכה והנה בא\"ר מצדד דאם לא קרא עדיין ג' פסוקים בשל חנוכה יפסיק באמצע ויקרא בשל ר\"ח [דאם קרא ג' פסוקים מודה לדעת הט\"ז דיברך הכהן ברכה אחרונה ויקראו לאחרים בשל ר\"ח וא\"צ לחזור ולקרות של חנוכה] וכן מצדד קצת בספר מור וקציעה מ\"מ הרבה אחרוני' [הבגדי ישע והשולחן שלמה ובספר פני יצחק ס\"ט והדה\"ח והח\"א] ומכללם גם המגן אברהם בסימן ק\"מ בסופו הורו להלכה כדברי הט\"ז דכיון שהתחיל בשל חנוכה צריך לגמור הכהן בשל חנוכה בס\"ת זו ואח\"כ יקראו הג' בס\"ת אחרת בר\"ח (ואף שבסימן זה פירש מגן אברהם הטעם לדברי הרמ\"א מ\"מ להלכה בודאי דעתו כמו שכתב שם) והתחלה נקרא משהתחיל לברך הברכה דהיינו שאמר ברוך אתה ד' אבל אם לא התחיל לברך אף שנזדמן בידם אותה שהוא מתוקן לחנוכה אין לו לחוש לזה לכו\"ע ויגללוה ויקראו בס\"ת אחרת שהוציאוה לשם ר\"ח ואין כאן פגם לס\"ת זו כיון שיקראו בה אח\"כ [אחרונים] ובר\"ח טבת שחל בשבת שצריך להוציא ג' ספרים ועניני חנוכה קורין בשלישית כנ\"ל אם טעו וקראו בשני בשל חנוכה ובשלישית בשל ר\"ח מ\"מ קורין ההפטרה בשל חנוכה משום פרסומי ניסא [ח\"א] וכעין זה מצדד גם הפמ\"ג בסוף דבריו עי\"ש ומ\"מ בדיעבד אם קראו הפטרה של ר\"ח השמים כסאי יצאו [שם] מי שיש לו יא\"צ בחנוכה לא יחשוב לפי ימי החנוכה אלא לפי ימי החודש שהרי לפעמים ר\"ח טבת יום א' ולפעמים שני ימים:","\u0003 ואם צריך לברך וכו' ע\"ל סימן ק\"מ\u0004 - ר\"ל דשם יש שני דיעות בזה ואחרונים כתבו שם דנוהגין למעשה כהדעה שסוברת דצריך לברך וכן פסק בשערי אפרים דצריך לברך על קריאת ר\"ח לפניה ולאחריה:"],"\u0010g0\u0011 קוֹרִין בְּקָרְבְּנוֹת \u0010y0\u0011 הַנְּשִׂיאִים שֶׁבְּפָרָשַׁת נָשׂא, שְׁלֹשָׁה בְּכָל יוֹם; \u0010g1\u0011 וּמַתְחִילִין בְּבִרְכַּת \u0010y1\u0011 כֹּהֲנִים \u0005 וְיֵשׁ אוֹמְרִים שֶׁמַּתְחִילִין בְּיוֹם כַּלּוֹת מֹשֶׁה \u0006 \u0005(טוּר)\u0006, \u0005 וְכֵן אָנוּ נוֹהֲגִין, \u0010g2\u0011 \u0006 וְקוֹרֵא אוֹתוֹ \u0010y2\u0011 עִם כֹּהֵן וְלֵוִי, וְיִשְׂרָאֵל קוֹרֵא בַּיּוֹם הָרִאשׁוֹן. \u0005 וְיֵשׁ אוֹמְרִים שֶׁהַכֹּהֵן קוֹרֵא כָּל אוֹתָהּ הַפָּרָשָׁה עַד בַּיּוֹם הָרִאשׁוֹן, וְהַלֵּוִי וְהַיִּשְׂרָאֵל קוֹרִין בַּיּוֹם הָרִאשׁוֹן \u0006 \u0005(מִנְהָגִים)\u0006 \u0005 וְכֵן נוֹהֲגִין; \u0010g3\u0011 \u0006 בְּיוֹם שֵׁנִי קוֹרֵא כֹּהֵן בַּיּוֹם הַשֵּׁנִי עַד פַּר אֶחָד בֶּן בָּקָר, וְלֵוִי עַד בַּיּוֹם הַשְּׁלִישִׁי, וְיִשְׂרָאֵל חוֹזֵר וְקוֹרֵא: בַּיּוֹם הַשֵּׁנִי, וְעַל דֶּרֶךְ זֶה בְּכָל יוֹם. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁיִּשְׂרָאֵל קוֹרֵא בַּיּוֹם שֶׁלְּאַחֲרָיו, דְּהַיְנוּ בַּיּוֹם הַג', וְכֵן בְּכָל יוֹם; וְכֵן נוֹהֲגִין \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פי\"ג)\u0006; \u0010g4\u0011 בְּיוֹם שְׁמִינִי מַתְחִילִין: בַּיּוֹם \u0010y3\u0011 הַשְּׁמִינִי, וְגוֹמְרִין כָּל הַסֵדֶר, וְקוֹרִין פָּרָשָׁה רִאשׁוֹנָה שֶׁל בְּהַעֲלוֹתְךָ \u0005 וְנוֹהֲגִים לְסַיֵּם כֵּן עָשָׂה אֶת הַמְּנוֹרָה \u0006 \u0005(מִנְהָגִים)\u0006. \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011\nבְּשַׁבָּת שֶׁבַּחֲנֻכָּה מוֹצִיאִין ב' סְפָרִים; בְּאֶחָד קוֹרֵא \u0010y4\u0011 בְּפָרָשַׁת הַשָּׁבוּעַ, וּבַשֵּׁנִי קוֹרֵא \u0010y5\u0011 בְּשֶׁל \u0010y6\u0011 \u0010g5\u0011 חֲנֻכָּה, וּמַפְטִיר: רָנִּי וְשִׂמְחִי; וְאִם חָלוּ בּוֹ שְׁתֵּי שַׁבָּתוֹת, מַפְטִיר \u0010g6\u0011 בַּשֵּׁנִי בִּמְלָכִים, בְּנֵרוֹת דִּשְׁלֹמֹה. \u0005 הַגָּה: וְאִם חָל חֲתֻנָּה בְּשַׁבָּת זוֹ, \u0010y7\u0011 מַפְטִירִין \u0010t0\u0011 \u0010m0\u0011 בְּשֶׁל חֲנֻכָּה \u0006 \u0005(מִנְהָגִים)\u0006. \u0010g7\u0011 \u0010r4\u0011\nאִם חָל רֹאשׁ חֹדֶשׁ טֵבֵת בְּשַׁבָּת, מוֹצִיאִין ג' סְפָרִים וְקוֹרִין ו' \u0010y8\u0011 בְּפָרָשַׁת הַשָּׁבוּעַ, \u0010m1\u0011 וּבַשֵּׁנִי קוֹרֵא \u0010y9\u0011 אֶחָד בְּשֶׁל רֹאשׁ חֹדֶשׁ וּמַתְחִיל: וּבְיוֹם הַשַּׁבָּת, וּבַג' קוֹרֵא מַפְטִיר בְּשֶׁל \u0010y10\u0011 \u0010g8\u0011 חֲנֻכָּה וּמַפְטִיר: רָנִּי וְשִׂמְחִי; \u0010y11\u0011 \u0010g9\u0011 וְאִם חָל רֹאשׁ חֹדֶשׁ בַּחֹל, מוֹצִיאִין ב' סְפָרִים וְקוֹרִין בְּאֶחָד ג' בְּשֶׁל רֹאשׁ חֹדֶשׁ, וּבַשֵּׁנִי קוֹרֵא אֶחָד בְּשֶׁל \u0010g10\u0011 חֲנֻכָּה. וְאִם טָעָה הַחַזָּן \u0010y12\u0011 וְקָרָא ד' בְּשֶׁל רֹאשׁ חֹדֶשׁ, אִם לֹא הוֹצִיאוּ סֵפֶר ב' \u0010y13\u0011 \u0010t1\u0011 \u0010m2\u0011 אֵינוֹ צָרִיךְ לִקְרוֹת יוֹתֵר; אֲבָל אִם הוֹצִיאוּ סֵפֶר \u0010y14\u0011 ב', מִשּׁוּם פְּגָמוֹ צָרִיךְ \u0010y15\u0011 \u0010t2\u0011 \u0010s0\u0011 \u0010m3\u0011 לִקְרוֹת חֲמִישִׁי בְּשֶׁל חֲנֻכָּה. \u0005 הַגָּה: וְאִם טָעָה וְהִתְחִיל \u0010c0\u0011 לִקְרוֹת בְּשֶׁל \u0010y16\u0011 \u0010m4\u0011 חֲנֻכָּה צָרִיךְ \u0010t3\u0011 \u0010s1\u0011 \u0010s2\u0011 \u0006 \u0005 לְהַפְסִיק לִקְרוֹת בְּשֶׁל רֹאשׁ חֹדֶשׁ \u0006 \u0005(אַבּוּדַרְהַם הִלְכוֹת בְּרָכוֹת)\u0006; \u0010y17\u0011 \u0005 וְאִם צָרִיךְ לְבָרֵךְ \u0010c1\u0011 עַל קְרִיאַת רֹאשׁ חֹדֶשׁ, עַיִּןִ לְעֵיל סִימָן ק\"מ. \u0006 \u0010r5\u0011",{"g":["משנה מגילה ל\"א דאי' בפסיקתא שבכ\"ה בכסליו נשלם מלאכת המשכן טור","שם בשם יש מקומות","שם בטור","שם","שם","בריי' שם במגילה","שם ואע\"ג דנרות דשלמה קדימי טפי אפ\"ה עדיפא לן דזכריה דנבואות עתיד נינהו ר\"ן","מימרא דר' יצחק נפחא מגילה כ\"ט","במאי דסליק מיניה ועוד דפרסומי ניסא עדיף הרא\"ש","מימרא דר' יצחק שם","רוקח והכל בו בשם רש\"י"],"t":["\u0003בשל חנוכה. \u0004 ומקצת שוש אשיש עיין סימן תכ\"ה סעיף ב'. וי\"א דבשבת שני מפטירין שוש אשיש. לבוש:","\u0003א\"צ לקרות יותר. \u0004 דאין משגיחין בחנוכה:","\u0003לקרות חמישי. \u0004 ויאמר קדיש אחריו ואם אמר קדיש אחר הרביעי לא יאמרנו אחר החמישי תשובת מהרי\"ל סימן רי\"ב. ועיין סימן רפ\"ב ס\"ו וססי' קמ\"ד ואפי' נזכרו בקריאת הרביעי אל יקרא הוא בחנוכה דאין מדלגין כמ\"ש סימן קמ\"ד. ב\"י ש\"ל מ\"א:","\u0003להפסיק. \u0004 והט\"ז כתב דהאי פסקא דרמ\"א לאו דסמכא הוא ואינו צריך להפסיק אלא קורא כהן בשל חנוכה ואח\"כ יקרא לאחרים בשל ר\"ח וכתב שכן הסכים הרב הגאון מוהר\"ר נפתלי כ\"ץ ז\"ל ע\"ש ועיין בגינת ורדים חא\"ח כלל א' סי' ל\"ו:"],"s":["\u0003בש\"ע קורים בקרבנות כו' \u0004 ע' בדינים אלו ובדין טעות בקריאה בספרי שער אפרים שער ח' ותמצא הכל מבואר היטב:","\u0003לקרות. \u0004 עבה\"ט וע' בתוספת דמגילה דף כ\"ט ובשאילת שלום אות ל\"ו ומ\"ש בזה בספרי בית אפרים סימן י\"ח להגאון מוהר\"מ ז\"ל בעמ\"ח ש\"ש:","\u0003להפסיק. \u0004 ע' בה\"ט וט' ביד אפרים מ\"ש בזה על הט\"ז ובספרי שו\"ת בית אפרים סי' י\"ח כתבתי בארוכה יותר בזה ע\"ש:"],"m":["\u0003בשל חנוכה\u0004. ומקצת שוש אשיש עיין סימן תכ\"ה ס\"ב וי\"א דבשבת שני מפטירין שוש אשיש [לבוש]:","\u0003ובב' קורא א' בשל ר\"ח\u0004. דתדיר קודם ומפטיר רני ושמחי דהא דתדיר קודם היינו להקדי' אבל לדחות פרסומא ניסא עדיף ובתוספ' סוכה דף נ\"ד ע\"ב משמע דס\"ל דאפי' לדחות תדיר קוד' ע\"ש ויש ליישב:","\u0003א\"צ לקרות יותר\u0004. דאין משגיחין בחנוכה:","\u0003לקרות חמישי\u0004. ויאמר קדיש אחריו ואם אמר קדיש אחר הרביעי לא יאמרנו אחר החמישי (תשו' מהרי\"ל סי' רי\"ב) עסי' רפ\"ב ס\"ו וססי' קמ\"ז ואפי' נזכרו בקריא' הרביעי אל יקרא הוא בחנוכה דאין מדלגין כמ\"ש סי' קמ\"ד (ב\"י ש\"ל):","\u0003צריך להפסיק\u0004. אף על גב דאין מעבירין על המצות הכא מעכבות דדמי להקדים תפילין של ראש לשל יד (שם):"],"r":["\u0003ס\"א ומתחילין. \u0004דהנס נעשה על ידם. טור:","\u0003וי\"א. \u0004מבואר:","\u0003ביום שני. וי\"א. \u0004תליא בפלוגתא דלעיל סי' ת\"ד ס\"ג ע\"ש וטעם ס' הראשונה שאין לקרות שלא מענין היום כמ\"ש ברפ\"ג דמגילה שאני התם דאפשר כו' וס' שניה ס\"ל דמיום המחרת אינה שלא מענין היום וכ\"כ תוס' סוף סוכה נ\"ה א' ד\"ה אתקין ע\"ש. וראיה ממעמדות שהיה דולג בבראשית וקורא יהי רקיע ובתוספתא פ\"ב דמגילה משמע כסברא ראשונה:","\u0003וקורין פרשה. \u0004כדי לסיים בנרות טור וע' בפסיקתא דפ' בהעלותך:","\u0003ס\"ב ומפטיר. \u0004תוס' דשבת כנ\"ל:","\u0003ס\"ג ואם טעה החזן. \u0004ואם טעה. מדאמרי' שם אין משגיחין בחנוכה:"]}],["\u0010y0\u0011 רֹאשׁ חֹדֶשׁ אֲדָר הַסָמוּךְ לְנִיסָן שֶׁחָל לִהְיוֹת בְּשַׁבָּת, \u0010y1\u0011 קוֹרִין פָּרָשַׁת שְׁקָלִים שֶׁהִיא כִּי תִשָּׂא, עַד וִעָשִׂיתָ כִּיּוֹר \u0010y2\u0011 נְחֹשֶׁת, וּמַפְטִיר: וַיִּכְרֹת יְהוֹיָדָע; וּמוֹצִיאִין שְׁלֹשָׁה סְפָרִים: בְּאַחַת קוֹרֵא פָּרָשַׁת \u0010y3\u0011 הַשָּׁבוּעַ, \u0010y4\u0011 וּבַשֵּׁנִי שֶׁל רֹאשׁ חֹדֶשׁ, וּבַשְּׁלִישִׁי קוֹרֵא מַפְטִיר בְּפָרָשַׁת שְׁקָלִים.\nבְּשַׁבָּת שְׁנִיָּה מוֹצִיאִין שְׁנֵי סְפָרִים; בְּאֶחָד קוֹרֵא פָּרָשַׁת \u0010y5\u0011 הַשָּׁבוּעַ, וּבַשֵּׁנִי קוֹרֵא: זָכוֹר אֶת אֲשֶׁר עָשָׂה לְךָ \u0010y6\u0011 עֲמָלֵק, וּמַפְטִיר: \u0010y7\u0011 פָּקַדְתִּי אֶת אֲשֶׁר עָשָׂה עֲמָלֵק.\nבְּשַׁבָּת שְׁלִישִׁית, שֶׁהוּא ט\"ו בְּאֲדָר, מַפְסִיקִין; וּבְשַׁבָּת ד' שֶׁהִיא כ\"ב לְאֲדָר מוֹצִיאִין שְׁנֵי סְפָרִים; בְּאֶחָד קוֹרֵא \u0010y8\u0011 בְּפָרָשַׁת הַשָּׁבוּעַ, וּבַשֵּׁנִי קוֹרֵא פָּרָשַׁת \u0010y9\u0011 פָּרָה, וּמַפְטִיר: וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים \u0010y10\u0011 \u0005 וְעַיֵּן לְעֵיל סי' קל\"ז סָעִיף ה'. \u0006\nבְּשַׁבָּת חֲמִישִׁי, שֶׁהוּא כ\"ט בַּאֲדָר, מוֹצִיאִין ב' סְפָרִים: בְּאֶחָד קוֹרֵא פָּרָשַׁת \u0010y11\u0011 הַשָּׁבוּעַ, וּבַשֵּׁנִי: הַחֹדֶשׁ הַזֶּה \u0010y12\u0011 לָכֶם, וּמַפְטִיר: בָּרִאשׁוֹן בְּאֶחָד לַחֹדֶשׁ.\nחָל רֹאשׁ חֹדֶשׁ אֲדָר הַסָמוּךְ לְנִיסָן בְּתּוֹךְ יְמֵי הַשָּׁבוּעַ, וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת, מַקְדִּימִין לִקְרוֹת פָּרָשַׁת שְׁקָלִים בְּשַׁבָּת שֶׁלְּפָנָיו, וּמַפְסִיקִין בַּשְּׁנִיָּה כְּדֵי שֶׁתְּהֵא פָּרָשַׁת זָכוֹר בַּשַּׁבָּת הַסְמוּכָה לְפוּרִים מִלְּפָנֶיהָ; וְאִם חָל פּוּרִים בְּעֶרֶב שַׁבָּת, מַקְדִּימִים לִקְרוֹת פָּרָשַׁת זָכוֹר בְּשַׁבָּת שֶׁלְּפָנָיו.\nהַיָּמִים שֶׁרָאוּי לִקְבֹּעַ בָּהֶם רֹאשׁ חֹדֶשׁ אֲדָר, זבד\"ו; וְסִימָן לְשַׁבְּתוֹת הַהַפְסָקָה, זט\"ו ב\"ו ד\"ד ובי\"ו, כְּלוֹמַר: כְּשֶׁחָל רֹאשׁ חֹדֶשׁ בְּשַׁבָּת מַפְסִיקִין בַּחֲמִשָּׁה עָשָׂר בּוֹ, וְסִימָן זט\"ו; וּכְשֶׁחָל בְּיוֹם ב' מַפְסִיקִין בְּו' בּוֹ, וְסִימָן ב\"ו; וּכְשֶׁחָל בְּיוֹם ד' מַפְסִיקִין בְּד' בּוֹ, וְסִימָן ד\"ד; וּכְשֶׁחָל בְּיוֹם ו' מַפְסִיקִין בִּשְׁתֵּי שַׁבָּתוֹת ב' בּוֹ וְי\"ו בּוֹ, וְסִימָן ובי\"ו.\nיֵשׁ אוֹמְרִים \u0010y13\u0011 שֶׁפָּרָשַׁת זָכוֹר \u0010y14\u0011 וּפָרָשַׁת פָּרָה אֲדֻמָּה חַיָּבִים לְקָרְאָם מִדְּאוֹרַיְתָא, לְפִיכָךְ בְּנֵי הַיִּשּׁוּבִים שֶׁאֵין לָהֶם מִנְיָן צְרִיכִים לָבֹא \u0010y15\u0011 לְמָקוֹם שֶׁיֵּשׁ מִנְיָן בַּשַּׁבָּתוֹת הַלָּלוּ כְּדֵי לִשְׁמֹעַ פָּרָשִׁיּוֹת אֵלּוּ שֶׁהֵם מִדְּאוֹרַיְתָא. \u0005 הַגָּה: וְאִם אִי אֶפְשָׁר לָהֶם לָבֹא, \u0010y16\u0011 מִכָּל מָקוֹם יִזָּהֲרוּ לִקְרוֹתָם \u0010y17\u0011 בִּנְגִינָתָם וּבְטַעֲמָם \u0006 \u0005(מָצָא כָּתוּב)\u0006.",["\u0003ר\"ח אדר וכו'\u0004 אבאר בקיצור ענין ד' פרשיות. והוא. חז\"ל תקנו לקרות ד' פרשיות בשנה מר\"ח אדר עד ר\"ח ניסן לזכרון ד' דברים והם אלו. הראשונה היא פרשת שקלים לזכרון מצות מחצית השקל שיתבאר בסמוך שהיו מחוייבים ליתן ללשכה לקרבן התמיד בכל שנה. השניה היא פרשת זכור לזכור מעשה עמלק וקורין אותה בשבת שלפני פורים לסמכה למעשה שהיה מזרע עמלק וכדי להקדים זכירת מחיית עמלק לעשייתה וכדכתיב והימים האלה נזכרים ונעשים. השלישית היא פרשת פרה אדומה והיא בשבת שקודם פרשת החודש שכן היה שריפתה במדבר סמוך לניסן כדי להזות בה את ישראל באפר החטאת מיד אחר הקמת המשכן כדי שיהיו טהורים ויוכלו לעשות הפסח בזמנו לכך קורין פרשה זו להתפלל לפניו ית' שגם עלינו יזרוק מים טהורים במהרה. הרביעית פרשת החודש בשבת הסמוך לר\"ח ניסן כדי לקדש חודש ניסן דכתיב בתורה החודש הזה לכם ראש חדשים אבל אין זה עיקר הקידוש כי עיקר הקידוש הוא בעת ראית הלבנה שמקדשין אותו הב\"ד ואין הקריאה הזאת אלא מדרבנן:","\u0003קורין פרשת שקלים\u0004 דאמר קרא זאת עולת חודש בחדשו לחדשי השנה והאי לחדשי יתירא הוא אלא אמרה תורה יש לך חודש שאתה צריך לחדשו בהבאת עולות תמידין ומוספין מתרומה חדשה וזהו ניסן דגמרינן בגמרא בג\"ש שחודש זה הוא חודש ניסן וכיון דבניסן בעי לאקרובי מתרומה חדשה לכך מקדמינן ומשמיעין על השקלים באדר הסמוך לו שיביאו שקליהם בר\"ח ניסן ואנו משלמין פרים שפתינו בקריאת הפרשה של כי תשא דכתיב בה ענין השקלים. יוצר יש לשחרית וגם למוסף בפרשת שקלים ובפרשת החודש אבל בזכור ופרה לא תקנו במוסף [פמ\"ג] אם אירע שלא קראו הפרשה מענינו של יום אין לה תשלומין לשבת הבאה [שערי אפרים]. אם שכחו הצבור לקרות פרשת שקלים וה\"ה בשארי השלשה פרשיות אם כבר אמר הפטרה של סדר השבוע בברכותיה ונזכרו צריכים לחזור ולהוציא ס\"ת ולקרות הפרשה בברכה לפניה ולאחריה ויאמר אח\"כ קדיש ויפטיר בלא ברכה לפניה ולאחריה. ואם נזכרו אחר שהתחיל לברך על הפטרה ואמר השם יגמור הברכה ויאמר קצת פסוקים מהפטרת השבוע [כדי שתהיה לברכה מקום לחול] ובלא ברכה אחריה ויוציאו ס\"ת ויקרא עולה אחד מענינו של יום ואחר ברכה אחרונה יאמר קדיש ויקרא הפטרה בלא ברכה לפניה והברכות שלאחריה יברך. ואם נזכרו מיד אחר שבירך ברכה אחרונה על התורה יוציאו ס\"ת אחרת ויניח אצל הראשונה ויאמר קדיש ואח\"כ יקרא אחר שיפטיר מענינו של יום בברכותיה [שם] אם טעו וקראו הפרשיות והמגילה באדר ראשון צריך לחזור ולקרות המגילה בשני ולענין הפרשיות בב\"י משמע דא\"צ לחזור אבל בד\"מ ובא\"ר כתבו דצריך לחזור:","\u0003ומפטיר ויכרות יהוידע\u0004 כי שם נזכר נדבות לבדק הבית. ואין מפטירין בשל ר\"ח אף שהיא תדירה משום דמשקלים סליקו בתורה ומפטירין בה:","\u0003השבוע\u0004 ששה אנשים ובמקום שנהגו להוסיף מוסיפין [ש\"א]:","\u0003ובשני של ר\"ח\u0004 ומתחילין וביום השבת [לבוש] ומניחין ס\"ת השלישית אצלה ואומרים ח\"ק. ואם אחר שגמר פרשת השבת טעה ולקח הס\"ת שהיתה מגוללת על פרשת שקלים ובירך לפניה והתחיל לקרות יסיים בפרשת שקלים ואח\"כ להעולה בס\"ת השלישית למפטיר יקרא עמו בפרשת ר\"ח וההפטרה יאמר השמים כסאי מאחר שבקריאת התורה נסתיים מענין של שבת ור\"ח. וכן ה\"ה בשבת פרשת החודש כשחל ר\"ח ניסן בשבת והקדים לקרות בפרשת החודש [ש\"א]:","\u0003השבוע\u0004 ומניחין ס\"ת השניה אצלה ואומר ח\"ק:","\u0003עמלק\u0004 עד לא תשכח:","\u0003פקדתי\u0004 כן הוא ברמב\"ם ובלבוש איתא ויאמר שמואל כה אמר ד' פקדתי את אשר עשה וגו':","\u0003השבוע\u0004 ומניחין ס\"ת השניה אצלה ואומרים ח\"ק:","\u0003פרה\u0004 בפרשת חוקת מתחלת הסדר עד תטמא עד הערב:","\u0003וע\"ל בסימן קל\"ז ס\"ה\u0004 שם מבואר אם טעה ולא גמר כל הפרשה:","\u0003השבוע\u0004 ומניחין ס\"ת השניה אצלה ואומרים ח\"ק:","\u0003לכם\u0004 עד תאכלו מצות כשחל ר\"ח ניסן בשבת שאז הוא פרשת החודש מפטירין פ' החודש ולא השמים כסאי [עט\"ז בשם לבוש] ומוציאין ג' ספרים באחד קורין פרשת השבוע ומניחין השניה ואין אומרין קדיש ומגביהין הראשונה וגוללין ופותחין השניה וקורין בפרשת ר\"ח מן וביום השבת עד ונסכו ומניחין השלישית ואומרין קדיש ומגביהין השניה וגוללין ופותחין השלישית וקוראין למפטיר בפ' החודש [ש\"א]:","\u0003שפרשת זכור\u0004 דכתיב זכור את אשר עשה וכו' וגמרינן בגמרא דהאי זכור היינו באמירה מתוך הספר דוקא [ולא די במה שיקבע זה בלבו] וע\"כ צריך הקורא לכוין להוציא כל השומעים וגם השומעים צריכין לכוין לצאת:","\u0003ופ' פרה אדומה\u0004 והרבה אחרונים כתבו שפרשה זו אינה מדאורייתא ועיין לעיל בסימן ס' סק\"י במ\"ב דאפילו במצוה דרבנן ג\"כ צריך לכוין לצאת ידי המצוה:","\u0003למקום שיש מנין וכו'\u0004 היינו אפילו יש לו ס\"ת בביתו אלא שאין לו מנין בביתו ואפילו אם נאמר דמנין לפרשה זכור הוא מדרבנן בעלמא עכ\"פ עיקר קריאת זכור הוא דאורייתא והנה בתרומת הדשן כתב דשמיעת קריאת פ' זכור בעשרה עדיף יותר ממקרא מגילה בצבור שמקרא מגילה לדעת רוב הפוסקים סגי בזמנו ביחיד וע\"כ אם א\"א לו לקיים שניהם יראה לקיים קריאת פ' זכור בצבור אבל המ\"א מצדד דטוב יותר שיבוא למקום שקורין המגילה בצבור ופרשת זכור יוצא ע\"פ הדחק במה שישמע הקריאה בפורים פרשת ויבוא עמלק דבזה נמי זוכר מעשה עמלק ויוצא י\"ח ור\"ל דיוצא מדאורייתא והנה למאי דקי\"ל לעיל בסימן ס' דמצות צריכות כונה יהיה צריך בעת שמיעת פרשה זו לכוין לצאת בזה מ\"ע של זכור אבל לענ\"ד עיקר דינו של המ\"א צ\"ע דהא כתיב בתורה זכור את אשר עשה וגו' אשר קרך בדרך ויזנב בך וגו' תמחה וגו' והכונה שלא לשכוח מה שעשה לנו עמלק ונספר זה לבנינו ולדורותינו לומר להם כך עשה לנו הרשע ולכך נצטוינו למחות את שמו כמו שכתב הרמב\"ן בביאורו וזה לא נזכר בפרשת ויבא עמלק:","\u0003מ\"מ יזהרו לקרותם וכו'\u0004 ויהדר לקרות זה מתוך הספר וכנ\"ל בסקי\"ד:","\u0003בנגינתם ובטעמם\u0004 דע דיש אומרים שצריך לקרות זכר עמלק בציר\"י ויש אומרים שצריך לקרות זכר עמלק בסגו\"ל וע\"כ מהנכון שהקורא יקרא שניהם לצאת י\"ש. כתב מהרי\"ל בכל ד' פרשיות אין מזכירין נשמות ואומרים צו\"ץ [ד\"מ] ולענין אב הרחמים בא\"ר בשם הגמ\"נ די\"ל בהם אב הרחמים ובד\"מ בשם מהרי\"ל משמע דאין אומרים בהם אה\"ר וכן העתיק בדה\"ח ולענין תענית של שובבי\"ם ת\"ת עיין בבה\"ט ושע\"ת:"],[],"\u0010y0\u0011 \u0010g0\u0011 \u0010s0\u0011 \u0010m0\u0011 רֹאשׁ חֹדֶשׁ אֲדָר הַסָמוּךְ לְנִיסָן שֶׁחָל לִהְיוֹת בְּשַׁבָּת, \u0010y1\u0011 קוֹרִין פָּרָשַׁת \u0010t0\u0011 שְׁקָלִים \u0010g1\u0011 שֶׁהִיא כִּי תִשָּׂא, עַד וִעָשִׂיתָ כִּיּוֹר \u0010y2\u0011 \u0010g2\u0011 נְחֹשֶׁת, וּמַפְטִיר: וַיִּכְרֹת יְהוֹיָדָע; וּמוֹצִיאִין שְׁלֹשָׁה סְפָרִים: בְּאַחַת קוֹרֵא פָּרָשַׁת \u0010y3\u0011 הַשָּׁבוּעַ, \u0010y4\u0011 וּבַשֵּׁנִי שֶׁל רֹאשׁ חֹדֶשׁ, וּבַשְּׁלִישִׁי קוֹרֵא מַפְטִיר בְּפָרָשַׁת שְׁקָלִים. \u0010g3\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011\nבְּשַׁבָּת שְׁנִיָּה מוֹצִיאִין שְׁנֵי סְפָרִים; בְּאֶחָד קוֹרֵא פָּרָשַׁת \u0010y5\u0011 הַשָּׁבוּעַ, וּבַשֵּׁנִי קוֹרֵא: זָכוֹר אֶת אֲשֶׁר עָשָׂה לְךָ \u0010y6\u0011 עֲמָלֵק, וּמַפְטִיר: \u0010y7\u0011 פָּקַדְתִּי אֶת אֲשֶׁר עָשָׂה עֲמָלֵק. \u0010g4\u0011 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011\nבְּשַׁבָּת שְׁלִישִׁית, שֶׁהוּא ט\"ו בְּאֲדָר, מַפְסִיקִין; וּבְשַׁבָּת ד' שֶׁהִיא כ\"ב לְאֲדָר מוֹצִיאִין שְׁנֵי סְפָרִים; בְּאֶחָד קוֹרֵא \u0010y8\u0011 בְּפָרָשַׁת הַשָּׁבוּעַ, וּבַשֵּׁנִי קוֹרֵא פָּרָשַׁת \u0010y9\u0011 פָּרָה, וּמַפְטִיר: וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים \u0010y10\u0011 \u0005 וְעַיֵּן לְעֵיל סי' קל\"ז סָעִיף \u0010g5\u0011 ה'. \u0006 \u0010r7\u0011 \u0010r8\u0011 \u0010r9\u0011 \u0010r10\u0011\nבְּשַׁבָּת חֲמִישִׁי, שֶׁהוּא כ\"ט בַּאֲדָר, מוֹצִיאִין ב' סְפָרִים: בְּאֶחָד קוֹרֵא פָּרָשַׁת \u0010y11\u0011 הַשָּׁבוּעַ, וּבַשֵּׁנִי: הַחֹדֶשׁ הַזֶּה \u0010y12\u0011 לָכֶם, וּמַפְטִיר: בָּרִאשׁוֹן בְּאֶחָד לַחֹדֶשׁ. \u0010r11\u0011 \u0010r12\u0011\nחָל רֹאשׁ חֹדֶשׁ אֲדָר הַסָמוּךְ לְנִיסָן בְּתּוֹךְ יְמֵי הַשָּׁבוּעַ, \u0010g6\u0011 וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת, מַקְדִּימִין לִקְרוֹת פָּרָשַׁת שְׁקָלִים בְּשַׁבָּת שֶׁלְּפָנָיו, וּמַפְסִיקִין בַּשְּׁנִיָּה כְּדֵי שֶׁתְּהֵא פָּרָשַׁת זָכוֹר בַּשַּׁבָּת הַסְמוּכָה לְפוּרִים מִלְּפָנֶיהָ; \u0010g7\u0011 וְאִם חָל פּוּרִים בְּעֶרֶב שַׁבָּת, מַקְדִּימִים לִקְרוֹת פָּרָשַׁת זָכוֹר בְּשַׁבָּת שֶׁלְּפָנָיו. \u0010g8\u0011 \u0010r13\u0011 \u0010r14\u0011 \u0010r15\u0011\nהַיָּמִים שֶׁרָאוּי לִקְבֹּעַ בָּהֶם רֹאשׁ חֹדֶשׁ אֲדָר, זבד\"ו; וְסִימָן לְשַׁבְּתוֹת הַהַפְסָקָה, זט\"ו ב\"ו ד\"ד ובי\"ו, כְּלוֹמַר: כְּשֶׁחָל רֹאשׁ חֹדֶשׁ בְּשַׁבָּת מַפְסִיקִין בַּחֲמִשָּׁה עָשָׂר בּוֹ, וְסִימָן זט\"ו; וּכְשֶׁחָל בְּיוֹם ב' מַפְסִיקִין בְּו' בּוֹ, וְסִימָן ב\"ו; וּכְשֶׁחָל בְּיוֹם ד' מַפְסִיקִין בְּד' בּוֹ, וְסִימָן ד\"ד; וּכְשֶׁחָל בְּיוֹם ו' מַפְסִיקִין בִּשְׁתֵּי שַׁבָּתוֹת ב' בּוֹ וְי\"ו בּוֹ, וְסִימָן ובי\"ו. \u0010g9\u0011 \u0010r16\u0011 \u0010r17\u0011 \u0010r18\u0011 \u0010r19\u0011\nיֵשׁ אוֹמְרִים \u0010y13\u0011 שֶׁפָּרָשַׁת זָכוֹר \u0010y14\u0011 וּפָרָשַׁת פָּרָה \u0010t1\u0011 \u0010s1\u0011 אֲדֻמָּה חַיָּבִים לְקָרְאָם מִדְּאוֹרַיְתָא, לְפִיכָךְ בְּנֵי הַיִּשּׁוּבִים שֶׁאֵין לָהֶם מִנְיָן צְרִיכִים לָבֹא \u0010y15\u0011 לְמָקוֹם שֶׁיֵּשׁ מִנְיָן בַּשַּׁבָּתוֹת הַלָּלוּ כְּדֵי לִשְׁמֹעַ פָּרָשִׁיּוֹת אֵלּוּ שֶׁהֵם מִדְּאוֹרַיְתָא. \u0005 הַגָּה: וְאִם אִי אֶפְשָׁר לָהֶם לָבֹא, \u0010y16\u0011 מִכָּל מָקוֹם יִזָּהֲרוּ לִקְרוֹתָם \u0010y17\u0011 בִּנְגִינָתָם וּבְטַעֲמָם \u0006 \u0005(מָצָא כָּתוּב)\u0006. \u0010r20\u0011 \u0010r21\u0011 \u0010r22\u0011",{"g":["\u0003משנה וברייתא מגילה כט.\u0004 ","כשמואל ותניא כוותיה","שם בבריי'","שם במשנה וברייתא ל'","שם","שם","כרב שם","שם כרב להקדים זכירה לעשייה","הרי\"ף והרא\"ש שם","תוס' ברכות י\"ג"],"t":["\u0003שקלים. \u0004 ואם שכחו הצבור בראש חדש אדר לקרות פרשת שקלים צריכים לחזור ולהוציא ס\"ת ולקרות הפרשה גינת ורדים חא\"ח כלל א' סי' ל\"ו ע\"ש. אם טעו וקראו הפרשיות והמגילה בראשון צריך לחזור לקרותן בשני עיין ב\"ח:","\u0003מדאורייתא. \u0004 בשל\"ה האריך לצדד שפרשת פרה אינה דאורייתא וכ\"כ הב\"ח וכ\"כ בתשובת מהרי\"ל סימן קפ\"ב שלא הזכיר אלא פרשת זכור. ובת\"ה סי' ק\"ח כתב וז\"ל באשר\"י פרק ז' דברכות כתב דעשה דאורייתא לקרות פרשת זכור בעשרה. ובתוס' שאנ\"ץ כתבו דאין שום קריאה דאורייתא רק פרשת זכור. ובתוס' הקצרות בברכות פרק ב' פירשו דפרשת זכור ופרשת פרה חייבים לקרות' מן התורה וכו'. ואם כן צריך לזהר יותר שישמעו קריאת פ' זכור בי\"ד ממקר' מגילה בזמנה אלא שהעולם לא זהירי בהכי עכ\"ל. וכתב המ\"א ונ\"ל ליישב מנהג העולם דאטו מי כתיב בתורה שיקראו דוק' בשבת זו אלא שחכמים תקנו בשבת זו הואיל ושכיחי רבים בבה\"כ וסמוך לפורים כדי לסמוך מעשה עמלק למעשה המן וע\"כ כששומע בפורים פרשת ויבא עמלק נמי זוכר מעשה עמלק ויוצא י\"ח וכ\"ה ברא\"ם סי' ב'. אבל פ' פרה לא מצינו שהוא מדאורייתא עכ\"ל ע\"ש. וכתב רש\"ל שאין הקטן עולה למפטיר בפ' זכור ובפ' פרה ע\"ש. והב\"ח כ' דבין קטן שיודע למי מברכין ובין שאינו יודע למי מברכין עולה ע\"ש: והט\"ז כ' דוקא קטן היודע למי מברכין עולה. ובסימן רפ\"ב פסק רמ\"א דקטן יכול לקרות בפ' המוספין או בארבע פרשיות שמוסיפין באדר ונראה דביודע למי מברכין קאמר עכ\"ל ע\"ש: ועיין בגינת ורדים חא\"ח כלל א' סי' ל\"ז. כתב מהרי\"ל בכל ארבע פרשיות אין מזכירין נשמות ואומרים צו\"ץ ד\"מ. יש נוהגין בשנה מעוברת לקבוע תענית בכל יום ה' מפרשת שובבי\"ם ת\"ת וי\"א גם פ' ויקהל ופקודי ואומרים שומר ישראל וכו'. ופשוט דהש\"ץ אומר ענינו בשחרית ומנחה. וכתב האר\"י ז\"ל בפי' התורה שימים אלו מסוגלים לתקן עון קרי יותר מכל השנה להמתענים בהן לכן מתחיל מפ' שמות שאז התחיל השעבוד שנתקן הקרי דאדה\"ר ונגמר בפ' כי תקנה עבד עברי ע\"ש:"],"s":["\u0003בש\"ע ר\"ח אדר הסמוך כו' \u0004 וע' כל דיני סדר קריאת ארבע פרשיות וטעות הקריאה בספרי שער אפרים שער ח' שביארתי הדברים על בוריין בעזהש\"י:","\u0003מדאורייתא. \u0004 עבה\"ט ועיין בשערי אפרים שער ח' ומ\"ש בה\"ט בענין תענית שובבים כו' מנהג המתענים במדינות אלו בשנה פשוטה שובבים לבד ובשנה מעוברת מוסיפים ת\"ת ועיין בא\"ר בשם מלבושי יו\"ט שאם אירע שר\"ח או ט\"ו שבט או פורים קטן חל ביום ה' אם ללותו ולפורעו (עיין שם בא\"ר שמסתפק בכוונתו אם ר\"ל שמחוייב להתענות בו ביום או שמא ר\"ל שידחה לגמרי עיין שם שאף שלשונו נוטה לומר שיתענה אין נלע\"ד דהא מעיקרא לא קבלוהו אדעתא דהכי וכן נוהגים שאין מתענים בהם וכמדומה שנוהגים להקל אף אם אירע לו סעודת מצוה שהוא שייך בה או שהוא סנדק מקילין בו ומכל מקום נראה שיש להתענות בפרשה שאחריה לתשלומין כיון שהוא תענית של תשובה וכמו בצום תענית אסתר וצ\"ע) ובא\"ר כת' שנ\"ל דאם חל ר\"ח וט\"ו בשבט ביום ה' יתענו במקומם ויקהל פקודי ועיין בפ\"מ שמסתפק למנהגינו בשנה פשוטה שאירע כן אם יתענה ת\"ת במקומם או יש לומר הואיל ונדחה ידחה עיין שם. ונראה דהנוהג כא\"ר בשנה מעוברת ויקהל פקודי כמנהג היש מקומות שהביא המג\"א מכ\"ש דבשנה פשוטה יתענה ת\"ת שנוהגין בו בשנה מעוברת: \u0003ואפשר \u0004 שטעמו כיון שיש נוהגין שלא להתענות בפשוטה כלל לכן יש להקל בו כשנדחה ומכל מקום נ\"ל עיקר כמ\"ש בזה:"],"m":["בשל\"ה האריך לצדד שפרש' פרה אינה דאורייתא וכ\"כ הב\"ח וכ\"מ בתשובת מהרי\"ל סי' קפ\"ב וקס\"ז שלא הזכיר אלא פרשת זכור ובת\"ה סי' ק\"ח כתב וז\"ל באשר\"י פ\"ו דברכות כתב דעשה דאורייתא לקרות פרש' זכור בעשרה, ובתוספות שנ\"ץ כתבו דאין שום קריאה דאורייתא רק פ' זכור, ובתו' הקצרות בברכות פ\"ב פי' דפ' זכור ופ' פרה חייבים לקרותן מן התורה וכו' וכן בסמ\"ק כתב מ\"ע זכור את אשר עשה ואם כן צריך ליזהר יותר שישמעו קריאת פרשת זכור בי' ממקרא מגילה בזמנה אלא שהעולם לא זהירי בהכי עכ\"ל ול\"נ ליישב מנהג העולם דאטו מי כתיב בתורה שיקראו דוקא בשבת זה אלא שחכמים תקנו בשבת זו הואיל ושכיחי רבים בבה\"כ וסמוך לפורים כדי לסמוך מעשה עמלק למעשה המן כמ\"ש הלבוש וא\"כ כששומע בפורים פרשת ויבא עמלק נמי זוכר מעשה עמלק ויוצא י\"ח וכ\"ה ברא\"ם סי' ב' ומשום פ' פרה ס\"ל דלא הוי מדאורייתא דבאמת אין טעם בקריאת' מדאורייתא וגם לא ידענא היכא רמיזא, ול\"נ שהגירס' הנכונ' כמ\"ש בחי' הרשב\"א וז\"ל והקשו שלא מצינו קריאת ס\"ת מן התורה אא\"כ יאמר רש\"י שתהא קריאת הפרשיות כגון פרשת פרה ופרשת זכור וכיוצא בהן מן התורה ע\"כ מ\"מ כל אדם יהא זהיר וזריז במצו' לבוא למנין, ובמגלה דף י\"ח משמע פשטא דתלמודא דפרשת זכור דאורייתא, ומשמע שם דה\"ה בפ' ויבא עמלק יצא: כתב מהרי\"ל בכל ד' פרשיות אין מזכירין נשמות ואומרים צו\"ץ (ד\"מ): יש נוהגין בשנה מעוברת לקבוע תענית בכל יום ה' מפרשת שובבי\"ם ת\"ת וי\"א גם פרשת ויקהל ופקודי ואומרים שומר ישראל וכו':"],"r":["\u0003ס\"א הסמוך כו'. \u0004ו' ב' ורשב\"ג סבר כו':","\u0003עד. \u0004כ\"ט ל':","\u0003ומוציאין. \u0004שם:","\u0003ובשלישי. \u0004כר' ירמיה ל' ב'. רי\"ף. דהלכה כר' ירמיה דבסדר הפטרות כו' וכי שם שיתא מכי תשא כו' וכן כל הסוגיא כולה שם כוותיה ועמ\"ש ס\"ב:","\u0003ס\"ב בשבת שניה. \u0004מתני' וגמ' שם תנן בשניה כו' וקי\"ל כרב:","\u0003מוציאין כו' באחר. \u0004כר' ירמיה דר' יצחק ואביי ס\"ל כוותיה ותניא כוותיה דאר\"י ר\"ח טבת ואדר שחל כו' חל להיות באותה כו' חל להיות כו' ת\"כ דאביי כו'. ואף ע\"ג דאביי קאמר כוותיה דר\"א הרי הדר ביה כאן:","\u0003ומפטיר. \u0004ברייתא שם:","\u0003ס\"ג בשבת שלישית. ירושלמי שם אין מפסיקין בין פרה להחודש וסימנך בין הכוסות כו':\n\u0004","\u0003ובשבת ד'. \u0004כמ\"ש כל שסמוכה לפורים והיינו למוקפין. ע' רש\"י:","\u0003באחד. \u0004כנ\"ל:","\u0003ומפטיר. \u0004שם:","\u0003ס\"ד בשבת חמישי. \u0004שם כל שסמוכה כו':","\u0003ומפטיר. \u0004שם:","\u0003ס\"ה חל. \u0004מתניתין:","\u0003ומפסיקין. \u0004מתניתין:","\u0003שתהא. \u0004ברייתא:","\u0003ס\"ו הימים. \u0004ר\"ה כ' א' סוכה מ\"ג ב'. וירושלמי ר' סימון כו' דלא אתא ערבתא בשבתא כו' הביאו תוס' שם ד\"ה לא ירושלמי פ\"א דמגילה סוף הלכה ב' א\"ר יוסא לית כאן חל להיות בשני ולית כאן חל להיות בשבת חל להיות בשני צומא רבא בחד בשובא חל להיות בשבת צומא רבא בערובתא:","\u0003כשחל ר\"ח. \u0004כנ\"ל:","\u0003וכשחל כו'. \u0004מתני' חל להיות בתוך כו':","\u0003וי\"ו בו. \u0004גמרא שם ולא פליגי הא כו':","\u0003ס\"ז י\"א שפרשת זכור. \u0004שם י\"ח אתיא זכירה כו' וממאי כו':","\u0003ופרשת פרה. \u0004בתוספות שלפנינו ליתא לא בברכות ולא במגילה י\"ז ב' וכן באשרי פ\"ו דברכות ליתא אלא זכור ונסחא משובשת נזדמנה לו:","\u0003לפיכך כו' למקום. \u0004שם כ\"ג ב' מתני' אין קורין בתורה ואין כו':"]}],["\u0003הלכות מגילה\u0004\nבַּחֲנֻכָּה וּפוּרִים \u0010y0\u0011 מֻתָּר לְהִתְעַנּוֹת לִפְנֵיהֶם וּלְאַחֲרֵיהֶם. \u0010y1\u0011\nמִתְעַנִּים בְּי\"ג בַּאֲדָר; וְאִם חָל פּוּרִים בְּאֶחָד בְּשַׁבָּת, מַקְדִּימִין \u0010y2\u0011 לְהִתְעַנּוֹת בְּיוֹם חֲמִישִׁי. \u0005 הַגָּה: וְתַעֲנִית זֶה אֵינוֹ חוֹבָה, לָכֵן יֵשׁ לְהָקֵל בּוֹ לְעֵת הַצֹּרֶךְ, כְּגוֹן: מְעֻבָּרוֹת אוֹ מֵינִיקוֹת אוֹ לְחוֹלֶה שֶׁאֵין בּוֹ סַכָּנָה, וַאֲפִלּוּ כּוֹאֲבֵי עֵינַיִם, שֶׁאִם \u0010y3\u0011 \u0006 \u0005 מִצְטַעֲרִים הַרְבֵּה לֹא יִתְעַנּוּ \u0010y4\u0011 וְיִפְרְעוּ אַחַר כָּךְ, אֲבָל שְׁאָר בְּרִיאִים \u0010y5\u0011 \u0006 \u0005 לֹא יִפְרְשׁוּ מִן הַצִּבּוּר \u0006 \u0005(חִדּוּשֵׁי אֲגֻדָּה בְּשֵׁם מַחֲזוֹר וִיטְרִי)\u0006. \u0005 וְאִם חָל פּוּרִים בְּיוֹם א', שֶׁמִּתְעַנִּין בְּיוֹם ה' שֶׁלְּפָנָיו, וְחָל בּוֹ בְּרִית מִילָה, \u0010y6\u0011 מֻתָּר \u0006 \u0005 לֶאֱכֹל עַל הַמִּילָה, וּלְמָחָר בְּיוֹם ו' יִתְעַנּוּ הָאוֹכְלִים \u0006 \u0005(הַגָּהוֹת מִנְהָגִים)\u0006.\nיֵשׁ מִתְעַנִּים \u0010y7\u0011 ג' יָמִים, זֵכֶר לְתַעֲנִית אֶסְתֵּר.",["\u0003מותר להתענות לפניהם ולאחריהם\u0004 וכן בהספד שרי וב\"ח כתב דבחנוכה אסור להתענות לפניו וכן הוא ג\"כ דעת הפר\"ח. והנה יש נוהגים להתענות לפני חנוכה תמורת ער\"ח ואין לשנות מנהגם אבל לכתחלה לא ינהוג כן ועכ\"פ אסור לגזור בו תענית צבור וכן יום ראשון דאחר חנוכה אף דיחיד מותר להתענות בו תענית צבור אסור לגזור בו:","\u0003מתענין בי\"ג באדר\u0004 כי בימי מרדכי ואסתר נקהלו ביום י\"ג באדר להלחם ולעמוד על נפשם והיו צריכין לבקש רחמים ותחנונים שיעזרם ד' להנקם מאויביהם ומצינו כשהיו ביום מלחמה שהיו מתענין שכן אמרו רז\"ל שמרע\"ה ביום שנלחם עם עמלק היה מתענה וא\"כ בודאי גם בימי מרדכי היו מתענים באותו יום ולכן נהגו כל ישראל להתענות בי\"ג באדר ונקרא תענית אסתר כדי לזכור שהש\"י רואה ושומע כל איש בעת צרתו כאשר יתענה וישוב אל ד' בכל לבבו כמו שעשה בימים ההם:","\u0003להתענות ביום ה'\u0004 אבל בע\"ש אין קובעין תענית בתחלה מפני כבוד השבת לפי שרגילין בתענית לומר סליחות ותחנונים ובע\"ש לא יתכן לעשות כן לפי שלא יוכלו לטרוח לכבוד השבת ומי שהיה בדרך ושכח שמתענים ביום ה' ואכל ובלילה בא לביתו ושמע שהעולם התענו היום יתענה למחר בע\"ש. מהרי\"ל לא היה מגיד ההלכה בתענית אסתר מפני שטרודים לקנות צרכי פורים אם לא כשחל פורים ביום א' וכתב בא\"ר ונ\"ל דכל זה מיירי לילך לישיבה אבל ללימוד הקבוע בביה\"מ אינו בכלל זה דאין בזה כ\"כ בטול צרכי סעודה. וא\"א צדקתך באותה שבת שחל פורים למחר כמו שא\"א תחנונים בערב פורים בחול כך א\"א צידוק הדין בשבת שהוא ערב פורים:","\u0003מצטערים\u0004 זה קאי על כואבי עינים אבל מעוברת אף שאינה מצטערת אינה מתענה כ\"כ הישועות יעקב ובא\"ר מחמיר בזה אך ביולדת כל ל' גם הוא מיקל:","\u0003ויפרעו אח\"כ\u0004 להישועות יעקב הנ\"ל מסתברא דלא קאי ד\"ז רק על כואבי עינים שבעצם יש עליו חיוב שלא לפרוש מן הצבור ורק עכשיו משום דכאיב ליה עיניו ולהכי לבתר שיסולק כאבו יפרע התענית משא\"כ מעוברת ומניקה דפטורות בעצם אפילו אינן מצטערות אכן מדברי הב\"ח לכאורה לא משמע כן:","\u0003לא יפרשו\u0004 אפילו ההולך בדרך וקשה עליו התענית:","\u0003מותר לאכול על המילה\u0004 היינו כל האנשים הקרואים להסעודה ואפילו יותר מעשרה ואפילו בשחרית מותרים לאכול אכן כולם צריכין להתענות למחר וכדלקמיה. ועיין בט\"ז וא\"ר שחולקים על הג\"ה זו ודעתם דקביעותא דתעניתא הוא דוקא ליום ה' וע\"כ אסורין כולם לאכול ביום ה' ויעשו הסעודה בלילה אכן הבעלי ברית בעצמן מותרין לאכול ביום ה' אחר מילה וא\"צ להתענות למחר וכנ\"ל בסימן תקנ\"ט ס\"ט לענין ט\"ב ועיין בפמ\"ג שכתב דהמיקל לנהוג כדעת הרמ\"א לא הפסיד וכן במו\"ק ובשבות יעקב הסכימו לדעת השו\"ע:","\u0003ג' ימים\u0004 פי' בה\"ב אחר פורים. משנכנס אדר מרבין בשמחה ומי שיש לו דין עם עכו\"ם ישפוט באדר [גמרא] יכולים בני עיר לתקן בהסכמה ובחרם עליהם ועל הבאים אחריהם לעשות פורים ביום שנעשה בו נס ומי שנעשה לו נס באדר ונדר לעשות פורים כשיבוא שנת העיבור צריך לעשות הפורים באדר שני אם לא שנעשה לו הנס בשנת העיבור באדר ראשון:"],[],"\u0003הלכות מגילה\u0004\n\u0010g0\u0011 \u0010m0\u0011 בַּחֲנֻכָּה וּפוּרִים \u0010y0\u0011 \u0010t0\u0011 מֻתָּר לְהִתְעַנּוֹת לִפְנֵיהֶם וּלְאַחֲרֵיהֶם. \u0010y1\u0011 \u0010g1\u0011 \u0010t1\u0011 \u0010m1\u0011 \u0010r0\u0011\nמִתְעַנִּים בְּי\"ג בַּאֲדָר; וְאִם חָל פּוּרִים בְּאֶחָד בְּשַׁבָּת, מַקְדִּימִין \u0010y2\u0011 \u0010m2\u0011 לְהִתְעַנּוֹת בְּיוֹם חֲמִישִׁי. \u0005 הַגָּה: וְתַעֲנִית זֶה אֵינוֹ חוֹבָה, לָכֵן יֵשׁ לְהָקֵל בּוֹ לְעֵת הַצֹּרֶךְ, כְּגוֹן: מְעֻבָּרוֹת אוֹ מֵינִיקוֹת אוֹ לְחוֹלֶה שֶׁאֵין בּוֹ סַכָּנָה, וַאֲפִלּוּ כּוֹאֲבֵי עֵינַיִם, שֶׁאִם \u0010y3\u0011 \u0010t2\u0011 \u0006 \u0005 מִצְטַעֲרִים הַרְבֵּה לֹא יִתְעַנּוּ \u0010y4\u0011 וְיִפְרְעוּ אַחַר כָּךְ, אֲבָל שְׁאָר בְּרִיאִים \u0010y5\u0011 \u0010t3\u0011 \u0010m3\u0011 \u0006 \u0005 לֹא יִפְרְשׁוּ מִן הַצִּבּוּר \u0006 \u0005(חִדּוּשֵׁי אֲגֻדָּה בְּשֵׁם מַחֲזוֹר וִיטְרִי)\u0006. \u0005 וְאִם חָל פּוּרִים בְּיוֹם א', שֶׁמִּתְעַנִּין בְּיוֹם ה' שֶׁלְּפָנָיו, וְחָל בּוֹ בְּרִית מִילָה, \u0010y6\u0011 \u0010t4\u0011 \u0010s0\u0011 מֻתָּר \u0006 \u0005 לֶאֱכֹל עַל הַמִּילָה, וּלְמָחָר בְּיוֹם ו' יִתְעַנּוּ הָאוֹכְלִים \u0006 \u0005(הַגָּהוֹת מִנְהָגִים)\u0006. \u0010g2\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011 \u0010r7\u0011\nיֵשׁ מִתְעַנִּים \u0010y7\u0011 \u0010t5\u0011 \u0010m4\u0011 ג' יָמִים, זֵכֶר לְתַעֲנִית אֶסְתֵּר.",{"g":["תוס' תענית י\"ח וכן כ' הרא\"ש בפ' קמא דמגילה","הרא\"ש שם אהא דאיתא שם ב' י\"ג זמן קהלה לכל הוא","טור בשם מסכת סופרים ואע\"פ שאותן היו בניסן לא רצו להתענות בניסן לפי שנגאלו בו אבותינו והוקם המשכן"],"t":["\u0003מותר. \u0004 וב\"ח כתב דחנוכה אסור להתענות לפניו ועיין סי' תר\"ע ס\"ק ב' מש\"ש. וע' יד אהרן:","\u0003בי\"ג. \u0004 ויש מתענין לילה ויום. כנה\"ג. מהרי\"ל לא היה מגיד ההלכה בתענית אסתר מפני שטרודים לקנות צרכי פורים אם לא כשחל פורים ביום א' ובהגמ\"נ הוכיח מהגמרא שאפי' בפורים היו רגילים ללמוד לפני רבם:","\u0003מצטערים. \u0004 וכ\"ש יולדת כל שלשים יום:","\u0003לא יפרשו. \u0004 אפי' ההולך בדרך וקשה עליו התענית. ב\"י ש\"ל:","\u0003לאכול. \u0004 משמע אפי' יותר מיו\"ד. וט\"ז כתב דאין לסמוך על הג\"ה זו אלא יאכל סעודת המילה בלילה כמו בט\"ב ע\"ש. משנכנס אדר מרבין בשמחה. ומי שיש לו דין עם עכו\"ם ישפוט באדר. כתב ר\"מ אלשקאר סי' מ\"א דיכולין לתקן בני העיר בהסכמת וחרם עליהם ועל הבאים אחריהם לעשות פורים על שנעשה להם נס ואף שהולכים לעיר אחרת להשתקע חל עליהם ומי שנעשה לו נס באדר ונדר לעשות לו פורים י\"א לעשות בשנת עיבור באדר שני וי\"א לעשותו באדר ראשון אא\"כ נעשה הנס בשנת העיבור באדר שני הר\"ש הלוי סי' י\"ו ועיין מ\"ש סי' תקס\"ח סעיף ז' \u0005(ובמג\"א חולק עליו. ובספר אליה רבה דחה דבריו בסימן תרפ\"ה עיין שם)\u0006. כתב כנה\"ג מי שמתענה יום שנעשה לו נס ואירע בשבת יתענה בערב שבת:","\u0003ג' ימים. \u0004 פי' בה\"ב אחר פורים ב\"י סימן תכ\"ט ע\"ש:"],"s":["\u0003לאכול. \u0004 עבה\"ט ועיין בשבו\"י ח\"ג סימן נון שמסכים לדברי הש\"ע ולמד מדברי הש\"ע בהיה בא בדרך ושכח שמתענים ביום ה' ואכל ושתה ובלילה בא לביתו ושמע שהעולם התענו היום יתענו ביום מחר בע\"ש בכדי לקיים מצות הצומות וזעקתם הכתובים במגילה שהוא כד\"ת כמ\"ש ועיין במהר\"ש הלוי סימן ר\"א ואף להט\"ז י\"ל דמודה דהתם י\"ל שיעשה ב\"מ בלילה משא\"כ כאן שחלף היום ואין לו תקנה אחרת שפיר מתענה ביום ואו ע\"ש ועיין במו\"ק בשם אביו הגאון ח\"צ ז\"ל שיש נוהגין להתענות באדר שני לפי שגם פורים היה בזכות משה שחשב המן להיפך ומש\"ה ראוי שיהיה בחודש א' עם פורים וכן נראה מהמג\"א סימן תק\"פ אבל בשאילת יעב\"ץ ח\"א סי' קי\"ז דתליא בפלוגתא בסוטה והיכא דאיחזק למיעבד בראשון יעשו כן ועיין בסידור עמודי שמים שכת' ג\"כ כמ\"ש במו\"ק שהעיקר להתענות בשני וסיים ג\"כ ועיין בש\"י סימן קי\"ז כמו שסיים בה במו\"ק ועיין בבר\"י בשם ב\"ד שחתן בתוך ימי חופתו לא יתענה צום אסתר כו' ונראה דכ\"ש דזה עדיף מברית מילה וא\"צ תשלומין אחר כך אבל בד' צומות כתבו בשם הריטב\"א דמתענה כמש\"ל סי' תקמ\"ט:\nעיין שם בסליחות לתענית אסתר סדר להשתמש בשונים נראה ט\"ס וצ\"ל סרר להשתמש כו' בשני רישין גם מ\"ש שם עישת בשלו להשמיד כו' נדחקו לפרש ולפענ\"ד הוא ט\"ס וצ\"ל עישת כשלו ופירושו חשב במחשבתו כי עישת מלשון עשתונות וכסל נאמר על הכליות מקום המחשבה כדכתיב אם אמרתי לזהב כסלו וכן לשון הפייט אקשטה כסל וקרב וכן בדוכתי טובא:"],"m":["\u0003בחנוכה וכו'\u0004. וב\"ח כתב דבחנוכה אסור להתענות לפניו, ובאמת יש נוהגים להתענו' לפני חנוכה תמור' ערב ראש חדש ואין לשנות מנהג' אבל לכתחלה לא ינהוג כן על כל פנים אסור לגזור בו תענית צבור (ראב\"ח סימן ה') ואף ביום שלאחריו אסור (כ\"ה):","\u0003מתענין בי\"ג\u0004. ויש מתענין לילה ויום (כ\"ה):","\u0003להתענו' ביום ה'\u0004. אבל בערב שבת אין קובעין תענית בתחלה מפני כבוד השבת (מ\"מ ב\"ח הגמ\"נ) עמ\"ש סוף סי' רמ\"ט: מהרי\"ל לא הי' מגיד ההלכ' בתענית אסתר מפני שטרודים לקנות צרכי פורים אם לא כשחל פורים ביום א' ובהגמ\"נ הוכיח מהגמרא שאפי' בפורים היו רגילים ללמוד לפני רבם:","\u0003לא יפרשו\u0004. אפי' ההולך בדרך וקשה עליו התענית (ב\"י ש\"ל):","\u0003ג' ימים\u0004. פירוש בה\"ב אחר פורים (ב\"י סי' תכ\"ט ע\"ש), משנכנס אדר מרבין בשמחה ומי שיש לו דין עם עכו\"ם ישפוט באדר, יכולים בני עיר לתקן בהסכמ' ובחרם עליהם ועל הבאים אחריהם לעשות פורים ביום שנעשה בו נס (הר\"מ אלשקר מ\"ט) (ועיין בס' משא מלך ח\"ז סי' ט\"ו): ומי שנעש' לו נס באדר לעשו' פורים י\"א לעשות בשנ' עיבור באדר שני וי\"א לעשותו באדר ראשון אא\"כ נעשה הנס בשנת העיבור באדר שני (הר\"ש הלוי י\"ו) עמ\"ש סי' תקס\"ח ס\"ז ומ\"ש שם דמוכח דיש לעשות באדר שני:"],"r":["\u0003ס\"א בחנוכה ופורים כו'. \u0004ר\"ל ואע\"ג דאמרינן בפ\"ק דר\"ה י\"ט דחנוכה ופורים לא בטלה מגילת תענית ה\"מ להימים עצמן ולכן מתענין י\"ג באדר. עש\"ו. וא\"צ לזה דפורים דברי קבלה הוא ודברי כו' כמ\"ש שם י\"ט א' וז\"ש מגילה ה' לא נצרכה כו' ר\"ל דלענין הספד ותענית הם ימי פורים לכל ואף במלאכה הוי ס\"ד שהן לכל אבל משום שלפניהם ואחריהם לא ולכן נ\"ק משום לאחריהם ואף לפניהם אי איקלע מילתא ובטליה לניקנור כמ\"ש בתענית י\"ח א' וע' מרדכי בשם רשב\"ט שכ' דמדכללינהו בירושלמי שאמרו בכל מתענין חוץ משבת וי\"ט ור\"ח וחנוכה ופורים ש\"מ דכולם שוין וכ\"מ ברז\"ה ובר\"ן פ\"ב דתענית ואע\"ג דבירושלמי מ' דגם לפני פורים יש לאסור מפני יום שלפניהם הירושלמי פליג אגמרא וס\"ל דדברי קבלה אינן כד\"ת. ועיין תוס' שם י\"ח א' ד\"ה רב כו'. והרי\"ף חולק בספ\"א דמגילה ואוסר לפניהם ולאחריהם ומ\"מ בלפני פורים כת' שאסור בהספד לחודיה וטעמו משום תענית אסתר וכ' שם ואע\"ג דר' יוחנן פסק בדלא למספד כר\"מ לא קי\"ל כוותייהו דהא רב אשי קאמר שם כל שלאחריו כו' והוא כר' יוסי וז\"ש כאן בש\"ע לפניהם ולאחריהם. אבל הר\"ן בספ\"ב דתענית פסק כר' יוחנן. ודברי הרי\"ף הנ\"ל במגילה שם צ\"ע שכת' דלפניהם ולאחריהם אסורין בהספד וזהו דלא כרב אשי וכן בירושלמי פריך על יום נקנור לית הוא עצמו מפני שהוא יום שלפני י\"ד ומשני להודיעך שהוא אסור בהספד והביאו הר\"ן בתענית שם ונראה שאינו דברי הרי\"ף וכ\"כ הר\"ן שם:","\u0003ס\"ב ואם חל. \u0004כמ\"ש בתענית כ\"ז ב':","\u0003ותענית זה כו'. \u0004דלא כר\"ת שכ' דתענית קבוע הוא וכ\"כ הראב\"ד דז\"ש דברי הצומות כו'. וליתא דהא בימיהם היתה מי\"ט הכתובים במגילת תענית ובירושלמי הנ\"ל לית הוא עצמו כו' שלפני י\"ד כו' שהוא אסור בהספד אלמא אף בלא\"ה היה אסור בהספד ותענית וא\"ל בהספד לחוד כמ\"ש הר\"ן בספ\"ב דתענית דלישנא דירושלמי לא מ' כן מדקאמר להודיעך כו' וכן קשה על הרא\"ש שכ' בס\"ת ולמאי דפרישית לעיל כו'. ומ\"ש דברי הצומות כת' הר\"ן שכבר פי' דקאי על ד' צומות וה\"ק תקבלו עליהן לעשות שמחה כמו שקבלו דברי הצומות מכבר ומזה כת' הר\"ן דזעקתם קשה דד' הצומות אינן לזעקה ותפלה וא\"ל דקבלו לצום ומשנבנה בה\"מ בטלה כמו שבטלו ד' צומות אז דא\"כ נ\"ל ליום ניקנור הא בלא\"ה הוי לששון ולשמחה כמו הד' צומות וכמו דפריך בפ\"ק דר\"ה על ג' בתשרי:","\u0003כגון כו'. \u0004דאנו אין מתענין אפי' בראשונות ואחרונות כמ\"ש בספ\"ק דתענית ולא אמרו אלא בת\"ב וביה\"כ כמ\"ש בפ\"ד דפסחים ופשיטא לחולה שאין כו':","\u0003ואפי'. \u0004דאף בד' תעניות אמרו בר\"ה י\"ח ב' רצו אין כו' רק משום ופורץ גדר כמ\"ש הרמב\"ן:","\u0003ויפרעו ואח\"כ. \u0004שתענית זה אינו קבוע כמ\"ש במס' סופרים שהיו מתענין אחר פורים מפני נקנור וחבריו וע' ר\"ן שם:","\u0003אבל שאר. \u0004כמ\"ש בתענית י\"א א':","\u0003ומה חל. \u0004דבעל הברית מותר אף בשאר תענית אף שאינן נדחין חוץ מת\"ב כמש\"ש י\"ב א' ועירובין מ\"א א' דאר\"א ב\"צ כו' וכתבו תוס' בר\"ה י\"ט א' ד\"ה אסורין דוקא בט\"ב דחמיר אבל בשאר תענית א\"צ להתענות כלל מדקאמר לפניהם ולאחריהן מותרין ולרבנן בלא השלמה וע\"כ בי\"ט אף בכה\"ג אסור וכן חתן ביום חופתו וע' במ\"א סי' תקנ\"ט ס\"ק י\"א בשם ר\"ש הלוי ע\"ש:"]}],["חַיָּב אָדָם \u0010y0\u0011 לִקְרוֹת הַמְּגִלָּה בַּלַּיְלָה \u0010y1\u0011 וְלַחֲזֹר וְלִשְׁנוֹתָהּ בַּיּוֹם. וְשֶׁל לַיְלָה, זְמַנָּהּ \u0010y2\u0011 כָּל הַלַּיְלָה; וְשֶׁל יוֹם, זְמַנָּהּ כָּל הַיּוֹם \u0010y3\u0011 מֵהָנֵץ הַחַמָּה \u0010y4\u0011 עַד סוֹף הַיּוֹם; וְאִם קְרָאָהּ מִשֶּׁעָלָה עַמּוּד הַשַּׁחַר, \u0010y5\u0011 יָצָא. \u0010y6\u0011\nמְבַטְּלִים תַּלְמוּד תּוֹרָה לִשְׁמֹעַ מִקְרָא מְגִלָּה, קַל וָחֹמֶר לִשְׁאָר מִצְוֹת שֶׁל תּוֹרָה שֶׁכֻּלָּם נִדְחִים מִפְּנֵי מִקְרָא מְגִלָּה, וְאֵין לְךָ דָּבָר שֶׁנִּדְחָה מִקְרָא מְגִלָּה מִפָּנָיו חוּץ מִמֵּת מִצְוָה שֶׁאֵין לוֹ \u0010y7\u0011 קוֹבְרִים \u0005 כְּדֵי \u0006 \u0005 צָרְכּוֹ, \u0006 שֶׁהַפּוֹגֵעַ בּוֹ קוֹבְרוֹ תְּחִלָּה וְאַחַר כָּךְ קוֹרֵא. \u0005 הַגָּה: וְכָל זֶה לֹא מַיְרֵי אֶלָּא \u0010y8\u0011 בִּדְאִכָּא שְׁהוּת לַעֲשׂוֹת שְׁתֵּיהֶן, \u0010y9\u0011 אֲבָל אִם אִי אֶפְשָׁר לַעֲשׂוֹת שְׁתֵּיהֶן \u0010y10\u0011 אֵין שׁוּם מִצְוָה דְּאוֹרַיְתָא נִדְחֵית מִפְּנֵי מִקְרָא מְגִלָּה \u0006 \u0005(רַ\"ן וּבֵית יוֹסֵף בְּשֵׁם תּוֹסָפוֹת ומהר\"א מִזְרָחִי)\u0006. \u0005 וְהָא דְּמֵת מִצְוָה קוֹדֵם, הַיְנוּ דַּוְקָא \u0010y11\u0011 \u0006 \u0005 בִּדְאֶפְשָׁר לוֹ לְקָרְאָהּ אַחַר כָּךְ \u0006 \u0005(מהר\"א מִזְרָחִי)\u0006.",["\u0003לקרות המגילה בלילה\u0004 משעת צאת הכוכבים ועיין לקמן בסימן תרצ\"ב ס\"ד במ\"ב ובה\"ל מה שכתבנו שם:","\u0003ולחזור ולשנותה ביום\u0004 זכר לנס שהיו צועקים בימי צרתם יום ולילה:","\u0003כל הלילה\u0004 עד עמוד השחר ואם לא קראה קודם אפילו באונס שוב לא יקרא דמשעלה עה\"ש יממא הוא:","\u0003מהנץ החמה\u0004 לפי שאין הכל בקיאין בעמוד השחר וזמנין דאתי לאקדומי צריך לכתחלה להמתין עד הנץ דיום ברור הוא לכל:","\u0003עד סוף היום\u0004 היינו שקיעת החמה ואם נמשך עד בין השמשות יקראנה בלי ברכה:","\u0003יצא\u0004 ואם היה אונס קצת יכול לקרותה לכתחלה משעלה עמוד השחר [אחרונים]:","\u0003מבטלים ת\"ת וכו'\u0004 ר\"ל אף דת\"ת שקול כנגד כל המצות ואפילו היתה ת\"ת של חבורה גדולה של ק' אנשים שלומדים באיזה בית אפ\"ה צריך לבטל ולילך לקרותה בצבור משום ברב עם הדרת מלך. וכתב הח\"א מ\"מ מי שמתפלל כל השנה בקביעות במנין המיוחד לו להתפלל שם א\"צ לילך לביהכ\"נ:","\u0003כדי צרכו\u0004 מלשון זה מוכח דאף שהוא בעיר שיש לו קוברין דשוב אינו מוטל בבזיון והזריזות לקוברו קודם הוא רק תוספות כבוד לו אפ\"ה מותר להקדימו קודם מקרא מגילה וכ\"מ בהג\"ה סוף סי' תרצ\"ו דס\"ל דקבורת מתו קודם אבל במ\"א הביא בשם כמה פוסקים דס\"ל דוקא מת מצוה משמע שמצאו בשדה שהוא מוטל בבזיון שאין לו קוברין כלל אבל בעיר שיש לו אנשים שדואגין בעבורו מקרא מגילה קודם [אם לא בת\"ח שקבורתו קודם למקרא מגילה] וכן הסכים בביאור הגר\"א להלכה אכן כתב שאם התחילו להוציאו אין מפסיקין באמצע ואז נדחה מקרא מגילה לגמרי אפילו א\"א לקראה אח\"כ וכעין זה כתב הפר\"ח ג\"כ עי\"ש:","\u0003בדאיכא שהות וכו'\u0004 וה\"ה לענין מילה ומגילה איכא שהות לעשות שתיהן מגילה קודם משום פרסומי ניסא [פר\"ח ופרמ\"ג] והעולם נוהגין למול קודם המגילה וכדלקמן בסוף סימן תרצ\"ג [ח\"א]:","\u0003אבל אם א\"א וכו'\u0004 ר\"ל שיתבטל המצוה דאורייתא לגמרי אם לא יעשנה ביום ההוא ומה שכתב לקמיה דאם א\"א לו לקראה אח\"כ יקראנה קודם התם לא יתבטל לגמרי המצות קבורה דיהיה אפשר לו לקברו בלילה ואה\"נ דאם לא יהיה אפשר לו לקברו אח\"כ כגון מפני לסטים וכה\"ג בודאי מת מצוה קודם:","\u0003אין שום מצוה דאורייתא נדחית וכו'\u0004 מפני שמקרא מגילה הוא רק מדרבנן ועיין בט\"ז שהביא בשם רש\"ל וב\"ח דתמיד מקרא מגילה קודם משום פרסומי ניסא והגר\"א בביאורו ג\"כ סובר הכי עי\"ש:","\u0003בדאפשר לו לקראה\u0004 אבל אם הוא סמוך לחשיכה יקרא המגילה דהא מת מצוה אפשר לקוברו בלילה. והנה זה העתיק הרמ\"א בשם מהר\"א מזרחי אבל כמה אחרונים חולקין ע\"ז וסוברין דאפילו באופן שידחה המגילה לגמרי ג\"כ מת מצוה קודם משום בכבוד הבריות אכן כבר ביארנו לעיל דדוקא במת מצוה משמת אבל לא בשאר מתים ואפילו אם נפסוק שם דבשאר מתים ג\"כ מצוה להקדים קבורתו לקריאת המגילה עכ\"פ היכא דידחה עי\"ז קריאת המגילה לגמרי בודאי מגילה קודם ויקבר מתו בלילה:"],[],"\u0010g0\u0011 חַיָּב אָדָם \u0010y0\u0011 לִקְרוֹת הַמְּגִלָּה בַּלַּיְלָה \u0010y1\u0011 וְלַחֲזֹר וְלִשְׁנוֹתָהּ בַּיּוֹם. \u0010g1\u0011 וְשֶׁל לַיְלָה, זְמַנָּהּ \u0010y2\u0011 \u0010t0\u0011 \u0010m0\u0011 כָּל הַלַּיְלָה; וְשֶׁל יוֹם, זְמַנָּהּ כָּל הַיּוֹם \u0010y3\u0011 מֵהָנֵץ הַחַמָּה \u0010y4\u0011 עַד סוֹף הַיּוֹם; וְאִם קְרָאָהּ מִשֶּׁעָלָה עַמּוּד הַשַּׁחַר, \u0010y5\u0011 יָצָא. \u0010y6\u0011 \u0010g2\u0011 \u0010r0\u0011\nמְבַטְּלִים תַּלְמוּד \u0010t1\u0011 תּוֹרָה \u0010m1\u0011 לִשְׁמֹעַ מִקְרָא \u0010t2\u0011 מְגִלָּה, קַל וָחֹמֶר לִשְׁאָר מִצְוֹת שֶׁל תּוֹרָה שֶׁכֻּלָּם נִדְחִים מִפְּנֵי מִקְרָא \u0010m2\u0011 מְגִלָּה, וְאֵין לְךָ דָּבָר שֶׁנִּדְחָה מִקְרָא מְגִלָּה מִפָּנָיו \u0010g3\u0011 חוּץ מִמֵּת מִצְוָה שֶׁאֵין לוֹ \u0010y7\u0011 \u0010m3\u0011 קוֹבְרִים \u0005 כְּדֵי \u0010t3\u0011 \u0006 \u0005 צָרְכּוֹ, \u0006 שֶׁהַפּוֹגֵעַ בּוֹ קוֹבְרוֹ תְּחִלָּה וְאַחַר כָּךְ קוֹרֵא. \u0005 הַגָּה: וְכָל זֶה לֹא מַיְרֵי אֶלָּא \u0010y8\u0011 \u0010m4\u0011 בִּדְאִכָּא שְׁהוּת לַעֲשׂוֹת שְׁתֵּיהֶן, \u0010y9\u0011 אֲבָל אִם אִי אֶפְשָׁר לַעֲשׂוֹת שְׁתֵּיהֶן \u0010y10\u0011 אֵין שׁוּם מִצְוָה דְּאוֹרַיְתָא נִדְחֵית מִפְּנֵי מִקְרָא מְגִלָּה \u0006 \u0005(רַ\"ן וּבֵית יוֹסֵף בְּשֵׁם תּוֹסָפוֹת ומהר\"א מִזְרָחִי)\u0006. \u0005 וְהָא דְּמֵת מִצְוָה קוֹדֵם, הַיְנוּ דַּוְקָא \u0010y11\u0011 \u0010t4\u0011 \u0010s0\u0011 \u0010s1\u0011 \u0010m5\u0011 \u0006 \u0005 בִּדְאֶפְשָׁר לוֹ לְקָרְאָהּ אַחַר כָּךְ \u0006 \u0005(מהר\"א מִזְרָחִי)\u0006. \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011",{"g":["מימרא דר' יהושע ב\"ל מגילה ד'","רמב\"ם בפ\"א ממשנה שם כ'","ברייתא שם ג'","בעיא דרבא שם והדר פשטה"],"t":["\u0003כל הלילה. \u0004 ואחר שעלה עמוד השחר לא יקרא וגר שנתגייר קודם הנץ החמה פטור מקריאת הלילה מ\"א וע\"ש בהלק\"ט סימן רפ\"ו. ואונס קצת יכול לשמוע של יום אחר שעלה עמוד השחר:","\u0003תורה. \u0004 עיין מ\"א וט\"ז ובתשובת שבות יעקב חלק ב' סימן מ\"ו. ובתשובת חות יאיר סי' ח' פלפול חריף ע' י\"א ובשכנה\"ג:","\u0003מגילה. \u0004 בצבור ב\"י ב\"ח:","\u0003צרכו. \u0004 משמע דס\"ל דאע\"פ שיש לו קוברין כיון שאינם כדי צרכו מקרי מת מצוה וכ\"מ בהג\"ה ססי' תרצ\"ו סעיף ז' דס\"ל דקבורתו קודם ע\"ש. ומ\"א חולק וכ' דוקא במת שאין לו קוברין וכ\"כ הש\"ג דוק' כשהוא בשדה שהוא מוטל בבזיון אבל בעיר מגילה קודם וכ\"כ הב\"ח וכ\"מ בד\"מ בשם א\"ז שכתב קבורת ת\"ח קודם למגילה עכ\"ל. וטעמו מדאמרינן כבוד תורה דיחיד חמיר משמע דלשאר כל אדם מגילה קודם כיון שמוטל בעיר וכן עיקר עכ\"ל:","\u0003בדאפש'. \u0004 אבל אם הוא סמוך לחשיכה יקר' המגילה דהא מת מצוה אפש' לקברו בלילה אבל אם הוא בענין שא\"א לקוברו אח\"כ מפני לסטים בודאי ידחה מקרא מגיל' עיין מ\"א ובט\"ז. מילה ומקר' מגילה אי איכא שהות לשתיהן מקר' מגילה קודם משום פרסום ניסא ואי ליכא שהות לשתיהן מילה בזמנה דהוי דאורייתא וקודמת למקר' מגילה דהוי דרבנן פר\"ח. אבל בת\"ה סימן רס\"ב [ורס\"ג] צידד לומר איפכ' דכשיש שהות יקדים המילה וכשאין שהות יקדים המגילה. ונ\"ל הטעם דיכול למול בתשיעי. כנה\"ג ע\"ש:"],"s":["\u0003 (ס\"א) בש\"ע חייב אדם כו' \u0004 ועיין בנ\"ב סי' מ\"א שדעתו דקריאת הלילה דרבנן וקריאת היום מדברי קבלה ע\"ש ועיין בבר\"י שאם שכח או נאנס בלילה די בקריאה דיום וא\"צ לשנותה עוד הפעם ולתשלום קריאת הלילה ע\"ש:","\u0003בדאפשר וע' בשבו\"י \u0004 ח\"ב סי' מ\"ג מ\"ש בענין זה וע' בתשו' מהרי\"ט צהלון סי' רפ\"ז וע' בשו\"ת חוות יאיר סי' ח' ט' י' י\"א פלפול עצום וארוך בענין זה על דברי הר\"א מזרחי והב\"י והט\"ז ומג\"א ע\"ש ועמ\"ש ביד אפרים וע' בשאילת יעב\"ץ ח\"ב סי' ק\"ב על מ\"ש בחו\"י שם בשם הגאון אב\"ד דפ\"פ דל\"ל דנשים חייבות במגילה ת\"ל מלאו דלא תסור וכל ל\"ת נשים חייבות ועמ\"ש החו\"י לתרץ והוא כ' דלק\"מ דבמקום שתיקנו בפירוש גם על הנשים פשיטא דאיכא למימר לאו דל\"ת אבל כאן דלא תיקנו עליהם כלל דלא עדיף ממצות דאורייתא דכל מ\"ע שהז\"ג נשים פטורות ור\"ל דרבנן כעין דאורייתא תיקנו וע\"ז קאמר דודאי גם עלייהו תיקנו לפי שגם הן היו באותו נס ע\"ש וע' לקמן סי' תרצ\"ה סק\"ג מ\"ש על דברי פר\"ח לענין משלוח מנות דאשה וע' בשאילת יעב\"ץ סי' ק\"ך ח\"א:"],"m":["כתוב בהגמ\"נ גר שנתגייר קודם הנץ החמ' פטור מקריא' הליל' דעיקר מצות' ביום עכ\"ל נ\"ל דה\"פ אף על פי שלענין ק\"ש מקרי לילה וחייב כמ\"ש סי' נ\"ח מ\"מ פטור ממגילה הואיל ועיקר מצותו ביום ומשמע שאחר שלא קראה בליל' קורא' קודם הנץ החמה ול\"נ דאינו קורא אחר שעלה עמוד השחר דבשלמא ק\"ש תלוי בזמן שכיב' ואיכא אינשי דגני בההיא שעתא אבל הכא תלוי בלילה וכיון שעלה עמוד השחר מקרי יום כדאיתא בגמ': \u0003כל הלילה\u0004. אף על גב דק\"ש עד חצות דוקא הכא לא גזרי' דלמא אתי למפשע איידי דחביבא להו עכ\"ל הרא\"מ בסמ\"ג, ולפי מש\"ל דעיקר מצותו ביום לא קשה מידי:","\u0003לשמוע מקרא מגילה\u0004. בציבור [ב\"י ב\"ח] עססי' תר\"צ:","\u0003שאין לך כו'\u0004. משמע דס\"ל דאפי' ת\"ת דרבים מבטלין ובגמ' משמע דלא מבטלין דרבים [כ\"ה] וע' רד\"ך בי\"ג [עססי' תר\"צ], וב\"ח כ' ת\"ת דרבים היינו של כל ישראל וכ\"מ בתוס' בד\"ה מ\"מ עדיף וכו' ע\"ש ומ\"מ נ\"ל דהא עכ\"פ צריכין לקרות המגילה ומיהו יחיד צריך לבטל מלימודו ולילך לקרות בצבור אבל רבים לא שייך הא דאפי' כל יחיד לומד בפני עצמו מקרי רבים הואיל ומבטל כל א' וכ\"מ בתוס':","\u0003כדי צרכו\u0004. משמע דס\"ל דאע\"פ שיש לו קוברין כיון שאינם כדי צרכו מקרי מת מצוה וכ\"מ בהג\"ה סוף סי' תרצ\"ו דס\"ל דקבורת מתו קודם וצ\"ע דהא אמרי' פשיטא לי מגילה ועבודה מגילה עדיף מת מצוה ועבודה מת מצוה עדיף מת מצוה ומגילה מאי וכו' ופשיט הא דאמרי' מת מצוה עדיפא מעבוד' היינו דוקא במת שאין לו קוברין אבל קבורת קרובים לא דחי עבודה וכ\"כ בתוס' בשבועות דף ל' ע\"ב וא\"כ פשיטא דמגיל' עדיפא מקבורת קרובים דהא מגיל' עדיפא אפי' מעבוד' ומיהו זה יש לדחות אבל האמת יורה דרכה כמ\"ש הרמב\"ן בס' תה\"א דמת מצוה דוקא קאמר אלא דרישא דקאמר מ\"מ עדיפא מת\"ת איירי בכל מתים ע\"ש וכ\"כ התוס' ועמ\"ש סי' תקכ\"ו בשם יש\"ש וכ\"כ הש\"ג דוקא כשהוא בשדה שהוא מוטל בבזיון אבל בעיר מגילה קודם וכ\"כ הב\"ח וכ\"מ בד\"מ בשם א\"ז שכ' קבורת ת\"ח קודם למגיל' עכ\"ל וטעמו מדאמרי' כבוד תורה דיחיד חמיר משמע דלשאר כל אדם מגיל' קודם וכן עיקר וכ\"מ בברכות דף כ' דקבורת קרובים לא מקרי כבוד הבריות כיון שמוטל בעיר וא\"כ לא דחי מגיל' וכ\"מ ברא\"מ סס\"ב:","\u0003בדאיכ' שהות\u0004. וה\"ה מילה ומגיל' אבל בת\"ה סי' רס\"ו צידד לומר איפכא דכשיש שהות יקדים המילה וכשאין שהות יקרא המגילה, ונ\"ל הטעם דיכול למול בתשיעי [כ\"ה] עססי' תרצ\"ג:","\u0003בדאפשר לו לקראה\u0004. אבל אם הוא סמוך לחשיכה יקרא המגילה דהא מ\"מ אפשר לקברו בלילה אבל אם הוא בענין שא\"א לקוברו אח\"כ מפני לסטים בודאי ידחה מקרא מגילה דהא מ\"מ דחי עבודה לגמרי ועבודה דחי מגילה לגמרי ומ\"מ צ\"ע דהא ילפי' בגמ' מ\"מ עדיף דאמר מר גדול כבוד הבריות שדוחה ל\"ת שבתו' וק\"ל בלאו דלא תסור דחי' המצו' לגמרי משום כבוד הבריו' כמ\"ש סי' י\"ג וע\"ק דהא פסח ומילה דחיה לגמרי משום כבוד הבריות אף על פי שאפשר לקוברו אח\"כ מ\"מ אמרי' שלא יהא מוטל בבזיון ק\"ו למגילה דהא אין שום מצוה דאוריי' נדחית מפני מגילה ואפ\"ה נדחית מפני מ\"מ ק\"ו למגיל' שתדח' בפניה והרא\"ם בעצמו הביא כל הני מילי דאמרן [וכ\"ה כ' על פי' הב\"י ברא\"ם דברי רבי' תמוהים הארכתי בהם בקונט' עכ\"ל כיון למה שכתבתי] לכן נ\"ל דהרא\"ם לא בא אלא להוכיח דהרמב\"ם לא מיירי אלא מדין קדימ' מדקאמ' קוברו תחל' ואח\"כ קורא דמשמע אי איכא שהות אין ואי לא לא כלו' משמע דהרמב\"ם מיירי בדאיכא שהות ואי לא לא פי' דאי ליכא שהות לעשות שתיהן לא קמיירי אלא מגילה נדחת מפני כל המצות דאורייתא וק\"ו מפני מ\"מ כנ\"ל:"],"r":["\u0003ס\"א מהנץ כו' ואם. \u0004שם:","\u0003ס\"ב ק\"ו לשאר. \u0004פ\"ק דפאה וספ\"ק דקדושין:","\u0003שאין. \u0004רמב\"ם:","\u0003כדי צרכו. \u0004כ\"כ הכל בו. אבל הרמב\"ם וש\"ע השמיטו דס\"ל דוקא במת מצוה. וכן משמע לכאורה מדקבעי רבא מ\"מ ומ\"מ איזה כו' ואי בכל מת קאמר ע\"כ מקרא מגילה עדיף שדוחה עבודה ומת אינו דוחה עבודה. אבל י\"ל דלכאורה קשה דהקדי' שם דת\"ת ועבודה דנדחים מפני מ\"מ מפני הבעיא ובאיזה מת קמיבעיא אם במ\"מ דוקא לא הל\"ל ת\"ת ואם בכל מת לא ה\"ל להקדים עבודה אלא דהבעי' דוקא במ\"מ כנ\"ל אבל הדר דפשטה גדול כו' ה\"ה בכל מת וכמ\"ש בברכות י\"ט ב' בא בטהורה כו' ולכן הקדים ת\"ת ואף שאמרו שם דוקא מפני כבוד ת\"ח היינו בהספד אבל בקבורה ה\"ה לכל אדם. ומיהו נראה לי דוקא בהתחילו דלא גרע מק\"ש וכמ\"ש שם בברכות י\"ט א' ואז נדחי' מקרא מגילה לגמרי אפי' א\"א לקראה אח\"כ דלא כמ\"ש בהג\"ה וכמ\"ש גדול כבוד הבריות שדוחה ומשמע לגמרי וכמ\"ש בברכות שם וש\"מ בפסח ומילה דדחי לגמרי ועיין מ\"א וכן הבעיא שלו לדחות לגמרי דהא הבעיא שלו מדדחי עבודה ושם דחי לגמרי ועוד מדבעיא ליה פרסומי ניסא עדיף וזהו דוקא לדחות כמ\"ש תוס' בשבת כ\"ג ב' ד \"ה הדר כו' והרא\"ש שם דאיכא פרסומי ניסא כו':","\u0003וכל זה כו'. \u0004כ\"כ הדין שם דמ\"ש שמבטלין עבודתן כו' היינו שיכולין להשלים אח\"כ העבודה כיון שהיא דאורייתא ודבריו תמוהין דא\"כ הא דבעי רבא שם מקרא מגילה ומ\"מ כו' ר\"ל כיון דשניהם דוחין עבודה ות\"ת ואם איתא הא ע\"כ מ\"מ עדיף דדוחה עבודה לגמרי ובסנהדרין ל\"ה א' ותהא קבורת מ\"מ דוחה שבת כו' וכן לשאר מצות וכמש\"ש ולמול כו' ונקט אלו אע\"פ שיש בהן כרת וכ\"ש לשאר וה\"ה למגילה:","\u0003אבל אם כו'. \u0004לתירוץ חד דתוס' בפ\"י דפסחים ובפ\"ק דנזיר דקידוש על היין דבר תורה ואמרינן בפ\"ב דשבת שנ\"ח דוחה אותה והוא דלא כמ\"ש כאן ור\"ן ס\"ל כתי' אחר וכמ\"ש הרמב\"ם ומד\"ס לקדש על היין כו':"]}],["כְּרַכִּים הַמֻּקָּפִים חוֹמָה מִימוֹת יְהוֹשֻׁעַ בִּן נוּן, \u0010y0\u0011 אֲפִלּוּ אֵינָן מֻקָּפִין עַכְשָׁו, קוֹרִין בְּט\"ו, אֲפִלּוּ אִם הֵם בְּחוּצָה לָאָרֶץ, \u0010y1\u0011 וַאֲפִלּוּ אֵין בָּהֶם עֲשָׂרָה בַּטְלָנִים \u0005(פי' בַּטְלָנִים מִמְּלַאכְתָּם \u0010y2\u0011 וְעוֹסְקִים בְּצָרְכֵי צִבּוּר)\u0006; וְהוּא שֶׁהֻקַּף וְאַחַר כָּךְ יָשַׁב, אוֹ שֶׁיָּשַׁב תְּחִלָּה עַל דַּעַת לְהַקִּיפוֹ אַחַר כָּךְ, \u0010y3\u0011 לַאֲפוּקֵי כְּשֶׁנּוֹדַע שֶׁיָּשַׁב תְּחִלָּה עַל דַּעַת שֶׁלֹּא לְהַקִּיפוֹ \u0010c0\u0011 \u0005 אֲבָל \u0006 \u0005 בִּסְתָמָא הֻקְּפָה וּלְבַסּוֹף יָשְׁבָה \u0006 \u0005(רַ\"ן)\u0006.\nוְכֵן \u0010y4\u0011 הַכְּפָרִים הַנִּרְאִים עִמָּהֶם, אֲפִלּוּ אֵינָם סְמוּכִים, כְּגוֹן שֶׁהֵם בָּהָר; אוֹ \u0010c1\u0011 שֶׁסְמוּכִים לָהֶם, אֲפִלּוּ אֵינָם נִרְאִים עִמָּהֶם, כְּגוֹן שֶׁהֵם בָּעֵמֶק, \u0010y5\u0011 וּבִלְבַד שֶׁלֹּא יִהְיוּ רְחוֹקִים יוֹתֵר מִמִּיל. וּבְשׁוּשָׁן אַף עַל פִּי שֶׁאֵינָהּ מֻקֶּפֶת חוֹמָה מִימוֹת יְהוֹשֻׁעַ, \u0010y6\u0011 קוֹרִין בְּט\"ו הוֹאִיל וְנַעֲשָׂה בּוֹ הַנֵּס.\nכְּפָרִים וַעֲיָרוֹת גְּדוֹלוֹת, וּכְרַכִּים שֶׁאֵינָם מֻקָּפִים חוֹמָה מִימוֹת יְהוֹשֻׁעַ בִּן נוּן \u0010y7\u0011 קוֹרִין בְּי\"ד.\nכְּרַךְ \u0010y8\u0011 שֶׁהוּא סָפֵק אִם הֻקַּף בִּימֵי יְהוֹשֻׁעַ אִם לָאו, קוֹרִין \u0010y9\u0011 בְּי\"ד וּבְט\"ו וּבְלֵילֵיהוֹן, \u0010y10\u0011 וְלֹא יְבָרֵךְ כִּי אִם בְּי\"ד שֶׁהוּא זְמַן קְרִיאָה לְרֹב הָעוֹלָם. \u0010y11\u0011\nבֶּן עִיר שֶׁהָלַךְ לַכְּרַךְ, \u0010c2\u0011 אוֹ בֶּן כְּרַךְ שֶׁהָלַךְ לָעִיר, אִם הָיָה דַּעְתּוֹ לַחֲזֹר לִמְקוֹמוֹ בִּזְמַן קְרִיאָה \u0005(שֶׁל י\"ד)\u0006 וְנִתְעַכֵּב וְלֹא חָזַר, קוֹרֵא בִּמְקוֹמוֹ; וְאִם לֹא הָיָה בְּדַעְתּוֹ לַחֲזֹר אֶלָּא לְאַחַר זְמַן הַקְּרִיאָה, קוֹרֵא עִם אַנְשֵׁי הַמָּקוֹם שֶׁהוּא שָׁם. \u0005 הַגָּה: \u0010y12\u0011 וְאִם הוּא בַּמִּדְבָּר אוֹ בַּסְּפִינָה, קוֹרֵא בְּיוֹם י\"ד כְּמוֹ רֹב הָעוֹלָם \u0006 \u0005(כָּל בּוֹ)\u0006. \u0010y13\u0011\nיוֹם חֲמִשָּׁה עָשָׂר שֶׁחָל לִהְיוֹת בְּשַׁבָּת \u0010y14\u0011 אֵין קוֹרִין \u0010y15\u0011 הַמְּגִלָּה בְּשַׁבָּת, אֶלָּא מַקְדִּימִים לִקְרוֹתָהּ בְּעֶרֶב שַׁבָּת, וְגוֹבִים מָעוֹת מַתְּנוֹת עֲנִיִּים וּמְחַלְּקִים אוֹתָם בּוֹ בַּיּוֹם; וּבְיוֹם שַׁבָּת מוֹצִיאִים שְׁנֵי סְפָרִים וּבַשֵּׁנִי קוֹרִין: וַיָּבֹא עֲמָלֵק; \u0010y16\u0011 וְאוֹמְרִים: עַל הַנִּסִים; \u0010y17\u0011 וְאֵין עוֹשִׂים סְעֻדַּת פּוּרִים עַד יוֹם אֶחָד בְּשַׁבָּת.\nהַמְפָרֵשׁ בַּיָּם וְהַיּוֹצֵא \u0010y18\u0011 בְּשַׁיָּרָא וְאֵינוֹ מוֹצֵא מְגִלָּה לְהוֹלִיךְ עִמּוֹ, יִקְרָאֶנָּה \u0010y19\u0011 \u0010c3\u0011 בְּי\"ג אוֹ בְּי\"ב אוֹ בְּאֶחָד עָשָׂר, בְּלֹא בְּרָכָה; וְאִם אִי אֶפְשָׁר לְהַמְתִּין עַד יָמִים הַלָּלוּ, יֵשׁ אוֹמְרִים שֶׁקּוֹרֵא \u0010y20\u0011 אֲפִלּוּ מִתְּחִלַּת הַחֹדֶשׁ. \u0005 הַגָּה: וְהָכֵי נָהוּג; מִיהוּ אִם נִזְדַּמֵּן לוֹ \u0010y21\u0011 אַחַר כָּךְ מְגִלָּה, חוֹזֵר וְקוֹרֵא אוֹתָהּ \u0006 \u0005 בְּיוֹם י\"ד, אֲפִלּוּ קְרָאָהּ תְּחִלָּה בְּיוֹם י\"ג מִכָּל מָקוֹם קָרָא אוֹתָהּ שֶׁלֹּא בִּזְמַנָּהּ \u0006 \u0005(כָּל בּוֹ וּבֵית יוֹסֵף)\u0006.\nבֶּן עִיר שֶׁהָיָה בַּסְפִינָה אוֹ בַּדֶּרֶךְ וְלֹא הָיָה בְּיָדוֹ מְגִלָּה, וְאַחַר כָּךְ נִזְדַּמְּנָה לוֹ בְּט\"ו, \u0010y22\u0011 קוֹרֵא אוֹתָהּ בְּט\"ו.",["\u0003המוקפים חומה מימות יהושע בן נון\u0004 כי בזמן מרדכי בעת הנס כתיב שהיהודים שבכל מקום נלחמו ביום י\"ג ונחו ביום י\"ד ועשו אותו משתה ושמחה ובשושן ניתן ליהודים להלחם עם העכו\"ם גם ביום י\"ד ולא עשו יו\"ט עד ט\"ו וכיון שבאותו זמן נחלקו לשני ימים ולכן כשקבע מרדכי ואסתר בהסכמת אנשי כה\"ג לקבוע פורים לדורות חלקו ג\"כ אותו לשני ימים והיה ראוי לתקן שכל עיר שהיא מוקפת חומה כמו שושן יהיה דומה לשושן לעשות בט\"ו והיה ראוי לתלות הכבוד בשושן ולתקן שכל עיר שהיא מוקפת חומה מימות אחשורוש יקראו בט\"ו אך כיון שא\"י היתה חריבה באותו עת ויהיה לפ\"ז עיירות המוקפות בחו\"ל חשובות מהם וע\"כ תקנו לכבוד א\"י שכל עיר שהיא מוקפת מימות יהושע ב\"נ יקראו בט\"ו אע\"פ שאין מוקפות עכשיו והשאר בי\"ד לבד שושן אע\"פ שאינה מוקפת מימות יב\"נ אפ\"ה קורין בט\"ו מפני שבו נעשה הנס:","\u0003ואפילו אין בהם וכו'\u0004 ויש מהראשונים שחולקין ע\"ז וס\"ל דבכרך המוקף חומה אם אין בה עתה עשרה בטלנין קורין בה בי\"ד וביד אפרים מצדד דיש לחוש לשיטתם לקרות גם בי\"ד:","\u0003ועוסקים בצרכי צבור\u0004 פי' בבהכ\"נ כן איתא בהדיא בגמרא וע\"ש בפירש\"י דהיינו שהם קבועין תמיד להשכים ולהעריב בבהכ\"נ להתפלל ועיין בפי' המשנה להר\"מ ובהר\"ן:","\u0003לאפוקי כשנודע וכו'\u0004 אבל מסתמא אמרינן שישב על דעת להקיפה אחר כך שכן דרך רוב המדינות המוקפין חומה דאפילו אם אין מקיפין אותה מתחלה עכ\"פ מיישבין אותה ע\"ד להקיפה אח\"כ:","\u0003הכפרים\u0004 וה\"ה עיירות [נ\"ח וכ\"כ במאירי]:","\u0003ובלבד שלא יהיו וכו'\u0004 זה קאי אדסמיך ליה דהיינו שהיה סמוך אבל נראה אפילו רחוק יותר ממיל הוי ככרך וי\"א דבנראה ג\"כ אינו נחשב לכרך אא\"כ שאינו רחוק יותר ממיל:","\u0003הואיל ונעשה בו נס\u0004 שהם נחו בט\"ו כדכתיב בקרא:","\u0003קורים בי\"ד\u0004 מי שדינו לקרוא בט\"ו אינו יכול לקרוא ולפטור לבני י\"ד בי\"ד וכן להיפך כיון שאינו מחוייב עתה בדבר [פר\"ח] והפמ\"ג כתב דבדיעבד אם בן כרך קרא לבן י\"ד בי\"ד יצא:","\u0003שהוא ספק\u0004 וטבריא צריך לקרות בה בי\"ד ובט\"ו שספק אם הים חשוב כחומה [גמרא] ובמדינות אלו בכרכין המוקפין חומה אין להסתפק שמא מוקפין מימות יהושע ב\"נ לפי שהם מצפון ורחוקים מא\"י וידוע שלא היו מיושבים בזמן יהושע:","\u0003קורין בי\"ד ובט\"ו\u0004 ונוהגין שמחה ומתנות לאביונים בשניהם:","\u0003ולא יברך\u0004 שהברכה אפילו במצוה של תורה הוא מדרבנן וא\"כ בדבר שהוא ספק לענין הברכה הוא ספיקא דרבנן וכ\"ש בזה שהוא מצוה של דבריהם לכו\"ע א\"צ ברכה ומה שמברך בי\"ד משום דביום י\"ד הוא זמן קריאה לרוב העולם כדלקמיה ור\"ל דע\"כ אפילו הוא מוקף חומה שדינו בט\"ו אם קרא ביום י\"ד יצא בדיעבד ולא הוי ברכה לבטלה:","\u0003בן עיר שהלך לכרך וכו'\u0004 סעיף זה הוא לשון הרמב\"ם ומפני שרבים מתקשים בסעיף הזה מוכרח אני להרחיב הדבור קצת ונבארו כפי מה שפירשוהו המגיד והכסף משנה וכן משמע מהגר\"א. וצריכין אנו לידע שלשה דברים א) דאם הוא שייך לערי הפרזות אפילו יום אחד קרוי פרוז וקורא בי\"ד וכן אם הוא שייך למוקפין אפילו יום אחד קרוי מוקף וקורא בט\"ו ב) זמן קריאה הוא העיקר ביום וכיון שהיה בערי הפרזות בהתחלת היום י\"ד קורא בי\"ד וכן כה\"ג לענין מוקפין ביום ט\"ו ג) זמן קריאה שכותב המחבר היינו זמן קריאת המקום שהוא בו עתה לא זמן שיצא משם ועתה נבאר את הסעיף כסדר בכל פרט בפני עצמו. בן עיר שהלך לכרך אם היה דעתו בעת נסיעתו לחזור למקומו בזמן קריאה ר\"ל בזמן קריאה של ט\"ו דהיינו משהאיר היום לא יהיה שם כי יחזור משם קודם אור היום אף שלבסוף רואה שהוא מוכרח להתעכב שם גם על יום ט\"ו מ\"מ אינו נקרא בשם מוקף וקורא ביום י\"ד בהיותו בכרך אבל אם בעת נסיעתו לא היה בדעתו לחזור מן הכרך אלא לאחר זמן הקריאה דהיינו בבקר של ט\"ו שאז כבר הוא זמן הקריאה אז חל עליו שם מוקף וקורא עמהן ביום ט\"ו ואפילו אם אח\"כ חזר לעירו ביום ט\"ו קורא שם אם לא קרא מתחלה בכרך. ועתה נבאר הסעיף לענין אופן השני דהיינו בן כרך שהלך לעיר אם היה דעתו בעת נסיעתו לחזור למקומו בזמן קריאה דהיינו שיחזור משם בליל י\"ד קודם שיאיר היום דהוא זמן קריאה ואף שלבסוף היה שנתעכב ולא חזר קוראו כמקומו דהיינו ביום ט\"ו אבל אם לא היה בדעתו בעת נסיעתו לחזור משם רק לאחר זמן קריאה דהוא ביום י\"ד בבוקר חל עליו חובת הקריאה של העיר וזה שאמר המחבר קורא עם אנשי המקום אשר הוא שם [וע\"כ אף שחזר באותו יום ובא לכרך צריך לקרוא באותו יום י\"ד דהוא נקרא פרוז בן יומו] וכתב הט\"ז דכ\"ז דוקא אם היה שם בעיר בתחלת היום אבל אם חזר למקומו שהוא כרך קודם היום לא מועיל מה שחשב מתחלה להיות בעיר בעת קריאת העיר:","\u0003ואם הוא במדבר וכו'\u0004 אפילו הוא מבני הכרכין א\"ז בשם כלבו:","\u0003יום ט\"ו וכו'\u0004 דאלו י\"ד א\"א לחול בשבת:","\u0003אין קורין וכו'\u0004 דגזרו רבנן שמא ילך אצל חכם ללמדה איך לקרותה ויעבירנה ד\"א בר\"ה:","\u0003המגילה בשבת\u0004 ואז יום השבת ח' לאדר הוא פרשת זכור ומפטירין פקדתי וגם בט\"ו לאדר מפטירין פקדתי בכרכין [אבל בעיירות מפטירין בסדר השבוע] ושואלין ודורשין בו ביום בהלכות פורים כדי שיזכרו ענין היום וכשחל בחול יוצאין ע\"י קריאת מגילה:","\u0003ואומרים על הנסים\u0004 בשבת ולא בע\"ש [שבאמת לכרכין זמנם בט\"ו ולא בי\"ד ורק משום גזירה כנ\"ל הצריכו לקרות המגילה בע\"ש ומ\"מ אם אמר אין מחזירין אותו] וכן אין מוציאין בו ס\"ת ולעיירות אומרים עה\"נ בי\"ד ולא בט\"ו ועיר מסופק אם היא מוקפת מימות יב\"נ אומרים עה\"נ בשני ימים:","\u0003ואין עושין וכו'\u0004 דאמרינן בירושלמי ויעשו אותם בשבת א\"ל ימי משתה כתוב את ששמחתו תלויה בב\"ד יצא זה [שבת] ששמחתו בידי שמים היא. וה\"ה ממילא ששילוח מנות גם ביום א' בשבת. והנה מהר\"ל חביב האריך להוכיח דבבלי שלנו אין סובר כן ודעתו שהסעודה היא בשבת ועשה כן מעשה בירושלים וגם משלוח מנות בשבת כי המנות הם מהסעודה. והרדב\"ז ח\"א סימן קמ\"ז פסק כהש\"ע וכן הוא ג\"כ דעת המ\"א והקרבן נתנאל ות' מ\"ב ח\"א סימן מ\"ב. והנה הפר\"ח אוסר לטלטל המגילה בשבת מאחר שאין קורין בו אבל כמה אחרונים חולקין עליו ומתירין:","\u0003ואינו מוצא מגילה וכו'\u0004 דאם היה מוצא מחויב ליקחה ולקרות בי\"ד:","\u0003יקראנה בי\"ג וכו'\u0004 בקיבוץ עשרה דשלא בזמנה בעי י' [ועיין במאירי דבדיעבד אף ביחיד יוצא ועיין לקמן ס\"ס תר\"צ במ\"ב] אכן אפשר דסגי בקטנים הואיל והוא רק משום פרסומי ניסא. ועיין בר\"ן שמסתפק לענין בני הכפרים שמקדימין לקרותה אי מחוייב לקרותה גם בלילה או די בקריאה דיום ופשוט דה\"ה לענין מפרשי הים ויוצא בשיירא ומדברי הטור משמע קצת דצריך לקרות גם בלילה. ודע עוד דהא דהקילו לבני הכפרים או למפרשי הים הוא רק לענין קריאת המגילה אבל סעודת פורים וכן משלוח מנות ומתנות לאביונים לא יקיים אלא בזמנה:","\u0003אפילו מתחלת החדש\u0004 דכתיב והחודש אשר נהפך מיגון לשמחה וגו':","\u0003חוזר וקורא אותה ביום י\"ד\u0004 היינו בברכותיה דהא זמנה היא:","\u0003קורא אותה בט\"ו\u0004 ובלא ברכה דכבר עבר עיקר זמנה אבל מט\"ו ואילך לא יקרא כלל דכתיב ולא יעבור. אם טעו וקראו הפרשיות והמגילה באדר ראשון צריך לחזור ולקרות בשני:"],["\u0003 על דעת שלא להקיפו\u0004 - היינו דלא נבנו בה בתים חדשים לאחר שהוקפה אבל אם נבנו בה דל בתים שקדמו להקיפן מכאן ונידונית ככרך ע\"י בתים הללו שלאחר הקיפן ונ\"ל דאזלינן בתר רובא דאם רוב בתים שבעיר קדמו להקיפן קורין בי\"ד ואם איפכא איפכא ומחצה על מחצה צ\"ע [טורי אבן]:","\u0003 או שסמוכין להם\u0004 - כפר הסמוך לכרך שהיו קורין בט\"ו ונהיה הכרך שמם יקראו בי\"ד [דבר משה] כרך של עכו\"ם שאין בו ישראל כלל ישראל הנכנס לכרך זה בפורים קורא בט\"ו. אם בכרך קראו בי\"ד וט\"ו מספק הכפרים הנראים וסמוכים קוראין בי\"ד [בר\"י]:","\u0003 בן עיר שהלך לכרך וכו'\u0004 - סעיף זה רבו פארותיו מאוד עיין בפמ\"ג ובשארי אחרונים והעתקתי במ\"ב רק שיטת רש\"י שהסכימו עליה הרבה ראשונים וגם זה בקיצור נמרץ ומ\"מ למעשה אני מבקש מהקורא שלא יסמוך עלי לענין ברכה ויעיין בפמ\"ג ועיין בש\"ג ובביאור הגר\"א שהעתיקו דברי הירושלמי לדינא שבן עיר שעקר דירתו בליל ט\"ו והלך לו לכרך נתחייב כאן וכאן:","\u0003 יקראנה וכו' בלא ברכה\u0004 - עיין בטור כי יש מהראשונים דסברי שהאידנא דנתבטל הדין שבני כפרים יכולים להקדים ממילא אין קורין שלא בי\"ד בשום גווני:"],"כְּרַכִּים הַמֻּקָּפִים חוֹמָה מִימוֹת יְהוֹשֻׁעַ בִּן נוּן, \u0010y0\u0011 \u0010g0\u0011 \u0010g1\u0011 \u0010m0\u0011 אֲפִלּוּ אֵינָן מֻקָּפִין עַכְשָׁו, קוֹרִין בְּט\"ו, \u0010g2\u0011 אֲפִלּוּ אִם הֵם בְּחוּצָה לָאָרֶץ, \u0010y1\u0011 \u0010g3\u0011 וַאֲפִלּוּ אֵין בָּהֶם עֲשָׂרָה בַּטְלָנִים \u0005(פי' בַּטְלָנִים מִמְּלַאכְתָּם \u0010y2\u0011 וְעוֹסְקִים בְּצָרְכֵי צִבּוּר)\u0006; \u0010g4\u0011 וְהוּא שֶׁהֻקַּף וְאַחַר כָּךְ יָשַׁב, \u0010g5\u0011 אוֹ שֶׁיָּשַׁב תְּחִלָּה עַל דַּעַת לְהַקִּיפוֹ אַחַר כָּךְ, \u0010y3\u0011 לַאֲפוּקֵי כְּשֶׁנּוֹדַע שֶׁיָּשַׁב תְּחִלָּה עַל דַּעַת שֶׁלֹּא לְהַקִּיפוֹ \u0010c0\u0011 \u0005 אֲבָל \u0010t0\u0011 \u0010m1\u0011 \u0006 \u0005 בִּסְתָמָא הֻקְּפָה וּלְבַסּוֹף יָשְׁבָה \u0006 \u0005(רַ\"ן)\u0006. \u0010g6\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011\nוְכֵן \u0010y4\u0011 הַכְּפָרִים הַנִּרְאִים עִמָּהֶם, אֲפִלּוּ אֵינָם סְמוּכִים, כְּגוֹן שֶׁהֵם בָּהָר; אוֹ \u0010c1\u0011 שֶׁסְמוּכִים לָהֶם, אֲפִלּוּ אֵינָם נִרְאִים עִמָּהֶם, כְּגוֹן שֶׁהֵם בָּעֵמֶק, \u0010y5\u0011 \u0010g7\u0011 \u0010t1\u0011 \u0010m2\u0011 וּבִלְבַד שֶׁלֹּא יִהְיוּ רְחוֹקִים יוֹתֵר מִמִּיל. וּבְשׁוּשָׁן אַף עַל פִּי שֶׁאֵינָהּ מֻקֶּפֶת חוֹמָה מִימוֹת יְהוֹשֻׁעַ, \u0010y6\u0011 \u0010g8\u0011 קוֹרִין בְּט\"ו הוֹאִיל וְנַעֲשָׂה בּוֹ הַנֵּס. \u0010g9\u0011 \u0010r5\u0011\nכְּפָרִים וַעֲיָרוֹת גְּדוֹלוֹת, וּכְרַכִּים שֶׁאֵינָם מֻקָּפִים חוֹמָה מִימוֹת יְהוֹשֻׁעַ בִּן נוּן \u0010y7\u0011 קוֹרִין בְּי\"ד. \u0010g10\u0011 \u0010r6\u0011\nכְּרַךְ \u0010y8\u0011 \u0010m3\u0011 שֶׁהוּא \u0010t2\u0011 \u0010s0\u0011 סָפֵק אִם הֻקַּף בִּימֵי יְהוֹשֻׁעַ אִם לָאו, \u0010m4\u0011 קוֹרִין \u0010y9\u0011 בְּי\"ד וּבְט\"ו וּבְלֵילֵיהוֹן, \u0010y10\u0011 \u0010g11\u0011 \u0010m5\u0011 וְלֹא יְבָרֵךְ כִּי אִם בְּי\"ד שֶׁהוּא זְמַן קְרִיאָה \u0010t3\u0011 לְרֹב הָעוֹלָם. \u0010y11\u0011 \u0010g12\u0011 \u0010r7\u0011 \u0010r8\u0011 \u0010r9\u0011\nבֶּן עִיר שֶׁהָלַךְ לַכְּרַךְ, \u0010c2\u0011 אוֹ בֶּן כְּרַךְ שֶׁהָלַךְ לָעִיר, אִם הָיָה דַּעְתּוֹ לַחֲזֹר לִמְקוֹמוֹ \u0010g13\u0011 \u0010t4\u0011 בִּזְמַן קְרִיאָה \u0005(שֶׁל י\"ד)\u0006 וְנִתְעַכֵּב וְלֹא חָזַר, קוֹרֵא בִּמְקוֹמוֹ; וְאִם לֹא הָיָה בְּדַעְתּוֹ לַחֲזֹר אֶלָּא לְאַחַר \u0010m6\u0011 זְמַן הַקְּרִיאָה, קוֹרֵא עִם אַנְשֵׁי הַמָּקוֹם שֶׁהוּא שָׁם. \u0005 הַגָּה: \u0010y12\u0011 וְאִם הוּא בַּמִּדְבָּר אוֹ בַּסְּפִינָה, קוֹרֵא בְּיוֹם י\"ד כְּמוֹ רֹב הָעוֹלָם \u0006 \u0005(כָּל בּוֹ)\u0006. \u0010y13\u0011 \u0010g14\u0011 \u0010m7\u0011 \u0010r10\u0011 \u0010r11\u0011 \u0010r12\u0011\nיוֹם חֲמִשָּׁה עָשָׂר שֶׁחָל לִהְיוֹת בְּשַׁבָּת \u0010y14\u0011 \u0010t5\u0011 \u0010m8\u0011 אֵין קוֹרִין \u0010y15\u0011 הַמְּגִלָּה בְּשַׁבָּת, אֶלָּא מַקְדִּימִים לִקְרוֹתָהּ בְּעֶרֶב שַׁבָּת, \u0010g15\u0011 וְגוֹבִים מָעוֹת מַתְּנוֹת עֲנִיִּים וּמְחַלְּקִים אוֹתָם בּוֹ בַּיּוֹם; וּבְיוֹם שַׁבָּת מוֹצִיאִים שְׁנֵי סְפָרִים וּבַשֵּׁנִי קוֹרִין: וַיָּבֹא עֲמָלֵק; \u0010y16\u0011 וְאוֹמְרִים: עַל הַנִּסִים; \u0010y17\u0011 \u0010g16\u0011 \u0010m9\u0011 וְאֵין \u0010t6\u0011 \u0010s1\u0011 עוֹשִׂים סְעֻדַּת פּוּרִים עַד יוֹם אֶחָד \u0010g17\u0011 בְּשַׁבָּת. \u0010r13\u0011 \u0010r14\u0011 \u0010r15\u0011 \u0010r16\u0011 \u0010r17\u0011\nהַמְפָרֵשׁ בַּיָּם וְהַיּוֹצֵא \u0010y18\u0011 בְּשַׁיָּרָא וְאֵינוֹ מוֹצֵא מְגִלָּה לְהוֹלִיךְ עִמּוֹ, \u0010m10\u0011 יִקְרָאֶנָּה \u0010y19\u0011 \u0010c3\u0011 \u0010t7\u0011 בְּי\"ג אוֹ בְּי\"ב אוֹ בְּאֶחָד עָשָׂר, בְּלֹא בְּרָכָה; וְאִם אִי אֶפְשָׁר לְהַמְתִּין עַד יָמִים הַלָּלוּ, \u0010g18\u0011 יֵשׁ אוֹמְרִים שֶׁקּוֹרֵא \u0010y20\u0011 אֲפִלּוּ מִתְּחִלַּת הַחֹדֶשׁ. \u0005 הַגָּה: וְהָכֵי נָהוּג; מִיהוּ אִם נִזְדַּמֵּן לוֹ \u0010y21\u0011 אַחַר כָּךְ מְגִלָּה, חוֹזֵר וְקוֹרֵא אוֹתָהּ \u0010t8\u0011 \u0006 \u0005 בְּיוֹם י\"ד, אֲפִלּוּ קְרָאָהּ תְּחִלָּה בְּיוֹם י\"ג מִכָּל מָקוֹם קָרָא אוֹתָהּ שֶׁלֹּא בִּזְמַנָּהּ \u0006 \u0005(כָּל בּוֹ \u0010g19\u0011 וּבֵית יוֹסֵף)\u0006. \u0010r18\u0011 \u0010r19\u0011 \u0010r20\u0011\nבֶּן עִיר שֶׁהָיָה בַּסְפִינָה אוֹ בַּדֶּרֶךְ וְלֹא הָיָה בְּיָדוֹ מְגִלָּה, וְאַחַר כָּךְ נִזְדַּמְּנָה לוֹ בְּט\"ו, \u0010y22\u0011 \u0010m11\u0011 קוֹרֵא אוֹתָהּ \u0010t9\u0011 בְּט\"ו. \u0010r21\u0011",{"g":["משנה ריש מגילה","ברייתא שם ג","טור וכ\"כ הר\"ן בשם התו' והרמב\"ן ע\"פ הירושלמי ושכן דעת הגאונים","תוס' והרא\"ש שם דריב\"ל אי ירי בלא הוקף מימות יהושע בן נון","מימרא דריב\"ל שם","טור בשם מהר\"מ מרוטנבורג","מימרא דריב\"ל שם וברייתא שם","שם בגמרא ג'","שם בגמרא ג' משמיה דרבא ואמרי לי' כדי","שם במשנה","\u0003רמב\"ם שם מהא דחזקיה קרי בטבריא בי\"ד וט\"ו וכו'\u0004 ","שם","רמב\"ם בפ\"א ממשנ' י\"ט וכאוקימת' דרבא וכפרש\"י שם","ר\"ל בזמן קריאת המקום שהוא בו עתה לא זמן המקום שיצא משם כ\"כ ה\"ה","משנה שם ב'","מצא כתוב בשם מנהג ירו'","\u0003הר\"ן בפ\"ק דמגילה:\u0004 ","טור בשם שדרו ממתיבתא","הגהת אשר\"י בשם א\"ז וכן איתא בירו'","שבלי לקט וע\"פ הירו'"],"t":["\u0003מסתמא. \u0004 האחרונים הקשו דזה הפך ממ\"ש בסי' ת\"א דסתם עיירות מוקפות לדירה שבונין בתים תחיל' ואח\"כ מקיפים אותה ע\"ש מה שתירצו:","\u0003ובלבד וכו'. \u0004 זה קאי אדסמוך וכו' אבל נרא' אפי' רחוק הרב' הוי ככרך. מ\"א ע\"ש. ועיין ט\"ז ובתשו' מהריט\"ץ סימן קפ\"ג:","\u0003ספק. \u0004 וטבריא צריך לקרות בה בי\"ד ובט\"ו שספק אם הים חשוב כחומה גמ'. בח\"ל יש כרכים שראוי להסתפק בהן של\"ה. ובלבוש כתב דבמדינות אלו אין להסתפק לפי שהם בצפון ורחוקים מא\"י וידוע שלא היו מיושבים בזמן יהושע:","\u0003לרוב. \u0004 ונוהגין שמחה ומתנות לאביונים בשניהם. כנה\"ג ש\"ג:","\u0003בזמן קריאה. \u0004 פי' של י\"ד ועיקר קריאה תלוי ביום י\"ד ולא בלילה. מ\"א ועיין ט\"ז:","\u0003אין קורין. \u0004 דאין בקיאין בקריאת הטעמים משא\"כ בס\"ת ודו\"ק ובזה מתורץ קושית התוי\"ט ועיין יד אהרן. ושואלין ודורשין בענינו של יום. גמ':","\u0003סעודת. \u0004 ור\"ל חביב סימן ל\"ב האריך בראיות שהסעוד' היא בשבת ועשה כן מעשה בירושלים וגם משלוח מנות בשבת כי המנות הם מהסעוד' עיין ב\"ח והרדב\"ז ח\"א סי' קמ\"ז פסק כש\"ע וכן דעת המ\"א. ועכ\"פ מתנות לאביונים הוא ביום קריאת המגילה. אבל אסור לטלטל המגילה בשבת פר\"ח ע\"ש ועיין בשכנה\"ג בסימן זה ובסי' ש\"ח בהגהת ב\"י. ודע שאם חל יום ט\"ו בשבת אזי יום השבת ח' לאדר הוא פ' זכור ומפטירין פקדתי ב\"י וב\"ח כתב בשם ר\"ל חביב דבט\"ו לאדר מפטירין ג\"כ פקדתי ע\"ש:","\u0003בי\"ג. \u0004 בקיבוץ י' דשלא בזמנה בעי י' ובהג\"א מסופק אי סגי בקטנים. מ\"צ:","\u0003ביום י\"ד. \u0004 בברכה עיין לבוש:","\u0003בט\"ו. \u0004 בלא ברכה. ב\"י ש\"ל:"],"s":["\u0003ספק עבה\"ט \u0004 וע' בר\"י בשם תשו' הרדב\"ז שכ' שחברון עה\"ק פשיטא דאינה מוקפת מימות יהושע וקורין בי\"ד ע\"ש אבל מנהג קדום לקרות כל הימים מספק:","\u0003סעודת. \u0004 עבה\"ט וע' בנ\"ב ח\"א סי' מ\"ב שהכריע ג\"כ כדברי הרי\"ף וש\"ע שפסקו כהירושלמי ובזה\"ז שמסתכלין בה מאחרין השמחה ליום א' וע' בהשמטות מור וקציעה שהסכים ג\"כ אך כתב דמ\"מ משלוח מנות יהיה בשבת דבר בעתו מה טוב ופרסומי ניסא ע\"ש וצ\"ע:"],"m":["\u0003מימות יהושע בן נון\u0004. תקנו כן כדי לחלק כבוד לא\"י:","\u0003מסתמא הוקפה כו'\u0004. שכן דרך רוב מדינות מקיפין חומה תחלה ואח\"כ מישבין אותן עכ\"ל הר\"ן וקשה דזה הפך ממ\"ש בסי' ת\"א וסתם עיירות מוקפות לדירה וכתב הרא\"ש בשם הר\"מ דאין דרך להקיף מחיצה עד שיבנו הבתים תחלה ע\"כ, ונ\"ל דמשום זה ס\"ל להר\"מ כאן דבעינן ישב תחלה אדעתא שלא להקיפו וכו' כמ\"ש הטור ע\"ש ודעת רמ\"א צ\"ע:","\u0003ובלבד שלא כו'\u0004. מדהיפך לשון הטור ש\"מ דסבירא ליה דהאי ובלבד קאי אדסמוך וכו', אבל נראה אפי' רחוק הרבה הוי ככרך כמ\"ש בב\"י ובמ\"מ:","\u0003שהוא ספק\u0004. וטבריא צריך לקרו' בה בי\"ד ובט\"ו שספק אם הים חשוב כחומ' (גמ'): בח\"ל יש כרכים שראוי להסתפק בהן (של\"ה) ולבוש כת' דמדינות אלו אין להסתפק לפי שהם בצפון ורחוקים מא\"י וידוע שלא היו מיושבים בזמן יהושע:","\u0003קורין בי\"ד ובט\"ו\u0004. ונוהגין שמחה ומתנות לאביונים בשניהם (ש\"ג כ\"ה):","\u0003ולא יברך כו'\u0004. הקשה הב\"ח בשם רש\"ל דיברך בשניהם מידי דהוי אשני י\"ט של גליות וכו' ע\"ש ול\"ד דלק\"מ דדוק' על מצוה שתקנו חכמים לעשות מספק מברכי' אבל מצות שאנו עושים מספק אין מברכין אפי' על ספק דאוריי' כמ\"ש בי\"ד סי' כ\"ח ע\"ש:","\u0003זמן קריאה\u0004. ועיקר קריאה תלוי ביום י\"ד ולא בליל' כמ\"ש סי' תרצ\"ב:","\u0003יום ט\"ו וכו'\u0004. וביום השבת ח' לאדר הוא פ' זכור ומפטירין פקדתי [ב\"י] וב\"ח כ' כשם ר\"ל חביב דבט\"ו לאדר מפטירין ג\"כ פקדתי ע\"ש:","\u0003אין קורין המגילה בשבת\u0004. ושואלין ודורשין בענינו של יום (טור גמ'):","\u0003ואין עושין סעודת פורים כו'\u0004. ור\"ל חביב האריך בראיות שהסעודה היא בשבת ועשה כן מעש' בירושלים וגם משלוח מנות בשבת כי המנו' הם מהסעוד' עכ\"ל ב\"ח ורדב\"ז ח\"א קמ\"ז פסק כש\"ע וכנ\"ל דראיות דרלב\"ח אינן מוכרחות וגם אין בנו כח לחלוק על הירושלמי וע' בגמ' דף ל' ע\"א גבי עשייה וזכירה ועכ\"פ מתנות לאביונים הוא ביום קריאת המגיל' כדאי' בגמ':","\u0003יקראנ' בי\"ג\u0004. בקיבוץ עשרה דשלא בזמנ' בעי' י' ועססי' תר\"ץ ובהג\"א מסופק אי סגי בקטנים (מ\"צ): אם טעו וקראו הפרשיות והמגילה בראשון צריך לחזור ולקרותן בשני (בד\"ה ד\"מ ב\"ח):","\u0003קורא אות' בט\"ו\u0004. בלא ברכה (ב\"י ש\"ל):"],"r":["\u0003ס\"א אפילו אינן כו' ואפי' כו'. \u0004כמ\"ש בירושלמי הטעם שחילקו במוקפין מימות יהושע ב\"נ כדי לחלוק כבוד לא\"י שהיתה חריבה באותן הימים ולא יהיו עיירות המוקפות בח\"ל חשובות מהם וע' ר\"ן:","\u0003ואפי' אם הם בח\"ל. \u0004מדאמרינן לריב\"ק כשושן כו' ומדריב\"ק נשמע לרבנן דהא ל\"פ אלא בזמן. ושם ה' ב' ר\"א קרי בהוצל כו' ואמרינן בפ' בתרא בבבל היכא כו' ובע\"פ הוא יוסף איש הוצל הוא יוסף הבבלי ובסוף כתובות נקטינן בבל כו' תרגומא הוצל. ובירושלמי פ\"ק דמגילה חרב ונעשה של עו\"ג מהו בו אין קורין בחוצה קורין ר\"ל אם בח\"ל קורין אע\"ג שלא היה בו ישראל כ\"ש בא\"י וע' ר\"ן. אבל אין פירושו מכוון וז\"ל הירושלמי שם תני הסמוך לכרך והנראה עמו ה\"ה כיוצא בו ר' אייבו בר גרי כגון הדא חמתא כו' חרב הכרך ונעשה של עובדי גילולים איתא חמי בו אינן קורין ובחוצה לו קורין. ר\"ל אם בחוץ לכרך קורין דהא שם לא מחמת חומה דהא אמרינן בערכין והובא בירושלמי שם כל שהוא לפנים מן החומה כו' וא\"כ אף שבטל החומה קורין כ\"ש בתוכה. ולכאורה מזה ראיה לפי' תוס' דבשל כרכין א\"צ עשרה בטלנים דזה היתה הבעיא שנעשה של עובדי גילולים אבל י\"ל דה\"ל שרובה עובדי גילולים דבטלה קדושת החומה וע' תוס' דכתובות מ\"ה ב' ד\"ה על כו' ואפשר לפרש הירושלמי דהוא לשון פשיטות בו אינן קורין אבל בחוצה לו קורין מדלא נקט להיפך בחוצה לו קודם:","\u0003ואפילו אין בהם. \u0004ממ\"ש שם כרך שישב ולבסוף כו' וע\"כ באין בו עשרה בטלנין מדאמר ככפר. תוס' ס\"ד כרך. והרמב\"ן ורשב\"א חולקים על זה ע\"ש:","\u0003או שישב כו'. \u0004ממ\"ש ה' ב' ולא שור איגר ועתוס' הנ\"ל וא\"ת לקמן כו' ובזה מתורץ קושייתם:","\u0003אבל בסתמא כו'. \u0004ממש\"ש ומי מספקא לי' מילתיה דטבריא כו' ודלמא מספקא ליה אי ישבה ולבסוף הוקפה ושם והא רבי בטבריא הוי כו':","\u0003ס\"ב ובלבד כו'. \u0004הטור כתב אנראה וכן פי' הר\"ן בפי' השני וטעמם משום דמציין הגמרא עד כמה שם ב' ב' קודם שפי' שנראה וסמוך הן ב' דברים אלמא אכולה קאי אבל רש\"י פירש שם אסמוך ונזהר מזה וכת' שם בד\"ה נידון סמוך אף ע\"ג כו' וכן משמע מלשון ש\"ע שהיפך דברי הטור. ועוד למד הטור ממ\"ש מחמתן לטבריא וטבריא בעמק הוא כמ\"ש בפ' ט\"ז דשבת וש\"מ וחמתן בהר כמ\"ש בפ\"ה דעירובין וע\"כ קאי אנראה כמש\"ש ג' ב' ועוד ממש\"ש בשלמא נראה אע\"פ כו' אלא סמוך כו' ולכאורה קשה דקארי ליה מאי קארי ליה אלא דקשיא ליה כיון דאינו סמוך הוא עד מיל ע\"כ סמוך סמוך לעיר מיד ממש והיאך אפשר שאינו נראה אפילו יושבת בשיפוע או בעמק ומשני שיושבת בנחל ר\"ל גיא שוה בעומק שחוט המשקולת יורד כנגדו שאפי' העומד סמוך לה ברחוק ד\"א אינו רואה אותה:","\u0003ס\"ג וכרכים. \u0004שם בגמרא יליף פרזי כו'.","\u0003ס\"ד כרך כו'. \u0004והגאונים הורו שלא יקרא אלא בי\"ד דאזלינן בתר רובא דעלמא ועוד ספק דבריהם לקולא אלא שלא תיבטל ממנו בודאי מקרא מגילה יקרא בי\"ד ופטור מט\"ו. מ\"מ ור\"ן. ור\"ל כיון שבי\"ד יוצא בדיעבד וכמש\"ל שזהו טעמו של הרמב\"ם שכת' ולא יברך כו'. ובמשנה למלך האריך בחנם בזה וכתבו הגאונים אע\"ג דאמרינן דחזקיה קרי כו' מדת חסידות היה ועוד דוקא בא\"י שהיו עריה ידועות בשעת התקנה מחמת בתי ערי חומה כו' וצ\"ל דגרסי' בגמרא הוצל דבית בנימין ועמ\"ש בס\"א:","\u0003ולא יברך. \u0004כ\"כ הגאונים ממ\"ש בפ\"ב דשבת ספק דדבריהם כו'. והנה הרי\"ף בפי\"ט דשבת בשם רב האי גאון והרא\"ש שם וכן הריב\"ש סי' ר\"כ פסקו דאף ספק דאורייתא אין מברכין ופי' הסוגיא דשבת שם ודאי דדבריהם דבר שניתקן מדבריהם מחמת ודאי בעי ברוכי אבל ספק דדבריהם ר\"ל דבר שהם תקנו מחמת ספק כגון דמאי לא בעי ברוכי ורבא פליג דכיון שהם תיקנו אפי' מחמת ספק בעי ברוכי אבל שאר ספק אף בדאורייתא אין מברכין כמ\"ש הרי\"ף ורא\"ש בפי\"ט דשבת גבי מילה ורא\"ש בפרק כיסוי הדם גבי כוי ועיין ר\"י בפ\"ג דברכות ור\"ן בפ\"ב דשבת ופי\"ט שם ורמב\"ם פ\"ו מהלכות סוכה ופ\"ב מה' מילה וחנוכה וראב\"ד ומ\"מ ולח\"מ שם ובפ\"ג מה' מילה וראב\"ד שם וכ\"מ הביא תשובת הרמב\"ם ותורף דבריו כנ\"ל וראייתו ממ\"ש בסוכה פ\"ד מיתב יתבינן ברוכי כו' וכ\"כ בפ\"ו מה' סוכה כנ\"ל והטעם שהברכה אפי' בשל תורה הוא דרבנן כמ\"ש בפ\"ב דברכות ושם פ\"ג ספק קרא כו' כיון שהוא מדרבנן א\"צ וע' ברא\"ש שם בשם בה\"ג. וראב\"ד וחכמי לוניל והר' יונה בפ\"ג דברכות והביא דבריו הרא\"ש בחולין שם ס\"ל מדס\"ל לרבא דוקא משום דרוב כו' הא בכל ספק דאורייתא כגון דמאי מברכין וכן יו\"ט ב' וכן בכל ספק אף שלא מחמת תקנה ושם בק\"ש מפני שהיא עיקרה מדרבנן משא\"כ בברכת המצוה כיון שהמצוה היא מדאורייתא וסוכה שאני דסתרי אהדדי כמ\"ש הרי\"ף שם. אבל בש\"ע פסק כדעת הרי\"ף ורמב\"ם ורא\"ש כמש\"ל סי' י\"ז ובי\"ד סי' כ\"ט וסי' רס\"ה. והרמב\"ם בפ\"ג מהלכות מגילה וחנוכה חזר ממ\"ש בתשובה דרבא פליג אאביי ושם ס\"ל דל\"פ אלא שהוסיף ולכן ס\"ל דאף תקנה מחמת ספק דאורייתא א\"צ ברכה אבל כאן שהספק בשל דבריהם לכל השיטות א\"צ ברכה ומ\"ש הראב\"ד לרבא ספק אחר אף בדרבנן מברכין ר\"ל דבר שתיקנו רבנן על ספק כמ\"ש הוא עצמו בפ\"ו דסוכה ופ\"ג מה' מילה:","\u0003כי אם בי\"ד. \u0004דאף בני כרכים יוצאין בדיעבד בי\"ד כמ\"ש בירושלמי בפ\"ב דמגילה הלכה ג' בן עיר מהו שיוציא בן כרך י\"ח ייבא כהדא כל שאינו מחוייב בדבר כו' בן כרך מהו שיוציא את בן עיר י\"ח ייבא כהדא כו' הכל יוצאין בי\"ד שהיא זמן קריאתה וכן שם פ\"א הלכה א' ה' ד' ולכן מברכין בי\"ד אף לכתחלה כמ\"ש תוס' וש\"פ בברכה שמסופקין אם בפה\"א או בפה\"ע וכמ\"ש בפ\"ו דברכות שקפץ ר\"ע ובירך מעין שלש וא\"ל ר\"ג למה אתה כו':","\u0003ס\"ה בזמן קריאה. \u0004של יום. וע' בה\"ג וכפרש\"י שם ומכאן ראיה לר\"ת וב\"ה בסי' תרצ\"ב ס\"א וי\"א דאף כו' ודלא כהרא\"ש שכת' דהכל תלוי בליל י\"ד ודחקו מדמפ' גמרא דין בן כרך סיפא דמתני' ולא מפרש רישא וכן הרי\"ף מציין בן עיר שהלך לכרך א\"ר ל\"ש כו'. אבל כבר דחאו הר\"ן משום דפרוז בן יומו מפורש בקרא והרי\"ף מציין פסקא דמתנייתן וראיה מדאמרינן בירושלמי שם בן עיר שעקר דירתו ליל ט\"ו נתחייב כאן וכאן וכ\"ש בן כרך וע' ר\"ן:","\u0003ונתעכב. \u0004כפי' הרי\"ף ממ\"ש שעתיד לחזור:","\u0003ואם הוא. \u0004ירושלמי שם מפרשי ימים והולכי מדברות קורין בארבעה עשר:","\u0003ס\"ו יום ט\"ו כו'. \u0004והשמיט מ\"ש שואלין ודורשין כו' דס\"ל דלאו דוקא בשבת אלא לרבותא אבל הרמב\"ם כת' דוקא בשבת וכ\"כ תוס' שם ד\"ה פורים ואשתמיטתיה זה לבעל לח\"מ:","\u0003אלא מקדימין. \u0004כמש\"ש ה' א' כרב:","\u0003וגובים. \u0004שם ד' ב' הואיל כו' שעיניהם כו':","\u0003וביום כו' קורין. \u0004ל' ב' בפורים כו' ושם לכל מפסיקין כו' וע' רש\"י שם ד\"ה הא כדאיתא כו' וקי\"ל כר' ירמיה כמש\"ל סי' תרפ\"ה:","\u0003ואין עושין. \u0004ירושלמי פ\"א וסעודת פורים מאחרין ולא מקדימין ויעשו אותן בשבת לעשות אותו ימי משתה ושמחה כתיב את ששמחתו תלויה בב\"ד יצא זה ששמחתו תלויה בידי שמים. ורילב\"ח הקשה ממ\"ש בפ\"ד ל' א' עשייה וזכירה כו' וע' רש\"י ב' ב' ד\"ה אשכחן כו' ועמ\"א וע' פר\"ח שדחהו. ולי נראה שגירסת הרי\"ף היתה כגירסת הספרים הישנים ר\"א מקדימין כי היכי דתקדום זכירה לעשייה ושמואל כו' בחמיסר קדמי זכירה לעשייה וערש\"י שם ד\"ה ה\"ג כו':","\u0003ס\"ז המפרש כו'. \u0004ז\"ל הרז\"ה פ\"א תניא בברייתא המפרש והיוצא לדרך קורין בי\"ג כו' וה\"ה לי\"ב וי\"א וכדאי ר\"ע לסמוך עליו בשעת הדחק ובירושלמי מפרשי ימים והולכי כו' כנ\"ל ס\"ה הא דאפשר הא דלא אפשר וכ\"כ מרדכי והג\"מ:","\u0003ואם א\"א כו'. \u0004ירושלמי כל החודש כשר לקריאת מגילה מ\"ט והחדש אשר נהפך כו' ובלבד עד ט\"ו ולא יעבור כתיב. מרדכי והג\"מ:","\u0003ומיהו אם. \u0004גמרא י\"ט א' בן כפר שהלך כו':","\u0003ס\"ח בן עיר. \u0004ירושלמי הנ\"ל כל החדש כו' ובלבד עד ט\"ו ומשמע אף לבן עיר:"]}],["הַכֹּל חַיָּבִים בִּקְרִיאָתָהּ, אֲנָשִׁים \u0010y0\u0011 וְנָשִׂים \u0010c0\u0011 וְגֵרִים וַעֲבָדִים \u0010y1\u0011 \u0010c1\u0011 מְשֻׁחְרָרִים; וּמְחַנְּכִים \u0010y2\u0011 אֶת הַקְּטַנִּים לִקְרוֹתָהּ. \u0010c2\u0011\nאֶחָד הַקּוֹרֵא וְאֶחָד הַשּׁוֹמֵעַ מִן הַקּוֹרֵא, \u0010y3\u0011 יָצָא יְדֵי חוֹבָתוֹ; וְהוּא שֶׁיִּשְׁמַע מִפִּי שֶׁהוּא חַיָּב בִּקְרִיאָתָהּ. לְפִיכָךְ אִם הָיָה הַקּוֹרֵא \u0010y4\u0011 חֵרֵשׁ \u0010y5\u0011 \u0010c3\u0011 אוֹ קָטָן אוֹ שׁוֹטֶה, הַשּׁוֹמֵעַ מִמֶּנּוּ לֹא יָצָא; \u0010y6\u0011 וְיֵשׁ אוֹמְרִים שֶׁהַנָּשִׁים אֵינָם מוֹצִיאוֹת אֶת הָאֲנָשִׁים. \u0005 הַגָּה: \u0010y7\u0011 וְיֵשׁ אוֹמְרִים אִם הָאִשָּׁה קוֹרְאָהּ \u0006 \u0005 לְעַצְמָהּ מְבָרֶכֶת: לִשְׁמֹעַ מְגִלָּה, שֶׁאֵינָהּ חַיֶּבֶת בִּקְרִיאָה \u0006 \u0005(מָרְדְּכַי פ\"ק \u0010y8\u0011 דִּמְגִלָּה)\u0006.\nאַנְדְּרוֹגִינוּס \u0010y9\u0011 מוֹצִיא מִינוֹ \u0010y10\u0011 וְלֹא שֶׁאֵינוֹ מִינוֹ, \u0010y11\u0011 טֻמְטוּם וּמִי שֶׁחֶצְיוֹ עֶבֶד אֲפִלּוּ מִינוֹ אֵינוֹ מוֹצִיא. \u0005 הַגָּה: \u0010y12\u0011 יֵשׁ אוֹמְרִים דְּאֲפִלּוּ אֶת \u0006 \u0005 עַצְמוֹ אֵינוֹ מוֹצִיא וְצָרִיךְ לִשְׁמֹעַ מֵאֲחֵרִים \u0006 \u0005(בֵּית יוֹסֵף)\u0006.\nהַשּׁוֹמֵעַ מְגִלָּה מִמִּי שֶׁהוּא מֻדָּר הֲנָאָה מִמֶּנּוּ, \u0010y13\u0011 יָצָא.\nמָקוֹם שֶׁאֵין מִנְיָן, \u0010c4\u0011 אִם אֶחָד יוֹדֵעַ וְהָאֲחֵרִים אֵינָם יוֹדְעִים אֶחָד פּוֹטֵר אֶת כֻּלָּם; וְאִם כֻּלָּם יוֹדְעִים, כָּל אֶחָד קוֹרֵא \u0010y14\u0011 לְעַצְמוֹ. \u0010y15\u0011\nמִנְהָג טוֹב לְהָבִיא \u0010y16\u0011 \u0010c5\u0011 קְטַנִּים וּקְטַנּוֹת \u0010y17\u0011 \u0010y18\u0011 לִשְׁמֹעַ מִקְרָא מְגִלָּה.",["\u0003ונשים\u0004 ואף דהקריאה היא דבר שהזמן גרמא מ\"מ חייבות שאף הן היו באותו הנס דמתחלה היתה הגזירה גם עליהם כדכתיב בקרא. ולכן צריך האיש לקרותה בביתו לפני הבתולות והמשרתות ובקצת מקומות נוהגין שהם הולכות לביהכ\"נ לעזרת נשים לשמוע הקריאה אכן צ\"ע איך יוצאין שם נשים דא\"א לשמוע שם כדין:","\u0003משוחררים\u0004 אבל אינם משוחררים פטורים דגריעי מנשים לענין זה וי\"א דאפי' אינם משוחררים חייבים:","\u0003את הקטנים\u0004 היינו מי שהגיע למצות חינוך ועיין לקמן בס\"ו. וכיון דגם נשים חייבות פשוט דגם בקטנות יש בהן משום מצות חינוך וע\"ל בס\"ו:","\u0003יצא ידי חבותו\u0004 וצריך שיכוין הקורא להוציא והשומע לצאת כדין שארי מצות שאחד מוציא חבירו וכדלקמן בסי' תר\"צ סי\"ד:","\u0003חרש\u0004 היינו המדבר ואינו שומע כלל ואע\"ג דבעלמא קי\"ל דאם לא השמיע לאזנו יצא כדלעיל בסימן ס\"ב וסימן קפ\"ה הכא לענין מגילה דהוא משום פרסומי ניסא החמירו בו יותר דהשמיעה לאזנו הוא לעיכובא א\"נ דחרש גרע טפי שאינו יכול להשמיע לאזנו ועיין בשע\"ת דדוקא אם הוא חרש גמור שאינו שומע כלל לאפוקי אם הוא שומע כשמדברים לו בקול רם. וכ\"ז הוא לדעת השו\"ע אבל דעת כמה אחרונים דאפילו הוא חרש גמור יצא השומע ממנו ומ\"מ לכתחלה כו\"ע מודים שלא יעמידוהו להוציא רבים י\"ח. ודע דמי שכבדו אזניו או שהוא רחוק מן הבימה ואינו יכול לשמוע היטיב מן הקורא יזהר לקרות לעצמו ממגילה כשרה או עכ\"פ יאחוז חומש והתיבות שיחסר לו יאמר תיכף מן החומש:","\u0003או קטן\u0004 אע\"ג דקטן נמי חייב עכ\"פ מדרבנן כדלעיל בס\"א אפ\"ה אינו יכול להוציא את הגדול דלגבי קטן הוי תרי דרבנן (ר\"ל דעצם קריאת המגילה הוי רק מד\"ס וחיובו של קטן הוי ג\"כ רק מדרבנן בכל המצות) משא\"כ גדול הוי חד דרבנן ולא אתי תרי דרבנן ומפיק חד דרבנן. והנה לעיל בסימן תרע\"ה ס\"ג הביא המחבר דיש מי שמכשיר בקטן שהגיע לחינוך שיכול להוציא אחרים בהדלקתו וה\"ה לענין קריאת המגילה ועיין בעקרי דינים שכתב בשם סמא דחיי דבמקום הדחק כשאין שם אנשים בקיאים במקרא מגילה יכול להוציאם קטן שהגיע לחינוך:","\u0003וי\"א שהנשים אינם מוציאות וכו'\u0004 ולא דמי לנר חנוכה דשאני מגילה דהוי כמו קריאת התורה ופסולה מפני כבוד הצבור ולכן אפילו ליחיד אינה מוציאה משום לא פלוג וגם דאפשר דאשה אינה חייבת בקריאה רק לשמוע וכדלקמיה ומקרי שאינה מחוייבת בדבר לגבי איש אבל אשה מוציאה את חברתה:","\u0003אם האשה קראה וכו'\u0004 ועיין במ\"א שמצדד דלא תקרא לעצמה כלל רק תשמע מהאנשים. וכ\"ז ביש לה ממי לשמוע אבל אם אין לה מי שיקרא לפניה תקרא היא לעצמה במגילה כשרה ומברכת אקב\"ו לשמוע מקרא מגילה [ח\"א]:","\u0003אנדרוגינוס\u0004 יש לו זכרות ונקבות:","\u0003מוציא מינו\u0004 דאם זה זכר גם זה זכר ואם זו נקבה גם זו נקבה ואם נסבור דהוא בריה בפני עצמו גם השני בריה בפני עצמו הוא:","\u0003ולא שאינו מינו\u0004 דשמא זה נקבה והשני הוא זכר ואפילו למ\"ד דנשים מוציאות האנשים זה גרע טפי דבעינן שהמוציא את אחרים יהיה ניכר אם הוא איש או אשה:","\u0003טומטום וכו' אפילו מינו אינו מוציא\u0004 דשמא זה זכר וזה נקבה [משא\"כ אנדרוגינוס כולן שוין במינן] וכן מי שחציו עבד לא אתי צד עבדות דידיה ומפיק להאחר שיש בו צד חירות:","\u0003י\"א דאפילו א\"ע וכו'\u0004 זה לא קאי אטומטום רק אחציו עבד וחציו בן חורין ומשום דלא אתי צד עבדות דידיה ומפיק צד חירות דידיה וכ\"ז דוקא לדעה הסוברת דנשים אין מוציאות האנשים ועבד דומה לאשה:","\u0003יצא\u0004 דמצות לאו ליהנות ניתנו ולא מקרי הנאה ועיין לעיל סימן תקפ\"ט ס\"ז דשייך לענינינו:","\u0003לעצמו\u0004 דאין היחיד מוציא חבירו אלא בעשרה ולא דמי לשופר דקריאת המגילה הוי כמו תפלה דבעינן עשרה דוקא. והנה הפר\"ח כתב דכ\"ז הוא רק לענין לכתחלה אבל בדיעבד אם נתכוין לפטור חבירו יצאו אע\"פ שכולם יודעים ובמ\"א מצדד עוד דאפילו לכתחלה עדיף שיקרא אחד לכולן משום ברוב עם הדרת מלך אמנם בא\"ר ובמטה יהודא דעתם כהשו\"ע דכל אחד יקרא לעצמו וכן העתיק בדה\"ח:","\u0003מנהג טוב להביא וכו'\u0004 כדי לחנכם במצות פרסומי ניסא ומטעם זה נוהגין הקהל לקרות אלו הפסוקים בקול רם [כדלקמן בסימן תר\"צ סי\"ז] שהם עיקר התחלת הנס וסופו והם איש יהודי. ומרדכי יצא. ליהודים. כי מרדכי. כדי לעורר הקטנים שלא יישנו ויתנו לבם על הקריאה ומקרין אותם הפסוקים כדי לחנכם [לבוש]:","\u0003קטנים וקטנות\u0004 ובלבד שלא יביאו קטנים ביותר שמבלבלין דעת השומעים [מ\"א וש\"א]:","\u0003לשמוע וכו'\u0004 ועכשיו בעו\"ה נהפוך הוא שלבד שאינם שומעים אלא הם מבלבלים שגם הגדולים אינם יכולים לשמוע וכל ביאתם הוא רק להכות את המן ובזה אין האב מקיים מצות חינוך כלל ובאמת מצד מצות חינוך צריך כל אב להחזיק בניו הקטנים אצלו ולהשגיח עליהם שישמעו הקריאה וכשיגיע הקורא לזכור שם המן האגגי רשאי הקטן להכותו כמנהגו אבל לא שיהיה זה עיקר הבאת הקטן לביה\"מ:","\u0003מקרא מגילה\u0004 ועכשיו ראוי לכל אחד שיהיה לו מגילה כשרה ולקרוא בלחש מלה במלה דא\"א לשמוע מהש\"ץ מחמת רעש ובלבול שמכים בעצים ומשמיעים קול וראוי לכל ישראל לנהוג כן מי שהיכולת בידו [פמ\"ג] ועיין לקמן בסימן תר\"צ ס\"ד:"],["\u0003 ונשים\u0004 - לכאורה אם היא כבר יצאה י\"ח אין מוציאה לאשה אחרת וה\"ה קטן לאשה או לקטן אחר (שנסתפק בזה אם הם בכלל ערבות דלימא בהו ג\"כ אע\"פ שיצא מוציא) [אשל אברהם]:","\u0003 ועבדים\u0004 - עיין מ\"ב די\"א דאפילו אינם משוחררים חייבין והוא ממ\"א ואף דהגר\"א דחה דבריו היינו רק בדעת הרמב\"ם וסמ\"ג אבל בבה\"ג הלא מבואר להדיא דגם עבדים חייבין וכן העתיקו בשמו בתוס' ערכין אלא דאין חייבין רק בשמיעה ולא בקריאה ודע דלהוציא אחרים בודאי אין יכולים לכו\"ע דלדעת בה\"ג הלא גבי נשים אין מוציאות אחרי' וכדלקמיה וה\"ה גבי עבדים דדין אחד להם ולדעת הגר\"א ורא\"מ בפירוש הרמב\"ם והסמ\"ג הלא פטורין לגמרי:","\u0003 את הקטנים לקרותה\u0004 - וגם בשמיעה יצאו וכדלקמיה בס\"ו:","\u0003 חרש\u0004 - מלשון השו\"ע משמע דאינו בר חיוב כלל אף לקרות לעצמו אכן מסברתו בב\"י שכתב דמשום פרסומי ניסא הוא משמע לכאורה דהוא רק לענין להוציא אחרים שהם פקחין צריכין לשמוע מאיש ששומע באזניו דוקא עי\"ש משום דהלא אותן אחרים יכולין לקרות לעצמן או להשתדל שיוציאן איש אחר שיש לו חוש השמיעה כמותו אבל לא לפוטרו לגמרי מקריאה עכ\"פ [והלא אף דבעלמא שנשים פטורות ממ\"ע שהזמן גרמא הכא חייבו אותן מפני שאף הן היו באותו הנס ואף חרשין היו באותו הנס ולא גרע מהן] ויש בזה אריכות דברים ואכ\"מ להאריך. אכן לדינא אין נ\"מ דבלא\"ה הלא דעת כמה ראשונים הרשב\"א והריא\"ז והרשב\"ץ שגם לאחרים הוא מוציא וכ\"ש שהוא בעצמו בר חיובא וגם ברמב\"ם יש חלופי גרסאות וכן הסכימו כמה אחרונים כמ\"ש במ\"ב וע\"כ חרש לעצמו בודאי מחויב לקרות בעצמו כיון שאינו שומע ואף אם יקראנו בלא טעמים ג\"כ אין קפידא. ולשון ריא\"ז קשה קצת שכתב דיכול לקרות לכתחלה לעצמו מאי לשון יכול בזה דהלא לכאורה מחוייב לעשות כן:","\u0003 מקום שאין מנין\u0004 - דבמקום שיש מנין מחוייב לחזור אחר מנין כדלקמן בסימן תר\"צ סי\"ח:","\u0003 מנהג טוב להביא וכו'\u0004 - הנה בודאי כונת המחבר הוא דוקא על קטנים שהגיעו לחינוך דהקטנים ביותר רק מבלבלין כמו שכתב המגן אברהם וא\"כ מאי שייך מנהג טוב הלא מדינא מחוייב לחנכם בקריאת המגילה או עכ\"פ בשמיעה וכנ\"ל ואולי דבזה היה יוצא אם היה קורא לפניהם בביתם אבל כדי לפרסם הנס ביותר מנהג להביאם בביהמ\"ד שישמעו בצבור כדי לחנכם שגם בגדלותם ישמעו בצבור:"],"\u0010g0\u0011 הַכֹּל חַיָּבִים בִּקְרִיאָתָהּ, אֲנָשִׁים \u0010y0\u0011 \u0010t0\u0011 \u0010m0\u0011 וְנָשִׂים \u0010c0\u0011 וְגֵרִים \u0010m1\u0011 וַעֲבָדִים \u0010y1\u0011 \u0010c1\u0011 \u0010g1\u0011 מְשֻׁחְרָרִים; וּמְחַנְּכִים \u0010y2\u0011 אֶת הַקְּטַנִּים לִקְרוֹתָהּ. \u0010c2\u0011 \u0010g2\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011\nאֶחָד הַקּוֹרֵא וְאֶחָד הַשּׁוֹמֵעַ מִן הַקּוֹרֵא, \u0010y3\u0011 יָצָא יְדֵי חוֹבָתוֹ; וְהוּא שֶׁיִּשְׁמַע מִפִּי שֶׁהוּא חַיָּב בִּקְרִיאָתָהּ. לְפִיכָךְ אִם הָיָה הַקּוֹרֵא \u0010y4\u0011 \u0010g3\u0011 \u0010m2\u0011 חֵרֵשׁ \u0010y5\u0011 \u0010c3\u0011 אוֹ \u0010g4\u0011 \u0010m3\u0011 קָטָן אוֹ שׁוֹטֶה, הַשּׁוֹמֵעַ מִמֶּנּוּ \u0010t1\u0011 \u0010s0\u0011 \u0010s1\u0011 לֹא יָצָא; \u0010y6\u0011 \u0010g5\u0011 וְיֵשׁ אוֹמְרִים שֶׁהַנָּשִׁים \u0010m4\u0011 אֵינָם מוֹצִיאוֹת אֶת הָאֲנָשִׁים. \u0005 הַגָּה: \u0010y7\u0011 \u0010m5\u0011 וְיֵשׁ אוֹמְרִים אִם הָאִשָּׁה קוֹרְאָהּ \u0010t2\u0011 \u0006 \u0005 לְעַצְמָהּ מְבָרֶכֶת: \u0010m6\u0011 לִשְׁמֹעַ מְגִלָּה, שֶׁאֵינָהּ חַיֶּבֶת בִּקְרִיאָה \u0006 \u0005(מָרְדְּכַי פ\"ק \u0010y8\u0011 \u0010g6\u0011 דִּמְגִלָּה)\u0006. \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011\nאַנְדְּרוֹגִינוּס \u0010y9\u0011 מוֹצִיא מִינוֹ \u0010y10\u0011 וְלֹא שֶׁאֵינוֹ מִינוֹ, \u0010y11\u0011 טֻמְטוּם וּמִי שֶׁחֶצְיוֹ עֶבֶד \u0010m7\u0011 אֲפִלּוּ מִינוֹ \u0010t3\u0011 אֵינוֹ מוֹצִיא. \u0005 הַגָּה: \u0010y12\u0011 יֵשׁ אוֹמְרִים דְּאֲפִלּוּ אֶת \u0010t4\u0011 \u0010m8\u0011 \u0006 \u0005 עַצְמוֹ אֵינוֹ מוֹצִיא וְצָרִיךְ לִשְׁמֹעַ מֵאֲחֵרִים \u0010g7\u0011 \u0006 \u0005(בֵּית יוֹסֵף)\u0006. \u0010r7\u0011 \u0010r8\u0011\nהַשּׁוֹמֵעַ מְגִלָּה מִמִּי שֶׁהוּא מֻדָּר הֲנָאָה מִמֶּנּוּ, \u0010y13\u0011 יָצָא. \u0010g8\u0011 \u0010r9\u0011\nמָקוֹם שֶׁאֵין מִנְיָן, \u0010c4\u0011 אִם אֶחָד יוֹדֵעַ וְהָאֲחֵרִים אֵינָם יוֹדְעִים אֶחָד פּוֹטֵר אֶת כֻּלָּם; וְאִם כֻּלָּם יוֹדְעִים, כָּל אֶחָד \u0010m9\u0011 קוֹרֵא \u0010y14\u0011 \u0010t5\u0011 לְעַצְמוֹ. \u0010y15\u0011 \u0010g9\u0011 \u0010r10\u0011\nמִנְהָג טוֹב \u0010m10\u0011 לְהָבִיא \u0010y16\u0011 \u0010c5\u0011 \u0010t6\u0011 קְטַנִּים וּקְטַנּוֹת \u0010y17\u0011 \u0010y18\u0011 לִשְׁמֹעַ מִקְרָא מְגִלָּה. \u0010r11\u0011",{"g":["בריי' בריש ערכין ב'","רמב\"ם בפ\"א","משנה י\"ט","שם וכדעת הרי\"ף ורא\"ש וכן הוא בקצת נוסחאות ספרי רמב\"ם וע' בכ\"מ שם וב\"י","שם וכת\"ק אבל נשים מוציאות לאנשים טור בשם רש\"י ערכין","\u0003שם בשם בה\"ג וכ\"כ המרדכי בשם וראבי\"ה:\u0004 ","תוספתא כתבה הרא\"ש בפ\"ק דמגילה","א\"ח","שם","\u0003טור בשם הירושלמי:\u0004 "],"t":["\u0003ונשים. \u0004 ולכן צריך לקרותה בביתו לפני הבתולות מגן אברהם. ובקצת מקומות נוהגים שהבתולות הולכות לבה\"כ נשים לשמוע המגילה. וקטן שהגיע לחינוך מוציא נשים. וקטן לקטן ואשה לאשה. א\"ז עיין יד אהרן:","\u0003לא יצא. \u0004 וב\"ח פסק דהשומע מן החרש יצא בדיעבד וכ\"מ בגמרא:","\u0003לעצמה. \u0004 ובמדרש הנעלם רות כתב דלא תקרא לעצמה רק תשמע מהאנשים:","\u0003אינו מוציא. \u0004 אפילו למ\"ד דנשים מוציאות אנשים זה גרע טפי עיין ב\"י:","\u0003עצמו אינו מוציא. \u0004 היינו למ\"ד דנשים אין מוציאות אנשים ב\"י והבאר היטב אשר לפני לא דק בכאן ע\"ש:","\u0003לעצמו. \u0004 והב\"ח כתב בשם מהרי\"ל בפשיטות דעדיף טפי שיקרא אחד לכולם וכן דעת המ\"א משום ברוב עם הדרת מלך עיין שם:","\u0003קטנים. \u0004 ובלבד שלא יביאו קטנים ביותר שמבלבלים דעת השומעים. מ\"א עשל\"ה:"],"s":["\u0003ונשים. \u0004 עבה\"ט וע' במח\"ב שיש נוהגים לומר לאשה שתברך הברכה ואח\"כ יקרא לה להוציאה ואין לעשות כן אלא הקורא יברך ע\"ש:","\u0003לא יצא. \u0004 עבה\"ט וע' בשבו\"י ח\"ג סי' ל\"ג שכ' שם שקשה להקל כהב\"ח נגד משמעות הראשונים וע\"ש שכ' בא' שכבדו אזניו משמוע אא\"כ שצועקים מאוד בקול רם אז שומע וקרא המגילה לפני הציבור בקול בינוני שנראה שהוא עצמו לא השמיע לאזנו אעפ\"כ יצאו הציבור בקריאה זו דחרש גמור לא הוי כיון ששומע אם צועקים כמ\"ש הרא\"ש בתשו' כלל פ\"ה סי' י\"ב ובסימנים שם ובפר\"ח ה' גיטין סי' קכ\"א כ' דאף שאינו שומע רק כשמדברים עמו בקול רם ע\"י מין חצוצרות וכיוצא בזה מ\"מ לא מיקרי חרש וגם אין לחוש בשביל שלא השמיע לאזנו משום דמוכח מסתירת הפוסקים מק\"ש למגילה כמבואר בב\"י דיש חילוק בין לא השמיע לאזנו לחרש (ומ\"ש הב\"י והב\"ח דחוק מאוד) ונראה דדוקא חרש שאין ראוי להשמיע לאזנו וכיון ששמע מפי שהוא אינו חייב בקריאה לא יצא משא\"כ זה שיכול לשמוע ע\"י קול רם וחייב בקריאתה גם השומעים ממנו בקול בינוני יצאו ע\"ש. ונראה דהוא עצמו י\"ל ג\"כ דיצא אע\"ג דלא השמיע לאזנו דהא מ\"מ בר קריאה הוא וכיון שהוא עצמו הקורא יצא י\"ח בקריאה אע\"פ שלא השמיע לאזנו כמו בק\"ש דקרא ולא השמיע יצא וקריאה כשמיעת אחרים ממנו דמי ואע\"ג דאחרים שמעו והוא לא שמע מ\"מ יצא בקריאה שקרא לעצמו וע' לעיל סי' ס\"ב:"],"m":["\u0003ונשים\u0004. ולכן צריך לקרותו בביתו לפני הבתולות:","\u0003ועבדי'\u0004. [בב\"י] משמע אפי' אין משוחררים:","\u0003חרש\u0004. וב\"ח פסק דהשומע מן החרש יצא בדיעבד וכ\"מ במג':","\u0003קטן\u0004. אף על גב דגדול נמי אינו חייב אלא דרבנן ול\"ד למ\"ש ססי' קפ\"ז דהתם יכול הקטן לאכול כדי שבעו להביא עצמו לידי חיוב דרבנן (הרא\"מ) וצ\"ע דהרב\"י פסק בססי' תרע\"ה כדעת ב\"ה שמכשיר בקטן והכא סתם ופסק כדעת האוסרים ודוחק לחלק בזה בין מגיל' לנ\"ח וגם בר\"ן שם משמע דדמי להדדי בזה עמ\"ש בסמוך:","\u0003אינם מוציאות\u0004. ול\"ד לנ\"ח דשאני מגיל' דהוי כמו קריאת התור' (סמ\"ג) פי' ופסול' מפני כבוד הצבור ולכן אפי' ליחיד אין מוציא' דלא פלוג (רא\"ם) עמ\"ש סי' ער\"א:","\u0003אם האשה קורא'\u0004. ובמדרש הנעלם רות כ' דלא תקרא לעצמ' רק תשמע מהאנשים:","\u0003שאינה חייבת\u0004. דס\"ל כמ\"ד שאין מוציאות אנשים (כ\"מ במרדכי):","\u0003מינו אינו מוציא\u0004. אפילו למ\"ד דנשים מוציאות אנשים זה גרע טפי עב\"י:","\u0003עצמו אינו מוציא\u0004. היינו למ\"ד דנשים אין מוציאות אנשים (ב\"י):","\u0003קורא לעצמו\u0004. משמע דס\"ל דאין היחיד מוציא חבירו אלא בי' וצ\"ל דלא דמי לשופר דקריאת המגילה הוי כמו תפלה דבעינן י' אבל ברי\"ו ני\"ג משמע דאפי' יחיד מוציא חבירו במגילה אף על פי שהוא בקי ע\"ש ח\"ג וכ\"כ האבודרהם וכ\"כ הב\"ח ססי' תר\"צ בפשיטו' בשם מהרי\"ל וא\"כ עדיף שיקרא א' לכולן משום ברוב עם הדרת מלך כמ\"ש סי' צ\"ח סי\"ד ובתשב\"ץ כ' כל א' קורא לעצמו אם ירצו עכ\"ל סי' ר\"כ:","\u0003להביא קטנים\u0004. ובלבד שלא יביאו קטנים ביותר שמבלבלים דעת השומעים:"],"r":["\u0003ס\"א וגרים ועבדים. \u0004תוספתא בפ\"ב דמגילה. ובנוסחא שלנו נשמט גרים וט\"ס הוא וע' בסוף פ\"ג דר\"ה כ\"ט א' לעניין שופר:","\u0003משוחררים. \u0004רמב\"ם. אע\"ג דס\"ל דנשים חייבים ומוציאין משום שהיו באותו הנס משא\"כ עבדים פטורים שלא היו כו' ול\"ד לנשים כאן דלא כטור ומ\"א:","\u0003ומחנכים כו'. \u0004ירושלמי פ\"ב בר קפרא אומר צריך לקרותה לפני אנשים ונשים וקטנים שאף הן היו באותו הנס ריב\"ל עביד כן מכנש בניו וב\"ב וקרי לה קומיהון. והביאו הג\"מ וש\"פ ואינו אלא חינוך כמו בכל מצות ועתוס' י\"ט ב' ד\"ה ור\"י מכשיר קשה כו' וי\"ל כו':","\u0003ס\"ב חרש. \u0004בנוסחת הכל בו לא כ' חרש ברמב\"ם וכן בנוסחא שלפנינו וכן בא\"ח ועמ\"א וכ\"ה בירושלמי שם א\"ר מתנא דר' יוסי היא כו' ר\"ח אמר לית כאן חרש באשגרת לישנא היא מתנייא:","\u0003וי\"א שהנשים. \u0004תוספתא שם נשים ועבדים וקטנים פטורים ואין מוציאין את הרבים ידי חובתן וכתבה בה\"ג. ומ\"ש במגילה ד' א' נשים חייבות כו' היינו לשמוע וגי' במשמע מגילה כמ\"ש במרדכי והביא ראיה מירושלמי הנ\"ל צריך לקרותה בפני כו'. ושם בירושלמי הנ\"ל ריב\"ל עבד כן מכניש ב\"ב וקרי כו' ועבתוס' ערכין שם ומגילה שם. וסברא ראשונה ס\"ל דההיא תוספתא לאו דסמכא היא דגמרא פליג על התוספתא שהרי רישא הכל חייבין אמרינן בגמ' דאתי לאתויי נשים והיאך תני בסיפא פטורין והא ע\"כ דומיא דרישא היא:","\u0003אין מוציאות. \u0004תוספתא הנ\"ל ואין מיציאות כו' כנ\"ל ומ\"ש בערכין הכל כשרין כו' לאתויי נשים ר\"ל להוציא נשים. וכ\"כ בז\"ח רות ס\"ח ב' וא\"ר אבא נשים חייבות במקרא מגילה אבל הן אינן קוראות לאחרים אבל חייבות לשמוע מפי המברך כו':","\u0003וי\"א. \u0004כגי' בה\"ג במשמע מגילה ומתוספתא וירושלמיי הנ\"ל:","\u0003ס\"ג אנדרוגינוס. \u0004תוספתא שם. והרמב\"ם השמיטו דאזיל לשיטתו דס\"ל לית הלכתא כתוספתא מאחר שאפי' נשים מוציאין אנשים י\"ח וכ\"כ הכל בו וכ\"כ תוס' ד' א' דלא כב\"י ומ\"א אבל מה שהשמיט הרמב\"ם חציו עבד צ\"ע לפי מ\"ש משוחררין:","\u0003י\"א. \u0004כמ\"ש בר\"ה כ\"ט א' מ\"ש לאחרים כו':","\u0003ס\"ד השומע. \u0004כמש\"ש כ\"ח א':","\u0003ס\"ה מקום. \u0004ס\"ל כרב אשי ה' א' וס\"ל דלעיכובא אלא דא\"כ אין הלכה כר\"א מהא דר\"י דפ\"ב וע' ס\"ס תר\"ץ. והוי זה כמ\"ש בסוף ר\"ה יחיד שלא בירך אין חבירו כו' וע\"ש בר\"ן וכ' שם ומיהו ה\"מ בשיודע אבל בשאינו יודע חבירו מוציאו דהא שלשה דברים מוציא בירושלמי מן הכלל ק\"ש ותפלה ובה\"מ ואמרינן בברכות פ\"ז שנים שאכלו כו' אבל אחד סופר כו':","\u0003ס\"ו ירושלמי. \u0004הנ\"ל:"]}],["קוֹרֵא אָדָם אֶת הַמְּגִלָּה בֵּין עוֹמֵד \u0010y0\u0011 בֵּין יוֹשֵׁב; \u0010y1\u0011 אֲבָל לֹא יִקְרָא בְּצִבּוּר, \u0010c0\u0011 יוֹשֵׁב, לְכַתְּחִלָּה מִפְּנֵי כְּבוֹד הַצִּבּוּר. \u0005 הַגָּה: \u0010y2\u0011 וְאָסוּר לַחַזָּן לִקְרוֹת אֶת הַמְּגִלָּה עַד \u0006 \u0005 שֶׁאוֹמְרִים לוֹ: קְרָא, \u0006 \u0005(מָרְדְּכַי פֶּרֶק הַקוֹרֵא)\u0006.\nאֲפִלּוּ שְׁנַיִם, וַאֲפִלּוּ עֲשָׂרָה, יְכוֹלִים לִקְרוֹתָהּ בְּיַחַד \u0010y3\u0011 וְיוֹצְאִים הֵם וְהַשּׁוֹמְעִים מֵהֶם. \u0010y4\u0011\nצָרִיךְ לִקְרוֹתָהּ \u0010y5\u0011 כֻּלָּהּ, וּמִתּוֹךְ הַכְּתָב; וְאִם קְרָאָהּ עַל פֶּה, לֹא יָצָא. \u0010y6\u0011 וְצָרִיךְ שֶׁתְּהֵא כְּתוּבָה כֻּלָּהּ לְפָנָיו לְכַתְּחִלָּה, \u0010y7\u0011 אֲבָל בְּדִיעֲבַד אִם הִשְׁמִיט הַסוֹפֵר בְּאֶמְצָעָהּ \u0010y8\u0011 תֵּבוֹת, אֲפִלּוּ עַד חֶצְיָהּ, וּקְרָאָם הַקּוֹרֵא עַל פֶּה, יָצָא. \u0005 הַגָּה: \u0010y9\u0011 אֲבָל אִם הִשְׁמִיט תְּחִלָּתָהּ \u0010c1\u0011 אוֹ סוֹפָהּ, \u0010y10\u0011 אֲפִלּוּ מִעוּטָהּ, לֹא יָצָא \u0006 \u0005(רַ\"ן)\u0006; \u0010y11\u0011 \u0005 וַאֲפִלּוּ בְּאֶמְצָעָהּ דַּוְקָא דְּלֹא הִשְׁמִיט עִנְיָן \u0010c2\u0011 שָׁלֵם, \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח)\u0006; אֲבָל בְּיוֹתֵר מֵחֶצְיָהּ, אֲפִלּוּ הֵן כְּתוּבוֹת, אֶלָּא שֶׁהֵן \u0010c3\u0011 מְטֻשְׁטָשׁוֹת וְאֵין רִשּׁוּמָן נִכָּר, פְּסוּלָה.\nמִי שֶׁתּוֹפֵס בְּיָדוֹ מְגִלָּה שֶׁאֵינָהּ \u0010y12\u0011 כְּשֵׁרָה, לֹא יִקְרָא עִם שְׁלִיחַ צִבּוּר, אֶלָּא שׁוֹמֵעַ וְשׁוֹתֵק. \u0005 הַגָּה: \u0010y13\u0011 וְכֵן לֹא יְסַיֵּע שׁוּם אָדָם עַל פֶּה לַחַזָּן, \u0010y14\u0011 וְלָכֵן אוֹתָן הַפְּסוּקִים שֶׁקּוֹרִין הַקָּהָל \u0010y15\u0011 צָרִיךְ הַחַזָּן לַחֲזֹר וְלִקְרוֹתָם מִתּוֹךְ מְגִלָּה כְּשֵׁרָה. \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם שִׁבּוֹלֵי לֶקֶט)\u0006.\nקְרָאָהּ סֵרוּגִין, דְּהַיְנוּ שֶׁפָּסַק בָּהּ וְשָׁהָה וְאַחַר כָּךְ חָזַר לַמָּקוֹם שֶׁפָּסַק, \u0010y16\u0011 אֲפִלּוּ שָׁהָה כְּדֵי לִגְמֹר אֶת \u0010y17\u0011 כֻּלָּהּ, יָצָא. \u0005 הַגָּה: \u0010y18\u0011 וַאֲפִלּוּ \u0006 \u0005 סָח \u0010y19\u0011 בֵּינְתַיִם. מִיהוּ גּוֹעֲרִין בְּמִי שֶׁסָּח בֵּינְתַיִם, כְּדִלְקַמָּן סִימָן תרצ\"ב סָעִיף ב'. \u0006 \u0005(הָרַשְׁבָּ\"א סי' רמ\"ד)\u0006.\nהַקּוֹרֵא \u0010c4\u0011 אֶת \u0010y20\u0011 הַמְּגִלָּה לְמַפְרֵעַ, לֹא יָצָא; קָרָא פָּסוּק אֶחָד \u0010y21\u0011 וְדִלֵּג הַשֵּׁנִי וְקָרָא שְׁלִישִׁי \u0010y22\u0011 וְאַחַר כָּךְ חָזַר וְקָרָא הַשֵּׁנִי, לֹא יָצָא. מִפְּנֵי שֶׁקָּרָא לְמַפְרֵעַ פָּסוּק אֶחָד; אֶלָּא כֵּיצַד יַעֲשֶׂה, מַתְחִיל מִפָּסוּק שֵׁנִי שֶׁשָּׁכַח, וְקוֹרֵא עַל הַסֵדֶר. \u0010y23\u0011\nהַקּוֹרֵא אֶת הַמְּגִלָּה עַל פֶּה, לֹא יָצָא יְדֵי חוֹבָתוֹ.\nהַלּוֹעֵז שֶׁשָּׁמַע אֶת הַמְּגִלָּה הַכְּתוּבָה \u0010c5\u0011 בִּלְשׁוֹן \u0010y24\u0011 הַקֹּדֶשׁ וּבְכִתְבֵי הַקֹּדֶשׁ, אַף עַל פִּי שֶׁאֵינוֹ יוֹדֵעַ מַה הֵם אוֹמְרִים, \u0010y25\u0011 יָצָא יְדֵי חוֹבָתוֹ. \u0010y26\u0011\nהָיְתָה כְּתוּבָה תַּרְגּוּם אוֹ בְּלָשׁוֹן אַחֶרֶת מִלְּשׁוֹנוֹת הָעַכּוּ\"ם, לֹא יָצָא יְדֵי חוֹבָתוֹ בִּקְרִיאָתָהּ אֶלָּא הַמַּכִּיר אוֹתוֹ הַלָּשׁוֹן בִּלְבַד; \u0010y27\u0011 אֲבָל אִם הָיְתָה כְּתוּבָה \u0010y28\u0011 בִּכְתָב עִבְרִי, \u0010y29\u0011 וּקְרָאָהּ אֲרַמִּית לַאֲרַמִּי, לֹא יָצָא, שֶׁנִּמְצָא זֶה קוֹרֵא עַל \u0010c6\u0011 פֶּה, וְכֵיוָן שֶׁלֹּא יָצָא הַקּוֹרֵא יְדֵי חוֹבָתוֹ \u0010y30\u0011 לֹא יָצָא הַשּׁוֹמֵעַ מִמֶּנּוּ. \u0005 הַגָּה: \u0010y31\u0011 אֲבָל אֵין לָחוּשׁ \u0010c7\u0011 \u0006 \u0005 בְּאֵיזֶה כְּתָב כְּתוּבָה \u0010c8\u0011 \u0006 \u0005(בֵּית יוֹסֵף)\u0006.\nמִי שֶׁיּוֹדֵעַ לַעַז וְיוֹדֵעַ אַשּׁוּרִית, \u0010y32\u0011 אֵינוֹ יוֹצֵא בְּלַּעַז; \u0010y33\u0011 וְיֵשׁ אוֹמְרִים שֶׁיּוֹצֵא. \u0005 הַגָּה: וְאִם כְּתוּבָה \u0010y34\u0011 בִּשְׁנֵי לְשׁוֹנוֹת, מִי שֶׁמְּבִינִים \u0010y35\u0011 יָצְאוּ \u0010y36\u0011 \u0006 \u0005(בֵּית יוֹסֵף)\u0006.\nיֵשׁ לִמְחוֹת בְּיַד הַקּוֹרְאִים לְנָשִׁים הַמְּגִלָּה בִּלְשׁוֹן לַעַז, \u0010y37\u0011 אַף עַל פִּי שֶׁכְּתוּבָה בִּלְשׁוֹן לַעַז. \u0010y38\u0011\nקְרָאָהּ מִתְנַמְנֵם, \u0010c9\u0011 הוֹאִיל וְלֹא נִרְדַּם \u0010y39\u0011 בְּשֵׁנָה, יָצָא; \u0010y40\u0011 אֲבָל אִם שְׁמָעָהּ מִתְנַמְנֵם, לֹא יָצָא.\nהָיָה כּוֹתְבָהּ, \u0010y41\u0011 שֶׁקּוֹרֵא פָּסוּק בַּמְּגִלָּה שֶׁהוּא מַעְתִּיק מִמֶּנָּה, וְכוֹתְבָהּ; \u0010y42\u0011 אִם כִּוֵּן לִבּוֹ לָצֵאת יְדֵי חוֹבָתוֹ, יָצָא, וְהוּא \u0010y43\u0011 שֶׁתְּהֵא כְּתוּבָה כֻּלָּהּ לְפָנָיו בַּמְּגִלָּה שֶׁהוּא מַעְתִּיק מִמֶּנָּה; \u0010y44\u0011 וְכֵן אִם הָיָה מַגִּיהָהּ; וְכֵן אִם הָיָה דּוֹרְשָׁהּ, שֶׁקּוֹרֵא פָּסוּק בִּמְגִלָּה שְׁלֵמָה וְדוֹרְשׁוֹ, אִם כִּוֵּן לִבּוֹ לָצֵאת יְדֵי חוֹבָתוֹ, יָצָא; וְלֹא יַפְסִיק בָּהּ בְּעִנְיָנִים אֲחֵרִים \u0010y45\u0011 כְּשֶׁדּוֹרְשָׁהּ, שֶׁאָסוּר לְהַפְסִיק בָּהּ \u0010y46\u0011 בְּעִנְיָנִים אֲחֵרִים.\nהַקּוֹרֵא אֶת \u0010y47\u0011 הַמְּגִלָּה צָרִיךְ שֶׁיְּכַוֵּן לְהוֹצִיא הַשּׁוֹמֵעַ, וְצָרִיךְ שֶׁיְּכַוֵּן הַשּׁוֹמֵעַ לָצֵאת, וְאִם הַקּוֹרֵא שְׁלִיחַ צִבּוּר \u0010y48\u0011 מִסְתָמָא דַּעְתּוֹ עַל כָּל הַשּׁוֹמְעִים, אֲפִלּוּ הֵם אֲחוֹרֵי בֵּית \u0010y49\u0011 הַכְּנֶסֶת, אֵין מְדַקְדְּקִין בְּטָעֻיּוֹתֶיהָ; \u0010c10\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא בְּטָעוּת שֶׁהַלָּשׁוֹן וְהָעִנְיָן אֶחָד, כְּהַהוּא עֻבְדָּא דִּתְרֵי תַּלְמִידֵי דַּהֲווּ יָתְבֵי קַמֵּהּ דְּרַב, חַד קָרֵי יְהוּדִים וְחַד קָרֵי יְהוּדִיִּים וְלֹא אַהְדַּר חַד מִינַיְיהוּ; אֲבָל טָעוּת \u0010y50\u0011 אַחֵר; לֹא.\nצָרִיךְ לוֹמַר עֲשֶׂרֶת בְּנֵי הָמָן וְעֲשֶׂרֶת, \u0010y51\u0011 הַכֹּל בִּנְשִׁימָה אַחַת, לְהוֹדִיעַ שֶׁכֻּלָּם נֶהֶרְגוּ וְנִתְלוּ כְּאֶחָד. \u0005 הַגָּה: וְדַוְקָא לְכַתְּחִלָּה, אֲבָל בְּדִיעֲבַד אִם \u0010y52\u0011 הִפְסִיק בֵּינֵיהֶם יָצָא \u0006 \u0005(תוס' ספ\"ק דִּמְגִלָּה וְאַבּוּדַרְהַם וּמַהֲרִי\"ל)\u0006. \u0005 וּלְכַתְּחִלָּה נוֹהֲגִין לוֹמַר בִּנְשִׁימָה אַחַת מִתְּחִלַּת חֲמֵשׁ מֵאוֹת \u0010y53\u0011 אִישׁ וְאֶת פַּרְשַׁנְדָתָא וכו' עַד עֲשֶׂרֶת; \u0006 \u0005(מַהֲרִי\"ל בְּשֵׁם רוֹקֵחַ)\u0006.\nצָרִיךְ שֶׁיֹּאמַר: אָרוּר הָמָן, בָּרוּךְ מָרְדְּכַי, אֲרוּרָה זֶרֶשׁ, בְּרוּכָה אֶסְתֵּר, אֲרוּרִים כָּל עוֹבְדֵי אֱלִילִים, בְּרוּכִים כָּל יִשְׂרָאֵל; וְצָרִיךְ שֶׁיֹּאמַר: וְגַם חַרְבוֹנָה זָכוּר לְטּוֹב.\nמִנְהַג כָּל יִשְׂרָאֵל \u0010y54\u0011 שֶׁהַקּוֹרֵא קוֹרֵא \u0010y55\u0011 וּפוֹשְׁטָה כְּאִגֶּרֶת, לְהַרְאוֹת הַנֵּס; \u0010y56\u0011 וּכְשֶׁיִּגְמֹר, חוֹזֵר וְכוֹרְכָהּ כֻּלָּהּ, וּמְבָרֵךְ. \u0005 הַגָּה: יֵשׁ שֶׁכָּתְבוּ שֶׁנּוֹהֲגִין לוֹמַר ד' פְּסוּקִים שֶׁל \u0010y57\u0011 גְּאֻלָּה בְּקוֹל רָם, דְּהַיְנוּ: אִישׁ יְהוּדִי וְגו', וּמָרְדְּכַי יָצָא וְגו', לַיְּהוּדִים הָיְתָה אוֹרָה וְגו', כִּי מָרְדְּכַי הַיְהוּדִי וְגו'; וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"א וְכָל בּוֹ וְאַבּוּדַרְהַם)\u0006; \u0005 וְהַחַזָּן חוֹזֵר וְקוֹרֵא אוֹתָן. עוֹד כָּתְבוּ שֶׁנָּהֲגוּ הַתִּינוֹקוֹת לָצוּר צוּרַת הָמָן עַל עֵצִים וַאֲבָנִים, אוֹ לִכְתֹּב שֵׁם הָמָן עֲלֵיהֶן, וּלְהַכּוֹתָן זֶה עַל זֶה כְּדֵי שֶׁיִּמָּחֶה שְׁמוֹ עַל דֶּרֶךְ: מָחֹה תִּמְחֶה אֶת זֵכֶר עֲמָלֵק \u0006 \u0005(דְּבָרִים כה, יט)\u0006 \u0005 וְשֵׁם רְשָׁעִים יִרְקַב \u0006 \u0005(מִשְׁלֵי י, ז)\u0006 \u0005 וּמִזֶּה נִשְׁתַּרְבֵּב הַמִּנְהָג \u0010y58\u0011 \u0006 \u0005 שֶׁמַּכִּים הָמָן \u0010y59\u0011 כְּשֶׁקּוֹרִים אֶת הַמְּגִלָּה בְּבֵית הַכְּנֶסֶת \u0006 \u0005(אַבּוּדַרְהַם)\u0006; \u0005 וְאֵין לְבַטֵּל שׁוּם \u0006 \u0005 מִנְהָג \u0010c11\u0011 אוֹ לִלְעֹג עָלָיו, כִּי לֹא לְחִנָּם הֻקְבָּע. \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח)\u0006. \u0010y60\u0011\nמְגִלָּה בְּי\"ד וּבְט\"ו צָרִיךְ \u0010y61\u0011 \u0010c12\u0011 לַחֲזֹר אַחַר עֲשָׂרָה, וְאִם אִי אֶפְשָׁר בַּעֲשָׂרָה קוֹרִים אוֹתָם בְּיָחִיד. \u0005 הַגָּה: וְיֵשׁ לְהִסְתַּפֵּק \u0010y62\u0011 אִם נָשִׁים מִצְטָרְפוֹת לַעֲשָׂרָה. \u0006 \u0005(הַגָּהוֹת אֲשֵׁרִי פ\"ק טוּר סי' תרס\"ט)\u0006. \u0005 וְאִם קָרְאוּ אוֹתָם בְּצִבּוּר, וְאֵיזֶה יָחִיד לֹא שְׁמָעָהּ, יָכוֹל לִקְרוֹת \u0010y63\u0011 אֲפִלּוּ לְכַתְּחִלָּה בְּיָחִיד, הוֹאִיל וְקוֹרִין אוֹתָם בְּאוֹתָהּ הָעִיר בַּעֲשָׂרָה \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח)\u0006; \u0010y64\u0011 \u0005 וּכְשֶׁהַיָּחִיד קוֹרֵא אוֹתָהּ \u0010y65\u0011 בִּזְמַנָּהּ, צָרִיךְ לְבָרֵךְ עָלֶיהָ. \u0006 \u0005(בֵּית יוֹסֵף)\u0006.",["\u0003בין יושב\u0004 מיהו הברכה יברך בעמידה:","\u0003אבל לא יקרא וכו'\u0004 ר\"ל דאם קורא בצבור צריך לקרוא בעמידה ועיין בה\"ל שצידדנו דעמידה ע\"י סמיכה שרי לענין מגילה:","\u0003ואסור לחזן וכו'\u0004 דלהוציא הצבור הוא ענין כבוד ואין ראוי לאדם לחלוק כבוד לעצמו כ\"ז שלא כבדוהו וכ\"ז באינו קבוע לכך אבל בש\"ץ קבוע שמינוהו לכך א\"צ להמתין:","\u0003ויוצאים הם וכו'\u0004 ולא אמרינן דתרי קלי לא משתמעי שפיר כדאמרינן לענין קה\"ת ושארי דוכתי דקריאה זו חביבה ביותר מפני הנס ויהיב דעתיה לשמוע היטיב. וכיון שכן פשוט הוא באם מרגיש בעצמו שמבלבלים ליה הקולות ושא\"א לו לשמוע כל התיבות בודאי לא יצא:","\u0003צריך לקרותה כולה\u0004 והוא לעיכובא. ודעת רוב הפוסקים שאפילו אם חיסר ממנה רק תיבה אחת לא יצא:","\u0003ומתוך הכתב\u0004 ומתבאר בש\"ס דאפילו קורא כל פסוק במגילה אלא שלא היתה המגילה כשרה נמי מקרי בע\"פ ולא יצא:","\u0003וצריך שתהא כתובה וכו'\u0004 ר\"ל דמה שאמרנו לא יצא היינו אם קרא בע\"פ את כל המגילה או רובה אבל אם קרא מקצתה כשרה דיעבד ואפילו אם היתה סיבת קריאתו בע\"פ מפני שהסופר השמיט בה איזה תיבות באמצעה עד חציה והוכרח הקורא לקרותם בע\"פ אף שלכתחלה אינו נכון לקרות במגילה שחסרה תיבות מ\"מ בדיעבד יצא:","\u0003אבל בדיעבד וכו'\u0004 ואם אין לו מגילה אחרת קורא בה לכתחלה:","\u0003אפילו עד חציה\u0004 וחציה יש לעיין אם כשירה בדיעבד:","\u0003אבל אם השמיט וכו'\u0004 דבזה נראה כספר חסר משא\"כ בנשמט בו פסוק באמצע אינו אלא כספר שלם שיש בו טעיות שאין מדקדקין במגילה בזה כ\"ז שהטעיות אינם ברובה של מגילה הואיל ונקרית אגרת:","\u0003אפילו מיעוטה\u0004 ואפשר אפילו בחסר רק פסוק ראשון או אחרון נמי הדין כן:","\u0003דוקא דלא השמיט ענין שלם\u0004 דבהשמיט ענין שלם נראה כספר חסר:","\u0003לא יקרא וכו'\u0004 דשמא יתן השומע לבו לזה הקורא ולא לש\"ץ ולפי טעם זה אם קורא רק לאדם אחד רשאי לקרות עם הקורא מתוך מגילה פסולה או מתוך חומש אבל יש מחמירין בכל גווני לפי שנותן דעתו בקריאתו ואינו משגיח למה שאומר הש\"ץ כיון שהוא עסוק בקריאתה:","\u0003וכן לא יסייע וכו'\u0004 ג\"כ מטעם הנ\"ל ועיין בא\"ר דמצדד גם בזה להחמיר אפילו בשקורא להוציא יחיד דשמא יתן דעתו למה שקורא בע\"פ בעצמו ובתוך כך ישתמט ממנו כמה תיבות שקורא הש\"ץ:","\u0003ולכן אותן הפסוקים וכו'\u0004 ר\"ל כמו שם דמחמירין שלא יסייע ע\"פ דעי\"ז יתנו כמה אנשים דעת לשמוע מזה המסייע דקורא ע\"פ ובאמת צריך לקרותה לכתחלה כולה מן הכתב כן גם בזה צריך החזן לחזור ולקרותם מתוך מגילה כשרה והם יכוונו לצאת בקריאתו כדי שיהא כולה מתוך הכתב:","\u0003צריך החזן וכו'\u0004 היינו לכתחלה:","\u0003אפילו שהה כדי לגמור את כולה\u0004 ר\"ל שהיה יכול בזמן הזה לגמור כל המגילה מראשה עד סופה:","\u0003יצא\u0004 ובשהה מחמת אונס לפי מה דקיי\"ל לעיל בסימן ס\"ה לענין ק\"ש דחוזר לראש ה\"ה הכא דחוזר וקורא מיהו אין לו לברך עוד פעם שני ועיין מש\"כ שם בבה\"ל:","\u0003ואפילו סח וכו'\u0004 ר\"ל דל\"ד בשהה בשתיקה אלא אפילו פסקו באמצע המגילה בשיחה ושהו עי\"ז נמי א\"צ לחזור אלא גומר ממקום שפסק. וכ\"ז כששח הקורא אבל השומע ששח ולא שמע עי\"ז הקריאה אפילו חיסר רק תיבה אחת דעת כמה פוסקים דלא יצא ולכן צורך גדול להיות לכל אחד חומש כי בעוד שמכין הנערים המן וכיוצא א\"א לשמוע כמה תיבות מש\"ץ ויוצא מה שקורא ע\"פ מחומש ויוצא עכ\"פ דיעבד [פמ\"ג]:","\u0003מיהו גוערין וכו'\u0004 דכיון שבירך עליה אין לו להפסיק בינתיים עד לאחר כל המצוה:","\u0003למפרע\u0004 היינו שקרא הפסוקים האחרונים קודם שקרא הפסוקים הראשונים ואפילו רק פסוק אחד וכדלקמיה וה\"ה היכי שקרא פרשה ב' קודם לא':","\u0003ודילג השני וקרא שלישי\u0004 וה\"ה אם קרא אחר הדילוג כל המגילה או ענין אחד ואח\"כ קרא פסוק הנדלג לא יצא וה\"ה אם קרא תיבה אחת למפרע כ\"ז בכלל למפרע וצריך לחזור ולקרות על הסדר:","\u0003ואח\"כ חזר וקרא השני לא יצא\u0004 היינו בקורא אח\"כ פסוק רביעי אלא אחר שחזר וקרא פסוק שני צריך לקרות שוב פסוק שלישי וזהו שמסיים אלא כיצד וכו':","\u0003הקורא וכו' ע\"פ\u0004 כבר כתבו המחבר לעיל בס\"ג וחזר ושנאו כאן משום דהתחיל להעתיק כאן לשון הרמב\"ם בסעיף ז' ולהלן ע\"כ העתיק כסדר הכתוב שם ושם מתחיל מדינא דקרא ע\"פ עי\"ש:","\u0003ובכתבי הקודש\u0004 צ\"ל בכתב הקודש וכך הגירסא ברמב\"ם ור\"ל בכתב אשורית:","\u0003יצא י\"ח\u0004 דהא האחשתרנים בני הרמכים גם אנן לא ידעינן מהו אלא לא בעינן אלא מצות קריאה ופרסומי ניסא ואפילו לכתחלה נמי ומשו\"ה יוצאין ג\"כ הנשים ועמי הארץ. כתב הפמ\"ג כל ירא שמים נכון שיהיה לו מגילה כשרה בידו ולקרוא מלה במלה בלחישה שא\"א לשמוע מן הש\"ץ הכל ובפרט שהנערים מבלבלים:","\u0003היתה כתובה תרגום וכו'\u0004 ואפילו הכתב היה כתב אשורית ג\"כ לא יצא מי שאינו מכיר הלשון:","\u0003אבל אם היתה כתובה וכו'\u0004 ר\"ל אימת אמרינן שיוצא משום שמכיר הלשון דוקא אם קורא בלשון הכתוב במגילה אבל אם מעתיק זה הלשון ללשון אחר אף שהוא מכיר שתי הלשונות יחד אינו יוצא והטעם כדלקמיה:","\u0003בכתב עברי\u0004 ר\"ל בלשון העברי:","\u0003וקראה ארמית לארמי\u0004 אשמועינן דאע\"ג שהמגילה לפניו והוא מעיין בכל תיבה ומתרגמה להשומע והו\"א דזה עדיף מקורא ע\"פ קמ\"ל דגם בזה לא יצא:","\u0003לא יצא\u0004 ר\"ל השומע כיון שהקורא קראה ע\"פ ואינה חשיבה קריאה אף לעצמו לא עדיף השומע ממנו:","\u0003אבל אין לחוש וכו'\u0004 ר\"ל דלא קפדינן שיהא דוקא הכתב של לשון זה שקורא ואפילו בהיה הלשון גיפטית והאותיות כתוב עילמית וכיו\"ב נמי שרי [ומ\"מ בעינן שיהא מכיר הקורא אותו הכתב דאל\"ה הוי בכלל ע\"פ כשאינו מכיר] אבל כמה פוסקים חולקים וס\"ל דמגילה בכל לשון שהיא אינה כשרה לקרות בה ואפילו ללועז אלא בשהכתב שלה אשורית ועיין בבה\"ל. כתב הפמ\"ג אם היתה כתובה כתב ולשון תרגום וכדומה והקורא אינו מבין תרגום וקראה להשומע שמבין לשון תרגום אינו יוצא י\"ח אף לדעת המחבר. וכן ה\"ה אם הקורא מבין אותו הלשון וכתובה לפניו באותו הלשון אם השומע אינו מבין אותו הלשון השומע אינו יוצא דכיון שאינו מבין אין כאן זכרון הנס גבי שומע מיהו נוהגין בזה\"ז לקרות הכל בלה\"ק ולכתבה בכתבי אותיות הקודש [לבוש]:","\u0003אינו יוצא בלע\"ז\u0004 משמע דעת המחבר לסתום כדעה זו ומ\"מ אינו חוזר ומברך דספק ברכות להקל. ומתבאר בפוסקים דלדעה זו אין לו להוציא אפילו למי שאינו מבין לה\"ק דכיון דקריאתו לא מהני לו בעצמו הו\"ל כמי שאינו מחוייב בדבר שאינו מוציא אחרים:","\u0003וי\"א שיוצא\u0004 דע דבכל מקום דאמרינן דיוצא בלע\"ז היינו שעכ\"פ תיבת האחשתרנים בני הרמכים יקרא לפניהם בלשה\"ק:","\u0003בשני לשונות\u0004 כגון מקצת המגילה בלשון אחד ומקצתה בלשון אחרת:","\u0003יצאו\u0004 בדיעבד אבל לכתחלה אין נכון להיות כתובה בשתי לשונות:","\u0003יש למחות ביד וכו'\u0004 טעם הדבר משום דהגברים הקוראים מבינים לה\"ק ויש לחוש לדעת הפוסקים שסוברים דהיכי שהוא מבין לה\"ק אינו יוצא בקריאה בלע\"ז וממילא אינו יכול להוציא בקריאה זו אף למי שאינו מבין לה\"ק וכנ\"ל ועוד משום האחשתרנים בני הרמכים שאינו ידוע בלע\"ז שלהן וא\"ת יקרא האחשתרנים בני הרמכים בלה\"ק י\"ל דאסור לכתחלה לקרותו בשתי לשונות:","\u0003אע\"פ שכתובה בלע\"ז\u0004 דאי לא כתובה בלע\"ז רק מעיין ומתרגם בלע\"ז הוי ליה קורא בע\"פ וכדלעיל ובלא\"ה לא יוציא. כתבו האחרונים דאפילו הקוראים בשני ימים להחמיר ג\"כ לא יקראו בלע\"ז:","\u0003קראה מתנמנם\u0004 ומתנמנם נקרא כגון דקרו ליה ועני ולא ידע לאהדורי סברא וכי מדכרו לי מדכר וצ\"ל דמ\"מ יכול לכוין לצאת דמצות צריכות כונה [פמ\"ג]:","\u0003יצא\u0004 וה\"ה השומע ממנו ג\"כ יצא אם רק נשמעים הדברים היטיב כ\"כ המאירי ואע\"ג דצריך לכוין להוציא אפשר דמתנמנם ג\"כ יכול לכוין ויותר נראה לומר דמיירי שחשב בתחילת הקריאה קודם שנתנמנם להוציא השומעין:","\u0003אבל אם שמעה וכו'\u0004 דבקריאה כיון שקורא כראוי הרי מוכח שרמי אנפשיה לומר שפיר משא\"כ בשמיעה בודאי חסר לו כמה תיבות:","\u0003שקורא פסוק במגילה וכו'\u0004 היינו אפילו אם באופן זה היתה קריאת כל המגילה כשרה הואיל שכיון לצאת בזה י\"ח ואם לא כיון לצאת אפילו רק פסוק ראשון אף שמשם ואילך התכוין לצאת לא יצא:","\u0003אם כיון לבו לצאת י\"ח\u0004 סתם בזה כהפוסקים דס\"ל מצות צריכות כונה לצאת ידי המצוה ועיין לעיל בסימן ס' ס\"ד:","\u0003שתהא כתובה כולה\u0004 עיין לעיל בס\"ג:","\u0003וכן אם היה מגיה\u0004 ר\"ל ובעת הגה קוראה ומכוין לצאת י\"ח ודוקא אם קרא בניקוד כראוי אבל אם קרא להגיה ע\"פ המסורת ולא בניקוד כראוי אינו יוצא י\"ח:","\u0003שאסור להפסיק וכו'\u0004 עיין לעיל בס\"ה בהג\"ה:","\u0003בענינים אחרים\u0004 היינו שלא מענינו של יום:","\u0003צריך שיכוין וכו' וצריך וכו'\u0004 ולעיכובא הוא אפילו בדיעבד וזה הכיון הוא קודם שמתחיל לקרוא יכוין על כל הקריאה זה לצאת וזה להוציא ותו א\"צ לכוין בכל הקריאה. וצריך השומע להאזין אוזנו ולשמוע כל תיבה ותיבה מפי הקורא ואם חיסר הקורא אפילו תיבה אחת וכן אם השומע חיסר תיבה אחת לשמוע לא יצאו וצריך לחזור:","\u0003מסתמא דעתו וכו'\u0004 ולענין השומעים ישתנה הדין דהעומדים בביהכ\"נ סתמא מכונים אבל העובר אחורי בהכ\"נ בעינן שיכוין בפירוש לצאת ידי חובה [פר\"ח]:","\u0003אין מדקדקין בטעיותיה\u0004 אין הדין הזה מיירי לענין כתיבה דשם הדין כמו בס\"ג והכא מיירי לענין קריאה דהיינו אפילו קרא אותה בכמה טעיות כיון שעכ\"פ קרא כולה:","\u0003אחר\u0004 כגון שקרא מיושב ישב או מנופל נפל דהוי כאלו דילג אותה תיבה לגמרי וצריך לחזור ולקרותה כסדר:","\u0003הכל בנשימה אחת\u0004 ובכל המגילה בין פסוק לפסוק יפסיק רק כדי נשימה מפני שצריך לקרותה כאגרת. כשיאמר בלילה ההוא נדדה יגביה הקול כי שם מתחיל הנס. כשיאמר האיגרת הזאת ינענע המגילה כתב הח\"א מה שנוהגין במקצת מקומות שכל הקהל אומרים י' בני המן אינו מנהג אלא הקורא יאמרם לבד והשאר ישמעו כמו כל המגילה:","\u0003הפסיק\u0004 אפי' שהא כדי לגמור כולה:","\u0003איש ואת וכו'\u0004 במהרי\"ל כתב בשם הרוקח משום דעשרת בני המן היו שרי חמשים על חמש מאות איש ומי שיש לו נשימה קצרה ישער שאם יתחיל מן חמש מאות איש לא יוכל לומר כל עשרת בני המן בנשימה אחת טוב יותר שיתחיל מן ואת פרשנדתא וכו' כי זהו דינא דגמרא אבל חמש מאות איש הוא מנהג בעלמא:","\u0003שהקורא וכו'\u0004 אבל היחידים השומעין במגילות א\"צ לפשוט [ב\"ח ומהרי\"ל]:","\u0003ופושטה כאיגרת\u0004 היינו שפושטה כולה ואינו מניחה כרוכה אלא כופל אותה דף על דף ויזהר שלא יגררה ע\"ג קרקע [א\"ר ופר\"ח] ועיין בפמ\"ג שכתב דל\"ד ע\"ג קרקע ה\"ה תלויה מעל השולחן ושטענדע\"ר נמי הוי גנאי כתבי קודש. עוד כתב דהפשיטה יהיה קודם שמתחיל לברך כדי שלא יהיה הפסק בין ברכה לקריאה:","\u0003חוזר וכורכה כולה ומברך\u0004 ר\"ל שכורכה כולה ומניחה לפניו על המגדל ואח\"כ מברך והטעם דגנאי הוא למגילה שתהיה מונחת כך ואפילו אם התחיל הברכה ואמר ברוך אתה כיון שלא אמר השם פוסק באמצע וכורך ואח\"כ מברך:","\u0003בקול רם\u0004 משום שמחה ומה שחוזר וקורא אותן כדי להשמיע לצבור שמצוה לכתחלה לשמוע כל המגילה מתוך הכתב:","\u0003שמכים המן\u0004 מהרי\"ל לא היה חושש להכות המן והגאון יעב\"ץ כותב על אביו הח\"צ שהיה מכה ורוקע ברגלו וטופח בסנדלו כשהגיע לזכירת המן והפמ\"ג כתב דיצא שכרם בהפסדם שמבלבלין הרבה:","\u0003כשקורין המגילה בביהכ\"נ\u0004 וצריך החזן לשתוק אז בעת שמכין כדי שישמעו כולם קריאתו ומפני שמצוי מאוד קלקולים ע\"י ההכאה ורגילים הנערים להכות כמה פעמים בעת שחוזר החזן לקרות ע\"כ טוב ונכון שכל יחיד יקרא פסוק או ב' מתוך החומש בעוד שמכין המן כי אז אף שלא ישמע מהחזן יצא כמ\"ש ס\"ג [מ\"א] וכ\"כ הפמ\"ג שנכון מאוד שכל אחד יתפוס חומש בעת הקריאה וכל תיבה שלא ישמע מן החזן יקרא מן החומש [מ\"א]:","\u0003בי\"ד ובט\"ו\u0004 היינו בי\"ד לעיירות וט\"ו למוקפין ור\"ל אף שהוא בזמנה ואיכא פרסומי ניסא בלא\"ה שהכל קורין באותו זמן אפ\"ה צריך לטרוח ולקבץ עשרה שיהיו בעת הקריאה משום פרסומי ניסא וכ\"ש אם הוא שלא בזמנה כגון המפרש בים והיוצא בשיירא ואינו מוצא מגילה להוליך עמו דמותר להקדים ולקרותה קודם שיוצא כנ\"ל בסימן תרפ\"ח ס\"ז או דמתרמי יום ט\"ו בשבת דצריכין המוקפין להקדים ולקרותו בע\"ש כדאיתא שם בס\"ו בודאי צריך לקבץ עשרה לקריאתו ובזה עוד חמיר יותר דאי ליכא עשרה לא יברכו המוקפין עליה:","\u0003לחזור אחר עשרה\u0004 ואם בעת ההוא קורין אותה בצבור בבהכ\"נ אז אפילו יש לו ק' אנשים בביתו מצוה לילך לשם משום ברוב עם הדרת מלך וכן מי שהיה ביתו סמוך לביהכ\"נ וחלונותיו פתוחות לביהכ\"נ אפ\"ה צריך לילך לבהכ\"נ לכו\"ע משום ברוב עם ועיין בבה\"ל:","\u0003אם נשים וכו'\u0004 דאפשר דכיון דהוא רק משום פרסומי ניסא סגי אף בנשים ועיין בפמ\"ג דמדלא הזכיר הרב קטנים משמע דס\"ל דקטנים בודאי אין מצטרפין לעשרה דלאו בני חיובא נינהו וחיובן הוא רק מטעם חינוך:","\u0003לכתחלה ביחיד\u0004 דהנס כבר נתפרסם וליכא רק משום ברוב עם לא מטרחינן ליה למכנף עשרה והא דקי\"ל דאף אם יש לו מנין בביתו אפ\"ה מבטלין ת\"ת ועבודה לילך ולקרות בצבור משום ברוב עם התם הלא הצבור מזומן לפניו משא\"כ הכא לעשות צבור אינו מחוייב ועיין ביד אפרים שכתב דדין זה שהביא הרמ\"א בשם או\"ח אינו מוסכם לשארי פוסקים ולכן אף בכה\"ג יהדר אחר עשרה אנשים:","\u0003וכשהיחיד קורא אותה\u0004 היינו במקום דאי אפשר לו לקבץ עשרה או בגוונא דצייר הרמ\"א מקודם:","\u0003בזמנה\u0004 לאפוקי אם קורא היחיד אותה שלא בזמנה כגון כרכין המוקפין חומה דמתרמי יום ט\"ו שלהן בשבת דקורין אותה בע\"ש והוא קורא אותה ביחיד לא יברך עליה בכל גווני וכנ\"ל בס\"ק ס\"א:"],["\u0003 אבל לא יקרא בצבור מיושב לכתחלה וכו'\u0004 - הנה במטה יהודא מצדד דסמיכה מותר ונראה דבשעת הדחק יש לסמוך ע\"ז להקל כי באמת מן הגמרא דקאמר משא\"כ בתורה והתם הלא בדיעבד ג\"כ יצא כדאיתא במאירי בהדיא (ודלא כב\"ח) ואינו אלא לכתחלה וא\"כ הכא אפילו לכתחלה שרי וכן מוכח ברש\"י ור\"ן ודברי הרמב\"ם נובעים מדברי המאירי שהוא מנהג שנהגו בו עם קדוש בענין זה וכן בכמה ענינים ע\"ש ואף דבודאי אין לזוז מזה אחרי שהוא מנהג של כלל ישראל מ\"מ דיינו אם נחמיר בזה בישיבה ממש ולא בסמיכה כנלענ\"ד:","\u0003 אבל אם השמיט תחלתה או סופה וכו' ואפילו באמצעה וכו'\u0004 - בענין זה יש מבוכה בין הפוסקים דמדברי הרא\"ש בפ\"ב סימן ד' משמע להקל בזה בדיעבד בכל גווני בין בחסר בראש הספר ובין בחסר ענין שלם כ\"ז שלא חסר רוב הספר עי\"ש והב\"ח מצדד כדבריו ובדברי הרשב\"א והאורחות חיים ג\"כ יש לעיין אם לא פליגי אהדדי דאפשר להרשב\"א דוקא בתחלת הספר יש קפידא אמנם באמצע אפילו ענין שלם לא חיישינן בדיעבד וכמו שנטה כן באמת הפר\"ח וכן משמע לכאורה ברשב\"א ור\"ן עי\"ש ואפשר עוד לומר דהרשב\"א גופא אינו מחמיר אף בראש הספר כ\"א בשחסר פרשה שלמה ויש משמעות כן בדבריו ע\"ש בחידושיו ובר\"ן ולפ\"ז ברור דפליג אאורחות חיים ואפילו אם נימא דלהרשב\"א בראש הספר אפילו בפסוק אחד פסול אם חיסר וכמו שכתב בעל מטה יהודא בדעתו וגם מודה להאורחות חיים דבענין שלם אפילו באמצע פסול וכמו שנראה לכאורה כן דעת הג\"ה [דאל\"כ יאמר וי\"א עוד דאפילו באמצעה וכו'] עכ\"פ אינו מוכח אם האו\"ח מודה להרשב\"א דאפשר דס\"ל דוקא בשחיסר ענין שלם יצא מתורת מגילה אבל לא בחיסר פסוק אפילו פסוק ראשון או אחרון. ובאמת במאירי פ\"ב ממגילה מביא רק סברא זו דענין שלם וז\"ל יש מי שאומר שלא הותר אף במקצתה כשחסר משם ענין שלם על הסדר שהרי אומר צריך שתהא כתובה כולה למעט אם חסרה פרשה או ענין שלם אף שהוא מועט עכ\"ל וסברת הרשב\"א לא הביא כלל. ומ\"מ לדינא אין לנו לנטות מדעת ההג\"ה וכפי שפירשנו במ\"ב. ברם צריך לברר דלכל הסברות הנ\"ל משמע לכאורה דאם לא חיסר בראש ובסוף וגם באמצע לא חיסר ענין שלם כשר כ\"ז דלא חיסר רובה ולפ\"ז משכחת בשחיסר בכל תיבה ותיבה שבמגילה מקצת אותיות עד שלא יהיה אפשר לקרות כלל המגילה בשביל זה ואיך ס\"ד דיהיה כשר הלא אין זה ספר כלל ובע\"כ דאין אנו חושבין כולה או מקצתה במספר האותיות אלא במספר התיבות ואפילו המיעוט של האותיות מטושטשות כל שיש בכל תיבה או ברובה איזה אות מטושטש פסול:","\u0003 דוקא דלא השמיט ענין שלם\u0004 - עיין במ\"ב דבכל זה הטעם דבעינן שיקרא מתוך ספר ואם חסר מתחלתו או שחסר באמצע ענין שלם אף שהוא רק מקצתו לא מקרי ספר ולפ\"ז נראה פשוט דזה שייך דוקא לענין אם השמיט מתוך הספר ולאפוקי לענין קריאה בע\"פ דיצא במקצתו אין לחלק בזה ובבגדי ישע ראיתי שהחמיר בזה ולא נהירא כלל וכן מוכח מסתימת כל הפוסקים שכתבו דמקצתו כשר ולא חילקו בזה אח\"כ מצאתי כדברי במטה יהודא:","\u0003 אלא שהן מטושטשות וכו'\u0004 - וה\"ה אם היו נפסקין האותיות חשוב כחסר [ח\"א]:","\u0003 הקורא וכו' למפרע לא יצא\u0004 - ונראה דצריך נמי לחזור ולברך היכי שהתחיל תיכף אחר הברכה לקרוא שלא מראש המגילה דנתבטלה ברכתו כדין שאר הפסק בין הברכה לתחלת המצוה ועיין לעיל בסימן תכ\"ב בסוף הסימן (סעיף ו') במ\"ב ובה\"ל:","\u0003 הכתובה בלה\"ק\u0004 - ואם שינה בה אף איזה תיבות ללשון אחר פסולה לכמה פוסקים [ומקורו ממגילה ד' ט' מקרא שכתבו תרגום ותרגום שכתבו מקרא ואע\"ג דאפילו חסר וקרא בע\"פ כשר כתבו הראשונים דשאני הכא דהוי כמזויף מתוכו והריטב\"א מצדד להכשיר בזה וצ\"ע]:","\u0003 שנמצא זה קורא על פה\u0004 - לפי דעת המחבר בס\"י שמי שיודע אשורית אינו יוצא בלע\"ז א\"כ בלא\"ה לא יצא שהרי מבין בלשון העברי אכן באמת ניחא שדברי המחבר בזה הוא לשון הרמב\"ם ולדידיה אתי שפיר שכבר כתב הרב המגיד שדעת הרמב\"ם להקל ביודע לע\"ז ואשורית:","\u0003 אבל אין לחוש וכו'\u0004 - עיין במ\"ב וכתב הריטב\"א דמגילה הכתובה בכתב האומות אין מדקדקין בה שיהיו האותיות מוקפות גויל שלא הצריכו זה אלא בכתב הקודש:","\u0003 באיזה כתב כתובה\u0004 - עיין מ\"ב מה שכ' שם בשם כמה פוסקים לחלוק על המחבר ומ\"מ אחרי העיון מצאנו שדעת כמה וכמה ראשונים כהמחבר עיין בר\"ן מה שכתב בשם הרמב\"ן בריש פ\"ב לענין הא דהתירו בלע\"ז ללועזים כתב דמפני שאין יודעין אשורית אע\"פ שיוצאין בו בקושי וכו' ראו חכמים דפרסומי ניסא בידיעה ממש עדיף טפי להוציאו בלשון שיודע בו ועוד כדי שיהא יכול להוציא א\"ע ידי חובה ויקרא לעצמו וכו' עיי\"ש ואי בעינן דוקא שיהא הכתב אשורית איך יכול לקרות ודוחק לומר דמיירי שאינו יודע הלשון אבל בכתב אשורית הוא בקי (ועיין בר\"ן שם) ובחי' הרשב\"א מבואר עוד יותר דבכל גווני יצא שכתב דהא דתנן עד שתהא כתובה אשורית לאו אכולה מתניתין קאי אלא אלועז ששמע אשורית ומסתייע מתוספתא ושם מבואר להדיא דקאי אלועז ששמא אשורית ומסיים שם בהדיא דלעולם אין יוצאין י\"ח עד שתהא כתובה אשורית בלשון עברי עי\"ש וכן מצאתי גם בריטב\"א בפ\"ק ובפ\"ב שכתב להדיא דהיכי דהכשירו לשון העכו\"ם הכשירו גם הכתב. וכן משמע דעת התוס' בפ\"ק דף ח' ע\"ב ד\"ה עד שכתבו וז\"ל כיון שניתנה לקרות ולכתוב בכל לשון שמכירין בה עי\"ש ומוכח מזה שדעתם דבכל לשון ובכל כתב שרי וכן משמע ג\"כ דעת הרמב\"ם שהעתיק דינא דמתניתין עד שתהא כתובה אשורית לענין לועז ששמע אשורית וכפי המבואר בס\"ח שהוא לשון הרמב\"ם [וביותר הא דס\"ט שהוא ג\"כ לשון הרמב\"ם וכתב שם והוא שתהא כתובה בכתב אותו הלשון הרי מבואר בהדיא דלא בעינן אשורית] וכן הטור לא העתיק דינא דמתניתין כלל אלמא דלא קאי רק אמגילה שנכתבה בלה\"ק ואח\"כ מצאתי באשכול שרצה ג\"כ לומר כהני פוסקים דבעינן כתב אשורית אפילו בהיתה המגילה לועזית ואח\"כ כתב מדשתקו רבוותא משמע דס\"ל דעד שתהא כתובה אשורית לא קאי אלא באם היה הלשון עברי והביא ג\"כ הא דתוספתא הנ\"ל אכן מדבריו שם משמע לכאורה דלא מכשיר אלא באם היה הלשון והכתב של אומה אחת ועיין שם בנחל אשכול וצ\"ע:","\u0003 קראה מתנמנם יצא\u0004 - ואין חילוק בין תחלת שינה לסוף שינה [ט\"ז וש\"א דלא כב\"ח]:","\u0003 אין מדקדקין בטעיותיה וכו'\u0004 - דין זה הוא מירושלמי והנה מלשון ריא\"ז המובא בש\"ג פ\"ב שכתב דבתיבות שאין מפסידין הקריאה אפילו אם השמיט ולא קרא כלל אינו חוזר וסיים שכן הוא בתלמוד א\"י מוכח דסבר דמה שאין מדקדקין היינו בתיבות שאין מפסידין הקריאה [אבל אם מפסידין הקריאה כגון וימי הפורים האלה לא יעברו והשמיט תיבת לא וכן ומתנות לאביונים השמיט המ\"ם לא יצא כ\"כ שם] והנה המגן אברהם בסק\"ה כתב עיין לקמן בסי\"ד דלא משמע כן וא\"י כונתו אם מן הי\"א דמוכח דאפילו מן יושב לישב ומן נופל לנפל חוזר כמו שהביא המגן אברהם כ\"ש אם השמיט לגמרי איזה תיבות אף שאין מפסידין הקריאה דחוזר דלמא הריא\"ז סובר כדעה ראשונה דבכל גווני אין מדקדקין בטעיותיה ואולי דסובר המגן אברהם דמשמע מלשון המחבר דלדעה ראשונה אף בטעות שהענין משתנה אין לדקדק בטעיותיה ואינו חוזר אבל בהשמיט לגמרי איזה תיבות זה אינו נכנס בכלל טעות וחוזר לכו\"ע. ועיין בר\"ן שהביא ראיה מוכרחת מן הגמרא דאם חיסר רק תיבות בני הרמכים ולא קראן כלל אינו יוצא אף בדיעבד דלא היקל בגמרא בזה אף דלא ידע פירושן רק משום דעכ\"פ איכא בזה מצות קריאה ופרסומי ניסא הא אם לא קראן כלל אינו יוצא אף בדיעבד ואלו להריא\"ז יוצא בזה בדיעבד דהא אינו מפסיד הקריאה וכן הוא גם כן דעת הרשב\"א כהר\"ן. והנה המגן אברהם והפר\"ח והמטה יהודא נקטו כולם לדינא כהר\"ן והרשב\"א ולא כהריא\"ז. ועתה נבאר בקצרה לדינא הנה לכתחלה בודאי יש לנהוג כדעת הי\"א דהיכא שהענין משתנה כגון מן נופל נפל ומן יושב ישב דחוזר וקורא על הסדר אפילו היכא דסיים כל המגילה וכמו שכתב הפר\"ח דהעיקר כהי\"א ומ\"מ כיון שהמחבר תלה ד\"ז בשתי דיעות כלשון הטור יש לנקוט דחוזר ואינו מברך אכן אם חיסר לגמרי איזה תיבה בקריאה [וה\"ה בשמיעה] לדעת כל הפוסקים הנ\"ל חוזר ומברך אף שאין מפסיד הקריאה אכן בח\"א חשש לדעת הריא\"ז וכתב דתיבה שאין מפסיד הקריאה חוזר ואינו מברך וע\"ש דאפילו חסר אות אחת בקריאתו יחזור:","\u0003 ואין לבטל שום מנהג וכו'\u0004 - עיין במגן אברהם שהאריך בזה והנה מה שכתב דאפילו יש במנהג צד איסור אין לבטלו כמש\"כ מהרי\"ק ש\"ט עיין בתשובת ח\"ס סקנ\"ט שאין אנו שומעין לו דכבר דחה ליה פר\"ח במנהגי איסור שלו שס\"י בראיות ברורות וכן נראה מתשובת הריב\"ש סרנ\"ו ע\"ש ועיין תשובת יכין ובועז סקי\"ח שהאריך בדיני מנהג [פ\"ת]:","\u0003 צריך לחזור אחר עשרה\u0004 - עיין מ\"ב מש\"כ במי שהיה ביתו סמוך לביהכ\"נ וכו' כן הביא הבה\"ט בשם הלכות קטנות והנה ראיתי בלבוש שהעתיק לדינא היפוך מזה דיוצא בזה ואף לכתחלה יכול לעשות כן ומ\"מ נראה דהדין עם הלק\"ט דצריך לילך לשם דאף שדברי הלבוש [שכתב דכיון דבמקום הקריאה יש שם עשרה ושם הוי פרסומי ניסא והוא שומע לה מאותו המקום יוצא בה אף לכתחלה דקריאת המגילה הלא במקום עשרה היא] נובעים מדברי הר\"ן המובא בב\"י ע\"ש מ\"מ פשוט דגם הר\"ן מודה דצריך לילך לשם עכ\"פ משום ברוב עם הדרת מלך דהרי הר\"ן גופא הקשה לדברי רב דבזמנה קורין ביחיד אף לכתחלה אמאי אמרו בגמרא דבית רבי היו מבטלין ת\"ת לילך לשמוע מקרא מגילה ותירץ דלמצוה מן המובחר משום ברוב עם הדרת מלך גם רב מודה דאפילו היה לו בביתו ק' אנשים צריך לילך לביהכ\"נ לשמוע הקריאה בצבור ורק לענין לחזור אחר עשרה לקבצם סבר רב דלא הטריחוהו חכמים ע\"ש וא\"כ ה\"נ בענינינו אף אם נימא דמשום פרסומי ניסא אין מחויב לילך לביהכ\"נ כסברת הלבוש עכ\"פ משום ברוב עם צריך לילך ואפשר דגם הלבוש מודה לזה. ומלבד כ\"ז הר\"ן שדחק עצמו בסברא זו הוא לתרץ קושית התוספות על מה דקאמרה המשנה היה עובר אחורי בהכ\"נ ושמע קול מגילה אם כיון לבו יצא הא בעינן עשרה אפילו בזמנה לדברי רב אסי והנה זה הקושיא הוא רק אם אנו סוברין כהפוסקים דלרב אסי הוא לעיכובא משא\"כ אם נסבור דרב אסי קאמר רק למצוה וכפסק השו\"ע וכמו שכתב הגר\"א ממילא אין כאן קושיא כלל ואין אנו צריכין לעיקר סברתו ולפ\"ז גם משום פרסומי ניסא מחויב לילך לשם. אח\"כ מצאתי בביאור הגר\"א שרמז לדברינו אלה האחרונים במלותיו הקצרות וגם הוא ס\"ל סברת הר\"ן לדוחק:"],"\u0010g0\u0011 \u0010s0\u0011 קוֹרֵא אָדָם אֶת הַמְּגִלָּה בֵּין עוֹמֵד \u0010y0\u0011 \u0010m0\u0011 בֵּין \u0010t0\u0011 יוֹשֵׁב; \u0010y1\u0011 \u0010g1\u0011 אֲבָל לֹא יִקְרָא בְּצִבּוּר, \u0010c0\u0011 יוֹשֵׁב, לְכַתְּחִלָּה מִפְּנֵי כְּבוֹד הַצִּבּוּר. \u0005 הַגָּה: \u0010y2\u0011 \u0010m1\u0011 וְאָסוּר לַחַזָּן לִקְרוֹת אֶת הַמְּגִלָּה עַד \u0010t1\u0011 \u0006 \u0005 שֶׁאוֹמְרִים לוֹ: קְרָא, \u0006 \u0005(מָרְדְּכַי פֶּרֶק הַקוֹרֵא)\u0006. \u0010g2\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011\nאֲפִלּוּ שְׁנַיִם, וַאֲפִלּוּ עֲשָׂרָה, יְכוֹלִים \u0010m2\u0011 לִקְרוֹתָהּ בְּיַחַד \u0010y3\u0011 וְיוֹצְאִים הֵם וְהַשּׁוֹמְעִים מֵהֶם. \u0010y4\u0011 \u0010g3\u0011 \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011\nצָרִיךְ לִקְרוֹתָהּ \u0010y5\u0011 \u0010g4\u0011 כֻּלָּהּ, וּמִתּוֹךְ הַכְּתָב; וְאִם קְרָאָהּ עַל פֶּה, לֹא יָצָא. \u0010y6\u0011 \u0010g5\u0011 וְצָרִיךְ שֶׁתְּהֵא כְּתוּבָה כֻּלָּהּ לְפָנָיו לְכַתְּחִלָּה, \u0010y7\u0011 אֲבָל בְּדִיעֲבַד \u0010g6\u0011 \u0010m3\u0011 אִם הִשְׁמִיט הַסוֹפֵר בְּאֶמְצָעָהּ \u0010y8\u0011 תֵּבוֹת, אֲפִלּוּ עַד חֶצְיָהּ, וּקְרָאָם הַקּוֹרֵא עַל פֶּה, יָצָא. \u0005 הַגָּה: \u0010y9\u0011 אֲבָל אִם הִשְׁמִיט תְּחִלָּתָהּ \u0010c1\u0011 אוֹ סוֹפָהּ, \u0010y10\u0011 \u0010m4\u0011 אֲפִלּוּ מִעוּטָהּ, לֹא יָצָא \u0006 \u0005(רַ\"ן)\u0006; \u0010y11\u0011 \u0005 וַאֲפִלּוּ בְּאֶמְצָעָהּ דַּוְקָא דְּלֹא הִשְׁמִיט עִנְיָן \u0010c2\u0011 שָׁלֵם, \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח)\u0006; \u0010g7\u0011 אֲבָל בְּיוֹתֵר מֵחֶצְיָהּ, אֲפִלּוּ הֵן כְּתוּבוֹת, אֶלָּא שֶׁהֵן \u0010c3\u0011 מְטֻשְׁטָשׁוֹת וְאֵין רִשּׁוּמָן נִכָּר, פְּסוּלָה. \u0010g8\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011\nמִי שֶׁתּוֹפֵס בְּיָדוֹ מְגִלָּה שֶׁאֵינָהּ \u0010y12\u0011 \u0010t2\u0011 \u0010m5\u0011 כְּשֵׁרָה, לֹא יִקְרָא עִם שְׁלִיחַ צִבּוּר, אֶלָּא שׁוֹמֵעַ וְשׁוֹתֵק. \u0005 הַגָּה: \u0010y13\u0011 וְכֵן לֹא יְסַיֵּע שׁוּם אָדָם עַל פֶּה לַחַזָּן, \u0010y14\u0011 וְלָכֵן אוֹתָן הַפְּסוּקִים שֶׁקּוֹרִין הַקָּהָל \u0010y15\u0011 צָרִיךְ הַחַזָּן לַחֲזֹר וְלִקְרוֹתָם מִתּוֹךְ מְגִלָּה כְּשֵׁרָה. \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם שִׁבּוֹלֵי לֶקֶט)\u0006. \u0010g9\u0011 \u0010r9\u0011 \u0010r10\u0011 \u0010r11\u0011\nקְרָאָהּ סֵרוּגִין, דְּהַיְנוּ שֶׁפָּסַק בָּהּ וְשָׁהָה וְאַחַר כָּךְ חָזַר לַמָּקוֹם שֶׁפָּסַק, \u0010y16\u0011 \u0010g10\u0011 אֲפִלּוּ שָׁהָה כְּדֵי לִגְמֹר אֶת \u0010y17\u0011 כֻּלָּהּ, יָצָא. \u0005 הַגָּה: \u0010y18\u0011 \u0010t3\u0011 \u0010m6\u0011 וַאֲפִלּוּ \u0006 \u0005 סָח \u0010y19\u0011 בֵּינְתַיִם. מִיהוּ גּוֹעֲרִין בְּמִי שֶׁסָּח בֵּינְתַיִם, כְּדִלְקַמָּן סִימָן תרצ\"ב סָעִיף ב'. \u0006 \u0005(הָרַשְׁבָּ\"א סי' רמ\"ד)\u0006. \u0010g11\u0011 \u0010r12\u0011 \u0010r13\u0011 \u0010r14\u0011 \u0010r15\u0011\nהַקּוֹרֵא \u0010c4\u0011 אֶת \u0010y20\u0011 הַמְּגִלָּה לְמַפְרֵעַ, לֹא יָצָא; קָרָא פָּסוּק אֶחָד \u0010y21\u0011 וְדִלֵּג הַשֵּׁנִי וְקָרָא שְׁלִישִׁי \u0010y22\u0011 וְאַחַר כָּךְ חָזַר וְקָרָא הַשֵּׁנִי, לֹא יָצָא. מִפְּנֵי שֶׁקָּרָא לְמַפְרֵעַ פָּסוּק אֶחָד; אֶלָּא כֵּיצַד יַעֲשֶׂה, מַתְחִיל מִפָּסוּק שֵׁנִי שֶׁשָּׁכַח, וְקוֹרֵא עַל הַסֵדֶר. \u0010y23\u0011 \u0010g12\u0011\nהַקּוֹרֵא אֶת \u0010t4\u0011 \u0010m7\u0011 הַמְּגִלָּה עַל פֶּה, לֹא יָצָא יְדֵי חוֹבָתוֹ. \u0010g13\u0011\nהַלּוֹעֵז שֶׁשָּׁמַע אֶת הַמְּגִלָּה הַכְּתוּבָה \u0010c5\u0011 בִּלְשׁוֹן \u0010y24\u0011 הַקֹּדֶשׁ וּבְכִתְבֵי הַקֹּדֶשׁ, אַף עַל פִּי שֶׁאֵינוֹ יוֹדֵעַ מַה הֵם אוֹמְרִים, \u0010y25\u0011 \u0010g14\u0011 יָצָא יְדֵי חוֹבָתוֹ. \u0010y26\u0011 \u0010g15\u0011\nהָיְתָה כְּתוּבָה תַּרְגּוּם אוֹ בְּלָשׁוֹן אַחֶרֶת מִלְּשׁוֹנוֹת הָעַכּוּ\"ם, לֹא יָצָא יְדֵי חוֹבָתוֹ בִּקְרִיאָתָהּ אֶלָּא הַמַּכִּיר אוֹתוֹ הַלָּשׁוֹן בִּלְבַד; \u0010y27\u0011 אֲבָל אִם הָיְתָה כְּתוּבָה \u0010y28\u0011 בִּכְתָב עִבְרִי, \u0010y29\u0011 וּקְרָאָהּ אֲרַמִּית לַאֲרַמִּי, לֹא יָצָא, שֶׁנִּמְצָא זֶה קוֹרֵא עַל \u0010c6\u0011 פֶּה, וְכֵיוָן שֶׁלֹּא יָצָא הַקּוֹרֵא יְדֵי חוֹבָתוֹ \u0010y30\u0011 לֹא יָצָא הַשּׁוֹמֵעַ מִמֶּנּוּ. \u0005 הַגָּה: \u0010y31\u0011 אֲבָל אֵין לָחוּשׁ \u0010c7\u0011 \u0010t5\u0011 \u0010m8\u0011 \u0006 \u0005 בְּאֵיזֶה כְּתָב כְּתוּבָה \u0010c8\u0011 \u0010g16\u0011 \u0006 \u0005(בֵּית יוֹסֵף)\u0006. \u0010r16\u0011 \u0010r17\u0011 \u0010r18\u0011 \u0010r19\u0011\nמִי שֶׁיּוֹדֵעַ לַעַז וְיוֹדֵעַ אַשּׁוּרִית, \u0010y32\u0011 \u0010m9\u0011 אֵינוֹ יוֹצֵא בְּלַּעַז; \u0010y33\u0011 \u0010g17\u0011 וְיֵשׁ אוֹמְרִים שֶׁיּוֹצֵא. \u0005 הַגָּה: וְאִם כְּתוּבָה \u0010y34\u0011 בִּשְׁנֵי לְשׁוֹנוֹת, מִי \u0010m10\u0011 שֶׁמְּבִינִים \u0010y35\u0011 \u0010t6\u0011 יָצְאוּ \u0010y36\u0011 \u0010g18\u0011 \u0010m11\u0011 \u0006 \u0005(בֵּית יוֹסֵף)\u0006. \u0010r20\u0011 \u0010r21\u0011 \u0010r22\u0011\nיֵשׁ \u0010t7\u0011 לִמְחוֹת בְּיַד הַקּוֹרְאִים לְנָשִׁים הַמְּגִלָּה בִּלְשׁוֹן לַעַז, \u0010y37\u0011 אַף עַל פִּי שֶׁכְּתוּבָה \u0010m12\u0011 בִּלְשׁוֹן \u0010t8\u0011 לַעַז. \u0010y38\u0011 \u0010g19\u0011 \u0010r23\u0011\nקְרָאָהּ \u0010m13\u0011 מִתְנַמְנֵם, \u0010c9\u0011 הוֹאִיל וְלֹא נִרְדַּם \u0010y39\u0011 בְּשֵׁנָה, יָצָא; \u0010y40\u0011 \u0010g20\u0011 אֲבָל אִם שְׁמָעָהּ \u0010t9\u0011 מִתְנַמְנֵם, לֹא יָצָא. \u0010g21\u0011 \u0010r24\u0011 \u0010r25\u0011\nהָיָה כּוֹתְבָהּ, \u0010y41\u0011 שֶׁקּוֹרֵא פָּסוּק בַּמְּגִלָּה שֶׁהוּא מַעְתִּיק מִמֶּנָּה, וְכוֹתְבָהּ; \u0010y42\u0011 אִם כִּוֵּן לִבּוֹ לָצֵאת יְדֵי חוֹבָתוֹ, יָצָא, \u0010g22\u0011 וְהוּא \u0010y43\u0011 שֶׁתְּהֵא כְּתוּבָה כֻּלָּהּ לְפָנָיו בַּמְּגִלָּה שֶׁהוּא מַעְתִּיק מִמֶּנָּה; \u0010y44\u0011 וְכֵן אִם הָיָה מַגִּיהָהּ; וְכֵן אִם הָיָה דּוֹרְשָׁהּ, שֶׁקּוֹרֵא פָּסוּק בִּמְגִלָּה שְׁלֵמָה וְדוֹרְשׁוֹ, אִם כִּוֵּן לִבּוֹ לָצֵאת יְדֵי חוֹבָתוֹ, יָצָא; \u0010g23\u0011 וְלֹא יַפְסִיק בָּהּ בְּעִנְיָנִים אֲחֵרִים \u0010y45\u0011 כְּשֶׁדּוֹרְשָׁהּ, שֶׁאָסוּר לְהַפְסִיק בָּהּ \u0010y46\u0011 בְּעִנְיָנִים אֲחֵרִים. \u0010g24\u0011 \u0010r26\u0011 \u0010r27\u0011 \u0010r28\u0011\nהַקּוֹרֵא אֶת \u0010y47\u0011 \u0010m14\u0011 הַמְּגִלָּה צָרִיךְ שֶׁיְּכַוֵּן לְהוֹצִיא הַשּׁוֹמֵעַ, וְצָרִיךְ \u0010t10\u0011 שֶׁיְּכַוֵּן הַשּׁוֹמֵעַ לָצֵאת, וְאִם הַקּוֹרֵא שְׁלִיחַ צִבּוּר \u0010y48\u0011 מִסְתָמָא דַּעְתּוֹ עַל כָּל הַשּׁוֹמְעִים, אֲפִלּוּ הֵם אֲחוֹרֵי בֵּית \u0010y49\u0011 \u0010g25\u0011 הַכְּנֶסֶת, אֵין מְדַקְדְּקִין בְּטָעֻיּוֹתֶיהָ; \u0010c10\u0011 \u0010g26\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא בְּטָעוּת שֶׁהַלָּשׁוֹן וְהָעִנְיָן אֶחָד, כְּהַהוּא עֻבְדָּא דִּתְרֵי תַּלְמִידֵי דַּהֲווּ יָתְבֵי קַמֵּהּ דְּרַב, חַד קָרֵי יְהוּדִים וְחַד קָרֵי יְהוּדִיִּים וְלֹא אַהְדַּר חַד מִינַיְיהוּ; אֲבָל \u0010m15\u0011 טָעוּת \u0010y50\u0011 אַחֵר; לֹא. \u0010g27\u0011 \u0010r29\u0011 \u0010r30\u0011\nצָרִיךְ לוֹמַר עֲשֶׂרֶת בְּנֵי הָמָן וְעֲשֶׂרֶת, \u0010y51\u0011 \u0010m16\u0011 הַכֹּל בִּנְשִׁימָה אַחַת, לְהוֹדִיעַ שֶׁכֻּלָּם נֶהֶרְגוּ וְנִתְלוּ כְּאֶחָד. \u0005 הַגָּה: וְדַוְקָא לְכַתְּחִלָּה, אֲבָל בְּדִיעֲבַד אִם \u0010y52\u0011 הִפְסִיק בֵּינֵיהֶם יָצָא \u0006 \u0005(תוס' ספ\"ק דִּמְגִלָּה וְאַבּוּדַרְהַם וּמַהֲרִי\"ל)\u0006. \u0005 וּלְכַתְּחִלָּה נוֹהֲגִין לוֹמַר בִּנְשִׁימָה אַחַת מִתְּחִלַּת חֲמֵשׁ מֵאוֹת \u0010y53\u0011 אִישׁ וְאֶת פַּרְשַׁנְדָתָא וכו' עַד עֲשֶׂרֶת; \u0006 \u0005(מַהֲרִי\"ל בְּשֵׁם רוֹקֵחַ)\u0006. \u0010g28\u0011 \u0010r31\u0011 \u0010r32\u0011\nצָרִיךְ שֶׁיֹּאמַר: אָרוּר הָמָן, בָּרוּךְ מָרְדְּכַי, אֲרוּרָה זֶרֶשׁ, בְּרוּכָה אֶסְתֵּר, אֲרוּרִים כָּל עוֹבְדֵי אֱלִילִים, בְּרוּכִים כָּל יִשְׂרָאֵל; וְצָרִיךְ שֶׁיֹּאמַר: וְגַם חַרְבוֹנָה זָכוּר לְטּוֹב. \u0010g29\u0011 \u0010r33\u0011 \u0010r34\u0011\nמִנְהַג כָּל יִשְׂרָאֵל \u0010y54\u0011 שֶׁהַקּוֹרֵא קוֹרֵא \u0010y55\u0011 \u0010g30\u0011 \u0010t11\u0011 \u0010m17\u0011 וּפוֹשְׁטָה כְּאִגֶּרֶת, לְהַרְאוֹת הַנֵּס; \u0010y56\u0011 וּכְשֶׁיִּגְמֹר, חוֹזֵר \u0010t12\u0011 \u0010m18\u0011 וְכוֹרְכָהּ \u0010m19\u0011 כֻּלָּהּ, וּמְבָרֵךְ. \u0005 הַגָּה: יֵשׁ שֶׁכָּתְבוּ שֶׁנּוֹהֲגִין לוֹמַר ד' פְּסוּקִים שֶׁל \u0010y57\u0011 גְּאֻלָּה בְּקוֹל רָם, דְּהַיְנוּ: אִישׁ יְהוּדִי וְגו', וּמָרְדְּכַי יָצָא וְגו', לַיְּהוּדִים הָיְתָה אוֹרָה וְגו', כִּי מָרְדְּכַי הַיְהוּדִי וְגו'; וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"א וְכָל בּוֹ וְאַבּוּדַרְהַם)\u0006; \u0005 וְהַחַזָּן חוֹזֵר וְקוֹרֵא אוֹתָן. עוֹד כָּתְבוּ \u0010m20\u0011 שֶׁנָּהֲגוּ הַתִּינוֹקוֹת לָצוּר צוּרַת הָמָן עַל עֵצִים וַאֲבָנִים, אוֹ לִכְתֹּב שֵׁם הָמָן עֲלֵיהֶן, וּלְהַכּוֹתָן זֶה עַל זֶה כְּדֵי שֶׁיִּמָּחֶה שְׁמוֹ עַל דֶּרֶךְ: מָחֹה תִּמְחֶה אֶת זֵכֶר עֲמָלֵק \u0006 \u0005(דְּבָרִים כה, יט)\u0006 \u0005 וְשֵׁם רְשָׁעִים יִרְקַב \u0006 \u0005(מִשְׁלֵי י, ז)\u0006 \u0005 וּמִזֶּה נִשְׁתַּרְבֵּב הַמִּנְהָג \u0010y58\u0011 \u0010t13\u0011 \u0006 \u0005 שֶׁמַּכִּים הָמָן \u0010y59\u0011 כְּשֶׁקּוֹרִים אֶת הַמְּגִלָּה בְּבֵית הַכְּנֶסֶת \u0006 \u0005(אַבּוּדַרְהַם)\u0006; \u0010m21\u0011 \u0005 וְאֵין לְבַטֵּל שׁוּם \u0010t14\u0011 \u0006 \u0005 מִנְהָג \u0010c11\u0011 אוֹ לִלְעֹג עָלָיו, כִּי לֹא לְחִנָּם הֻקְבָּע. \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח)\u0006. \u0010y60\u0011 \u0010g31\u0011 \u0010r35\u0011 \u0010r36\u0011 \u0010r37\u0011 \u0010r38\u0011 \u0010r39\u0011 \u0010r40\u0011 \u0010r41\u0011\nמְגִלָּה בְּי\"ד וּבְט\"ו \u0010m22\u0011 צָרִיךְ \u0010y61\u0011 \u0010c12\u0011 לַחֲזֹר אַחַר \u0010t15\u0011 עֲשָׂרָה, וְאִם אִי אֶפְשָׁר בַּעֲשָׂרָה קוֹרִים אוֹתָם בְּיָחִיד. \u0005 הַגָּה: \u0010m23\u0011 וְיֵשׁ לְהִסְתַּפֵּק \u0010y62\u0011 אִם נָשִׁים מִצְטָרְפוֹת לַעֲשָׂרָה. \u0006 \u0005(הַגָּהוֹת אֲשֵׁרִי פ\"ק טוּר סי' תרס\"ט)\u0006. \u0005 וְאִם קָרְאוּ אוֹתָם בְּצִבּוּר, וְאֵיזֶה יָחִיד לֹא שְׁמָעָהּ, יָכוֹל לִקְרוֹת \u0010y63\u0011 \u0010m24\u0011 אֲפִלּוּ לְכַתְּחִלָּה בְּיָחִיד, הוֹאִיל וְקוֹרִין אוֹתָם בְּאוֹתָהּ הָעִיר בַּעֲשָׂרָה \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח)\u0006; \u0010y64\u0011 \u0005 וּכְשֶׁהַיָּחִיד קוֹרֵא אוֹתָהּ \u0010y65\u0011 בִּזְמַנָּהּ, צָרִיךְ לְבָרֵךְ עָלֶיהָ. \u0006 \u0005(בֵּית יוֹסֵף)\u0006. \u0010r42\u0011 \u0010r43\u0011 \u0010r44\u0011 \u0010r45\u0011 \u0010r46\u0011",{"g":["משנה מגילה כה","טור בשם הרמב\"ם בפ\"ג","שם במשנה ובברייתא שם דכיון דחביבה יהבי דעתייהו ושמעי","משנה שם יט וכר\"מ שם בגמרא","משנה שם יז","מימרא דרב שם יט לכולי עלמא","ברייתא שם טז","אוקימתא דגמרא שם ורובה קרוי כולא כפי' הרמב\"ם בפ\"ב וכ\"כ הטור ואורחות חיים","הרשב\"א בתשובה שבלי הלקט","משנה שם י\"ז וכדמפרש שם בגמ' י\"ח","מסקנת הגמ' שם","שם במשנה","שם במשנה","שם במשנה","דאיכא מצות קריאה ופרסומי ניסא גמ' י\"א","רמב\"ם בפ\"ב דמשנה דלעיל וברייתא י\"ח","ה\"ה ע\"פ הירושלמי וחדושי רשב\"א והרמב\"ן","כן נראה מדברי ש\"י ורמב\"ם","תשובת הריב\"ש ותשובת ר\"ן על זה","משנה שם י\"ז כדמפרש בגמ' י\"ח","מרדכי ע\"פ הירושלמי ושבלי הלקט בשם רבינו שמחה","שם במשנה","שם בגמ' י\"ח","רא\"ש שם בשם הירושלמי","ציינתי לעל סי' תקפ\"ט בסעיף ח' ט'","טור בשם הירושלמי","\u0003שם וכן בת' א\"ח.\u0004 והר\"ן","מימרא דרב אדא מגילה ט\"ז","טור בשם הירושלמי בפ\"ד דמגילה","שם בשם רב האי ושכן מנהג צרפת ואשכנז וספרד וכ\"כ בשמו ש\"פ","כך הם דברי הרמב\"ם אבל הטור כתב פושט וקורא וכפי' א' שכ' סי' נ\"ז ופושטה כאיגרת אפי' מה שעתיד לקרות","מגילה ה' וכרב וכפירוש התו' שם וכן כת' הטור בשם רב עמרם ואביו הרא\"ש"],"t":["\u0003יושב. \u0004 אבל הברכה תהיה מעומד. מ\"א:","\u0003שאומרים. \u0004 היינו במקום שהמנהג שאין החזן קורא לעולם המגילה אבל במדינתינו החזן קורא לעולם המגילה א\"צ שיאמרו לו דמעיקרא מינוהו על כך. מ\"א:","\u0003לא יקרא\u0004 \u0003וכו'. \u0004 דשמא יתן השומע לבו לזה הקורא ולא לש\"ץ ב\"י א\"ח משמע דהוא עצמו יכול לשמוע לש\"ץ אע\"פ שקורא. מ\"א:","\u0003סח. \u0004 פירוש הקורא אבל השומע שסח ולא שמע לא יצא. ב\"י סי' תרצ\"ב:","\u0003על פה. \u0004 קשה דהא כבר כתבו בס\"ג אפשר דבא לומר דאפילו השומע ממנו לא יצא כמ\"ש בסמוך. מ\"א:","\u0003באיזה כתב. \u0004 פי' ובלבד שיכול לקרות אותו כתב:","\u0003יצאו. \u0004 בדיעבד עסי\"א:","\u0003למחות. \u0004 משום דלא ידעי הלעז של האחשתרנים וא\"ת יקרא האחשתרנים ככתבו בלה\"ק י\"ל דאסור לכתחלה לקרות בשני לשונות. מ\"א:","\u0003לעז. \u0004 ואפי' הקוראים בשני הימים אסור לקרותה בלעז ראב\"ח חלק ב' סי' ע\"ט:","\u0003מתנמנם. \u0004 כגון דקרי ליה ועני ולא ידע לאהדורי סברא:","\u0003השומע. \u0004 מבואר בתשובת הרשב\"א דאם השומע לא שמע תיבה אחת לא יצא אבל אם שמע ולא כוון בכל תיבה יצא עמ\"א:","\u0003ופושט. \u0004 ודוקא ש\"צ והשומעין במגילה א\"צ לפשוט. ב\"ח ומהרי\"ל עמ\"א:","\u0003וכורכה. \u0004 ומניחה על מקומה ואח\"כ מברך מ\"צ מט\"מ מהרי\"ל. ואם רוצה מברך ואח\"כ כורכה כנה\"ג סה\"י. כ' מהרי\"ל כשאומר בלילה ההוא נדדה יגביה קולו כי שם עיקר הנס כשיאמר האגרת הזאת ינענע המגילה. מט\"מ:","\u0003שמכים. \u0004 מהרי\"ל לא היה חושש להכות המן. ובלבוש כתב בשעה שאומרים המן יאמר שם רשעים ירקב. ועכ\"פ כשמכין המן צריך החזן לשתוק כדי שישמעו כולם קריאתו וכל יחיד יקרא פסוק או ב' מתוך החומש בעוד שמכים המן כי אז אף שלא ישמע מהחזן יצא כמ\"ש סעיף \u0005(ד')\u0006 [ג']:","\u0003מנהג. \u0004 וכתב רמ\"א בתשובה סי' \u0005(כ\"א)\u0006 [י\"ט] בשם מהרי\"ק שורש קמ\"ד דאם נמצא המנהג באיזה פוסק אין לבטל ואפי' בשעת הדחק אין לשנות מנהג ואפי' יש במנהג צד איסור אין לבטלו כמ\"ש מהרי\"ק ש\"ט. ואפי' במנהג מקום א' אמרי' שמבטל הלכה. מיהו אם נשתנה הענין מאשר היה בזמן הראשונים רשאים לשנות המנהג לפי הזמן עכ\"ל ומהרא\"ש בביאורי סמ\"ג כתב הא דאמרינן מנהג עוקר הלכה היינו אפי' רוב דיעות ס\"ל אסור והתלמוד מסייע להו והמנהג בנוי על פי הפסיקת' או ספרי חיצונים אמרינן מנהג עוקר הלכה דודאי כך קבלו אבותינו איש מפי איש עכ\"ל. עיין מהרי\"ק ש\"ט ושנ\"ד ובספר ב\"ש. ודוקא מנהג שנתייסד ע\"פ ותיקין אבל מנהג שאין לו ראיה מן התורה אינו אלא כטועה בשיקול הדעת מ\"ס פי\"ד ודבר שנגזר במנין אפי' ידוע מאיזה טעם ובטל הטעם צריך מנין אחר להתירו גמרא פרק קמא דביצה ואין ב\"ד יכול לבטל דבר ב\"ד חבירו אא\"כ גדול ממנו בחכמה ובמנין. ובכל דבר שהוא רק משום חששא ועברה החששא א\"צ מנין אחר כמ\"ש בי\"ד סי' קי\"ו ובתוספות ביצה ע\"ש וביבמות דף ע\"ח כתבו דבדבר שבממון יכולים לבטל דברי ב\"ד חבירו משום דהפקר ב\"ד הפקר. וע\"ש בתוספות דדבר שלא פשט איסורו ברוב ישראל יכולין לבטל ע\"ש ועיין מ\"א ועיין מ\"ש המ\"א ססי' ט' ועיין בספר נחלת שבעה דינים הרבה מענין המנהגים ועיין בספר ב\"ש:","\u0003עשרה. \u0004 אע\"פ שיש לו מאה אנשים מצוה לקרותה בצבור משום ברוב עם הדרת מלך ר\"ן ב\"ח. ועיין הלק\"ט חלק א' סי' רפ\"ז דאפילו ביתו סמוך לבה\"כ וחלונותיו פתוחות לב\"ה אפ\"ה ילך לבה\"כ משום פרסומי ניסא ע\"ש:"],"s":["\u0003 (ס\"א) בש\"ע קורא אדם כו' \u0004 וע' בבית יהודה סיכ\"ג שיש מדינות שנהגו לקרותה בלא טעמים ע\"ש ולא יעש' כן במדינותינו אם לא כשלא נמצא מי שיודע לקרותה בטעמים אבל מ\"מ צריך לחזור אחר מי שיודע לקרות המלות כמשפט הניקוד כמבואר לקמן דטעות שהענין משתנה מעכב בקריאתה ולכן אם אין שם מי יודע לקרות הניקוד כהלכתו אין לברך עליו וע' בשערי אפרים סעיף נ\"ח שאם מעמידין א' שיקרא לפני הקורא מתוך החומש יקרא בלחש וזה המקרא לפני הקורא צריך אח\"כ לחזור ולקרות מתוך המגילה ע\"ש:"],"m":["\u0003בין יושב\u0004. ערסי' ח' דמשמע דהברכ' תהי' בעמיד' ועססי' קמ\"ו מ\"ש:","\u0003ואסור לחזן\u0004. היינו במקום שהמנהג שאין החזן קורא לעולם המגילה אבל במדינתינו החזן קורא לעולם המגילה א\"צ שיאמרו לו דמעיקרא מינוהו על כך כמ\"ש סי' קל\"ט ס\"ג וכ\"מ במרדכי ע\"ש:","\u0003לקרות' ביחד\u0004. דאיידי דחביבא להו יהבי דעתייהו לשמוע:","\u0003אם השמיט הסופר\u0004. ואם השמיט הקורא תיבות שאין מפסידין הקריא' יצא (ש\"ג) עיין סי' קמ\"ב ולקמן סי\"ד דלא משמע כן:","\u0003אפי' מיעוט'\u0004. ע' בכ\"ה שהרבה להשיב ע\"ז ולענ\"ד אינו כלום דהרשב\"א הוכיח דאי איתא דבדיעבד כשר מנ\"ל להקשות דלמא אפי' השמיט רובה כשר וא\"כ לא ה\"ל לאתויי דרב חמא:","\u0003לא יקרא כו'\u0004. דשמא יתן השומע לבו לזה הקורא ולא לש\"ץ (ב\"י א\"ח) משמע דהוא עצמו יכול לשמוע להש\"ץ אף על פי שקורא:","\u0003ואפי' סח\u0004. פי' הקורא אבל השומע ששח ולא שמע לא יצא (ב\"י סי' תרצ\"ב):","\u0003ע\"פ\u0004. צ\"ע דהא כבר כתבו בס\"ג ואפשר דבא לומר דאפי' השומע (דפוס ישן משומע) ממנו לא יצא כמ\"ש בסמוך:","\u0003באיזה כתב\u0004. פי' ובלבד שיכול לקרות אותו כתב:","\u0003אינו יוצא בלעז\u0004. דס\"ל דהא דאיתא בגמרא אבל קורין ללועזות בלעז היינו מי שאינו יודע לה\"ק (ר\"ן דלא כע\"ש):","\u0003מי שמבינים יצאו\u0004. בדיעבד עסי\"א:","\u0003יש למחות\u0004. משום דלא ידעי הלעז של האחשתרנים וא\"ת יקרא האחשתרנים ככתבו בלה\"ק י\"ל דאסור לכתחלה לקרות בב' לשונות:","\u0003בלשון לעז\u0004. ואפי' הקוראים בשני הימים אסור לקרותה בלעז (ראב\"ח ח\"ב ע\"ט):","\u0003מתנמנם\u0004. כגון דקרי ליה ועני ולא ידע לאהדורי סברא:","\u0003צריך שיכוין\u0004. כתב הרשב\"א סי' תס\"ז שאלת אם צריך השומע לכוין בכל תיבה ותיבה בשמיעתו ששמעתי שחכם א' היה תופס מגילה א' בידו ותמיהני מי לא יצא מפי הקורא ועוד דנשים וע\"ה יוצאין באשורית תשובה האמת כמ\"ש מאותן ראיות מן הלועזות וע\"ה ועוד אמרו העובר אחורי ב\"ה ושמע קול מגיל' אם עמד חזקה כוון כו' אבל במה שנסתפק לך אם השמיט בה הקורא תיבה א' אם חוזר באמת אפילו תיבה א' חוזר עכ\"ל, מבואר דה\"ה אם השומע לא שמע תיבה א' לא יצא דאטו מי יפה כח השומע מכח הקור' וכ\"כ הטור סי' נ\"ט וב\"י סי' תרצ\"ב אלא אם שמע ולא כוון בכל תיבה יצא הארכתי בזה לפי שבב\"ח סי' תרצ\"א לא משמע כן:","\u0003טעות אחר\u0004. כגון מיושב ישב ומנופל נפל (ב\"י א\"ח):","\u0003הכל בנשימה א'\u0004. לא יפסיק רק כדי נשימה אפי' בין פסוק לפסוק שצריך לקרות' כאגרת (מט\"מ) (ד\"מ טור) כשיאמר בלילה ההוא נדדה יגביה קולו כי שם עיקר הנס (מהרי\"ל ד\"מ), כשיאמר האגרת הזאת ינענע המגילה (מט\"מ):","\u0003ופושטה כאגרת\u0004. אפי' מה שעתיד לקרות (מהרי\"ל סי' נ\"ו), כשקרא החזן והיה ביד מהרי\"ל מגילה כשרה לעיין בה היה מניח' כרוכ' (ב\"ח):","\u0003וכורכ' כולה\u0004. ומניחה על מקומה ואח\"כ מברך (מ\"מ מט\"מ מהרי\"ל) ול\"ד למ\"ש סי' רפ\"ד ס\"ו דאין לסלק ההפטרה עד שיברך דשאני הכא דהברכה לא קאי על המגיל': כתוב במהרי\"ל הבנתי אחר מהרי\"ל שלא הי' חושש להכות המן [ד\"מ] ועכ\"פ כשמכין המן צריך החזן לשתוק כדי שישמעו כולם קריאתו, וכל יחיד יקרא פסוק או ב' מתוך החומש בעוד שמכין המן כי אז אף שלא ישמע מהחזן יצא כמ\"ש ס\"ג:","\u0003ומברך\u0004. ואם רצה מברך ואח\"כ כורך (כ\"ה סה\"י):","\u0003שנהגו התינוקות וכו'\u0004. ולבוש כ' בשעה שאומרים המן יאמר שם רשעים ירקב ועיין ברב' במגילה גבי נבוכדנצר:","\u0003ואין לבטל כו'\u0004. וכ' רמ\"א בתשו' סי' כ\"א בשם מהרי\"ק שורש קמ\"ד דאם נמצא המנהג באיזה פוסק אין לבטלו אפי' בשעת הדחק אין לשנות מנהג כדאמרי' בבני בישן ואפי' יש במנהג צד איסור אין לבטלו כמ\"ש מהרי\"ק ש\"ט ואפי' במנהג מקום א' אמרי' שמבטל הלכה מיהו אם נשתנ' הענין מאשר הי' בזמן הראשונים רשאים לשנות המנהג לפי הזמן עכ\"ל ומהרא\"ש בביאורי סמ\"ג כ' הא דאמרינן מנהג עוקר הלכה היינו אפי' רוב דיעות ס\"ל אסור והתלמוד מסייע להו והמנהג הבנוי על פי הפסיקתא או ספרי' חיצונים אמרי' מנהג עוקר הלכה דודאי כך קבלו אבותינו איש מפי איש עכ\"ל (עיין מהרי\"ק ש\"ט ושנ\"ד ובס' ב\"ש) ודוקא מנהג שנתיסד ע\"פ ותיקין כמ\"ש המרדכי אבל מנהג שאין לו ראיה מן התורה אינו אלא כטועה בשיקול הדעת (מ\"ס פי\"ד), ודבר שנגזר במנין אפי' ידוע מאיזה טעם ובטל הטעם צריך מנין אחר להתירו (גמ' פ\"ק דביצה) ואין ב\"ד יכול לבטל דברי ב\"ד חבירו אא\"כ גדול ממנו בחכמה ובמנין וכל דבר שהוא משום חששא ועברה החששא א\"צ מנין אחר כמ\"ש בי\"ד סי' קי\"ו ובתוס' ביצה ע\"ש וביבמות דף ע\"ט כתבו דבדבר שבממון יכולים לבטל דברי ב\"ד חבירו משום דהפקר ב\"ד הפקר ולכאורה לא משמע הכי בגיטין דף ל\"ו גבי פרוזבל ע\"ש ומיהו י\"ל דהתם הוי מילתא דאיסורא שעי\"כ נמנעין מלהלוות וע\"ש בתוס' דדבר שלא פשט איסורו ברוב ישראל יכולין לבטל ע\"ש ועמ\"ש ססי' ט\"ו ע' בס' נחלת שבעה דינים הרבה מענין המנהגים ובס' ב\"ש:","\u0003צריך לחזור כו'\u0004. אף על גב שיש לו ק' אנשים מצוה לקרות' בצבור משום ברוב עם וכו' (ר\"ן ב\"ח) עסי' תרפ\"ז ס\"ב:","\u0003ויש להסתפק\u0004. באמת בהג\"א מסתפק בקטנים ונשים ופלוגתא היא בטור סי' תרפ\"ט:","\u0003לכתחלה ביחיד\u0004. דמשום ברוב עם לא מטרחי' ליה למכנף עשרה והא דמבטלים כל המצות מפני מ\"מ בצבור היינו למצוה מן המובחר:"],"r":["\u0003ס\"א בין כו'. \u0004ירושלמי שם מה לשעבר הא בתחל' לא והתניא מעשה בר\"מ שקרא מיושב בבה\"כ של טבעין כו' כיני מתני' מותר לקרותה עומד מותר לקרותה יושב. וכן כולה מתני' ע\"כ לכתחלה קראה א' קראה שנים יצא ובגמ' אפי' עשרה קורין וע' ר\"ן:","\u0003אבל לא. \u0004ירושלמי שם זה שהוא עומד לקרות בתורה מפני מה הוא עומד מפני כבודה או מפני כבוד הרבים אין תימר מפני כבודה אפילו בינו לבינה כו':","\u0003ואסור. \u0004תוספתא הביאו הרי\"ף ורא\"ש פ\"ג סי\"א וה\"ה למגילה מטעם שאמדו שם שאין אדם כו':","\u0003ס\"ב אפילו. \u0004מתניתין:","\u0003ואפילו. \u0004ברייתא שם:","\u0003והשומעים. \u0004שם כיון דחביבה כו':","\u0003ס\"ג אבל אם. \u0004ממ\"ש ואפי' למ\"ד מאיש יהודי כו' ומשמע דאפילו לעכב מדפרכינן מינה שם אלא דכת' פסוקא כו' ותי' הרשב\"א דדוקא באמצעיתה דנראה כספר שיש בו טעות אבל כשחסר תחלה או סוף הוי כספר חסר:","\u0003ואפילו באמצעה. \u0004ג\"כ מכח קושיא הנ\"ל:","\u0003אבל ביותר כו'. \u0004מדאמרינן במקצתה:","\u0003ס\"ד מי שתופס. \u0004עט\"ז:","\u0003וכן. \u0004מטעם הנ\"ל:","\u0003ולכן אותן כו. \u0004כנ\"ל דקראה מקצת ע\"פ דוקא דיעבד דלא כהג\"מ:","\u0003ס\"ה ואפי' סח. \u0004ברכות י\"ד א' פוסק כו' אלמא אין מפסיד הקריאה דאין מפסיד אלא הברכה לא המצוה כמ\"ש וכן בתפלה:","\u0003מיהו. \u0004כמ\"ש בסי\"ג ולא יפסיק כו' שאסור כו' כ\"ש בכה\"ג:","\u0003קרא פסוק. \u0004גמרא שם וע' רי\"ף ורא\"ש שם בשם ירושל':","\u0003אלא כיצד. \u0004גמרא שם ת\"ר השמיט כו':","\u0003ס\"ט היתה כו'. \u0004הרמב\"ם פסק דלעז יוני לכל כשר כרב ושמואל והרי\"ף השמיט מש\"ש לעז יוני לכל כשר. וע' ברא\"ש שם שכת' הטעם שהשמיט משום דאינהו ס\"ל כרשב\"ג ולא קי\"ל כן אלא כרבנן. ודבריו תמוהין ואינן מובנים לכאורה דהא ר' יוחנן פסק בפ\"ק שם ט' ב' כרשב\"ג אלא דיש לומר דלא קי\"ל כרב ושמואל דפסקו אף במגילה כותיה וכן סתמא דסוגיא שם א' דלא כרב ושמואל דקאמר שם אי רשב\"ג הא איכא כו' אלא ל\"ק כאן במגילה כו' ורשב\"ג לאחמורי אתא וכן ס\"ל לר\"פ ורנב\"י שם והא דפסק ר' יוחנן הלכה כרשב\"ג משום דס\"ל לר\"י דלא פליג רשב\"ג אלא בשאר ספרים ולא במגילה וע' במלחמות והר\"ן דחה דבריו וכת' דלהכי השמיטום משום דיוני כבר נשכח ואבד זכרו וכמ\"ש הרמב\"ם בפ\"א מה' ס\"ת וכן פ' רמב\"ם כאן כרב ושמואל וכ\"פ הרז\"ה וכ' המ\"מ שכ\"פ הרבה פוסקים. ומ\"מ דברי הרמב\"ן נכונים דודאי סוגיא דשם ט' א' דלא כרב ושמואל וכנ\"ל וכן בירושלמי שם מה בין ספרים למגלת אסתר אלא שהספרים נכתבים בכל לשון ומגילת אסתר אינה נכתבת אלא אשורית אבל הרמב\"ם ס\"ל כרב אשי שם וכמ\"ש תוספת שם ד\"ה כאן כו' וקיי\"ל כרב אשי:","\u0003אבל אם. \u0004גמ' שם:","\u0003וכיון שלא. \u0004ירושלמי וכמ\"ש למטה:","\u0003אבל אין. \u0004שגגה היא דמתני' שם עד שתהא כתובה אשורית ועלה אמרו בגמרא שם דכתי' ככתבם וכן שם ט' א' ל\"ק הא בגופן כו' במאי אוקימתא בגופן כו' עד שיכתבנו כו' ובתוספתא שם עד שתהא כתובה אשורית בלשון עברי כו':","\u0003ס\"י מי שיודע. \u0004שהקשו והא אמרינן בפ\"ק ט' א' דבמגילה אינו יוצא רק בלה\"ק ופי' ללועזות שאינן מכירין בלה\"ק כמו בפ\"ק דמכות הנהו לעוזי כו' ומפני שאינן יודעין התירו להם בקושי כדי שידעו ידיעה ממש וגם כן יוכלו לקרות בעצמן. וכ\"ה בירושלמי רפ\"ב דמגילה סוף הלכה א' ר' אבהו בשם ר\"א יודע אשורית ויודע לעז יוצא באשורית ור\"ל רק באשורית דבאשורית לצאת בה אף אם אינו יודע כלל יוצא בה. בלעז יוצא בה בלעז. יודע אשורית ויודע לעז מהו שיוציא אחרים בלעז. ר\"ל שהאחרים אין מכירין רק לעז ייבק כהדא כל שאינו חייב בדבר אינו מוציא את הרבים ידי חובתן כ\"ה הנוסחא המדוייקת וע' ר\"ן ומ\"מ שכן פסקו הרמב\"ן והרשב\"א וכ\"ה בסוטה בריש פ' ואלו נאמרין ר' לוי בר חיתא אזיל לקסרן שמע מלין קריין שמע אלוניסתון ר\"ל באיזה לעז (ובערוך כ' שהוא לשון יוני) בעא מעכבתון שמע ר' יוסי ואיקפד אמר כך אני אומר מי שאינו יודע לקרות (אשורית) לא יקראנה כל עיקר השיב ר' ברכיה הרי מגילת אסתר היה יודע לקרות אשורית ולעז אינו יוצא אלא אשורית ר\"ל מה אתה משיב ממי שאינו יודע ליודע ושפיר עכבם כו' ע\"ש. וכן עיקר כי פשטא דירושל' משום שיודע ג\"כ בלשון אשורית וכן פשטא דמתני' דקרי להו לועזות וכן מדקאמר והלועז כו' ופריך בגמ' והא לא ידע מאי קא' ואף לאותן שדחו הירושלמי ופירשו דירושלמי מיירי שכתובה בלשון אשורית דלא כגמרא דידן וכמ\"ש למטה מ\"מ מדידהו נשמע לדידן היכא שכתובה בלשון לעז והגמ' שלנו דקאמר וקראן כו' כמתורגמן המתרגם יצא ור\"ל בלשון תרגום וכמ\"ש למטה. ודאי הפי' כן אבל מ\"מ אין ראיה מזה דדוקא מקצתה יצא כמו שיוצא במה שקורא בע\"פ ואף דבירושלמי לא משמע הכי דפריך שם היאך יוצא בתרגום ומשני שמואל כדעתיה כו' ר' אבוה כו' משמע דלר' אבוה לא יצא בזה. י\"ל דגמרא דידן פליג בזה דהא לא פריך כלום מתרגום. אלא שי\"ל דגמרא דידן ס\"ל כשמואל דזו הברייתא השמיט הסופר כו' דשמואל היא כמש\"ש בירושל' ולפ\"ז קי\"ל כשמואל וזהו סברא שני' דיצא: אבל לפרש הירושלמי כמו שפי' ולחלק דאם כתובה בלעז אף ר' אבוה מודה לא נהירי כנ\"ל דהא ודאי דהירושלמי פליג אגמ' דידן ומכשיר ללועזות אפי' כתובה אשורית אבל מ\"מ ה\"ה לדידן אם כתובה בלעז כנ\"ל:","\u0003וי\"א שיוצא. \u0004שמפ' הירושלמי דמיירי בכתובה אשורית וקורא בלעז וכנ\"ל דס\"ל לירושלמי דאפ\"ה יוצא ודוקא בשאינו מכיר רק בלעז כמ\"ש הר\"ן בתשוב' שלמעלה תני בירושלמי שם תני שמואל טעה והשמיט פסוק אחד ותירגמו המתרגם יצא אנן אמרינן בכל לשון לא יצא ואת אמרת הכין שמואל כדעתיה דאמר היתה כתובה כהלכתה הלועז יוצא בה בלעז ר' אבהו בשם ר\"א יודע כו' כנ\"ל וסובר הירושלמי דמתני' ה\"ק על פה לא יצא בכל לשון כו' ג\"כ שכתוב' אשורית וקראה תרגום בכל לשון דהוא נמי ע\"פ ותי' שמואל כדעתיה דס\"ל כתובה כהלכתה ר\"ל בלה\"ק וקראה בלעז יצא כיון שתרגם מתוך הכתב דלא כגמרא שלנו ומתניתין לאו משום ע\"פ רק משום שאין מכיר בלעז ואמר כתובה כהלכתה לרבותא אבל הא דתני שמואל הוא אף לגמרא דידן כמ\"ש למטה. ור' אבוה פליג עליו וסובר דבכה\"ג שכתובה אשורית וקרא בלעז אינו יוצא בה אלא דוקא שאינו מכיר בלה\"ק וע\"ז קאמר יודע כו' מהו שיוציא כו' כהדא כל כו'. נמצא לפי הגמרא שלנו דס\"ל שאף למי שאינו מכיר בלה\"ק אפ\"ה כה\"ג אינו יוצא דהוי ע\"פ אינו מוציא אחרים ג\"כ וז\"ש הרמב\"ם וש\"ע בס\"ט אבל אם היתה כו' וכיון שלא יצא כו' והירושלמי דסוטה הוא למ\"ד ק\"ש אינה נאמרת רק בלה\"ק ומדמי למגילה בכה\"ג שלמעלה אמר שם רבי אומר אומר אני ק\"ש אינו נאמר' אלא בלה\"ק מ\"ט והיו הדברים האלה ר' לוי כו' כנ\"ל. וכ\"מ שם בירושלמי דס\"ל דמש\"ש ע\"פ לא יצא בכל לשון כו' היינו שכתובה אשורית וקראה תרגום כו' דהוא נמי ע\"פ כנ\"ל דאמר שם למעלה והוא שתהא כתובה בלעז ר\"ל מ\"ש אבל קורין אותה ללעוזות בלעז. מה אנן קיימין אם כשהיתה כתובה אשורית ותירגמה בלעז הדא דתנינן בכל לשון. ור\"ל הא אמר ברישא דלא יצא בכהאי גוונא אם כשהיתה כתובה לעז ותירגמה אשורית. ר\"ל אפי' תירגמה אשורית הדא הוא דתנינן מה בין ספרים למגילת אסתר אלא שהספרים נכתבין בכל לשון ומגילה אינה נכתבת אלא אשורית. תיפתר שהיתה כתיבה גיגנטון ר\"ל יוני וכמ\"ש בגמרא דיוני כשר תני שמואל כו'. ונראה דקושיא על שמואל נמי לאו משום ע\"פ דגם בתחלה הוא סובר דלאו ע\"פ הוא כמ\"ש אם כו' אם כו' אלא משום דאין יוצא בלעז רק גיגנטון וכמ\"ש כשהיתה כתובה בלה\"ק וקראה בלעז זהו בכל לשון ואינו כשר אלא יוני וקרא בלשון הקודש כנ\"ל ופי' הר\"ן תמוה דאם קושייתו היה מפני בע\"פ ה\"ל להקשות מרישא קראה ע\"פ ועוד דמאי משני מ\"מ ע\"פ הוא אלא ודאי דידע דמקצתה הוי כמתוך (הכתב) כמ\"ש בגמרא שלנו אלא מלשון אחר פריך דס\"ל מ\"ש אבל קורין כו' דוקא בלעז יוני כנ\"ל וכס\"ד מעיקרא בגמ' שלנו וע\"ז תירץ שמואל כדעתיה כו' וכמסקנא דגמ' דבכל לעז איירי מתניתין:","\u0003ואם כתובה. \u0004ברייתא דשמואל הנ\"ל טעה כו' ותרגומו כו' אף שכל המגילה קראה בלה\"ק ולר' אבהו דוקא בשאינו מכיר בלה\"ק וקרא כל המגילה בלשון אחר ולגמרא דידן דוקא שכתובה באותן הלשונות דאל\"כ הוי ע\"פ וכן יש לפרש גמרא שלנו שם ת\"ר השמיט כו' וקראן הקורא כמתורגמן המתרגם כו' דלפי' רש\"י כ\"ז שפת יתר הוא. אבל הפי' הוא שקראן בלשון תרגום לפי שהיו מכירין התרגום ע\"פ לכך נקט כה\"ג יצא דאותו מקצת שהשמיט הוי ככתובה כיון שלא השמיט רובה וז\"ש כמתורגמן כו' דאל\"כ דברים שבכתב אסור לאומרן בע\"פ להוציא רבים י\"ח לכ\"ע וע\"כ איירי אף במבינים לה\"ק דאל\"כ הל\"ל ברייתא דמטושטשת כך מ\"מ ש\"מ דאם כתובה מקצת תרגום דש\"ר לקרותן כה\"ג וכן י\"ל אף לר' אבהו ור\"א ל\"פ אלא אשמואל אבל לא אדתני שמואל דכה\"ג מודה ר\"א כנ\"ל ולפי' זה סיוע להרמב\"ם דיוצא כנ\"ל:","\u0003סי\"א יש למחות כו'. \u0004משום דלסברא ראשונה אינו מוציאן י\"ח כמ\"ש בירושלמי הנ\"ל יודע אשורית כו' כהדא כו' וז\"ש אע\"פ שכתובה כו' דאי לא\"ה אף לסברא שניה אינו מוציאה שכן מפ' הירושלמי הנ\"ל ועוד משום האחשתרנים בני הרמכים שאינו יודע הלעז כמ\"ש בגמ' אטו האחשתרנים כו' וע' בריב\"ש סי' שפ\"ח שצ\"א ע\"ש:","\u0003ס\"יב הואיל ולא. \u0004גמ' שם ה\"ד מתנמנם כו':","\u0003אבל אם. \u0004ירושלמי שם ר' מנשה הוה יתיב קומי ר\"ז ואינמנם א\"ל חזור לך דלא איכוונית:","\u0003סי\"ג לצאת ידי חובתו. \u0004כמ\"ד מצות צריכות כוונה ומתני' לצאת י\"ח:","\u0003וכן כו'. \u0004שם:","\u0003ולא יפסיק. \u0004ירושלמי שם ודורשה ובלבד שלא יפליג עצמו כו':","\u0003ס\"יד הקורא כו' ואם. \u0004ר\"ה כ\"ט א':","\u0003אין כו' וי\"א. \u0004ירושלמי שם אין מדקדקין בטעיותיה' ר' יצחק ור' חננאל הוון יתבין קמי דרב כו' ומפ' דוקא בכה\"ג דהא קי\"ל צריך לקרותה כולה וטעות שהענין משתנה כאלו לא קראה ואמרינן אטו אנן האחשתרנים כו' כו' ש\"מ דמשום קצת תיבות דוקא משום דאיכא קריאה כו' ושם השמיט הסופר אותיות כו' וקראן כו' הא לא קראן לא:","\u0003ס\"טו ודוקא. \u0004גיר' הרי\"ף בעי למימרינהו:","\u0003ולכתחלה כו'. \u0004ובהג\"מ תמה ע\"ז דהא בגמרא אמרינן מ\"ט כולהו כו' וזה לא שייך בחמש מאות איש ואפשר שמנהג זה נתייסד ע\"פ מ\"ש ר' יצחק בר' יהודה לקרות ס\"פ ותחלת פסוק שאחריה בנשימה אחת וכ' הג\"מ שכן נהגו ואף שמ\"מ א\"צ להתחיל רק מן איש מ\"מ חמש מאות איש הוא ענין א' אבל הג\"מ סתר זה מהגמ' הנ\"ל וכת' שכן פסק ר\"צ גאון ועט\"ז:","\u0003ס\"טז צריך שיאמר. \u0004רא\"ש בשם ירושלמי ובנוסחתינו חסר קצת:","\u0003וצריך שיאמר. \u0004ירושלמי שם:","\u0003ס\"יז מנהג. \u0004דנקרא איגרת כמש\"ש י\"ט א' ועמ\"ש בסי' תרצ\"א ס\"ב:","\u0003וכשיגמור כו'. \u0004שם ל\"ב א' תוס' ס\"ד גוללו. אבל לאחר כו':","\u0003חוזר וכורכה כו'. \u0004דלא כמ\"א בשם סה\"י וע' בכ\"ה שאין ממש בדבריו וז\"ל במהרי\"ל פעם א' פתח הקורא ברכת האל הרב אחר הקריאה טרם שכרכו אגרת המגילה וגער בו מהרי\"ל והשתיקו עד שכרכו אגרת המגילה לכרך א' והניחו לפניו ואז חזר והתחיל ובירך וכן הלשון חוזר וכורכה ומברך עכ\"ל ובעל מ\"א לא ראה את ספר מהרי\"ף רק מ\"ש בכה\"ג כידוע והחילוק של סה\"י אין לו שחר:","\u0003יש שכתבו כו'. \u0004וכתבו הג\"מ ומרדכי משום שמחה ולעורר התינוקות שישמעו קריאת המגילה. ובסוטה ל' ב' ר\"נ אומר כסופר הפורס על שמע כו' וכ' הגאונים מכאן נהגו לומר פסוקים של גאולה כל הקהל ביחד כגון בברכת ק\"ש שהש\"ץ מוציאן וכשמגיע למי כמוכה ומלוך אומרין כולם ביחד בקול רם ולא אסור משום דברים שבכתב כמ\"ש בתענית כ\"ח א' אר\"י וכי יחיד כו' אלא כולן נכנסין וקורין אותה ע\"פ כקורא את שמע:","\u0003עוד כתבו. \u0004במדרש מחה תמחה את זכר עמלק אפי' מעל עצים ואבנים:","\u0003ושם רשעים ירקב. \u0004ירושלמי ומ\"ר כד הוה מטי אשר הגלה כו':","\u0003ואין לבטל. \u0004עפ\"ד דפסחים נ\"א א' וריש פ\"ז דב\"מ וירושלמי שם ומ\"ס ס\"פ י\"ד.","\u0003ס\"יח מגילה כו'. \u0004כרב אסי מדחש רב לדר\"א:","\u0003לחזור כו' ואם כו'. \u0004רש\"י שם ור' יוחנן שם י\"ט הקורא כו' דמשמע שאף ביחיד יוצא אתי ככ\"ע. והרי\"ף וש\"פ חולקין ע\"ז. וע' תוס' שם וברפ\"ב דקדושין מ\"ה ב' ד\"ה הוה כו' וע' רא\"ש שם ושם ורש\"י שם אבל הרשב\"א הכריח כדברי הרי\"ף ממ\"ש בירושלמי כל שאמרו ידחה ליום הכניסה ובלבד בי' מ' לעיכובא וכ\"מ דהלכה כרב וע' מ\"מ:","\u0003ויש להסתפק. \u0004אע\"ג דחייבין במגילה דבבה\"מ ג\"כ חייבין ומספקא בפ\"ג דברכות אם חייבין מדאורייתא ואפ\"ה אמרו שם בפ\"ז דאין מצטרפין עם אנשים וער\"ן וטור:","\u0003ואם קראת אותה בצבור כו'. \u0004כל בו בשם הראב\"ד דאמרינן בירושל' על המקדימין ובלבד בעשרה וצ\"ל דבזמנה א\"צ והטעם משום דכולן קוראים כמ\"ש כאן וע' ירושלמי פ\"א הלכה ה'. ובס\"פ כיצד צולין אמר רב וכן לתפלה כו' ועתוס' שם וש\"מ שפי' שאם יש בכה\"ג עשרה שהיחיד השומע בחוץ אם יכול לענות קדוש וקדושה והקשה הר\"ן בספ\"ג דר\"ה היאך מוקים רב למתניתין דשם וכן מי שהיה עובר אחורי בכה\"נ ושמע כו' ואמרי' בפ\"ק דמגילה שרב חש לדר\"א כנ\"ל והצריך י' אפי' בזמנה וע\"ש בר\"ן שדחק בזה אבל לפ\"ז ניחא אבל כ\"ז הוא לדעת האומרים מ\"ש בעשרה הוא לעיכובא אבל ר\"ע חולק ע\"ז וכנ\"ל:","\u0003וכשהיחיד. \u0004תוס' שם לאפוקי ממ\"ש המרדכי בשם ר\"ג דלא יברך משום דר\"א וס\"ל דאף בדיעבד לא יצא דקי\"ל דרב אסי לא אמר אלא לכתחלה כנ\"ל:"]}],["אֵין כּוֹתְבִין \u0010y0\u0011 הַמְּגִלָּה אֶלָּא בִּדְיוֹ, \u0010y1\u0011 עַל הַגְּוִיל \u0010y2\u0011 אוֹ עַל הַקְּלָף, כְּסֵפֶר תּוֹרָה; וְאִם כְּתָבָהּ \u0010y3\u0011 בְּמֵי עֲפָצִים וְקַנְקַנְתּוֹם, כְּשֵׁרָה. כְּתָבָהּ בִּשְׁאָר מִינֵי צִבְעוֹנִים, פְּסוּלָה. \u0010y4\u0011 וּצְרִיכָה \u0010y5\u0011 שִׁרְטוּט כַּתּוֹרָה עַצְמָהּ; וְאֵין הָעוֹר שֶׁלָּהּ צָרִיךְ לְעַבֵּד לִשְׁמָהּ; \u0010y6\u0011 וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ עִבּוּד לִשְׁמָהּ.\nהָיְתָה כְּתוּבָה עַל הַנְּיָר אוֹ עַל עוֹר שֶׁאֵינוֹ מְעֻבָּד, אוֹ שֶׁכְּתָבָהּ עַכּוּ\"ם אוֹ אֶפִּיקוֹרוֹס, פְּסוּלָה; וְדִינָהּ כְּסֵפֶר תּוֹרָה \u0010y7\u0011 לְעִנְיַן הֶקֵּף גְּוִיל וַחֲטֹטְרוֹת חֵתִי\"ן וּתְלִיַּת הֵהִי\"ן וְקוֹפִי\"ן וְכָל גּוּפוֹת הָאוֹתִיּוֹת בְּצוּרָתָן וּבַחֲסֵרוֹת וִיתֵרוֹת. \u0005 הַגָּה: גַּם צָרִיךְ לְכָתְבָהּ \u0010y8\u0011 מִן \u0010c0\u0011 הַכְּתָב \u0006 \u0005(רַ\"ן)\u0006, \u0010y9\u0011 \u0005 וּלְהוֹצִיא \u0006 \u0005 כָּל תֵּבָה מִפִּיו קֹדֶם שֶׁיִּכְתְּבֶנָּה, \u0010y10\u0011 כְּמוֹ בְּסֵפֶר תּוֹרָה \u0006 \u0005(מַהֲרִי\"ל)\u0006; \u0005 וְעוֹשִׂין כָּל פָּרָשִׁיּוֹתֶיהָ \u0010y11\u0011 סְתוּמוֹת, וְאִם עֲשָׂאָן \u0010y12\u0011 פְּתוּחוֹת, \u0006 \u0005 פְּסוּלָה \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב וּפִסְקֵי מהרא\"י \u0010y13\u0011 סִימָן כ\"ג)\u0006; \u0005 וּבְדִיעֲבַד אֵין לִפְסֹל מְגִלָּה מִשּׁוּם חֲסֵרוֹת וִיתֵרוֹת, דְּלֹא גָּרַע מֵהִשְׁמִיט בָּהּ הַסּוֹפֵר אוֹתִיּוֹת, דִּכְשֵׁרָה \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב וְאוֹר זָרוּעַ)\u0006, \u0005 כְּמוֹ שֶׁנִּתְבָּאֵר סי' תר\"צ סָעִיף ג'; \u0006 וּצְרִיכָה עַמּוּד בְּסוֹפָהּ וְחָלָק בְּרֹאשָׁהּ כְּדֵי לְהַקִּיפָהּ בּוֹ; וְיֵשׁ אוֹמְרִים שֶׁצְּרִיכָה תַּגִּין, וְיֵשׁ אוֹמְרִים שֶׁאֵינָהּ צְרִיכָה; \u0005 הַגָּה: וְנָהֲגוּ \u0010y14\u0011 לְתַיְּגָהּ, גַּם נָהֲגוּ שֶׁלֹּא לַעֲשׂוֹת לָהּ עַמּוּד \u0010y15\u0011 כְּלָל בְּסוֹפָהּ. \u0006 \u0005(מַהֲרִי\"ל)\u0006.\nעֲשֶׂרֶת בְּנֵי הָמָן צָרִיךְ לְכָתְבָהּ כְּשִׁירָה, וְלֹא כִּשְׁאָר שִׁירוֹת שֶׁחָלָק עַל גַּבֵּי כְּתָב, אֶלָּא \u0010y16\u0011 מַנִּיחַ חָלָק בֵּין כְּתָב לִכְתָב; וְאִם לֹא עָשָׂה כֵּן, פְּסוּלָה.\nצָרִיךְ \u0010y17\u0011 לְהַאֲרִיךְ בְּוָא\"ו דְּוַיְזָתָא \u0005 בִּכְתִיבָתָהּ, \u0010y18\u0011 וְיֵשׁ אוֹמְרִים בִּקְרִיאָתָהּ \u0006 \u0005(רַ\"ן בְּשֵׁם הָרֹא\"שׁ וּמַהֲרִי\"ל וּבֵית יוֹסֵף בְּשֵׁם א\"ח)\u0006; וְצָרִיךְ לִכְתֹּב אִישׁ בְּרֹאשׁ דַּפָּא, \u0010y19\u0011 וְאֶת בְּסוֹפָהּ.\nאִם תְּפָרָהּ בְּחוּטֵי פִּשְׁתָּן, פְּסוּלָה.\nאִם הֵטִיל בָּהּ ג' חוּטֵי גִּידִים, כְּשֵׁרָה, וּבִלְבַד שֶׁיִּהְיוּ מְשֻׁלָּשׁוֹת; וּמִפִּנֵי שֶׁיֵּשׁ בּוֹ \u0010c1\u0011 פֵּרוּשִׁים שׁוֹנִים, צָרִיךְ לָצֵאת יְדֵי כֻּלָּם וְיַעֲשֶׂה שְׁלֹשָׁה \u0010y20\u0011 תְּפִירוֹת בְּרֹאשָׁהּ וְג' בְּסוֹפָהּ וְג' בְּאֶמְצָעִיתָהּ וּתְפִירָה אַחַת \u0010y21\u0011 בַּחֵלֶק הָרְבִיעִי מִצַּד זֶה וּתְפִירָה אַחַת בַּחֵלֶק הָרְבִיעִי שֶׁמִּצַּד הָאַחֵר. \u0005 הַגָּה: וְאִם אֵין לוֹ גִּידִין יוֹתֵר, מוּטָב לִתְפֹּר הַנִּשְׁאָר בְּחוּטֵי פִּשְׁתָּן מִלְּהַנִּיחוֹ בְּלֹא תְּפִירָה \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פֶּרֶק ב' וְכָל בּוֹ)\u0006; \u0005 אֲבָל אִם יֵשׁ לוֹ גִּידִין יִתְפֹּר כֻּלָּהּ בְּגִידִין; וְהַתְּפִירָה תִּהְיֶה מִבַּחוּץ וְלֹא מִבִּפְנִים \u0006 \u0005(רַבֵּנוּ יְרוּחָם נ\"י ח\"ב בְּשֵׁם א\"ח)\u0006.\nצָרִיךְ לְהַנִּיחַ שִׁיּוּר בְּרֹאשׁ הַיְרִיעָה וּבְסוֹפָהּ, כְּשֶׁתּוֹפְרָם יַחַד, וּבְמַשֶּׁהוּ סַגֵּי.\nאֵין קוֹרִין בְּצִבּוּר \u0010c2\u0011 בִּמְגִלָּה הַכְּתוּבָה \u0010y22\u0011 בֵּין הַכְּתוּבִים; וְאִם קָרָא, לֹא יָצָא אֶלָּא אִם כֵּן הָיְתָה \u0010y23\u0011 יְתֵרָה עַל שְׁאָר הַיְרִיעוֹת אוֹ חֲסֵרָה, כְּדֵי שֶׁיְּהֵא לָהּ הֶכֵּר; אֲבָל הַיָּחִיד קוֹרֵא בָּהּ, \u0010c3\u0011 וַאֲפִלּוּ אֵינָהּ חֲסֵרָה אוֹ יְתֵרָה, וְיוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ; וְדַוְקָא כְּשֶׁהִיא כְּתוּבָה בְּגִלָּיוֹן כְּסֵפֶר תּוֹרָה. \u0010y24\u0011\nמְגִלָּה שֶׁהִיא נְקֻדָּה, וְכֵן אִם כָּתַב בָּהּ בַּדַּף הָרִאשׁוֹן \u0010y25\u0011 בְּרָכוֹת וּפִיּוּטִים, אֵינָהּ נִפְסֶלֶת בְּכָךְ.\nאִם אֵין מְגִלָּה כְּשֵׁרָה קוֹרִים אוֹתָהּ \u0010y26\u0011 בְּחֻמָּשׁ בְּלֹא בְּרָכָה.\nאִם קָרָא בִּמְגִלָּה גְּזוּלָה, \u0010y27\u0011 יָצָא. \u0005 הַגָּה: וְאִם מְבָרְכִים עָלֶיהָ, עַיֵּן לְעֵיל סִימָן תרמ\"ט \u0010y28\u0011 לְעִנְיַן לוּלָב \u0010y29\u0011 הַגָּזוּל, וְהוּא הַדִּין כָּאן. \u0006",["\u0003אלא בדיו\u0004 עיין לעיל בסימן ל\"ב ס\"ג בהג\"ה ובמ\"ב שם:","\u0003על הגויל\u0004 הוא העור שלא נחלק ולא הוסר ממנו רק השער ותקנו שם ומצד הבשר לא הוסר כלום:","\u0003או על הקלף\u0004 עיין לעיל בסימן ל\"ב ס\"ז:","\u0003במי עפצים וקנקנתום\u0004 עיין בט\"ז בשם הכ\"מ דמה שהכשירו במי עפצים היינו עם גומא דממי עפצים בלחוד פסול [וכן הסכים הגר\"א בביאורו דמשניהן יחד נקרא דיו] וכן קנקנתום דמכשרינן היינו במי קנקנתום דאלו קנקנתום לחוד בודאי פסול והגר\"א בביאורו פירש דמה שאמר במי עפצים וקנקנתום היינו שכתב בשניהם מעורבין יחד ועיין לעיל בסימן ל\"ב ס\"ג בבה\"ל ד\"ה שלא וכו':","\u0003וצריכה שרטוט\u0004 היינו על כל שיטה ושיטה:","\u0003כתורה עצמה\u0004 וע\"כ חק תוכות פסול בה ודוקא ברובה אבל במיעוטה כשר בדיעבד דלא גרע מהשמיט לעיל בסימן תר\"צ ס\"ג ע\"ש פרטי הדברים:","\u0003וי\"א שצריך וכו'\u0004 וכן פסק רמ\"א סי' ס\"א:","\u0003לענין היקף גויל\u0004 על כל אות. וה\"ה לכל דבר ולכן בעינן שיהיו שיטותיה שוים גם שיהי' רוחב העמוד ג' למשפחותיכם וכל דיני ס\"ת:","\u0003מן הכתב\u0004 וה\"ה אם אחד מקריא אותו בע\"פ כדי שלא יטעה ואם עבר וכתב בע\"פ שלא מן הכתב י\"א דאסור לקרות בה אלא בשעת הדחק:","\u0003ולהוציא כל תיבה וכו'\u0004 היינו לכתחלה ובדיעבד אין להחמיר אם לא טעה:","\u0003כמו בס\"ת\u0004 היינו אפילו אם כותב אותה מתוך הכתב:","\u0003סתומות\u0004 דנקרא אגרת:","\u0003פתוחות פסולה\u0004 בתשו' ר' משה מינץ סי' י\"ב דין ה' מפקפק ע\"ז ולכן נ\"ל דיש לסמוך עליו בשעת הדחק [מ\"א]:","\u0003ובדיעבד\u0004 פי' שכבר קרא בה וכשאין לו מגילה אחרת יוכל לקרות בה לכתחלה:","\u0003גם נהגו שלא לעשות וכו'\u0004 אבל חלק בראשה מניחין וגולל סופו לתחלתו:","\u0003כלל\u0004 והגר\"א בביאורו מפקפק ע\"ז מאוד:","\u0003מניח חלק\u0004 כפלים מן הכתב:","\u0003להאריך בוי\"ו דויזתא\u0004 למתוח ראשה הכפוף ותהיה כעין זקופה לרמז שנתלו כולם בזקיפה אחת:","\u0003בקריאתה\u0004 שלא יחטוף אותה:","\u0003ואת בסופה\u0004 פי' בסוף השיטה אבל בסוף הדף יכתוב תיבת עשרת [ב\"י]. ובדיעבד אם לא האריך בוי\"ו דויזתא וכן אם כתב אחר תיבת עשרת עוד שיטות כשר ויש מחמירין כשכתב אחר תיבת עשרת עוד שיטות ועיין בשער אפרים סימן נ\"ה כתב דאם יש שם מגילה אחרת כתובה כדינה אין לקרות בזו לכתחלה בצבור אם לא שיש טורח צבור להמתין עד שיביאו הכתובה כדינה יכולים לקרות בזו:","\u0003בראשה\u0004 של כל יריעה ויריעה ועיין בח\"א שכתב דאם תפורה כולה בגידין א\"צ לדקדק כמה תפירות:","\u0003בחלק הרביעי\u0004 כי צריך לשער היריעה כאלו נחלק לד' חלקים:","\u0003בין הכתובים\u0004 הטעם דלא הוי פרסומי ניסא דמיחזי כקורא במקרא משו\"ה ביחיד כשר דבלא\"ה ליכא פרסומי וכל בי עשרה מקרי צבור:","\u0003יתירה וכו'\u0004 היינו שהיתה ארוכה משאר הקלפים למעלה או למטה או חסרה ועי\"ז יש לה היכר לעצמה:","\u0003שהיא נקודה\u0004 ואי ליכא מי שיודע לקרות בטעמים בע\"פ מותר לכתוב גם הטעמים במגילה ולברך עליה דלא גרע מניקוד ומ\"מ אם אין הטעמים במגילה מותר לקרות בלא טעמים כמ\"ש ססי' קמ\"ב:","\u0003ברכות\u0004 ולכתחלה לא יכתוב ברכותיה בה:","\u0003בחומש\u0004 ודוקא כשעשוי החומש בגלילה כמ\"ש סימן קמ\"ג ומשום שי\"א שיוצא בזה בשעת הדחק אבל בחומש שלנו לכו\"ע לא יצא [ב\"ח ומ\"א] והפמ\"ג כתב דראוי גם בזה לקרות בלא ברכה שלא תשתכח תורת מגילה:","\u0003יצא\u0004 דאין גזל בקול:","\u0003לענין לולב הפסול\u0004 צ\"ל לענין לולב הגזול:","\u0003וה\"ה כאן\u0004 ועיין בפמ\"ג דאפילו אם קנאו בשינוי מעשה וכדומה אפ\"ה לא יברך:"],["\u0003 גם צריך לכתבה מן הכתב\u0004 - עיין במ\"ב מה שכתבנו לענין דיעבד והוא בד\"מ בשם הר\"ן ומה שלא הביא הרמ\"א זאת בהג\"ה נראה משום דלא ברירא ליה ד\"ז וראיתו מן הירושלמי יש לדחות בפשיטות דהנה הירושלמי תירץ שני תירוצים על הא דר\"מ אחד שעת הדחק שאני ואחד דר\"מ כתב שני מגילות והראשונה גנז ומדגנז ש\"מ דאפילו בדיעבד אין לקרות בה אבל הבבלי תירץ רק שעת הדחק שאני ונוכל לומר בפשיטות דבשעת הדחק התיר ר\"מ לעצמו לכתבה ולקרות בה לכתחלה ושלא בשעת הדחק לא היה מתיר לעצמו אכן בדיעבד אפשר דשרי לקרות בה וא\"צ לגנוז. ודע עוד דמה שכתב דצריך לכתוב מן הכתב הוא אפילו אם היתה שגורה היטיב על פיו ומה שהתירו לעיל בסימן ל\"ב סכ\"ט לענין תפילין כששגורות בפיו התם משום דמצוי הוא לכו\"ע להיות שגורות משא\"כ במגילה כן מוכח בגמרא:","\u0003 ומפני שיש בו פירושים שונים\u0004 - דרש\"י פי' שמחלק לד' חלקים את אורך היריעה ויהיה תפירה אחת למעלה בסוף רביע והשניה בסוף חציה והשלישית בתחלת הרביע של צד מטה והרי\"ף פי' משולשין כפשוטו שנים בשני ראשי היריעה ואחת באמצע ממש והרמב\"ם מפרש משולשין ג' תפירות בראש היריעה וג' בסופה וג' באמצעיתה וכשיעשה כעצת המחבר יצא ידי כולם:","\u0003 בצבור\u0004 - בטורי אבן פי' דדוקא בזמן שאין קורין את המגילה אלא בצבור והיינו שלא בזמנה דבעי פרסומי ניסא לכן מגילה הכתובה בין הכתובים דליכא פרסומי ניסא לא יצא אבל בזמנה לא חיישינן להא דכתובה בין הכתובים ע\"ש:","\u0003 היחיד קורא בה\u0004 - משמע אף לכתחלה אף שיש לו מגילה כתובה לבדה ויכול לקרות בזו [פמ\"ג] אבל הרי\"ף והרא\"ש והטור כתבו דיצא [ביאור הגר\"א]:"],"\u0010g0\u0011 אֵין כּוֹתְבִין \u0010y0\u0011 הַמְּגִלָּה אֶלָּא בִּדְיוֹ, \u0010y1\u0011 עַל הַגְּוִיל \u0010y2\u0011 אוֹ עַל הַקְּלָף, כְּסֵפֶר תּוֹרָה; וְאִם כְּתָבָהּ \u0010y3\u0011 בְּמֵי עֲפָצִים \u0010g1\u0011 וְקַנְקַנְתּוֹם, כְּשֵׁרָה. \u0010g2\u0011 כְּתָבָהּ בִּשְׁאָר מִינֵי צִבְעוֹנִים, פְּסוּלָה. \u0010y4\u0011 \u0010g3\u0011 וּצְרִיכָה \u0010y5\u0011 \u0010t0\u0011 \u0010s0\u0011 \u0010m0\u0011 שִׁרְטוּט כַּתּוֹרָה עַצְמָהּ; \u0010g4\u0011 וְאֵין הָעוֹר שֶׁלָּהּ צָרִיךְ לְעַבֵּד לִשְׁמָהּ; \u0010y6\u0011 \u0010g5\u0011 \u0010t1\u0011 \u0010m1\u0011 וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ עִבּוּד לִשְׁמָהּ. \u0010g6\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011\nהָיְתָה כְּתוּבָה עַל הַנְּיָר אוֹ עַל עוֹר שֶׁאֵינוֹ מְעֻבָּד, אוֹ \u0010g7\u0011 שֶׁכְּתָבָהּ עַכּוּ\"ם אוֹ אֶפִּיקוֹרוֹס, פְּסוּלָה; \u0010g8\u0011 וְדִינָהּ כְּסֵפֶר תּוֹרָה \u0010y7\u0011 \u0010m2\u0011 לְעִנְיַן \u0010t2\u0011 \u0010s1\u0011 הֶקֵּף גְּוִיל וַחֲטֹטְרוֹת חֵתִי\"ן וּתְלִיַּת הֵהִי\"ן וְקוֹפִי\"ן וְכָל גּוּפוֹת הָאוֹתִיּוֹת בְּצוּרָתָן וּבַחֲסֵרוֹת וִיתֵרוֹת. \u0005 הַגָּה: גַּם צָרִיךְ לְכָתְבָהּ \u0010y8\u0011 מִן \u0010c0\u0011 הַכְּתָב \u0006 \u0005(רַ\"ן)\u0006, \u0010y9\u0011 \u0010m3\u0011 \u0005 וּלְהוֹצִיא \u0010t3\u0011 \u0006 \u0005 כָּל תֵּבָה מִפִּיו קֹדֶם שֶׁיִּכְתְּבֶנָּה, \u0010y10\u0011 כְּמוֹ בְּסֵפֶר תּוֹרָה \u0006 \u0005(מַהֲרִי\"ל)\u0006; \u0005 וְעוֹשִׂין כָּל פָּרָשִׁיּוֹתֶיהָ \u0010y11\u0011 סְתוּמוֹת, וְאִם עֲשָׂאָן \u0010y12\u0011 \u0010m4\u0011 פְּתוּחוֹת, \u0010t4\u0011 \u0010s2\u0011 \u0006 \u0005 פְּסוּלָה \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב וּפִסְקֵי מהרא\"י \u0010y13\u0011 \u0010m5\u0011 סִימָן כ\"ג)\u0006; \u0005 וּבְדִיעֲבַד אֵין לִפְסֹל מְגִלָּה מִשּׁוּם חֲסֵרוֹת וִיתֵרוֹת, דְּלֹא גָּרַע מֵהִשְׁמִיט בָּהּ הַסּוֹפֵר אוֹתִיּוֹת, דִּכְשֵׁרָה \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב וְאוֹר זָרוּעַ)\u0006, \u0005 כְּמוֹ שֶׁנִּתְבָּאֵר סי' תר\"צ סָעִיף ג'; \u0010g9\u0011 \u0006 וּצְרִיכָה עַמּוּד בְּסוֹפָהּ וְחָלָק בְּרֹאשָׁהּ כְּדֵי לְהַקִּיפָהּ בּוֹ; \u0010g10\u0011 וְיֵשׁ אוֹמְרִים שֶׁצְּרִיכָה תַּגִּין, \u0010g11\u0011 וְיֵשׁ אוֹמְרִים שֶׁאֵינָהּ צְרִיכָה; \u0005 הַגָּה: וְנָהֲגוּ \u0010y14\u0011 לְתַיְּגָהּ, גַּם נָהֲגוּ שֶׁלֹּא לַעֲשׂוֹת לָהּ עַמּוּד \u0010y15\u0011 כְּלָל בְּסוֹפָהּ. \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0010g12\u0011 \u0010r5\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011 \u0010r9\u0011 \u0010r10\u0011 \u0010r11\u0011 \u0010r12\u0011 \u0010r13\u0011 \u0010r14\u0011 \u0010r15\u0011 \u0010r16\u0011 \u0010r17\u0011 \u0010r18\u0011 \u0010r19\u0011\nעֲשֶׂרֶת בְּנֵי הָמָן צָרִיךְ לְכָתְבָהּ כְּשִׁירָה, וְלֹא כִּשְׁאָר שִׁירוֹת שֶׁחָלָק עַל גַּבֵּי כְּתָב, אֶלָּא \u0010y16\u0011 מַנִּיחַ חָלָק בֵּין כְּתָב לִכְתָב; \u0010g13\u0011 וְאִם לֹא עָשָׂה כֵּן, פְּסוּלָה. \u0010g14\u0011 \u0010m6\u0011 \u0010r20\u0011 \u0010r21\u0011\nצָרִיךְ \u0010y17\u0011 \u0010t5\u0011 \u0010s3\u0011 לְהַאֲרִיךְ בְּוָא\"ו דְּוַיְזָתָא \u0005 בִּכְתִיבָתָהּ, \u0010y18\u0011 וְיֵשׁ אוֹמְרִים בִּקְרִיאָתָהּ \u0006 \u0005(רַ\"ן בְּשֵׁם הָרֹא\"שׁ וּמַהֲרִי\"ל וּבֵית יוֹסֵף בְּשֵׁם א\"ח)\u0006; \u0010g15\u0011 וְצָרִיךְ לִכְתֹּב אִישׁ בְּרֹאשׁ \u0010t6\u0011 \u0010s4\u0011 \u0010s5\u0011 \u0010s6\u0011 דַּפָּא, \u0010y19\u0011 וְאֶת בְּסוֹפָהּ. \u0010g16\u0011 \u0010r22\u0011 \u0010r23\u0011 \u0010r24\u0011\nאִם תְּפָרָהּ בְּחוּטֵי פִּשְׁתָּן, פְּסוּלָה. \u0010g17\u0011\nאִם הֵטִיל בָּהּ ג' חוּטֵי גִּידִים, כְּשֵׁרָה, וּבִלְבַד שֶׁיִּהְיוּ מְשֻׁלָּשׁוֹת; וּמִפִּנֵי שֶׁיֵּשׁ בּוֹ \u0010c1\u0011 פֵּרוּשִׁים שׁוֹנִים, \u0010g18\u0011 צָרִיךְ לָצֵאת יְדֵי כֻּלָּם וְיַעֲשֶׂה שְׁלֹשָׁה \u0010y20\u0011 תְּפִירוֹת בְּרֹאשָׁהּ וְג' בְּסוֹפָהּ וְג' בְּאֶמְצָעִיתָהּ וּתְפִירָה אַחַת \u0010y21\u0011 בַּחֵלֶק הָרְבִיעִי מִצַּד זֶה וּתְפִירָה אַחַת בַּחֵלֶק הָרְבִיעִי שֶׁמִּצַּד הָאַחֵר. \u0005 הַגָּה: וְאִם אֵין לוֹ גִּידִין יוֹתֵר, מוּטָב לִתְפֹּר הַנִּשְׁאָר בְּחוּטֵי פִּשְׁתָּן מִלְּהַנִּיחוֹ בְּלֹא תְּפִירָה \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פֶּרֶק ב' וְכָל בּוֹ)\u0006; \u0005 אֲבָל אִם יֵשׁ לוֹ גִּידִין יִתְפֹּר כֻּלָּהּ בְּגִידִין; וְהַתְּפִירָה תִּהְיֶה מִבַּחוּץ וְלֹא מִבִּפְנִים \u0006 \u0005(רַבֵּנוּ יְרוּחָם נ\"י ח\"ב בְּשֵׁם א\"ח)\u0006. \u0010g19\u0011 \u0010r25\u0011 \u0010r26\u0011 \u0010r27\u0011 \u0010r28\u0011\nצָרִיךְ לְהַנִּיחַ שִׁיּוּר בְּרֹאשׁ הַיְרִיעָה וּבְסוֹפָהּ, כְּשֶׁתּוֹפְרָם יַחַד, וּבְמַשֶּׁהוּ סַגֵּי. \u0010g20\u0011 \u0010r29\u0011 \u0010r30\u0011\nאֵין קוֹרִין \u0010t7\u0011 \u0010m7\u0011 בְּצִבּוּר \u0010c2\u0011 בִּמְגִלָּה הַכְּתוּבָה \u0010y22\u0011 בֵּין הַכְּתוּבִים; וְאִם קָרָא, לֹא יָצָא \u0010g21\u0011 אֶלָּא אִם כֵּן הָיְתָה \u0010y23\u0011 \u0010g22\u0011 יְתֵרָה עַל שְׁאָר הַיְרִיעוֹת אוֹ חֲסֵרָה, כְּדֵי שֶׁיְּהֵא לָהּ הֶכֵּר; אֲבָל \u0010g23\u0011 הַיָּחִיד \u0010g24\u0011 קוֹרֵא בָּהּ, \u0010c3\u0011 וַאֲפִלּוּ אֵינָהּ חֲסֵרָה אוֹ יְתֵרָה, וְיוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ; \u0010g25\u0011 וְדַוְקָא כְּשֶׁהִיא כְּתוּבָה בְּגִלָּיוֹן כְּסֵפֶר תּוֹרָה. \u0010y24\u0011 \u0010g26\u0011 \u0010r31\u0011 \u0010r32\u0011 \u0010r33\u0011\nמְגִלָּה שֶׁהִיא \u0010t8\u0011 נְקֻדָּה, וְכֵן אִם כָּתַב בָּהּ בַּדַּף הָרִאשׁוֹן \u0010y25\u0011 \u0010t9\u0011 \u0010m8\u0011 בְּרָכוֹת וּפִיּוּטִים, \u0010g27\u0011 אֵינָהּ נִפְסֶלֶת בְּכָךְ. \u0010r34\u0011\nאִם אֵין \u0010g28\u0011 מְגִלָּה כְּשֵׁרָה קוֹרִים אוֹתָהּ \u0010y26\u0011 \u0010t10\u0011 \u0010m9\u0011 בְּחֻמָּשׁ בְּלֹא בְּרָכָה. \u0010g29\u0011 \u0010r35\u0011 \u0010r36\u0011\nאִם קָרָא בִּמְגִלָּה גְּזוּלָה, \u0010y27\u0011 \u0010m10\u0011 יָצָא. \u0005 הַגָּה: וְאִם מְבָרְכִים עָלֶיהָ, עַיֵּן לְעֵיל סִימָן תרמ\"ט \u0010y28\u0011 לְעִנְיַן לוּלָב \u0010y29\u0011 הַגָּזוּל, וְהוּא הַדִּין כָּאן. \u0006 \u0010r37\u0011",{"g":["לשון הרמב\"ם בפ\"ב ממשנה מגילה י\"ז","\u0003במשנה תנן בקנקנתו' פסולה וה\"ה כת' שם ודע שבקנקנתו' פסולה ובמימיו כשרה כו'\u0004 וע' בתוס' שם י\"ח","שם במשנה","מימרא דרבי תנחום ואמרי לה רב אשי שם ט\"ז","טור בשם רמב\"ם","\u0003שם בשם ר\"ח:\u0004 ","משנה שם י\"ז כדמפרש שם י\"ט","טור בשם רמב\"ם","שם בשם ר\"ת","מברייתא דב\"ב י\"ג וכפי' התו' וכ\"כ בספר התרומה ורא\"ש בפי' המשנה פ\"ג דמסכת ידים ואפי' לפי מ\"ש שם לקיים גי' הספרים","טור בשם ר\"ת","שם בשם בעל הלכות גדולות","מימרא דר' שילא שם ט\"ז","טור בשם הירוש'","מימרא דר' יוחנן שם","טור בשם הירושלמי","מימרא דרב שם י\"ט","שם","פירוש רש\"י ותו' ופי' הרי\"ף ופירוש רמב\"ם","מימרא דר' יוחנן י\"ט ושם בתו'","מימרא דרבי יוחנן שם","כפיר' רש\"י וכ\"פ הרי\"ף והרא\"ש ורמב\"ם","אוקימתא דרבא שם","פי' דמפרסים ניסא טפי דכי קיימי בין הכתובים נראה כקורא במקרא רש\"י","טור","שם","רשב\"א בתשו'","אבל לכתחלה אין לכותבה כך דלדעת המרדכי בפ\"ד דמגילה היא פסולה","ב\"י לדעתו","\u0003טור בשם בעל התרומות וכ\"כ רשב\"א בתשובה מדין השופר הגזול ונתבאר בסימן תקפ\"ו:\u0004 "],"t":["\u0003שירטוט. \u0004 ודי בשרטוט שטה ראשונה שהסופרים בקיאים לישר אח\"כ. לבוש מ\"א: ובתשובות חכם צבי סי' צ\"ז חולק וכתב להלכה ולמעשה מגילה צריכה שרטוט בכל השורות ע\"ש. וחק תוכות פסול בה. כנה\"ג מ\"א \u0005(עפר\"ח)\u0006:","\u0003וי\"א שצריך. \u0004 וכ\"פ \u0005(רמ\"א)\u0006 [רמ\"מ] סי' ס\"א:","\u0003היקף. \u0004 וה\"ה לכל דבר לכן בעי' שיהיו שיטותיה שווים מ\"א ע\"ש ועיין בתשובת מהר\"ם מינץ ובכה\"ג מדין כתיבת המגילה:","\u0003כל תיבה. \u0004 צ\"ע דבסי' נ\"ב סעיף ל\"א כתב דדוקא אם כותב ע\"פ צריך להוציא מפיו ומגילה אסור לכתוב ע\"פ. מ\"א ע\"ש:","\u0003פסול'. \u0004 בתשובת רמ\"א סי' י\"ב דין ה' מפקפק על זה ולכן נראה לי דיש לסמוך עליו בשעת הדחק. מ\"א:","\u0003להאריך. \u0004 וכל אלו כשר בדיעבד מ\"א ע\"ש ועיין בגינת ורדים חא\"ח כלל ד' סי' י\"ב \u0005(ועיין בספר אליהו רבא כל תקוני המגלה בענין חסרות ויתרות הכל על נכון)\u0006:","\u0003דפא. \u0004 עיין בשכנה\"ג בהגה\"ת ב\"י אות ז' ובאות ט' כ' דמעשה בא לפניו במגלה שהיו כתובים עשרת בני המן בחצי הדף איש בראש שיטה ועשרת בסוף שיטה אלא שאינו בסוף דפא ופוסל אותה ע\"ש. ובגינת ורדים חא\"ח כלל ד' סי' י\"ב כ' דכשרה ע\"ש:","\u0003בצבור. \u0004 וכל י' מקרי צבור. טור:","\u0003נקודה. \u0004 ואי ליכא מי שיודע לקרות בטעמים בע\"פ מותר לכתוב הטעמים במגילה ולברך עליה באר שבע דף ק\"ט. וכתב מ\"א ומ\"מ נ\"ל דאם אין הטעמים במגילה מותר לקרות בלא טעמים כמ\"ש ססי' קמ\"ב:","\u0003ברכות. \u0004 ולכתחלה לא יכתוב ברכותי' בה הגה\"מ ומרדכי ולבוש וכ\"כ התשב\"ץ. מ\"א:","\u0003בחומש. \u0004 ודוקא כשעושין בגלילה כמ\"ש סי' תמ\"ג אבל בחומש שלנו לכ\"ע לא יצא. ב\"ח ובהגמ\"נ מ\"א:"],"s":["\u0003 (•) \u0004 \u0003ס\"א בש\"ע אין כותבין כו' \u0004 ע' בבר\"י שהביא בשם מהר\"מ פרובנציאל בתשו' כת\"י כת' במעשה שהדפיסו מגילות על (קלף) והצריכו גניזה דפסולים משום חק תוכות ודילמא אתי למטעי להכשירם אבל בנייר לא אתי למטעי ע\"ש ועיין פר\"ח דאם דפוס' רובא פסולה אבל כתובה רובה כשר ודלא כספר הזכרונות כו' ועיין בספר קרבן נתנאל שהשיג עליו דמדמי להשמיט הסופר כו' דזאת דנכתב שלא כהוגן גרע כמ\"ש רש\"י דף ט' והבר\"י הליץ בעד הפר\"ח דדעתו דהתוספות פליגי על רש\"י בזה ע\"ש ולענין דפוס אם הוא חק תוכות דעת כמה תשובות שהם נידון ככתיבה ועיין לעיל סימן רפ\"ד וביו\"ד הל' ס\"ת ועיין בתשב\"ץ ח\"א סימן ח' דמגילה בכת' מאשיט (והוא כעין משוטא שלנו) פסולה והביאו בכנה\"ג ותמה על הפוסקים (שהשמיטו) ממשנתינו דתני עד שתהה כתובה אשורית ע\"ש וקצרתי כאן:\n\u0003 (א) \u0004 \u0003שירטוט \u0004 עבה\"ט ומ\"ש בשם הח\"צ ע' בר\"י שכנה\"ג כת' דהחדר על דבר ה' יחזור אחר משורטטת כולה ומ\"מ משורטטת שיטה ראשונה בדיעבד כשירה ואם אין משורטטת כלל פסולה אפי' בדיעבד:","\u0003ס\"ב בש\"ע או שכתב' עכו\"ם כו' \u0004 ועיין בפר\"ח שכת' דכ' בשמאל כשר בדיעבד אף דבתפילין פסול ובבר\"י למד מזה דאם כתבה אשה כשירה ובשיורי ברכה שם הביא ראיה מדמייתי הסמ\"ג ראיה לענין עיבוד לשמה ממגילה הכתובה בין הכתובים דיצא וא\"כ ה\"ה לענין כתיבת אשה דכשירה לכתיבת נביאים וכתובים כמ\"ש התוס' בגיטין דף מ\"ד וע' בח\"צ סימן צ\"א מ\"ש לתרץ קושית הרא\"מ לענין שירטוט דשרטוט שאני דהא חזי ליה דלא משורטט כו' ולענין כתיבת אשה לא שייך זה ובמח\"ב הביא דבעל מעשה רוקח הלכות מגילה פוסל מגילה שכתבה אשה או קטן ומח\"ב דחה ראיותיו וגם כת' דבספר מטה יהודה כת' להכשיר בכת' בשמאל או קטן שכתב עיין שם. אך מ\"ש לדחות ראיות הספר מעשה רוקח מסה\"ת שהביא הב\"י סימן ל\"ב ונדחק בזה עיין מ\"ש ביד אפרים בגליון הפר\"ח שהבאתי מסה\"ת ג\"כ והרוא' יראה שאין לדחות כמ\"ש המח\"ב. ונראה דגם הפר\"ח אפשר דלא מכשי' אלא בדיעבד שכבר קרא בה אבל לא לקרות לכתחלה ונראה דאם יש למצוא אחרת בקל יקרא שני' בלא ברכה וה\"ה בכתיבת אשה או קטן:","\u0003היקף. \u0004 ועיין בר\"י בשם בעל כתר כהונה בכת\"י כל שיש ביריעה לכתוב ג' דפי' אף אם לא נכתב אלא דף א' כשר בדיעבד בס\"ת וכ\"ש במגילה ע\"ש וביו\"ד סימן רע\"ב ועיין בסנהדרין דף ך' כי מטו למגילת אסתר אמרי הא לא בעי מטפחת ע\"ש ובמו\"ק כת' בעיא מטפחת פשוט בחלק דף ך' עיין שם ובאמת הוא בש\"ס להיפך רק בשאילת יעב\"ץ כת' דקשיא ליה דמה\"ת נאמר דלא בעי דהא מטמאה הידים ועיקר הטעם דטומאת ידים משום דר' פרנך שלא יאחזם ערומים בלא מטפחת ואפשר דמה\"ט קפיד עלייהו ר\"י למימרא דליתא אלא בעי מטפח' עיין שם ואין המנהג כדבריו ואין נזהרים כלל מליקח המגילה בלא מטפחת והיינו בפשיטות דברי הש\"ס דלענין זה אמרינן כיון דנקראת אגרת בלא מטפחת סגי לה ואע\"ג דנקראת ספר היינו לענין הדברים שהם הכשר הכתיבה כגון שרטוט והקיף הגויל אבל בדברים שאחר בכתיבה כאיגרת דמי ואף על גב שמטמאת הידים ניטלת ערומה כמו תפילין ועיין במג\"א סי' קמ\"ז שדעתו שיש ליזהר במגילה שנכתבה כדינה ובפמ\"א ח\"א סימן ע\"ו כת' שאין העולם נזהרים והביא שם מש\"ס בסנהדרין וכן בשבו\"י סימן י\"א דעתו להתיר אף במגילה עיין שם שכת' שמה\"ט תיקון שני עמודים בס\"ת מפני שאסור לאחוז ערום משא\"כ כתבי קודש ע\"ש ועיין בא\"ר סימן קמ\"ז דמפרש מ\"ש בהג\"ה שם וטוב להחמיר אם לא נטל ידיו דקאי אמגילה ואפי' בסתם ידי' ובידוע שמטונפות יש להחמיר אף בשאר כתבי הקודש ע\"ש והעולם אין נזהרים ליטול סתם ידים קודם נטילת המגילה בידם וטוב להחמיר כמ\"ש בא\"ר:","\u0003פסולה. \u0004 ע' בשערי אפרים שער ו' ובפתחי שערים שם ומ\"ש במג\"א תשו' רמ\"א הוא ט\"ס וצ\"ל רמ\"מ הוא תשו' מהר\"מ מינץ ועיין מה שכת' שם על דברי הא\"ר בזה:","\u0003להאריך. \u0004 עבה\"ט ועיין בשב יעקב חלק יו\"ד סי' נ\"ד בדין מגילה אחת שנמצא כתוב בה תיבת ליהודים בתוספות ה' בין ו' לדלת כו' והבאתי הדברים בשערי אפרים שער ו' סעיף נ\"ב ע\"ש ובפתחי שערים איך יש לנהוג בזה וע\"ש סעיף נ\"א תיקון מגילה לתועלת הסופרים עפ\"י סדר א' ב':","\u0003דפא. \u0004 עבה\"ט ועיין בספרי שו\"ת בית אפרים סימן ע\"ב באריכות בענין זה ובענין מה שנוהגין לכתוב עשרת ב\"ה באותיות גדולות ע\"ש ושם מבואר דגם יש למנוע לכתחלה מה שכותבין רמז שם הקדוש בר\"ת או בס\"ת באותיות גדולות עיין שם ובשערי אפרים ובפתחי שערים שם ועיין שם בשם מח\"ב שכת' בשם זרע אמת במגילה שלא כת' בעמוד האחרון כ\"א ג' או ד' שיטות ולא גמר בסוף הדף ולא סיים באמצע שיטה כשירה לקרות בה לכתחלה עיין שם ועיין בבר\"י בשם מהר\"מ אם היתה מגילה כתובה למפרע לא יצא ומהר\"ש הלוי מגמגם בדבר:","\u0003 (סי\"א בש\"ע) לענין לולב הגזול \u0004 כצ\"ל ועיין בפר\"ח סימן תקפ\"ו שכ' לענין שופר גזול דמברך ולדידיה ה\"ה כאן דהא דין מגילה נלמד מדין שופר בזה אך בבר\"י כת' בשם המאירי שיש מחמירים במגילה אף שמכשירים בשופר ע\"ש ולפי\"ז דאף המכשירים במגילה עכ\"פ גרע משופר שלא לברך אלא דבבר\"י כת' שצריך טעם למה גרע מגילה משופר. ומ\"מ נראה שאין לברך לא במגילה ולא בשופר דספק ברכות להקל ואם הבעלים של השופר או המגילה שם בבה\"כ ויוצאים בשמיעה או בקריאה זו נראה דשפיר מברך כיון דלדידיה אין גזל והוא מתכוין לצאת ג\"כ בברכה אין כאן בוצע ברך כלל:"],"m":["\u0003כתורה עצמה\u0004. מיהו די בשרטוט שיטה ראשונה שהסופרים בקיאים ליישר אח\"כ (לבוש) עסי' ל\"ב ס\"ו וחק תוכות פסול בה (זכרונות כ\"ה):","\u0003ויש אומרים שצריך\u0004. וכ\"פ רמ\"מ סי' ס\"א:","\u0003לענין היקף גויל\u0004. וה\"ה לכל דבר ע' בהג\"ה ולכן בעי' שיהיו שיטותי' שוים וכ\"כ בתשב\"ץ וע' במנחות דף ל\"א ע\"ב בתוס' וכ\"כ בתשו' מהר\"מ סי' שנ\"א שיהא רוחב העמוד ג' למשפחותיכם וכל דיני ס\"ת (עיין בתשו' מהר\"מ מינץ ובכנסת הגדולה מדין כתיבת המגילה):","\u0003ולהוציא כל תיבה\u0004. צ\"ע דבסי' ל\"ב סל\"א כ' דדוקא אם כותב ע\"פ צריך להוציא מפיו ומגיל' אסור לכתוב ע\"פ וגם הטור וסמ\"ג לא כתבו שצריך להוציא מפיו אלא גבי תפילין וא\"כ קשה על הרב\"י שכתבו גם בה' ס\"ת דהא בס\"ת צריך שיכתו' מתוך הכתב ואם כן א\"צ להוציא כל תיבה מפיו ואפי' את\"ל דמיירי שאחר מקרא לו בע\"פ מכל מקום ה\"ל לפרש וצ\"ע:","\u0003פתוחו' פסול'\u0004. תשו' רמ\"א סי' י\"ב דין ה' מפקפק ע\"ז ולכן נ\"ל דיש לסמוך עליו בשעת הדחק עס\"י ועסי' קמ\"ג סס\"ג:","\u0003ובדיעבד\u0004. פי' שאין לו מגילה אחרת או שכבר קראה בה:","\u0003צריך להאריך וכו'\u0004. נראה דכל זה כשר בדיעבד ועסי' תר\"צ ס\"ג וע' רמ\"מ סי' ס\"א כמה דינים בענין חסירות ויתירות ויש נוהגין בענין אחר ע' בס' כ\"ה:","\u0003בצבור\u0004. וכל י' מקרי צבור (טור מ\"צ ש\"ג):","\u0003ברכות ופיוטים\u0004. ול\"ד לכתוב' בין הכתובים דהתם אין ניכרת שהיא מגילה משא\"כ הכא (רשב\"א סי' ק\"נ) (ובתשב\"ץ סי' רכ\"ג כתב שלא יהא ברכותי' כתובים בה לכתחלה) וכ\"כ הג\"מ ומרדכי ולבוש:","\u0003בחומש\u0004. כי י\"א שיוצא בזה בשעת הדחק ודוקא כשעשוי בגליל' כמ\"ש סי' קמ\"ג ס\"ב אלא שיש בו פסול אבל בחומש שלנו לכ\"ע לא יצא (ב\"ח וכ\"מ במרדכי ובהגמ\"נ): ש\"ץ שאינו בקי בנגינ' בע\"פ ואין שם מי שיודע להקרות לש\"ץ מותר לכתוב הטעמים במגיל' דלא גרע מניקוד (ב\"ח) ומ\"מ נ\"ל דאם אין הטעמים במגיל' מותר לקרות בלא טעמים כמ\"ש ססי' קמ\"ב:","\u0003יצא\u0004. דאין גזל בקול:"],"r":["\u0003ס\"א על הגויל או כו' כס\"ת. \u0004שם על הספר ובגמרא שם מנלן אתיא כתיבה כתיבה כו' ואזיל לשיטתו שפסק בפ\"א מהלכות תפילין דס\"ת אינו נכתב כ\"א בגויל או בקלף וכ\"פ בש\"ע י\"ד סי' רע\"א ס\"ג וכמ\"ש בירושלמי פ\"ק דמגילה וצריך שיהא כותב על הגויל במקום שיער ועל הקלף במקום נחשתן ואם שינה פסול משמע דלא כשר אלא אלו וכן אמרו בפ\"ק דמ\"ס ובב\"ב י\"ד א' א\"ל בגויל ששה בקלף בכמה כו' ומ\"ש בשבת ע\"ט ב' דתנא דבי מנשיא כו' ואוקמוה בס\"ת ההיא יחידאה היא:","\u0003ואם כתבה כו'. \u0004וכ\"פ בס\"ת ואין ר\"ל בכל א' לחוד דפסול קנקנתום במתניתין ומשמע שאינו דיו וה\"ה לס\"ת כמ\"ש בשבת ק\"ג ב' כתבה שלא בדיו כו'. ובירושלמי פ\"ק דמגילה הל\"מ שיהיו כותבין בדיו וכן מי עפצים משמע בגיטין י\"ט א' שאינו דיו אלא בשניהם יחד שאז הוא דיו וקא משמע לן אף שאינו נמחק כמ\"ש בעירובין י\"ג א' ואפילו הכי מותר ופסק כר\"י משום ר' מאיר שאמר לכל מטילין כו' כמ\"ש פרק א' מהלכות תפלין וזהו לשונם כיצד מעשה הדיו מקבצין העשן של שמנים כו' ושורהו במי עפצים וכיוצא בו וכותב בו שאם תמחקנו היה נמחק וזהו הדיו שמצוה מן המובחר לכתו' בו סת\"מ ואם כת' שלשתן במי עפצים וקנקנתום שהוא עומד ואינו נמחק כשרים אם כן מה מיעטה ההלכה שנאמר למשה מסיני שיהיו כתובים בדיו למעט שאר מיני צבעונים כגון האדום וירוק וכיוצא בהן שאם כת' בסת\"מ אפילו אות אחת בשאר מיני צבעונים או בזהב הרי אלו פסולין וכן כת' הרא\"ש בהלכות קטנות וז\"ש כאן כתבה בשאר כו' וזה לשונו בפירושו לפרק שני דסוטה ראיתי בארץ ישראל מרחיקין כתיבת ס\"ת באחד ממיני הדיו נקרא בערבי חיב\"ר אלא בדיו ממש והנה טעה בפסק הלכה מן הגמרא שהדבר האחרון הנאמר בגמרא בזה הענין מ\"ש בכל מטילין קנקנתום חוץ מפרשת סוטה שבמקדש וכת' המעתיק שם אמר כמעתיק ראיתי לבאר מהו חיבור כפי שפירשו הגאונים החיב\"ר הוא הדיו של עפצים ומטילין בתוכו הקנקנתום והוא מין ממיני העפר המשחיר ואינו נמחק וכן כת' ר\"ח ז\"ל כו' עיין שם:","\u0003וצריכה שרטוט. \u0004על כל שטה ושטה דלא כלבוש ומ\"א ושגגה בידם דבתפלין דאין צריכין שרטוט אמרינן כן כמ\"ש בתוספות דגיטין ו' ב' בדבור המתחיל אמר ר\"י כו' ואם תאמר דאמר כו' ואומר ר\"ת כו' ואומר ר\"ת כו' וכן באג\"ש אבל מזוזה וכל דבר שצריכה שירטוט על כרחך על כל שיטה בעינן ועיין שם וברא\"ש:","\u0003ואין העור כו'. \u0004אזיל לשיטתו שפסק דאף מזוזה אינה צריכה עיבוד לשמה ואע\"ג דבס\"ת קיימא לן דצריך עיבוד לשמה כמו שאמרו בגיטין נ\"ד ב' וכן פסק בפרק עשירי מהלכות ספר תורה ובפרק א' מהלכות תפילין סבירא להו דלא אמרו אלא בספר תורה וכן תפילין דאיקרי תורה כמ\"ש בשבת כ\"ח ב' וק\"ח א' אבל שאר דברים כגון ספרים ומזוזה אע\"ג דדינם כספר תורה לא ולמד ממ\"ש במנחות מ\"ב ב' תפילין יש כו' ספרים ומזוזות כו' וכפירוש רש\"י שם דבור המתחיל תפלין כו' ודבור המתחיל ונקחין כו' ואין לנו מספרים אלא מגילה ועיין תוספות שם דבור המתחיל תפלין כו' וכן פירש הרמב\"ם כו' עיין שם ולמד עוד ממ\"ש בסנהדרין מ\"ח ב' תנאי היא דתניא כו' ופסק כתנא קמא וכרבא וכפירוש רש\"י שם וכמ\"ש בפרק שני מהלכות תפילין ואע\"ג דאית בהו שי\"ן וכמו שאמרו שבת כ\"ח ב' אלא לעורן והאמר אביי שי\"ן כו' והוא הדין כאן במגילה וכן במזוזה ואע\"ג שבמנחות מ\"ב ב' אר\"י אמר רבי עשאה כו' כתנאי והוא פסק כשמואל כמו שאמרו בפרק ראשון מהלכות ציצית פסק כסוגיא דסוכה ט' א' ובית הלל לית להו דר\"י כו' שאני התם כו' וסוגיא דמנחות כבית שמאי:","\u0003ויש אומרים שצריך. \u0004הוא דעת רבינו תם שכת' במנחות שם דבור המתחיל עד כו' אומר רבינו תם דהלכה כרבן שמעון בן גמליאל דסוגיא דהניזקין כוותיה והא דפרק נגמר הדין דפליגי אביי ורבא כו' רבינו תם ור\"ח פירשו דרבא כרבן שמעון בן גמליאל דבעי עיבוד לשמה ועל כרחך הזמנה לאו מילתא דאם לא כן אפשר בחיתוך עור ובתיקונים קטנים כו' וכן כת' בסנהדרין שם עיין שם וכן פסק במזוזה ועיין סימן ל\"ב ויורה דעה סימן רפ\"ח:","\u0003ס\"ב או על. \u0004זהו דיפתרא כמ\"ש בגמרא שם:","\u0003או שכתב. \u0004גיטין מ\"ה ב':","\u0003ודינה כספר תורה כו'. \u0004מרדכי והגהת מיימוני בשם רבינו תם וכמו שאמרו הר\"ן בשם הרמב\"ן דמגזירה שוה דכתיבה נלמד דבעיקר הכתיבה דינה כספר תורה ונכתב ואמת ללמד אף תקון הכתיבה כמו שירטוט דינה כספר תורה ונכתב ספר ללמד אף דבר שאינה גופה כגון התפירה דינה כספר תורה והקילו בה לפי שאינה גופה ממש בתפרה בשלשה חוטין כו' ולכן אמרו שהקורא פושט כאגרת שהיא דבר שחוץ מגופה שלכן אמרו הקורא את המגילה עומד כו' מה שאין כן בתורה ובפרק קמא דמגילה בירושלמי מה בין ספרים למגילת אסתר שהספרים נכתבין בכל לשון כו' משמע הא לכל דבר זה וזה שוין. ושם פרק שני סוף הלכה ב' כתוב אחד אומר ספר וכתוב אחד אומר איגרת הא כיצד קל הקילו בתפירתה כו' משמע דדוקא בתפירתה הקילו ולא בשאר דבר:","\u0003לענין היקף גויל. \u0004מנחות כ\"ט א' ל\"ד א':","\u0003וחטוטרות חתי\"ן. \u0004שם כ\"ט ב':","\u0003ותליית ההי\"ן. \u0004שם:","\u0003וקופי\"ן. \u0004שבת ק\"ד א':","\u0003וכל גופות כו'. \u0004שם ק\"ג ב':","\u0003ובחסרות ויתירות. \u0004מנחות שם ועיין תוספות שם דבור המתחיל אבל יתירות כו' וכמש\"ש כ\"ט א' ל\"ד א' אפי' קוצה של יו\"ד וער\"ן פ\"ב דמגילה:","\u0003גם צריך. \u0004מגילה י\"ח ב' לימא מסייע ליה כו' מיתבי אמר רשב\"א כו'. ובירושל' פ\"ד דמגילה הלכה א' ר\"ז בשם רב חננאל אפי' רגיל בתורה כעזרא לא יהא הוגה מפיו וקורא כמ\"ש בברוך כו' והתניא מעשה בר\"מ שהיה באסיא ולא היה שם מגילה כתובה עברית וכשבה מפיו וקרייה אין למדין משעת הדחק וי\"א שתים כת' כת' את הראשונה מפיו וכת' את השניה מתוך הראשונה וגנז את הראשונה וקרא בשניה:","\u0003ולהוציא כל תיבה כו'. \u0004מנחות ל' א' וע\"ש תוס' ד\"ה ומשה כו' וכ\"כ המרדכי בה\"ק סי' תתרנ\"ז מכאן יש להוכיח דסת\"מ הסופר צריך להוציא בפיו כו'. וכ\"כ כל הפוסקים וכ\"פ בטוש\"ע י\"ד סי' רע\"ד ס\"ב ומשמע דאף שכות' מתוך הכתב דהא ס\"ח א\"א לכותבה שלא מן הכתב ומ\"ש בסי' ל\"ב סל\"א אם אינו כו' תפלין שאני ועמ\"א שם והוא דעת הרי\"א שדייק מלשון הסמ\"ג שכת' ואסור לאדם אחר להקרות לסופר אא\"כ חוזר כו' ול\"ד דלרבותא נקט אע\"ג דכשאחר מקרא אותו ל\"ל לטעות כמ\"ש בברכת כהנים מ\"מ צריך כמו שמצינו במשה אע\"ג דהקב\"ה אומר מ\"מ משה חוזר ואומר וכ\"ד כל הפוסקים שלא חילקו וכ' סת\"מ אע\"ג דס\"ת צריך מן הכתב:","\u0003ועושין. \u0004דנקרא איגרת:","\u0003וצריכה כו'. \u0004ב\"ב י\"ג ב' וע\"ש תוס' ד\"ה ועושה. נראה לר\"י דגרסינן ועושה בראשו כדי היקף ובסופו כדי לגלול עמוד וכן גי' הגאונים שם י\"ד א' כל הספרים נגללין לתחלתן ושם ב' ספר עזרה לתחלתו נגלל ובירושלמי פ\"ק דמגילה הלכה י\"א ועושין עמוד לספר בסופו לתורה מכאן ומכאן לפיכך גוללו הספר לתחלתו והתורה לאמצעיתה וכן במ\"ס פ\"ב ובידים פ\"ג רי\"א שבסוף אינו מטמא עד שיעשה לו עמוד וע' ר\"ש שם והרא\"ש ואף לרשב\"א דמקיים גי' הספרים ומחלק בין מדביק כו' מודה דבספרים לחוד עושה עמוד בסופה כו':","\u0003וי\"א צריכה תגין וי\"א שא\"צ כו'. \u0004ער\"ן פ\"ב וסברא ראשונה ס\"ל דהוא דבר שבגופה ודינה כס\"ת כנ\"ל וס' אחרונה ס\"ל דתגין לאו מגוף הכתיבה כמ\"ש במנחות שמצאו להקב\"ה קישר כתרים כו' ע\"ש וכל שאינו מגוף אינו מעכב ולא אמרינן דנקראת ספר מדאצטריך למילף על הכתיבה בקומוס כו' על כו' מג\"ש דכתיבה כתיבה ולא יליף מספר וע' ר\"ן ורשב\"א אבל בספי\"ב דשבת מ' דבלא זיונין אינו אותיות כלל וער\"ן ובמרדכי פאדווא וע' מ\"ש בסי' ל\"ה ס\"ג:","\u0003גם נהגו. \u0004ע' ב\"ח וכ\"כ ט\"ז ס\"ק ב' והוא תמיה גדולה וצע\"ג:","\u0003ס\"ג שחלק ע\"ג כתב כו'. \u0004ל' הטור וכפירש\"י שם וער\"ן ומרדכי שם:","\u0003ואם לא. \u0004ירושלמי פ\"ג הל' ח' עשרת בני המן ומלכי כנען כו' למצוה או לעכב כו' עבר ר' בא בר זבדא ושאלינן ליה ואמר בשם רב לעיכוב:","\u0003ס\"ד צריך להאריך. \u0004לשון הטור ומשמע מדבריהם כלשון ראשון בכתיבתה מדכת' בסי' הזה בדיני כתיבה:","\u0003בכתיבתה וי\"א. \u0004רא\"ש ור\"ן:","\u0003וצריך כו'. \u0004ירושל' שם אר\"י בר בון צריך שיהא איש בריש דפא ואת בסופה שניץ ונחית כהדין קונטרא ר\"ל כמין ב' שנצין של כיס ושוה מב' צדדין כמו משקולת הבנאים וע' במ\"ס שם. ומ\"ש בריש דפא ר\"ל בריש שיטה ובסוף שיטה ודלא כי\"מ בריש דפא בריש העמוד דאל\"כ מה בא ריב\"ב להוסיף אדר\"י בשם רב דאמר שם עשרת בני המן כו' ושירת מ\"כ כו' אריח ע\"ג כו'. ומזה נמשך מה שכותבים עשרת בני המן בעמוד בפ\"ע ובאותיות רבתות. ושיבוש הוא דהא לא נמסר לנו לכתו' עשרת בני המן באותיות דא\"ב רבתא. אלא העיקר דמש\"ש בריש דפא היינו בריש השיטה כנ\"ל. וריב\"ב הא גופא קמ\"ל דאי מדר\"י בשם רב ה\"א כיון דנחלקה עשרת בנ\"ה מכל השירות והושווה לשירות מ\"כ לענין שנכתבו שתיהן לבד אריח ע\"ג אריח כו' כנ\"ל וכמ\"ש בגמ' א\"כ לגמרי נשווינהו לא לכתוב בתוך עשרת בנ\"ה התיבה שלפניה כמו בשירת מלכי כנען שמתחלת מלך כו' וז\"ש ריב\"ב צריך כו' איש בריש כו' וכנ\"ל בריש שיטה ובסוף שיטה כעין כיס וב' שנצין כנ\"ל וכשאר אותיות המגילה:","\u0003ס\"ו ומפני שיש בה. \u0004דרש\"י ותוס' פי' א' באמצעיתה וב' בחלקי' הרביעית וראיה ממ\"ש במכות ט' ושלשת שיהו משולשין כו'. ורי\"ף פי' שנים בקצוות וראיה ממ\"ש בעירובין נ\"ז שלשה כפרים המשולשין כו' וכן בבכורות ל\"ח גבי מומין וע' פ' הערל פ' ע\"ש וכן פי' הרמב\"ם אלא שפי' ג' חוטין בכל תפירה כמו עגלה משולשת ועז משולשת כו' וע\"ש בתרגום וע' ברא\"ש שם ובתוס' וע' בתוס' דבכורות ל\"ט א' ד\"ה שיהו כו':","\u0003ואם אין כו'. \u0004כמ\"ש בב\"ב קס\"ב ב' מסייע כו' ולא תתמה כו'. מרדכי והג\"מ פ\"ב ס\"ק ס' והטעם דצריך שיהא כולה חפורה מראש עד סוף שיהא ספר אחד לבד שיור התפר כמ\"ש בטוש\"ע י\"ד סי' ער\"ה ס\"א וכמ\"ש בגיטין ס' א' ספר שחסר אפי' כו' ופי' הרא\"ש שאין תפורה עמו וכמ\"ש שם ס\"ד ובירושלמי פ\"ג דמגילה תיפורה הל\"מ וכ\"כ הרמב\"ם פ\"ב המגילה צריכה שתהא תפורה כולה עד שיהיו כל עורותיה מגילה אחת:","\u0003אבל אם. \u0004שכשירה משמע דיעבד:","\u0003והתפירה כו'. \u0004מ\"ס פ\"ב הלכה י\"א:","\u0003ס\"ז בראש היריעה ובסופה. \u0004ירושלמי פ\"ק דמגילה צריך שיהא משייר מלמעלן ומלמטן וכן פירש\"י והרי\"ף והרא\"ש:","\u0003ובמשהו סגי. \u0004טור:","\u0003ס\"ח לא יצא. \u0004שם וכ\"כ הרי\"ף ורמב\"ם ורא\"ש וטור דלא כר\"ן:","\u0003אבל היחיד כו'. \u0004רמב\"ם אבל הרי\"ף ורא\"ש וטור כתבו דיצא:","\u0003ודוקא. \u0004רש\"י שם ד\"ה הכתובה כמ\"ש רשב\"א סי' ש\"ע דנקראת ספר ואינה נקראת איגרת אלא לענין תפירה כנ\"ל:","\u0003ס\"ט מגילה שהיא כו' וכן כו'. \u0004אע\"ג דס\"ת נפסלת בניקוד כמ\"ש במ\"ס פ\"ג הלכה ז' ספר שפסקו ושנוקד כו' אל יקרא בו וכן אם כ' ברכות כמ\"ש במגילה ל\"ב א' כדי שלא יאמרו ברכות כו' מ\"מ כאן אינה נפסלת דלא גרע מחסירות ויתירות אבל לכתחילה אסור כמ\"ש מרדכי והג\"מ:","\u0003ס\"י אם אין כו'. \u0004טור כמו לולב היבש שיוצא בשעת הדחק כמ\"ש בפ\"ג דסוכה אין שעת הדחק ראיה. ובירוש' פ\"ב הלכה ג' בין כמ\"ד כולה בין כו' ובלבד מספר שלם אם היתה כתובה חומשין אין קוראין בה ברבים א\"ר תנחומא מפני ההדיוטות וז\"ש הטור חומשין וכמ\"ש בגיטין לענין ס\"ת:","\u0003בלא ברכה. \u0004שם כמו לולב כמ\"ש בסי' תרמ\"ט ס\"ו:","\u0003ס\"יא אם. \u0004כמו בשופר שאמרו בירושלמי פ\"ג דסוכה מה בין שופר כו' הכא בקולו הוא יוצא ויש קול אסור בהנייה ע\"ש:"]}],["הַקּוֹרֵא אֶת הַמְּגִלָּה מְבָרֵךְ לְפָנֶיהָ ג' בְּרָכוֹת: עַל מִקְרָא מְגִלָּה, וְשֶׁעָשָׂה נִסִים, \u0010y0\u0011 \u0010y1\u0011 וְשֶׁהֶחֱיָנוּ; וּבַיּוֹם אֵינוֹ חוֹזֵר וּמְבָרֵךְ שֶׁהֶחֱיָנוּ; \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּאַף \u0006 \u0005 בַּיּוֹם מְבָרֵךְ: שֶׁהֶחֱיָנוּ \u0006 \u0005(טוּר בְּשֵׁם רַבֵּנוּ תָּם וְהָרֹא\"שׁ וְהַמַּגִּיד)\u0006, \u0005 וְכֵן נוֹהֲגִין בְּכָל מְדִינוֹת אֵלּוּ; \u0010y2\u0011 וְאֶחָד יָכוֹל לְבָרֵךְ וְשֵׁנִי קוֹרֵא \u0006 \u0005(הַגָּהוֹת \u0010y3\u0011 אֲשֵׁרִי פ\"ג)\u0006; וּלְאַחֲרֶיהָ נוֹהֲגִין לְבָרֵךְ: \u0010y4\u0011 הָרַב אֶת רִיבֵנוּ וכו'. \u0010y5\u0011 אִם לֹא בֵּרַךְ לֹא לְפָנֶיהָ וְלֹא לְאַחֲרֶיהָ, יָצָא. \u0005 הַגָּה: וְנָהֲגוּ לוֹמַר בַּלַּיְלָה: אֲשֶׁר הֵנִיא, \u0010y6\u0011 אֲבָל \u0006 \u0005 לֹא בַּיּוֹם \u0006 \u0005(כָּל בּוֹ וּבֵית יוֹסֵף בְּשֵׁם א\"ח)\u0006, \u0010y7\u0011 \u0005 וְאֵין לְבָרֵךְ אַחֲרֶיהָ אֶלָּא \u0006 \u0005 בְּצִבּוּר. \u0010y8\u0011 \u0006 \u0010c0\u0011 \u0010c1\u0011\nאֵין לָשׂוּחַ בְּעוֹד שֶׁקּוֹרִין אוֹתָהּ. \u0010y9\u0011\nאַף עַל פִּי שֶׁיָּצָא כְּבָר, מְבָרֵךְ \u0010y10\u0011 לְהוֹצִיא אֶת אַחֵר יְדֵי חוֹבָתוֹ.\nמִי שֶׁהוּא אָנוּס קְצָת וְאֵינוֹ יָכוֹל לֵילֵךְ \u0010y11\u0011 לְבֵית הַכְּנֶסֶת וְצָרִיךְ לְהַמְתִּין עַד אַחַר שֶׁקָּרְאוּ הַקָּהָל, וְקָשֶׁה עָלָיו לִישֵׁב בְּתַעֲנִית כָּל כָּךְ, יָכוֹל לִשְׁמֹעַ קְרִיאָתָהּ מִבְּעוֹד יוֹם \u0010y12\u0011 מִפְּלַג הַמִּנְחָה וּלְמַעְלָה. \u0010c2\u0011 \u0005 הַגָּה: \u0010y13\u0011 אֲבָל אָסוּר \u0010y14\u0011 לֶאֱכֹל קֹדֶם שֶׁיִּשְׁמַע קְרִיאַת \u0010y15\u0011 הַמְּגִלָּה, אֲפִלּוּ הַתַּעֲנִית קָשָׁה עָלָיו \u0006 \u0005(תְּרוּמַת הַדֶּשֶׁן סִימָן ק\"ט)\u0006.",["\u0003ושהחיינו\u0004 ונכון לכוין בברכת שהחיינו גם על משלוח מנות וסעודת פורים שהם ג\"כ מצות ויודיע זה להש\"ץ המברך דבעי כונת שומע ומשמיע. ויכוין זה בברכת שהחיינו דיום כי זמנם ביום ומי שאין לו מגילה לא יברך שהחיינו על משלוח מנות וסעודה דזהו דבר הנהוג בכל יום ובכל שבת ויו\"ט [מ\"א] וי\"א דראוי לברך זמן על היום מפני תקפו של נס שהיה בו וכיון דמזמן לזמן קאתי הרי הוא ככל מועדי ד' שמברכין עליהן זמן ועיין בבה\"ל אכן אם היה לו מגילה בלילה ובירך אז שהחיינו לכו\"ע א\"צ שוב לברך ביום אם אבל קורא את המגילה יברך אחר הברכות משום ברכת שהחיינו שאין האבל מברך להוציא רבים בברכת שהחיינו והאבל יקרא את המגילה:","\u0003וביום אינו חוזר ומברך וכו'\u0004 דהרי כבר בירך בלילה וטעם הדעה שניה דסוברת דאף ביום וכו' דעיקר מצות קריאתה ביום הוא. אם נשתתק הקורא באמצע המגילה דעת האחרונים דא\"צ הקורא השני העומד תחתיו להתחיל בראש רק יתחיל ממקום שפסק הראשון [וכ\"ש שא\"צ לברך מחדש דיצאו כל הקהל בברכת הראשון] דהוא טרחא דצבורא ועיין בשע\"ת:","\u0003ואחד יכול לברך\u0004 בין ברכה ראשונה ובין לענין ברכה אחרונה ובלבד שיכוין להוציא השומעים והם יכונו לצאת:","\u0003ולאחריה נוהגים לברך\u0004 כי בגמרא איתא דברכה דלאחריה תליא במנהגא במקום שנוהגים לברך יברך ולכן כתב המחבר דהאידנא נוהגים לברך:","\u0003הרב וכו'\u0004 ואין לומר האל הרב כיון שכבר זכר השם שאמר אלהינו ויש גורסים האל ובא\"ר הכריע כהשו\"ע שאין לומר וכן אין לומר בא\"י האל הנפרע רק בא\"י הנפרע ע\"ש:","\u0003אם לא בירך לא לפניה וכו'\u0004 דברכות אין מעכבות ונראה דאם נזכר באמצע שלא בירך יברך בין הפרקים:","\u0003אבל לא ביום\u0004 דכבר אמר פיוטים:","\u0003ואין לברך אחריה וכו'\u0004 אבל הברכות שלפניה לכו\"ע היחיד צריך לברך:","\u0003אין לשוח בעוד שקורין אותה\u0004 היינו בין השומע ובין הקורא אסור להם לשוח לכתחלה ואפילו בד\"ת ולענין דיעבד יש חילוק דהשומע אם שח בעת הקריאה לא יצא אפילו אם חיסר לשמוע תיבה אחת דהא לא שמעה כולה אבל הקורא יצא ולפעמים אפילו לכתחלה מותר כגון לשאול בין הפרקים מפני הכבוד כמו לענין ק\"ש בסימן ס\"ו וכ\"ז לענין שיחה באמצע הקריאה אבל אם שח בין הברכה לתחלת הקריאה בין השומע ובין הקורא הפסיד הברכה וכן בין הקריאה לסוף הברכה ג\"כ אסור להפסיק:","\u0003אע\"פ שיצא כבר מברך וכו'\u0004 וכ\"ש דיכול להוציאם בקריאה אע\"פ שיצא כבר ומ\"מ יש פוסקין שסוברין לענין ברכה אם יודעין בעצמן לברך יברכו בעצמן כיון שהוא כבר יצא בקריאה ומנהג העולם להקל להוציאן בכל גווני ועיין לעיל סימן תקפ\"ה במ\"ב סק\"ה:","\u0003להוציא את אחר י\"ח\u0004 ויקראנה לנשים אחר שיצא מביהכ\"נ דמצוה שיצא בעצמו בקריאת הצבור אכן אם מכוין שלא לצאת באותה קריאה שפיר דמי לצאת אח\"כ בקריאת הצבור. וכשהוא מברך לנשים טוב שיברך לשמוע מגילה כי יש פוסקים שסוברין דאשה אינה חייבת בקריאה רק לשמוע:","\u0003וצריך להמתין וכו'\u0004 ר\"ל שיבוא אחד לקרוא לפניו דמקודם אסור לאכול כמו לענין ק\"ש לעיל בסי' רל\"ה:","\u0003מפלג המנחה ולמעלה\u0004 דהוא שעה ורביע קודם הלילה והטעם דכיון דחשבינן ליה לילה לענין תפילת ערבית שיכול להתפלל בזמן ההוא חשבינן ליה לילה גם לענין הזה:","\u0003אבל אסור לאכול וכו'\u0004 עיין במ\"א שמסיק דדוקא אכילה אסור אבל טעימה בעלמא שרי וע\"כ טוב יותר להקל לאיש הזה שיטעום קודם קריאת המגילה ולא להקל לקרות מפלג המנחה ולמעלה דהפר\"ח קרא תגר על קולא זו ודעתו דקודם צה\"כ אינו יוצא כלל אפילו דיעבד וכן משמע דעת הגר\"א בביאורו. ואפילו טעימה אין להקל אלא לצורך גדול דהיינו חולה קצת או מי שמתענה והתענית קשה לו ושיעור טעימה היינו כביצה פת או משקין כשיעור ביצה. וכתב הפמ\"ג דלפי דעת הפר\"ח אפילו בין השמשות אין לקרות ובדיעבד אם קרא בבין השמשות ג\"כ מסתפק שם אם לא באונס והכרח גדול יש לצדד להקל. וכתב בח\"א דאפילו קרא מקצתה קודם צאת הכוכבים לא יצא וצריך לחזור ולקרות ובלי ברכה. ועיין בשע\"ת בשם הברכי יוסף ובביאור הלכה דמ\"מ המיקל לחולה וליולדת למהר קריאתן מבעוד יום קצת יש לו על מי לסמוך:","\u0003קודם שישמע קריאת המגילה\u0004 כמו לענין ק\"ש דערבית דאסרינן מטעם שמא יחטפנו שינה ויבטל מקריאתה וא\"כ כ\"ש שאסור לישן קודם קריאת המגילה ואפילו דעתו רק לישן קימעא כמו שם גבי ק\"ש וקריאת המגילה הוא חוב גדול שהרי כל המצות נדחים מפניה כדלעיל בסימן תרפ\"ז ועיין לעיל בסימן רל\"ה ס\"ב ובמ\"ב שם כמה פרטים לענין ק\"ש וה\"ה כאן ודע דכמו בלילה אסור לאכול קודם קריאתה ה\"ה ביום אפילו כבר התפלל אסור לאכול קודם קריאתה וכמו לענין שופר ולולב:","\u0003אפילו התענית קשה עליו\u0004 ואם הוא אדם חלוש והשהייה יזיק לבריאותו ויכול לבוא לידי חולי וטעימה מעט אינו מספיק לו נראה דשרי לאכול אך יבקש מאחד שיזכירנו לקרוא את המגילה אחר אכילתו כתב הפמ\"ג ספק אם קרא את המגילה אפשר דלא אמרינן בזה ספיקא דרבנן לקולא משום דהוא דברי קבלה:"],["\u0003 ושהחיינו\u0004 - עיין מ\"ב סק\"א מה שכתבנו די\"א דראוי לברך וכו' הוא ממור וקציעה שהשיג על המגן אברהם וז\"ל ולא ידעתי מה בכך שהוא דבר נהוג והלא בלאו מצות שילוח מנות וסעודה ראוי לברך זמן על היום ואף שהוא מדברי קבלה צריך חזוק כשל תורה ויותר ביחיד מפני תקפו של נס שהיה בו וכיון דמזמן לזמן קאתי הרי הוא לענין זה ככל מועדי ד' שמברכין עליהן זמן וזמן לא בעי כוס דהלכתא אומרו אפילו בשוק ויוה\"כ שאין בו אכילה ושתיה אלא שביתה ומנוחה אעפ\"כ מברכין אותו וכו' ומסיים שם דשפיר הוא לכתחלה למאן דלית ליה מגילה למסמך זמן אכוס דסעודה עכ\"ל ובאמת לפי סברתו שיברך זמן על עצם היום מפני תקפו של נס שהיה בו א\"כ היה לו לברך ג\"כ ברכת שעשה נסים ובאמת מצאתי במאירי של שבת לענין חנוכה [וה\"ה בענינינו לענין פורים] וז\"ל מי שאין לו להדליק ואינו במקום שאפשר לו לראות י\"א שמברך לעצמו שעשה נסים ושהחיינו בלילה א' ושעשה נסים בכל הלילות והדברים נראים עכ\"ל וגם על עצם תמיהתו שמתמה על המגן אברהם והלא בלאו מצות שילוח מנות וכו' ראוי לברך זמן על היום וכו' לא אדע דאפשר דגם המגן אברהם מודה לזה אלא דהוא מיירי שבלילה היה לו מגילה ובירך אז שהחיינו וממילא יצא על עצם הזמן [ומה שמצדד הפמ\"ג דלדעת המחבר יוצא בברכת שהחיינו דלילה על משלוח מנות וסעודה דיום לא נהירא וגם ריהטא דלישנא דמ\"א לא משמע כן] אלא דביום לא היה לו כלל אפשר דגם הוא מודה. אח\"כ מצאתי בברכי יוסף וז\"ל אם אין לו מגילה יברך שהחיינו אך לא יברך ברכת שעשה נסים וברכת הרב את ריבנו [ר\"י מלכו] אבל האחרונים כתבו דגם שהחיינו לא יברך עכ\"ל ולא אדע באיזה אחרונים מצא ד\"ז לבד ממ\"א וא\"ר שהעתיקו ומהם אין ראיה כמו שכתבנו וצ\"ע למעשה ועיין לעיל בסימן תרע\"ו בשעה\"צ אות ג':","\u0003 אלא בצבור\u0004 - הנה בב\"י כתב דא\"ח כתב כן בשם הירושלמי ועיין בא\"ר דהוכיח מכמה פוסקים דמברך אפילו ביחיד ועיין בביאור הגר\"א דמירושלמי ג\"כ אין ראיה דלא קאי אלא אברכת התורה. ומ\"מ נראה דאין כדאי לברך אחרי' דבלא\"ה הברכה זו אפילו בצבור אינה חיובית ותליא במנהגא כדאיתא בגמרא ומי יאמר דנתפשט המנהג כהיום לברך ביחיד וכ\"כ הפמ\"ג דספק ברכות להקל:","\u0003 מפלג המנחה ולמעלה\u0004 - מקורו ממה שהקלנו לעיל בסימן רל\"ג לגבי תפלת ערבית וה\"ה ק\"ש של ערבית לשיטת ר\"ת אכן כ\"ז אם הוא נזהר תמיד להתפלל מנחה קודם פלג וכמבואר שם בס\"א וכ\"כ הגר\"א. והנה הפר\"ח השיג על תה\"ד בעיקר דינו דכיון דבגמרא ילפינן מהא דכתיב ולילה ולא דומיה ולילה לא נקרא עד צה\"כ וגם לענין ק\"ש רוב הפוסקים חולקין על ר\"ת אכן הב\"י בסי' תרפ\"ז העתיק בשם אורחות חיים בשם הראב\"ד דנהגו לקרות קצת מבע\"י כדי להקל על האנושים והמעוברות שלא יתענו יותר מדאי וכן מצאתי באשכול [וגם במאירי הביא כעין זה לענין חולות ויולדות שאין צריכין להעריב כ\"כ ורשאין למהר קריאתן אף שהוא עדיין בתחום י\"ג] ואף שהפר\"ח דחה המנהג הזה בשתי ידים מ\"מ כמה אחרונים הליצו בעד המנהג הזה שהביאוהו כמה ראשונים [עיין בבגדי ישע ובמאמר מרדכי ובמור וקציעה] ודעתם דאף שהמחמיר תבוא עליו ברכה מ\"מ לענין חולה ומצטער שמיקל לקרות מבע\"י קצת יש לו על מי לסמוך. ואפשר במקום שהדחק גדול אף בצבור יש להקל לקרות אף שאין עדיין לילה גמורה:"],"\u0010g0\u0011 הַקּוֹרֵא אֶת הַמְּגִלָּה מְבָרֵךְ לְפָנֶיהָ ג' בְּרָכוֹת: עַל מִקְרָא מְגִלָּה, וְשֶׁעָשָׂה נִסִים, \u0010y0\u0011 \u0010y1\u0011 \u0010g1\u0011 \u0010t0\u0011 \u0010m0\u0011 וְשֶׁהֶחֱיָנוּ; וּבַיּוֹם אֵינוֹ חוֹזֵר וּמְבָרֵךְ שֶׁהֶחֱיָנוּ; \u0005 הַגָּה: \u0010t1\u0011 \u0010s0\u0011 \u0010m1\u0011 וְיֵשׁ אוֹמְרִים דְּאַף \u0006 \u0005 בַּיּוֹם מְבָרֵךְ: שֶׁהֶחֱיָנוּ \u0006 \u0005(טוּר בְּשֵׁם רַבֵּנוּ תָּם וְהָרֹא\"שׁ וְהַמַּגִּיד)\u0006, \u0005 וְכֵן נוֹהֲגִין בְּכָל מְדִינוֹת אֵלּוּ; \u0010y2\u0011 וְאֶחָד יָכוֹל לְבָרֵךְ וְשֵׁנִי קוֹרֵא \u0006 \u0005(הַגָּהוֹת \u0010y3\u0011 \u0010g2\u0011 אֲשֵׁרִי פ\"ג)\u0006; וּלְאַחֲרֶיהָ נוֹהֲגִין לְבָרֵךְ: \u0010y4\u0011 הָרַב אֶת רִיבֵנוּ וכו'. \u0010y5\u0011 \u0010g3\u0011 אִם לֹא בֵּרַךְ לֹא לְפָנֶיהָ וְלֹא לְאַחֲרֶיהָ, יָצָא. \u0005 הַגָּה: וְנָהֲגוּ לוֹמַר בַּלַּיְלָה: אֲשֶׁר הֵנִיא, \u0010y6\u0011 אֲבָל \u0010t2\u0011 \u0010m2\u0011 \u0006 \u0005 לֹא בַּיּוֹם \u0006 \u0005(כָּל בּוֹ וּבֵית יוֹסֵף בְּשֵׁם א\"ח)\u0006, \u0010y7\u0011 \u0005 וְאֵין לְבָרֵךְ אַחֲרֶיהָ אֶלָּא \u0010t3\u0011 \u0006 \u0005 בְּצִבּוּר. \u0010y8\u0011 \u0010g4\u0011 \u0010m3\u0011 \u0006 \u0010c0\u0011 \u0010c1\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011\nאֵין \u0010t4\u0011 \u0010s1\u0011 לָשׂוּחַ בְּעוֹד שֶׁקּוֹרִין אוֹתָהּ. \u0010y9\u0011 \u0010g5\u0011 \u0010m4\u0011\nאַף עַל פִּי שֶׁיָּצָא כְּבָר, מְבָרֵךְ \u0010y10\u0011 לְהוֹצִיא אֶת אַחֵר \u0010g6\u0011 \u0010t5\u0011 יְדֵי חוֹבָתוֹ.\nמִי שֶׁהוּא אָנוּס קְצָת וְאֵינוֹ יָכוֹל לֵילֵךְ \u0010y11\u0011 לְבֵית הַכְּנֶסֶת וְצָרִיךְ לְהַמְתִּין עַד אַחַר שֶׁקָּרְאוּ הַקָּהָל, וְקָשֶׁה עָלָיו לִישֵׁב בְּתַעֲנִית כָּל כָּךְ, יָכוֹל לִשְׁמֹעַ קְרִיאָתָהּ מִבְּעוֹד יוֹם \u0010y12\u0011 \u0010t6\u0011 \u0010s2\u0011 \u0010m5\u0011 \u0010m6\u0011 מִפְּלַג הַמִּנְחָה וּלְמַעְלָה. \u0010c2\u0011 \u0005 הַגָּה: \u0010y13\u0011 אֲבָל אָסוּר \u0010y14\u0011 לֶאֱכֹל קֹדֶם שֶׁיִּשְׁמַע קְרִיאַת \u0010y15\u0011 הַמְּגִלָּה, אֲפִלּוּ הַתַּעֲנִית קָשָׁה עָלָיו \u0006 \u0005(תְּרוּמַת הַדֶּשֶׁן סִימָן ק\"ט)\u0006. \u0010r9\u0011 \u0010r10\u0011",{"g":["מהא דר' ששת מגילה כ\"ט","טור בשם רמב\"ם","משנה וגמ' שם","טור בשם תוספתא","טור לדעתו וכ\"כ רשב\"א בתשו'","שם מהא דתני קודם שישמע קריאת המגילה אפי' התענית קשה עליו (תה\"ד סי' ק\"ט) מהא דתני אהבה ר\"ה כ\"ט","ת\"ה"],"t":["\u0003ושהחיינו. \u0004 ויכוין בברכת שהחיינו ג\"כ על משלוח מנות וסעודות פורים שהם גם כן מצות של\"ה ונ\"ל דיכוין זה בברכת שהחיינו דיום כי זמנם ביום. ונראה לי דמי שאין לו מגילה לא יברך שהחיינו על משלוח מנות וסעודה דזהו דבר הנהוג בכל יום ובכל שבת וי\"ט. מ\"א:","\u0003ביום. \u0004 דעיקר מצות קריאתה ביום. אם נשתתק הקורא באמצע המגילה השני צריך להתחיל בראש כמ\"ש סי' רפ\"ד סעיף ה' אבל א\"צ לברך תחלה דיוצא בברכת הראשון. מ\"א:","\u0003לא\u0004 \u0003ביום. \u0004 שכבר אמרו פיוטים. לבוש:","\u0003בצבור. \u0004 וא\"ז כתב בשם פוסקים לברך ביחיד ע\"ש \u0005(ועיין בספר אליה רבה נוסחת ברכה אחרונה על נכון)\u0006:","\u0003לשוח. \u0004 והקורא עצמו רשאי להפסיק ש\"ג. מ\"א:","\u0003י\"ח. \u0004 ואם מברך לנשים יברך לשמוע מגילה ב\"ח. אבל לא יברך שהחיינו. ויקראנה לנשים אחר יציאת בה\"כ דמצוה שיצא הוא בקריאת הצבור. מ\"א:","\u0003מפלג. \u0004 אחר שיתפלל ערבית. וכתב המ\"א מאחר דשינ' רמ\"א לשונו וכתב אסור לאכול וכו' משמע דטעימה שרי ומ\"מ אין להקל אלא לצורך גדול ומשמע במהרי\"ל דאפילו חולה לא יאכל קודם קריאתה אא\"כ יש בו סכנה. וכתב הב\"י שנהגו לקרות קצת מבע\"י כדי להקל על האנושים והמעוברות שלא יתענו יותר מדאי:"],"s":["\u0003ביום. \u0004 עבה\"ט ועיין בא\"ר שא\"צ להתחיל בראש רק יתחיל ממקום שפסק הראשון עיין שם ובשבו\"י ח\"א סי' מ\"ב הסכים לדבריו בזה וכת' ואם יאמר האומר מה בכך שיתחיל בראש אף אתה אמור לו שהרי מאוד הקפידו חז\"ל על טירחא דציבורא כו' רק שיהיה הגומר בשעת הברכה שבירך הראשון כדאיתא בשופר סי' תקפ\"ה סעיף ג' עיין שם וכ\"כ בדגול מרבבה דמגילה דומה לשופר שמוציא ולכן מתחיל ממקום שפסק זה ונראה שאם לא קרא רק קצת פסוקים אינו מאריך טרחא ויתחיל מראש וגם נראה דאם רוב הציבור מסכימים שיתחיל מראש וליל פורים במוצאי שבת טוב להתחיל מראש שלא יהיה נפשם עגומה בקריאה לחצאין אך אם הוא בשאר הימים שהתענית קשה עליהם יש להקל כמ\"ש הא\"ר והשב\"י להתחיל ממקום שפסק הראשון ועיין בשערי אפרים שער ו' סעיף ס' ובפתחי שערים שם בתחילתו:","\u0003לשוח. \u0004 עבה\"ט ועיין בנ\"ב ח\"א שהביא דברי הטור בשם בעה\"ט שמתיר להפסיק באמצע הקריאה ודברי הטור והב\"י שם והביא ראיה דלא כבה\"ע מברכות דף י\"ד דמבעיא ליה בהלל ומגילה מהו שיפסוק כו' א\"ל פוסק כו' משמע דעכ\"פ אין להקל במגילה יותר מבק\"ש שאין מותר רק מפני היראה והכבוד כו' וגם בעה\"ט נראה דמודה דהפסק דהילוך גרע טפי וע\"ש בדין אם הגיע זמן קידוש לבנה בליל פורים וזרחה באמצע קריאת המגילה באיזה ענין מותר לפסוק והבאתי הדברים בשערי אפרים סעיף ג' ובפתחי שערים שם עיין שם:","\u0003מפלג. \u0004 עבה\"ט ועיין פר\"ח שחולק ע\"ז וכ' דקריאת לילה נפקא מוליל' ולא מיקרי לילה עד אחר צאת הכוכבים ובבר\"י הביא בשם המאירי גבי זמן בני הכפרים שכ' ומכאן סמכו גדולי המפורשים לחולות ויולדות שאין צריכים כ\"כ להעריב ורשאין למהר קריאתן מבע\"י ואף שהוא עדיין בתחום י\"ג עכ\"ל:"],"m":["\u0003ושהחיינו\u0004. ויכוין בברכת שהחיינו ג\"כ על משלוח מנות וסעודת פורים שהם ג\"כ מצות [של\"ה] ונ\"ל דיכוין זה בברכת שהחיינו דיום כי זמנם ביום, ונ\"ל דמי שאין לו מגילה לא יברך שהחיינו על משלוח מנות וסעודה דזהו דבר הנהוג בכל יום ובכל שבת וי\"ט דהא לא תקנו כלל ברכה עליהם:","\u0003וי\"א דאף כו'\u0004. דעיקר מצות קריאת' ביום: אם נשתתק הקורא באמצע המגיל' השני צריך להתחיל בראש כמ\"ש סי' רפ\"ד אבל א\"צ לברך תחלה דיוצא בברכת הראשון דעשה הברכ' בשביל כל הקהל כמ\"ש סי' תקפ\"ה ס\"ג וכ\"מ במרדכי סוף מגיל' בשם ר\"א:","\u0003לא ביום\u0004. שכבר אמרו פיוטים [לבוש]:","\u0003אין לשוח\u0004. והקורא עצמו רשאי להפסיק כמו בק\"ש (ש\"ג פ\"ב דברכות):","\u0003אף על פי שיצא וכו'\u0004. ואם מברך לנשים יברך לשמוע מגיל' כמ\"ש סי' תרפ\"ט ס\"ב [ב\"ח] ועמ\"ש סי' תקפ\"ה ס\"ב ונ\"ל דיקראנ' לנשים אחר יציאת בה\"כ דמצוה שיצא הוא בקריאת הצבור כמ\"ש רסי' תרפ\"ז:","\u0003מפלג המנח'\u0004. נ\"ל דאפי' בשבת מותר לעשות כן כשיש לו איזה אונס כמ\"ש סי' רצ\"ג אך יש לאסור דאין קורין המגיל' בשבת:","\u0003מפלג המנח'\u0004. אחר שיתפלל ערבית אבל אין נ\"ל להתיר לטעום מעט וימתין עד שיבא הקורא כדאמרי' בברכות לא יאמר אדם אוכל קימעא וכו' אח\"כ אקרא ק\"ש, ונראה דכ\"ש לענין קריאת מגילה דחיישי' שמא תחטפנו שינה ויבטל מקריאת' שהרי יש בה שהות טובא וגם קריאת' חוב' טפי שהרי כל המצות נדחי' מפני' [ת\"ה] ועמ\"ש סי' תרפ\"ז בשם רא\"מ דס\"ל איידי דחביבא לא אתי למפשע, ומה\"ט לא אסרו ללמוד כמו גבי בדיקת חמץ עכ\"ל, א\"כ ס\"ל דקיל מק\"ש וחמץ והנה כיון דבק\"ש וחמץ שרי טעימה כמ\"ש סי' רל\"ה ותל\"ב ק\"ו כאן, ועוד דעיקר קריאת המגילה ביום, ונ\"ל דמש\"ה שינה רמ\"א לשונו וכתב אסור לאכול וכו' משמע דטעימה שרי ומ\"מ אין להקל אלא לצורך גדול, ובתוספתא דפ\"ק דשבת כתב דמגילה דמי ללולב ושופר וק\"ש: משמע במהרי\"ל דאפי' חולה לא יאכל קודם קריאתה אא\"כ יש בו סכנה: ופשוט דאנוס קצת יכול לשמוע של יום קודם הנץ החמה אחר שעלה ע\"ה עסי' תרפ\"ז, וכתב שם ב\"י בשם א\"ח שנהגו לקרות קצת מבע\"י כדי להקל על האנושים והמעוברות שלא יתענו יותר מדאי:"],"r":["\u0003ס\"א הקורא כו'. \u0004כ\"א ב' ל\"ש אלא כו':","\u0003שלש כו'. \u0004שם:","\u0003וביום כו'. \u0004אע\"ג דעיקר זמנה ביום כמש\"ש מ\"מ כיון שבירך בלילה יצא דלא גרע מאם בירך אסוכה ולולב בשעת עשייה וכן לכתחילה יש לברך בלילה ומשבירך בלילה אינו מברך ביום כמו בסוכה כמ\"ש שם מ\"ו א':","\u0003וי\"א. \u0004דעיקר קריאתה ביום כמש\"ש אלהי אקרא יומם כו' ושם כ' ב' כל היום כו' מנלן דכתי' והימים כו' ובדלילה ל\"ק וכן שם א' אין קורין כו' אע\"ג דבגמרא אמרו כי קתני אדיום מ\"מ מדלא תני אלא ביום וכן בני כפרים לא היו קורין אלא ביום ובתוספתא פ\"ב קראה בלילה לא יצא י\"ח אר\"י מעשה בריב\"נ שקראה בצפורי בלילה א\"ל אין שעת הסכנה ראיה:","\u0003ואחד כו'. \u0004ירושל' פ\"ד מעשה בר\"מ שקרייה כו' ונתנה לאחר ובירך עליה כו' זה קורא וזה מברך מכאן שהשומע כקורא כתיב אשר קראו לפני המלך כו':","\u0003ולאחריה נוהגין. \u0004מתני' וגמ':","\u0003אם לא. \u0004תוספתא פ\"ב:","\u0003ונהגו. \u0004עמ\"א:","\u0003ואין כו'. \u0004כל בו בשם ירושלמי והוא בפ\"ד הלכה א' והוא בנוסחא שלנו משובש וג\"כ משמע שם דלא קאי אלא אתורה אר\"ש ב\"א למדו ברכת כו':","\u0003ס\"ד מי שהוא כו'. \u0004דמפלג המנחה הוא לילה אף לק\"ש כמ\"ש ר\"ת בברכות ב' א' וכן לקידוש והבדלה כמ\"ש בפ\"ד שם ודוקא למי שנוהג תמיד כר\"י שם וע' פר\"ח שחלק ודחה דבריו:","\u0003אבל. \u0004ע' מ\"א בשם ת\"ה:"]}],["\u0010y0\u0011 אַחַר קְרִיאַת הַמְּגִלָּה בְּעַרְבִית, אוֹמֵר: וְאַתָּה קָדוֹשׁ, וְאִם חָל בְּמוֹצָאֵי שַׁבָּת אוֹמֵר: וִיהִי נֹעַם, קֹדֶם וְאַתָּה קָדוֹשׁ. \u0005 הַגָּה: \u0010y1\u0011 וְאוֹמְרִים: וְיִתֶּן לְךְ, וְקוֹרִים \u0010y2\u0011 הַמְּגִלָּה וְאַחַר כָּךְ מַבְדִּילִין \u0006 \u0005(מִנְהָגִים)\u0006.\nאוֹמֵר: עַל הַנִּסִים, \u0010y3\u0011 בַּלַּיְלָה וּבַיּוֹם. \u0005 הַגָּה: וְאִם לֹא אֲמָרוֹ, \u0010y4\u0011 אֵין מַחֲזִירִין אוֹתוֹ \u0006 \u0005(טוּר)\u0006. \u0005 וְאֵין אוֹמְרִים עַל הַנִּסִּים רַק בְּיוֹם י\"ד, \u0010y5\u0011 אֲבָל \u0006 \u0005 לֹא בְּט\"ו \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח וּמִנְהָגִים)\u0006; \u0005 וּבְלֵיל י\"ד, אַף עַל פִּי שֶׁלֹּא קָרְאוּ הַמְּגִלָּה עֲדַיִן, אוֹמֵר עַל הַנִּסִּים, בִּתְפִלַּת עַרְבִית. \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב)\u0006.\nאֵין קוֹרִין בּוֹ \u0010y6\u0011 הַלֵּל, \u0010y7\u0011 וְאֵין נוֹפְלִים עַל פְּנֵיהֶם. \u0005 הַגָּה: וְאֵין אוֹמְרִים \u0006 \u0005 לַמְנַצֵּחַ וְלֹא אֵל אֶרֶךְ אַפַּיִם \u0006 \u0005(מִנְהָגִים וּבֵית יוֹסֵף בְּשֵׁם תּוֹסָפוֹת)\u0006.\nמוֹצִיאִין \u0010c0\u0011 סֵפֶר תּוֹרָה וְקוֹרִין בְּפָרָשַׁת וַיָּבֹא \u0010y8\u0011 עֲמָלֵק, וְאַף עַל פִּי שֶׁאֵין בָּהּ אֶלָּא ט' פְּסוּקִים; וְכּוֹפְלִין פָּסוּק אַחֲרוֹן כְּדֵי לְהַשְׁלִים עֲשָׂרָה פְּסוּקִים. \u0010y9\u0011 \u0005 וְאֵין הַמִּנְהָג לִכְפֹּל פָּסוּק הָאַחֲרוֹן שֶׁל הַפָּרָשָׁה. \u0010y10\u0011 \u0006 וְקוֹרִין הַמְּגִלָּה וְאַחַר כָּךְ סֵדֶר קְדֻשָּׁה. \u0005 הַגָּה: כְּשֶׁיֵּשׁ מִילָה בְּפוּרִים \u0010y11\u0011 מָלִין הַתִּינוֹק \u0006 \u0005 קֹדֶם קְרִיאַת הַמְּגִלָּה \u0006 \u0005(מַהֲרִי\"ל וּמִנְהָגִים)\u0006.",["\u0003אחר קריאת המגילה וכו'\u0004 עיין במ\"א שמצדד דאחר שמו\"ע אומר ק\"ש עם תתקבל וכ\"כ בא\"ר ואחר אמירת ואתה קדוש שאומרים אחר קריאת המגילה יאמר ק\"ש בלא תתקבל וא\"ר כתב דיוכל ג\"כ לומר תתקבל ויחזור תתקבל על תפלה דבסדר קדושה ובשחרית יאמר חצי קדיש אחר ש\"ע ולאחר סדר קדושה ק\"ש עם תתקבל:","\u0003ואומר ויתן לך\u0004 במו\"ש אחר הבדלה וההבדלה הוא אחר סדר קדושה כמו בשאר ימות השנה ומה שכתב וקורים המגילה הוא ענין בפני עצמו:","\u0003ואח\"כ מבדילין\u0004 דכל מה שיש לאחר את ההבדלה ביציאת היום מאחרינן לה:","\u0003בלילה\u0004 אפילו אם הקדים להתפלל ערבית קודם צאת הכוכבים:","\u0003אין מחזירין אותו\u0004 עיין לעיל בסימן תרפ\"ב ס\"א וה\"ה בענינינו. ולענין על הנסים בבהמ\"ז עיין לקמן בסימן תרצ\"ה ס\"ג:","\u0003אבל לא בט\"ו\u0004 כיון שאין שייך זה לאותו היום הו\"ל שלא מעין המאורע והוי הפסק בתפלה מיהו אם אמרו אין מחזירין אותו דמ\"מ יש קצת שייכות בימים אלו. כרכים הספיקות אם הם מוקפות חומה אומרים על הנסים בתפלה בשני ימים ואין זה הפסק כיון דמספק אומרים. שחרית משכימין לביה\"מ. אין לחלוץ התפילין אף שהתפללו כבר עד אחר קריאת המגילה דדרשינן ויקר אלו תפילין [מנהגים]:","\u0003הלל\u0004 דבשלמא ביציאת מצרים אמרינן הללו עבדי ה' ולא עבדי פרעה אבל הכא אכתי עבדי אחשורוש אנן:","\u0003ואין נופלין וכו'\u0004 וא\"א למנצח וכו' בשני ימי פורים משום דכתיב ביה צרה וצרה בפורים לא מדכרינן:","\u0003עמלק\u0004 עד מדור דור ואומרים ח\"ק:","\u0003ואין המנהג לכפול\u0004 ואע\"ג דקי\"ל אין פוחתין מעשרה פסוקים היכא דסליק ענינא שאני:","\u0003וקורין המגילה\u0004 ומברכין אחריה ברכת הרב את ריבנו כדלעיל בסימן תרצ\"ב וצריכין כולן לשמוע הברכה ויש מהמונים שאומרים אז קדיש אחר סיום המגילה ואינו נכון:","\u0003מלין התינוק קודם וכו'\u0004 ואסמכתא לזה דכתיב ליהודים היתה אורה ושמחה וששון וששון מרמז על מילה. והפר\"ח כתב דיקדים קריאת המגילה וכ\"מ בביאור הגר\"א דמתמה על הרמ\"א בזה:"],["\u0003 מוציאין ס\"ת וכו'\u0004 - הנה תוס' מגילה (דף ד.) כתבו דאין מחזיר הס\"ת למקומו אלא יושב ואוחז בידו עד שקראו את המגילה ובלבוש משמע דמחזיר הס\"ת למקומו ואח\"כ קורא המגילה וכ\"כ בדה\"ח אח\"כ מצאתי בבית מאיר וז\"ל הנה יתר הפוסקים השמיטו דברי התוס' ש\"מ דלא ס\"ל ויראה דהטעם משום דהאוחז הא ג\"כ חייב לכוין לצאת שמיעת קריאת המגילה כדאיתא סי' תר\"צ סי\"ד ואם יאחז ס\"ת בידו יהא לבו על הס\"ת כדאיתא בסימן צ\"ו לענין תפלה עכ\"ל:"],"\u0010y0\u0011 \u0010g0\u0011 אַחַר קְרִיאַת הַמְּגִלָּה בְּעַרְבִית, אוֹמֵר: \u0010t0\u0011 וְאַתָּה קָדוֹשׁ, וְאִם חָל בְּמוֹצָאֵי שַׁבָּת \u0010g1\u0011 אוֹמֵר: \u0010t1\u0011 \u0010s0\u0011 \u0010s1\u0011 \u0010s2\u0011 וִיהִי נֹעַם, קֹדֶם וְאַתָּה קָדוֹשׁ. \u0005 הַגָּה: \u0010y1\u0011 \u0010g2\u0011 וְאוֹמְרִים: וְיִתֶּן לְךְ, וְקוֹרִים \u0010y2\u0011 הַמְּגִלָּה וְאַחַר כָּךְ מַבְדִּילִין \u0006 \u0005(מִנְהָגִים)\u0006. \u0010g3\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011\nאוֹמֵר: עַל הַנִּסִים, \u0010y3\u0011 בַּלַּיְלָה וּבַיּוֹם. \u0005 הַגָּה: וְאִם לֹא אֲמָרוֹ, \u0010y4\u0011 אֵין מַחֲזִירִין אוֹתוֹ \u0006 \u0005(טוּר)\u0006. \u0005 וְאֵין אוֹמְרִים עַל הַנִּסִּים רַק בְּיוֹם י\"ד, \u0010y5\u0011 \u0010m0\u0011 אֲבָל \u0010t2\u0011 \u0006 \u0005 לֹא בְּט\"ו \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח וּמִנְהָגִים)\u0006; \u0005 וּבְלֵיל י\"ד, אַף עַל פִּי שֶׁלֹּא קָרְאוּ הַמְּגִלָּה עֲדַיִן, אוֹמֵר עַל הַנִּסִּים, בִּתְפִלַּת עַרְבִית. \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב)\u0006. \u0010g4\u0011 \u0010m1\u0011 \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011\nאֵין קוֹרִין בּוֹ \u0010y6\u0011 הַלֵּל, \u0010y7\u0011 \u0010g5\u0011 וְאֵין נוֹפְלִים עַל פְּנֵיהֶם. \u0005 הַגָּה: וְאֵין אוֹמְרִים \u0010t3\u0011 \u0006 \u0005 לַמְנַצֵּחַ וְלֹא אֵל אֶרֶךְ אַפַּיִם \u0006 \u0005(מִנְהָגִים וּבֵית יוֹסֵף בְּשֵׁם תּוֹסָפוֹת)\u0006. \u0010r6\u0011\nמוֹצִיאִין \u0010c0\u0011 \u0010g6\u0011 סֵפֶר תּוֹרָה וְקוֹרִין בְּפָרָשַׁת וַיָּבֹא \u0010y8\u0011 עֲמָלֵק, וְאַף עַל פִּי שֶׁאֵין בָּהּ אֶלָּא ט' פְּסוּקִים; \u0010g7\u0011 וְכּוֹפְלִין פָּסוּק אַחֲרוֹן כְּדֵי לְהַשְׁלִים עֲשָׂרָה פְּסוּקִים. \u0010y9\u0011 \u0005 וְאֵין הַמִּנְהָג לִכְפֹּל פָּסוּק הָאַחֲרוֹן שֶׁל הַפָּרָשָׁה. \u0010y10\u0011 \u0006 וְקוֹרִין הַמְּגִלָּה וְאַחַר כָּךְ סֵדֶר קְדֻשָּׁה. \u0005 הַגָּה: כְּשֶׁיֵּשׁ מִילָה בְּפוּרִים \u0010y11\u0011 \u0010m2\u0011 מָלִין הַתִּינוֹק \u0010t4\u0011 \u0006 \u0005 קֹדֶם קְרִיאַת הַמְּגִלָּה \u0006 \u0005(מַהֲרִי\"ל וּמִנְהָגִים)\u0006. \u0010r7\u0011 \u0010r8\u0011 \u0010r9\u0011",{"g":["טור בשם י\"א","\u0003שם ופי' כמו בשאר ימות השנה אחר סדר קדושה וכו'\u0004 ולא בא אלא לאשמועינן שמאחרין ההבדלה אחר קריאת המגילה משום דאפוקי יומא מאחרינן ליה)","כאשר הגהתי כנ\"ל וכן היא בס\"ח","שם","מסקנ' הגמ' מגילה י\"ד","טור בשם תשו' שמצא וכ\"כ או\"ח","משנ' שם ל'","ב\"י שכן נהגו"],"t":["\u0003ואתה קדוש. \u0004 ואומרים קדיש שלם בלא תתקבל לאחר קריאת המגילה. מ\"א עיין שם:","\u0003ויהי נועם. \u0004 אחר קריאת המגילה מנהגים וכ\"כ מי\"ט דמ\"ש ואומרים ויהי נועם לאפוקי מהכלבו דפסק דא\"א כלל ומ\"ש וקורין המגילה קאי אלאחריו ואח\"כ מבדילין ועיין בשכנה\"ג בהגהת ב\"י אות ד' ועיין בתשובת דבר שמואל סי' קכ\"ח:","\u0003לא בט\"ו. \u0004 מיהו אם אמרו בט\"ו אין מחזירין אותו מ\"א וט\"ז דלא כב\"ח עיין שם. שחרית משכימין לבה\"כ ואין לחלוץ התפילין עד אחר קריאת המגילה דדרשינן ויקר זו תפילין. מט\"מ מנהגים:","\u0003למנצח. \u0004 כתב ב\"ח בשם תוספות מגילה דף ד' דאומרים שיר מזמור לאסף דיש בה מפלה לעכו\"ם:","\u0003קודם. \u0004 דכתיב וששון זו מילה:"],"s":["\u0003ויהי נועם. \u0004 ועיין באר הגולה ועיין שם בדבר שמואל שכת' שרוב העולם נוהגים להקדים קריאת המגילה להבדלה על הכוס בבה\"כ דהיינו גם אחר סיום סדר קדושה וקדיש תתקבל כמנהג בכל השנה אך כיון שאין הכרע מן הש\"ס והראשונים אין להכריח לא' מהקהילות לשנות המנהג וכל קהל כעיר בפני עצמו ואין בזה משום לא תתגודדו כו' וע' במוהרשד\"ם ביו\"ד סי' ק\"ע ע' שם ועיין במג\"א סי' תשצ\"ג ועיין בר\"י שהפר\"ח כת' שיבדיל קודם שאין ראוי שיהנה מן הנר קודם הבדלה עד כאן לשונו ולפי\"ז סגי אם מברך בורא מאורי האש והב\"ד גימגם דאיך יוציא את אשתו בברכה זו כו' אם כן יברך במ\"ה בבה\"כ קודם הבדלה כיון דכמה רבוותא כ' לברך במ\"ה קודם שלא יהנה בלא ברכה כו' ועיין בכנה\"ג בשם מהר\"ש הלוי שא\"צ לברך במ\"ה קודם כיון דמסדרן אחר כך על הכוס והנאת הנר כבר נפט' בברכת יוצר המאורות ואינו אלא זכר למה שאירע לאדם הראשון עיין שם ועיין בתוספת פסחים דף נ\"א וע' בשירי כנה\"ג דאף על פי שבליל ט\"ב מברכים קודם התם אינו עתיד לסדרן על הכוס באותו לילה כו' והמברך במ\"ה קודם המגילה לא הפסיד ע\"ש. ובש\"ח הביא מתורת חסד שהביא גם כן דברי כנה\"ג בשם מהר\"ש הלוי כו' ודברי הד\"ש שכתבתי לעיל ע\"ש ולענין אם לטלטל המגילה בשבת ולהביאה לבה\"כ מבע\"י לליל פורים שחל במ\"ש עיין לעיל סימן תרפ\"ח בט\"ו שחל בשבת שכ' הפר\"ח דאסור לטלטלה ובשכנה\"ג סימן ש\"ח קצת מסתפק בזה ובש\"ח הביא בשם מטה יהודה דגם להפר\"ח אין איסור אלא אם חל בט\"ו כיון דיש בו חובת הקריאה אבל בשאר שבתות לא שייכא גזירה דרבה ולמה יאסר ליקרא בה כקורא בתורה וממילא כיון דמותר בקריאה מותר בטלטול וכן נראה שנוטה דעת השכנה\"ג וכן מנהג העול' להקל עכ\"ל ועיין לעיל סימן ש\"ח בש\"ת הבאתי מא\"ר דמגילה דינה ככתבי קודש ודברי הפר\"ח דאוסר ולפי מ\"ש מטה יהודה י\"ל דלא פליגי דבא\"ר דמיירי בשאר שבתות השנה ובזה גם הפר\"ח מודה ואמנם לענין הבאה לבה\"כ קודם הלילה הייתי מונע מזה משום הכנה משבת לחול וע\"ד שנתבאר סימן תרס\"ח. ועתה מצאנו כן בהשמטות שבסוף מו\"ק ע\"ש. ויש להחמיר שלא להביאה ע\"י קטן עיין בספרי שו\"ת בית אפרים חלק יו\"ד סימן ס\"ב וס\"ג אלא ימתין עד שתחשך או יביאנה בצנעה מבע\"י לבה\"כ ומעיין בה קצת דרך לימוד דאז לא מיחזי כ\"כ כהכנה וע' במג\"א סימן של\"ד ס\"ק י\"ח לענין מגילה שאין כתובה כהלכתה דמכל מקום מצילין כו' ע\"ש:","\u0003 (ס\"ג בש\"ע) אין קורין בו הלל. \u0004 וכת' בר\"י בשם המאירי דלהך טעמא דאמרי בש\"ש משום דקריאתה זו הילולא אם אין לו מגילה לקרות בה יאמר הלל כו' והבר\"י כת' כיון דרבא אמר טעמא משום דאכתי עבדי אחשורוש אנן כו' לא יאמר הלל כלל והלכה כרבא דהוא בתרא וגם לגירסת הרי\"ף הרא\"ש והר\"ן מתקיף לה רבא כו' משמע דהלכתא כוותיה דהא לא אותיבו עליה ולכן סתמו הפוסקים ומשמע דלעולם לא יאמר הלל ע\"ש אך במח\"ב הביא דבה\"ג ורמב\"ם כתבו ג\"כ הטעם דקריאתה זו הלולא וכדמשמע מהמאירי ויהיב טעמא משום דמיסתבר להו טעמא דר\"נ כו' עיין שם ולפ\"ז חזר הדין דמי שאין לו מגילה יאמר הלל אך לענ\"ד דעיקר כוונת הש\"ס על עיקר התקנה אבל אחרי שלא נתקן הלל בפורים משום דקריאתה כו' ממילא שאין מקום לקרות הלל מה שלא תיקנוהו חז\"ל לאומרה היום ולענ\"ד דאעפ\"כ כשאין לו מגילה לקרות יש לו לקרות הלל בלא ברכה שלפניו ושלאחריו כקורא בתהלים ושפיר דמי ואף אם יש לו חומש שקורא בו מגילה לעצמו מכל מקום הרוצה לקרות גם הלל בלא ברכה לא הפסיד דאפשר דעדיף אמירת הלל שלא נתקן שיהיה בכשרות קצת כס\"ת משא\"כ קריאת המגילה שעיקר תקנתה להיות כתובה כתיקנה ולכן יוצא ידי שניהם:","\u0003 (ס\"ד בש\"ע) מוציאין ס\"ת כו'. \u0004 ועיין בשבו\"י ח\"א סימן ט' בן כרך שהלך לעיר ודעתו לחזור בזמן קריאת המגילה היינו ביום ט\"ו שלו שאז אינו חייב לקרות בי\"ד והוא מתפלל בבה\"כ עם הציבור ויכול לעלות לתורה בפרשת ויבא עמלק אף על פי שאין עליו היום חיוב קריאת המגילה ועיין שם לענין יום התענית כשהכהן אין מתענה שיוצא מבה\"כ ולענין בן א\"י שדעתו לחזור לענין הקריאה בח\"ל ביום טוב ב' ש\"ג וכתבתי מזה בשערי אפרים ע\"ש:"],"m":["כתוב במנהגים שאומרים קדיש שלם אחר תפלת י\"ח קודם קריאת המגיל' וכ\"כ מהרי\"ל בתשובה סי' נ\"ו רוקח, וכ\"כ התוס' דף ד' והג\"מ דלא כלבוש, ובאגודה כתב בשם רוקח לומר חצי קדיש ובמסכת תענית כתב גבי ט\"ב ואומרים ק\"ש קודם איכא אכן הרוקח כ' לומר חצי קדיש עכ\"ל ואבודרהם כ' ג\"כ חצי קדיש: ונ\"ל דבמדינות אלו שנוהגין לומר קדיש שלם אזי אחר קריאת המגילה יאמרו ק\"ש בלא תתקבל ואפשר שכן דעת המנהגים ועסי' תקנ\"ט: \u0003אבל לא בט\"ו\u0004. מיהו אם אמרו אין מחזירין אותו כמ\"ש ססי' ק\"ח דלא כב\"ח:","\u0003אין קורין בו הלל\u0004. דבשלמא ביציאת מצרים אמרי' הללו עבדי ה' ולא עבדי פרעה אבל הכא אכתי עבדי אחשורוש אנן: שחרית משכימין לבה\"כ ואין לחלוץ התפילין עד אחר קריאת המגיל' [מט\"מ מנהגים]:","\u0003מלין קודם\u0004. דכתי' וששון זו מילה:"],"r":["\u0003ס\"א אומר ואתה קדוש. \u0004שסמוך אחר פסוק אלהי אקרא כו' וכל המזמור נאמר על אסתר כמ\"ש רש\"י ד' א'. כל בו והג\"מ ומרדכי:","\u0003ואם כו' ויתן לך. \u0004כמו בשאר ימות השנה:","\u0003וקורין בו'. \u0004דאפוקי יומא מאחרינן ליה כמ\"ש בפ\"ח דברכות ובפ\"י דפסחים:","\u0003ס\"ב אומר כו'. \u0004תוספתא פ\"ג דברכות כל שאין בו מוסף כגון חנוכה ופורים ערבית שחרית ומנחה מתפלל שמנה עשרה ואומר מעין המאורע בהודאה ואם לא אמר אין מחזירין אותו והביאו הרי\"ף ורא\"ש בפ\"ב דשבת:","\u0003וא\"א. \u0004דיום ט\"ו לפרזים אינו אלא מחמת מגילת תענית להספד ותענית כמ\"ש שם ה' ב' וכמ\"ש לעיל:","\u0003ובליל י\"ד. \u0004ע' רש\"י בשבת כ\"ד א' ד\"ה ערבית וע' רי\"ף שם כגון תענית ומעמדות חנכה ופורים כו':","\u0003ס\"ג ואין נופלין כו' וא\"א כו'. \u0004דאסור בהספד ותעניות. שם ה' ב':","\u0003ס\"ד ואע\"פ שאין. \u0004ירושלמי פ\"ד הלכה ב' והביאו הרי\"ף הרי פ' עמלק א\"ל שנייא היא שהיא סדורו של יום וכמ\"ש בהפטרה בגמ' כ\"ג ב' תוס' ורא\"ש:","\u0003ואין המנהג. \u0004כנ\"ל:","\u0003כשיש מילה כו'. \u0004כמ\"שש ט\"ז ב' וששון זה מילה כו'. וצ\"ע דאף עבודה דרבים מאחרינן וזמנה בבקר כ\"ש מילה דאינה אלא משום זריזין כו' וכ\"כ פר\"ח:"]}],["\u0010y0\u0011 חַיָּב כָּל אָדָם \u0010y1\u0011 לִתֵּן לְפָחוֹת \u0010y2\u0011 שְׁתֵּי מַתָּנוֹת לִשְׁנֵי עֲנִיִּים. \u0005 הַגָּה: יֵשׁ אוֹמְרִים שֶׁיֵּשׁ לִתֵּן קֹדֶם פּוּרִים מַחֲצִית מִן הַמַּטְבֵּעַ הַקָּבוּעַ בְּאוֹתוֹ מָקוֹם וּבְאוֹתוֹ זְמַן, זֵכֶר לְמַחֲצִית הַשֶּׁקֶל שֶׁהָיוּ נוֹתְנִין בְּאֲדָר; וּמֵאַחַר שֶׁשְּׁלֹשָׁה פְּעָמִים כָּתוּב תְּרוּמָה בַּפָּרָשָׁה, יֵשׁ לִתֵּן שְׁלשָׁה \u0006 \u0005(מָרְדְּכַי רֵישׁ פ\"ק דִּמְגִלָּה)\u0006; \u0005 וְיֵשׁ \u0010y3\u0011 לִתְּנוֹ בְּלֵיל פּוּרִים קֹדֶם שֶׁמִּתְפַּלְּלִים מִנְחָה \u0006 \u0005(מַהֲרִי\"ל)\u0006, \u0005 וְכֵן נוֹהֲגִין בְּכָל מְדִינוֹת אֵלּוּ; וְיֵשׁ לִתֵּן ג' חֲצָאִים גְּדוֹלִים בִּמְדִינוֹת אֵלּוּ, כִּי אֵין מַטְבֵּעַ שֶׁשֵּׁם מַחֲצִית עָלֶיהָ מִלְּבַד זוֹ; וּבִמְדִינוֹת אוסטריי\"ף יִתְּנוּ ג' חֵצִי וויינ\"ר, שֶׁנִּקְרְאוּ גַּם כֵּן מַחֲצִית, וְכֵן לְכָל מְדִינָה וּמְדִינָה; \u0006 \u0005 וְאֵין חַיָּב לִתְּנוֹ רַק מִי שֶׁהוּא \u0010y4\u0011 מִבֶּן עֶשְׂרִים וּלְמַעְלָה, וְיֵשׁ אוֹמְרִים שֶׁנּוֹתְנִים מַחֲצִית הַשֶּׁקֶל לִצְדָקָה מִלְּבַד ג' מַחֲצִית אֵלּוּ, וְאֵין נוֹהֲגִין כֵּן. \u0010y5\u0011 \u0006 \u0010c0\u0011 \u0010c1\u0011 \u0010c2\u0011 \u0010c3\u0011\nאֵין מְשַׁנִּין מָעוֹת פּוּרִים \u0010y6\u0011 לִצְדָקָה אַחֶרֶת. \u0005 הַגָּה: \u0010y7\u0011 וְדַוְקָא הַגַּבָּאִים \u0006 \u0005(מָרְדְּכַי פ\"ק דְּבָבָא בַּתְרָא)\u0006, אֲבָל הֶעָנִי יָכוֹל לַעֲשׂוֹת בּוֹ \u0010y8\u0011 מַה שֶּׁיִּרְצֶה.\nאֵין מְדַקְדְּקִים בְּמָעוֹת פּוּרִים אֶלָּא כָּל מִי שֶׁפּוֹשֵׁט יָדוֹ לִטֹּל נוֹתְנִים לוֹ; \u0010y9\u0011 וּבְמָקוֹם שֶׁנָּהֲגוּ \u0010y10\u0011 לִתֵּן אַף לְעַכּוּ\"ם, נוֹתְנִים. \u0010y11\u0011\nבְּמָקוֹם שֶׁאֵין עֲנִיִּים, יָכוֹל לְעַכֵּב \u0010y12\u0011 מָעוֹת פּוּרִים שֶׁלּוֹ לְעַצְמוֹ וְנוֹתְנָם בַּמָּקוֹם שֶׁיִּרְצֶה.",["\u0003כל אדם\u0004 בין איש ובין אשה ואפילו עני המתפרנס מן הצדקה דעת כמה אחרונים דצריך לתת ממה שנתנו לו:","\u0003ליתן לפחות וכו'\u0004 ורשאי ליתן מאכל או מעות ולא מצאתיו כעת כמה יהיה שיעור מתנות [פמ\"ג] ובחידושי ריטב\"א כתב אפילו שתי פרוטות דשוה פרוטה חשובה מתנה אבל לא בפחות. אם החליף סעודתו בשל חבירו יצא ידי מתנות וע\"כ עני המתפרנס מן הצדקה יתן שתי מתנות לשני אביונים ויחזרו הם ויתנו לו [פמ\"ג] עוד כתב נ\"ל דלכתחלה צריך ליתן לאביון דבר הראוי ליהנות ממנו בפורים מאכל או מעות שיוכל להוציא בפורים:","\u0003שתי מתנות\u0004 זהו מדינא אבל באמת מוטב להרבות במתנות לאביונים מלהרבות בסעודתו ובשלוח מנות לרעיו שאין שמחה גדולה ומפוארה אלא לשמח לב עניים יתומים ואלמנות ודומה לשכינה שנאמר להחיות רוח שפלים ולהשיב לב נדכאים [רמב\"ם] והנה השתי מתנות צריך ליתן משלו ולא משל מעשר וההוספה שמוסיף יוכל ליתן משל מעשר:","\u0003בליל פורים\u0004 ובמדינתינו נוהגין ליתנו בשחרית קודם קריאת המגילה [מ\"א] ועכשיו נוהגין ליתן מחצית השקל קודם מנחה ובשחרית מעות מגילה:","\u0003מבן עשרים ולמעלה\u0004 זהו לדעת ר\"ע מברטנורא אבל התוי\"ט כתב שהפוסקים חולקים וס\"ל דמבן י\"ג ולמעלה שהוא בכלל איש חייב במחצית השקל וא\"ר כתב דכל זה רק מדינא אבל המנהג הוא ליתן אפילו בעד בניו הקטנים ואשה מעוברת בעד ולדה איתא במשנה כל קטן שהתחיל אביו לשקול על ידו שוב אינו פוסק:","\u0003אין משנים מעות פורים\u0004 היינו מעות שגבה אותן הגבאי לחלקם לעניים לסעודת פורים אין יכול לשנותן לומר דיין בפחות והמותר יפול לכיס של צדקה אבל לוקחין עגלים לרוב בכל המעות והמותר שלא יספיקו לאכול בפורים ימכר ויפול לכיס של צדקה [גמרא]. כתב ב\"י בשם הגהת אשרי דמעות שחשב בלבו לחלקם לעניים ביום פורים אינו רשאי לשנותו והטעם דס\"ל דצדקה יש לו דין הקדש וחייב לקיים מחשבתו אף שלא הוציא בשפתיו:","\u0003לצדקה אחרת\u0004 אם יש מנהג באותה העיר לתת מעות פורים לחזן אין איסור בדבר דכל הנותן אדעתא דמנהגא נותן אבל לא נפקי בזה ידי מתנות לאביונים אפילו אם החזן הוא עני [דכיון דהוא בכלל שכירות החזן הו\"ל פורע חובו במתנות לאביונים] אא\"כ מחלקים מהם לעניים:","\u0003ודוקא הגבאים\u0004 ואם בני העיר יכולים לשנות יש דיעות בפוסקים עיין במ\"א:","\u0003מה שירצה\u0004 ר\"ל אף דהגובים גבו המעות לצורך סעודת פורים מ\"מ יש לעני רשות להוציאן לשאר צרכיו:","\u0003ובמקום שנהגו וכו'\u0004 אבל בעיר שלא הורגלו עדיין בכך זה הנותן פרוטה לעכו\"ם גוזל לעניים ומראה בעצמו כאלו מקיים בהם ומתנות לאביונים:","\u0003אף לעכו\"ם נותנים\u0004 מפני דרכי שלום:","\u0003במקום שאין עניים\u0004 ישראל:","\u0003מעות פורים שלו\u0004 היינו מה שגבו כבר ממנו ואין מוצאין למי לחלקם ויותר נראה דר\"ל מה שרגיל ליתן בכל שנה לצורך עניים:"],["\u0003 ליתן לפחות וכו'\u0004 - נסתפקתי מתנה לאביון אי מהני ע\"מ להחזיר ומשלוח מנות לא מהני כי מצוה מאכל ומשקה שישמחו בפורים. ומחצית השקל אם מחלקין לעניים יוצאין ידי מתנות לאביונים [פמ\"ג]:","\u0003 לשני עניים\u0004 - ולא יתן להם קודם פורים דלמא אכלי להו קודם פורים [מ\"א בשם המאור] ומנהג העולם ליתן קודם פורים אף דמתנות לאביונים מצותו דוקא ביום פורים צ\"ל דע\"כ נותן שתי מתנות לאביונים גם ביום פורים וגם יש הרבה עניים החוזרים על הפתחים בפורים [מחצית השקל]:","\u0003 י\"א שיש ליתן וכו'\u0004 - ועני המתפרנס מן הצדקה צ\"ע אם מחוייב ליתן מחצית השקל [פמ\"ג]:","\u0003 ויש ליתן ג' חצאי גדולים במדינות אלו\u0004 - הנה דרך העולם לפרש חצאי גדולים חצי ג\"פ והיינו מה שקורין במדינתינו (חצי גראשין) ולא משמע כן בד\"מ עיי\"ש ואולי הוא שם מטבע אחרת שנקרא כן במדינתו שכתב שם שחצי גדול הוא ט' פשוטין קטנים. ובמדינתינו כעת אין לנו מטבע זו. ולפי מדינתינו נראה דמדינא יוצא במטבע קטנה שנקרא חצי גראש אבל מ\"מ אין זה מטבע חשובה כלל אפילו אם נותן ג' חצאין אם לא שנותן גם בעד בניו הקטנים וראיתי איזה גבאים שנותנין מתחלה בהקערה של צדקה ג' חצאי רו\"כ וכשבא אחד ליתן המחצית השקל נותן לו הגבאי תחת מעותיו הג' חצאי רו\"כ והוא נותן אותם להקערה אבל אין זה מחוור דאם הגבאי נותן לו רק בתורת שאלה על איזה רגעים וגם הנותן אין דעתו להקנותם לצדקה הלא אין זה נתינה כלל והוא מערים רק לעצמו בזה. ואם כונת הגבאי בעצמו באמת להקנות לו והוא נותנם לצדקה זהו עצה רק להראשון ולא להאנשים שאחריו כיון שכבר נעשו צדקה אין רשות להגבאי להחליפם תחת ג' חצאי ג\"פ ואולי כיון שכבר נהגו כך הו\"ל כאלו התנו בהדיא כל הנותנים לצדקה שנותנים על אופן זה שיהיה להגבאי רשות לזה. והנה בזמן הגר\"א היה מצוי חצי זהוב פוליש וכתוב במעשה רב שלא היה נותן כ\"א חצי זהב אחד פוליש אבל כעת אין מצוי מטבע זו כלל אם לא שיתן חצאי ג\"פ או חצי רו\"כ. ומי שעוזרו הקב\"ה שיכול ליתן רו\"כ אחד זכר למחצית השקל וג' חצאי ג\"פ לענין מה שכתוב בפרשה ג' פעמים תרומה וכהי\"א האחרון שכתב רמ\"א אשרי וטוב לו:"],"\u0010y0\u0011 \u0010g0\u0011 חַיָּב כָּל אָדָם \u0010y1\u0011 לִתֵּן לְפָחוֹת \u0010y2\u0011 \u0010t0\u0011 \u0010s0\u0011 \u0010m0\u0011 שְׁתֵּי מַתָּנוֹת לִשְׁנֵי עֲנִיִּים. \u0005 הַגָּה: יֵשׁ אוֹמְרִים שֶׁיֵּשׁ לִתֵּן קֹדֶם פּוּרִים מַחֲצִית מִן הַמַּטְבֵּעַ הַקָּבוּעַ בְּאוֹתוֹ מָקוֹם וּבְאוֹתוֹ זְמַן, זֵכֶר לְמַחֲצִית הַשֶּׁקֶל שֶׁהָיוּ נוֹתְנִין בְּאֲדָר; וּמֵאַחַר שֶׁשְּׁלֹשָׁה פְּעָמִים כָּתוּב תְּרוּמָה בַּפָּרָשָׁה, יֵשׁ לִתֵּן שְׁלשָׁה \u0006 \u0005(מָרְדְּכַי רֵישׁ פ\"ק דִּמְגִלָּה)\u0006; \u0005 וְיֵשׁ \u0010y3\u0011 \u0010m1\u0011 לִתְּנוֹ בְּלֵיל פּוּרִים קֹדֶם שֶׁמִּתְפַּלְּלִים מִנְחָה \u0006 \u0005(מַהֲרִי\"ל)\u0006, \u0005 וְכֵן נוֹהֲגִין בְּכָל מְדִינוֹת אֵלּוּ; וְיֵשׁ לִתֵּן ג' חֲצָאִים גְּדוֹלִים בִּמְדִינוֹת אֵלּוּ, כִּי אֵין מַטְבֵּעַ שֶׁשֵּׁם מַחֲצִית עָלֶיהָ מִלְּבַד זוֹ; וּבִמְדִינוֹת אוסטריי\"ף יִתְּנוּ ג' חֵצִי וויינ\"ר, שֶׁנִּקְרְאוּ גַּם כֵּן מַחֲצִית, וְכֵן לְכָל מְדִינָה וּמְדִינָה; \u0010t1\u0011 \u0010s1\u0011 \u0006 \u0005 וְאֵין חַיָּב לִתְּנוֹ רַק מִי שֶׁהוּא \u0010y4\u0011 \u0010m2\u0011 מִבֶּן עֶשְׂרִים וּלְמַעְלָה, וְיֵשׁ אוֹמְרִים שֶׁנּוֹתְנִים מַחֲצִית הַשֶּׁקֶל לִצְדָקָה מִלְּבַד ג' מַחֲצִית אֵלּוּ, וְאֵין נוֹהֲגִין כֵּן. \u0010y5\u0011 \u0010g1\u0011 \u0010m3\u0011 \u0006 \u0010c0\u0011 \u0010c1\u0011 \u0010c2\u0011 \u0010c3\u0011 \u0010r0\u0011 \u0010r1\u0011\nאֵין מְשַׁנִּין מָעוֹת פּוּרִים \u0010y6\u0011 לִצְדָקָה אַחֶרֶת. \u0005 הַגָּה: \u0010y7\u0011 \u0010m4\u0011 וְדַוְקָא הַגַּבָּאִים \u0006 \u0005(מָרְדְּכַי פ\"ק דְּבָבָא בַּתְרָא)\u0006, אֲבָל הֶעָנִי יָכוֹל לַעֲשׂוֹת בּוֹ \u0010y8\u0011 מַה שֶּׁיִּרְצֶה. \u0010g2\u0011 \u0010r2\u0011 \u0010r3\u0011\nאֵין מְדַקְדְּקִים בְּמָעוֹת פּוּרִים אֶלָּא כָּל מִי שֶׁפּוֹשֵׁט יָדוֹ לִטֹּל נוֹתְנִים לוֹ; \u0010y9\u0011 \u0010g3\u0011 \u0010m5\u0011 וּבְמָקוֹם שֶׁנָּהֲגוּ \u0010y10\u0011 לִתֵּן אַף לְעַכּוּ\"ם, \u0010t2\u0011 נוֹתְנִים. \u0010y11\u0011 \u0010g4\u0011 \u0010r4\u0011\nבְּמָקוֹם שֶׁאֵין עֲנִיִּים, יָכוֹל לְעַכֵּב \u0010y12\u0011 מָעוֹת פּוּרִים שֶׁלּוֹ לְעַצְמוֹ וְנוֹתְנָם בַּמָּקוֹם שֶׁיִּרְצֶה. \u0010r5\u0011 \u0010r6\u0011",{"g":["מהא דתני ר' יוסף מגילה ז'","בריית' כמציעא ע\"ח","שם","ר\"מ בשערי אפרים","\u0003מרדכי בפרק קמא דמגילה:\u0004 "],"t":["\u0003שתי מתנות. \u0004 עיין פר\"ח וביד אהרן. ואם נתן לאחד שיעור שתי מתנות אם יצא עיין הלק\"ט ח\"ב סי' ל\"ט דנוטה לכאן ולכאן עיין שם. ולא יתן להם קודם פורים דלמא אכלי להו קודם פורים. וכתבו ב\"ח וט\"ז אפי' עני המתפרנס מהצדקה חייב כמו בארבע כוסות מה שאין כן בשאר צדקה שאינו חייב רק פעם אחת בשנה כדי לקיים מצות צדקה כמ\"ש בי\"ד סי' רמ\"ח ורמ\"ט:","\u0003ואין. \u0004 דהיינו חיובא ליכא ומנהגא איכא דכתב לבוש ונוהגין ליתן מעות פורים בעד כל אחד ואחד אפי' בעד הילדים ונותנים המעוברות גם מהולד הגמ\"נ ואיתא במשנה כל קטן שהתחיל אביו לשקול על ידו שוב אינו פוסק. במקום דנהיגי לתת המעות מחצית השקל לחזן אין איסור בדבר דכל הנותן אדעתא דמנהג נותן מ\"ב סי' נ\"ד. אבל לא נפקו בזה ידי מתנות לאביונים אא\"כ מחלקים מהם לעניים מ\"א. וכתב של\"ה דמחצית השקל וכל שכן מתנות לאביונים ומשלוח מנות אין בא ממעות מעשר ואם בא להוסיף מוסיף משל מעשר מהרי\"ל בתשובה סי' נ\"ו ועיין כנה\"ג וביד אהרן. ומעות שחשב בלבו לחלקם ביום פורים אינו רשאי לשנות. ב\"י בשם הג\"א וע' בי\"ד ססי' רנ\"ח:","\u0003נותנים. \u0004 ולכתחלה אין לנהוג כן ליתן לעכו\"ם. מג\"א:"],"s":["\u0003שתי מתנות. \u0004 עבה\"ט ועיין פר\"ח דס\"ל דעני פטור ממתנות לאביונים ומשלוח מנות חייב והבר\"י כתב כדברי הב\"ח וט\"ז כדקי\"ל בי\"ד סימן רמ\"ח דאפי' עני המתפרנס מצדקה צריך לתת ממה שנתנו לו ובמח\"ב כתב שכ\"כ במטה יהודה עיין שם בשם זרע יעקב שאם נותן מעות צריך שיתן שיעור שיקנה ג' ביצים אוכל ואם נותן אוכלים צריך שיתן לו שיעור ג' ביצים מפת כך נראה לפום ריהטא ולפי\"ז אם מחלק לעניים מנה לכ\"א פרוטה לא יי\"ח ועדיין צריך להתישב עד כאן לשונו ואין גוף הספר בידי לדעת טעמו דבכל דוכתי נתינה בפרוטה עיין בפסחים דף ל\"ב ובגיטין דף ך' בתוספות שם ואפשר שלמד ממ\"ש בחולין ר\"פ ראשית הגז שיתן לו משקל ה' סלעים לעשות ממנו בגד קטן שנאמר תתן לו שיהא בו כדי מתנה וכן כ' הרמב\"ם בפרק יו\"ד מהלכות בכורים ובש\"ע י\"ד סי' של\"ג תתן לו שיהא בו כדי מתנה המועלת ולפ\"ז יש לומר דה\"ה כאן אינה קרויה מתנה אא\"כ יש בה כדי מתנה המועלת דהיינו כדי שיעור סעודה ואמנם שם דף קל\"ח איתא דהא דילפינן כדי לעשות בגד קטן מדכתיב לעמוד לשרת נפקא ועיין בשו\"ת נ\"ב מ\"ת בחלק יו\"ד סימן ר\"א שכת' בענין הפרשת חלה שיש בזה ב' מצות א' לאפקועי איסור טבל וע\"ז אין לו שיעור מה\"ת והשני לקיים מצות נתינה לכהן יש לו שיעור מה\"ת דכתיב תתנו כדי נתינה כו' ושם נשא ונתן בדברי התוספות בגיטין דף ך' ותמה עליהם ע\"ש שהאריך (ועיין ברמב\"ן בגיטין שם שכת' דלענין מילתא דהוי דררא דממונא הוי נתונה בפרוטה וגט שאני עיין שם) ונפלאתי שלא הזכיר מתני' דר\"פ ראשית הגז ומדברי המשנה למלך י\"ל מתנות עניים ה\"ל והמעיין יראה שהדברים קרובים עיין שם ומה שכת' בשם הלק\"ט בנותן לאחד שיעור שני מתנות כו' נראה מלשון הש\"ס והפוסקים דודאי לא יצא בפחות משני עניים ועיין בפר\"ח שהקשה אימא שני מתנות לכל אביון וכדפריך ביומא גבי ונתן על שני השעירים כו' ע\"ש ובבר\"י האריך בזה וע\"ש בא\"ר בשם הרמב\"ם טוב להרבות במתנות לאביונים מלהרבות בסעודתו ומשלוח מנות לרעים שאין שמחה גדולה ומפוארה אלא לשמח לב עניים יתומים ואלמנות וגרים ודומה לשכינה שנ' להחיות רוח שפלים ולהשיב לב נדכאים עד כאן לשונו:","\u0003ואין עבה\"ט. \u0004 מ\"ש במקום דנהיגי לתת המעות מחצית השקל להחזן כו' במח\"ב שגג בזה ע\"י טעות שנפל במג\"א וחסר הציון על סעיף ב' אין משנים מעות פורים כו' וע\"ז קאי המג\"א כמבואר במ\"ב וכמ\"ש ביד אפרים ומעולם לא עלה על הדעת שיהיה מנהג לתת מחצית השקל להחזן והבה\"ט שהוסיף מדעתו תיבות מחצית השקל לא כיון יפה והוא מכשול הגורם לגבאי צדקה שהם יד עניים לגרוע כוחם של עניים מצדקה זו שנותנית למחצית השקל לתתם להחזן וז\"ל המ\"ב מה שנוהגים בכמה קהילות שנותנין מעות פורים הכל לש\"צ הקורא את המגילה לו לבדו ואין מחלקים לעניים מעות פורים כלום אי שרי למיעבד הכי או צריך לבטל המנהג משום דתנא מגבת פורים כו' תשובה ודאי דלאו שפיר למיעבד הכי ומנהג כשר הוא לחלק לעניים אמנם היינו דוקא האיך שגבהו בהדיא לצורך העניים כו' או שמנהג אותה העיר כו' אבל באותן מקומות שכבר נהגו ליתן מעות פורים הכל לחזן הקורא המגילה איני רואה איסור שכל הנותן כו' ומחשבת כ\"א אדעתא דחזן דאין כאן דין מעות פורים ואע\"ג דמרגלא בפומי דאינשי לקרותם בשם מעות פורים לאו בשמא תליא מילתא אלא בגביות תליא מילתא וכן פירש\"י מגבת פורים מעות שגבו הגבאים מבני העיר לחלק לעניים לסעודת פורים כו' משא\"כ בנדון דידן מעולם לא גבי אדעתא דעניים כו' עכ\"ל מבואר שהיה דרך אותן המקומות לגבות מעות מבה\"כ ע\"ד ליתן לחזן הקורא המגילה והיה נקרא בשם מעות פורים ובזה כת' המ\"ב דינו אבל אין להקל במחצית השקל והאומר מנהג ע\"פ מ\"ש בבה\"ט אין שומעים לו כי הוא מנהג בטעות ואם נהגו צריך לבטלו ולדידי חזי לי ש\"ץ יראי ה' אשר רצו לזכות במחצית השקל מחמת דברי בה\"ט אלו והראיתי להם שהוא טעות וחזרו בהם ומשכו את ידם מן הוא והלאה ומ\"ש המ\"א שהביא הבה\"ט אבל לא נפקי בזה כו' זה מבואר גם כן דקאי על הך מעות הניתן לגבאים שנקרא עליהם שם מעות פורים:"],"m":["\u0003ב' מתנות\u0004. משלו ולא משל מעות מעשר [של\"ה] ואם בא להוסיף מוסיף משל מעשר [מהרי\"ל בתשו' סי' נ\"ו], וכתוב במאור דלא יתן להם קודם פורים דלמא אכלו להו קודם פורים:","\u0003בליל פורים\u0004. ובמדינתנו נותנין בשחרית קודם קריאת המגילה:","\u0003מבן כ' וכו'\u0004. זהו לדעת הר\"ע ברטנורה אבל התי\"ט כ' שהפוסקי' חולקים וס\"ל דבן י\"ג חייב ונשים פטורים בהג\"מ כ' דנשים וילדים חייבים ולא ידעתי מנ\"ל האי ואי' במשנה כל קטן שהתחיל אביו לשקול על ידו שוב אינו פוסק: במקום דנהיגי לתת המעות לחזן אין איסור בדבר דכל הנותן אדעתא דמנהג נותן [מ\"ב סי' נ\"ד] אבל לא נפקי בזה ידי מתנות לאביונים אא\"כ מחלקים מהם לעניים:","\u0003אין משנין\u0004. כ' ב\"י בשם הג\"א מעות שחשב בלבו לחלקם ביום פורים אינו רשאי לשנותו עכ\"ל ועבי\"ד ססי' רנ\"ח ובח\"מ סי' רי\"ב ס\"ח:","\u0003ודוקא הגבאים אבל כו'\u0004. בטור משמע שאף בני העיר אין יכולין לשנות וכ\"מ מל' רמ\"א כאן אבל המרדכי כ' בהדיא דבני העיר יכולין לשנות וא\"כ דינם כשאר צדקה כמ\"ש בי\"ד סי' רנ\"ו ס\"ד:","\u0003ובמקום שנהגו\u0004. אבל לכתחלה אין לנהוג ליתן לעכו\"ם:"],"r":["\u0003ס\"א י\"א שיש כו': ומאחר. \u0004ירושלמי פ\"ק דשקלים סוף הלכה א' שלש תרומות נאמרו בפרשה כו' וע\"ש פ\"ב הלכה ד' והעמדנו עלינו כו' מכאן שאדם חייב לשלש שקלו כו' ע\"ש ועפ\"ח דברכות וע' תו' דמגילה כ\"א א' ד\"ה קורא:","\u0003ואין חייב כו'. \u0004כמ\"ש בפרש' מבן עשרים כו' ומ\"ש בירושל' פ\"ק הלכ' ה' ז' ב' שערות שם בשכבר נתן פ\"א:","\u0003ס\"ב אין משנין כו' ואין מדקדקין כו'. \u0004בגמרא שם אי' מגבת פורים לפורים מגבת העיר לאותה העיר ואין מדקדקין בדבר אבל לוקחין את העגלים ושוחטין ואוכלין אותן והמותר יפול לכיס של צדקה ר' אליעזר אומר מגבת פורים לפורים ואין העני רשאי ליקח מהן רצועה לסנדלו אא\"כ התנה במע\"אה ד\"ר יעקב שאמר משום ר\"מ ורשב\"ג מיקל ופירש\"י ואין מדקדקין לומר דיים בפחות אבל לוקחין כו' וכ\"כ בהג\"א דפ\"ק דמגילה אבל הרמב\"ם פי' ואין מדקדקין בדבר ר\"ל כל הפושט יד כו'. והשמיט מש\"ש אבל לוקחין כו' והוא כגי' הרי\"ף ורא\"ש שם מגבת פורים לפורים ואין מדקדקין בדבר ואין העני רשאי ליקח כו':","\u0003ודוקא כו' אבל כו'. \u0004ע' תוס' ד\"ה ר\"א כו' ופ' כת\"ק והרי\"ף ורא\"ש כ' שם דלית הלכתא כוותיה אלא כרשב\"ג דמיקל דר\"מ אזיל לשיטתו כמ\"שש וקי\"ל כמתני' שסתם שם באחרונ' אם החליקה פטור כו' וכ\"ש להני אמוראי דלא מוקמי כלל למתני' כר\"מ ועוד דבמתני' לצבוע לו אדום קי\"ל כר\"י כמש\"ש בפ\"ק שם ובפ\"ק דע\"ז. וגי' שלנו צ\"ע שמתחיל בדברי ר\"א ומסיים בדברי ר' יעקב שאמר משום ר\"מ וגי' הרי\"ף נכונה וז\"ש דר\"מ אזיל לשיטתו. וז\"ל ירושל' פ\"ק דמגילה הלכה ד' אין משנין במעות פורים הא שאר כל המעות משנין אלא כל המעות עד שלא ינתנו לגזברין את רשאי לשנותן כו' ועי\"ד סי' רנ\"ט:","\u0003ס\"ג אין מדקדקין כו'. \u0004ג\"כ כגי' הרי\"ף וכ\"ה בירושלמי שם:","\u0003ס\"ד במקום שנהגו. \u0004גיטין ס\"א א' ועט\"ז ומ\"א:","\u0003במקום. \u0004ע' בחולין קל\"ד ב':"]}],["\u0005 הַגָּה: מִצְוָה לְהַרְבּוֹת בִּסְעֻדַּת פּוּרִים \u0006 \u0005(טוּר)\u0006; \u0010y0\u0011 \u0005 וּבִסְעֻדָּה אַחַת יוֹצְאִים \u0006 \u0005(מָרְדְּכַי ספ\"ק)\u0006. סְעֻדַּת פּוּרִים \u0010y1\u0011 שֶׁעֲשָׂאָהּ בַּלַּיְלָה, לֹא יָצָא יְדֵי חוֹבָתוֹ. \u0005 הַגָּה: וּמִכָּל מָקוֹם גַּם בַּלַּיְלָה \u0006 \u0005 יִשְׂמַח \u0010y2\u0011 וְיַרְבֶּה קְצָת בִּסְעֻדָּה. \u0006 \u0005(תְּשׁוּבַת מהרי\"ו)\u0006.\nחַיָּב אִינִישׁ לְבַסוֹמֵי בְּפוּרַיָּא עַד דְּלֹא יָדַע \u0010y3\u0011 בֵּין אָרוּר הָמָן לְבָרוּךְ מָרְדְּכַי. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵינוֹ צָרִיךְ לְהִשְׁתַּכֵּר כָּל כָּךְ, אֶלָּא שֶׁיִּשְׁתֶּה יוֹתֵר מִלִּמּוּדוֹ \u0006 \u0005(כָּל בּוֹ)\u0006 \u0010y4\u0011 \u0005 וְיִישַׁן, וּמִתּוֹךְ שֶׁיָּשֵׁן אֵינוֹ יוֹדֵעַ בֵּין אָרוּר הָמָן לְבָרוּךְ מָרְדְּכַי. \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0005 וְאֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט, וּבִלְבַד שֶׁיְּכַוֵּן לִבּוֹ לַשָּׁמַיִם. וְאֵין לְהִתְעַנּוֹת בְּפוּרִים, \u0010y5\u0011 מִלְּבַד תַּעֲנִית חֲלוֹם, \u0010y6\u0011 וְעַיֵּן לְעֵיל סִימָן תקס\"ח וְסִימָן תק\"ע. יֵשׁ שֶׁנָּהֲגוּ לִלְבֹּשׁ בִּגְדֵי שַׁבָּת וְיוֹם טוֹב בְּפוּרִים, וְכֵן נָכוֹן \u0006 \u0005(מַהֲרִי\"ל)\u0006; \u0005 וְנוֹהֲגִים לַעֲשׂוֹת סְעֻדַּת פּוּרִים \u0010y7\u0011 לְאַחַר \u0006 \u0005 מִנְחָה, וְעַרְבִית יִתְפַּלְּלוּ בַּלַּיְלָה. וּמִתְפַּלְּלִים מִנְחָה תְּחִלָּה \u0010y8\u0011 בְּעוֹד הַיּוֹם גָּדוֹל; וְרֹב הַסְּעֻדָּה צְרִיכָה לִהְיוֹת בַּיּוֹם \u0006 \u0005(מִנְהָגִים)\u0006, \u0005 וְלֹא כְּמוֹ שֶׁנּוֹהֲגִין לְהַתְחִיל סָמוּךְ לָעֶרֶב וְעִקַּר הַסְּעֻדָּה הוּא לֵיל ט\"ו. וּכְשֶׁחָל פּוּרִים בְּיוֹם שִׁשִּׁי, יַעֲשׂוּ \u0010y9\u0011 הַסְּעֻדָּה בְּשַׁחֲרִית, מִשּׁוּם כְּבוֹד שַׁבָּת \u0006 \u0005(מִנְהָגִים)\u0006; \u0005 וּמִי שֶׁרוֹצֶה לַעֲשׂוֹתָהּ תָּמִיד בְּשַׁחֲרִית, הָרְשׁוּת בְּיָדוֹ \u0006 \u0005(ת\"ה)\u0006. \u0005 יֵשׁ אוֹמְרִים שֶׁיֵּשׁ \u0010y10\u0011 לֶאֱכֹל מַאֲכַל זֵרְעוֹנִים בְּפוּרִים, זֵכֶר לַזֵּרְעוֹנִים שֶׁאָכַל \u0010y11\u0011 דָּנִיּאֵל וַחֲבֵרָיו בְּבָבֶל \u0006 \u0005(כָּל בּוֹ)\u0006. \u0005 טוֹב לַעֲסֹק מְעַט בַּתּוֹרָה קֹדֶם שֶׁיַּתְחִיל הַסְּעֻדָּה, וְסֶמֶךְ לַדָּבָר: לַיְּהוּדִים הָיְתָה אוֹרָה וְשִׂמְחָה \u0006 \u0005(אֶסְתֵּר ח, טז)\u0006 \u0005 וְדַרְשִׁינָן: אוֹרָה, זוֹ תּוֹרָה \u0006 \u0005(מהרי\"ב)\u0006. \u0005 וְחַיָּב בְּמִשְׁתֶּה וְשִׂמְחָה קְצָת בִּשְׁנֵי יָמִים, י\"ד וְט\"ו, \u0006 \u0005(מִנְהָגִים)\u0006 \u0005 וְכֵן נָהֲגוּ. וְיֵשׁ אוֹמְרִים \u0010y12\u0011 דְאִם הִזִּיק אֶחָד אֶת \u0010y13\u0011 חֲבֵרוֹ מִכֹּחַ שִׂמְחַת פּוּרִים, \u0006 \u0005 פָּטוּר מִלְּשַׁלֵּם. \u0006 \u0005(ת\"ה סִימָן ק\"י)\u0006. \u0005 וְעַיֵּן בח\"מ בְּדִינֵי נְזִיקִין. \u0010y14\u0011 \u0006 \u0010c0\u0011 \u0010c1\u0011\nאוֹמֵר עַל הַנִּסִים בְּבִרְכַּת הַמָּזוֹן בְּבִרְכַּת הָאָרֶץ; וְאִם הִתְחִיל סְעוּדָתוֹ בַּיּוֹם וּמָשְׁכָה עַד הַלַּיְלָה, \u0010y15\u0011 אוֹמֵר: עַל הַנִּסִים, דְּבָתַר תְּחִלַּת סְעֻדָּה אַזְלִינָן; וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאֵין \u0010y16\u0011 לְאָמְרוֹ, \u0005 וְנוֹהֲגִין כִּסְבָרָא \u0006 \u0005 רִאשׁוֹנָה. \u0010y17\u0011 \u0010y18\u0011 \u0006\nחַיָּב לִשְׁלֹחַ לַחֲבֵרוֹ שְׁתֵּי מָנוֹת בָּשָׂר אוֹ שֶׁל \u0010y19\u0011 מִינֵי אֳכָלִים, שֶׁנֶּאֱמַר: וּמִשְׁלוֹחַ מָנוֹת אִישׁ לְרֵעֵהוּ \u0005(אֶסְתֵּר ט, יט ו כב)\u0006 שְׁתֵּי מָנוֹת לְאִישׁ אֶחָד. וְכָל הַמַּרְבֶּה לִשְׁלֹח לְרֵעִים מְשֻׁבָּח; וְאִם אֵין לוֹ, מַחֲלִיף עִם \u0010y20\u0011 חֲבֵרוֹ, זֶה שׁוֹלֵחַ לָזֶה סְעוּדָתוֹ, וְזֶה שׁוֹלֵחַ לָזֶה סְעוּדָתוֹ, כְּדֵי לְקַיֵּם: וּמִשְׁלוֹחַ מָנוֹת אִישׁ לְרֵעֵהוּ \u0005(אֶסְתֵּר ט, יט ו כב)\u0006. \u0005 הַגָּה: וְיֵשׁ \u0010y21\u0011 לִשְׁלֹחַ מָנוֹת \u0006 \u0005 בַּיּוֹם וְלֹא בַּלַּיְלָה \u0006 \u0005(מִדִּבְרֵי הָרֹא\"שׁ פ\"ק דִּמְגִלָּה)\u0006; \u0005 וְאִם שׁוֹלֵחַ מָנוֹת לְרֵעֵהוּ וְהוּא אֵינוֹ רוֹצֶה לְקַבְּלָם, \u0010y22\u0011 אוֹ מוֹחֵל לוֹ, \u0010y23\u0011 יָצָא. \u0010y24\u0011 \u0006 \u0005 וְאִשָּׁה חַיֶּבֶת בְּמַתָּנוֹת לָאֶבְיוֹנִים וּמִשְׁלוֹחַ מָנוֹת, כָּאִישׁ; וְאִשָּׁה תִּשְׁלַח לְאִשָּׁה, וְאִישׁ לְאִישׁ; אֲבָל לֹא בְּהֶפֶךְ, שֶׁלֹּא יָבֹא אִישׁ לִשְׁלֹחַ לְאַלְמָנָה וְיָבוֹאוּ לִידֵי \u0010y25\u0011 סְפֵק קִדּוּשִׁין, אֲבָל בְּמַתָּנוֹת לָאֶבְיוֹנִים \u0010y26\u0011 אֵין לָחוּשׁ. \u0006 \u0010c2\u0011 \u0010c3\u0011",["\u0003ובסעודה אחת יוצאים\u0004 לאפוקי ממ\"ד דחייב לאכול גם בלילה של י\"ד דומיא דמגילה ומ\"מ נכון לאכול גם בלילה וכדלקמיה בס\"א בהג\"ה:","\u0003שעשאה בלילה\u0004 היינו בליל י\"ד דבליל ט\"ו לבני עיירות פשיטא דכבר עבר זמנה:","\u0003וירבה קצת בסעודה\u0004 ואפילו כשחל הי\"ד במוצאי שבת דעשה סעודה חשובה בסעודה שלישית מ\"מ צריך להרבות קצת בלילה לכבוד פורים אך אינה סעודה כמו למחר דשם צריך להרבות יותר. כתבו האחרונים דנכון ללבוש בגדי שבת ג\"כ מבערב וימצא אח\"כ בביתו נרות דולקות ושולחן ערוך ומטה מוצעת:","\u0003בין ארור המן\u0004 שזה מפלה ראשונה שניטל נקמה רבה ממנו ועוד טובה יתרה מזה גדולת מרדכי שבירכו הקב\"ה שעלה למעלה ראש והנה קודם שנשתכר נתן בודאי תודה להש\"י על שתי הטובות וע\"כ אחז\"ל שלא יפסיק מלתן שבח ע\"ז בשמחה עד שיבוא לידי כך שלא יבחין עוד מה בין טובה זו לזו. ועיין בא\"ז דמ\"מ יראה להיות זהיר בענין נט\"י וברכת המוציא ובהמ\"ז ויהיה שמחה של מצוה ועיין בפמ\"ג שכתב דענין סעודת פורים ומתנות לאביונים ומשלוח מנות אפשר דצריך כונה ע\"ז לשם מצוה:","\u0003וישן ומתוך שישן וכו'\u0004 וכן ראוי לעשות [פמ\"ג]:","\u0003מלבד תענית חלום\u0004 ויתענה עד אחר מנחה ויאכל קודם ביאת השמש רק פ\"א. הנשבע להתענות בפורים יראה להתיר שבועתו:","\u0003וע\"ל סימן תקס\"ח\u0004 ס\"ה ובסימן תק\"ע בכל הסימן:","\u0003לאחר מנחה\u0004 הא דלא נהיגי לעשותה בשחרית משום שטרודים במשלוח מנות ונמשכין ברוב עד המנחה ואסורין להתחיל בסעודה קודם מנחה:","\u0003בעוד היום גדול\u0004 כתב א\"ר בשם של\"ה המשובח מי שעושה סעודה בשחרית וכתב עוד שיקבץ אנשי ביתו וחביריו דא\"א לשמוח כראוי ביחיד. ומ\"מ יהיה שמחה של ד\"ת וכדלקמיה:","\u0003הסעודה בשחרית\u0004 היינו קודם חצות היום לכתחלה ועיין ביד אפרים מה שכתב בשם מהרי\"ל:","\u0003מאכל זרעונים\u0004 בלילה הראשונה:","\u0003דניאל וחביריו\u0004 וגם אסתר אכלה זרעונים כדאמרינן פ\"ק דמגילה וישנה לטוב שהאכילה זרעונין:","\u0003דאם הזיק וכו'\u0004 בב\"ח מחלק בין היזק גדול לקטן בין בגוף בין בממון דבהיזק גדול מקפידין ואין מנהג לפטור בהיזק גדול:","\u0003מכח שמחת פורים\u0004 פי' שעשה מכח שמחה אבל אם כיון להזיק חייב:","\u0003אומר עה\"נ בבהמ\"ז וכו'\u0004 ואם שכח לומר עה\"נ י\"א דמחזירין אותו וי\"א דאין מחזירין אותו וספק ברכות להקל ודוקא בסעודה ראשונה שאוכל בו ביום אבל בסעודה שניה שאוכל אחר המנחה שקורין סעודת פורים וכבר אכל סעודה אחת ביום שוב אין מחזירין אותו לכו\"ע אלא כשמגיע להרחמן יאמר הרחמן הוא יעשה לנו נסים וכו'. כשחל פורים בע\"ש ומשכה סעודתו עד הלילה חייב להזכיר של עכשיו דהיינו רצה וא\"כ איך יאמר על הניסים דהוי תרתי דסתרי וכיון דאין הזכרת עה\"נ חמור כ\"כ לכן יאמר רק של שבת. וכ\"ז אפילו כשלא התפלל עדיין ובפרט אם התפלל מקודם בודאי אינו כדאי להזכיר אח\"כ עה\"נ בבהמ\"ז וכדלקמיה:","\u0003אומר על הניסים\u0004 י\"א דוקא כשלא התפלל ערבית עדיין אבל משהתפלל שוב אינו אומר עה\"נ וי\"א דבכל גווני אומר וע\"כ מהנכון שיברך בהמ\"ז קודם שיתפלל להוציא עצמו מפלוגתא. ואם רוצה למצוא תקנה שיתפללו קצת מהצבור בבהכ\"נ כדרכו תמיד נראה שמשהגיע הזמן בלילה יברך בהמ\"ז ויאמר עה\"נ וילך לבהכ\"נ להתפלל ואח\"כ יכול לאכול ולשתות ולשמוח עוד דהא מצוה בשמחה בשני ימים:","\u0003ונוהגין וכו'\u0004 ובזה אם לא אמרו בודאי אין מחזירין אותו אפילו לדעת המחמירין הנ\"ל דהא אפילו בלכתחלה יש פלוגתא אם לאמרו וכנ\"ל:","\u0003לשלוח\u0004 בת' בנין ציון סי' מ\"ד נסתפק אם הביא בעצמו המנות ולא ע\"י שליח אי יוצא כיון דכתיב ומשלוח נימא דבעינן דוקא ע\"י שליחות ע\"ש:","\u0003שתי מתנות\u0004 בעניים הקפידו ליתן לשני עניים דמצוה לחלק משא\"כ בעשיר דדי כשנותן לאחד:","\u0003מיני אוכלין\u0004 ולא בגדים ושארי דברים וה\"ה משקה דשפיר דמי דשתיה בכלל אכילה וכן סגי באחד אוכל ואחד משקה ובעינן שיהיה מין אוכל המבושל ולא בשר חי דמשלוח מנות הראוי מיד לאכילה משמע וי\"א דכיון שהוא שחוט וראוי להתבשל מיד שרי:","\u0003זה שולח לזה וכו'\u0004 ויוצא י\"ח אע\"פ שהולך אח\"כ לסעוד אצלו:","\u0003לשלוח מנות ביום\u0004 וה\"ה מתנות לאביונים אם לא שקיים המצוה דשילוח מנות לאיש אחד ומתנות לשני אביונים ביום אין נ\"מ במה שרוצה להוסיף עוד בלילה:","\u0003או מוחל לו\u0004 ר\"ל שאומר הריני כאלו התקבלתי:","\u0003יצא\u0004 והפר\"ח חולק ע\"ז וכן החתם סופר בסי' קצ\"ו מתמה ע\"ז:","\u0003ואשה חייבת וכו'\u0004 שכולן היו באותו הנס וצריכה היא לשמוח ולשמח לב אביונים וכתיב קימו וקיבלו היהודים וגו' וגם נשים בכלל. וכתב המ\"א לא ראיתי נזהרין בזה ואפשר דוקא באלמנה אבל אשה שיש לה בעל בעלה משלח בשבילה לכמה אנשים ומ\"מ יש להחמיר:","\u0003ספק קידושין\u0004 שיאמרו שזהו סבלונות שאחר הקידושין וחיישינן שמא קידשה כבר בפני עדים ואינם לפנינו:","\u0003אין לחוש\u0004 דזה הוי במעות וליכא למיחש לסבלונות ואפילו אם נותן לאביון מאכל הוא דרך צדקה ואינו דרך סבלונות:"],["\u0003 חייב איניש וכו'\u0004 - וא\"ת האיך יחייבו חז\"ל מה שנזכר בתורה ובנביאים בכמה מקומות השיכרות למכשול גדול וי\"ל מפני שכל הניסים שנעשו לישראל בימי אחשורוש היו ע\"י משתה כי בתחלה נטרדה ושתי ע\"י משתה ובאה אסתר וכן ענין המן ומפלתו היה ע\"י משתה ולכן חייבו חכמים להשתכר עד כדי שיהא נזכר הנס הגדול בשתיית היין. ומ\"מ כ\"ז למצוה ולא לעכב [א\"ר]:","\u0003 עד דלא ידע וכו'\u0004 - וז\"ל המאירי חייב אדם להרבות בשמחה ביום זה ובאכילה ובשתיה עד שלא יחסר שום דבר ומ\"מ אין אנו מצוין להשתכר ולהפחית עצמינו מתוך השמחה שלא נצטוינו על שמחה של הוללות ושל שטות אלא בשמחה של תענוג שיגיע מתוכה לאהבת הש\"י והודאה על הנסים שעשה לנו וע\"ש מה שמבאר דברי הגמרא. וז\"ל הח\"א כיון שכל הנס היה ע\"י יין לכן חייבו חכמים להשתכר ולפחות לשתות יותר מהרגלו כדי לזכור הנס הגדול ואמנם היודע בעצמו שיזלזל אז במצוה מן המצות בנט\"י וברכה ובהמ\"ז או שלא יתפלל מנחה או מעריב או שינהוג קלות ראש מוטב שלא ישתכר וכל מעשיו יהיו לש\"ש עכ\"ל:","\u0003 חייב לשלוח לחבירו וכו'\u0004 - הח\"א הוכיח מן הירושלמי דאם שולח לעשיר דבר פחות אינו יוצא בזה ידי משלוח מנות וכן משמע בריטב\"א לפי גירסא אחת שם בגמרא. אכן ש\"פ לא הזכירו דבר זה ונכון ליזהר בזה לכתחלה:","\u0003 או של מיני אוכלים וכו'\u0004 - בטורי אבן מסתפק אם שלח ב' מנות לאיש עני אם יוכל לחשבם לתרתי לקיום שילוח מנות דגם העני בכלל איש לרעהו ולקיים מתנות לאביונים ואם נתן עוד מתנה א' לעני אחד יצא או לא והביאו הגרע\"א בחידושיו. כתב הפר\"ח עיר ספק מוקף ישלחו המנות בי\"ד שהוא לרוב העולם ועיין בפמ\"ג שמפקפק בזה:"],"\u0005 הַגָּה: מִצְוָה \u0010g0\u0011 לְהַרְבּוֹת בִּסְעֻדַּת פּוּרִים \u0006 \u0005(טוּר)\u0006; \u0010y0\u0011 \u0010m0\u0011 \u0005 וּבִסְעֻדָּה אַחַת יוֹצְאִים \u0006 \u0005(מָרְדְּכַי ספ\"ק)\u0006. \u0010g1\u0011 סְעֻדַּת פּוּרִים \u0010y1\u0011 שֶׁעֲשָׂאָהּ \u0010m1\u0011 בַּלַּיְלָה, לֹא יָצָא יְדֵי חוֹבָתוֹ. \u0005 הַגָּה: וּמִכָּל מָקוֹם גַּם בַּלַּיְלָה \u0010t0\u0011 \u0006 \u0005 יִשְׂמַח \u0010y2\u0011 וְיַרְבֶּה קְצָת בִּסְעֻדָּה. \u0006 \u0005(תְּשׁוּבַת מהרי\"ו)\u0006. \u0010g2\u0011 \u0010r0\u0011 \u0010r1\u0011\nחַיָּב אִינִישׁ לְבַסוֹמֵי בְּפוּרַיָּא עַד דְּלֹא יָדַע \u0010y3\u0011 בֵּין אָרוּר הָמָן לְבָרוּךְ מָרְדְּכַי. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵינוֹ צָרִיךְ לְהִשְׁתַּכֵּר כָּל כָּךְ, \u0010m2\u0011 אֶלָּא שֶׁיִּשְׁתֶּה יוֹתֵר מִלִּמּוּדוֹ \u0006 \u0005(כָּל בּוֹ)\u0006 \u0010y4\u0011 \u0010t1\u0011 \u0010s0\u0011 \u0005 וְיִישַׁן, וּמִתּוֹךְ שֶׁיָּשֵׁן אֵינוֹ יוֹדֵעַ בֵּין אָרוּר הָמָן לְבָרוּךְ מָרְדְּכַי. \u0010g3\u0011 \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0005 וְאֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט, וּבִלְבַד שֶׁיְּכַוֵּן לִבּוֹ לַשָּׁמַיִם. וְאֵין לְהִתְעַנּוֹת בְּפוּרִים, \u0010y5\u0011 מִלְּבַד \u0010m3\u0011 תַּעֲנִית חֲלוֹם, \u0010y6\u0011 וְעַיֵּן לְעֵיל סִימָן תקס\"ח וְסִימָן תק\"ע. יֵשׁ שֶׁנָּהֲגוּ לִלְבֹּשׁ בִּגְדֵי שַׁבָּת וְיוֹם טוֹב בְּפוּרִים, וְכֵן נָכוֹן \u0006 \u0005(מַהֲרִי\"ל)\u0006; \u0005 וְנוֹהֲגִים לַעֲשׂוֹת סְעֻדַּת פּוּרִים \u0010y7\u0011 לְאַחַר \u0010t2\u0011 \u0006 \u0005 מִנְחָה, וְעַרְבִית יִתְפַּלְּלוּ בַּלַּיְלָה. וּמִתְפַּלְּלִים מִנְחָה תְּחִלָּה \u0010y8\u0011 בְּעוֹד הַיּוֹם גָּדוֹל; \u0010m4\u0011 וְרֹב הַסְּעֻדָּה צְרִיכָה לִהְיוֹת בַּיּוֹם \u0006 \u0005(מִנְהָגִים)\u0006, \u0005 וְלֹא כְּמוֹ שֶׁנּוֹהֲגִין לְהַתְחִיל סָמוּךְ לָעֶרֶב וְעִקַּר הַסְּעֻדָּה הוּא לֵיל ט\"ו. וּכְשֶׁחָל פּוּרִים בְּיוֹם שִׁשִּׁי, יַעֲשׂוּ \u0010y9\u0011 הַסְּעֻדָּה בְּשַׁחֲרִית, מִשּׁוּם כְּבוֹד שַׁבָּת \u0006 \u0005(מִנְהָגִים)\u0006; \u0005 וּמִי שֶׁרוֹצֶה לַעֲשׂוֹתָהּ תָּמִיד בְּשַׁחֲרִית, הָרְשׁוּת בְּיָדוֹ \u0006 \u0005(ת\"ה)\u0006. \u0005 יֵשׁ אוֹמְרִים שֶׁיֵּשׁ \u0010y10\u0011 לֶאֱכֹל מַאֲכַל \u0010m5\u0011 זֵרְעוֹנִים בְּפוּרִים, זֵכֶר לַזֵּרְעוֹנִים שֶׁאָכַל \u0010y11\u0011 דָּנִיּאֵל וַחֲבֵרָיו בְּבָבֶל \u0006 \u0005(כָּל בּוֹ)\u0006. \u0005 טוֹב לַעֲסֹק מְעַט בַּתּוֹרָה קֹדֶם שֶׁיַּתְחִיל הַסְּעֻדָּה, וְסֶמֶךְ לַדָּבָר: לַיְּהוּדִים הָיְתָה אוֹרָה וְשִׂמְחָה \u0006 \u0005(אֶסְתֵּר ח, טז)\u0006 \u0005 וְדַרְשִׁינָן: אוֹרָה, זוֹ תּוֹרָה \u0006 \u0005(מהרי\"ב)\u0006. \u0005 וְחַיָּב בְּמִשְׁתֶּה וְשִׂמְחָה קְצָת בִּשְׁנֵי יָמִים, י\"ד וְט\"ו, \u0006 \u0005(מִנְהָגִים)\u0006 \u0005 וְכֵן נָהֲגוּ. וְיֵשׁ אוֹמְרִים \u0010y12\u0011 \u0010m6\u0011 דְאִם הִזִּיק אֶחָד אֶת \u0010y13\u0011 \u0010m7\u0011 חֲבֵרוֹ מִכֹּחַ שִׂמְחַת פּוּרִים, \u0010t3\u0011 \u0006 \u0005 פָּטוּר מִלְּשַׁלֵּם. \u0006 \u0005(ת\"ה סִימָן ק\"י)\u0006. \u0005 וְעַיֵּן בח\"מ בְּדִינֵי נְזִיקִין. \u0010y14\u0011 \u0010g4\u0011 \u0010g5\u0011 \u0010m8\u0011 \u0006 \u0010c0\u0011 \u0010c1\u0011 \u0010r2\u0011 \u0010r3\u0011 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011\nאוֹמֵר עַל \u0010t4\u0011 הַנִּסִים בְּבִרְכַּת הַמָּזוֹן בְּבִרְכַּת הָאָרֶץ; וְאִם הִתְחִיל סְעוּדָתוֹ בַּיּוֹם וּמָשְׁכָה עַד הַלַּיְלָה, \u0010y15\u0011 \u0010g6\u0011 אוֹמֵר: עַל הַנִּסִים, דְּבָתַר תְּחִלַּת סְעֻדָּה אַזְלִינָן; \u0010g7\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאֵין \u0010y16\u0011 \u0010m9\u0011 לְאָמְרוֹ, \u0005 וְנוֹהֲגִין כִּסְבָרָא \u0010t5\u0011 \u0010s1\u0011 \u0006 \u0005 רִאשׁוֹנָה. \u0010y17\u0011 \u0010y18\u0011 \u0010g8\u0011 \u0010m10\u0011 \u0006 \u0010r9\u0011 \u0010r10\u0011 \u0010r11\u0011 \u0010r12\u0011\nחַיָּב לִשְׁלֹחַ לַחֲבֵרוֹ שְׁתֵּי מָנוֹת \u0010t6\u0011 \u0010s2\u0011 בָּשָׂר אוֹ שֶׁל \u0010y19\u0011 מִינֵי אֳכָלִים, שֶׁנֶּאֱמַר: וּמִשְׁלוֹחַ מָנוֹת אִישׁ לְרֵעֵהוּ \u0010m11\u0011 \u0005(אֶסְתֵּר ט, יט ו כב)\u0006 שְׁתֵּי מָנוֹת לְאִישׁ אֶחָד. \u0010g9\u0011 וְכָל הַמַּרְבֶּה \u0010g10\u0011 לִשְׁלֹח לְרֵעִים מְשֻׁבָּח; וְאִם אֵין לוֹ, מַחֲלִיף עִם \u0010y20\u0011 חֲבֵרוֹ, זֶה \u0010g11\u0011 שׁוֹלֵחַ לָזֶה סְעוּדָתוֹ, וְזֶה שׁוֹלֵחַ לָזֶה סְעוּדָתוֹ, כְּדֵי לְקַיֵּם: וּמִשְׁלוֹחַ מָנוֹת אִישׁ לְרֵעֵהוּ \u0005(אֶסְתֵּר ט, יט ו כב)\u0006. \u0005 הַגָּה: וְיֵשׁ \u0010y21\u0011 \u0010m12\u0011 לִשְׁלֹחַ מָנוֹת \u0010t7\u0011 \u0006 \u0005 בַּיּוֹם וְלֹא בַּלַּיְלָה \u0006 \u0005(מִדִּבְרֵי הָרֹא\"שׁ פ\"ק דִּמְגִלָּה)\u0006; \u0005 וְאִם שׁוֹלֵחַ מָנוֹת לְרֵעֵהוּ וְהוּא אֵינוֹ רוֹצֶה לְקַבְּלָם, \u0010y22\u0011 אוֹ מוֹחֵל לוֹ, \u0010y23\u0011 יָצָא. \u0010y24\u0011 \u0010t8\u0011 \u0010s3\u0011 \u0010s4\u0011 \u0010m13\u0011 \u0006 \u0005 וְאִשָּׁה חַיֶּבֶת בְּמַתָּנוֹת לָאֶבְיוֹנִים וּמִשְׁלוֹחַ מָנוֹת, כָּאִישׁ; וְאִשָּׁה תִּשְׁלַח לְאִשָּׁה, וְאִישׁ לְאִישׁ; אֲבָל לֹא בְּהֶפֶךְ, שֶׁלֹּא יָבֹא אִישׁ לִשְׁלֹחַ לְאַלְמָנָה וְיָבוֹאוּ לִידֵי \u0010y25\u0011 \u0010m14\u0011 סְפֵק קִדּוּשִׁין, אֲבָל בְּמַתָּנוֹת לָאֶבְיוֹנִים \u0010y26\u0011 אֵין לָחוּשׁ. \u0006 \u0010c2\u0011 \u0010c3\u0011 \u0010r13\u0011 \u0010r14\u0011 \u0010r15\u0011",{"g":["שם בגמרא דמגילה ז'","מימרא דרבא שם","ג\"ז מימרא דרבא שם","דיש מפרשים שברוך מרדכי וארור המן חושבני' דדין כחושבני' דדין ושצריך לשתות כל כך עד שלא ידע לכוין המספר","\u0003סוף סימן שע\"ח:\u0004 ","שבת כד כרב הונא ורב ששת","הגהת מיי' בפ' ב' מהלכות מגילה בשם הר\"מ וא\"ח בשם הר\"י מקורביל","טור בשם אביו הרא\"ש","ציינתי לעיל ריש סי' תרצ\"ד","רמב\"ם בפ\"ב מהלכות מגילה","מהא דאביי בר אבין ורב חנינא בר אבין שם במגילה","\u0003כפירוש הר\"ן שם:\u0004 "],"t":["\u0003ישמח. \u0004 אפי' בליל י\"ד עב\"ח וכ\"כ שכנה\"ג וילבוש בגדי שבת ג\"כ מבערב מצאתי וכ\"כ בסדה\"י וז\"ל וימלא בביתו נרות דולקות ושלחן ערוך ומטה מוצעת:","\u0003וישן. \u0004 י\"א שלא ידע לחשוב שארור המן בגימטרי' ברוך מרדכי. וט\"ז כתב לפענ\"ד נראה לפרש דצריך האדם לתת שבח לו יתברך על טובה כפולה שעשה עמנו הא' פורעניות שהביא הוא על המן ואלו לא נתברך מרדכי אלא היה ניצול עם כל ישראל דיינו אלא שבירכו למרדכי בגדולה מאוד והטובה יתירה ע\"כ אמר צריך לבסומי עד שלא ידע מעלתינו מן ארור המן שזה מפלה שלו לברוך מרדכי שזה מעלתינו שניה ע\"ש:","\u0003מנחה. \u0004 ושל\"ה כתב דיעשה הסעודה קודם מנחה ע\"ש:","\u0003פטור. \u0004 ואם כוון להזיק חייב עיין ח\"מ ס\"ס שע\"ח ועיין מ\"א ס\"ק ז':","\u0003הנסים. \u0004 ואם שכח על הנסים בברכת המזון מחזירין אותו דלא סגי דלא אכיל. של\"ה רש\"ל מט\"מ. וכתבו הט\"ז ומ\"א דהיינו דוקא בסעודה הראשונה שאוכל בפורים דהא עיקר הטעם דיש חיוב סעודתו באותו יום דכתיב ימי משתה ושמחה וא\"כ סעודה ראשונה שאוכל בו ביום בו קיים סעודת פורים בזה ואין לנו לתלות הדין במה שאנו קורין לסעודה שאחר המנחה סעודת פורים וא\"כ אם כבר אכל סעודה ראשונה ביום שוב אין מחזירין אותו ע\"ש. וא\"ז כתב בשם מהר\"ל מפראג שפסק דלא כשל\"ה ומהרש\"ל אלא כשמגיע להרחמן יאמר הרחמן יעשה לנו נסים עיין סי' תרפ\"ב:","\u0003ראשונה. \u0004 ועיין סי' קפ\"ח סעיף י' מש\"ש ומ\"כ במרדכי כתוב בקלף היה אוכל סעודת פורים בע\"ש יתפלל ויפרוס מפה ויקדש ובברכת המזון יאמר על הנסים עכ\"ל ובמט\"מ ובמנהגים כתבו הואיל ולא התפלל ערבית משמע דאם התפלל שוב אינו אומר על הנסים וכ\"כ של\"ה ומהרי\"ל בתשובה סי' נ\"ו לכן נ\"ל דיברך ברכת המזון תחלה ואח\"כ יתפלל ערבית להוציא עצמו מפלוגתא וגם שלא ישתכר ולא יברך ברכת המזון. מ\"א:","\u0003בשר. \u0004 מבושל הראוי לאכילה מהרי\"ל וה\"ה משקה של\"ה. השולח מעות כסות וכלים בשביל מנות אם יכול למכרם מיד לקנות לצורך סעודה מהני הלק\"ט ח\"ב סי' קס\"ג. ומדברי בעל ת\"ה סי' קי\"א משמע קצת דלא יצא עיין שם ע' יד אהרן. נסתפקתי מי ששלח לחבירו בשביל מנות תרנגולת טריפה והוא לא ידע ואכלו ואח\"כ ביום פורים עצמו נודע לו שהיתה טריפה אם יצא ידי חובת מנות אם לא ע' בספ' מוצל מאש סי' ס\"א. עוד נסתפקתי מי ששלח לחבירו שבמדינת הים שני מנות. או שתי מתנות לשני אביונים קודם פורים ובפורים עצמו בודאי מגיעים לידו אם יוצא י\"ח או לא מי נימא כיון דבשעה ששלח לא הי' חייב בהם לא נפיק או דילמא כיון דבפורים עצמו שהוא שעת החיוב הגיעו לידו נפיק. ע' יד אהרן שדעתו נוטה דיוצא י\"ח שפיר בזה ע\"ש מי ששלח לחבירו דג וביצ' שעליו או פת ופניו טוחות בביצה יש להסתפק אי יוצא י\"ח של משלוח מנות עדות ביעקב סי' צ\"ב ע\"ש וע' כנה\"ג:","\u0003ביום. \u0004 וה\"ה מתנות לאביונים:","\u0003ואשה. \u0004 לא ראיתי נזהרין בזה ואפשר דוקא באלמנות אבל אשה שיש לה בעל בעלה משלח בשביל' לכמה בני אדם ומ\"מ יש להחמיר מ\"א. נראה לי דמי שאוכל על שלחן חבירו ולא הכין לו כלום פטור מלשלוח מנות וכ\"מ קצת ברש\"י גבי מחלפי סעודתייהו להדדי וע' ט\"ז ס\"ק ג'. ומ\"מ צ\"ע וטוב להחמיר מ\"א. וכתב בסה\"י יקבץ כל אנשי ביתו וחביריו דאם אדם יושב ביחיד א\"א לשמוח כראוי וכ\"כ רש\"י ז\"ל בפסוק משפחה ומשפחה:"],"s":["\u0003 (ס\"א) בש\"ע מצוה להרבות כו' \u0004 וע' בבר\"י בשם א' קדוש בתשובה כת\"י אם עשה סעודת פורים בלא לחם יצא ועיין שם בשם מהר\"י מולכו מי שאכל בליל פורים ונמשכה סעודתו עד היום ואכל קצת ביום יצא ועיין בכנה\"ג ופר\"ח דבלילה אפי' אבוקה כנגדו לא יצא ומ\"ש הב\"י שי\"מ כעין לילה שאין אבוקה כנגדו היינו אף ביום ובבית אפל אבל כשאינו אפל פשיט' שא\"צ הדלקה דשרגא בטיהרא מאי מהני ואני ראיתי חסידים ואנשי מעשה כשהיו יושבין בסעודה לאחר מנחה הי' מדליקין נרות לשמוח בהם עד כאן לשון הבני חייא ועיין בליקוטי פר\"ח שכת' בשם ת\"ה ס\"ק ק' כשעושה סעודה ביום מדליק אבוקה דרך שמחה ויו\"ט ע\"ש וכעת לא מצאתי בת\"ה ועיין במח\"ב מ\"ש על ספר שונה הלכות בזה וכת' במור וקציעה נ\"ל שא\"צ להזהר לעשות בסעודת פורים זכר לאבילות ירושלים כיון דחייב לבסומי עד דלא ידע כו':","\u0003וישן. \u0004 עבה\"ט ועיין בסידור עמודי שמים שכת' שאביו הגאון ז\"ל היה נוהג בימי בחרותו לקיים המימרא כפשוטו. ומי שהוא חלש בטבעו (או שמשתטה עד שאפשר שיבא עי\"ז לידי מעשה או דברים שלא כהוגן) אין לו לשתות יותר מדאי וראיה לדבר ריב\"א ודוק עכ\"ל. וכוונתו במ\"ש ריב\"א הוא ר\"ת ר' יהודה בר אילעי ר\"ל שר\"י בר אילעי אמר בירוש' דלא שתי אלא מפסחא לפסחא וחוגרני צדעי כו' משמע דבפורים לא שתה כיון ששתייתו היה מזיק לבריאת גופו:","\u0003ראשונה. \u0004 עבה\"ט ועיין בהר הכרמל סי' ז' שכת' דגם מהרי\"ל לא קאמר אלא בשבת אבל בפורים לא הוי סתרי אהדדי מה שאינו אומר עה\"נ בתפלה דזה שתיקה היא ואינו סתירה כדיבור ושפיר צריך להזכיר עה\"נ בלילה אפילו התפלל תוך סעודתו ע\"ש ועיין בא\"ר שדעתו כהמג\"א גם הביא ממהרי\"ל שמהר\"ן ושאר לומדים התפללו מעריב אחר הסעודה בחצות לילה וזה דלא כשל\"ה ואם רוצה למצוא תקנה שיתפללו בבה\"כ ולא יתבטל התמיד נ\"ל שילכו בלילה או סמוך ללילה יברכו בהמ\"ז ואח\"כ ילכו להתפלל ויוכלו לאכול ולשתות ולשמוח עוד דהא מצוה בשמחה בשני ימים וגם כל יחיד שמירתת שישכח להתפלל יעשה כן ע\"ש ובסידור עמודי שמים להגאון יעב\"ץ כ' שאף אם יתפלל בתוך הסעודה אומר עה\"נ והכי עבידנא עובדא ע\"ש:","\u0003בשר עבה\"ט \u0004 ועיין באשל אברהם ריש סימן תרצ\"ד בשלוח מנות ונאנסו כו' ואין לו שייכות לשם במתנות לאביונים כ\"א לכאן ומ\"ש שם דלא כספר בני חייא ע\"ש שבעהמ\"ח ב\"ח גופיה משמע דעתו שלא יצא שכת' בנגנבו או בנותן מתנה ע\"מ להחזיר אף על גב דבעלמא מהני יש לחלק דהכא עיקר התקנה משום שמחה וכיון שנגנבו או חוזר ונוטלו ליכא שמחה ע\"ש:","\u0003ואשה עבה\"ט \u0004 ועיין בפר\"ח שכת' דאיש כתיב ולא אשה ובשבו\"י ח\"א סימן מ\"ה כת' שהטעם ברור כיון שגם הם היו באותו הנס וגם כתיב קבלו היהודים והנשים בכלל ומ\"ש איש ע' בקידושין דאיש סיפק בידו לעשות ובב\"ק דף ך\"ט מיבעיא ליה בגזול גיורת אף על גב דכתיב איש דילמא אורחי' דקרא הוא כו' ולכך י\"ל דבמתנות לאביונים לא כתיב איש משום דמקבלין צדקה מן הנשים וע\"ש מ\"ש הרמ\"א במתנות לאביונים אין לחוש מלבד מ\"ש בד\"מ בשם מהר\"י ברי\"ן י\"ל כפשוטו דמשלוח מנות אשה לאיש או איש לאשה מראה הרגל דבר וחיבה משא\"כ במתנות לאביונים שהוא דרך צדקה כו' ועיין שם בשאילת יעב\"ץ ח\"א סימן ק\"ח השיג ג\"כ על הפר\"ח מהני טעמי שכת' השבו\"י וכת' גם כן כמו דחייבים במקרא מגילה איתקיש עשיה לזכירה גם כן וגם שטעם שאף הם היו בנס שייך לכל מצות הנוהגים בפורים ומכל מקום אי מעל זרעם לחוד דאשה נמי זרע מיקרי היה מקום לומר דפטורי כמו מצוה דאורייתא שהז\"ג כו' ועיין לעיל סימן תרפ\"ז ס\"ק ה' בשם שאילת יעב\"ץ ח\"ב ועיין בבר\"י כאן בשם מהר\"י מולכו שמסתפק באחד שאמר קחי זה המטבע למעות פורים והתקדשי לי בו וכו' עיין שם ולענ\"ד פשוט להחמיר בזה על כל פנים ספק קידושין ומה שכת' רמ\"א אבל במתנות לאביונים אין לחוש היינו בסתמא שרינן שישלח לה בתורת צדקה ואין לחוש שיבא לידי ספק קידושין כמו דחיישינן במנות ועמש\"ל בשם השבו\"י בזה:"],"m":["\u0003ובסעודה א'\u0004. לאפוקי ממ\"ד דחייב לאכול גם בלילה דומיא דמגילה וב\"ח כ' דמ\"מ יש לאכול בלילה אפי' כשחל במ\"ש כמש\"ל בהג\"ה:","\u0003בלילה\u0004. אפי' בליל י\"ד:","\u0003אלא שישתה יותר וכו'\u0004. וי\"א שלא ידע לחשוב שארור המן בגי' ברוך מרדכי:","\u0003תענית חלום\u0004. נ\"ל כוונתו דיתענה עד אחר מנחה ואח\"כ יאכל ועמ\"ש סי' תר\"ד וסי' תקנ\"ב סי\"א, ובס' תניא כתוב הנשבע להתענות בפורי' יעמוד בשבועתו ויסעוד בלילה אף על פי שמצוה מן המובחר ביום יעשה מה שיוכל ועיין ריש סי' תקנ\"ג דלא קי\"ל כן:","\u0003ורוב הסעודה וכו'\u0004. הא דלא נהיגי לעשותה בשחרית היינו משום שטרודים במשלוח מנות כדאשכחן ספ\"ה דחולין שלא היו מרבים בסעוד' י\"ט הראשון של סוכות מפני שהיו טרודים בסוכה ולולב (ת\"ה):","\u0003זרעוני' בליל' הראשונ'\u0004. ויש שאין אוכלין בשר בליל' כדי שלא יטעו לו' שהו' סעודת פורים (כל בו):","\u0003דאם הזיק\u0004. ובכ\"ה כ' דוקא שהזיק ממונו אבל גופו חייב עכ\"ל אבל באגודה סוכה כתב כשמשחקים הבחורים בשבת ומכין זה את זה פטורים ובלבד שלא יתכוונו עכ\"ל:","\u0003מכח שמחת פורים\u0004. פי' שעשה מכח שמחה אבל אם כוון להזיק חייב עבח\"מ שם:","\u0003אומר על הנסים\u0004. ואם שכח על הנסים בב\"ה מחזירין אותו דלא סגי דלא אכיל (של\"ה רש\"ל בשם ר\"י פולק מט\"מ) ומ\"מ דבריו צ\"ע דאטו מי עדיף מתפלה דחובה היא ואפ\"ה אין מחזירין אותו וכ\"ש בב\"ה ולכן נ\"ל דאם כבר אכל סעודה א' ביום שוב אין מחזירין אותו, דהא אי בעי לא אכל יותר וכמ\"ש ב\"י סי' קפ\"ח בשם התוספו' ע\"ש ואף על פי שרש\"ל לא כ' כן נ\"ל מ\"ש עיקר אליבא דהלכתא כי מדינא נ\"ל דלעולם אין מחזירין אותו כי לא מצינו שחייב לאכול פת בפורי' ומצי למיפטר נפשיה בשא' מיני מטעמי', ולכן בנדון זה שאכל כבר פשיטא דאין להחזירו ולחוש לספק ברכה לבטל': ומ\"כ במרדכי כתו' בקלף היה אוכל סעודת פורים בע\"ש יתפלל ויפרוס מפה ויקדש ובמזון יאמר על הניסים עכ\"ל ובמט\"מ ובמנהגי' כתבו הואיל ולא התפלל ערבית משמע דאם התפלל שוב אינו אומר על הניסים וכ\"כ של\"ה ומהרי\"ל בתשו' סי' נ\"ו לכן נ\"ל דיברך ברכת המזון תחל' ואח\"כ יתפלל ערבית להוציא עצמו מפלוגתא וגם שלא ישתכר ולא יברך ב\"ה:","\u0003ונוהגין כו'\u0004. ונ\"ל דבזה אם לא אמרו אין מחזירין אותו:","\u0003שתי מנות בשר\u0004. מבושלים הראוי לאכילה (מהרי\"ל) וה\"ה משקה (של\"ה):","\u0003ב' מנות כו'\u0004. ונ\"ל דבעניים הקפידו ליתן לשני עניים דמצו' לחלק משא\"כ בעשיר דדי כשנותן לא': ונ\"ל דמי שאוכל על שלחן חבירו ולא הכין לו כלום פטור מלשלוח מנות וכ\"מ קצת ברש\"י גבי מחלפי סעודתייהו להדדי ומ\"מ צ\"ע (עמ\"ש סי' תרפ\"א סס\"ו) וטוב להחמיר:","\u0003לשלוח מנות ביום\u0004. וה\"ה מתנות לאביונים (שם):","\u0003ואשה חייבת\u0004. לא ראיתי נזהרין בזה ואפשר דדוקא באלמנה אבל אשה שיש לה בעל בעל' משלח בשבילה לכמה בני אדם ומ\"מ יש להחמיר:","\u0003ספק קידושין\u0004. פי' שיאמרו שזהו סבלונות וחוששין לקידושין אבל מתנות לאביונים הוי מעות וליכא למיחש לסבלונות וגם ליכא למיחש שקדש' במעות הללו שהרי צריך שיאמר בפני ב' עדים הרי את מקודשת:"],"r":["\u0003ס\"א מצוה. \u0004שם ז' ב' כי נפיקנא כו':","\u0003ובסעודה כו'. \u0004שם ולא הוה אפשר כו':","\u0003ס\"ב חייב כו'. \u0004שם מיחייב אינש כו' ור\"ל בין נקמת המן לגדולת מרדכי והוא מ\"ש גדולה נקמה שניתנה כו' ואמרו גדול' דעה וכיון שניטלה הדעה לא ידע כו':","\u0003וי\"א דא\"צ. \u0004ע' בפ' בתרא דפסחים ובפ' בתרא דיומא יתהלך במישרים כו'. כל בו וע' בהג\"מ פ\"ב:","\u0003ואין להתענות. \u0004מגילה ה' ב':","\u0003ונוהגים לעשות כו'. \u0004עמ\"א ס\"ק ה' בשם ת\"ה ונמשכין ברוב עד המנחה ואסורין להתחיל קודם מנחה:","\u0003וכשחל. \u0004ע' סי' רמ\"ט ס\"ב מצוה להמנע כו' וכ\"ש בכה\"ג:","\u0003וחייב במשתה כו'. \u0004שנאמר את שני הימים כו'. ד\"מ בשם מנהגים. אבל בגמרא ה' ב' מ' דמשתה ושמחה לא קאי אלא אכל א' ביומו וע' רש\"י שם ד\"ה לא נצרכה כו':","\u0003וי\"א דאם. \u0004תוספ' סוכ' מ\"ה א' ד\"ה מיד התינוקות כו' ויש ללמד כו':","\u0003ס\"ג ואם התחיל כו'. \u0004כמו בתפלת נעילה אע\"ג דלרב ביומא פ\"ז ב' ולת\"ק פ\"ח א' דמתפלל בלילה וע' רא\"ש שם בשם ירושלמי מ\"מ מתפלל של שבת כמ\"ש בפ\"ב דשבת יה\"כ שחל בשבת כו' ואע\"ג דרב לא ס\"ל דריב\"ל לא מחמת לילה:","\u0003דבתר תחלת כו'. \u0004העיקר דכל שנמשכה קוושת שבת או שחלה מזכירים של שבת ולכן מתפלל בליל שבת שתים של שבת וכן מזכיר בבה\"מ של שבת כמ\"ש בתוספתא וכן בנעילה מזכיר של שבת הואיל ועדיין לא התפלל מעריב ועדיין קדושת שבת משא\"כ מתפלל במ\"ש שתים שכבר התפלל בראשונה של חול ולפ\"ז אין חילוק בין התחיל דאפילו לא התחיל כנ\"ל. ולפי הירושלמי דגומר בלילה י\"ל דאזלינן בתר התחלה אבל לגמרא דידן בסוף יומא דאף להתחיל בלילה ש\"ד מדאמר אין טובלין וכנ\"ל:","\u0003ויש מי. \u0004כמ\"ש בפ\"ד דברכות טעה ולא התפלל מנחה בע\"ש כו' בשבת מתפלל במ\"ש שתים של חול ובפרק ע\"פ גמרו כוס ראשון מברך עליו בה\"מ ואמרו בתוספתא דברכות שמזכיר של שבת בבה\"מ אע\"ג דסעודת חול היא אלמא בתר השתא אזלינן וס' ראשונה ס\"ל דל\"ד לתפלה דאינה אלא לתשלומין זמן מנחה עבר ומבדיל בראשונה אבל בה\"מ מברך על מה שאכל מבע\"י וכיון דאכתי לא צלי של חול אומר מעין המאורע. מהרי\"ל סי' נ\"ו ור\"ל בזה לתרץ קושיא שניה של הרא\"ש שמקשה מתוספתא הנ\"ל דשאני התם שכבר חל שבת משא\"כ כאן כ\"ז שלא התפלל עדיין קדושת שבת עליו:","\u0003ונוהגין. \u0004וכ\"פ ש\"ע בסי' קפ\"ח ס\"י:","\u0003ס\"ד מנות בשר. \u0004כמ\"ש בספ\"ק די\"ט בש\"א אין משלחין כו' וע' רש\"י שם:","\u0003ויש לשלוח. \u0004כמ\"ש ימי משתה ושמחה ומשלוח כו' וקאי אכולהו ואמרו שם ימי כתיב:","\u0003ואשה כו'. \u0004כמש\"ש ד' א' וע' פר\"ח:"]}],["פּוּרִים \u0010y0\u0011 מֻתָּר בַּעֲשִׂיַּת מְלָאכָה; וּבְמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לַעֲשׂוֹת, \u0010y1\u0011 אֵין עוֹשִׂין. \u0010c0\u0011 \u0005 הַגָּה: וְהָאִדָּנָא נָהֲגוּ \u0010y2\u0011 בְּכָל מָקוֹם שֶׁלֹּא לַעֲשׂוֹת \u0006 \u0005(כָּל בּוֹ)\u0006; וְהָעוֹשֶׂה, אֵינוֹ רוֹאֶה \u0010y3\u0011 סִימַן בְּרָכָה מֵאוֹתָהּ מְלָאכָה לְעוֹלָם, אֶלָּא אִם הוּא בִּנְיָן שֶׁל שִׂמְחָה, כְּגוֹן: בֵּית חַתְנוּת לִבְנוֹ \u0010y4\u0011 אוֹ אַבּוּרְנְקִי שֶׁל מְלָכִים, דְּשָׁרֵי. \u0005 הַגָּה: וּמֻתָּר לַעֲשׂוֹת כָּל מְלֶאכֶת מִצְוָה, כְּגוֹן: \u0010y5\u0011 \u0006 \u0005 לִכְתֹּב פִּסְקֵי הֲלָכוֹת; וְכֵן מֻתָּר לַעֲשׂוֹת אֲפִלּוּ מְלָאכוֹת גְּמוּרוֹת לְצֹרֶךְ פּוּרִים. \u0006 \u0005(ת\"ה סִימָן קי\"ב)\u0006.\nאֲפִלּוּ בְּמָקוֹם שֶׁנָּהֲגוּ, לֹא נָהֲגוּ אֶלָּא בְּיוֹם מִקְרָא מְגִלָּה בִּלְבַד, אֲבָל לֶאֱסֹר אֶת שֶׁל זֶה בָּזֶה, \u0010y6\u0011 אֵינוֹ מִנְהָג.\nיוֹם י\"ד וְיוֹם ט\"ו אֲסוּרִים \u0010y7\u0011 בְּהֶסְפֵּד \u0010y8\u0011 וְתַעֲנִית לְכָל אָדָם בְּכָל מָקוֹם, בֵּין לִבְנֵי כְּרַכִּים שֶׁהֵם עוֹשִׂין ט\"ו בִּלְבַד, בֵּין לִבְנֵי עֲיָרוֹת שֶׁהֵם עוֹשִׂים י\"ד בִּלְבַד; וְהַנָּשִׁים מְעַנּוֹת בָּהֶם, שֶׁכֻּלָּן עוֹנוֹת כְּאַחַת, וּמְטַפְּחוֹת שֶׁמַּכּוֹת כַּף אֶל כַּף; אֲבָל לֹא מְקוֹנְנוֹת, שֶׁתְּהֵא אַחַת מְדַבֶּרֶת וְכֻלָּן עוֹנוֹת אַחֲרֶיהָ; נִקְבַּר הַמֵּת, לֹא מְעַנּוֹת וְלֹא מְקוֹנְנוֹת.\nכָּל דִּבְרֵי אֲבֵלוּת נוֹהֲגִים בַּחֲנֻכָּה וּפוּרִים. \u0005 הַגָּה: וּמִכָּל מָקוֹם \u0010y9\u0011 יֵלֵךְ לְבֵית הַכְּנֶסֶת \u0010y10\u0011 \u0006 \u0005 לִשְׁמֹעַ הַמְּגִלָּה \u0006 \u0005(תּוֹסָפוֹת פ\"ק דְּמוֹעֵד קָטָן)\u0006. \u0005 וְאִם יוּכַל לֶאֱסֹף מִנְיָן לְבֵיתוֹ לִקְרוֹת הַמְּגִלָּה, עָדִיף טְפֵי \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0010y11\u0011 \u0005 וְיֵשׁ אוֹמְרִים שֶׁאֵין \u0006 \u0005 אֲבֵלוּת נוֹהֵג בְּפוּרִים, לֹא בְּי\"ד וְלֹא בְּט\"ו \u0006 \u0005(הָרֹא\"שׁ וּמִנְהָגִים)\u0006, \u0005 וְכֵן נוֹהֲגִין; וַאֲפִלּוּ אֲבֵלוּת יוֹם רִאשׁוֹן נִדְחֶה מִפְּנֵי פּוּרִים \u0006 \u0005(דִּבְרֵי עַצְמוֹ)\u0006; \u0005 אֲבָל \u0010y12\u0011 דְּבָרִים \u0006 \u0005 שֶׁבְּצִנְעָה, נוֹהֵג; וְאַף עַל פִּי שֶׁאֵין נוֹהֵג אֲבֵלוּת בְּפוּרִים, \u0010y13\u0011 עוֹלֶה לוֹ \u0006 \u0005 לְמִנְיַן שִׁבְעָה יְמֵי אֲבֵלוּת כְּמוֹ שַׁבָּת, וְכֵן פָּסַק הָרַב בְּעַצְמוֹ בְּטוּר יוֹרֶה דֵּעָה סי' ת\"א. \u0006\nאִם חָל פּוּרִים בְּמוֹצָאֵי שַׁבָּת וְהָאָבֵל יוֹשֵׁב בְּבֵית הַכְּנֶסֶת בְּשַׁבָּת בְּמִנְחָה, \u0010y14\u0011 לֹא יֵצֵא מִשָּׁם עַד שֶׁיִּתְפַּלֵּל תְּפִלַּת עַרְבִית וְיִשְׁמַע קְרִיאַת מְגִלָּה, וּלְמָחֳרָת לֹא יֵצֵא \u0010y15\u0011 מִפֶּתַח בֵּיתוֹ.\nיֵשׁ מִי שֶׁאוֹמֵר \u0010y16\u0011 שֶׁהָאָבֵל \u0010y17\u0011 חַיָּב לִשְׁלֹח מָנוֹת. \u0005 הַגָּה: \u0010y18\u0011 אֲבָל אֵין שׁוֹלְחִין לְאָבֵל \u0010y19\u0011 כָּל י\"ב חֹדֶשׁ \u0006 \u0005(מַהֲרִי\"ל)\u0006, \u0010y20\u0011 \u0005 וּכְמוֹ שֶׁיִּתְבָּאֵר בְּיוֹרֵה דֵּעָה סי' שפ\"ה, עַיֵּן שָׁם. וְאִם אֵין בָּעִיר אֶלָּא הָאָבֵל עִם אַחֵר, חַיָּב לִשְׁלֹחַ לָאָבֵל כְּדֵי לְקַיֵּם מִשְׁלֹחַ מָנוֹת, \u0010y21\u0011 אֶלָּא אִם כֵּן מָחַל הָאָבֵל עַל מְנָתוֹ \u0006 \u0005(מהרי\"ב)\u0006.\nיֵשׁ מִי שֶׁאוֹמֵר \u0010y22\u0011 שֶׁאוֹנֵן \u0010y23\u0011 מֻתָּר בְּבָשָׂר וְיַיִן, דְּלֹא אָתֵי עֲשֵׂה דְּיָחִיד דַּאֲבֵלוּת וְדָחֵי עֲשֵׂה דְּרַבִּים דְּאוֹרַיְתָא, דְּלִשְׂמֹחַ בְּפוּרִים דִבְרֵי קַבָּלָה נִינְהוּ שֶׁהֵם כְּדִבְרֵי תּוֹרָה. \u0005 הַגָּה: \u0010y24\u0011 וְכָל שֶׁכֵּן שֶׁחַיָּב בְּמִקְרָא מְגִלָּה וּתְפִלָּה וּקְרִיאַת שְׁמַע; וְנ\"ל דְּדַוְקָא \u0006 \u0005 בַּלַּיְלָה, אַף עַל פִּי שֶׁמֵּתוֹ מֻטָּל לְפָנָיו; אֲבָל בַּיּוֹם, שֶׁרוֹצֶה לְקָבְרוֹ, \u0010y25\u0011 קְבוּרַת מֵתוֹ \u0006 \u0005 קוֹדֵם כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סי' תרפ\"ז ס\"ב, וְלָכֵן קוֹרֵא וּמִתְפַּלֵּל \u0010y26\u0011 אַחַר כָּךְ, דְּלֹא עָדִיף מִיּוֹם טוֹב וְשַׁבָּת, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ע\"א \u0010y27\u0011 כֵּן נִרְאֶה לִי. \u0006\nמֻתָּר לִשָּׂא אִשָּׁה בְּפוּרִים. \u0005 הַגָּה: בֵּין בְּי\"ד בֵּין בְּט\"ו, וְכָל שֶׁכֵּן שֶׁמֻּתָּר לַעֲשׂוֹת \u0010y28\u0011 פִּדְיוֹן הַבֵּן \u0006 \u0005(תוס' פ\"ק דמ\"ק)\u0006. \u0005 וּמַה שֶּׁנָּהֲגוּ לִלְבֹּשׁ פַּרְצוּפִים בְּפוּרִים, וְגֶבֶר לוֹבֵשׁ שִׂמְלַת אִשָּׁה וְאִשָּׁה כְּלִי גֶּבֶר, אֵין אִסּוּר בַּדָּבָר מֵאַחֵר שֶׁאֵין מְכַוְּנִין אֶלָּא לְשִׂמְחָה בְּעָלְמָא; וְכֵן בִּלְבִישַׁת כִּלְאַיִם דְּרַבָּנָן. וְיֵשׁ אוֹמְרִים דְּאָסוּר, אֲבָל הַמִּנְהָג כַּסְּבָרָא \u0010y29\u0011 הָרִאשׁוֹנָה. וְכֵן בְּנֵי אָדָם הַחוֹטְפִים זֶה מִזֶּה דֶּרֶךְ שִׂמְחָה, אֵין בָּזֶה \u0010y30\u0011 מִשּׁוּם \u0006 \u0005 לֹא \u0010y31\u0011 תִגְזֹל \u0006 \u0005(וַיִּקְרָא יט, יג)\u0006 \u0005 וְנָהֲגוּ כָּךְ, וּבִלְבַד שֶׁלֹּא יֵעָשֶׂה דָּבָר שֶׁלֹּא כַּהֹגֶן עַל פִּי טוֹבֵי הָעִיר \u0006 \u0005(תְּשׁוּבַת מַהֲרִ\"י מִינְץ סִימָן ט\"ז)\u0006.",["\u0003מותר בעשיית מלאכה\u0004 דאע\"ג דכתיב משתה ושמחה ויו\"ט מ\"מ לא קיבלו עליהם לעשותו יו\"ט אכן אח\"ז נהגו מעצמן באיזה מקומות שלא לעשות:","\u0003אין עושין\u0004 וע\"י עכו\"ם שרי:","\u0003בכל מקום שלא לעשות\u0004 ופרקמטיא מותר ששמחה היא לו:","\u0003סימן ברכה\u0004 כגון אם זורע איזה דבר אינו מצמיח [ב\"י] אבל הרא\"ם כתב שאינו מרויח אבל אינו מפסיד ג\"כ [מ\"א]:","\u0003או אבורנקי של מלכים\u0004 שנוטעים לצל להסתופף בצלו:","\u0003פסקי הלכות\u0004 ופשטי המקרא ואגרת שלום ומזכרת חובותיו וכן כל דבר שא\"צ עיון גדול. וכתב בסי' עמודי שמים דמ\"מ יש לראות שלא ימשוך בה ויתבטל משמחת פורים. מגילה מותר לכתוב בפורים:","\u0003אינו מנהג\u0004 ויש מחמירין בזה ונראה דתלוי במנהג אותו המקום:","\u0003בהספד\u0004 ומקום שנהגו שביום ז' הולכים על הקבר לקונן אסור בפורים אלא האבל לבדו ילך לשם עם חזן אחד ויאמר לו השכבה ואפילו בערב פורים לא ילך לשם שלא יחשבו העולם שהאבילות נפסק בפורים:","\u0003ותענית\u0004 ולענין ת\"ח עיין לעיל בסימן תרצ\"ה ס\"ב בהג\"ה ובמ\"ב שם. ודין ת\"ח בפניו עיין ביו\"ד סימן ת\"א:","\u0003ילך לבהכ\"נ לשמוע וכו'\u0004 ומה שכתב בסעיף ה' בסופו דלמחרת לא יצא מפתח ביתו מיירי כשיש לו מנין בביתו אף דבעלמא קריאה בצבור עדיף טפי:","\u0003המגילה\u0004 אבל תפלת מעריב יתפלל בביתו:","\u0003וי\"א שאין וכו' וכן נוהגין\u0004 אף שהב\"ח ועוד אחרונים כתבו שבמקומם היה המנהג להתאבל אבל כבר כתב בשע\"ת בשם כמה אחרונים להקל ושכן פשט המנהג במדינות אלו ובפרט בענין חליצת מנעלים וישיבה ע\"ג קרקע בודאי אין להחמיר ומ\"מ יראה למעט במיני שמחה שעושין. כתב בתשובת בנין עולם סי' ל\"ה לענין לקרות האבל המגילה בביהכ\"נ אם אין שם אחר שיודע לקרות כ\"כ בנקודות ובטעמים ובדקדוק האותיות טוב יותר שיקראנה האבל כמ\"ש ביו\"ד לענין להתפלל בשבתות ויו\"ט:","\u0003דברים שבצנעה נוהג\u0004 הנה ט\"ז כתב דהליכה מביתו לתפלה אסור גם לדעה זו ולא מקרי זה בפרהסיא דלא מינכר שעושה כן משום אבילות ובמ\"א כתב דמשמע בטור דבשחרית הולך לבהכ\"נ להתפלל ועיין בפמ\"ג שכתב דהמיקל להתנהג כן לא הפסיד וכ\"כ בדה\"ח דשחרית הולך לתפלה בבהכ\"נ:","\u0003עולה לו למנין שבעה\u0004 אפילו מת בפורים:","\u0003לא יצא משם וכו'\u0004 דין זה כתבו הרוקח ובמקומו היו אוכלין סעודה שלישית קודם מנחה לכן קאמר דבבואו להתפלל מנחה לא יצא משם אבל לדידן צריך לילך לביתו אחר מנחה לאכול סעודה שלישית ובלילה יתפלל מעריב ויקרא המגילה בביתו אם יש לו מנין וא\"ל ילך לבהכנ\"ס בעוד יום ויהיה שם לתפלה וקריאת המגילה:","\u0003מפתח ביתו\u0004 ורק לשמוע מקרא מגילה אם אין לו מנין בביתו וכנ\"ל. והנה המחבר שהעתיק דברי הרוקח אזיל לשיטתו בס\"ד דאבילות נוהג בפורים אבל כבר כתב הרמ\"א לעיל דאנן נוהגין כהפוסקים דאין אבילות נוהג בפורים. ולפ\"ז אפילו אם יש לו מנין בביתו הולך לבהכ\"נ לשמוע מקרא מגילה בצבור [ולצאת מפתח ביתו לעניני רשות משמע מפמ\"ג שיש להחמיר] וכ\"ז ביום דימי משתה ושמחה כתיב אבל בלילה אם יש לו מנין יתפלל ויקרא המגילה בביתו ואם אין לו מנין יתפלל בביתו וילך לשמוע מקרא מגילה בבהכ\"נ ולבד הקריאה לא יצא מפתח ביתו. ועיין בדה\"ח דביום ט\"ו לא ילך מביתו לביהכ\"נ אפי' להתפלל שחרית ומ\"מ לענין חליצת מנעלים וישיבה ע\"ג קרקע משמע מן הפוסקים דאפילו ביום ט\"ו א\"צ. כתב הלבוש א\"א צידוק הדין ולא קדיש אלא לחכם בפניו אחר שדורשין עליו ואע\"פ שא\"א צ\"ה אומרים קדיש:","\u0003שהאבל וכו'\u0004 אפילו תוך שבעה דהא חייב בכל מצות האמורות בתורה וכ\"ש דחייב במתנות לאביונים:","\u0003חייב לשלוח מנות\u0004 אכן כל דבר שמחה לא ישלח וז\"ל ס\"ח מי שמת אביו בפורים לשנה הבאה ישלח מנות (אף דהוא יא\"צ) ובאותו שנה ישלח מעות או בשר לעניים רק לא תפנוקים העשויים לשמחה:","\u0003אבל אין שולחין לאבל\u0004 אפילו דבר שאינו של שמחה. ואם האבל הוא עני מותר לשלוח לו מעות אפילו תוך ז' דלא גרע מצדקה:","\u0003כל י\"ב חודש\u0004 היינו לאביו ואמו [ולשאר קרובים תוך ל'] והטעם כדין שאילת שלום שאסור י\"ב חודש:","\u0003וכמו שיתבאר ביו\"ד סימן שפ\"ה\u0004 כונתו להורות דבמקום שנהגו להקל לשאול בשלומם מותר לשלוח להם מנות ג\"כ בתוך י\"ב חודש [אבל לא בתוך שלשים] אבל לא ישלחו לו מיני שמחה:","\u0003אא\"כ מחל האבל וכו'\u0004 דאין נותנין לאדם מתנה על כרחו:","\u0003שאונן וכו'\u0004 אונן נקרא כ\"ז שלא נקבר המת:","\u0003מותר בבשר ויין\u0004 אף דדעת המחבר לעיל דאבלות נוהג בפורים מ\"מ אנינות ס\"ל דאינו נוהג וכמו שכתב הטעם ועיין במ\"א שהעלה דדוקא ביום שחל מצות שמחת פורים דימי משתה ושמחה כתיב אבל לא בלילה אפילו בלילה ראשונה. וכ\"ש בלילה שניה ומש\"כ אח\"כ ונ\"ל דוקא בלילה לא קאי רק לענין מגילה ותפלה וק\"ש:","\u0003וכ\"ש שחייב במקרא וכו'\u0004 ר\"ל דכשם שבשביל מצות שמחת היום דחינן את העשה דאבילות והתרנוהו בבשר ויין בודאי אין ראוי לפטרו בלילה ממקרא מגילה ושאר מצות כיון שאין דרך לקברו אז ודומה לאונן בליל יו\"ט שני דהרבה פוסקים חייבוהו במצות מטעם זה אבל יש לפקפק ע\"ז אחד דליל יו\"ט שני גופא יש דיעות בפוסקים ועוד דשם עכ\"פ יו\"ט הוא ולכך אין חל האנינות מחמת שאין דרך לקברו בלילה משא\"כ בפורים דעיקר שמחה ביום הוא ובלילה דומה לשאר לילה של חול דבודאי חל אנינות אף שאין דרך לקברו אז ולכן כתב בדה\"ח דבליל י\"ד ישמע קריאת המגילה מאחר:","\u0003קבורת מתו קודם כמו שנתבאר וכו'\u0004 ר\"ל דשם מוכח דלאו דוקא מת מצוה קודם לקריאת המגילה דה\"ה כל מת שאין לו קוברין כדי צרכו הפוגע בו קוברו תחלה ואח\"כ קורא. והנה באמת כבר כתב שם המ\"א דהרבה פוסקים חולקין ע\"ז וס\"ל דבכל מת קריאת המגילה קודם לקבורתו וכן נוהגין לקברו אחר יציאת בהכ\"נ והקשה המ\"א דהא תינח באנשים אחרים אבל האונן איך הוא חייב בקריאת המגילה הלא הוא פטור מכל המצות ואיך יצא במה ששמע בצבור אחרי שאז לא היה חייב כלל וע\"כ מסיק המ\"א דאע\"פ ששמע הקריאה בצבור יקראנה שנית אחר שנקבר המת. ולענין ק\"ש ותפלה הוא כשאר אונן בימות החול דקודם הקבורה הוא פטור ולאחר הקבורה עיין לעיל בסימן ע\"א במ\"ב סק\"ד שם מבואר כל הפרטים. ולענין תפילין דעת כמה אחרונים דלא יניח וכדלעיל בסימן ל\"ח ס\"ה:","\u0003אחר כך\u0004 ר\"ל אבל קודם הקבורה הוא פטור מזה ולזה מסיים דלא עדיף משבת ויו\"ט והיינו ביו\"ט שני כשקוברו וכן בשבת כשמחשיך על התחום לצרכי הקבורה הוא פטור אז מכל המצות וכ\"ש כאן:","\u0003מותר לישא וכו'\u0004 ולא דמי לחג דכתיב ושמחת בחגיך ולא באשתך משא\"כ בפורים והמ\"א כתב דיעשה החופה ביום י\"ג והסעודה בערב ועיין בשע\"ת שכתב שבמדינות אלו פשט המנהג להיתר כדעת הש\"ע ובחמד משה כתב שנכון יותר לעשות החופה בסוף יום י\"ד וסעודת פורים יעשה מקודם:","\u0003פדיון הבן\u0004 וברית מילה דבזה אין שמחה כ\"כ דיהיה שייך בהו לומר אין מערבין שמחה בשמחה:","\u0003הראשונה\u0004 עיין ביו\"ד סימן קפ\"ב שכתב שם הט\"ז בשם הב\"ח שיש לבטל מנהג זה הן בפורים או בשמחת נישואין וכ\"כ באה\"ג שם ואם כל המלבושים של איש רק מלבוש א' של אשה וניכרים הם אפשר שאין למחות בהם [פמ\"ג] ועיין בכנה\"ג ובשל\"ה שהזהירו להרחיק מזה:","\u0003משום לא תגזול\u0004 ולפ\"ז מותר לברך על מה שחוטפין מיהו כתב בשל\"ה לאו משנת חסידים היא ושומר נפשו ירחק ממלבושים דכלאים ולחטוף מחבירו [א\"ר]:","\u0003ונהגו כך\u0004 היינו מעת קריאת המגילה עד ליל סעודת פורים שהם שני לילות ויום אחד [א\"ר]:"],["\u0003 אין עושין\u0004 - עיין בפמ\"ג דדוקא ביום אבל בלילה עד הנץ שרי לעשות אף במקום שנהגו שלא לעשות ובת' ח\"ס סי' קצ\"ה מחמיר בזה:"],"\u0010g0\u0011 פּוּרִים \u0010y0\u0011 מֻתָּר בַּעֲשִׂיַּת מְלָאכָה; \u0010g1\u0011 וּבְמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לַעֲשׂוֹת, \u0010y1\u0011 \u0010t0\u0011 \u0010s0\u0011 אֵין עוֹשִׂין. \u0010c0\u0011 \u0005 הַגָּה: וְהָאִדָּנָא נָהֲגוּ \u0010y2\u0011 \u0010m0\u0011 בְּכָל מָקוֹם שֶׁלֹּא לַעֲשׂוֹת \u0006 \u0005(כָּל בּוֹ)\u0006; \u0010g2\u0011 וְהָעוֹשֶׂה, \u0010m1\u0011 אֵינוֹ רוֹאֶה \u0010y3\u0011 \u0010m2\u0011 סִימַן בְּרָכָה מֵאוֹתָהּ מְלָאכָה לְעוֹלָם, \u0010g3\u0011 אֶלָּא אִם הוּא בִּנְיָן שֶׁל שִׂמְחָה, כְּגוֹן: בֵּית חַתְנוּת לִבְנוֹ \u0010y4\u0011 אוֹ אַבּוּרְנְקִי שֶׁל מְלָכִים, דְּשָׁרֵי. \u0005 הַגָּה: וּמֻתָּר לַעֲשׂוֹת כָּל מְלֶאכֶת מִצְוָה, כְּגוֹן: \u0010y5\u0011 \u0010t1\u0011 \u0010m3\u0011 \u0006 \u0005 לִכְתֹּב פִּסְקֵי הֲלָכוֹת; וְכֵן מֻתָּר לַעֲשׂוֹת אֲפִלּוּ מְלָאכוֹת גְּמוּרוֹת לְצֹרֶךְ פּוּרִים. \u0006 \u0005(ת\"ה סִימָן קי\"ב)\u0006. \u0010g4\u0011 \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011\nאֲפִלּוּ בְּמָקוֹם שֶׁנָּהֲגוּ, לֹא נָהֲגוּ אֶלָּא בְּיוֹם מִקְרָא מְגִלָּה בִּלְבַד, אֲבָל לֶאֱסֹר אֶת שֶׁל זֶה בָּזֶה, \u0010y6\u0011 \u0010t2\u0011 אֵינוֹ מִנְהָג. \u0010g5\u0011\nיוֹם י\"ד וְיוֹם ט\"ו \u0010m4\u0011 אֲסוּרִים \u0010y7\u0011 \u0010t3\u0011 \u0010s1\u0011 בְּהֶסְפֵּד \u0010y8\u0011 וְתַעֲנִית לְכָל אָדָם בְּכָל מָקוֹם, \u0010g6\u0011 בֵּין לִבְנֵי כְּרַכִּים שֶׁהֵם עוֹשִׂין ט\"ו בִּלְבַד, בֵּין לִבְנֵי עֲיָרוֹת שֶׁהֵם עוֹשִׂים י\"ד בִּלְבַד; \u0010g7\u0011 וְהַנָּשִׁים מְעַנּוֹת בָּהֶם, שֶׁכֻּלָּן עוֹנוֹת כְּאַחַת, וּמְטַפְּחוֹת שֶׁמַּכּוֹת כַּף אֶל כַּף; אֲבָל לֹא מְקוֹנְנוֹת, שֶׁתְּהֵא אַחַת מְדַבֶּרֶת וְכֻלָּן עוֹנוֹת אַחֲרֶיהָ; נִקְבַּר הַמֵּת, לֹא מְעַנּוֹת וְלֹא מְקוֹנְנוֹת. \u0010g8\u0011 \u0010g9\u0011\nכָּל דִּבְרֵי אֲבֵלוּת נוֹהֲגִים בַּחֲנֻכָּה וּפוּרִים. \u0005 הַגָּה: \u0010m5\u0011 וּמִכָּל מָקוֹם \u0010y9\u0011 יֵלֵךְ לְבֵית הַכְּנֶסֶת \u0010y10\u0011 \u0010t4\u0011 \u0006 \u0005 לִשְׁמֹעַ הַמְּגִלָּה \u0006 \u0005(תּוֹסָפוֹת פ\"ק דְּמוֹעֵד קָטָן)\u0006. \u0005 וְאִם יוּכַל לֶאֱסֹף מִנְיָן לְבֵיתוֹ לִקְרוֹת הַמְּגִלָּה, עָדִיף טְפֵי \u0006 \u0005(מַהֲרִי\"ל)\u0006. \u0010y11\u0011 \u0010m6\u0011 \u0005 וְיֵשׁ אוֹמְרִים שֶׁאֵין \u0010t5\u0011 \u0010s2\u0011 \u0006 \u0005 אֲבֵלוּת נוֹהֵג בְּפוּרִים, לֹא בְּי\"ד וְלֹא בְּט\"ו \u0006 \u0005(הָרֹא\"שׁ וּמִנְהָגִים)\u0006, \u0005 וְכֵן נוֹהֲגִין; וַאֲפִלּוּ אֲבֵלוּת יוֹם רִאשׁוֹן נִדְחֶה מִפְּנֵי פּוּרִים \u0006 \u0005(דִּבְרֵי עַצְמוֹ)\u0006; \u0005 אֲבָל \u0010y12\u0011 \u0010m7\u0011 דְּבָרִים \u0010t6\u0011 \u0010s3\u0011 \u0006 \u0005 שֶׁבְּצִנְעָה, נוֹהֵג; וְאַף עַל פִּי שֶׁאֵין נוֹהֵג אֲבֵלוּת בְּפוּרִים, \u0010y13\u0011 \u0010m8\u0011 עוֹלֶה לוֹ \u0010t7\u0011 \u0006 \u0005 לְמִנְיַן שִׁבְעָה יְמֵי אֲבֵלוּת כְּמוֹ שַׁבָּת, וְכֵן פָּסַק הָרַב בְּעַצְמוֹ בְּטוּר יוֹרֶה דֵּעָה סי' ת\"א. \u0010g10\u0011 \u0006 \u0010r4\u0011 \u0010r5\u0011 \u0010r6\u0011 \u0010r7\u0011 \u0010r8\u0011 \u0010r9\u0011 \u0010r10\u0011\nאִם חָל פּוּרִים בְּמוֹצָאֵי שַׁבָּת וְהָאָבֵל יוֹשֵׁב בְּבֵית הַכְּנֶסֶת בְּשַׁבָּת בְּמִנְחָה, \u0010y14\u0011 \u0010m9\u0011 לֹא יֵצֵא מִשָּׁם עַד שֶׁיִּתְפַּלֵּל תְּפִלַּת עַרְבִית וְיִשְׁמַע קְרִיאַת מְגִלָּה, וּלְמָחֳרָת לֹא יֵצֵא \u0010y15\u0011 מִפֶּתַח בֵּיתוֹ. \u0010g11\u0011 \u0010r11\u0011\nיֵשׁ מִי שֶׁאוֹמֵר \u0010y16\u0011 \u0010m10\u0011 שֶׁהָאָבֵל \u0010y17\u0011 \u0010t8\u0011 חַיָּב לִשְׁלֹח מָנוֹת. \u0005 הַגָּה: \u0010y18\u0011 אֲבָל אֵין שׁוֹלְחִין לְאָבֵל \u0010y19\u0011 כָּל י\"ב חֹדֶשׁ \u0006 \u0005(מַהֲרִי\"ל)\u0006, \u0010y20\u0011 \u0005 וּכְמוֹ שֶׁיִּתְבָּאֵר \u0010m11\u0011 בְּיוֹרֵה דֵּעָה סי' שפ\"ה, עַיֵּן שָׁם. וְאִם אֵין בָּעִיר אֶלָּא הָאָבֵל עִם אַחֵר, חַיָּב לִשְׁלֹחַ לָאָבֵל כְּדֵי לְקַיֵּם מִשְׁלֹחַ מָנוֹת, \u0010y21\u0011 אֶלָּא אִם כֵּן מָחַל הָאָבֵל עַל מְנָתוֹ \u0010g12\u0011 \u0006 \u0005(מהרי\"ב)\u0006. \u0010r12\u0011 \u0010r13\u0011 \u0010r14\u0011\nיֵשׁ מִי שֶׁאוֹמֵר \u0010y22\u0011 שֶׁאוֹנֵן \u0010y23\u0011 מֻתָּר בְּבָשָׂר וְיַיִן, דְּלֹא אָתֵי \u0010m12\u0011 עֲשֵׂה דְּיָחִיד דַּאֲבֵלוּת וְדָחֵי עֲשֵׂה דְּרַבִּים דְּאוֹרַיְתָא, דְּלִשְׂמֹחַ בְּפוּרִים דִבְרֵי קַבָּלָה נִינְהוּ שֶׁהֵם כְּדִבְרֵי תּוֹרָה. \u0005 הַגָּה: \u0010y24\u0011 \u0010m13\u0011 וְכָל שֶׁכֵּן שֶׁחַיָּב בְּמִקְרָא מְגִלָּה וּתְפִלָּה וּקְרִיאַת שְׁמַע; וְנ\"ל \u0010m14\u0011 דְּדַוְקָא \u0010t9\u0011 \u0010s4\u0011 \u0006 \u0005 בַּלַּיְלָה, אַף עַל פִּי שֶׁמֵּתוֹ מֻטָּל לְפָנָיו; אֲבָל בַּיּוֹם, שֶׁרוֹצֶה לְקָבְרוֹ, \u0010y25\u0011 \u0010m15\u0011 קְבוּרַת מֵתוֹ \u0010t10\u0011 \u0006 \u0005 קוֹדֵם כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סי' תרפ\"ז ס\"ב, וְלָכֵן קוֹרֵא וּמִתְפַּלֵּל \u0010y26\u0011 אַחַר כָּךְ, \u0010m16\u0011 דְּלֹא עָדִיף מִיּוֹם טוֹב וְשַׁבָּת, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ע\"א \u0010y27\u0011 \u0010g13\u0011 \u0010t11\u0011 \u0010s5\u0011 \u0010m17\u0011 כֵּן נִרְאֶה לִי. \u0006 \u0010r15\u0011 \u0010r16\u0011\nמֻתָּר לִשָּׂא אִשָּׁה בְּפוּרִים. \u0005 הַגָּה: בֵּין בְּי\"ד בֵּין בְּט\"ו, וְכָל שֶׁכֵּן שֶׁמֻּתָּר לַעֲשׂוֹת \u0010y28\u0011 פִּדְיוֹן הַבֵּן \u0006 \u0005(תוס' פ\"ק דמ\"ק)\u0006. \u0005 וּמַה שֶּׁנָּהֲגוּ לִלְבֹּשׁ פַּרְצוּפִים בְּפוּרִים, וְגֶבֶר לוֹבֵשׁ שִׂמְלַת אִשָּׁה וְאִשָּׁה כְּלִי גֶּבֶר, אֵין אִסּוּר בַּדָּבָר מֵאַחֵר שֶׁאֵין מְכַוְּנִין אֶלָּא לְשִׂמְחָה בְּעָלְמָא; וְכֵן בִּלְבִישַׁת כִּלְאַיִם דְּרַבָּנָן. וְיֵשׁ אוֹמְרִים דְּאָסוּר, אֲבָל הַמִּנְהָג כַּסְּבָרָא \u0010y29\u0011 הָרִאשׁוֹנָה. וְכֵן בְּנֵי אָדָם הַחוֹטְפִים זֶה מִזֶּה דֶּרֶךְ שִׂמְחָה, אֵין בָּזֶה \u0010y30\u0011 מִשּׁוּם \u0010t12\u0011 \u0006 \u0005 לֹא \u0010y31\u0011 תִגְזֹל \u0006 \u0005(וַיִּקְרָא יט, יג)\u0006 \u0005 וְנָהֲגוּ כָּךְ, וּבִלְבַד שֶׁלֹּא יֵעָשֶׂה דָּבָר שֶׁלֹּא כַּהֹגֶן עַל פִּי טוֹבֵי הָעִיר \u0006 \u0005(תְּשׁוּבַת מַהֲרִ\"י מִינְץ סִימָן ט\"ז)\u0006. \u0010r17\u0011 \u0010r18\u0011 \u0010r19\u0011 \u0010r20\u0011",{"g":["כרבה בריה דרבא מגילה ה' דמלאכה לא קבילו עלייהו","כשינוי קמא שם בגמרא אהא דלטייה רב","רמב\"ם בפרק ב' מהלכות מגילה מהא דלטייה רב שם","\u0003כשינוי בתרא שם בגמ' אעובדא דרבי דנטע נטיעה בפורים:\u0004 ","שבולי הלקט","מהא דתני רב יוסף שמחה מלמד שאסורים בהספד שם בגמ'","מימרא דרבא מהא דמגילת תענית שם","משנה סוף מ\"ק","ודין ת\"ח בפניו שמענות ומקוננות כדרכן בחול בי\"ד סי' ת\"א ע\"ש","רשב\"ם בפ' י\"א מה' אבל","רוקח","טור בשם הר\"ם מרוטנבורג וכ\"כ ש\"פ בשמו","\u0003אורחות חיים:\u0004 ","\u0003תשו' רשב\"א וסיים דבענינים אלו הולכים בהם להקל דמדרבנן הם:\u0004 "],"t":["\u0003אין עושין. \u0004 וע\"י עכו\"ם שרי ערסי' תס\"ח מ\"א. וכתב הט\"ז נראה דפרקמטי' מותר כיון ששמח' היא לו ע\"ש:","\u0003לכתוב. \u0004 ופשטי המקרא ואגרת שלום ומזכרת חובותיו וכן כל דבר שא\"צ עיון גדול. מט\"מ ב\"י א\"ח:","\u0003אינו\u0004 \u0003מנהג. \u0004 ובמהרי\"ל ואבודרהם משמע דיש לנהוג כן:","\u0003בהספד. \u0004 ומקום שנהגו שביום ז' הולכין על הקבר לקונן אסור בפורים אלא האבל לבדו ילך שם עם חזן א' ויאמר לו השכבה. ואפי' בערב פורים אסור לילך שם שלא יחשבו העולם שהאבילות נפסק מחמת פורים. ר\"ש הלוי סי' י\"ג כנה\"ג:","\u0003לשמוע. \u0004 צ\"ע דהא הרב\"י פסק בס\"ה שלא יצא מפתח ביתו ואם כן ה\"ל לכתוב בלשון י\"א וכו'. מ\"א:","\u0003אבילות. \u0004 ב\"ח ורש\"ל ופרישה העידו שהמנהג להתאבל וכ\"כ מהרי\"ל ועכשיו גרירי עלמא בתר דברי רמ\"א ונ\"ל דיזהר בכולם חוץ מנעילת הסנדל וישיבה ע\"ג קרקע מפני הבריות ומכ\"ש שאסור לראות כל מיני שמחה. מ\"א:","\u0003שבצנעה. \u0004 ויתפלל בביתו ואחר כך ילך לבה\"כ לשמוע מגילה טור וכ\"מ בלבוש מיהו משמע בטור דבשחרית הולך לבה\"כ לתפילה עבי\"ד סי' שצ\"ג מ\"א וכתב הט\"ז ונ\"ל כיון דאין אבילות בפורים בפרהסי' אין לקרות בבית הכנסת בע\"ש קודם ברכו לילך נגד האבל דאין להזכיר שם אבל בפרהסי' אלא ילך לבה\"כ בלא קריאה עכ\"ל:","\u0003למנין. \u0004 אפי' מת בפורים. מ\"א:","\u0003מנות. \u0004 אפי' תוך שבעה מיהו לא ישלח מיני תפנוקים שהם עשוים לשמחה ס\"ח תשי\"ג. ומט\"מ כתב שאין שולחין לאבל אפי' דבר שאינו לשמחה וכ\"מ מדברי רמ\"א ובשכנה\"ג כתב דאבל פטור משלוח מנות תוך שבעה ואחר שבעה ישלח בצינעה לא' מקרוביו או לאחד מהעניים ופשוט הוא דאם האבל הוא עני דמותר לשלוח לו מעות דלא גרע מצדקה. מ\"א ע\"ש:","\u0003בלילה. \u0004 עיין מ\"א שהעל' דבלילה עכ\"פ לא יאכל בשר ומ\"ש ונראה לי דוקא בלילה וכו' קאי אמגילה ע\"ש:","\u0003קודם. \u0004 עמ\"ש סי' תרפ\"ז ס\"ק ד' דיש חולקין וכן נוהגין לקוברו אחר יציאת בה\"כ. ומ\"מ נ\"ל דלא יניח תפילין דאקרי פאר. מ\"א ע\"ש:","\u0003לישא. \u0004 ולפי מ\"ש ר\"ס תקמ\"ו דקי\"ל כמ\"ד אין מערבין שמחה בשמחה גם הכא אסור לעשות לכן יעשה החופה ביום י\"ג מ\"א ע\"ש ועיין בספר גופי הלכות ועמ\"ש באה\"ע סי' ס\"ב ס\"ק י':","\u0003לא תגזול. \u0004 ולפ\"ז מותר לברך על מה שחוטפין א\"ז. וכתב של\"ה לאו משנת חסידים היא ושומר נפשו ירחיק ממלבושים דכלאים ולחטוף מחבירו ועיין ט\"ז וב\"ח בי\"ד סי' קפ\"ב להחמיר בזה באורך וכן הכנה\"ג הורה לאסור הפרצופים בפורים ע\"ש ועיין בתשו' דברי שמואל סי' רמ\"ז ולכן הירא את דבר ה' ירחיק את בניו ובני ביתו מכל כי האי איסור' ופריצותא ועיין עוד בדבר שמואל סי' קנ\"ג תוכחת מגולה על הלומדים ספר מסכת שיכורים ע\"ש:"],"s":["\u0003עושין. \u0004 עבה\"ט ועיין בר\"י בשם בית דוד מי שהיה בונה ביתו קודם פורים ע\"י עכו\"ם כיון דאוושא מילתא מבטל ביום פורים עיין שם ונראה ששם במקום שנהגו שלא לעשות אף ע\"י עכו\"ם ואפשר דס\"ל דבנין בית בפרהסיא יש להחמיר טפי וצ\"ע:","\u0003בהספד. \u0004 עיין בר\"י בשם בית יהודה דה\"ה שאסור בבכיה וע\"ש שמ\"ש הנשים מענות דמ\"מ אסורים לבכות ולקונן על מת שיש כמה ימים שמת מיהו אין למחות בידם מוטב כו' ע\"ש:","\u0003אבילות. \u0004 עבה\"ט וע' בשו\"ת מוה\"ר יוסף קצבי סימן ו' שהאריך ובר\"י כת' דנקטי' כמ\"ש הב\"י ביו\"ד שלא להתאבל דהלכה כדברי המיקל באבל וכן הסכמת בעל בית דוד וכן פשט המנהג במדינות אלו וכן הורינו הלכה למעשה עיין שם ועיין ביד אפרים מ\"ש בשם התשב\"ץ:","\u0003שבצנעה. \u0004 עבה\"ט בשם הט\"ז שאין לקרות לילך נגד האבל ועיין בא\"ר דה\"ה כשחל שושן פורים בע\"ש אין לקרות ג\"כ:","\u0003בלילה. \u0004 עבה\"ט ועיין מה שכת' ביד אפרים על דברי הש\"ע והמג\"א בזה ועיין בא\"ר דמכ\"ש בליל שני דאסור:","\u0003לישא. \u0004 עבה\"ט ועיין פר\"ח שכת' גם כן שלא לישא בפורים ובבר\"י כת' בשם מופת הדור מוהר\"ר יצחק הכהן ז\"ל עם היותו תלמיד הפר\"ח הורה להתיר לישא בפורים כהוראות הש\"ע וכן פשט המנהג במדינות אלו:"],"m":["\u0003בכ\"מ\u0004. ערסי' תרס\"ח דע\"י עכו\"ם מותר ועיין סי' תקנ\"ד סכ\"ב:","\u0003אינו רואה\u0004. עיין ברמב\"ם דמשמע דאפי' במקום שנהגו לעשות, וכ\"כ הרא\"ם בשמו בביאורי סמ\"ג, אבל בב\"י משמע דדוקא במקום שנהגו שלא לעשות:","\u0003סי' ברכה\u0004. כגון אם זורע איזה דבר אינו מצמיח (ב\"י), אבל הרא\"ם כתב שאינו מרויח אבל אינו מפסיד ג\"כ ומשמע שם שגירסא אחרת הי' לו בגמ':","\u0003פסקי הלכות\u0004. ופשטי המקרא ואגרת שלום ומזכרת חובותיו וכן כל דבר שא\"צ עיון גדול (מט\"מ ב\"י א\"ח):","\u0003אסורים בהספד\u0004. ומקום שנהגו שביום ז' הולכין על הקבר לקונן אסורים בפורים אלא האבל לבדו ילך שם עם חזן א' ויאמר לו השכב' ואפי' בערב פורים אסור לילך שם שלא יחשבו העולם שאבילו' נפסק מחמת פורים (ר\"ש לוי י\"ג כ\"ה):","\u0003ומ\"מ ילך לבה\"כ\u0004. צ\"ע דהא הרב\"י פסק בס\"ה שלא יצא מפתח ביתו א\"כ ה\"ל לכתו' בל' י\"א וכו':","\u0003וי\"א שאין אבילו' וכו'\u0004. ב\"ח ורש\"ל ופרישה העידו שהמנהג להתאבל וכ\"כ מהרי\"ל ועכשיו גרירי עלמא בתר דברי רמ\"א, ונ\"ל דיזהר בכולם חוץ מנעילת הסנדל וישיבה ע\"ג קרקע מפני הבריות ומכ\"ש שאסור לראות כל מיני שמחה:","\u0003דברים שבצנעא וכו'\u0004. ויתפלל בביתו ואח\"כ ילך לבה\"כ לשמוע מגילה (טו' וכ\"מ בלבוש) מיהו משמע בטור דבשחרית הולך לבה\"כ לתפלת עבי\"ד סי' שצ\"ג:","\u0003עול' לו למנין\u0004. ואפי' מת בפורים וכמ\"ש סי' תקמ\"ח ס\"ב:","\u0003לא יצא משם\u0004. נ\"ל דבמקום הרוקח היו אוכלין סעוד' שלישית קודם מנחה אבל לדידן צריך לילך לביתו לאכול סעודה שלישית ואיתא במהרי\"ל כשהיה אבל באמצע השנה הלך במ\"ש לבה\"כ ועמד בפתח בה\"כ עד שאמר ברכו ואח\"כ חזר לביתו עכ\"ל ש\"מ שמותר לילך לבה\"כ כ\"ש בפורים די\"א דאין אבילו' נוהג כ' הלבוש א\"א צידוק הדין אלא לחכם בפניו (בניו) [אחר] שדורשין עליו אומרים קדיש:","\u0003שאבל חייב לשלוח\u0004. כתוב במהרי\"ל כל דבר שמח' לא ישלח ולא ישלחו לו וכ\"כ בס\"ח, ומט\"מ כ' שהמנהג שאין שולחין לאבל אפי' דבר שאינו עשוי לשמוח וכ\"מ מדברי רמ\"א, וז\"ל ס\"ח מי שמת אביו בפורי' לשנה הבא' ישלח מנות ובאותו שנה ישלח מעות או בשר לעניים רק לא תפנוקים העשוים לשמחה וכל דבר של שמחה לא ישלח ולא ישלחו לו עכ\"ל סי' תשי\"ג ופשוט דאם האבל הוא עני דמותר לשלוח לו מעות דלא גרע מצדק':","\u0003ביורה דעה סי' שפ\"ה ע\"ש\u0004. נ\"ל שכוונתו להורות דבמקום שאין נוהגין אבילות בפורים כמ\"ש ס\"ד א\"כ דינו כשבת ומותר לשלוח במקום שנהגו לשאול בשלומו ע\"ש:","\u0003עשה דיחיד\u0004. וי\"א דאפי' עשה דרבי' כמ\"ש סי' תקמ\"ח ס\"ג:","\u0003וכ\"ש שחייב\u0004. דברי רמ\"א צ\"ע גדול דבשלמא בבשר ויין מות' משום שמחת פורי' אבל ק\"ש ותפל' הטעם דפטו' שיהא פנוי לצורכי המת א\"כ מ\"ש פורים מימות החול ואף כי י\"ל דס\"ל דבליל' חייב בק\"ש שדינו כמו בי\"ט שני וכמ\"ש סי' תקמ\"ח ס\"ה מ\"מ קשה איך נלמד זה במכ\"ש דבשר ויין דמה ענין זה לזה וצ\"ע:","\u0003דדוקא בלילה\u0004. צ\"ע למה יהא מותר בליל' בבשר ויין והלא אין חיוב כלל לאכול בלילה כמ\"ש רסי' תרצ\"ה וא\"כ היאך כ' עשה דרבי' וכו' וע\"ק דבי\"ד סי' שמ\"א פסק דאפי' בשבת אם ירצה שלא לאכול בשר הרשות בידו וכמ\"ש תר\"י וז\"ל שאינו מחוייב שיאכל בשר ויין וכו' ומה שאסרו בחול היינו משום שאם ימשך אחר תענוגי' יתבטל מקבורת המת עכ\"ל (ועסי' תקנ\"ב ס\"י דכשנמנע משום אבילו' אסור) וא\"כ ליכא עשה כלל אפי' ביום ואפשר לו' דפורים שאני דכתיב ביה שמחה ואין שמח' אלא בבשר ומ\"מ קשה דהא י\"ט נמי שמחה כתיב ביה ואין חיוב לאכול בשר רק בזמן שב\"ה קיים עסי' תקכ\"ט לכן נ\"ל בלילה עכ\"פ לא יאכל בשר דהא בלא\"ה יש נמנעי' כמ\"ש סי' תרצ\"ה ס\"ב בהג\"ה ומ\"ש ונ\"ל דוק' בליל' קאי אמגיל':","\u0003קבור' מתו קודם\u0004. עמ\"ש סי' תרפ\"ז דיש חולקין וכן נוהגין לקברו אחר יציא' בה\"כ, וקשה דאיך חייב בקריאת מגילה כיון דפטור מכל מצות וי\"ל דטעמא דפטור משום שיהא עוסק בצרכי המת והכא אסור לקוברו עד שיקרא תחלה א\"כ חייב אפי' בתפלה וק\"ש דומיא דפסח שחייב אף על פי שהוא אונן וכמ\"ש הרא\"ש בשם הר\"מ והמרדכי דאפילו עבוד' מבטלין לשמוע קריאת מגילה בצבור כ\"ש אבילות א\"כ ה\"ה אונן ועוד דהא אין איסור באונן לילך לבה\"כ כמ\"ש בי\"ד סימן שמ\"א ומ\"מ נ\"ל דפטור מתפלה וק\"ש, וגם נ\"ל דאע\"פ ששמע המגילה בצבור יקראנה שנית אחר שנקבר המת כי תלמוד ערוך הוא דאונן פטור מכל המצות, ואף על גב דאמרינן מקרא מגילה קודם היינו באחר אבל האונן פטור עד שיקברנו מיהו לפי מ\"ש בסי' ע\"א דאם רצה להחמיר רשאי א\"כ יוצא במה ששמע בצבור דהא עיקר דמקרא מגילה קודם להמת וא\"כ חייב במקרא מגילה ונ\"ל דמ\"מ לא יניח תפילין דאקרי פאר וערסי' ע\"א:","\u0003דלא עדיף משבת וי\"ט\u0004. כלומר בי\"ט שני כשקוברו ובשבת שמחשיך על התחום פטור מכולן כ\"ש כאן ועמש\"ל:","\u0003מותר לישא\u0004. דבחג כתיב ושמחת בחגך ולא באשתך ולא בפורים ועוד דהוי ליה חד יומא ומשום חד יומא לא משהי אינש נפשיה וכמ\"ד משום ביטול פריה ורביה (ב\"י בשם הרשב\"א) לכאורה משמע דה\"פ דבשלמא ברגל גזרינן שמא ישהא עד הרגל כדי להשתכר שיצאו שבעת ימי המשתה בז' ימי החג אבל בפורים משום יום א' לא ישהא וצריך עיון דהא אמרינן בגמרא דמותר לישא ערב הרגל דמשום חד יומא לא משהי אינש נפשיה (פירש\"י ור\"ן כיון דאי משהו תו לא מצי עביד במועד) וא\"כ לא יעמיד הנשואין בערב הרגל וזה לא שייך גבי פורים ואפשר דהרשב\"א סברא דנפשיה קאמר אלא שתפס לשון הגמרא, ומ\"מ קשה מנ\"ל הא ואפשר שהוכחתו מדמותר לישא ערב עצרת ולא חיישינן שישהא הנישואין כי שם אינו חושש אם ידחה עד אחר עצרת דאינו אלא יום א' אלא ע\"כ כיון דאינו אלא יום א' לא איכפת לו בזה לשהות דהא מ\"מ יצטרך לעשות שבעת ימי המשתה: וכתב הלבוש לפי מה שכתבתי סימן תרפ\"ח ס\"ו דאין לעשות סעודת פורים בשבת אם כן הכי נמי אסור לעשות סעודת נשואין בי\"ד ע\"כ ול\"נ דלא דמי דהתם הטעם דאם כן לא תהא סעודת פורים ניכרת אבל הכא מה בכך אם לא תהא סעודת הנישואין ניכרת, ועיין מה שכתבתי שם, אלא אי קשיא הא קשיא דהא קיי\"ל אין מערבין שמחה בשמחה כמו שכתבתי ריש סימן תקמ\"ו וילפינן לה מקרא א\"כ היאך מותר לערב שמחת הנשואין בשמחת פורים, ויש לומ' דמש\"ה סיים הרשב\"א ודברים אלו מדרבנן הם והולכין להקל כלומר דלמאן דאמר אין מערבין באמת אסור, אבל כיון דלאידך שרי הולכין להקל, וא\"כ לפי מה שכתבתי ריש סימן תקמ\"ו דקיימא לן כמאן דאמר אין מערבין שמחה בשמחה גם הכא אסור לכן נ\"ל שיעשה החופה ביום י\"ג כנ\"ל:"],"r":["\u0003ס\"א והעושה. \u0004פסחים נ' ב' ובכ\"מ שיש נדנוד עבירה:","\u0003ומותר לעשות כל מלאכת מצוה. \u0004בפ\"ק דשקלים בט\"ו קורין כו' ומתקנין כו' ואפי' בכרכים מפני שהוא מצוה כמש\"ש בגמרא ומכין שאם לא כו':","\u0003כגון לכתוב. \u0004מתניתין י\"ז א' היה כותבה. ואע\"ג דבירושלמי מוכח משם דמותר בעשיית מלאכה היינו דלא קבלו עלייהו י\"ט ממש אבל משום המנהג מותר כמ\"ש בגמ' ה' ב' ואב\"א לעולם נהוג ורבי נטיעה כו' משמע אבל אי הוי י\"ט אף של שמחה אסור:","\u0003וכן מותר. \u0004כנ\"ל נטיעה של שמחה וכן פסקי הלכות מטעם זה פקודי כו':","\u0003ס\"ד כל. \u0004שלא אמרו בפ\"ג דמ\"ק אלא שבת ורגלים ומדמי למענות ומטפחות:","\u0003ומ\"מ. \u0004חולק על ש\"ע בסעיף ה'. וטעמו מדאמרינן שם ג' שמבטלין עבודה שהיא דאורייתא כ\"ש אבילות ידרבנן שהיא דוחה ואע\"ג דבסי' תרפ\"ז ס\"ב כת' דוקא להקדים אבל לדחות לא הא כת' שם מצוה דאורייתא:","\u0003מניין כו'. \u0004כיון שיכול לקיים שתיהן וכמ\"ש בפ\"ג דמ\"ק שבת ראשון כו':","\u0003וי\"א שאין. \u0004שנאמר בהן משתה ושמחה ואמרו ה' ב' ימי הפורים כו' לא נצרכה אלא לאסור בהספד ומדמי למקוננות. וז\"ש שם ג' ב' ודיחיד קל כו' כ\"ש כו'. ולכאורה אינו מובן וע' תוס' שם ד\"ה כ\"ש כו' שדחקו בזה ודבריהם דחוקים דלא הוזכר כלל מגילה שם וגם לא שייך כ\"ש דאין ענין לו ועוד הא קאמר חנוכה אלא כפשטיה לענין הספד קאמר שאע\"פ שכ' בו משתה ושמחה ופריך דכי היכי דמבטלין עשיה מפני ת\"ת ה\"נ לזכירה דהא איתקש להדדי ועיקרו עשיה וכמש\"ש ב' ב' ובפסוק הזה של משפחה ומשפחה נזכרים ונעשים כתי' וכמו שמבטלים לזכירה ה\"ה לעשייה וכמש\"ש ז' ב' נגה ולא אתו רבנן כו' אלא דלא שייך לומר שמבטלין עבודה דכל היום זמנה של עשייה משא\"כ בקריאה דזריזין כו' אלמא דלא אידחי משתה ושמחה של פורים אלא מפני ת\"ח בפניו וכמש\"ש כבוד תורה מפני כבוד תורה לבד:","\u0003ואפי'. \u0004כדעת תוס' שאף יום ראשון הוא מדרבנן שלא אמרו אנינות יום א' דאורייתא אלא בקדשים ומעשר והביאו ראיה מפ\"ק דכתובות ד' א' שדוחין האבלוית מפני החופה ובבכורות מ\"ט ולענין כו' דקי\"ל הלכה כו' ואפי' יום ראשון וע\"ל סי' תקמ\"ח ס\"ג וי\"ד סי' שצ\"ט סי\"ג:","\u0003אבל דברים. \u0004שאף בי\"ט נוהג כמ\"ש בפ\"ק דכתובות:","\u0003ואע\"פ כו'. \u0004כמ\"ש בפ\"ג דמ\"ק ולכן לא חשיב עם רגלים:","\u0003ס\"ה אם חל. \u0004כנ\"ל:","\u0003ס\"ו יש מי. \u0004כמ\"ש בפ\"ב דסוכה אבל חייב בכל מצות האמורות בתורה:","\u0003אבל אין. \u0004מדין שאילת שלום שאסור עד י\"ב חדש כמ\"ש בפ\"ג דמ\"ק:","\u0003אא\"כ מחל. \u0004דאין נותנין לאדם בע\"כ. שם:","\u0003ס\"ז דלא אתי עשה כו'. \u0004ריש פ\"ג דמ\"ק ומ\"ש בס\"ה ולמחרת כו' היינו שיקרא בביתו:","\u0003וכ\"ש' כו'. \u0004ונ\"ל דדוקא כו' ולכן. עמ\"א וצ\"ע:","\u0003מותר לישא. \u0004שלא אמרו אלא מועד ויליף שם מקרא ושמחת בחגך כו' ואף למ\"ד שאין מערבין ל\"פ עליו לדינא. ד\"מ:","\u0003וכ\"ש שמותר. \u0004דאף במועד מותר כמ\"ש תוס' שם ד\"ה מפני ביטול דקי\"ל כרב אשי דדריש בפ\"ק דחגיגה בחגך ולא באשתך כו' ועי\"ל דלא חשיבי שמחה כי אם סעודת נישואין לבד:","\u0003מה שנהגו כו' וכן. \u0004כמ\"ש בפרק הגוזל בתרא דמותר ללבוש כלאים להעביר כו' כיון שאין מתכוין להנא' לבישה וכ\"ש למפרשים שם כדי להתנכר שיסברו שהוא נכרי ולמדו מדברי תוס' דסוכה הנ\"ל וז\"ש וכן ב\"א כו':","\u0003וי\"א דאסור. \u0004שכת' דבשלמא ממון אתיהיב למחילה משא\"כ איסורא וגם בלבישה להעביר כו' הרמב\"ם וש\"ע י\"ד סי' ש\"א ס\"ה אוסר וע\"ש ושם ס\"ו בהג\"ה:"]}],["\u0010y0\u0011 יוֹם י\"ד וְט\"ו שֶׁבַּאֲדָר רִאשׁוֹן אֵין נוֹפְלִים עַל פְּנֵיהֶם, וְאֵין אוֹמְרִים מִזְמוֹר \u0010y1\u0011 יַעַנְךָ ה' בְּיוֹם צָרָה, וַאֲסוּרִים בְּהֶסְפֵּד \u0010y2\u0011 וְתַעֲנִית; אֲבָל שְׁאָר דְּבָרִים אֵין נוֹהֲגִים בָּהֶם; וְיֵשׁ אוֹמְרִים דְּאַף בְּהֶסְפֵּד וְתַעֲנִית מֻתָּרִים. \u0005 הַגָּה: וְהַמִּנְהָג כַּסְּבָרָא הָרִאשׁוֹנָה. יֵשׁ אוֹמְרִים שֶׁחַיָּב לְהַרְבּוֹת בְּמִשְׁתֶּה וְשִׂמְחָה \u0010y3\u0011 \u0006 \u0005 בְּ\"ד שֶׁבַּאֲדָר רִאשׁוֹן \u0006 \u0005(טוּר בְּשֵׁם הָרִי\"ף)\u0006 \u0005 וְאֵין נוֹהֲגִין כֵּן, \u0010y4\u0011 מִכָּל מָקוֹם יַרְבֶּה קְצָת בִּסְעֻדָּה כְּדֵי לָצֵאת יְדֵי הַמַּחְמִירִים; \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי בְּשֵׁם סְמַ\"ק)\u0006 \u0005 וְטוֹב לֵב מִשְׁתֶּה \u0006 \u0005 תָּמִיד \u0006 \u0005(מִשְׁלֵי ט\"ו, ט\"ו)\u0006.",["\u0003ראשון\u0004 ולכו\"ע אין אומרים על הניסים כיון דאין קורין המגילה ואם אמרו אין מחזירין אותו:","\u0003יענך\u0004 ואין אומרים אא\"א בפורים קטן ב' הימים דלמנצח יענך ואא\"א שווים המה. ומזמור לאסף בפורים קטן מקומות יש בלבוב שא\"א אותו בכל יום שא\"א תחנון ויש מקומות שאומרים רק ביום הלל א\"א מזמור לאסף וכן נוהגים בפפד\"א אם חל פורים קטן בשבת א\"א צו\"צ מי שאירע לו נס באדר וקבל ע\"ע לעשות תמיד יום משתה ושמחה אם אירע בשנה פשוטה עושה בראשון ואם אירע במעוברת בשני יעשה בשני. ואותה סעודה שעושין בשביל הנס היא סעודת מצוה דכל סעודה שעושין לזכר נפלאות ד' הוא סעודת מצוה:","\u0003ותענית\u0004 אבל אבילות לכו\"ע נוהג באדר ראשון. אם נדר בפירוש להתענות בפורים קטן י\"ל דחל הנדר דהוי רק מנהג בעלמא אבל אם נדר בסתם ב' וה' של כל השנה י\"ל דדעתו היה לבד פורים קטן:","\u0003בי\"ד\u0004 אבל לא בט\"ו אף לכרכים המוקפין חומה:","\u0003מ\"מ ירבה וכו'\u0004 בהגהת תשב\"ץ כתב דיש להרבות ורבינו יחיאל מפריש רגיל להרבות ולהזמין ב\"א וזהו שסיים הרמ\"א וטוב לב משתה תמיד היינו שטוב להרבות לכבוד הנס שנעשה בעתים הללו:"],[],"\u0010y0\u0011 \u0010g0\u0011 יוֹם י\"ד וְט\"ו שֶׁבַּאֲדָר רִאשׁוֹן אֵין נוֹפְלִים עַל פְּנֵיהֶם, וְאֵין אוֹמְרִים מִזְמוֹר \u0010y1\u0011 יַעַנְךָ ה' בְּיוֹם צָרָה, \u0010g1\u0011 וַאֲסוּרִים בְּהֶסְפֵּד \u0010y2\u0011 \u0010t0\u0011 \u0010s0\u0011 וְתַעֲנִית; אֲבָל שְׁאָר דְּבָרִים אֵין נוֹהֲגִים בָּהֶם; \u0010g2\u0011 וְיֵשׁ אוֹמְרִים דְּאַף בְּהֶסְפֵּד וְתַעֲנִית מֻתָּרִים. \u0005 הַגָּה: וְהַמִּנְהָג כַּסְּבָרָא הָרִאשׁוֹנָה. יֵשׁ אוֹמְרִים שֶׁחַיָּב לְהַרְבּוֹת בְּמִשְׁתֶּה וְשִׂמְחָה \u0010y3\u0011 \u0010t1\u0011 \u0010s1\u0011 \u0010m0\u0011 \u0006 \u0005 בְּ\"ד שֶׁבַּאֲדָר רִאשׁוֹן \u0006 \u0005(טוּר בְּשֵׁם הָרִי\"ף)\u0006 \u0005 וְאֵין נוֹהֲגִין כֵּן, \u0010y4\u0011 מִכָּל מָקוֹם יַרְבֶּה קְצָת בִּסְעֻדָּה כְּדֵי לָצֵאת יְדֵי הַמַּחְמִירִים; \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי בְּשֵׁם סְמַ\"ק)\u0006 \u0010m1\u0011 \u0005 וְטוֹב לֵב מִשְׁתֶּה \u0010t2\u0011 \u0006 \u0005 תָּמִיד \u0006 \u0005(מִשְׁלֵי ט\"ו, ט\"ו)\u0006. \u0010r0\u0011 \u0010r1\u0011 \u0010r2\u0011 \u0010r3\u0011",{"g":["ב\"י ע\"פ המנהג","\u0003טור בשם הסמ\"ג והרמב\"ם בפ\"ב מה' מגילה וכן דעת הר\"ן ממשנה דאין בין אדר ראשון וכו'\u0004 מגילה ו' כתירוצא בתרא בגמרא דמתני' חסורי מחסרא וכו' וכ\"כ הרי\"ף שם","\u0003שם בשם אביו הרא\"ש והגמ\"יי והמרדכי בשם הר\"ם:\u0004 נשלם טור א\"ח וה' מגילה. שבח והודאה לנורא עלילה. והוא יזכני לגמור את כולה. ויצילני מכל מכשול ותקלה. ברוך ה' לעולם אמן ואמן:"],"t":["\u0003ותענית. \u0004 ואבילות נוהג לכ\"ע:","\u0003בי\"ד. \u0004 אבל לא בט\"ו. ב\"י:","\u0003תמיד. \u0004 בית תפארתינו במהרה יעמוד. וביראה אותו נעבוד. נכון יהיה הר הבית בראש הרים עדי עד:"],"s":["\u0003ותענית. \u0004 עבה\"ט ועיין מג\"א דלכ\"ע אין אומרים עה\"נ ועיין בעטרת זקנים שאין נוהגים איסור בעשיית מלאכה באדר ראשון ועיין פר\"ח אם טעו וחשבו שהוא שנה פשוטה וקראו המגילה והפרשיות בראשון ואחר כך נודע להם שהיא מעוברת צריכים לחזור ולקרות הפרשיות והמגילה באדר השני ועיין בב\"י סימן תרפ\"ח ובסוף ספר בדק הבית ע\"ש ועיין מ\"ש מהר\"ש הלוי בתשובה במי שנעשה לו נס באדר כו' ומ\"ש ע\"ז בבר\"י ועיין במג\"א לעיל סי' תקס\"ח ס\"ק ך' האריך בדיני אדר שני לענין יא\"צ ושם הביא מאה\"ע סי' קכ\"ו ומי\"ד סימן ר\"ך ומשם יש ללמוד כמה הילכתא גבורתא בענין זה:","\u0003בי\"ד. \u0004 עבה\"ט ועבט\"ז שהביא בשם הגהות תשב\"ץ שרבינו יחיאל מפאריז רגיל להרבות בסעודה ולהזמין בני אדם כמשמעות לשון המשנה אין בין אדר כו' ושפי' מסיים רמ\"א וטוב לב משתה תמיד ועיין בר\"י שכת' מור\"מ ז\"ל בחכמה יסד חתימה מעין פתיחה שני תמידין כסדרן הוא פתח בריש הגהותיו שויתי ה' לנגדי תמיד וחתם וטוב לב משתה תמיד כו' ע\"ש. נ\"ל שלפי שרצה לסיים בדבר טוב ודבר בעתו נקט לישנא מעליא דקרא לצחות וטוב לב דהיינו שטוב שיעשה בב' האדרים משתה אפשר שזה כוונת הט\"ז מה שכת' ושפיר מסיים הרמ\"א כו' וכוונתו כמ\"ש וגם יש רמז כי תיבת משתה טוב בגי' אדר ראשון עוד אפשר לומר לפי מש\"ל סימן תר\"ע בהג\"ה ס\"ב לענין חנוכה שי\"א שיש קצת מצוה ברבוי הסעודות כו' ונוהגין לומר זמירות ותשבחות בסעודת שמרבים בהם ואז הוי סעודת מצוה ע\"ש ומשם נלמד לכאן ג\"כ כשירבה קצת בסעודה לצאת ידי המחמירים יש לנהוג לומר זמירות ותשבחות שאז בודאי הוא סעודת מצוה ולרמוז לזה מסיים וטוב לב משתה תמיד והוא עפ\"י מה דאמרינן בערכין דף י\"א מנין לעיקר שירה מה\"ת כו' איזה עבודה שהוא בשמחה ובטוב לבב הוי אומר זה שירה וע\"ש ברש\"י דמייתי מישעיה ס\"ה הנה עבדי ירונו מטוב לב וע\"ש בתוס' דאשכחן נמי גבי ד\"ת שכת' רש\"י ברות שיש במדרש וייטב לבו בד\"ת וכן בשבת דף ס\"ג ויטיבך לבך על תלמוד תורה אלא דלא כתיבא בהדיא ע\"ש ולזה אמר וטוב לב משתה תמיד כלו' שבטוב לב דהיינו שירות ותשבחות וד\"ת משתה תמיד ולפי מ\"ש במקום אחר על מ\"ש ויחן ישראל נגד ההר דהיינו שנסתלק היצה\"ר מהם ולכן פי' רש\"י ויחן כאיש אחד בלב א' לפי מה דאמרינן בכל לבבך בשני יצריך וכאן שנסתלק היצר הרע לא היה להם רק לב א' ובקרא דכתיב בשמחה ובטוב לבב וסמך טוב ללבב מסתבר טפי למדרשיה דקאי על שירה שאין היצר הרע מסתלק בשירה לבד כ\"א ע\"י ד\"ת שהוא תבלין שלו ואז עדיין יש כאן שני לבבות משא\"כ התם דכתיב ויטב לבו שפיר דריש ליה על תלמוד תורה דבעידנא דעסיק בה מגינא ומצלא וכן אמרו שלשה שאכלו על שולחן א' ואמרו עליו דברי תורה כו' ועיין מ\"ש בהקדמה שו\"ת בית אפרים חלק א\"ח במ\"פ וילכו לאהליהם שמחים וטובי לב כו' וזהו שאנו אומרים והאר עינינו בתורתך י\"ל שהכוונה ע\"י תורתך כמ\"ש חז\"ל המאור שבה מחזיר למוטב ואז ודבק לבנו במצותך ויחד לבבינו כו' ששני הלבבות יתיחדו להיות אחד לאהבה כו' וזה הגורם שידבק הלב במצות אחרי שאין שם יצר סמוך ויותר יש לזרז עצמו בד\"ת במקום שיש שם איזה שמחה אף אם היא שמחה של מצוה ועיין בסוף סוכה בענין שמחת בית השואבה וכן מבואר לעיל סימן תקכ\"ט אדם אוכל ושותה ושמח ברגל ולא ימשוך בבשר ויין ובשחוק וקלות ראש לפי שאין השחוק וקלות ראש שמחה אלא הוללות וסכלות ולא נצטוינו על הוללות וסכלות אלא על שמחה שיש בה עבודת היוצר עכ\"ל והוא לשון רבינו הרמב\"ם ז\"ל והמפרשים ז\"ל פירשו לשחוק אמרתי מהולל ר\"ל שיהיה באיזה ענין שיהיה השחוק הוא הוללות עבט\"ז לעיל אך לשמחה מה זו עושה ר\"ל שלענין שמחה אין להחליט שאינה יפה שבאמ' יש שמחה של מצוה ולכן יש ליתן לב לדעת מה זו עושה ר\"ל מה טובה אם הוא שמחה של מצוה או לא אך הואיל ואפשר כי מתוך אכילה ושתיה והוללת יתמשך לשחוק וקלות ראש לכן יקח תבלין לבסם השמחה בד\"ת וחדוות ה' יהיה מעוזו ויטב לבו בד\"ת וז\"ש וטוב לב משתה תמיד ויה\"ר שיהיה לנו לב אחד לאבינו שבשמים ונשא לבבנו אל כפים אל הפותח יד בתשוב' יהיו אמרינו לרצון לפני אדירי כל חפצם לשקוד על דלתות התורה והמצוה ליישר מסילה באורח חיים. ואשר יספוק עלימו בדינים או חתום באפוקי מגינים בשערי תשובה ויד אפרים יאיר עינים ויקרא שם המקום מחנים:\nוה' ישיב שבותינו בישיבת ציון וירושלים והיו לאחדים עץ יהודה את עץ יוסף אשר (ביד אפרים):"],"m":["\u0003בי\"ד שבאדר ראשון\u0004. ולכולי עלמא אין אומרים על הניסים כיון דאין קורין המגילה דהא י\"א אף בתפלת ערבית דפורים אין אומרים אותו ואף דלא קיי\"לן כן מ\"מ כאן כולי עלמא מודים דאין אומרים אותו:","\u0003וטוב לב משתה תמיד\u0004. בשמחות מצות אלקינו להעמיד אז ימלא שחוק פינו, במהרה בימינו אמן:"],"r":["\u0003ס\"א יום י\"ד וט\"ו כו'. \u0004כמש\"ש ו' ב' הא לענין הספד ותענית כו':","\u0003אבל שאר. \u0004כמ\"ש תוס' שם ד\"ה ור\"א מדקאמר לענין הספד ותענית משמע דשאר דברים כגון משתה ושמחה לא דאל\"כ הל\"ל משתה ושמחה וממילא ש\"מ הא:","\u0003וי\"א. \u0004שפי' מ\"ש הא לענין כו' קאי ארישא קראו את כו' נתערבה כו' דאל\"כ היאך ס\"ד דהפרשיות יהיו נוהגים בב' אדרים לעולם וכ\"ה בירושלמי שם מתניתין בשעבר וואח\"כ קראו אבל אם קראו ואח\"כ עברו לא הדא מתני' לא אמרה כן אלא קראו את המגילה באדר ראשון ונתעברה השנה קורין אותה באדר שני אלמא דבכה\"ג דוקא מיירי שקראו ואח\"כ עברו בו ביום. אבל הר\"ן שם מפרש דה\"ק דאף בכה\"ג מיירי וכלישנא דירושלמי:","\u0003י\"א שחייב. \u0004שמפרש לענין הספד ותענית היינו משתה ושמחה דתליא זה בזה כמש\"ש ה' ב' משתה מלמד כו' שמחה כו':"]}]]};
